function dispatchAniClientEvent(eventName, detail = {}) {
  if (typeof window === "undefined" || typeof window.dispatchEvent !== "function") return false;
  const EventConstructor = typeof window.CustomEvent === "function" ? window.CustomEvent : null;
  if (!EventConstructor) return false;
  window.dispatchEvent(new EventConstructor(eventName, { detail }));
  return true;
}

if (settingsPanel && settingsPanel.parentElement !== document.body) {
  document.body.append(settingsPanel);
}

function isCapacitorNativeApp() {
  const capacitor = window.Capacitor;
  if (!capacitor) {
    return false;
  }
  if (typeof capacitor.isNativePlatform === "function") {
    return capacitor.isNativePlatform();
  }
  if (typeof capacitor.getPlatform === "function") {
    return capacitor.getPlatform() !== "web";
  }
  return Boolean(capacitor.Plugins);
}

function getNativeSpeechPlugin() {
  return window.Capacitor?.Plugins?.AniSpeech || null;
}

function parseNativeSpeechResult(result) {
  if (!result) {
    return {};
  }
  if (typeof result === "string") {
    try {
      return JSON.parse(result);
    } catch {
      return { status: result };
    }
  }
  return result;
}

function getAndroidNativeBridge() {
  return window.AniNativeSpeech || null;
}

function getNativeFileBridge() {
  const bridge = getAndroidNativeBridge();
  return bridge?.saveBase64File ? bridge : null;
}

function blobToBase64Payload(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => {
      const value = String(reader.result || "");
      resolve(value.includes(",") ? value.split(",").pop() : value);
    };
    reader.onerror = () => reject(reader.error || new Error("ANI could not prepare the file for export."));
    reader.readAsDataURL(blob);
  });
}

async function saveBlobWithNativeBridge(blob, filename) {
  const bridge = getNativeFileBridge();
  if (!isNativeShell || !bridge) {
    return false;
  }
  const payload = await blobToBase64Payload(blob);
  const result = parseNativeSpeechResult(bridge.saveBase64File(
    filename,
    blob?.type || "application/octet-stream",
    payload
  ));
  if (result?.status === "error") {
    throw new Error(result.error || "ANI could not save that file on this device.");
  }
  return Boolean(result?.status);
}

function getAndroidSpeechBridge() {
  const bridge = getAndroidNativeBridge();
  if (!bridge?.speak) {
    return null;
  }
  return {
    speak: async ({ text, rate, pitch }) => parseNativeSpeechResult(bridge.speak(text, String(rate), String(pitch))),
    stop: async () => parseNativeSpeechResult(bridge.stop?.() || ""),
    isAvailable: async () => parseNativeSpeechResult(bridge.isAvailable?.() || "")
  };
}

function getNativeSpeechController() {
  return getAndroidSpeechBridge() || getNativeSpeechPlugin();
}

function getNativeSpeechRecognizer() {
  const plugin = getNativeSpeechPlugin();
  return plugin?.recognize ? plugin : null;
}

function canUseNativeSpeechRecognition() {
  return isNativeShell && Boolean(getNativeSpeechRecognizer());
}

function stopNativeSpeech() {
  const nativeSpeech = getNativeSpeechController();
  if (!nativeSpeech?.stop) {
    return;
  }
  try {
    const result = nativeSpeech.stop();
    if (result?.catch) {
      result.catch(() => {});
    }
  } catch {
    // Native speech is best-effort; browser speech cancellation still runs below.
  }
}

function stopAniSpeech(status = "") {
  motionGeneration += 1;
  speechQueue = [];
  stopNativeSpeech();
  if ("speechSynthesis" in window) {
    window.speechSynthesis.cancel();
  }
  stopAvaMotion();
  if (status && voiceStatus) {
    voiceStatus.textContent = status;
  }
}

