function stripPharmCombinationRouteFormWords(value = "") {
  const parts = normalizePharmText(value).split(" ").filter(Boolean);
  while (parts.length > 1 && PHARM_COMBINATION_ROUTE_FORM_WORDS.has(parts[parts.length - 1])) {
    parts.pop();
  }
  return parts.join(" ");
}

function isStudentFacingCombinationMedicationName(value = "") {
  const raw = String(value || "").toLowerCase();
  const key = normalizePharmText(value);
  if (!key || PHARM_SINGLE_INGREDIENT_SAFE_TERMS.has(key)) return false;
  if (PHARM_PROTECTED_COMBINATION_CARD_TERMS.has(key)) return false;
  if (PHARM_KNOWN_COMBINATION_TERMS.has(key) || PHARM_KNOWN_COMBINATION_BRAND_TERMS.has(key)) return true;
  const routeStrippedKey = stripPharmCombinationRouteFormWords(key);
  if (
    routeStrippedKey
    && routeStrippedKey !== key
    && PHARM_KNOWN_COMBINATION_TERMS.has(routeStrippedKey)
  ) {
    return true;
  }
  if (/[+/]|(?:\s-\s)|(?:\s\/\s)/.test(raw)) return true;
  if (/\b(?:and|with|plus)\b/.test(key)) return true;
  return false;
}

function isStudentFacingCombinationMedicationEntry(drug = {}) {
  // Integrated clinical-guide titles can legitimately contain words such as
  // "and" (for example, "Mercury poisoning and chelation decision
  // pathway"). They are single teaching pathways, not hidden combination
  // products, so keep them in the searchable encyclopedia.
  if (drug.studentFacingCombinationCard || drug.curatedStandaloneCard === true || normalizePharmText(drug.entryType) === "clinical guide") return false;
  if (isMedicationClassCardEntry(drug)) return false;
  const key = normalizePharmText(drug.generic || drug.name || drug.displayName || "");
  if (!key) return false;
  if (PHARM_PROTECTED_COMBINATION_CARD_TERMS.has(key)) return false;
  if (drug.combinationProduct) {
    return !PHARM_SINGLE_INGREDIENT_SAFE_TERMS.has(key);
  }
  return isStudentFacingCombinationMedicationName(key);
}

function sanitizeMedicationAliasesForSingleDrug(drug = {}) {
  return sanitizeMedicationTermListForSingleDrug(drug, drug.aliases || []);
}

function medicationTermIsKnownComboPartnerForPrimary(primaryKey = "", termKey = "") {
  if (!primaryKey || !termKey || primaryKey === termKey) return false;
  let result = false;
  const inspectComponents = (components = []) => {
    if (components.includes(primaryKey) && components.includes(termKey)) {
      result = true;
    }
  };
  PHARM_KNOWN_COMBINATION_COMPONENTS.forEach(inspectComponents);
  PHARM_KNOWN_COMBINATION_BRAND_COMPONENTS.forEach(inspectComponents);
  return result;
}

const PHARM_BROAD_MISLEADING_ALIAS_TERMS = new Set([
  "calcium",
  "magnesium",
  "potassium",
  "sodium",
  "iron",
  "zinc",
  "vitamin",
  "mineral",
  "electrolyte"
]);

function isAllowedStandaloneMedicationSearchTerm(drug = {}, value = "", options = {}) {
  const key = normalizePharmText(value);
  if (!key || PHARM_PLACEHOLDER_ENTRY_NAMES.has(key)) return false;
  const primary = normalizePharmText(drug.generic || drug.name || drug.displayName || "");
  if (primary && key === primary) {
    return options.allowPrimary !== false;
  }
  // frontier-wave8-curated-combination-identities
  if (drug.studentFacingCombinationCard || drug.curatedStandaloneCard === true || normalizePharmText(drug.entryType) === "clinical guide") {
    const curatedIdentities = [
      ...(Array.isArray(drug.aliases) ? drug.aliases : []),
      ...(Array.isArray(drug.brandExamples) ? drug.brandExamples : [])
    ].map((term) => normalizePharmText(term)).filter(Boolean);
    if (curatedIdentities.includes(key)) return true;
  }
  if (isStudentFacingCombinationMedicationName(key)) return false;
  if (medicationTermIsKnownComboPartnerForPrimary(primary, key)) return false;
  if (PHARM_BROAD_MISLEADING_ALIAS_TERMS.has(key)) return false;
  return true;
}

function sanitizeMedicationTermListForSingleDrug(drug = {}, values = []) {
  if (!Array.isArray(values)) return [];
  const seen = new Set();
  return values.filter((value) => {
    const key = normalizePharmText(value);
    if (!isAllowedStandaloneMedicationSearchTerm(drug, key, { allowPrimary: false })) return false;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function createSingleIngredientPatch(name, patch = {}) {
  const generic = normalizePharmText(patch.generic || name);
  return {
    name,
    displayName: name,
    generic,
    brandExamples: [],
    aliases: [],
    boxedWarning: "No drug-specific boxed warning is listed in this nursing reference. Verify current medication labeling before clinical use.",
    boxedWarningSpecificity: "single-ingredient reference",
    populationRisks: [],
    expandedIndex: true,
    combinationProduct: false,
    confidenceTier: "Curated NCLEX support",
    nclexEssential: true,
    sourceNote: "Verify current medication labeling before clinical use.",
    ...patch,
    generic,
    name,
    displayName: name,
    aliases: Array.isArray(patch.aliases) ? patch.aliases : []
  };
}

function titleCaseMedicationComponent(componentKey = "") {
  return String(componentKey || "")
    .split(/\s+/)
    .filter(Boolean)
    .map((word) => {
      if (/^(iv|im|po|ecg|inr|npo|pca|tca)$/i.test(word)) return word.toUpperCase();
      return word.charAt(0).toUpperCase() + word.slice(1);
    })
    .join(" ");
}

function createCombinationComponentFallbackPatch(componentKey = "") {
  const generic = normalizePharmText(componentKey);
  const name = titleCaseMedicationComponent(generic);
  return createSingleIngredientPatch(name, {
    generic,
    class: "Single-ingredient medication reference",
    usedToTreat: `${name} appears as an ingredient in at least one combination product in the expanded medication index. Use the single-ingredient entry for class matching, interaction checks, contraindication screening, and nursing safety review.`,
    mechanism: "Mechanism depends on the ingredient's drug class. Verify the medication class and current labeling before clinical use.",
    nursingEssentials: [
      "Use the individual generic medication name when studying pharmacology. Combination products can hide which ingredient creates the key nursing concern.",
      "Check indication, allergies, contraindications, pregnancy status, renal/hepatic function, and major interactions before giving."
    ],
    contraindications: [
      "Clarify any drug-specific contraindication, serious hypersensitivity, pregnancy risk, organ impairment, or high-risk interaction before administration."
    ],
    interactions: [
      "Review current medication list for class-specific interactions and duplicate therapy."
    ],
    keyLabs: [
      "Monitoring depends on the drug class and client risk factors."
    ],
    nclexTraps: [
      "Do not study the combination product as one blended drug. Split it into each generic ingredient and identify which ingredient causes each safety issue."
    ],
    confidenceTier: "Component split support",
    expandedIndex: true,
    nclexEssential: false,
    combinationComponentOnly: true,
    sourceNote: "Combination products are studied by separating each generic ingredient."
  });
}

