function cleanMedicationDisplayName(value = "", fallback = "Medication") {
  const cleaned = safeText(value)
    .replace(/\s+\b(?:drug|medication|medicine|system|product|preparation)\b\s*$/i, "")
    .replace(/\s+/g, " ")
    .trim();
  return cleaned || fallback;
}

function pharmDrugDisplayName(drug = {}, fallback = "Medication") {
  return cleanMedicationDisplayName(drug.name || drug.generic || drug.displayName, fallback);
}

