const pharmCombinationSafeTerms = PHARM_SINGLE_INGREDIENT_SAFE_TERMS;
const pharmCombinationIgnoredWords = PHARM_COMBINATION_IGNORED_WORDS;

function pharmEntryNameKey(drug = {}) {
  return normalizePharmText(drug.generic || pharmDrugDisplayName(drug, "") || drug.name || "");
}

function hasNclexEssentialPharmOverride(drug = {}) {
  const terms = pharmIdentityTermsForEntry(drug)
    .map((term) => normalizePharmText(applyMedicationSpellingFixups(term)))
    .filter(Boolean);
  return terms.some((term) => NCLEX_ESSENTIAL_PHARM_OVERRIDES.has(term));
}

function isLikelyCombinationDrugEntry(drug = {}) {
  if (drug.studentFacingCombinationCard || normalizePharmText(drug.entryType) === "clinical guide") return false;
  if (pharmCombinationEntryCache.has(drug)) {
    return pharmCombinationEntryCache.get(drug);
  }
  let result = false;
  if (drug.combinationProduct) {
    result = true;
  } else {
    const key = pharmEntryNameKey(drug);
    if (!key || pharmCombinationSafeTerms.has(key)) {
      result = false;
    } else if (/\b(and|with|plus)\b/.test(key)) {
      result = true;
    } else {
      const medicationWords = key
        .split(" ")
        .filter((word) => word.length > 3 && !pharmCombinationIgnoredWords.has(word));
      result = medicationWords.length >= 2;
    }
  }
  pharmCombinationEntryCache.set(drug, result);
  return result;
}

function isNclexCorePharmEntry(drug = {}) {
  if (!drug || typeof drug !== "object") {
    return false;
  }
  if (drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only") {
    return false;
  }
  if (pharmNclexCoreEntryCache.has(drug)) {
    return pharmNclexCoreEntryCache.get(drug);
  }
  let result = false;
  if (isLikelyCombinationDrugEntry(drug)) {
    result = false;
  } else if (drug.nclexEssential || hasNclexEssentialPharmOverride(drug)) {
    result = true;
  } else if (drug.expandedIndex) {
    result = false;
  } else {
    const text = [
      drug.name,
      drug.generic,
      drug.class,
      drug.boxedWarning,
      ...(drug.tags || []),
      ...(drug.nclexTraps || []),
      ...(drug.nursingEssentials || [])
    ].join(" ");
    result = /\b(nclex|antidote|high-alert|black box|boxed|insulin|anticoagulant|opioid|antibiotic|antipsychotic|ssri|ace inhibitor|arb|beta blocker|diuretic|seizure|preeclampsia|magnesium|digoxin|lithium|heparin|warfarin|thrombolytic|potassium|pregnancy|respiratory depression|toxicity|hold|priority|safety)\b/i.test(text);
  }
  pharmNclexCoreEntryCache.set(drug, result);
  return result;
}

function pharmStudyTier(drug = {}) {
  if (drug.nclexEssential || isNclexCorePharmEntry(drug)) {
    return "NCLEX ESSENTIAL";
  }
  return "Medication reference";
}

let pharmCrashCourseOpenersHydrated = false;
