function setLectureModeActive(active = false) {
  lectureModePrimed = Boolean(active);
  if (!lectureModePrimed) {
    lectureState.active = false;
    lectureState.awaitingChoice = false;
    lectureState.parkedTopic = "";
  }
  document.body.classList.toggle("lecture-mode-active", lectureModePrimed);
  document.documentElement.classList.toggle("lecture-mode-active", lectureModePrimed);
  if (lectureModeButton) {
    lectureModeButton.textContent = lectureModePrimed ? "Exit lecture mode" : "Lecture mode";
    lectureModeButton.classList.toggle("active", lectureModePrimed);
    lectureModeButton.setAttribute("aria-pressed", String(lectureModePrimed));
  }
  if (messageInput) {
    messageInput.placeholder = lectureModePrimed
      ? "Lecture mode: type any disease, med, lab, protocol, or concept..."
      : "Ask ANI anything clinical...";
  }
  if (voiceStatus) {
    voiceStatus.textContent = lectureModePrimed
      ? "Lecture mode ready. Type a concept and press Send."
      : "Lecture mode off. Ask ANI anything clinical.";
  }
}

function normalizeApiBaseUrl(value = "") {
  return String(value || "").trim().replace(/\/$/, "");
}

function fileLaunchApiFallbacks() {
  if (location.protocol !== "file:") {
    return [];
  }
  return ["http://localhost:4179", "http://127.0.0.1:4179"];
}

function buildApiBaseCandidates() {
  const configured = [
    window.ANI_CONFIG?.apiBaseUrl,
    ...(Array.isArray(window.ANI_CONFIG?.apiBaseUrls) ? window.ANI_CONFIG.apiBaseUrls : [])
  ].map(normalizeApiBaseUrl).filter(Boolean);
  const stored = normalizeApiBaseUrl(localStorage.getItem("ani-active-api-base-url") || "");
  if (location.protocol === "file:") {
    return [...new Set([...configured, stored, ...fileLaunchApiFallbacks()])].filter(Boolean);
  }
  return [...new Set(["", ...configured, stored])];
}

function apiCredentialsFor(baseUrl = activeApiBaseUrl) {
  return baseUrl ? "include" : "same-origin";
}

function detectDeviceMode() {
  const queryMatches = window.matchMedia?.(PHONE_DEVICE_QUERY)?.matches;
  const mobileUserAgent = /Android|iPhone|iPod|IEMobile|Opera Mini/i.test(navigator.userAgent || "");
  const narrowScreen = Math.min(window.innerWidth || 0, window.screen?.width || Infinity) <= 820;
  const isPhone = Boolean(queryMatches || (mobileUserAgent && narrowScreen));
  const mode = isPhone ? "phone" : "desktop";
  document.documentElement.dataset.deviceMode = mode;
  document.body?.dataset && (document.body.dataset.deviceMode = mode);
}

detectDeviceMode();
const phoneDeviceMedia = window.matchMedia?.(PHONE_DEVICE_QUERY);
phoneDeviceMedia?.addEventListener?.("change", detectDeviceMode);
window.addEventListener("resize", detectDeviceMode);
window.screen?.orientation?.addEventListener?.("change", detectDeviceMode);

function chatBottomDistance() {
  if (!chatLog) {
    return 0;
  }
  return chatLog.scrollHeight - chatLog.scrollTop - chatLog.clientHeight;
}

function pageBottomDistance() {
  const root = document.documentElement;
  return root.scrollHeight - window.scrollY - window.innerHeight;
}

function isChatNearBottom() {
  return chatBottomDistance() <= 96;
}

function isPageNearBottom() {
  return pageBottomDistance() <= 120;
}

function updateScrollBottomButton() {
  if (!chatLog || !scrollToBottomButton) {
    return;
  }
  const canScroll = chatLog.scrollHeight > chatLog.clientHeight + 36;
  const pageCanScroll = document.documentElement.scrollHeight > window.innerHeight + 36;
  const shouldShow = (canScroll && !isChatNearBottom()) || (pageCanScroll && !isPageNearBottom());
  scrollToBottomButton.hidden = !shouldShow;
  scrollToBottomButton.classList.toggle("is-visible", shouldShow);
  scheduleScrollBottomGeometryUpdate();
}

let scrollBottomGeometryFrame = null;

function scheduleScrollBottomGeometryUpdate() {
  if (!scrollToBottomButton) return;
  if (scrollBottomGeometryFrame !== null) {
    window.cancelAnimationFrame?.(scrollBottomGeometryFrame);
  }
  scrollBottomGeometryFrame = window.requestAnimationFrame(() => {
    scrollBottomGeometryFrame = null;
    scrollToBottomButton.style.removeProperty("--ani-scroll-bottom-avoidance");
    if (scrollToBottomButton.hidden
        || !scrollToBottomButton.classList.contains("is-visible")
        || document.documentElement.dataset.deviceMode !== "phone"
        || !chatForm) {
      return;
    }
    const buttonRect = scrollToBottomButton.getBoundingClientRect();
    const composerRect = chatForm.getBoundingClientRect();
    const horizontalIntersection = buttonRect.left < composerRect.right
      && buttonRect.right > composerRect.left;
    const composerVisible = composerRect.bottom > 0
      && composerRect.top < (window.visualViewport?.height || window.innerHeight);
    if (!horizontalIntersection || !composerVisible) return;
    const minimumGap = 12;
    const raiseBy = Math.max(0, buttonRect.bottom - composerRect.top + minimumGap);
    if (raiseBy > 0) {
      scrollToBottomButton.style.setProperty("--ani-scroll-bottom-avoidance", `${Math.ceil(raiseBy)}px`);
    }
  });
}

function scrollChatToBottom(options = {}) {
  if (!chatLog) {
    return;
  }

  const behavior = options.behavior || "auto";
  if (typeof chatLog.scrollTo === "function") {
    chatLog.scrollTo({
      top: chatLog.scrollHeight,
      behavior
    });
  } else {
    chatLog.scrollTop = chatLog.scrollHeight;
  }

  if (document.documentElement.dataset.deviceMode === "phone"
    || document.documentElement.dataset.aniSurface === "website") {
    if (typeof window.scrollTo === "function") {
      window.scrollTo({
        top: document.documentElement.scrollHeight,
        behavior
      });
    }
    chatForm?.scrollIntoView?.({
      block: "end",
      behavior
    });
  }

  if (behavior === "smooth") {
    window.setTimeout(updateScrollBottomButton, 260);
    window.setTimeout(updateScrollBottomButton, 560);
  } else {
    updateScrollBottomButton();
  }
}

window.addEventListener("resize", () => {
  window.setTimeout(updateScrollBottomButton, 80);
});
window.addEventListener("scroll", updateScrollBottomButton, { passive: true });
window.visualViewport?.addEventListener?.("resize", scheduleScrollBottomGeometryUpdate, { passive: true });
window.visualViewport?.addEventListener?.("scroll", scheduleScrollBottomGeometryUpdate, { passive: true });

function apiUrl(pathname = "", baseUrl = activeApiBaseUrl) {
  if (/^https?:\/\//i.test(pathname)) {
    return pathname;
  }
  const normalized = pathname.startsWith("/") ? pathname : `/${pathname}`;
  return `${baseUrl || ""}${normalized}`;
}

function createApiIdempotencyKey() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  const bytes = new Uint8Array(16);
  globalThis.crypto?.getRandomValues?.(bytes);
  const randomPart = [...bytes].map((value) => value.toString(16).padStart(2, "0")).join("");
  return `ani-${Date.now().toString(36)}-${randomPart || Math.random().toString(36).slice(2)}`;
}

async function fetchApi(pathname = "", options = {}) {
  if (!ANI_BACKEND_SERVICES_ENABLED) {
    const error = new Error("ANI online services are disabled in the encyclopedia launch profile.");
    error.code = "ANI_FEATURE_DISABLED";
    throw error;
  }
  const candidates = [...new Set([activeApiBaseUrl, ...API_BASE_URLS])];
  let lastError = null;
  const requestHeaders = { ...(options.headers || {}) };
  if (String(options.method || "GET").toUpperCase() === "POST"
    && /^\/api\/ani\/(?:cje|advanced-item|standard-question)$/.test(pathname)
    && !requestHeaders["Idempotency-Key"] && !requestHeaders["idempotency-key"]) {
    requestHeaders["Idempotency-Key"] = createApiIdempotencyKey();
  }

  for (const baseUrl of candidates) {
    try {
      const response = await fetch(apiUrl(pathname, baseUrl), {
        ...options,
        headers: requestHeaders,
        credentials: options.credentials || apiCredentialsFor(baseUrl)
      });
      activeApiBaseUrl = baseUrl;
      if (baseUrl) {
        localStorage.setItem("ani-active-api-base-url", baseUrl);
      } else {
        localStorage.removeItem("ani-active-api-base-url");
      }
      if ((response.status === 404 || response.status === 405) && pathname.startsWith("/api/") && candidates.length > 1) {
        lastError = new Error(`ANI backend at ${baseUrl || "same origin"} did not have ${pathname}.`);
        continue;
      }
      if (currentUser && /^\/api\/ani\/(?!status\b)/i.test(pathname)) {
        window.setTimeout(() => refreshAiUsage(), 200);
        window.setTimeout(() => refreshAiUsage(), 1200);
      }
      return response;
    } catch (error) {
      lastError = error;
    }
  }

  throw lastError || new Error("ANI could not reach the app server.");
}

function xhrApi(pathname = "", options = {}) {
  if (!ANI_BACKEND_SERVICES_ENABLED) {
    const error = new Error("ANI online services are disabled in the encyclopedia launch profile.");
    error.code = "ANI_FEATURE_DISABLED";
    return Promise.reject(error);
  }
  const candidates = [...new Set([activeApiBaseUrl, ...API_BASE_URLS])];
  let candidateIndex = 0;
  let lastError = null;

  return new Promise((resolve, reject) => {
    const tryNext = () => {
      const baseUrl = candidates[candidateIndex];
      candidateIndex += 1;
      if (baseUrl === undefined) {
        reject(lastError || new Error("ANI could not reach the app server."));
        return;
      }

      const xhr = new XMLHttpRequest();
      const method = options.method || "GET";
      xhr.open(method, apiUrl(pathname, baseUrl), true);
      xhr.withCredentials = apiCredentialsFor(baseUrl) === "include";
      Object.entries(options.headers || {}).forEach(([key, value]) => {
        xhr.setRequestHeader(key, value);
      });
      xhr.onload = () => {
        activeApiBaseUrl = baseUrl;
        if (baseUrl) {
          localStorage.setItem("ani-active-api-base-url", baseUrl);
        } else {
          localStorage.removeItem("ani-active-api-base-url");
        }
        if ((xhr.status === 404 || xhr.status === 405) && pathname.startsWith("/api/") && candidateIndex < candidates.length) {
          lastError = new Error(`ANI backend at ${baseUrl || "same origin"} did not have ${pathname}.`);
          tryNext();
          return;
        }
        resolve({
          ok: xhr.status >= 200 && xhr.status < 300,
          status: xhr.status,
          json: async () => {
            if (!xhr.responseText) return {};
            try {
              return JSON.parse(xhr.responseText);
            } catch {
              return {};
            }
          }
        });
      };
      xhr.onerror = () => {
        lastError = new Error("Failed to fetch");
        tryNext();
      };
      xhr.ontimeout = () => {
        lastError = new Error("Account server request timed out");
        tryNext();
      };
      xhr.timeout = 12000;
      xhr.send(options.body || null);
    };

    tryNext();
  });
}

function activeBackendLabel() {
  if (activeApiBaseUrl) {
    return activeApiBaseUrl;
  }
  if (location.protocol === "file:") {
    return "http://localhost:4179";
  }
  return `${location.protocol}//${location.host}`;
}

function backendUnavailableMessage() {
  if (!ANI_BACKEND_SERVICES_ENABLED) {
    return "I can answer from ANI's medical encyclopedia. Try a medication, disease, laboratory test, clinical sign, or nursing topic.";
  }
  if (location.protocol === "file:") {
    return "ANI cannot reach live AI right now.";
  }
  if (isNativeShell) {
    const target = activeBackendLabel();
    return `ANI cannot reach the app server at ${target}. Keep the ANI server running on your computer, keep your phone and computer on the same Wi-Fi, then try again.`;
  }
  return "ANI cannot reach the app server right now. Refresh after the local ANI server is running, then try again.";
}

function recordingServerUnavailableMessage() {
  if (!ANI_SERVER_TRANSCRIPTION_ENABLED) {
    return "Recorded-audio transcription is not included in this encyclopedia launch. You can still type, or use your device's built-in speech input when available.";
  }
  if (location.protocol === "file:") {
    return "Recording worked, but transcription service is unavailable right now.";
  }
  if (isNativeShell) {
    return `Recording worked, but ANI could not reach the server at ${activeBackendLabel()}. Check Wi-Fi and keep the PC server running.`;
  }
  return "Recording worked, but ANI could not reach the server. You can still type.";
}

function aiUnavailableMessage() {
  if (!aniBackendReachable) {
    return backendUnavailableMessage();
  }
  if (!aniModelAvailable) {
    return OPENAI_REQUIRED_MESSAGE;
  }
  return ANI_BACKEND_UNREACHABLE_MESSAGE;
}

function hideAppSplash() {
  const completeStartupTiming = () => completeAniUiTimingAfterPaint(
    aniStartupTimingToken,
    () => document.body.classList.contains("app-ready")
      && (!appSplash || appSplash.classList.contains("is-hidden")),
    { state: "app-ready-painted", bindCurrentSurfaceAndDeviceMode: true }
  );
  if (!appSplash) {
    document.body.classList.remove("app-booting");
    document.body.classList.add("app-ready");
    completeStartupTiming();
    return;
  }
  window.setTimeout(() => {
    appSplash.classList.add("is-finishing");
    window.setTimeout(() => {
      appSplash.classList.add("is-hidden");
      appSplash.setAttribute("aria-hidden", "true");
      document.body.classList.remove("app-booting");
      document.body.classList.add("app-ready");
      completeStartupTiming();
    }, 140);
  }, isNativeShell ? 220 : 140);
}

