function readNursingFactState() {
  try {
    return JSON.parse(localStorage.getItem(NURSING_FACT_STATE_KEY) || "{}");
  } catch {
    return {};
  }
}

function writeNursingFactState(state = {}) {
  try {
    localStorage.setItem(NURSING_FACT_STATE_KEY, JSON.stringify(state));
  } catch {
    // Nonessential study garnish; failing storage should never block chat.
  }
}

function chooseNextNursingFactIndex(previousIndex = -1) {
  if (!nursingFactHeadliners.length) {
    return -1;
  }
  if (nursingFactHeadliners.length === 1) {
    return 0;
  }
  let nextIndex = Math.floor(Math.random() * nursingFactHeadliners.length);
  if (nextIndex === previousIndex) {
    nextIndex = (nextIndex + 1) % nursingFactHeadliners.length;
  }
  return nextIndex;
}

function currentNursingFact() {
  const now = Date.now();
  const state = readNursingFactState();
  const previousIndex = Number.isFinite(Number(state.index)) ? Number(state.index) : -1;
  const previousTimestamp = Number(state.timestamp || 0);
  if (previousIndex >= 0 && nursingFactHeadliners[previousIndex] && now - previousTimestamp < NURSING_FACT_INTERVAL_MS) {
    return nursingFactHeadliners[previousIndex];
  }
  const index = chooseNextNursingFactIndex(previousIndex);
  writeNursingFactState({ index, timestamp: now });
  return nursingFactHeadliners[index] || "";
}

function renderNursingFactTicker() {
  if (!nursingFactTicker) {
    return;
  }
  nursingFactTicker.textContent = currentNursingFact();
}

function startNursingFactTicker() {
  renderNursingFactTicker();
  window.setInterval(renderNursingFactTicker, Math.min(NURSING_FACT_INTERVAL_MS, 60 * 1000));
}

