function capturePharmHighlightedText() {
  const selected = selectedPharmText();
  if (selected?.text) {
    clearPharmSelectedParagraph({ preserveHighlightText: true, updateControls: false });
    currentPharmHighlightText = selected.text;
  } else {
    const selectedParagraphText = selectedPharmParagraphText();
    if (selectedParagraphText) currentPharmHighlightText = selectedParagraphText;
  }
  updatePharmVoiceControls();
  return currentPharmHighlightText.trim();
}

function updatePharmHighlightFromSelection() {
  if (pharmSelectionUpdateTimer) {
    window.clearTimeout(pharmSelectionUpdateTimer);
  }
  pharmSelectionUpdateTimer = window.setTimeout(() => {
    pharmSelectionUpdateTimer = null;
    capturePharmHighlightedText();
  }, 0);
}

function isInteractiveAssistantTarget(target) {
  return Boolean(target?.closest?.("button, input, label, select, textarea, a, [contenteditable='true']"));
}

function escapeRegex(value = "") {
  return String(value).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function applyNclexEssentialMarkup(text = "") {
  let marked = String(text || "");
  const labels = [
    "NCLEX essential",
    "NCLEX takeaway",
    "NCLEX red flag",
    "NCLEX trap",
    "Important NCLEX safety point",
    "Priority",
    "Safety",
    "Rationale",
    "Nook-and-cranny detail",
    "Clinical judgment target"
  ];

  labels.forEach((label) => {
    const pattern = new RegExp(`(^|\\n)(${escapeRegex(label)}:)`, "gi");
    marked = marked.replace(pattern, (match, prefix, labelText) => (
      match.includes("**") ? match : `${prefix}**${labelText}**`
    ));
  });

  return marked;
}

function appendFormattedText(parent, text = "") {
  const lines = String(text || "").split("\n");
  lines.forEach((line, lineIndex) => {
    if (lineIndex > 0) {
      parent.append(document.createElement("br"));
    }

    line.split(/(\*\*[^*]+\*\*)/g).forEach((segment) => {
      if (!segment) {
        return;
      }
      if (/^\*\*[^*]+\*\*$/.test(segment)) {
        const strong = document.createElement("strong");
        strong.textContent = segment.slice(2, -2);
        parent.append(strong);
      } else {
        parent.append(document.createTextNode(segment));
      }
    });
  });
}

function chatReferenceCandidateFromLabel(label = "") {
  const query = safeText(label).trim();
  if (!query) return null;
  const suggestions = offlineLookupSuggestions(query);
  const direct = suggestions.find((candidate) => inputDirectlyNamesOfflineCandidate(query, candidate)) || suggestions[0];
  if (!direct || !offlineLookupIsDirectEnough(query, direct)) return null;
  return direct;
}

function linkOpeningReferencePreface(bubble, sourceText = "") {
  if (!bubble || !/\bOpening\s+\*\*/i.test(sourceText) || !/\bin the clinical reference\b/i.test(sourceText)) {
    return;
  }
  const targets = [];
  const pattern = /\bOpening\s+\*\*([^*]{2,140})\*\*\s+in the clinical reference\b/gi;
  let match = pattern.exec(String(sourceText || ""));
  while (match) {
    const label = safeText(match[1]).trim();
    const candidate = chatReferenceCandidateFromLabel(label);
    if (candidate) {
      targets.push({
        label,
        candidate,
        key: offlineLookupEntityKey(candidate)
      });
    }
    match = pattern.exec(String(sourceText || ""));
  }
  if (!targets.length) return;

  const strongNodes = Array.from(bubble.querySelectorAll("strong"));
  targets.forEach((target) => {
    const strong = strongNodes.find((node) => (
      normalizePharmText(node.textContent) === normalizePharmText(target.label)
    ));
    if (!strong) return;
    const link = document.createElement("button");
    link.type = "button";
    link.className = "pharm-inline-link chat-encyclopedia-link chat-reference-reopen";
    link.dataset.encyclopediaTarget = target.key;
    link.dataset.aniTargetType = target.candidate.type;
    link.dataset.aniTargetName = offlineLookupEntityLabel(target.candidate);
    link.dataset.aniTargetKey = target.key;
    link.setAttribute("aria-label", `Reopen ${offlineLookupEntityLabel(target.candidate)} in ANI encyclopedia`);
    link.textContent = strong.textContent;
    link.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPharmDatabase(offlineLookupQuery(target.candidate), {
        openDetail: true,
        expandDetail: true,
        autoFocus: false,
        detailType: target.candidate.type,
        fastDetail: true,
        highlightQuery: offlineLookupEntityLabel(target.candidate),
        targetCandidate: { type: target.candidate.type, item: target.candidate.item }
      });
    });
    strong.replaceWith(link);
  });
}

function linkBoundEncyclopediaTargetInBubble(bubble, target = null) {
  const candidate = target?.candidate || target;
  if (!bubble || !candidate?.item || !candidate?.type) return false;
  const label = safeText(target?.label || offlineLookupEntityLabel(candidate));
  const normalizedLabel = normalizePharmText(label);
  if (!normalizedLabel) return false;
  const strong = Array.from(bubble.querySelectorAll("strong")).find((node) => {
    const text = normalizePharmText(node.textContent);
    return text === normalizedLabel || text.startsWith(`${normalizedLabel} `);
  });
  if (!strong) return false;
  const targetKey = safeText(target?.key || offlineLookupEntityKey(candidate));
  const link = document.createElement("button");
  link.type = "button";
  link.className = "pharm-inline-link chat-encyclopedia-link chat-reference-reopen";
  link.dataset.encyclopediaTarget = targetKey;
  link.dataset.aniTargetType = candidate.type;
  link.dataset.aniTargetName = label;
  link.dataset.aniTargetKey = targetKey;
  link.setAttribute("aria-label", `Open ${label} in ANI encyclopedia`);
  link.textContent = strong.textContent;
  link.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    openPharmDatabase(offlineLookupQuery(candidate), {
      openDetail: true,
      expandDetail: true,
      autoFocus: false,
      detailType: candidate.type,
      fastDetail: true,
      highlightQuery: label,
      targetCandidate: { type: candidate.type, item: candidate.item }
    });
  });
  strong.replaceWith(link);
  return true;
}

function setBubbleText(bubble, role, text = "", editable = false, options = {}) {
  if (role !== "assistant" || editable) {
    bubble.textContent = text;
    return;
  }

  bubble.textContent = "";
  appendFormattedText(bubble, applyNclexEssentialMarkup(text));
  const boundTargets = Array.isArray(options.boundEncyclopediaTargets)
    ? options.boundEncyclopediaTargets
    : [options.boundEncyclopediaTarget || null];
  const linkedBoundTarget = boundTargets
    .filter(Boolean)
    .map((target) => linkBoundEncyclopediaTargetInBubble(bubble, target))
    .some(Boolean);
  if (!linkedBoundTarget) {
    linkOpeningReferencePreface(bubble, text);
  }
  linkEncyclopediaTermsInBubble(bubble, text, {
    maxLinks: Number(options.maxEncyclopediaLinks || 0) || undefined
  });
}

function addMessage(role, text, editable = false, shouldSpeak = true, shouldRemember = true, options = {}) {
  const article = document.createElement("article");
  article.className = `message ${role}`;

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = role === "user" ? "You" : "ANI";

  const bubble = document.createElement("div");
  bubble.className = "bubble";
  setBubbleText(bubble, role, text, editable, options);
  if (role === "assistant" && options?.reportProblemDraft?.query) {
    const action = document.createElement("div");
    action.className = "chat-report-action";
    const button = document.createElement("button");
    button.type = "button";
    button.className = "chat-report-action-button";
    button.textContent = options.reportProblemDraft.label || "Report missing content";
    button.addEventListener("click", () => {
      openMissingContentReportDraft(options.reportProblemDraft.query, {
        category: options.reportProblemDraft.category || "missing_content"
      });
    });
    action.append(button);
    bubble.append(action);
  }
  if (editable) {
    bubble.contentEditable = "true";
    bubble.spellcheck = true;
    bubble.setAttribute("aria-label", "Editable message transcript");
  }

  if (role === "assistant") {
    const row = document.createElement("div");
    row.className = "assistant-row";
    const miniAvatar = createMiniAva(text);
    miniAvatar.classList.toggle("is-muted", aniMuted);
    miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
    miniAvatar.title = miniAvaActionLabel();
    miniAvatar.setAttribute("aria-pressed", String(aniMuted));
    if (shouldSpeak && ANI_AUTOPLAY_SPEECH && !aniMuted) {
      miniAvatar.classList.add("mini-speaking");
      window.setTimeout(() => {
        miniAvatar.classList.remove("mini-speaking");
      }, Math.min(12000, Math.max(2600, text.length * 36)));
    }
    row.append(miniAvatar, bubble);
    if (shouldAttachLectureDownloads(text)) {
      bubble.append(createLectureDownloadActions(text));
    }
    article.append(label, row);
    attachAssistantAccessibility(article, miniAvatar, bubble, text);
  } else {
    article.append(label, bubble);
  }

  chatLog.append(article);
  scrollChatToBottom();

  if (shouldRemember) {
    rememberConversation(role, text);
  }

  if (role === "assistant") {
    lastAssistantText = text;
    if (shouldSpeak && ANI_AUTOPLAY_SPEECH) {
      speak(text);
    }
  }
}

function offlineComparisonReadableText(comparison = {}) {
  const rows = Array.isArray(comparison.rows) ? comparison.rows : [];
  const primaryLabel = comparison.columns?.primary || "Lab";
  const rowText = rows.map((row) => (
    `${primaryLabel}: ${row.lab}. ${comparison.columns?.adult || "Adult"}: ${row.adult}. ${comparison.columns?.population || "Population"}: ${row.population}. ${comparison.columns?.why || "Why it matters"}: ${row.why}.`
  ));
  return [
    comparison.title,
    comparison.intro,
    ...rowText,
    comparison.summary ? `Pattern summary: ${comparison.summary}` : "",
    comparison.note,
    comparison.closing
  ].filter(Boolean).join("\n\n");
}

function addOfflineComparisonMessage(comparison = {}) {
  const readable = offlineComparisonReadableText(comparison);
  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(readable);
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = `${miniAvaActionLabel()} Right-click for read all.`;
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble offline-comparison-bubble";
  const title = document.createElement("strong");
  title.className = "offline-comparison-title";
  title.textContent = safeText(comparison.title || "Reference comparison");

  const wrap = document.createElement("div");
  wrap.className = "offline-comparison-table-wrap";
  const table = document.createElement("table");
  table.className = "offline-comparison-table";
  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const headings = [
    comparison.columns?.primary || "Lab",
    comparison.columns?.adult || "Adult",
    comparison.columns?.population || "Comparison group",
    comparison.columns?.why || "Why it matters"
  ];
  headings.forEach((headingText) => {
    const th = document.createElement("th");
    th.textContent = headingText;
    headRow.append(th);
  });
  thead.append(headRow);
  const tbody = document.createElement("tbody");
  (comparison.rows || []).forEach((item) => {
    const tr = document.createElement("tr");
    [
      item.lab,
      item.adult,
      item.population,
      item.why
    ].forEach((cellText, index) => {
      const td = document.createElement("td");
      td.dataset.label = headings[index] || "";
      appendFormattedText(td, applyNclexEssentialMarkup(cellText || ""));
      linkEncyclopediaTermsInBubble(td, cellText || "", { maxLinks: 3 });
      tr.append(td);
    });
    tbody.append(tr);
  });
  table.append(thead, tbody);
  wrap.append(table);

  const note = document.createElement("p");
  note.className = "offline-comparison-note";
  const noteText = [comparison.note, comparison.closing].filter(Boolean).join("\n\n");
  appendFormattedText(note, applyNclexEssentialMarkup(noteText));
  linkEncyclopediaTermsInBubble(note, noteText, { maxLinks: 4 });
  const summaryText = safeText(comparison.summary);
  const summary = document.createElement("p");
  summary.className = "offline-comparison-summary";
  if (summaryText) {
    appendFormattedText(summary, applyNclexEssentialMarkup(`**Pattern summary:** ${summaryText}`));
    linkEncyclopediaTermsInBubble(summary, summaryText, { maxLinks: 5 });
  }
  bubble.append(title);
  if (comparison.intro) {
    const intro = document.createElement("p");
    intro.className = "offline-comparison-intro";
    appendFormattedText(intro, applyNclexEssentialMarkup(comparison.intro));
    bubble.append(intro);
  }
  bubble.append(wrap);
  if (summaryText) {
    bubble.append(summary);
  }
  bubble.append(note);

  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, readable);
  chatLog.append(article);
  scrollChatToBottom();
  rememberConversation("assistant", readable);
  lastAssistantText = readable;
  if (!aniMuted) {
    speak(readable);
  }
  return { article, bubble };
}

function visualAidCue(input = "") {
  const lower = normalizeIntentText(input);
  if (/\b(graph|chart|curve|curves|visual|visual aid|diagram|flowchart|map|timeline|picture|image|draw|show me)\b/i.test(lower)) {
    return true;
  }
  return /\b(throughout|over time|across ages|by age|year by year|trend|trends)\b/i.test(lower)
    && /\b(age|ages|year|years|height|weight|growth|percentile|percentiles|procedure|steps?|pathophysiology|disease|condition)\b/i.test(lower);
}

function offlineVisualCandidate(input = "") {
  if (!visualAidCue(input)) return null;
  const lower = normalizeIntentText(input);
  if (/\b(question|questions|quiz|quizzes|practice problem|practice item|test question|drill|challenge|nclex item|case study)\b/i.test(lower)) {
    return null;
  }
  if (isBareOfflineLookupFollowup(input)) {
    const remembered = recentOfflineLookupTarget();
    return offlineVisualCandidateSupportsVisual(remembered) ? remembered : null;
  }
  if (wantsGrowthReference(input)) {
    const growth = bestClinicalReferenceMatch(input, { type: "growth" });
    if (growth) return { type: "reference", item: growth, score: 999 };
  }
  const suggestions = offlineLookupSuggestions(input);
  return suggestions.find((candidate) => (
    offlineVisualCandidateSupportsVisual(candidate)
    && offlineLookupIsDirectEnough(input, candidate)
  )) || null;
}

function offlineVisualReadableText(response = {}) {
  const candidate = response.candidate || {};
  const label = offlineLookupEntityLabel(candidate);
  const growthAxis = response.growthAxis || "";
  const growthVisualPath = growthAxis === "height"
    ? "Visual path: height-for-age percentile curve anchors across age."
    : growthAxis === "weight"
    ? "Visual path: weight-for-age percentile curve anchors across age."
    : "Visual path: height and weight percentile curve anchors across age.";
  const parts = [
    response.title,
    response.lead,
    candidate.type === "pathology" ? "Visual path: pathophysiology, findings, diagnostics, treatment, nursing priorities, and complications." : "",
    candidate.type === "reference" && candidate.item?.type === "procedure" ? "Visual path: why it is done, before, during, after, red flags, and NCLEX trap." : "",
    candidate.type === "reference" && candidate.item?.type === "growth" ? growthVisualPath : "",
    label ? `Opened visual aid for ${label}.` : ""
  ];
  return parts.filter(Boolean).join("\n\n");
}

function makeOfflineVisualResponse(input = "") {
  const candidate = offlineVisualCandidate(input);
  if (!candidate) return null;
  const label = offlineLookupEntityLabel(candidate);
  if (!label) return null;
  const item = candidate.item || {};
  rememberOfflineLookupTarget(candidate, input);

  if (candidate.type === "reference" && item.type === "growth") {
    const growthAxis = growthAxisIntent(input);
    const titleAxis = growthAxis === "weight"
      ? "Weight-for-age"
      : growthAxis === "height"
      ? "Height-for-age"
      : "Pediatric growth";
    return {
      type: "offline-visual",
      candidate,
      title: `${titleAxis} percentiles - visual aid`,
      lead: growthQuickAnswerForInput(item, input),
      visuals: growthVisualsForInput(item, input),
      growthAxis
    };
  }

  if (candidate.type === "reference" && item.type === "procedure") {
    return {
      type: "offline-visual",
      candidate,
      title: `${clinicalReferenceDisplayName(item)} - procedure visual aid`,
      lead: item.quickAnswer || item.summary || "",
      flow: makeClinicalReferenceFlowVisualData(item)
    };
  }

  if (candidate.type === "pathology") {
    return {
      type: "offline-visual",
      candidate,
      title: `${safeText(item.name)} - pathology visual aid`,
      lead: item.pathology || pathologyListText(item.signsSymptoms) || "",
      flow: makePathologyFlowVisualData(item)
    };
  }

  return null;
}

function addOfflineReferenceVisualMessage(response = {}) {
  const readable = offlineVisualReadableText(response);
  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(readable);
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble offline-visual-bubble";
  const title = document.createElement("strong");
  title.className = "offline-visual-title";
  title.textContent = safeText(response.title || "Reference visual aid");
  bubble.append(title);

  if (response.lead) {
    const lead = document.createElement("p");
    lead.className = "offline-visual-lead";
    appendFormattedText(lead, applyNclexEssentialMarkup(response.lead));
    linkEncyclopediaTermsInBubble(lead, response.lead, { maxLinks: 5 });
    bubble.append(lead);
  }

  (response.visuals || []).forEach((visual) => {
    if (visual?.type === "percentile-curves") {
      bubble.append(buildPercentileCurveVisual(visual));
    }
  });

  if (response.flow) {
    bubble.append(buildClinicalFlowVisual(response.flow));
  }

  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, readable);
  chatLog.append(article);
  scrollChatToBottom();
  rememberConversation("assistant", readable);
  lastAssistantText = readable;
  if (!aniMuted) {
    speak(readable);
  }
}

function shouldAttachLectureDownloads(text = "") {
  const value = String(text || "");
  if (value.length < 700) return false;
  return hasCompleteLectureStructure(value)
    || (/\bpathophysiology\b/i.test(value) && /\bnclex traps?\b/i.test(value) && /\bpriority nursing actions?\b/i.test(value));
}

function sanitizeDownloadFileName(value = "ANI lecture") {
  return String(value || "ANI lecture")
    .replace(/[^a-z0-9 _-]+/gi, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, 72)
    .replace(/\s/g, "-")
    .toLowerCase() || "ani-lecture";
}

function firstMeaningfulLine(text = "") {
  return String(text || "")
    .split(/\n+/)
    .map((line) => line.replace(/\*\*/g, "").replace(/^\s*\d+\.\s*/, "").trim())
    .find((line) => line.length >= 4) || "";
}

async function downloadBlob(blob, filename) {
  if (isNativeShell && getNativeFileBridge()) {
    try {
      if (await saveBlobWithNativeBridge(blob, filename)) {
        if (voiceStatus) {
          voiceStatus.textContent = `${filename} was saved in your device's Downloads/ANI folder.`;
        }
        return;
      }
    } catch (error) {
      if (voiceStatus) {
        voiceStatus.textContent = error.message || "ANI could not save the file with the app, so she is trying the browser download.";
      }
    }
  }

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = filename;
  link.rel = "noopener";
  document.body.append(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 5000);
  if (voiceStatus) {
    voiceStatus.textContent = `${filename} download started.`;
  }
}

function pdfSafeText(value = "") {
  return String(value || "")
    .replace(/[“”]/g, '"')
    .replace(/[‘’]/g, "'")
    .replace(/[–—]/g, "-")
    .replace(/[^\x09\x0A\x0D\x20-\x7E]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function pdfEscape(value = "") {
  return pdfSafeText(value).replace(/\\/g, "\\\\").replace(/\(/g, "\\(").replace(/\)/g, "\\)");
}

function wrapPdfLine(text = "", maxChars = 88) {
  const words = pdfSafeText(text).split(/\s+/).filter(Boolean);
  const lines = [];
  let line = "";
  words.forEach((word) => {
    const next = line ? `${line} ${word}` : word;
    if (next.length > maxChars && line) {
      lines.push(line);
      line = word;
    } else {
      line = next;
    }
  });
  if (line) lines.push(line);
  return lines.length ? lines : [""];
}

function makeSimplePdfBlob(title = "ANI Lecture", text = "") {
  const sourceLines = [
    `ANI Lecture Script - ${title}`,
    `Generated ${new Date().toLocaleString()}`,
    "",
    ...String(text || "").split(/\n+/)
  ];
  const lines = sourceLines.flatMap((line) => line.trim() ? wrapPdfLine(line) : [""]);
  const pageLineLimit = 45;
  const pages = [];
  for (let i = 0; i < lines.length; i += pageLineLimit) {
    pages.push(lines.slice(i, i + pageLineLimit));
  }
  if (!pages.length) pages.push(["ANI lecture script"]);

  const objects = [];
  const addObject = (body) => {
    objects.push(body);
    return objects.length;
  };
  const catalogId = addObject("<< /Type /Catalog /Pages 2 0 R >>");
  const pagesId = addObject("");
  const pageIds = [];
  const fontId = 3 + pages.length * 2;

  pages.forEach((pageLines) => {
    const content = [
      "BT",
      "/F1 11 Tf",
      "48 760 Td",
      "14 TL",
      ...pageLines.map((line) => `(${pdfEscape(line)}) Tj T*`),
      "ET"
    ].join("\n");
    const contentId = addObject(`<< /Length ${content.length} >>\nstream\n${content}\nendstream`);
    const pageId = addObject(`<< /Type /Page /Parent ${pagesId} 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${fontId} 0 R >> >> /Contents ${contentId} 0 R >>`);
    pageIds.push(pageId);
  });
  addObject("<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>");
  objects[pagesId - 1] = `<< /Type /Pages /Kids [${pageIds.map((id) => `${id} 0 R`).join(" ")}] /Count ${pageIds.length} >>`;

  let pdf = "%PDF-1.4\n";
  const offsets = [0];
  objects.forEach((body, index) => {
    offsets.push(pdf.length);
    pdf += `${index + 1} 0 obj\n${body}\nendobj\n`;
  });
  const xrefOffset = pdf.length;
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`;
  offsets.slice(1).forEach((offset) => {
    pdf += `${String(offset).padStart(10, "0")} 00000 n \n`;
  });
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root ${catalogId} 0 R >>\nstartxref\n${xrefOffset}\n%%EOF`;
  return new Blob([pdf], { type: "application/pdf" });
}

async function downloadLectureAudioMp3(text = "", button = null) {
  const previous = button?.textContent || "MP3";
  if (button) {
    button.disabled = true;
    button.textContent = "Building MP3...";
  }
  try {
    const response = await fetchApi("/api/ani/lecture-audio", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({ text })
    });
    if (!response.ok) {
      const data = await response.json().catch(() => ({}));
      throw new Error(data.error || data.text || "ANI could not export lecture audio yet.");
    }
    const responseBlob = await response.blob();
    const contentType = String(response.headers.get("content-type") || responseBlob.type || "").toLowerCase();
    const header = new Uint8Array(await responseBlob.slice(0, 4).arrayBuffer());
    const hasId3Header = header.length >= 3 && header[0] === 0x49 && header[1] === 0x44 && header[2] === 0x33;
    const hasMpegFrameHeader = header.length >= 2 && header[0] === 0xff && (header[1] & 0xe0) === 0xe0;
    if (!contentType.includes("audio/mpeg") && !contentType.includes("audio/mp3") && !hasId3Header && !hasMpegFrameHeader) {
      throw new Error("ANI received a response that was not a playable MP3, so no invalid audio file was saved.");
    }
    if (!hasId3Header && !hasMpegFrameHeader) {
      throw new Error("ANI could not verify a valid MP3 audio stream, so no file was saved.");
    }
    const blob = responseBlob.type === "audio/mpeg"
      ? responseBlob
      : new Blob([responseBlob], { type: "audio/mpeg" });
    await downloadBlob(blob, `${sanitizeDownloadFileName(firstMeaningfulLine(text) || "ani lecture")}.mp3`);
  } catch (error) {
    if (voiceStatus) {
      voiceStatus.textContent = error.message || "ANI could not export MP3 yet.";
    }
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = previous;
    }
  }
}

function createLectureDownloadActions(text = "") {
  const actions = document.createElement("div");
  actions.className = "lecture-download-actions";
  ["click", "pointerdown", "mousedown", "touchstart"].forEach((eventName) => {
    actions.addEventListener(eventName, (event) => {
      event.stopPropagation();
    });
  });

  const pdfButton = document.createElement("button");
  pdfButton.type = "button";
  pdfButton.textContent = "Download PDF script";
  pdfButton.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    const title = firstMeaningfulLine(text) || "ANI lecture";
    downloadBlob(makeSimplePdfBlob(title, text), `${sanitizeDownloadFileName(title)}.pdf`).catch((error) => {
      if (voiceStatus) {
        voiceStatus.textContent = error.message || "ANI could not export that PDF yet.";
      }
    });
  });

  actions.append(pdfButton);
  if (ANI_SERVER_LECTURE_AUDIO_ENABLED) {
    const mp3Button = document.createElement("button");
    mp3Button.type = "button";
    mp3Button.textContent = "Download MP3 lecture";
    mp3Button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      downloadLectureAudioMp3(text, mp3Button);
    });
    actions.append(mp3Button);
  }
  return actions;
}

function wantsCjeChallenge(input = "") {
  if (wantsUnfoldingCase(input)) {
    return false;
  }

  const lower = normalizeIntentText(input);
  return /\b(cje|clinical judgment exam|clinical judgment|ngn|bow[-\s]?tie|butterfly|tabbed|tabs|nursing notes|vital signs|laboratory results|labs|collaborative care|medication prescriptions)\b/i.test(lower)
    && /\b(question|questions|item|items|challenge|hard|generate|ask|give|practice|make|create|drill|butterfly|bow[-\s]?tie|case)\b/i.test(lower);
}

function nextCjeCase(input = "") {
  const lower = normalizeIntentText(input);
  const shockCases = cjeCaseBank.filter((caseItem) => caseItem.topic === "Complex Care" && /shock|deterioration/i.test(`${caseItem.id} ${caseItem.title} ${caseItem.client} ${caseItem.rationale?.condition || ""}`));
  const neuroCases = cjeCaseBank.filter((caseItem) => caseItem.topic === "Neuro Complex Care");
  const endocrineCases = cjeCaseBank.filter((caseItem) => caseItem.topic === "Endocrine");
  const maternalCases = cjeCaseBank.filter((caseItem) => caseItem.topic === "Maternal newborn");
  const requested = (/icp|intracranial|gcs|glasgow|brain|ventriculostomy|evd/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-neuro-icp") : null)
    || (/stroke|dysphagia|swallow|vertigo|ataxia|thrombolytic|\btpa\b|alteplase/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-neuro-stroke-airway") : null)
    || (/neuro|seizure|spinal|myasthenic|guillain/.test(lower) ? chooseFreshItem(neuroCases, "cje-case") : null)
    || (/thyroid|graves|storm/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-endocrine-thyroid-storm") : null)
    || (/dka|diabetic|potassium|insulin/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-dka-potassium") : null)
    || (/endocrine/.test(lower) ? chooseFreshItem(endocrineCases, "cje-case") : null)
    || (/hemorrhage|haemorrhage|boggy|fundus|lochia|uterine atony|uterus/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-postpartum-hemorrhage") : null)
    || (/\bpe\b|embolism|dyspnea|calf/.test(lower) && /postpartum|maternal|pregnan|cesarean|birth/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-postpartum-pe") : null)
    || (/postpartum|maternal|pregnan|newborn|birth/.test(lower) ? chooseFreshItem(maternalCases, "cje-case") : null)
    || (/cardiogenic|myocardial|infarction|\bmi\b|pulmonary edema|pump failure/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-cardiogenic-shock") : null)
    || (/sepsis|septic|pneumonia/.test(lower) ? cjeCaseBank.find((caseItem) => caseItem.id === "cje-septic-shock") : null)
    || (/shock|critical|icu|high acuity/.test(lower) ? chooseFreshItem(shockCases, "cje-case") : null)
    || cjeCaseBank.find((caseItem) => lower.includes(caseItem.topic.toLowerCase()));

  if (requested) {
    const exactCaseRequested = (requested.id === "cje-neuro-icp" && /icp|intracranial|gcs|glasgow|ventriculostomy|evd/.test(lower))
      || (requested.id === "cje-neuro-stroke-airway" && /stroke|dysphagia|swallow|vertigo|ataxia|thrombolytic|\btpa\b|alteplase/.test(lower))
      || (requested.id === "cje-dka-potassium" && /dka|diabetic|potassium|insulin/.test(lower))
      || (requested.id === "cje-endocrine-thyroid-storm" && /thyroid|graves|storm/.test(lower))
      || (requested.id === "cje-postpartum-hemorrhage" && /hemorrhage|haemorrhage|boggy|fundus|lochia|uterine atony|uterus/.test(lower))
      || (requested.id === "cje-postpartum-pe" && (/\bpe\b|embolism|dyspnea|calf/.test(lower)))
      || (requested.id === "cje-cardiogenic-shock" && /cardiogenic|myocardial|infarction|\bmi\b|pulmonary edema|pump failure/.test(lower))
      || (requested.id === "cje-septic-shock" && /sepsis|septic|pneumonia/.test(lower));
    if (exactCaseRequested) {
      return requested;
    }

    if (recentCjeCaseIds.includes(requested.id)) {
      const alternates = cjeCaseBank.filter((caseItem) => caseItem.id !== requested.id && caseItem.topic === requested.topic);
      const freshAlternate = chooseFreshItem(alternates, "cje-case");
      if (freshAlternate) {
        return freshAlternate;
      }
    }
    return requested;
  }

  const selected = chooseFreshItem(cjeCaseBank, "cje-case") || cjeCaseBank[cjeRotationIndex % cjeCaseBank.length];
  cjeRotationIndex += 1;
  return selected;
}

function makeCjeChallenge(input = "") {
  const caseItem = nextCjeCase(input);
  if (!caseItem) {
    return null;
  }
  currentTopic = caseItem.topic;
  saveDifficulty("hard");
  updateFocus();
  return {
    type: "cje-case",
    caseItem
  };
}

function cjeDisplayTitle(caseItem) {
  return caseItem.displayTitle || "Client Chart Review";
}

function advancedDisplayTitle(item) {
  if (item.displayTitle) {
    return item.displayTitle;
  }
  const label = advancedTypeLabel(item);
  return `${label.charAt(0).toUpperCase()}${label.slice(1)} item`;
}

function unfoldingDisplayTitle(caseItem) {
  if (caseItem.displayTitle) {
    return caseItem.displayTitle;
  }
  return caseItem.variant === "condensed" ? "Condensed Ongoing Case Study" : "Full Ongoing Case Study";
}

function unfoldingIntroText(caseItem) {
  const count = Array.isArray(caseItem.steps) ? caseItem.steps.length : 6;
  const modeLine = caseItem.variant === "condensed"
    ? "This is the condensed version: quick chart updates, faster questions, and less chart-reading load."
    : "This is the full version: the chart tabs accumulate notes, vitals, labs, collaborative care, and prescriptions as the same client evolves.";
  return `${unfoldingDisplayTitle(caseItem)}\n\nThe following ${count} questions are part of an ongoing clinical judgment case study. This is the same client each time; new chart data will be added as the case develops.\n\n${modeLine}`;
}

function cjeIntroText(caseItem) {
  return `${cjeDisplayTitle(caseItem)}\n\nThis is a hard clinical judgment item with chart tabs and a bow-tie/butterfly answer format. Inspect the tabs before answering. The trap is in the trend, not one isolated value.`;
}

function wantsConceptDiagram(input = "") {
  const lower = normalizeIntentText(input);
  const visualCue = /\b(diagram|draw|illustrate|illustration|visual|visualize|picture|image|concept map|flowchart|labeled|labelled|numbered|sketch|show me|looks? like)\b/i.test(lower);
  const taskCue = /\b(explain|teach|break down|show|make|create|generate|draw|diagram|visualize|map|looks? like)\b/i.test(lower);
  const uploadCue = /\b(upload|uploaded|attached|attachment|screenshot|scan|analyze this image|look at this image)\b/i.test(lower);
  // frontier-wave13-medication-draw-not-diagram
  const medicationDrawUpCue = /\b(draw|drawing|withdraw|withdrawing)\b[\s\S]{0,80}\b(into|up)\b[\s\S]{0,35}\b(syringe|needle|iv|intravenous)\b|\bdraw\s+up\b/i.test(lower);
  // frontier-wave16-figurative-look-not-diagram
  const explicitVisualCreationCue = /\b(diagram|draw|illustrat|visuali[sz]e|picture|image|concept map|flowchart|sketch)\b/i.test(lower);
  const figurativeLookCue = !explicitVisualCreationCue
    && /\bmak(?:e|es|ing|ed)\b[\s\S]{0,120}\blook(?:s|ed|ing)? like\b/i.test(lower);
  return visualCue && taskCue && !uploadCue && !medicationDrawUpCue && !figurativeLookCue;
}

