function makeConceptDiagram(input = "") {
  const template = conceptDiagramTemplates.find((item) => item.match.test(input)) || defaultConceptDiagram;
  return {
    ...template,
    requestedFrom: input,
    points: template.points.map((point, index) => ({
      ...point,
      id: point.id || String(index + 1)
    }))
  };
}

function diagramNarration(diagram) {
  const pointText = diagram.points
    .map((point) => `${point.id}. ${point.label}: ${point.detail}`)
    .join(" ");
  const essentials = diagram.essentials?.length
    ? ` NCLEX essentials: ${diagram.essentials.join(" ")}`
    : "";
  return `${diagram.title}. ${diagram.subtitle} ${pointText}${essentials}`;
}

function addConceptDiagramMessage(diagram) {
  markActiveLearningContext("concept-diagram", {
    title: diagram.title,
    topic: diagram.topic,
    points: diagram.points,
    essentials: diagram.essentials
  });

  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const narration = diagramNarration(diagram);
  const miniAvatar = createMiniAva(narration);
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble concept-diagram-bubble";

  const intro = document.createElement("p");
  intro.className = "concept-diagram-intro";
  intro.textContent = "I made a numbered visual. Use the numbers in the picture, then match them to the rationale list underneath.";

  const card = document.createElement("section");
  card.className = "concept-diagram-card";
  card.setAttribute("aria-label", diagram.title);

  const header = document.createElement("div");
  header.className = "concept-diagram-header";
  const title = document.createElement("strong");
  title.textContent = diagram.title;
  const subtitle = document.createElement("span");
  subtitle.textContent = diagram.subtitle;
  header.append(title, subtitle);

  const visual = document.createElement("div");
  visual.className = "concept-diagram-visual";
  visual.setAttribute("role", "img");
  visual.setAttribute("aria-label", `${diagram.title} numbered concept diagram`);

  diagram.points.forEach((point, index) => {
    const connector = document.createElement("span");
    connector.className = `diagram-connector connector-${index + 1}`;
    visual.append(connector);
  });

  const center = document.createElement("div");
  center.className = "diagram-center";
  center.textContent = diagram.center;
  visual.append(center);

  diagram.points.forEach((point, index) => {
    const node = document.createElement("div");
    node.className = "diagram-node";
    node.dataset.position = String(index + 1);

    const marker = document.createElement("span");
    marker.className = "diagram-marker";
    marker.textContent = point.id;

    const text = document.createElement("strong");
    text.textContent = point.label;
    node.append(marker, text);
    visual.append(node);
  });

  const pointList = document.createElement("ol");
  pointList.className = "concept-diagram-points";
  diagram.points.forEach((point) => {
    const item = document.createElement("li");
    const heading = document.createElement("strong");
    heading.textContent = `${point.id}. ${point.label}:`;
    item.append(heading, ` ${point.detail}`);
    pointList.append(item);
  });

  const essentials = document.createElement("div");
  essentials.className = "concept-diagram-essentials";
  (diagram.essentials || []).forEach((essential) => {
    const line = document.createElement("p");
    const strong = document.createElement("strong");
    strong.textContent = "NCLEX essential:";
    line.append(strong, ` ${essential.replace(/^NCLEX essential:\s*/i, "")}`);
    essentials.append(line);
  });

  card.append(header, visual, pointList, essentials);
  bubble.append(intro, card);
  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, narration);
  chatLog.append(article);
  scrollChatToBottom();

  rememberConversation("assistant", `${diagram.title}: ${diagram.points.map((point) => `${point.id} ${point.label}`).join("; ")}`);
  lastAssistantText = narration;
  speak(narration);
}

function isVitalSignsTab(tab) {
  return /vital signs?/i.test(tab?.label || "");
}

function isLabResultsTab(tab) {
  return /laborator(?:y|ies)|\blabs?\b/i.test(tab?.label || "");
}

function splitChartEntry(entry = "") {
  const text = String(entry).trim();
  const separator = text.search(/:\s+/);

  if (separator === -1) {
    return {
      label: "",
      body: text
    };
  }

  return {
    label: text.slice(0, separator).trim(),
    body: text.slice(separator + 1).trim()
  };
}

function formatChartDateLabel(label = "") {
  const match = /\b(\d{1,2})\/(\d{1,2})(?:\/\d{2,4})?\b/.exec(String(label));
  if (!match) {
    return "";
  }

  return `${Number(match[1])}/${Number(match[2])}`;
}

function formatClockTimeLabel(label = "") {
  const trimmed = String(label).trim();
  const compact = /\b(\d{1,2})(\d{2})\b/.exec(trimmed);
  if (compact) {
    return `${compact[1].padStart(2, "0")}:${compact[2]}`;
  }

  const clock = /\b(\d{1,2}):(\d{2})\s*(AM|PM)?\b/i.exec(trimmed);
  if (clock) {
    return `${clock[1].padStart(2, "0")}:${clock[2]}${clock[3] ? ` ${clock[3].toUpperCase()}` : ""}`;
  }

  return "";
}

function parseDateTimeLabel(label = "", fallback = "Reading") {
  const raw = String(label || "").trim();
  const date = formatChartDateLabel(raw);
  const time = formatClockTimeLabel(raw);
  let event = raw
    .replace(/\b\d{1,2}\/\d{1,2}(?:\/\d{2,4})?\b/g, "")
    .replace(/\b\d{1,2}:?\d{2}\s*(?:AM|PM)?\b/gi, "")
    .replace(/\s{2,}/g, " ")
    .replace(/^[,\s-]+|[,\s-]+$/g, "")
    .trim();

  if (!event && !time && !date) {
    event = fallback;
  }

  return {
    date,
    time: time || event || fallback,
    event: event && event !== time ? event : ""
  };
}

function extractVitalField(body, key, pattern, fields, removals) {
  const match = pattern.exec(body);
  if (!match) {
    return;
  }

  fields[key] = match[1].trim();
  removals.push(match[0]);
}

function parseVitalSignEntry(entry = "") {
  const { label, body } = splitChartEntry(entry);
  const parsedLabel = parseDateTimeLabel(label, "Reading");
  const fields = {
    ...parsedLabel
  };
  const removals = [];

  extractVitalField(body, "temp", /\bT\s*([0-9.]+\s*[CF])\b/i, fields, removals);
  extractVitalField(body, "bp", /\bBP\s*([0-9]{2,3}\/[0-9]{2,3})\b/i, fields, removals);
  extractVitalField(body, "map", /\bMAP\s*([0-9]{2,3})\b/i, fields, removals);
  extractVitalField(body, "hr", /\bHR\s*([0-9]{2,3}(?:\/min)?)\b/i, fields, removals);
  extractVitalField(body, "rr", /\bRR\s*([0-9]{1,3}(?:\/min)?)\b/i, fields, removals);
  extractVitalField(body, "spo2", /\bSpO2\s*([0-9]{2,3}%[^,.;]*)/i, fields, removals);
  extractVitalField(body, "pain", /\bpain(?:\s+(?:rated|is))?\s*([0-9]{1,2}\/10)\b/i, fields, removals);

  let other = body;
  removals.forEach((text) => {
    other = other.replace(text, " ");
  });
  other = other
    .replace(/[;,]+/g, " ")
    .replace(/\s{2,}/g, " ")
    .replace(/^\W+|\W+$/g, "")
    .trim();

  if (other) {
    fields.other = other;
  }

  return fields;
}

function setTimeCellContent(cell, row, previousDate = "") {
  cell.textContent = "";

  if (row.date && row.date !== previousDate) {
    const date = document.createElement("span");
    date.className = "chart-date-label";
    date.textContent = row.date;
    cell.append(date);
  }

  const time = document.createElement("span");
  time.className = "chart-time-label";
  time.textContent = row.time || row.event || "Reading";
  cell.append(time);

  if (row.event && row.event !== row.time) {
    const event = document.createElement("span");
    event.className = "chart-event-label";
    event.textContent = row.event;
    cell.append(event);
  }
}

function appendVitalSignTable(panel, tab) {
  const rows = (tab.entries || []).map(parseVitalSignEntry);
  const columns = [
    ["time", "Time / event"],
    ["temp", "Temp"],
    ["bp", "BP"],
    ["map", "MAP"],
    ["hr", "HR"],
    ["rr", "RR"],
    ["spo2", "SpO2"],
    ["pain", "Pain"],
    ["other", "Notes"]
  ].filter(([key]) => key === "time" || rows.some((row) => row[key]));

  const wrap = document.createElement("div");
  wrap.className = "vitals-chart-wrap";
  const table = document.createElement("table");
  table.className = "vitals-chart";
  table.setAttribute("aria-label", "Vital signs flowsheet");

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  columns.forEach(([, label]) => {
    const th = document.createElement("th");
    th.textContent = label;
    headRow.append(th);
  });
  thead.append(headRow);
  table.append(thead);

  const tbody = document.createElement("tbody");
  let previousDate = "";
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    columns.forEach(([key, label]) => {
      const cell = key === "time" ? document.createElement("th") : document.createElement("td");
      cell.dataset.label = label;
      if (key === "time") {
        cell.setAttribute("scope", "row");
        setTimeCellContent(cell, row, previousDate);
      } else {
        cell.textContent = row[key] || "-";
      }
      tr.append(cell);
    });
    if (row.date) {
      previousDate = row.date;
    }
    tbody.append(tr);
  });
  table.append(tbody);
  wrap.append(table);
  panel.append(wrap);
}

function normalizeLabColumnName(rawName = "") {
  const cleaned = rawName
    .replace(/\s{2,}/g, " ")
    .replace(/[()]/g, "")
    .trim();

  const key = cleaned.toLowerCase();
  if (/^white blood cell|^wbc/.test(key)) return "WBC";
  if (/^bands?/.test(key)) return "Bands";
  if (/^hemoglobin|^hgb/.test(key)) return "Hgb";
  if (/^hematocrit|^hct/.test(key)) return "Hct";
  if (/^platelets?/.test(key)) return "Platelets";
  if (/^lactate/.test(key)) return "Lactate";
  if (/^creatinine/.test(key)) return "Creatinine";
  if (/^glucose/.test(key)) return "Glucose";
  if (/^potassium|^k\b/.test(key)) return "Potassium";
  if (/^sodium|^na\b/.test(key)) return "Sodium";
  if (/^calcium|^ca\b/.test(key)) return "Calcium";
  if (/^magnesium|^mg\b/.test(key)) return "Magnesium";
  if (/^ph$/.test(key)) return "pH";
  if (/^paco2/.test(key)) return "PaCO2";
  if (/^pao2/.test(key)) return "PaO2";
  if (/^hco3|^bicarbonate/.test(key)) return "HCO3";
  if (/^anion gap/.test(key)) return "Anion gap";
  if (/^osmolality|^serum osmolality/.test(key)) return "Osmolality";
  if (/^ketones?/.test(key)) return "Ketones";
  if (/^lipase/.test(key)) return "Lipase";
  if (/^ast\/alt|^ast|^alt/.test(key)) return "AST/ALT";
  if (/^pt\/inr|^inr/.test(key)) return "PT/INR";
  if (/^aptt|^ptt/.test(key)) return "aPTT";
  return cleaned || "Result";
}

function parseLabSegment(segment = "") {
  const cleaned = String(segment)
    .replace(/\s{2,}/g, " ")
    .replace(/^\W+|\W+$/g, "")
    .trim();

  if (!cleaned) {
    return null;
  }

  const match = /^([A-Za-z][A-Za-z0-9/%+\-. ]{0,28}?)(?:\s*[:=]\s*|\s+)(.+)$/.exec(cleaned);
  if (!match) {
    return {
      key: "Notes",
      value: cleaned
    };
  }

  return {
    key: normalizeLabColumnName(match[1]),
    value: match[2].trim()
  };
}

function parseLabResultEntry(entry = "") {
  const { label, body } = splitChartEntry(entry);
  const parsedLabel = parseDateTimeLabel(label, "Result");
  const fields = {
    ...parsedLabel
  };

  const segments = body
    .split(";")
    .map((segment) => segment.trim())
    .filter(Boolean);

  const parsedSegments = (segments.length ? segments : [body])
    .map(parseLabSegment)
    .filter(Boolean);

  parsedSegments.forEach(({ key, value }) => {
    if (fields[key]) {
      fields[key] = `${fields[key]}; ${value}`;
    } else {
      fields[key] = value;
    }
  });

  return fields;
}

function appendLabResultTable(panel, tab) {
  const rows = (tab.entries || []).map(parseLabResultEntry);
  const columnOrder = [];
  rows.forEach((row) => {
    Object.keys(row).forEach((key) => {
      if (!["date", "time", "event"].includes(key) && !columnOrder.includes(key)) {
        columnOrder.push(key);
      }
    });
  });

  const columns = [
    ["time", "Time / event"],
    ...columnOrder.map((key) => [key, key])
  ];

  const wrap = document.createElement("div");
  wrap.className = "vitals-chart-wrap lab-chart-wrap";
  const table = document.createElement("table");
  table.className = "vitals-chart lab-chart";
  table.setAttribute("aria-label", "Laboratory results flowsheet");

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  columns.forEach(([, label]) => {
    const th = document.createElement("th");
    th.textContent = label;
    headRow.append(th);
  });
  thead.append(headRow);
  table.append(thead);

  const tbody = document.createElement("tbody");
  let previousDate = "";
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    columns.forEach(([key, label]) => {
      const cell = key === "time" ? document.createElement("th") : document.createElement("td");
      cell.dataset.label = label;
      if (key === "time") {
        cell.setAttribute("scope", "row");
        setTimeCellContent(cell, row, previousDate);
      } else {
        cell.textContent = row[key] || "-";
      }
      tr.append(cell);
    });
    if (row.date) {
      previousDate = row.date;
    }
    tbody.append(tr);
  });
  table.append(tbody);
  wrap.append(table);
  panel.append(wrap);
}

function appendTabbedEntries(panel, tab) {
  if (isVitalSignsTab(tab)) {
    appendVitalSignTable(panel, tab);
    return;
  }

  if (isLabResultsTab(tab)) {
    appendLabResultTable(panel, tab);
    return;
  }

  const list = document.createElement("ul");
  tab.entries.forEach((entry) => {
    const item = document.createElement("li");
    item.textContent = entry;
    list.append(item);
  });
  panel.append(list);
}

function createCjeTabs(caseItem, card) {
  const tabButtons = document.createElement("div");
  tabButtons.className = "cje-tabs";
  const panels = document.createElement("div");
  panels.className = "cje-panels";

  const activateTab = (tabId) => {
    tabButtons.querySelectorAll(".cje-tab").forEach((button) => {
      const active = button.dataset.tab === tabId;
      button.classList.toggle("active", active);
      button.setAttribute("aria-selected", String(active));
    });
    panels.querySelectorAll(".cje-panel").forEach((panel) => {
      panel.hidden = panel.dataset.panel !== tabId;
    });
  };

  caseItem.tabs.forEach((tab, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "cje-tab";
    button.dataset.tab = tab.id;
    button.textContent = tab.label;
    button.setAttribute("role", "tab");
    button.setAttribute("aria-selected", String(index === 0));
    button.addEventListener("click", () => activateTab(tab.id));
    tabButtons.append(button);

    const panel = document.createElement("div");
    panel.className = "cje-panel";
    panel.dataset.panel = tab.id;
    panel.hidden = index !== 0;

    appendTabbedEntries(panel, tab);
    panels.append(panel);
  });

  card.append(tabButtons, panels);
}

function createCjeChoiceGroup(caseItem, key, legend, type, limit = 1) {
  const fieldset = document.createElement("fieldset");
  fieldset.className = "cje-choice-group";
  fieldset.dataset.group = key;

  const heading = document.createElement("legend");
  heading.textContent = legend;
  fieldset.append(heading);

  const hint = document.createElement("p");
  hint.className = "cje-choice-hint";
  hint.textContent = type === "radio" ? "Select one." : `Select ${limit}.`;
  fieldset.append(hint);

  caseItem.choices[key].forEach((choice, index) => {
    const label = document.createElement("label");
    label.className = "cje-choice";

    const input = document.createElement("input");
    input.type = type;
    input.name = `${caseItem.id}-${key}`;
    input.value = choice;

    if (type === "checkbox") {
      input.addEventListener("change", () => {
        const checked = fieldset.querySelectorAll("input:checked");
        if (checked.length > limit) {
          input.checked = false;
          const warning = fieldset.querySelector(".cje-choice-hint");
          warning.textContent = `Only select ${limit}. Choose the strongest priorities.`;
        }
      });
    }

    const text = document.createElement("span");
    text.textContent = choice;
    label.append(input, text);
    fieldset.append(label);
  });

  return fieldset;
}

function createAdvancedButterfly(item) {
  const butterfly = document.createElement("div");
  butterfly.className = "cje-butterfly advanced-butterfly";

  const header = document.createElement("div");
  header.className = "cje-butterfly-header";
  const title = document.createElement("strong");
  title.textContent = "Butterfly Answer";
  const hint = document.createElement("span");
  hint.textContent = "Choose the condition, two priority interventions, and two monitoring findings.";
  header.append(title, hint);

  const body = document.createElement("div");
  body.className = "cje-butterfly-body";
  body.setAttribute("aria-hidden", "true");
  body.append(
    Object.assign(document.createElement("span"), { className: "body-dot top" }),
    Object.assign(document.createElement("span"), { className: "body-dot middle" }),
    Object.assign(document.createElement("span"), { className: "body-dot bottom" })
  );

  butterfly.append(
    header,
    createCjeChoiceGroup(item, "interventions", "Priority interventions", "checkbox", 2),
    createCjeChoiceGroup(item, "conditions", "Most likely condition", "radio", 1),
    createCjeChoiceGroup(item, "monitoring", "Parameters to monitor", "checkbox", 2),
    body
  );
  return butterfly;
}

function selectedCjeValues(card, group) {
  return Array.from(card.querySelectorAll(`[data-group="${group}"] input:checked`))
    .map((input) => input.value);
}

function compareCjeSet(selected, correct) {
  const selectedSet = new Set(selected);
  return correct.filter((item) => selectedSet.has(item)).length;
}

function gradeCjeCase(card, caseItem) {
  const condition = selectedCjeValues(card, "conditions")[0] || "";
  const interventions = selectedCjeValues(card, "interventions");
  const monitoring = selectedCjeValues(card, "monitoring");
  const conditionScore = condition === caseItem.answer.condition ? 1 : 0;
  const interventionScore = compareCjeSet(interventions, caseItem.answer.interventions);
  const monitoringScore = compareCjeSet(monitoring, caseItem.answer.monitoring);
  const total = conditionScore + interventionScore + monitoringScore;
  const result = card.querySelector(".cje-result");

  result.hidden = false;
  result.innerHTML = "";

  const title = document.createElement("strong");
  title.textContent = `Score: ${total}/5`;
  const summary = document.createElement("p");
  const summaryText = total === 5
    ? "Strong. That is the level of synthesis I want from you."
    : total >= 3
      ? "Good start, but this is where ANI tightens the screws: partial recognition is not the same as full clinical judgment."
      : "This is exactly why we practice hard CJE items. The clues were spread across tabs, and the priority was hidden in the trend.";
  summary.textContent = summaryText;

  const answer = document.createElement("p");
  answer.textContent = `Best answer: ${caseItem.answer.condition}; interventions: ${caseItem.answer.interventions.join(" and ")}; monitor: ${caseItem.answer.monitoring.join(" and ")}.`;

  const rationale = document.createElement("div");
  rationale.className = "cje-rationale";
  [
    ["Condition rationale:", caseItem.rationale.condition],
    ["Intervention rationale:", caseItem.rationale.interventions],
    ["Monitoring rationale:", caseItem.rationale.monitoring],
    ["Trap:", caseItem.rationale.trap]
  ].forEach(([label, detail]) => {
    const line = document.createElement("p");
    const strong = document.createElement("strong");
    strong.textContent = label;
    line.append(strong, ` ${detail}`);
    rationale.append(line);
  });

  result.append(title, summary, answer, rationale);
  updateActiveExamContextGrade(
    "cje-case",
    caseItem,
    {
      condition,
      interventions,
      monitoring
    },
    {
      score: total,
      maxScore: 5,
      scoreText: `${total}/5`,
      isCorrect: total === 5,
      correct: caseItem.answer,
      missed: {
        condition: conditionScore ? [] : [caseItem.answer.condition],
        interventions: caseItem.answer.interventions.filter((item) => !interventions.includes(item)),
        monitoring: caseItem.answer.monitoring.filter((item) => !monitoring.includes(item))
      },
      incorrectSelections: {
        condition: condition && !conditionScore ? [condition] : [],
        interventions: interventions.filter((item) => !caseItem.answer.interventions.includes(item)),
        monitoring: monitoring.filter((item) => !caseItem.answer.monitoring.includes(item))
      },
      rationale: caseItem.rationale,
      feedback: summaryText
    }
  );
  scrollChatToBottom();
}

function addCjeCaseMessage(caseItem) {
  rememberQuestionFormat("butterfly");
  markActiveLearningContext("cje-case", caseItem);
  setActiveExamContext("cje-case", caseItem);
  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(cjeIntroText(caseItem));
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble cje-bubble";

  const intro = document.createElement("p");
  intro.className = "cje-intro";
  intro.textContent = cjeIntroText(caseItem);

  const card = document.createElement("section");
  card.className = "cje-card";
  card.setAttribute("aria-label", caseItem.title);

  const title = document.createElement("div");
  title.className = "cje-card-header";
  const titleText = document.createElement("strong");
  titleText.textContent = cjeDisplayTitle(caseItem);
  const titleMeta = document.createElement("span");
  titleMeta.textContent = "Chart-based clinical judgment";
  title.append(titleText, titleMeta);

  const client = document.createElement("p");
  client.className = "cje-client";
  client.textContent = caseItem.client;

  const stem = document.createElement("p");
  stem.className = "cje-stem";
  stem.textContent = caseItem.stem;

  const skillList = document.createElement("p");
  skillList.className = "cje-skills";
  skillList.textContent = `Clinical judgment targets: ${caseItem.clinicalJudgmentTargets.join(" -> ")}`;

  card.append(title, client, stem, skillList);
  createCjeTabs(caseItem, card);

  const butterfly = document.createElement("div");
  butterfly.className = "cje-butterfly";
  const butterflyHeader = document.createElement("div");
  butterflyHeader.className = "cje-butterfly-header";
  const butterflyTitle = document.createElement("strong");
  butterflyTitle.textContent = "Butterfly Answer";
  const butterflyHint = document.createElement("span");
  butterflyHint.textContent = "Choose the condition, two priority interventions, and two monitoring findings.";
  butterflyHeader.append(butterflyTitle, butterflyHint);
  const body = document.createElement("div");
  body.className = "cje-butterfly-body";
  body.setAttribute("aria-hidden", "true");
  body.append(
    Object.assign(document.createElement("span"), { className: "body-dot top" }),
    Object.assign(document.createElement("span"), { className: "body-dot middle" }),
    Object.assign(document.createElement("span"), { className: "body-dot bottom" })
  );
  butterfly.append(
    butterflyHeader,
    createCjeChoiceGroup(caseItem, "interventions", "Priority interventions", "checkbox", 2),
    createCjeChoiceGroup(caseItem, "conditions", "Most likely condition", "radio", 1),
    createCjeChoiceGroup(caseItem, "monitoring", "Parameters to monitor", "checkbox", 2),
    body
  );

  const gradeButton = document.createElement("button");
  gradeButton.type = "button";
  gradeButton.className = "cje-grade-button";
  gradeButton.textContent = "Grade Butterfly Answer";
  gradeButton.addEventListener("click", () => gradeCjeCase(card, caseItem));

  const result = document.createElement("div");
  result.className = "cje-result";
  result.hidden = true;

  card.append(butterfly, gradeButton, result);
  bubble.append(intro, card);
  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, cjeIntroText(caseItem));
  chatLog.append(article);
  scrollChatToBottom();

  const remembered = `${caseItem.title}: ${caseItem.stem}`;
  rememberConversation("assistant", remembered);
  lastAssistantText = remembered;
  speak("I built you a hard CJE butterfly case. Inspect the tabs, then choose the condition, two interventions, and two things to monitor.");
}

function wantsUnfoldingCase(input = "") {
  const lower = normalizeIntentText(input);
  return (/\b(unfolding|case\s*study|next development|evolving case)\b/i.test(lower)
    || /\b(?:six|6)\s*(?:question|questions|item|items|part|parts)\b/i.test(lower)
    || /\bcase\b.{0,50}\b(?:six|6)\b/i.test(lower)
    || /\b(?:six|6)\b.{0,50}\bcase\b/i.test(lower))
    && /\b(case|study|question|questions|item|items|generate|make|create|ask|practice|drill|give|want)\b/i.test(lower);
}

function wantsAdvancedItem(input = "") {
  if (wantsExplicitStandardQuestionFormat(input) && !wantsExplicitAdvancedQuestionFormat(input)) {
    return false;
  }

  return /\b(ordering|order question|order\/ordering|drag|draggable|priority based|prioritize patients|organize patients|which client|see first|assess first|procedure steps|sequence|trach|select all|sata|all that apply|cross out|eliminate|cloze|drop[-\s]?down|dropdown|fill[-\s]?in|sentence completion|most concern|most concerning|finding causes|bullet point|indicated|not indicated|expected findings|potential complication|highlight|time chart|hold the med|medication hold|what should.*question|question.*order|provider order|prescription.*question|what was done wrong|went wrong|improving|unchanged|deteriorating|symptom.*disease|disease.*symptom|associated symptoms|align.*disease|evd|external ventricular|csf drain|ventriculostomy|device)\b/i.test(normalizeIntentText(input));
}

function wantsAvoidStandardQuestionFormat(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(?:not|no|avoid|without|don'?t|do not|stop)\b.{0,45}\b(?:mcq|multiple choice|standard|single best|one best)\b/i.test(lower)
    || /\b(?:mcq|multiple choice|standard|single best|one best)\b.{0,45}\b(?:not|no|avoid|without|don'?t|do not|stop)\b/i.test(lower)
    || /\bnot\s+(?:the\s+)?same\s+mcq\b/i.test(lower)
    || /\bnot\s+(?:the\s+)?same\s+(?:question\s*)?(?:type|format)\b/i.test(lower);
}

function wantsExplicitStandardQuestionFormat(input = "") {
  const lower = normalizeIntentText(input);
  if (wantsAvoidStandardQuestionFormat(input)) {
    return false;
  }

  return /\b(multiple\s+choice|mcq|one[-\s]?best[-\s]?answer|single[-\s]?best[-\s]?answer)\b/i.test(lower)
    || /\bstandard\b.{0,35}\b(question|item|mcq|nclex)\b/i.test(lower)
    || /\b(question|item|mcq)\b.{0,35}\bstandard\s+format\b/i.test(lower);
}

function wantsExplicitAdvancedQuestionFormat(input = "") {
  return /\b(cje|bow[-\s]?tie|butterfly|unfolding|case\s+study|sata|select\s+all|all\s+that\s+apply|cloze|drop[-\s]?down|dropdown|fill[-\s]?in|sentence completion|ordering|order\/ordering|drag|draggable|priority\s+ordering|procedure\s+sequenc|matrix|bullet|highlight|time\s+chart|most\s+concern|provider\s+order|question.*order|what\s+was\s+done\s+wrong|improving|unchanged|deteriorating|symptom.*disease|disease.*symptom)\b/i.test(normalizeIntentText(input));
}

function activeLearningKind() {
  if (activeLearningContext?.kind) {
    return activeLearningContext.kind;
  }
  if (activeExamContext?.kind) {
    return activeExamContext.kind;
  }
  return lastQuestion ? "standard-question" : "";
}

function activeAdvancedTypeLabel() {
  const item = activeExamContext?.kind === "advanced-item" ? activeExamContext.item : null;
  if (!item?.type) {
    return "advanced NCLEX item";
  }
  if (item.type === "ordering" && item.subtype === "procedure") return "procedure ordering item";
  if (item.type === "ordering") return "priority ordering item";
  if (item.type === "sata") return "SATA item";
  if (item.type === "butterfly") return "butterfly/bow-tie item";
  if (item.type === "cloze") return "drop-down sentence-completion item";
  if (item.type === "concern") return "most-concerning chart item";
  if (item.type === "matrix") return "matrix item";
  if (item.type === "highlight") return "highlight chart item";
  return "advanced NCLEX item";
}

function wantsSameQuestionTypeFollowup(input = "") {
  const kind = activeLearningKind();
  if (!kind) {
    return false;
  }
  if (wantsAvoidStandardQuestionFormat(input) || wantsDifferentQuestionType(input)) {
    return false;
  }

  const lower = normalizeIntentText(input);
  const explicitSameFormat = /\b(same|that|this|previous|last)\b.{0,34}\b(question\s*)?(type|format|kind|style)\b/i.test(lower)
    || /\b(question\s*)?(type|format|kind|style)\b.{0,34}\b(same|that|this|previous|last)\b/i.test(lower)
    || /\b(like|similar to)\s+(this|that|the last one|the previous one)\b/i.test(lower)
    || /\banother\s+(?:random\s+)?(?:question|item|problem|one)\s+like\s+(?:this|that)\b/i.test(lower);
  const asksForAnother = /\b(another|next|new|different|fresh|random|more|same)\b.{0,70}\b(question|item|problem|one|type|format|kind|style)\b/i.test(lower)
    || /\b(question|item|problem|one)\b.{0,70}\b(another|next|new|different|fresh|random|same)\b/i.test(lower);
  const correctsPicker = /\b(i\s+just\s+told\s+(?:you|u)|i\s+said|same\s+question\s+type|same\s+type|same\s+format|not\s+the\s+picker|don'?t\s+make\s+me\s+pick)\b/i.test(lower);

  return explicitSameFormat || correctsPicker || (asksForAnother && /\b(like this|like that|same)\b/i.test(lower));
}

function wantsDifferentTopicFollowup(input = "") {
  return /\b(different topic|new topic|random topic|another topic|surprise topic|mix it up|not the same topic|different subject)\b/i.test(normalizeIntentText(input));
}

function alternateSameTypeTopic(input = "") {
  const activeTopic = activeLearningContext?.topic || currentTopic;
  const inferred = hasTopicSignal(input) ? inferTopic(input) : "";
  if (inferred && inferred !== activeTopic) {
    return inferred;
  }

  const topics = Object.keys(nclexBank).filter((topic) => topic !== activeTopic);
  const cursor = Number(localStorage.getItem("ani-same-type-topic-counter") || "0");
  localStorage.setItem("ani-same-type-topic-counter", String(cursor + 1));
  return topics[cursor % topics.length] || "Pharmacology";
}

function sameQuestionTypePrompt(input = "") {
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(currentDifficulty)] || "Hard";
  const activeTopic = activeLearningContext?.topic || currentTopic || "the active NCLEX focus";
  const topicDirection = wantsDifferentTopicFollowup(input)
    ? `Use ${alternateSameTypeTopic(input)} as the new topic. Do not use ${activeTopic}.`
    : `Stay close to ${activeLearningContext?.topic || currentTopic || "the active NCLEX focus"}.`;
  return `${input}\nSame question type as the active item. Keep ${difficulty.toLowerCase()} difficulty. ${topicDirection} Avoid repeating the active stem, scenario, and correct-answer logic.`;
}

async function makeSameQuestionTypeFollowupResponse(input = "") {
  const kind = activeLearningKind();
  const prompt = sameQuestionTypePrompt(input);

  if (kind === "standard-question") {
    const generatedQuestion = await requestGeneratedStandardQuestion(`${prompt}\nGenerate a one-best-answer NCLEX MCQ.`);
    if (generatedQuestion) {
      currentTopic = generatedQuestion.topic;
      saveDifficulty(generatedQuestion.difficulty);
      updateFocus();
      return formatQuestion(generatedQuestion, input);
    }
    return formatQuestion(nextQuestionData(prompt), input);
  }

  if (kind === "cje-case") {
    const generatedCase = await requestGeneratedCjeCase(`${prompt}\nGenerate a full tabbed CJE butterfly case.`);
    if (generatedCase) {
      currentTopic = generatedCase.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "cje-case",
        caseItem: generatedCase
      };
    }
    return makeCjeChallenge(prompt);
  }

  if (kind === "unfolding-case") {
    return makeUnfoldingCaseChallenge(prompt);
  }

  if (kind === "advanced-item") {
    const typeLabel = activeAdvancedTypeLabel();
    const generatedItem = await requestGeneratedAdvancedItem(`${prompt}\nGenerate the same advanced format as the active item: ${typeLabel}.`);
    if (generatedItem) {
      currentTopic = generatedItem.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "advanced-item",
        item: generatedItem
      };
    }
    return makeAdvancedItemChallenge(`${prompt} ${typeLabel}`);
  }

  return "";
}

function wantsSurpriseQuestionType(input = "") {
  const lower = normalizeIntentText(input);
  const asksForFormatChoice = /\b(surprise me|pick|choose|random|any|whatever|your choice|mix it up|keep me on my toes)\b.{0,70}\b(?:question\s*)?(?:type|format)\b/i.test(lower)
    || /\b(?:question\s*)?(?:type|format)\b.{0,70}\b(surprise me|pick|choose|random|any|whatever|your choice|mix it up|keep me on my toes)\b/i.test(lower)
    || /\b(any|random|whatever)\s+(?:question\s*)?(?:type|format)\b/i.test(lower);
  const asksForClinicalSubtype = /\btype\s+of\s+(?:shock|sepsis|stroke|heart failure|diabetes|diabetic|respiratory failure|arrhythmia|dysrhythmia|pneumonia|anemia|seizure)\b/i.test(lower);
  return asksForFormatChoice && !asksForClinicalSubtype;
}

function wantsRandomPracticeRequest(input = "") {
  const lower = normalizeIntentText(input);
  if (wantsSolicitedAniThought(input)) {
    return false;
  }
  if (
    wantsConceptDiagram(input)
    || wantsCjeChallenge(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsExplicitStandardQuestionFormat(input)
  ) {
    return false;
  }

  const randomCue = /\b(surprise me|random|anything|whatever you want|your choice|cook something up|keep me on my toes|hit me with anything|ask me anything|mix it up)\b/i.test(lower);
  const practiceCue = /\b(question|item|quiz|test me|practice|nclex|drill|challenge|problem)\b/i.test(lower)
    || /^(?:ani\s*)?(?:surprise me|random|anything|whatever you want|your choice|cook something up|hit me with anything|ask me anything|mix it up)[!.?]*$/i.test(lower);
  const notLifeThought = !/\b(thought|thinking|mind|fun fact|life|opinion)\b/i.test(lower);
  return randomCue && practiceCue && notLifeThought;
}

function wantsButterflyFormatCorrection(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(how|why)\s+(?:is|was)\s+(?:this|that|it)\s+(?:a\s+)?(?:butterfly|bow[-\s]?tie)\b/i.test(lower)
    || /\b(?:this|that|it)\s+(?:is|was|looks|looked)\s+(?:not|n't)\s+(?:like\s+)?(?:a\s+)?(?:butterfly|bow[-\s]?tie)\b/i.test(lower)
    || /\b(?:not|isn'?t|wasn'?t)\s+(?:a\s+)?(?:butterfly|bow[-\s]?tie)\s+(?:question|item|format|card)?\b/i.test(lower)
    || /\bwhere(?:'s|\s+is)\s+(?:the\s+)?(?:butterfly|bow[-\s]?tie)\b/i.test(lower);
}

function wantsButterflyStructureExplanation(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(how|why)\s+(?:is|was)\s+(?:this|that|it)\s+(?:a\s+)?(?:butterfly|bow[-\s]?tie)\b/i.test(lower)
    || /\bwhat\s+makes\s+(?:this|that|it)\s+(?:a\s+)?(?:butterfly|bow[-\s]?tie)\b/i.test(lower);
}

function hasActiveButterflyContext() {
  if (activeLearningContext?.kind) {
    return activeLearningContext.kind === "cje-case";
  }
  return activeExamContext?.kind === "cje-case";
}

function makeButterflyStructureExplanation() {
  const item = activeExamContext?.kind === "cje-case" ? activeExamContext.item : null;
  const title = item?.title || item?.displayTitle || "this chart item";
  return `${title} is a butterfly/bow-tie item because the answer is not one letter. The center is the most likely condition, the left side is two priority interventions, and the right side is two findings or parameters to monitor.\n\nIn other words, ANI is asking you to synthesize the chart into a clinical judgment pattern: identify what is happening, act on the priority threat, and monitor whether the client is improving or deteriorating.\n\nNCLEX essential: butterfly items test cue clustering, not memorized labels. The tabs matter because the correct condition and priorities are hidden across trends.`;
}

function makeButterflyFormatCorrectionResponse(input = "") {
  return {
    preface: "You are right. That was not the butterfly format. I corrected it below as an actual bow-tie item: condition in the center, two interventions, and two monitoring findings.",
    ...makeCjeChallenge(`${input} hard random CJE bow-tie butterfly item`)
  };
}

function wantsTestCreationSetup(input = "") {
  const lower = normalizeIntentText(input);
  const setupCue = /\b(let'?s|lets|help me|i want to|can you|could you|make|create|build|start|set up)\b.{0,70}\b(test|exam|practice set|quiz|assessment)\b/i.test(lower)
    || /\b(test|exam|practice set|quiz)\b.{0,50}\b(create|build|make|set up|plan)\b/i.test(lower);
  const hasSpecificFormat = wantsExplicitAdvancedQuestionFormat(input)
    || wantsExplicitStandardQuestionFormat(input)
    || wantsRapidFire(input)
    || wantsClassSpecificExam(input);
  return setupCue && !hasSpecificFormat;
}

function wantsDifferentQuestionType(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(change|switch|different|new|fresh|another)\b.{0,60}\b(?:question\s*)?(type|format)\b/i.test(lower)
    || /\bnot\s+(?:the\s+)?same\s+(?:question\s*)?(type|format)\b/i.test(lower)
    || /\b(?:question\s*)?(type|format)\b.{0,60}\b(change|switch|different|new|fresh)\b/i.test(lower);
}

function shouldChooseQuestionTypeForUser(input = "") {
  return wantsSurpriseQuestionType(input) || wantsDifferentQuestionType(input);
}

const mixedQuestionFormats = ["standard", "sata", "matrix", "ordering", "highlight", "cloze", "concern", "butterfly"];
const nonMcqQuestionFormats = ["sata", "matrix", "ordering", "highlight", "cloze", "concern", "butterfly"];

function requestedInteractiveQuestionFormat(input = "") {
  const lower = normalizeIntentText(input);
  if (/\b(butterfly|bow[-\s]?tie|cje|clinical judgment|ngn)\b/i.test(lower)) return "butterfly";
  if (/\b(unfolding|ongoing case|case\s*study|six|6)\b/i.test(lower) && /\b(case|question|item|study)\b/i.test(lower)) return "unfolding";
  if (/\b(select all|sata|all that apply)\b/i.test(lower)) return "sata";
  if (/\b(matrix|bullet point|improving|unchanged|deteriorating|symptom.*disease|disease.*symptom|indicated|not indicated|expected findings|potential complication)\b/i.test(lower)) return "matrix";
  if (/\b(ordering|order\/ordering|drag|draggable|sequence|procedure steps|priority ordering|organize patients|prioritize patients)\b/i.test(lower)) return "ordering";
  if (/\b(highlight|time chart|select.*row|chart row|hold the med|medication hold)\b/i.test(lower)) return "highlight";
  if (/\b(cloze|drop[-\s]?down|dropdown|fill[-\s]?in|sentence completion)\b/i.test(lower)) return "cloze";
  if (/\b(most concern|most concerning|finding causes|provider order|prescription.*question|what should.*question|what was done wrong|went wrong|question.*order)\b/i.test(lower)) return "concern";
  if (wantsExplicitStandardQuestionFormat(input)) return "standard";
  return "";
}

function chooseQuestionFormat(input = "", options = {}) {
  const allowStandard = options.allowStandard !== false;
  const requested = requestedInteractiveQuestionFormat(input);
  if (requested && (allowStandard || requested !== "standard")) {
    return requested;
  }

  const activeFormat = activeQuestionFormat();
  const recent = new Set([activeFormat, ...recentQuestionFormats.slice(0, 3)].filter(Boolean));
  let pool = (allowStandard ? mixedQuestionFormats : nonMcqQuestionFormats).filter((format) => !recent.has(format));

  if (!pool.length) {
    pool = allowStandard ? mixedQuestionFormats : nonMcqQuestionFormats;
  }

  return pool[aniRandomInt(pool.length)] || (allowStandard ? "standard" : "sata");
}

function advancedPromptForFormat(input = "", format = "") {
  const topic = inferTopic(input);
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(inferDifficulty(input, "hard"))] || "Hard";
  const directives = {
    sata: "Use a select-all-that-apply format with 5 to 7 choices and more than one correct answer.",
    matrix: "Use a bullet/matrix format. Good options include improving/unchanged/deteriorating, indicated/not indicated, expected/complication, or symptom-to-disease association.",
    ordering: "Use an ordering format. Make it draggable priority ordering or procedure sequencing with 4 to 6 items.",
    highlight: "Use a highlight/select-the-chart-row format with dated/timed rows and trend interpretation.",
    cloze: "Use a cloze/drop-down sentence-completion format with clinically meaningful answer choices.",
    concern: "Use a chart-cue format asking for the most concerning finding, unsafe action, or provider order the nurse should question."
  };

  return [
    input,
    `Requested interactive format: ${format}.`,
    directives[format] || "Use an advanced NCLEX/NGN item format.",
    `Topic focus: ${topic}. Difficulty: ${difficulty}.`,
    "Do not generate a standard MCQ or single-best-answer item for this request.",
    "Do not ask the student to choose a format. Build the item now in ANI's interactive template."
  ].join("\n");
}

function localQuestionForFormat(input = "", format = "") {
  if (format === "standard") {
    return formatQuestion(nextQuestionData(input), input);
  }
  if (format === "butterfly") {
    return makeCjeChallenge(`${input} butterfly bow-tie`);
  }
  if (format === "unfolding") {
    return makeUnfoldingCaseChallenge(input);
  }
  return makeAdvancedItemChallenge(advancedPromptForFormat(input, format));
}

async function makeRandomizedQuestionTypeResponse(input = "", options = {}) {
  const allowStandard = options.allowStandard !== false && !wantsAvoidStandardQuestionFormat(input);
  const format = chooseQuestionFormat(input, { allowStandard });

  if (format === "standard") {
    const generatedQuestion = await requestGeneratedStandardQuestion(`${input}\nUse a standard NCLEX one-best-answer MCQ. Randomize the correct answer position naturally.`);
    if (generatedQuestion) {
      currentTopic = generatedQuestion.topic;
      saveDifficulty(generatedQuestion.difficulty);
      updateFocus();
      return formatQuestion(generatedQuestion, input);
    }
    return localQuestionForFormat(input, "standard");
  }

  if (format === "butterfly") {
    const generatedCase = await requestGeneratedCjeCase(`${input}\nRequested format: butterfly/bow-tie CJE item. Do not return an MCQ.`);
    if (generatedCase) {
      currentTopic = generatedCase.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "cje-case",
        caseItem: generatedCase
      };
    }
    return localQuestionForFormat(input, "butterfly");
  }

  if (format === "unfolding") {
    return makeUnfoldingCaseChallenge(input);
  }

  const prompt = advancedPromptForFormat(input, format);
  const generatedItem = await requestGeneratedAdvancedItem(prompt);
  if (generatedItem && generatedItem.type !== "single") {
    currentTopic = generatedItem.topic;
    saveDifficulty("hard");
    updateFocus();
    return {
      type: "advanced-item",
      item: generatedItem
    };
  }

  return localQuestionForFormat(prompt, format);
}

function nextAdvancedItem(input = "") {
  const lower = normalizeIntentText(input);
  const requestedIds = [];
  if (/what should.*question|question.*order|provider order|prescription.*question/.test(lower)) requestedIds.push("adv-neuro-provider-order-question", "adv-neuro-stroke-provider-order-question");
  if (/what was done wrong|went wrong|unsafe event/.test(lower)) requestedIds.push("adv-neuro-event-highlight");
  if (/improving|unchanged|deteriorating|trend status/.test(lower)) requestedIds.push("adv-neuro-trend-status-matrix");
  if (/symptom.*disease|disease.*symptom|associated symptoms|align.*disease|symptom association/.test(lower)) requestedIds.push("adv-neuro-symptom-association", "adv-resp-cardiac-symptom-association");
  if (/cloze|drop[-\s]?down|dropdown|fill[-\s]?in|sentence completion/.test(lower)) requestedIds.push(/magnesium|preeclampsia|maternal|postpartum|ob\b|newborn/.test(lower) ? "adv-magnesium-toxicity-cloze" : "adv-clozapine-dropdown");
  if (/shock|sepsis|lactate|map|vasopressor|hypotension|perfusion/.test(lower) && /highlight|time chart|row|select.*time|select.*row/.test(lower)) requestedIds.push("adv-shock-response-highlight");
  if (/shock|sepsis|lactate|map|vasopressor|hypotension|perfusion|mottled|low urine|oliguria/.test(lower)) requestedIds.push("adv-shock-type-association", "adv-shock-response-highlight", "adv-sepsis-interventions-matrix", "adv-chart-most-concern");
  if (/evd|external ventricular|csf drain|ventriculostomy|device/.test(lower)) requestedIds.push("adv-evd-device-safety-sata", "adv-neuro-event-highlight");
  if (/trach|procedure|sequence|steps/.test(lower)) requestedIds.push("adv-trach-change-order", "adv-trach-obstruction-order");
  if (/priority|prioritize|which client|see first|assess first|organize patients/.test(lower)) requestedIds.push("adv-priority-multi-client", "adv-priority-multi-client-2");
  if (/select all|sata|all that apply|cross out|eliminate/.test(lower)) requestedIds.push(/neuro|evd|device|csf/.test(lower) ? "adv-evd-device-safety-sata" : /heparin|warfarin|anticoag|bleeding|clot|pe\b/.test(lower) ? "adv-anticoagulant-bleeding-sata" : "adv-lithium-sata", "adv-anticoagulant-bleeding-sata");
  if (/highlight|time chart|hold|metoprolol|bp|blood pressure/.test(lower)) requestedIds.push(/neuro|evd|device|csf|wrong|event/.test(lower) ? "adv-neuro-event-highlight" : "adv-beta-blocker-highlight");
  if (/most concern|most concerning|finding causes|notes|chart/.test(lower)) requestedIds.push("adv-chart-most-concern", "adv-neuro-provider-order-question");
  if (/expected|complication/.test(lower)) requestedIds.push("adv-postop-expected-complication");
  if (/indicated|not indicated|bullet|interventions/.test(lower)) requestedIds.push("adv-sepsis-interventions-matrix");

  const requested = chooseFreshItem(
    requestedIds.map((id) => advancedItemBank.find((item) => item.id === id)),
    "advanced-item"
  );

  if (requested) {
    return requested;
  }

  const topic = hasTopicSignal(input) ? inferTopic(input) : "";
  const topicMatches = topic
    ? advancedItemBank.filter((item) => item.topic === topic || (topic === "Neuro Complex Care" && /neuro|ventriculostomy|evd|csf|intracranial/i.test(`${item.topic} ${item.title} ${item.stem}`)))
    : advancedItemBank;
  const selected = chooseFreshItem(topicMatches.length ? topicMatches : advancedItemBank, "advanced-item")
    || advancedItemBank[advancedItemRotationIndex % advancedItemBank.length];
  advancedItemRotationIndex += 1;
  return selected;
}

function nextUnfoldingCase(input = "") {
  const lower = normalizeIntentText(input);
  const wantsCondensed = /\b(condensed|quick|short|mini|brief)\b/i.test(lower);
  const preferredVariant = wantsCondensed ? "condensed" : "full";
  const variantMatches = unfoldingCaseBank.filter((caseItem) => (caseItem.variant || "condensed") === preferredVariant);
  const fallbackMatches = unfoldingCaseBank.filter((caseItem) => (caseItem.variant || "condensed") !== preferredVariant);
  const searchBank = variantMatches.length ? variantMatches : unfoldingCaseBank;

  const requested = /neuro|stroke|icp|gcs|glasgow|brain|evd|ventriculostomy|complex neuro/.test(lower)
    ? searchBank.find((caseItem) => /neuro|icp|evd|ventriculostomy/i.test(`${caseItem.topic} ${caseItem.title} ${caseItem.client}`))
      || fallbackMatches.find((caseItem) => /neuro|icp|evd|ventriculostomy/i.test(`${caseItem.topic} ${caseItem.title} ${caseItem.client}`))
    : /sepsis|shock|pneumonia|complex/.test(lower)
    ? searchBank.find((caseItem) => /sepsis|shock|pneumonia/i.test(`${caseItem.topic} ${caseItem.title} ${caseItem.client}`))
      || fallbackMatches.find((caseItem) => /sepsis|shock|pneumonia/i.test(`${caseItem.topic} ${caseItem.title} ${caseItem.client}`))
    : null;

  if (requested) {
    return requested;
  }

  const selected = chooseFreshItem(searchBank, "unfolding-case") || searchBank[unfoldingCaseRotationIndex % searchBank.length];
  unfoldingCaseRotationIndex += 1;
  return selected;
}

function makeAdvancedItemChallenge(input = "") {
  const item = nextAdvancedItem(input);
  if (!item) {
    return null;
  }
  currentTopic = item.topic || currentTopic;
  saveDifficulty("hard");
  updateFocus();
  return {
    type: "advanced-item",
    item
  };
}

function makeUnfoldingCaseChallenge(input = "") {
  const caseItem = nextUnfoldingCase(input);
  if (!caseItem) {
    return null;
  }
  currentTopic = caseItem.topic || currentTopic;
  saveDifficulty("hard");
  updateFocus();
  return {
    type: "unfolding-case",
    caseItem
  };
}

function advancedPromptForSurprise(input = "", topic = currentTopic) {
  const lower = normalizeIntentText(input);
  if (/shock|sepsis|lactate|map|vasopressor|hypotension|perfusion/.test(lower)) {
    return `${topic} shock sepsis lactate MAP vasopressor highlight matrix most concern`;
  }
  if (/neuro|stroke|icp|gcs|glasgow|brain|evd|ventriculostomy|csf/.test(lower) || topic === "Neuro Complex Care") {
    return `${topic} neuro provider order trend matrix EVD device most concern`;
  }
  if (/trach|procedure|sequence|steps/.test(lower)) {
    return `${topic} trach procedure sequence ordering`;
  }
  if (/priority|prioritize|which client|see first|assess first/.test(lower)) {
    return `${topic} priority prioritize which client see first`;
  }
  return `${topic} ${input} most concern chart matrix priority`;
}

function makeSurpriseQuestionTypeChallenge(input = "") {
  const topic = inferTopic(input);
  const difficulty = inferDifficulty(input);
  currentTopic = topic;
  saveDifficulty(difficulty);
  updateFocus();

  const lower = normalizeIntentText(input);
  const forcedDifferent = wantsDifferentQuestionType(input);
  const allowStandard = !wantsAvoidStandardQuestionFormat(input)
    && !(forcedDifferent && activeQuestionFormat() === "standard");

  if (forcedDifferent || wantsSurpriseQuestionType(input) || wantsAvoidStandardQuestionFormat(input)) {
    return localQuestionForFormat(input, chooseQuestionFormat(input, { allowStandard }));
  }

  if (!forcedDifferent && /\b(unfolding|six|6)\b/i.test(lower)) {
    return makeUnfoldingCaseChallenge(input);
  }

  if (!forcedDifferent && /\b(butterfly|bow[-\s]?tie)\b/i.test(lower)) {
    return makeCjeChallenge(input);
  }

  if (!forcedDifferent && /\b(standard|multiple choice|mcq|single best|single answer)\b/i.test(lower)) {
    return formatQuestion(nextQuestionData(input), input);
  }

  if (forcedDifferent || /\b(cje|clinical judgment|ngn|case|tabs|chart|shock|sepsis|neuro|complex|priority|matrix|highlight|sata|select all|most concern|provider order|what to question|symptom)\b/i.test(lower)) {
    return makeAdvancedItemChallenge(advancedPromptForSurprise(input, topic));
  }

  const counter = Number(localStorage.getItem("ani-surprise-format-counter") || "0");
  localStorage.setItem("ani-surprise-format-counter", String(counter + 1));
  const modes = ["advanced", "standard", "cje", "unfolding"];
  const mode = modes[counter % modes.length];

  if (mode === "standard") {
    return formatQuestion(nextQuestionData(input), input);
  }
  if (mode === "cje") {
    return makeCjeChallenge(input);
  }
  if (mode === "unfolding") {
    return makeUnfoldingCaseChallenge(input);
  }
  return makeAdvancedItemChallenge(advancedPromptForSurprise(input, topic));
}

function randomPracticePlan(input = "") {
  const counter = Number(localStorage.getItem("ani-random-practice-counter") || "0");
  localStorage.setItem("ani-random-practice-counter", String(counter + 1));
  const topics = [
    "Pharmacology",
    "Neuro Complex Care",
    "Complex Care",
    "Endocrine",
    "Respiratory",
    "Cardiac",
    "Mental Health Nursing",
    "Fundamentals",
    "Pediatrics"
  ];
  const topic = topics[counter % topics.length];
  const mode = chooseQuestionFormat(input, { allowStandard: true });
  const difficulty = inferDifficulty(input, "hard");
  return { topic, mode, difficulty };
}

function randomPracticePrompt(plan, input = "") {
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(plan.difficulty)] || "Hard";
  if (plan.mode === "standard") {
    return `${input}\nSurprise the student with a ${difficulty.toLowerCase()} standard NCLEX one-best-answer MCQ. Topic: ${plan.topic}. Do not ask them to choose a format.`;
  }
  if (plan.mode === "sata") {
    return `${input}\nSurprise the student with a hard NCLEX SATA item. Topic: ${plan.topic}.`;
  }
  if (plan.mode === "cloze") {
    return `${input}\nSurprise the student with a hard NCLEX cloze/drop-down sentence completion item. Topic: ${plan.topic}.`;
  }
  if (plan.mode === "ordering") {
    return `${input}\nSurprise the student with a hard NCLEX ordering item. Topic: ${plan.topic}. Use priority or procedure sequencing, whichever fits best.`;
  }
  if (plan.mode === "butterfly") {
    return `${input}\nSurprise the student with a hard CJE butterfly/bow-tie item. Topic: ${plan.topic}.`;
  }
  if (plan.mode === "concern") {
    return `${input}\nSurprise the student with a hard chart-cue item asking for the most concerning finding, unsafe action, or order to question. Topic: ${plan.topic}.`;
  }
  if (plan.mode === "highlight") {
    return `${input}\nSurprise the student with a hard NCLEX highlight/time-chart item. Topic: ${plan.topic}.`;
  }
  return `${input}\nSurprise the student with a hard NCLEX matrix/bullet item. Topic: ${plan.topic}.`;
}

function makeRandomPracticeFallback(plan, input = "") {
  const prompt = randomPracticePrompt(plan, input);
  if (plan.mode === "standard") {
    const localTopic = nclexBank[plan.topic] ? plan.topic : currentTopic;
    return formatQuestion(generatedQuestionData(localTopic, plan.difficulty, prompt), prompt);
  }
  if (plan.mode === "butterfly") {
    return makeCjeChallenge(prompt);
  }
  return makeAdvancedItemChallenge(prompt);
}

function advancedIntroText(item) {
  return `${advancedDisplayTitle(item)}\n\nFormat: ${advancedTypeLabel(item)}. ${item.instructions || "Read the stem carefully, answer the item, then grade for a detailed rationale."}`;
}

function advancedTypeLabel(item) {
  if (item.type === "ordering" && item.subtype === "procedure") return "draggable procedure ordering";
  if (item.type === "ordering") return "draggable priority ordering";
  if (item.type === "sata") return "select all that apply";
  if (item.type === "butterfly") return "butterfly/bow-tie";
  if (item.type === "single") return "single-best-answer item";
  if (item.type === "cloze") return "drop-down sentence completion";
  if (item.type === "concern") return "chart cue, most concerning finding";
  if (item.type === "matrix") return "bullet matrix";
  if (item.type === "highlight") return "highlight/select chart row";
  return "NGN-style question";
}

function shuffledAdvancedItems(items = []) {
  return shuffledCopy(items);
}

function selectedAdvancedChoiceIds(panel) {
  return Array.from(panel.querySelectorAll("[data-choice-id] input:checked"))
    .map((input) => input.value);
}

function correctAdvancedChoiceIds(item) {
  return (item.choices || [])
    .filter((choice) => choice.correct)
    .map((choice) => choice.id);
}

function setAdvancedResult(panel, title, summary, lines = []) {
  const result = panel.querySelector(".advanced-result");
  result.hidden = false;
  result.textContent = "";

  const heading = document.createElement("strong");
  heading.textContent = title;
  const summaryText = document.createElement("p");
  summaryText.textContent = summary;
  result.append(heading, summaryText);

  lines.forEach((line) => {
    const p = document.createElement("p");
    if (typeof line === "string") {
      p.textContent = line;
    } else {
      const strong = document.createElement("strong");
      strong.textContent = line.label;
      p.append(strong, ` ${line.text}`);
    }
    result.append(p);
  });

  scrollChatToBottom();
}

function createAdvancedChoiceLabel(item, choice, inputType) {
  const label = document.createElement("label");
  label.className = "advanced-choice";
  label.dataset.choiceId = choice.id;

  const input = document.createElement("input");
  input.type = inputType;
  input.name = `${item.id}-choice`;
  input.value = choice.id;

  const text = document.createElement("span");
  text.textContent = choice.text;

  const eliminate = document.createElement("button");
  eliminate.type = "button";
  eliminate.className = "choice-eliminate";
  eliminate.textContent = "Cross out";
  eliminate.setAttribute("aria-pressed", "false");
  eliminate.addEventListener("click", (event) => {
    event.preventDefault();
    const eliminated = !label.classList.contains("is-eliminated");
    label.classList.toggle("is-eliminated", eliminated);
    eliminate.setAttribute("aria-pressed", String(eliminated));
    eliminate.textContent = eliminated ? "Restore" : "Cross out";
  });

  label.append(input, text, eliminate);
  return label;
}

function createAdvancedChoices(item, inputType = "checkbox") {
  const choices = document.createElement("div");
  choices.className = "advanced-choices";
  (item.choices || []).forEach((choice) => {
    choices.append(createAdvancedChoiceLabel(item, choice, inputType));
  });
  return choices;
}

function renderAdvancedTabs(item, panel) {
  if (!item.tabs?.length) {
    return;
  }

  const tabWrap = document.createElement("div");
  tabWrap.className = "cje-tabs advanced-tabs";
  const panels = document.createElement("div");
  panels.className = "cje-panels advanced-panels";

  const activate = (tabId) => {
    tabWrap.querySelectorAll(".cje-tab").forEach((button) => {
      const active = button.dataset.tab === tabId;
      button.classList.toggle("active", active);
      button.setAttribute("aria-selected", String(active));
    });
    panels.querySelectorAll(".cje-panel").forEach((entryPanel) => {
      entryPanel.hidden = entryPanel.dataset.panel !== tabId;
    });
  };

  item.tabs.forEach((tab, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "cje-tab";
    button.dataset.tab = tab.id;
    button.textContent = tab.label;
    button.setAttribute("aria-selected", String(index === 0));
    button.addEventListener("click", () => activate(tab.id));
    tabWrap.append(button);

    const entryPanel = document.createElement("div");
    entryPanel.className = "cje-panel";
    entryPanel.dataset.panel = tab.id;
    entryPanel.hidden = index !== 0;
    appendTabbedEntries(entryPanel, tab);
    panels.append(entryPanel);
  });

  panel.append(tabWrap, panels);
}

function moveAdvancedOrderItem(itemElement, direction) {
  const list = itemElement.parentElement;
  if (!list) return;
  if (direction < 0 && itemElement.previousElementSibling) {
    list.insertBefore(itemElement, itemElement.previousElementSibling);
  }
  if (direction > 0 && itemElement.nextElementSibling) {
    list.insertBefore(itemElement.nextElementSibling, itemElement);
  }
}

function createOrderingList(item) {
  const list = document.createElement("ol");
  list.className = "advanced-order-list";
  let dragged = null;
  let activePointerId = null;

  const moveDraggedToPoint = (event) => {
    if (!dragged || activePointerId !== event.pointerId) {
      return;
    }

    event.preventDefault();
    const previousPointerEvents = dragged.style.pointerEvents;
    dragged.style.pointerEvents = "none";
    const target = document.elementFromPoint(event.clientX, event.clientY)?.closest?.(".advanced-order-item");
    dragged.style.pointerEvents = previousPointerEvents;

    if (target && target.parentElement === list && target !== dragged) {
      const rect = target.getBoundingClientRect();
      const after = event.clientY > rect.top + rect.height / 2;
      list.insertBefore(dragged, after ? target.nextSibling : target);
    }

    const logRect = chatLog?.getBoundingClientRect?.();
    if (logRect && event.clientY < logRect.top + 70) {
      chatLog.scrollTop -= 14;
    } else if (logRect && event.clientY > logRect.bottom - 110) {
      chatLog.scrollTop += 14;
    }
  };

  const endPointerDrag = (event) => {
    if (activePointerId !== null && event.pointerId !== activePointerId) {
      return;
    }
    dragged?.classList.remove("dragging", "touch-dragging");
    dragged = null;
    activePointerId = null;
    window.removeEventListener("pointermove", moveDraggedToPoint);
    window.removeEventListener("pointerup", endPointerDrag);
    window.removeEventListener("pointercancel", endPointerDrag);
  };

  const startPointerDrag = (event, li) => {
    if (event.button && event.button !== 0) {
      return;
    }
    event.preventDefault();
    dragged = li;
    activePointerId = event.pointerId;
    li.classList.add("dragging", "touch-dragging");
    event.currentTarget.setPointerCapture?.(event.pointerId);
    window.addEventListener("pointermove", moveDraggedToPoint, { passive: false });
    window.addEventListener("pointerup", endPointerDrag);
    window.addEventListener("pointercancel", endPointerDrag);
  };

  shuffledAdvancedItems(item.items).forEach((entry) => {
    const li = document.createElement("li");
    li.className = "advanced-order-item";
    li.draggable = true;
    li.dataset.itemId = entry.id;

    const grip = document.createElement("span");
    grip.className = "drag-grip";
    grip.textContent = "::";
    grip.setAttribute("role", "button");
    grip.setAttribute("aria-label", "Drag to reorder");
    grip.title = "Drag to reorder";
    grip.addEventListener("pointerdown", (event) => startPointerDrag(event, li));

    const text = document.createElement("span");
    text.className = "order-text";
    text.textContent = entry.text;

    const controls = document.createElement("span");
    controls.className = "order-controls";
    const up = document.createElement("button");
    up.type = "button";
    up.textContent = "Up";
    up.addEventListener("click", () => moveAdvancedOrderItem(li, -1));
    const down = document.createElement("button");
    down.type = "button";
    down.textContent = "Down";
    down.addEventListener("click", () => moveAdvancedOrderItem(li, 1));
    controls.append(up, down);

    li.addEventListener("dragstart", () => {
      dragged = li;
      li.classList.add("dragging");
    });
    li.addEventListener("dragend", () => {
      li.classList.remove("dragging");
      dragged = null;
    });
    li.addEventListener("dragover", (event) => {
      event.preventDefault();
    });
    li.addEventListener("drop", (event) => {
      event.preventDefault();
      if (!dragged || dragged === li) return;
      const rect = li.getBoundingClientRect();
      const after = event.clientY > rect.top + rect.height / 2;
      list.insertBefore(dragged, after ? li.nextSibling : li);
    });

    li.append(grip, text, controls);
    list.append(li);
  });

  return list;
}

function createMatrixTable(item) {
  const wrap = document.createElement("div");
  wrap.className = "advanced-table-wrap";
  const table = document.createElement("table");
  table.className = "advanced-matrix";
  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  const blank = document.createElement("th");
  blank.textContent = "Finding or intervention";
  headRow.append(blank);
  item.categories.forEach((category) => {
    const th = document.createElement("th");
    th.textContent = category;
    headRow.append(th);
  });
  thead.append(headRow);
  table.append(thead);

  const tbody = document.createElement("tbody");
  item.rows.forEach((row) => {
    const tr = document.createElement("tr");
    tr.dataset.rowId = row.id;
    const textCell = document.createElement("td");
    textCell.dataset.label = "Finding";
    textCell.textContent = row.text;
    tr.append(textCell);
    item.categories.forEach((category) => {
      const td = document.createElement("td");
      td.dataset.label = category;
      const label = document.createElement("label");
      label.className = "matrix-radio";
      const input = document.createElement("input");
      input.type = Array.isArray(row.answer) ? "checkbox" : "radio";
      input.name = `${item.id}-${row.id}`;
      input.value = category;
      label.append(input, document.createTextNode(category));
      td.append(label);
      tr.append(td);
    });
    tbody.append(tr);
  });
  table.append(tbody);
  wrap.append(table);
  return wrap;
}

function createHighlightRows(item) {
  const wrap = document.createElement("div");
  wrap.className = "highlight-chart";
  item.rows.forEach((row) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "highlight-row";
    button.dataset.highlightId = row.id;
    const time = document.createElement("strong");
    time.textContent = row.time;
    const data = document.createElement("span");
    data.textContent = row.data;
    button.append(time, data);
    button.addEventListener("click", () => {
      wrap.querySelectorAll(".highlight-row").forEach((other) => {
        other.classList.toggle("selected", other === button);
      });
    });
    wrap.append(button);
  });
  return wrap;
}

function createClozeDropdown(item, blank) {
  const label = document.createElement("label");
  label.className = "cloze-select-label";
  const labelText = document.createElement("span");
  labelText.textContent = blank.label;
  const select = document.createElement("select");
  select.dataset.clozeId = blank.id;
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Select...";
  select.append(placeholder);
  blank.options.forEach((option) => {
    const entry = document.createElement("option");
    entry.value = option;
    entry.textContent = option;
    select.append(entry);
  });
  label.append(labelText, select);
  return label;
}

function createClozeSentence(item) {
  const wrap = document.createElement("div");
  wrap.className = "cloze-card";
  const sentence = document.createElement("p");
  sentence.className = "cloze-sentence";
  const parts = Array.isArray(item.sentenceParts) ? item.sentenceParts : [];

  if (parts.length === item.blanks.length + 1) {
    item.blanks.forEach((blank, index) => {
      sentence.append(document.createTextNode(parts[index]));
      sentence.append(createClozeDropdown(item, blank));
    });
    sentence.append(document.createTextNode(parts[parts.length - 1]));
    wrap.append(sentence);
    return wrap;
  }

  const fallback = document.createElement("div");
  fallback.className = "cloze-fallback";
  item.blanks.forEach((blank) => {
    fallback.append(createClozeDropdown(item, blank));
  });
  wrap.append(fallback);
  return wrap;
}

function renderAdvancedItemBody(item, panel) {
  if (item.tabs?.length) {
    renderAdvancedTabs(item, panel);
  }

  if (item.type === "ordering") {
    panel.append(createOrderingList(item));
    return;
  }

  if (item.type === "butterfly") {
    panel.append(createAdvancedButterfly(item));
    return;
  }

  if (item.type === "sata") {
    panel.append(createAdvancedChoices(item, "checkbox"));
    return;
  }

  if (item.type === "single" || item.type === "concern") {
    panel.append(createAdvancedChoices(item, "radio"));
    return;
  }

  if (item.type === "matrix") {
    panel.append(createMatrixTable(item));
    return;
  }

  if (item.type === "highlight") {
    panel.append(createHighlightRows(item));
    return;
  }

  if (item.type === "cloze") {
    panel.append(createClozeSentence(item));
  }
}

function gradeOrderingItem(panel, item) {
  const selected = Array.from(panel.querySelectorAll(".advanced-order-item")).map((li) => li.dataset.itemId);
  const correct = item.answer || [];
  const score = selected.filter((id, index) => id === correct[index]).length;
  const orderText = correct
    .map((id, index) => {
      const entry = item.items.find((candidate) => candidate.id === id);
      return `${index + 1}. ${entry?.text || id}`;
    })
    .join(" ");
  const lines = [
    { label: "Correct order:", text: orderText },
    { label: "Rationale:", text: item.rationale },
    ...correct.map((id, index) => {
      const entry = item.items.find((candidate) => candidate.id === id);
      return {
        label: `${index + 1}.`,
        text: entry ? entry.rationale : id
      };
    })
  ];
  setAdvancedResult(panel, `Score: ${score}/${correct.length}`, score === correct.length ? "Strong sequencing." : "Good attempt. Sequence questions punish small safety-order errors, so walk the physiology step by step.", lines);
  return {
    score,
    maxScore: correct.length,
    scoreText: `${score}/${correct.length}`,
    isCorrect: score === correct.length,
    selection: { order: selected },
    correct: { order: correct },
    rationale: item.rationale,
    details: lines
  };
}

function gradeChoiceItem(panel, item) {
  const selected = selectedAdvancedChoiceIds(panel);
  const correct = correctAdvancedChoiceIds(item);
  const wrongSelected = selected.filter((id) => !correct.includes(id));
  const correctSelected = selected.filter((id) => correct.includes(id));
  const score = item.type === "sata"
    ? Math.max(0, correctSelected.length - wrongSelected.length)
    : (selected[0] && correct.includes(selected[0]) ? 1 : 0);
  const denominator = item.type === "sata" ? correct.length : 1;
  const choiceLines = item.choices.map((choice) => ({
    label: choice.correct ? "Correct:" : "Eliminate:",
    text: `${choice.text} ${choice.rationale}`
  }));
  setAdvancedResult(
    panel,
    `Score: ${score}/${denominator}`,
    score === denominator ? "Excellent. You selected the safest answer pattern." : "Not fully there yet. Read the wrong choices as traps, not just distractors.",
    [
      { label: "Best answer pattern:", text: correct.map((id) => item.choices.find((choice) => choice.id === id)?.text || id).join("; ") },
      { label: "Overall rationale:", text: item.rationale },
      ...choiceLines
    ]
  );
  return {
    score,
    maxScore: denominator,
    scoreText: `${score}/${denominator}`,
    isCorrect: score === denominator,
    selection: { selectedChoiceIds: selected },
    correct: { correctChoiceIds: correct },
    missed: correct.filter((id) => !selected.includes(id)),
    incorrectSelections: wrongSelected,
    rationale: item.rationale,
    details: choiceLines
  };
}

function gradeMatrixItem(panel, item) {
  let score = 0;
  const lines = [];
  const selectedRows = {};
  const correctRows = {};
  item.rows.forEach((row) => {
    const selected = Array.from(panel.querySelectorAll(`tr[data-row-id="${row.id}"] input:checked`))
      .map((input) => input.value);
    const correct = Array.isArray(row.answer) ? row.answer : [row.answer];
    selectedRows[row.id] = selected;
    correctRows[row.id] = correct;
    const selectedSet = new Set(selected);
    const correctSet = new Set(correct);
    const rowCorrect = selected.length === correct.length
      && selected.every((value) => correctSet.has(value))
      && correct.every((value) => selectedSet.has(value));
    if (rowCorrect) {
      score += 1;
    }
    lines.push({
      label: `${correct.join(" + ")}:`,
      text: `${row.text} ${row.rationale}`
    });
  });
  setAdvancedResult(
    panel,
    `Score: ${score}/${item.rows.length}`,
    score === item.rows.length ? "Clean sorting. That is the kind of discrimination these items test." : "Good reps. The point is sorting each bullet by risk, not memorizing the table.",
    [
      { label: "Overall rationale:", text: item.rationale },
      ...lines
    ]
  );
  return {
    score,
    maxScore: item.rows.length,
    scoreText: `${score}/${item.rows.length}`,
    isCorrect: score === item.rows.length,
    selection: { rows: selectedRows },
    correct: { rows: correctRows },
    rationale: item.rationale,
    details: lines
  };
}

function gradeHighlightItem(panel, item) {
  const selected = Array.from(panel.querySelectorAll(".highlight-row.selected")).map((row) => row.dataset.highlightId);
  const correct = item.answer || [];
  const score = selected.length === correct.length && selected.every((id) => correct.includes(id)) ? 1 : 0;
  const correctRows = correct.map((id) => item.rows.find((row) => row.id === id)).filter(Boolean);
  const lines = [
    { label: "Correct selection:", text: correctRows.map((row) => `${row.time}: ${row.data}`).join(" ") },
    { label: "Overall rationale:", text: item.rationale },
    ...item.rows.map((row) => ({
      label: `${row.time}:`,
      text: row.rationale
    }))
  ];
  setAdvancedResult(panel, `Score: ${score}/1`, score ? "Exactly. You used the trend and the medication effect." : "Not quite. Highlight items often hide the answer in a trend.", lines);
  return {
    score,
    maxScore: 1,
    scoreText: `${score}/1`,
    isCorrect: score === 1,
    selection: { selectedRowIds: selected },
    correct: { rowIds: correct },
    rationale: item.rationale,
    details: lines
  };
}

function gradeClozeItem(panel, item) {
  let score = 0;
  const selections = {};
  const correct = {};
  const lines = item.blanks.map((blank) => {
    const value = panel.querySelector(`[data-cloze-id="${blank.id}"]`)?.value || "";
    selections[blank.id] = value;
    correct[blank.id] = blank.answer;
    if (value === blank.answer) {
      score += 1;
    }
    return {
      label: `${blank.label}:`,
      text: `Best answer: ${blank.answer}. ${blank.rationale}`
    };
  });

  setAdvancedResult(
    panel,
    `Score: ${score}/${item.blanks.length}`,
    score === item.blanks.length ? "Clean sentence logic." : "Good attempt. These items test whether the whole clinical sentence makes sense.",
    [
      { label: "Overall rationale:", text: item.rationale },
      ...lines
    ]
  );
  return {
    score,
    maxScore: item.blanks.length,
    scoreText: `${score}/${item.blanks.length}`,
    isCorrect: score === item.blanks.length,
    selection: { blanks: selections },
    correct: { blanks: correct },
    rationale: item.rationale,
    details: lines
  };
}

function gradeButterflyItem(panel, item) {
  const condition = selectedCjeValues(panel, "conditions")[0] || "";
  const interventions = selectedCjeValues(panel, "interventions");
  const monitoring = selectedCjeValues(panel, "monitoring");
  const conditionScore = condition === item.answer.condition ? 1 : 0;
  const interventionScore = compareCjeSet(interventions, item.answer.interventions || []);
  const monitoringScore = compareCjeSet(monitoring, item.answer.monitoring || []);
  const total = conditionScore + interventionScore + monitoringScore;
  const maxScore = 1 + (item.answer.interventions || []).length + (item.answer.monitoring || []).length;
  const rationale = item.rationale || {};

  setAdvancedResult(
    panel,
    `Score: ${total}/${maxScore}`,
    total === maxScore
      ? "Strong bow-tie reasoning. You matched the condition, interventions, and monitoring priorities."
      : "Good attempt. Butterfly items test whether the whole clinical picture matches the action plan.",
    [
      { label: "Best condition:", text: item.answer.condition },
      { label: "Best interventions:", text: (item.answer.interventions || []).join("; ") },
      { label: "Best monitoring:", text: (item.answer.monitoring || []).join("; ") },
      { label: "Condition rationale:", text: rationale.condition || item.rationale || "" },
      { label: "Intervention rationale:", text: rationale.interventions || "" },
      { label: "Monitoring rationale:", text: rationale.monitoring || "" },
      { label: "Trap:", text: rationale.trap || "The trap is treating one chart cue in isolation instead of clustering the trend." }
    ]
  );

  return {
    score: total,
    maxScore,
    scoreText: `${total}/${maxScore}`,
    isCorrect: total === maxScore,
    selection: {
      condition,
      interventions,
      monitoring
    },
    correct: item.answer,
    missed: {
      condition: conditionScore ? [] : [item.answer.condition],
      interventions: (item.answer.interventions || []).filter((choice) => !interventions.includes(choice)),
      monitoring: (item.answer.monitoring || []).filter((choice) => !monitoring.includes(choice))
    },
    incorrectSelections: {
      condition: condition && !conditionScore ? [condition] : [],
      interventions: interventions.filter((choice) => !(item.answer.interventions || []).includes(choice)),
      monitoring: monitoring.filter((choice) => !(item.answer.monitoring || []).includes(choice))
    },
    rationale,
    details: []
  };
}

function gradeAdvancedItem(panel, item, options = {}) {
  let grading;
  if (item.type === "ordering") {
    grading = gradeOrderingItem(panel, item);
  } else if (item.type === "butterfly") {
    grading = gradeButterflyItem(panel, item);
  } else if (item.type === "matrix") {
    grading = gradeMatrixItem(panel, item);
  } else if (item.type === "highlight") {
    grading = gradeHighlightItem(panel, item);
  } else if (item.type === "cloze") {
    grading = gradeClozeItem(panel, item);
  } else {
    grading = gradeChoiceItem(panel, item);
  }
  updateActiveExamContextGrade(
    options.kind || "advanced-item",
    options.parentCase || item,
    grading.selection,
    {
      ...grading,
      itemType: item.type,
      itemTitle: item.title || item.stem || "",
      activeStepTitle: options.stepTitle || item.title || ""
    },
    {
      activeStepIndex: options.activeStepIndex
    }
  );
  return grading;
}

function createAdvancedCard(item) {
  const card = document.createElement("section");
  card.className = "advanced-card";
  card.setAttribute("aria-label", item.title);

  const header = document.createElement("div");
  header.className = "advanced-card-header";
  const title = document.createElement("strong");
  title.textContent = advancedDisplayTitle(item);
  const meta = document.createElement("span");
  meta.textContent = advancedTypeLabel(item);
  header.append(title, meta);

  const stem = document.createElement("p");
  stem.className = "advanced-stem";
  stem.textContent = item.stem;

  card.append(header, stem);
  if (item.instructions) {
    const instructions = document.createElement("p");
    instructions.className = "advanced-instructions";
    instructions.textContent = item.instructions;
    card.append(instructions);
  }

  renderAdvancedItemBody(item, card);

  const gradeButton = document.createElement("button");
  gradeButton.type = "button";
  gradeButton.className = "advanced-grade-button";
  gradeButton.textContent = "Grade and Explain";
  gradeButton.addEventListener("click", () => gradeAdvancedItem(card, item));

  const result = document.createElement("div");
  result.className = "advanced-result";
  result.hidden = true;

  card.append(gradeButton, result);
  return card;
}

function addAdvancedItemMessage(item) {
  rememberQuestionFormat(item.type || "advanced");
  markActiveLearningContext("advanced-item", item);
  setActiveExamContext("advanced-item", item);
  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(advancedIntroText(item));
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble advanced-bubble";
  const intro = document.createElement("p");
  intro.className = "advanced-intro";
  intro.textContent = advancedIntroText(item);
  bubble.append(intro, createAdvancedCard(item));

  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, advancedIntroText(item));
  chatLog.append(article);
  scrollChatToBottom();

  const remembered = `${item.title}: ${item.stem}`;
  rememberConversation("assistant", remembered);
  lastAssistantText = remembered;
  speak(`I built you a hard ${advancedTypeLabel(item)} item. Answer it, then I will grade and explain the traps.`);
}

function appendUnfoldingTabEntry(tabMap, tab = {}) {
  const id = safeText(tab.id, slugify(tab.label || "chart")).toLowerCase();
  const label = safeText(tab.label, id);
  if (!tabMap.has(id)) {
    tabMap.set(id, {
      id,
      label,
      entries: []
    });
  }

  const target = tabMap.get(id);
  (tab.entries || []).forEach((entry) => {
    if (entry && !target.entries.includes(entry)) {
      target.entries.push(entry);
    }
  });
}

function accumulatedUnfoldingTabs(caseItem, stepIndex) {
  const tabMap = new Map();
  (caseItem.tabs || caseItem.initialTabs || []).forEach((tab) => appendUnfoldingTabEntry(tabMap, tab));
  caseItem.steps.slice(0, stepIndex + 1).forEach((step) => {
    (step.chartTabs || step.tabs || []).forEach((tab) => appendUnfoldingTabEntry(tabMap, tab));
  });
  return Array.from(tabMap.values()).filter((tab) => tab.entries.length);
}

function getUnfoldingState(card) {
  if (!card._unfoldingState) {
    card._unfoldingState = {
      maxVisitedStepIndex: 0,
      stepStates: {}
    };
  }
  return card._unfoldingState;
}

function createUnfoldingChart(caseItem, stepIndex) {
  const chart = document.createElement("div");
  chart.className = "unfolding-chart";
  const title = document.createElement("strong");
  title.textContent = caseItem.variant === "full" ? "Client chart through this development" : "Client chart so far";
  chart.append(title);

  const client = document.createElement("p");
  client.textContent = caseItem.client;
  chart.append(client);

  const tabs = accumulatedUnfoldingTabs(caseItem, stepIndex);
  if (tabs.length) {
    const tabArea = document.createElement("div");
    tabArea.className = "unfolding-chart-tabs";
    renderAdvancedTabs({ tabs }, tabArea);
    chart.append(tabArea);
    return chart;
  }

  const list = document.createElement("ol");
  caseItem.steps.slice(0, stepIndex + 1).forEach((step) => {
    const li = document.createElement("li");
    li.textContent = step.update;
    list.append(li);
  });
  chart.append(list);
  return chart;
}

function createUnfoldingProgress(caseItem, card, stepIndex) {
  const progress = document.createElement("div");
  progress.className = "unfolding-progress";
  const state = getUnfoldingState(card);
  caseItem.steps.forEach((step, index) => {
    const marker = document.createElement("button");
    marker.type = "button";
    marker.className = "unfolding-progress-step";
    const stepState = state.stepStates[index];
    const canVisit = index <= state.maxVisitedStepIndex;
    marker.classList.toggle("complete", Boolean(stepState?.graded));
    marker.classList.toggle("visited", canVisit);
    marker.classList.toggle("active", index === stepIndex);
    marker.textContent = String(index + 1);
    marker.title = step.title;
    marker.setAttribute("aria-label", `Go to ${step.title}`);
    marker.disabled = !canVisit;
    marker.addEventListener("click", () => {
      if (index === stepIndex || !canVisit) {
        return;
      }
      captureUnfoldingStepState(caseItem, card, stepIndex);
      renderUnfoldingStep(caseItem, card, index);
    });
    progress.append(marker);
  });
  return progress;
}

function unfoldingStepItem(caseItem, stepIndex) {
  const step = caseItem.steps[stepIndex] || {};
  return {
    ...step,
    id: `${caseItem.id}-${stepIndex}`,
    topic: caseItem.topic,
    difficulty: caseItem.difficulty
  };
}

function collectAdvancedSelection(panel, item = {}) {
  if (item.type === "ordering") {
    return {
      order: Array.from(panel.querySelectorAll(".advanced-order-item")).map((li) => li.dataset.itemId)
    };
  }

  if (item.type === "matrix") {
    const rows = {};
    (item.rows || []).forEach((row) => {
      rows[row.id] = Array.from(panel.querySelectorAll(`tr[data-row-id="${row.id}"] input:checked`))
        .map((input) => input.value);
    });
    return { rows };
  }

  if (item.type === "highlight") {
    return {
      selectedRowIds: Array.from(panel.querySelectorAll(".highlight-row.selected")).map((row) => row.dataset.highlightId)
    };
  }

  if (item.type === "cloze") {
    const blanks = {};
    (item.blanks || []).forEach((blank) => {
      blanks[blank.id] = panel.querySelector(`[data-cloze-id="${blank.id}"]`)?.value || "";
    });
    return { blanks };
  }

  if (item.type === "butterfly") {
    return {
      condition: selectedCjeValues(panel, "conditions")[0] || "",
      interventions: selectedCjeValues(panel, "interventions"),
      monitoring: selectedCjeValues(panel, "monitoring")
    };
  }

  return {
    selectedChoiceIds: Array.from(panel.querySelectorAll(".advanced-choice input:checked")).map((input) => input.value)
  };
}

function applyAdvancedSelection(panel, item = {}, selection = {}) {
  if (!selection) {
    return;
  }

  if (item.type === "ordering" && Array.isArray(selection.order)) {
    const list = panel.querySelector(".advanced-order-list");
    if (!list) return;
    const byId = new Map(Array.from(list.querySelectorAll(".advanced-order-item")).map((li) => [li.dataset.itemId, li]));
    selection.order.forEach((id) => {
      const li = byId.get(id);
      if (li) {
        list.append(li);
      }
    });
    Array.from(byId.values()).forEach((li) => {
      if (!selection.order.includes(li.dataset.itemId)) {
        list.append(li);
      }
    });
    return;
  }

  if (item.type === "matrix" && selection.rows) {
    Object.entries(selection.rows).forEach(([rowId, values]) => {
      Array.from(panel.querySelectorAll(`tr[data-row-id="${rowId}"] input`)).forEach((input) => {
        input.checked = values.includes(input.value);
      });
    });
    return;
  }

  if (item.type === "highlight" && Array.isArray(selection.selectedRowIds)) {
    panel.querySelectorAll(".highlight-row").forEach((row) => {
      row.classList.toggle("selected", selection.selectedRowIds.includes(row.dataset.highlightId));
    });
    return;
  }

  if (item.type === "cloze" && selection.blanks) {
    Object.entries(selection.blanks).forEach(([blankId, value]) => {
      const select = panel.querySelector(`[data-cloze-id="${blankId}"]`);
      if (select) {
        select.value = value;
      }
    });
    return;
  }

  if (item.type === "butterfly") {
    const selected = {
      conditions: selection.condition ? [selection.condition] : [],
      interventions: selection.interventions || [],
      monitoring: selection.monitoring || []
    };
    Object.entries(selected).forEach(([group, values]) => {
      panel.querySelectorAll(`[data-group="${group}"] input`).forEach((input) => {
        input.checked = values.includes(input.value);
      });
    });
    return;
  }

  if (Array.isArray(selection.selectedChoiceIds)) {
    panel.querySelectorAll(".advanced-choice input").forEach((input) => {
      input.checked = selection.selectedChoiceIds.includes(input.value);
    });
  }
}

function captureUnfoldingStepState(caseItem, card, stepIndex) {
  const state = getUnfoldingState(card);
  const item = unfoldingStepItem(caseItem, stepIndex);
  const result = card.querySelector(".advanced-result");
  state.stepStates[stepIndex] = {
    selection: collectAdvancedSelection(card, item),
    resultHtml: result?.innerHTML || "",
    resultHidden: result ? result.hidden : true,
    graded: Boolean(result && !result.hidden && result.innerHTML.trim()),
    showNext: Boolean(card.querySelector(".unfolding-next-button"))
  };
  state.maxVisitedStepIndex = Math.max(state.maxVisitedStepIndex, stepIndex);
}

function restoreUnfoldingStepState(caseItem, card, stepIndex) {
  const state = getUnfoldingState(card);
  const stepState = state.stepStates[stepIndex];
  if (!stepState) {
    return;
  }

  const item = unfoldingStepItem(caseItem, stepIndex);
  applyAdvancedSelection(card, item, stepState.selection);
  const result = card.querySelector(".advanced-result");
  if (result && stepState.resultHtml) {
    result.innerHTML = stepState.resultHtml;
    result.hidden = stepState.resultHidden;
  }
}

function appendUnfoldingNextButton(caseItem, card, stepIndex) {
  if (stepIndex >= caseItem.steps.length - 1 || card.querySelector(".unfolding-next-button")) {
    return;
  }

  const nextButton = document.createElement("button");
  nextButton.type = "button";
  nextButton.className = "unfolding-next-button";
  nextButton.textContent = "Reveal Next Development";
  nextButton.addEventListener("click", () => {
    captureUnfoldingStepState(caseItem, card, stepIndex);
    const state = getUnfoldingState(card);
    state.maxVisitedStepIndex = Math.max(state.maxVisitedStepIndex, stepIndex + 1);
    renderUnfoldingStep(caseItem, card, stepIndex + 1);
  });
  card.append(nextButton);
}

function markUnfoldingProgressComplete(card, stepIndex) {
  const marker = Array.from(card.querySelectorAll(".unfolding-progress-step"))[stepIndex];
  if (marker) {
    marker.classList.add("complete", "visited");
  }
}

function renderUnfoldingStep(caseItem, card, stepIndex = 0) {
  card.dataset.stepIndex = String(stepIndex);
  card.textContent = "";
  const state = getUnfoldingState(card);
  state.maxVisitedStepIndex = Math.max(state.maxVisitedStepIndex, stepIndex);
  setActiveExamContext("unfolding-case", caseItem, "awaiting-answer", { activeStepIndex: stepIndex });

  const header = document.createElement("div");
  header.className = "advanced-card-header";
  const title = document.createElement("strong");
  title.textContent = unfoldingDisplayTitle(caseItem);
  const meta = document.createElement("span");
  meta.textContent = `${stepIndex + 1} of ${caseItem.steps.length}`;
  header.append(title, meta);
  card.append(header, createUnfoldingProgress(caseItem, card, stepIndex), createUnfoldingChart(caseItem, stepIndex));

  const step = caseItem.steps[stepIndex];
  const stepTitle = document.createElement("h3");
  stepTitle.className = "unfolding-step-title";
  stepTitle.textContent = step.title;
  const stem = document.createElement("p");
  stem.className = "advanced-stem";
  stem.textContent = step.stem;
  card.append(stepTitle, stem);
  const stepItem = unfoldingStepItem(caseItem, stepIndex);
  renderAdvancedItemBody(stepItem, card);

  const gradeButton = document.createElement("button");
  gradeButton.type = "button";
  gradeButton.className = "advanced-grade-button";
  gradeButton.textContent = stepIndex === caseItem.steps.length - 1 ? "Grade Final Step" : "Grade This Step";
  gradeButton.addEventListener("click", () => {
    gradeAdvancedItem(card, stepItem, {
      kind: "unfolding-case",
      parentCase: caseItem,
      activeStepIndex: stepIndex,
      stepTitle: step.title
    });
    captureUnfoldingStepState(caseItem, card, stepIndex);
    markUnfoldingProgressComplete(card, stepIndex);
    appendUnfoldingNextButton(caseItem, card, stepIndex);
  });

  const result = document.createElement("div");
  result.className = "advanced-result";
  result.hidden = true;
  card.append(gradeButton, result);
  restoreUnfoldingStepState(caseItem, card, stepIndex);

  const restored = getUnfoldingState(card).stepStates[stepIndex];
  if (restored?.showNext || restored?.graded) {
    appendUnfoldingNextButton(caseItem, card, stepIndex);
  }
}

function addUnfoldingCaseMessage(caseItem) {
  rememberQuestionFormat("unfolding");
  markActiveLearningContext("unfolding-case", caseItem);
  setActiveExamContext("unfolding-case", caseItem, "awaiting-answer", { activeStepIndex: 0 });
  const article = document.createElement("article");
  article.className = "message assistant";
  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";
  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(unfoldingDisplayTitle(caseItem));
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble advanced-bubble";
  const intro = document.createElement("p");
  intro.className = "advanced-intro";
  intro.textContent = unfoldingIntroText(caseItem);
  const card = document.createElement("section");
  card.className = "advanced-card unfolding-card";
  renderUnfoldingStep(caseItem, card, 0);
  bubble.append(intro, card);
  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, unfoldingIntroText(caseItem));
  chatLog.append(article);
  scrollChatToBottom();

  const remembered = `${caseItem.title}: ${caseItem.client}`;
  rememberConversation("assistant", remembered);
  lastAssistantText = remembered;
  speak("I built you a six question ongoing clinical judgment case study. Start with question one, then reveal the next development after each rationale.");
}

function safeText(value = "", fallback = "") {
  let source = value;
  if (source && typeof source === "object") {
    source = source.text ?? source.label ?? source.value ?? source.name ?? source.title ?? "";
  }
  const text = String(source || "").trim();
  return text || fallback;
}

function sanitizeMedicalReferenceText(value = "") {
  return safeText(value)
    .replace(/\bANI's high-yield NCLEX study tier from NLM RxTerms\/RxNorm names plus nursing class templates\.?/gi, "High-yield NCLEX medication reference.")
    .replace(/\bANI high-yield NCLEX Essentials tier from NLM RxTerms\/RxNorm names plus nursing class templates\.?/gi, "High-yield NCLEX medication reference.")
    .replace(/\bANI recognizes this medication name offline, but the exact treatment use is not fully curated in this long-tail entry yet\.?/gi, "Confirm the exact labeled indication, dose, route, contraindications, and population-specific cautions in current prescribing information.")
    .replace(/\bANI recognizes this medication name offline\.?/gi, "Use current prescribing information for exact indications and safety details.")
    .replace(/\bANI can recognize this medication name offline\.?/gi, "Use current prescribing information for exact indications and safety details.")
    .replace(/\bANI can recognize the medication name, connect it to likely class patterns when possible, and screen for nursing safety themes\.?/gi, "Review indication, class, major interactions, contraindications, and nursing safety checks before administration.")
    .replace(/\bExpanded medication reference entry for name recognition, class matching, interaction screening, and nursing safety checks\.?/gi, "Medication reference for class, interaction, and nursing safety review.")
    .replace(/\bExpanded medication reference entry generated from NLM RxTerms\/RxNorm names\.?\s*Drug-specific label warnings should be verified in DailyMed\/current prescribing information\.?/gi, "Medication reference. Verify current prescribing information before clinical use.")
    .replace(/\bDrug-specific boxed warning status is not stored in this medication reference\.?/gi, "No drug-specific boxed warning is listed here.")
    .replace(/\bExact boxed-warning status is not listed for this medication reference\.?/gi, "No drug-specific boxed warning is listed here.")
    .replace(/\bExact boxed-warning status is not encoded for this expanded reference entry\.?/gi, "No drug-specific boxed warning is listed here.")
    .replace(/\bRECOGNITION ONLY\b/gi, "Medication reference")
    .replace(/\bsafety issue ANI lists\b/gi, "listed safety issue")
    .replace(/\bUse ANI's numbers\b/gi, "Use these numbers")
    .replace(/\bUse ANI's number\b/gi, "Use this number")
    .replace(/\bUse ANI's values\b/gi, "Use these values")
    .replace(/\bANI's offline encyclopedia\b/gi, "the clinical reference")
    .replace(/\bANI offline encyclopedia\b/gi, "clinical reference")
    .replace(/\bANI's offline\b/gi, "the clinical reference")
    .replace(/\boffline encyclopedia\b/gi, "clinical reference")
    .replace(/\boffline index entry\b/gi, "medication reference")
    .replace(/\bLong-tail offline medication index entry\b/gi, "Medication reference")
    .replace(/\bExpanded offline index entry\b/gi, "Medication reference")
    .replace(/\bexpanded-index entry\b/gi, "medication reference")
    .replace(/\bexpanded reference entry\b/gi, "medication reference")
    .replace(/\bexpanded medication reference entry\b/gi, "medication reference")
    .replace(/\boffline index\b/gi, "medication reference")
    .replace(/\boffline database\b/gi, "clinical reference")
    .replace(/\boffline mode\b/gi, "reference mode")
    .replace(/\bnot encoded\b/gi, "not listed")
    .replace(/\bencoded\b/gi, "listed")
    .replace(/\bfrom ANI\b/gi, "from the reference")
    .replace(/\bANI\b/gi, "the reference")
    .replace(/\s+/g, " ")
    .trim();
}

function toShortTextArray(value, fallback = [], limit = 8) {
  const source = Array.isArray(value)
    ? value
    : typeof value === "string"
      ? value.split(/\n+/)
      : fallback;
  return source
    .map((item) => safeText(item))
    .filter(Boolean)
    .slice(0, limit);
}

function slugify(value = "cje-case") {
  const slug = safeText(value, "cje-case")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 48);
  return slug || "cje-case";
}

function uniqueWithCorrectFirst(options = [], correct = [], limit = 8) {
  const merged = [...correct, ...options];
  const seen = new Set();
  const unique = merged
    .map((item) => safeText(item))
    .filter((item) => {
      const key = item.toLowerCase();
      if (!item || seen.has(key)) {
        return false;
      }
      seen.add(key);
      return true;
    })
    .slice(0, limit);
  return shuffledCopy(unique);
}

function fillChoices(options = [], fillers = [], limit = 8) {
  return uniqueWithCorrectFirst(options, fillers, limit);
}

function normalizeGeneratedCjeCase(rawCase, input = "") {
  if (!rawCase || typeof rawCase !== "object") {
    return null;
  }

  const answer = rawCase.answer || {};
  const conditionAnswer = safeText(answer.condition);
  const interventionAnswers = toShortTextArray(answer.interventions, [], 2);
  const monitoringAnswers = toShortTextArray(answer.monitoring, [], 2);

  if (!conditionAnswer || interventionAnswers.length !== 2 || monitoringAnswers.length !== 2) {
    return null;
  }

  const rawChoices = rawCase.choices || {};
  const conditions = fillChoices(rawChoices.conditions, [
    conditionAnswer,
    "Hypovolemic shock",
    "Cardiogenic shock",
    "Obstructive shock",
    "Distributive shock",
    "Septic shock",
    "Neurogenic shock"
  ], 6);
  const interventions = fillChoices(rawChoices.interventions, [
    ...interventionAnswers,
    "Notify the provider or rapid response team for immediate deterioration.",
    "Prepare to administer ordered oxygen, fluids, blood products, or vasoactive therapy based on the suspected shock state.",
    "Reassess airway, breathing, circulation, mental status, skin perfusion, and urine output.",
    "Hold a medication or intervention that could worsen hypotension, bleeding, or oxygenation."
  ], 8);
  const monitoring = fillChoices(rawChoices.monitoring, [
    ...monitoringAnswers,
    "Mean arterial pressure and blood pressure trend",
    "Urine output",
    "Mental status",
    "Serum lactate trend",
    "Oxygen saturation and work of breathing",
    "Skin temperature, color, and capillary refill"
  ], 8);

  if (conditions.length < 3 || interventions.length < 4 || monitoring.length < 4) {
    return null;
  }

  const rawTabs = Array.isArray(rawCase.tabs) ? rawCase.tabs : [];
  const normalizedTabs = cjeRequiredTabLabels.map((label, index) => {
    const match = rawTabs.find((tab) => safeText(tab?.label).toLowerCase() === label.toLowerCase())
      || rawTabs[index];
    const entries = toShortTextArray(match?.entries, [`${label}: No additional entry documented.`], 8);

    return {
      id: slugify(match?.id || label),
      label,
      entries
    };
  });

  if (normalizedTabs.some((tab) => tab.entries.length < 1)) {
    return null;
  }

  const topic = safeText(rawCase.topic, inferTopic(input) || "Complex Care");
  const title = safeText(rawCase.title, `CJE Challenge: ${topic}`);
  const clinicalJudgmentTargets = toShortTextArray(
    rawCase.clinicalJudgmentTargets,
    ["Recognize cues", "Analyze cues", "Prioritize hypotheses", "Generate solutions", "Take action", "Evaluate outcomes"],
    6
  );
  const rationale = rawCase.rationale || {};

  return {
    id: `generated-${slugify(rawCase.id || title)}-${Date.now()}`,
    title,
    displayTitle: "Client Chart Review",
    topic,
    difficulty: "Hard",
    client: safeText(rawCase.client, "A client presents with complex, unfolding clinical cues across the chart."),
    stem: safeText(
      rawCase.stem,
      "Complete the butterfly answer. Select the condition the client is most likely experiencing, two interventions the nurse should take, and two parameters the nurse should monitor most closely."
    ),
    clinicalJudgmentTargets,
    tabs: normalizedTabs,
    choices: {
      conditions,
      interventions,
      monitoring
    },
    answer: {
      condition: conditionAnswer,
      interventions: interventionAnswers,
      monitoring: monitoringAnswers
    },
    rationale: {
      condition: safeText(rationale.condition, "The correct condition integrates the highest-priority cues across the unfolding chart."),
      interventions: safeText(rationale.interventions, "The correct interventions address the immediate threat and expected nursing/collaborative priorities."),
      monitoring: safeText(rationale.monitoring, "The correct monitoring choices track whether the priority threat is improving or worsening."),
      trap: safeText(rationale.trap, "The trap is anchoring on one loud cue instead of synthesizing the trend.")
    }
  };
}

async function requestGeneratedCjeCase(input = "") {
  try {
    const response = await fetchApi("/api/ani/cje", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: input,
        context: getAniQuestionGeneratorContext(input, { formatHint: "butterfly" })
      })
    });

    if (!response.ok) {
      return null;
    }

    const data = await response.json();
    return normalizeGeneratedCjeCase(data.caseItem, input);
  } catch (error) {
    return null;
  }
}

function wantsStandardQuestionGeneration(input = "") {
  if (isContextRepairMessage(input)) {
    return false;
  }

  const lower = normalizeIntentText(input);
  if (wantsAvoidStandardQuestionFormat(input) || shouldChooseQuestionTypeForUser(input)) {
    return false;
  }

  const explicitStandard = wantsExplicitStandardQuestionFormat(input) && !wantsExplicitAdvancedQuestionFormat(input);
  return !wantsGenericPracticeProblem(input)
    && !wantsUnfoldingCase(input)
    && (explicitStandard || !wantsAdvancedItem(input))
    && !wantsCjeChallenge(input)
    && !wantsRapidFire(input)
    && (asksForQuestionNow(input) || /\b(quiz|test|practice|nclex)\b.{0,40}\b(question|item|quiz)\b/i.test(lower));
}

function standardQuestionExamples(input = "") {
  const topic = inferTopic(input);
  const difficulty = inferDifficulty(input);
  const selectedTopic = generatedQuestionBank[topic] ? topic : currentTopic;
  return getGeneratedPool(selectedTopic, difficulty)
    .concat((generatedQuestionBank[selectedTopic] || []).filter((item) => item.difficulty !== difficulty))
    .slice(0, 3)
    .map((item) => ({
      ...item,
      topic: selectedTopic
    }));
}

function normalizeGeneratedStandardQuestion(rawItem, input = "") {
  if (!rawItem || typeof rawItem !== "object") {
    return null;
  }

  const topic = safeText(rawItem.topic, inferTopic(input) || currentTopic);
  const difficulty = normalizeQuestionDifficulty(rawItem.difficulty || inferDifficulty(input));
  const options = toShortTextArray(rawItem.options, [], 4);
  const answer = safeText(rawItem.answer);
  if (options.length !== 4 || !options.includes(answer)) {
    return null;
  }
  const randomized = randomizeStandardOptions(options, answer);

  return {
    id: `generated-standard-${slugify(rawItem.id || rawItem.concept || rawItem.stem || "question")}-${Date.now()}`,
    topic,
    difficulty,
    skill: safeText(rawItem.skill, "Analyze cues"),
    concept: safeText(rawItem.concept, topic),
    stem: safeText(rawItem.stem, "Which nursing action is priority?"),
    options: randomized.options,
    answer: randomized.answer,
    rationale: safeText(rawItem.rationale, "The correct answer follows NCLEX priority, safety, and clinical judgment logic."),
    trap: safeText(rawItem.trap, "The trap is anchoring on a familiar cue without prioritizing the most urgent risk.")
  };
}

async function requestGeneratedStandardQuestion(input = "") {
  try {
    const topic = inferTopic(input);
    const difficulty = inferDifficulty(input);
    const requestItem = async (message) => {
      const response = await fetchApi("/api/ani/standard-question", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          message,
          topic,
          difficulty,
          examples: standardQuestionExamples(input),
          context: getAniQuestionGeneratorContext(input, { formatHint: "standard" })
        })
      });

      if (!response.ok) {
        return null;
      }

      const data = await response.json();
      return data.item || null;
    };

    const firstItem = await requestItem(input);
    const firstQuestion = firstItem && !hasRecentStandardQuestionSignature(firstItem.stem)
      ? normalizeGeneratedStandardQuestion(firstItem, input)
      : null;
    if (firstQuestion) {
      return firstQuestion;
    }

    return null;
  } catch (error) {
    return null;
  }
}

function normalizeGeneratedAdvancedItem(rawItem, input = "") {
  if (!rawItem || typeof rawItem !== "object") {
    return null;
  }

  const type = safeText(rawItem.type).toLowerCase();
  if (!["ordering", "sata", "single", "concern", "matrix", "highlight", "cloze"].includes(type)) {
    return null;
  }

  const base = {
    id: `generated-${slugify(rawItem.id || rawItem.title || type)}-${Date.now()}`,
    type,
    subtype: safeText(rawItem.subtype, type === "ordering" ? "priority" : ""),
    title: safeText(rawItem.title, `Advanced ${type} item`),
    displayTitle: type === "highlight" ? "Highlight Chart" : type === "matrix" ? "Bullet Matrix" : type === "concern" ? "Chart Cue Question" : type === "cloze" ? "Drop-Down Sentence Completion" : "",
    topic: safeText(rawItem.topic, inferTopic(input) || "Complex Care"),
    difficulty: "Hard",
    stem: safeText(rawItem.stem, "Answer the NCLEX-style item."),
    instructions: safeText(rawItem.instructions, "Answer the item, then grade for a detailed rationale."),
    rationale: safeText(rawItem.rationale, "The correct answer follows priority, safety, and clinical judgment logic.")
  };

  if (type === "ordering") {
    const items = Array.isArray(rawItem.items)
      ? rawItem.items.map((entry, index) => ({
        id: slugify(entry.id || `step-${index + 1}`),
        text: safeText(entry.text),
        rationale: safeText(entry.rationale, "This step belongs in the safe priority sequence.")
      })).filter((entry) => entry.text)
      : [];
    const itemIds = new Set(items.map((entry) => entry.id));
    const suppliedAnswer = toShortTextArray(rawItem.answer, [], items.length)
      .map((id) => slugify(id))
      .filter((id) => itemIds.has(id));
    const seenAnswerIds = new Set();
    const answer = suppliedAnswer.filter((id) => {
      if (seenAnswerIds.has(id)) return false;
      seenAnswerIds.add(id);
      return true;
    });
    items.forEach((item) => {
      if (!seenAnswerIds.has(item.id)) {
        answer.push(item.id);
        seenAnswerIds.add(item.id);
      }
    });
    if (items.length < 3 || answer.length !== items.length) {
      return null;
    }
    return { ...base, items, answer };
  }

  if (type === "sata" || type === "single" || type === "concern") {
    const choices = Array.isArray(rawItem.choices)
      ? rawItem.choices.map((choice, index) => ({
        id: slugify(choice.id || `choice-${index + 1}`),
        text: safeText(choice.text),
        correct: Boolean(choice.correct),
        rationale: safeText(choice.rationale, "This option must be judged against the priority cue in the stem.")
      })).filter((choice) => choice.text)
      : [];
    const correctCount = choices.filter((choice) => choice.correct).length;
    if (choices.length < 4 || correctCount < 1 || ((type === "single" || type === "concern") && correctCount !== 1)) {
      return null;
    }
    const randomizedChoices = shuffledCopy(choices);
    const tabs = Array.isArray(rawItem.tabs)
      ? rawItem.tabs.map((tab, index) => ({
        id: slugify(tab.id || tab.label || `tab-${index + 1}`),
        label: safeText(tab.label, `Chart ${index + 1}`),
        entries: toShortTextArray(tab.entries, [], 8)
      })).filter((tab) => tab.entries.length)
      : [];
    return { ...base, choices: randomizedChoices, tabs };
  }

  if (type === "matrix") {
    const categories = toShortTextArray(rawItem.categories, [], 4);
    const rows = Array.isArray(rawItem.rows)
      ? rawItem.rows.map((row, index) => {
        const answer = Array.isArray(row.answer)
          ? row.answer.map((value) => safeText(value)).filter((value) => categories.includes(value))
          : safeText(row.answer);
        return {
          id: slugify(row.id || `row-${index + 1}`),
          text: safeText(row.text),
          answer,
          rationale: safeText(row.rationale, "This row is categorized by priority, safety, or expected versus unexpected findings.")
        };
      }).filter((row) => row.text && (Array.isArray(row.answer) ? row.answer.length : categories.includes(row.answer)))
      : [];
    if (categories.length < 2 || rows.length < 3) {
      return null;
    }
    return { ...base, categories, rows };
  }

  if (type === "highlight") {
    const rows = Array.isArray(rawItem.rows)
      ? rawItem.rows.map((row, index) => ({
        id: slugify(row.id || row.time || `time-${index + 1}`),
        time: safeText(row.time, `Time ${index + 1}`),
        data: safeText(row.data),
        rationale: safeText(row.rationale, "This row is judged by the trend and medication or safety cue.")
      })).filter((row) => row.data)
      : [];
    const rowIds = new Set(rows.map((row) => row.id));
    const answer = toShortTextArray(rawItem.answer, [], 3)
      .map((id) => slugify(id))
      .filter((id) => rowIds.has(id));
    if (rows.length < 3 || !answer.length) {
      return null;
    }
    return { ...base, rows, answer };
  }

  if (type === "cloze") {
    const blanks = Array.isArray(rawItem.blanks)
      ? rawItem.blanks.map((blank, index) => {
        const options = toShortTextArray(blank.options, [], 6);
        const answer = safeText(blank.answer || blank.correct);
        const randomized = randomizeStandardOptions(options, answer);
        return {
          id: slugify(blank.id || blank.label || `blank-${index + 1}`),
          label: safeText(blank.label, `Blank ${index + 1}`),
          options: randomized.options,
          answer,
          rationale: safeText(blank.rationale, "This drop-down completes the safest clinical sentence.")
        };
      }).filter((blank) => blank.options.length >= 2 && blank.answer && blank.options.includes(blank.answer))
      : [];
    const sentenceParts = toShortTextArray(rawItem.sentenceParts || rawItem.parts, [], blanks.length + 1);
    if (!blanks.length) {
      return null;
    }
    return {
      ...base,
      sentenceParts: sentenceParts.length === blanks.length + 1 ? sentenceParts : [],
      blanks
    };
  }

  return null;
}

async function requestGeneratedAdvancedItem(input = "") {
  try {
    const response = await fetchApi("/api/ani/advanced-item", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: input,
        context: getAniQuestionGeneratorContext(input, { formatHint: requestedInteractiveQuestionFormat(input) || "advanced" })
      })
    });

    if (!response.ok) {
      return null;
    }

    const data = await response.json();
    return normalizeGeneratedAdvancedItem(data.item, input);
  } catch (error) {
    return null;
  }
}

function imageAttachmentSummary(images = []) {
  if (!images.length) {
    return "";
  }

  const names = images.map((image) => image.name).join(", ");
  return `${images.length === 1 ? "Image attached" : "Images attached"}: ${names}`;
}

function resourceAttachmentSummary(resources = []) {
  if (!resources.length) {
    return "";
  }

  const names = resources.map((resource) => resource.name).join(", ");
  return `${resources.length === 1 ? "Class resource attached" : "Class resources attached"}: ${names}`;
}

function attachmentSummary(images = [], resources = []) {
  return [imageAttachmentSummary(images), resourceAttachmentSummary(resources)]
    .filter(Boolean)
    .join("\n");
}

function imageAnalysisFallback(input = "", images = [], resources = []) {
  const summary = attachmentSummary(images, resources);
  const prompt = input.trim()
    ? `I see your note: "${input.trim()}"`
    : "I see that you uploaded something for me to analyze.";

  if (resources.length && !images.length) {
    return `${prompt}\n\n${summary}\n\nI can use the class-resource attachment names as context right now, but full ZIP/PDF/PowerPoint/Word reading needs the document-ingestion route connected before I can honestly analyze the file contents.\n\nFor now, paste the visible slide text, export key slides as screenshots, or tell me the class/unit topics, and I can build a hard NCLEX-style exam from that. Once document ingestion is connected, ANI should read the resource packet, extract concepts, and blend them with NCLEX-level testing.`;
  }

  return `${prompt}\n\n${summary}\n\nI can use uploaded images as visual reference when image recognition is connected.\nIf recognition is unavailable, paste the visible text and I will still answer from the readable content.\nFor meds, labs, or NCLEX image questions, I can prioritize likely matches and give confidence in my best guess, then explain the learning point.`;
}

function imageScanCacheKey(images = []) {
  return images
    .map((image) => [
      image.name || "image",
      image.size || 0,
      image.type || "",
      String(image.dataUrl || "").length,
      String(image.dataUrl || "").slice(0, 48),
      String(image.dataUrl || "").slice(-48)
    ].join(":"))
    .join("|");
}

function compactImageScanText(text = "") {
  return String(text || "")
    .replace(/\r/g, "")
    .replace(/[ \t]+\n/g, "\n")
    .replace(/\n{4,}/g, "\n\n\n")
    .trim()
    .slice(0, MAX_IMAGE_SCAN_TEXT_CHARS);
}

function imageScanMatchSummary(candidate = {}) {
  return {
    label: offlineLookupEntityLabel(candidate),
    kind: offlineLookupEntityKind(candidate),
    query: offlineLookupQuery(candidate),
    type: candidate.type,
    score: Math.round(candidate.score || 0),
    ambiguousIdentity: candidate.ambiguousIdentity === true,
    identitySuggestionOnly: candidate.identitySuggestionOnly === true,
    phoneticMatch: candidate.phoneticMatch === true,
    clinicalClueMatch: candidate.clinicalClueMatch === true,
    mayAutoOpen: candidate.mayAutoOpen === true,
    confidence: Number(candidate.confidence || 0),
    confidenceTier: candidate.confidenceTier || ""
  };
}

function buildImageScanLocalContext(input = "", scanned = {}) {
  const text = compactImageScanText(scanned.text || "");
  if (!text) {
    return null;
  }

  const matches = offlineLookupSuggestions([input, text].filter(Boolean).join("\n"))
    .slice(0, MAX_IMAGE_SCAN_MATCHES)
    .map(imageScanMatchSummary)
    .filter((match) => match.label && match.query);
  const matchLines = matches.length
    ? matches.map((match) => `- ${match.label} (${match.kind}; query: ${match.query}; score: ${match.score})`).join("\n")
    : "- No confident installed encyclopedia term match found yet.";
  const summaries = Array.isArray(scanned.imageSummaries) && scanned.imageSummaries.length
    ? scanned.imageSummaries.map((summary) => `- ${summary}`).join("\n")
    : "- Image summary unavailable.";

  return {
    text,
    matches,
    imageSummaries: scanned.imageSummaries || [],
    localDraft: [
      "ANI image text scanner extracted visible screenshot text:",
      text,
      "",
      "Clinical reference matches from the student message plus extracted image text:",
      matchLines,
      "",
      "Image summaries:",
      summaries,
      "",
      "Use the extracted text as the screenshot source text. Use the clinical reference matches as anchors when answering. If the image is a question, answer the question directly and explain the rationale."
    ].join("\n")
  };
}

function imageVisionScanCacheKey(images = []) {
  return `vision:${imageScanCacheKey(images)}`;
}

function wantsVisionIdentificationDirection(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(what is|what are|identify|recogniz|what does|what do you see|spot|look|name|is this|which|could this be|is this|photo|photo of|image of|medication|pill|tablet|drug|medicine|rash|lesion|wound|organism|bacteria|virus)\b/i.test(lower)
    || (input && !/\b(lecture|practice|question|quiz|test|generate|make|create)\b/i.test(lower) && /\b(this|these|that|image|photo)\b/i.test(lower));
}

function formatVisionConfidencePercent(confidence = 0) {
  const normalized = clampPercentage(confidence);
  return `${Math.round(normalized * 100)}%`;
}

function clampPercentage(value = 0) {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 0;
  if (numeric > 1 && numeric <= 100) return numeric / 100;
  return Math.max(0, Math.min(1, numeric));
}

function topVisionDraftLine(prediction = {}, differential = []) {
  if (!prediction?.label) return "";
  const percent = formatVisionConfidencePercent(prediction.confidence);
  const rationale = String(prediction.description || prediction.entityType || "").trim();
  const typeLine = rationale ? ` Why: ${rationale}` : "";
  return `- ${prediction.label} (${percent} likely)${typeLine}`;
}

function buildImageVisionScanLocalContext(input = "", scanned = {}) {
  const predictions = Array.isArray(scanned.predictions) ? scanned.predictions : [];
  const differential = Array.isArray(scanned.differential) ? scanned.differential : [];
  const matches = [];
  predictions.forEach((prediction = {}) => {
    const label = String(prediction.label || "").trim();
    if (!label) return;
    const candidates = offlineLookupSuggestions(label);
    const topCandidate = candidates?.find((candidate) => (
      candidate?.ambiguousIdentity !== true
      && candidate?.identitySuggestionOnly !== true
      && candidate?.phoneticMatch !== true
      && (candidate?.clinicalClueMatch !== true || candidate?.mayAutoOpen === true)
      && offlineLookupIsDirectEnough(label, candidate)
    ));
    if (!topCandidate) return;
    matches.push({
      prediction,
      candidate: topCandidate,
      score: Number(prediction.confidence || 0)
    });
  });

  const imageSummaryLines = Array.isArray(scanned.imageSummaries) && scanned.imageSummaries.length
    ? scanned.imageSummaries.slice(0, MAX_IMAGE_VISION_SUMMARIES).map((summary) => `- ${summary}`).join("\n")
    : "- Image summary unavailable.";

  const bestPrediction = predictions[0] && predictions[0].label
    ? predictions[0]
    : null;
  const matchLines = matches.length
    ? matches.map((match) => {
      const label = offlineLookupEntityLabel(match.candidate);
      return label ? `- ${label} (${match.score ? `${formatVisionConfidencePercent(match.score)} from ${match.prediction.label}` : match.prediction.label})` : "";
    }).filter(Boolean).slice(0, 6).join("\n")
    : "- No confident encyclopedia match from vision scan yet.";

  const diffLines = differential.length
    ? differential.slice(0, 4).map((term) => `- ${safeText(term)}`).join("\n")
    : "- No alternate differential returned.";

  return {
    predictions,
    differential,
    imageSummaries: scanned.imageSummaries || [],
    matches,
    bestPrediction,
    localDraft: [
      "ANI image vision scan findings:",
      "",
      topPredictionToVisionDraftText(bestPrediction),
      "",
      "Top matching encyclopedia candidates:",
      matchLines,
      "",
      "Top differential terms:",
      diffLines,
      "",
      "Image summaries:",
      imageSummaryLines,
      "",
      "Use this as context only. Explain if findings are uncertain and suggest next steps (other angles, lighting, re-capture, and symptom context)."
    ].join("\n")
  };
}

function topPredictionToVisionDraftText(prediction = {}) {
  if (!prediction?.label) return "- No confident visual prediction returned.";
  const percent = formatVisionConfidencePercent(prediction.confidence);
  const description = safeText(prediction.description || "");
  const category = safeText(prediction.category || "");
  return [
    `- ${prediction.label} (${percent} likely)`,
    prediction.category ? `  Category: ${category}` : "",
    description ? `  Rationale: ${description}` : ""
  ].filter(Boolean).join("\n");
}

function bestVisionMatchCandidate(scanned = {}) {
  const matches = Array.isArray(scanned.matches) ? scanned.matches : [];
  if (!matches.length) return null;
  const ranked = matches
    .filter((entry) => entry?.candidate && offlineLookupEntityLabel(entry.candidate) && entry.score >= IMAGE_VISION_DRAFT_THRESHOLD)
    .sort((left, right) => {
      const leftScore = Number(left.score || 0);
      const rightScore = Number(right.score || 0);
      const leftCandidate = Number(left.candidate?.score || 0);
      const rightCandidate = Number(right.candidate?.score || 0);
      return rightScore - leftScore || rightCandidate - leftCandidate;
    });
  return ranked[0] || null;
}

function isVisionAutoOpenSafe(input = "", match = null, topPrediction = null) {
  if (!match?.candidate || !topPrediction?.label) return false;
  if (match.candidate.ambiguousIdentity === true
    || match.candidate.identitySuggestionOnly === true
    || match.candidate.phoneticMatch === true
    || (match.candidate.clinicalClueMatch === true && match.candidate.mayAutoOpen !== true)) {
    return false;
  }
  const label = offlineLookupEntityLabel(match.candidate);
  const score = Number(topPrediction.confidence || 0);
  if (!label || score < IMAGE_VISION_AUTO_OPEN_THRESHOLD) return false;
  const candidateScore = Number(match.candidate?.score || 0);
  if (candidateScore < IMAGE_VISION_OFFLINE_MATCH_SCORE_MIN) return false;
  const rawInput = normalizeIntentText(input);
  return wantsVisionIdentificationDirection(rawInput) || rawInput.length <= 5;
}

async function scanImagesForVisionContext(input = "", images = []) {
  if (!images.length) {
    return null;
  }
  if (!ANI_SERVER_IMAGE_ANALYSIS_ENABLED) {
    return null;
  }

  const key = imageVisionScanKey(images);
  const cached = imageVisionScanCache.get(key);
  if (cached && typeof cached === "object") {
    return buildImageVisionScanLocalContext(input, cached);
  }

  try {
    if (voiceStatus) {
      voiceStatus.textContent = "Running image recognition for likely match candidates...";
    }
    const response = await fetchApi("/api/ani/image-vision", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: input,
        images: images.map((image) => ({
          name: image.name,
          type: image.type,
          dataUrl: image.dataUrl
        }))
      })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !Array.isArray(data.predictions) || !data.predictions.length) {
      return null;
    }
    const scanned = {
      predictions: data.predictions.map((prediction = {}) => ({
        ...prediction,
        confidence: clampPercentage(prediction.confidence)
      })),
      differential: Array.isArray(data.differential)
        ? data.differential.map((term) => String(term || "").trim()).filter(Boolean).slice(0, 8)
        : [],
      imageSummaries: Array.isArray(data.imageSummaries)
        ? data.imageSummaries.map((item) => String(item || "").trim()).filter(Boolean).slice(0, MAX_IMAGE_VISION_SUMMARIES)
        : []
    };
    scanned.predictions = scanned.predictions
      .sort((left, right) => Number(right.confidence || 0) - Number(left.confidence || 0))
      .slice(0, 6);
    imageVisionScanCache.set(key, scanned);
    if (imageVisionScanCache.size > IMAGE_VISION_CACHE_LIMIT) {
      imageVisionScanCache.delete(imageVisionScanCache.keys().next().value);
    }
    return buildImageVisionScanLocalContext(input, scanned);
  } catch (error) {
    return null;
  }
}

function imageVisionScanKey(images = []) {
  return `vision:${imageScanCacheKey(images)}`;
}

async function scanImagesForTextContext(input = "", images = []) {
  if (!images.length) {
    return null;
  }
  if (!ANI_SERVER_IMAGE_ANALYSIS_ENABLED) {
    return null;
  }

  const key = imageScanCacheKey(images);
  if (imageTextScanCache.has(key)) {
    return buildImageScanLocalContext(input, imageTextScanCache.get(key));
  }

  try {
    if (voiceStatus) {
      voiceStatus.textContent = "Scanning image text and matching encyclopedia terms...";
    }
    const response = await fetchApi("/api/ani/image-text", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: input,
        images: images.map((image) => ({
          name: image.name,
          type: image.type,
          dataUrl: image.dataUrl
        }))
      })
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok || !data.text?.trim()) {
      return null;
    }
    const scanned = {
      text: compactImageScanText(data.text),
      imageSummaries: Array.isArray(data.imageSummaries)
        ? data.imageSummaries.map((item) => String(item || "").trim()).filter(Boolean).slice(0, 6)
        : []
    };
    imageTextScanCache.set(key, scanned);
    if (imageTextScanCache.size > 12) {
      imageTextScanCache.delete(imageTextScanCache.keys().next().value);
    }
    return buildImageScanLocalContext(input, scanned);
  } catch (error) {
    return null;
  }
}

function readImageAsDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.addEventListener("load", () => resolve(reader.result));
    reader.addEventListener("error", () => reject(new Error("Unable to read image.")));
    reader.readAsDataURL(file);
  });
}

function renderImagePreviewTray() {
  if (!imagePreviewTray) {
    return;
  }

  imagePreviewTray.textContent = "";
  imagePreviewTray.classList.toggle("has-images", pendingImages.length > 0 || pendingResources.length > 0);

  pendingImages.forEach((image) => {
    const chip = document.createElement("div");
    chip.className = "image-chip";

    const thumb = document.createElement("img");
    thumb.src = image.dataUrl;
    thumb.alt = "";

    const label = document.createElement("span");
    label.textContent = image.name;

    const remove = document.createElement("button");
    remove.className = "remove-image-button";
    remove.type = "button";
    remove.textContent = "x";
    remove.setAttribute("aria-label", `Remove ${image.name}`);
    remove.addEventListener("click", () => {
      pendingImages = pendingImages.filter((item) => item.id !== image.id);
      renderImagePreviewTray();
      voiceStatus.textContent = pendingImages.length
        ? imageAttachmentSummary(pendingImages)
        : "Image removed";
    });

    chip.append(thumb, label, remove);
    imagePreviewTray.append(chip);
  });

  pendingResources.forEach((resource) => {
    const chip = document.createElement("div");
    chip.className = "image-chip resource-chip";

    const badge = document.createElement("span");
    badge.className = "resource-file-badge";
    badge.textContent = resource.extension || "FILE";

    const label = document.createElement("span");
    label.textContent = resource.name;

    const remove = document.createElement("button");
    remove.className = "remove-image-button";
    remove.type = "button";
    remove.textContent = "x";
    remove.setAttribute("aria-label", `Remove ${resource.name}`);
    remove.addEventListener("click", () => {
      pendingResources = pendingResources.filter((item) => item.id !== resource.id);
      renderImagePreviewTray();
      voiceStatus.textContent = pendingResources.length || pendingImages.length
        ? attachmentSummary(pendingImages, pendingResources)
        : "Attachment removed";
    });

    chip.append(badge, label, remove);
    imagePreviewTray.append(chip);
  });
}

async function addImageFiles(files = []) {
  const allFiles = Array.from(files);
  const imageSlots = MAX_IMAGE_ATTACHMENTS - pendingImages.length;
  const resourceSlots = MAX_RESOURCE_ATTACHMENTS - pendingResources.length;
  const selectedImages = allFiles
    .filter((file) => /^image\/(png|jpe?g|webp)$/i.test(file.type))
    .slice(0, Math.max(0, imageSlots));
  const selectedResources = allFiles
    .filter((file) => /\.(zip|pdf|pptx?|docx?|txt)$/i.test(file.name || ""))
    .slice(0, Math.max(0, resourceSlots));

  if (!selectedImages.length && !selectedResources.length) {
    voiceStatus.textContent = pendingImages.length || pendingResources.length
      ? `Maximum ${MAX_IMAGE_ATTACHMENTS} images and ${MAX_RESOURCE_ATTACHMENTS} class resources at a time.`
      : "Choose a screenshot or class resource file.";
    return;
  }

  for (const file of selectedImages) {
    if (file.size > MAX_IMAGE_BYTES) {
      voiceStatus.textContent = `${file.name} is too large. Use a screenshot under 6 MB.`;
      continue;
    }

    try {
      const dataUrl = await readImageAsDataUrl(file);
      pendingImages.push({
        id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
        name: file.name || "uploaded image",
        type: file.type,
        size: file.size,
        dataUrl
      });
    } catch (error) {
      voiceStatus.textContent = `Could not attach ${file.name}. Try another screenshot.`;
    }
  }

  selectedResources.forEach((file) => {
    if (file.size > MAX_RESOURCE_BYTES) {
      voiceStatus.textContent = `${file.name} is too large. Use a class resource under 50 MB.`;
      return;
    }

    const extension = (/\.(zip|pdf|pptx?|docx?|txt)$/i.exec(file.name || "")?.[1] || "file").toUpperCase();
    pendingResources.push({
      id: `${Date.now()}-${Math.random().toString(16).slice(2)}`,
      name: file.name || "class resource",
      type: file.type || "application/octet-stream",
      size: file.size,
      extension
    });
  });

  renderImagePreviewTray();
  if (pendingImages.length || pendingResources.length) {
    voiceStatus.textContent = `${attachmentSummary(pendingImages, pendingResources)}. Add a note or press Send.`;
  }
}

function inferTopic(input = "") {
  const lower = normalizeIntentText(input);
  const matches = [
    ["Neuro Complex Care", /(?:neuro|stroke|seizure|intracranial|icp|gcs|glasgow|brain|spinal|autonomic|guillain|myasthenic).{0,80}(?:complex|critical|icu|adult health|high acuity|deteriorat|shock|ventilat|perfusion)|(?:complex|critical|icu|adult health|high acuity).{0,80}(?:neuro|stroke|icp|gcs|glasgow|brain|spinal|guillain|myasthenic)/],
    ["Endocrine", /endocrine|\bdka\b|diabetic|insulin|glucose|thyroid|adrenal|potassium/],
    ["Respiratory", /copd|asthma|oxygen|spo2|ventilation|pneumonia|respiratory/],
    ["Cardiac", /heart failure|chf|mi\b|angina|ecg|ekg|cardiac|metoprolol|beta blocker/],
    ["Complex Care", /complex|critical|icu|shock|sepsis|multi.?system|hemodynamic|ventilator|vasopressor|lactate|map|deteriorat|adult health/],
    ["Neuro", /stroke|seizure|intracranial|icp|gcs|glasgow|neuro|pupil|confusion|brain|spinal|guillain|myasthenic/],
    ["Maternal newborn", /pregnan|preeclampsia|magnesium|postpartum|newborn|fetal/],
    ["Pediatrics", /infant|child|pediatric|pediatrics|peds|fontanel|dehydration/],
    ["Fundamentals", /fundamentals?|delegate|delegation|assistive|hygiene|sterile|fall/],
    ["Prioritization", /priority|first|most concerning|see first|abc/],
    ["Pathophysiology", /sepsis|shock|pathophys|mechanism|inflammation/],
    ["Pharmacology", /med|drug|dose|adverse|toxicity|antidote|pharm/]
  ];

  const match = matches.find(([, pattern]) => pattern.test(lower));
  return match ? match[0] : currentTopic;
}

function getTopicData(input = "") {
  return nclexBank[inferTopic(input)] || nclexBank[currentTopic] || nclexBank.Pharmacology;
}

function legacyQuestionToGenerated(topic, difficulty = currentDifficulty) {
  const data = nclexBank[topic] || nclexBank[currentTopic] || nclexBank.Pharmacology;
  return {
    ...data,
    topic: nclexBank[topic] ? topic : currentTopic,
    difficulty: normalizeQuestionDifficulty(difficulty),
    skill: "Recognize cues"
  };
}

function getGeneratedPool(topic, difficulty) {
  const requestedDifficulty = normalizeQuestionDifficulty(difficulty);
  const items = generatedQuestionBank[topic] || [];
  const exact = items.filter((item) => item.difficulty === requestedDifficulty);

  if (exact.length) {
    return exact;
  }

  if (items.length) {
    return items;
  }

  return [legacyQuestionToGenerated(topic, requestedDifficulty)];
}

function questionFactoryCounterKey(topic, difficulty) {
  return `ani-question-factory-counter:${slugify(topic)}:${normalizeQuestionDifficulty(difficulty)}`;
}

function readQuestionFactoryCounter(topic, difficulty) {
  return Number(localStorage.getItem(questionFactoryCounterKey(topic, difficulty)) || "0");
}

function saveQuestionFactoryCounter(topic, difficulty, value) {
  localStorage.setItem(questionFactoryCounterKey(topic, difficulty), String(value));
}

function blueprintsForTopic(topic, difficulty, input = "") {
  const pack = questionFactoryPacks[topic] || [];
  const requestedDifficulty = normalizeQuestionDifficulty(difficulty);
  const exact = pack.filter((blueprint) => normalizeQuestionDifficulty(blueprint.difficulty) === requestedDifficulty);
  const pool = exact.length ? exact : pack;
  const lower = normalizeIntentText(input);
  const genericWords = new Set([
    "another",
    "question",
    "questions",
    "practice",
    "nclex",
    "complex",
    "health",
    "adult",
    "neuro",
    "cardiac",
    "respiratory",
    "pharm",
    "pharmacology",
    "normal",
    "hard",
    "difficulty",
    "maximum",
    "topic",
    "requested"
  ]);
  const meaningfulWords = lower
    .split(/\s+/)
    .map((word) => word.replace(/[^a-z0-9]/g, ""))
    .filter((word) => word.length > 4 && !genericWords.has(word));
  const matchedConcept = pool.filter((blueprint) => {
    const conceptText = `${blueprint.concept} ${blueprint.scenario}`.toLowerCase();
    return meaningfulWords.some((word) => conceptText.includes(word));
  });

  return matchedConcept.length ? matchedConcept : pool;
}

function deterministicPick(items = [], variant = 0, offset = 0) {
  if (!items.length) {
    return "";
  }
  return items[(variant + offset) % items.length];
}

function rotateOptions(answer, distractors = [], variant = 0) {
  const uniqueDistractors = distractors
    .filter(Boolean)
    .filter((option, index, list) => list.indexOf(option) === index && option !== answer);
  const selectedDistractors = [];
  for (let index = 0; selectedDistractors.length < 3 && index < uniqueDistractors.length + 8; index += 1) {
    const candidate = deterministicPick(uniqueDistractors, variant, index);
    if (candidate && !selectedDistractors.includes(candidate)) {
      selectedDistractors.push(candidate);
    }
  }

  while (selectedDistractors.length < 3) {
    selectedDistractors.push(`Plausible distractor ${selectedDistractors.length + 1}`);
  }

  const options = [answer, ...selectedDistractors.slice(0, 3)];
  const answerIndex = shouldAvoidAnotherAAnswer()
    ? 1 + aniRandomInt(3)
    : aniRandomInt(4);
  const rotated = options.slice();
  const currentAnswerIndex = rotated.indexOf(answer);
  rotated.splice(currentAnswerIndex, 1);
  rotated.splice(answerIndex, 0, answer);
  return rotated;
}

function makeFactoryStem(blueprint, topic, variant, scenarioVariant = variant, blueprintIndex = 0) {
  const profile = questionFactoryTopicProfiles[topic] || {};
  const clients = blueprint.clients || profile.clients || questionFactoryClients;
  const settings = blueprint.settings || profile.settings || questionFactorySettings;
  const normalFindings = blueprint.normalFindings || profile.normalFindings || questionFactoryNormalFindings;
  let client = clients[(scenarioVariant + blueprintIndex) % clients.length];
  const setting = settings[(Math.floor(scenarioVariant / clients.length) + blueprintIndex * 2) % settings.length];
  const normalFinding = normalFindings[(Math.floor(scenarioVariant / (clients.length * settings.length)) + blueprintIndex * 3) % normalFindings.length];
  let scenario = blueprint.scenario || "";
  if (topic === "Pediatrics") {
    if (/6-week-old|RSV|apnea/i.test(scenario)) {
      client = "A 6-week-old infant";
      scenario = scenario.replace(/^\s*is\s+a\s+6-week-old\s+with\s+/i, "with ");
    } else if (/drooling|tripod|muffled voice|epiglottitis/i.test(scenario)) {
      client = "A preschool-age child";
    } else if (/vomiting|no tears|sunken eyes|capillary refill|lethargy/i.test(scenario)) {
      client = "A toddler";
    }
  }

  return [client, setting, scenario, normalFinding, blueprint.ask]
    .filter(Boolean)
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
}

function makeLocalGeneratedQuestion(topic = currentTopic, difficulty = currentDifficulty, input = "") {
  const selectedTopic = questionFactoryPacks[topic] ? topic : (questionFactoryPacks[currentTopic] ? currentTopic : "");
  if (!selectedTopic) {
    return null;
  }

  const selectedDifficulty = normalizeQuestionDifficulty(difficulty);
  const blueprints = blueprintsForTopic(selectedTopic, selectedDifficulty, input);
  if (!blueprints.length) {
    return null;
  }

  const baseCounter = readQuestionFactoryCounter(selectedTopic, selectedDifficulty);
  let selectedQuestion = null;
  let selectedVariant = baseCounter;

  for (let attempt = 0; attempt < Math.max(24, blueprints.length * 4); attempt += 1) {
    const variant = baseCounter + attempt;
    const blueprintIndex = variant % blueprints.length;
    const blueprint = blueprints[blueprintIndex];
    const scenarioVariant = Math.floor(variant / blueprints.length);
    const stem = makeFactoryStem(blueprint, selectedTopic, variant, scenarioVariant, blueprintIndex);
    if (attempt > 0 || !hasRecentStandardQuestionSignature(stem)) {
      selectedVariant = variant;
      selectedQuestion = {
        id: `factory-${slugify(selectedTopic)}-${slugify(blueprint.concept)}-${variant}`,
        topic: selectedTopic,
        difficulty: selectedDifficulty,
        skill: blueprint.skill || "Analyze cues",
        concept: blueprint.concept || selectedTopic,
        stem,
        options: rotateOptions(blueprint.answer, blueprint.distractors, scenarioVariant + blueprintIndex),
        answer: blueprint.answer,
        rationale: blueprint.rationale,
        trap: blueprint.trap
      };
      if (!hasRecentStandardQuestionSignature(stem)) {
        break;
      }
    }
  }

  saveQuestionFactoryCounter(selectedTopic, selectedDifficulty, selectedVariant + 1);
  return selectedQuestion;
}

function generatedQuestionData(topic = currentTopic, difficulty = currentDifficulty, input = "") {
  const selectedTopic = (generatedQuestionBank[topic] || nclexBank[topic])
    ? topic
    : currentTopic;
  const selectedDifficulty = normalizeQuestionDifficulty(difficulty);
  const factoryQuestion = makeLocalGeneratedQuestion(selectedTopic, selectedDifficulty, input);
  if (factoryQuestion) {
    return factoryQuestion;
  }

  const pool = getGeneratedPool(selectedTopic, selectedDifficulty)
    .map((item) => ({
      ...item,
      id: item.id || standardQuestionId(item, selectedTopic)
    }));
  const cursorKey = `${selectedTopic}:${selectedDifficulty}`;
  const cursor = generatedQuestionCursor[cursorKey] || 0;
  const targeted = selectedTopic === "Endocrine" && /\b(complex|critical|icu|high acuity|adult health)\b/i.test(input)
    ? pool.find((item) => /complex|dka|shock|ventricular|potassium/i.test(`${item.concept} ${item.stem}`))
    : null;
  const recent = new Set(recentStandardQuestionIds);
  const unseenPool = pool.filter((item) => !recent.has(item.id));
  const selected = targeted && !recent.has(targeted.id)
    ? targeted
    : (unseenPool.length ? unseenPool[cursor % unseenPool.length] : makeQuestionVariant(pool[cursor % pool.length], selectedTopic));
  generatedQuestionCursor[cursorKey] = (cursor + 1) % Math.max(1, unseenPool.length || pool.length);
  const randomized = randomizeStandardOptions(selected.options || [], selected.answer || "");

  return {
    ...selected,
    id: selected.id || standardQuestionId(selected, selectedTopic),
    topic: selectedTopic,
    difficulty: selected.difficulty || selectedDifficulty,
    skill: selected.skill || "Recognize cues",
    options: randomized.options,
    answer: randomized.answer
  };
}

function standardQuestionId(item = {}, topic = currentTopic) {
  return `standard-${slugify(topic)}-${slugify(item.id || item.concept || item.stem || "question")}`;
}

function makeQuestionVariant(item = {}, topic = currentTopic) {
  const variantNumber = Number(localStorage.getItem("ani-standard-variant-counter") || "0") + 1;
  localStorage.setItem("ani-standard-variant-counter", String(variantNumber));
  const concept = item.concept || "the same NCLEX priority";
  const skill = String(item.skill || "clinical judgment");

  return {
    ...item,
    id: `${standardQuestionId(item, topic)}-variant-${variantNumber}`,
    stem: `A different client presents with cues testing ${concept} in ${topic}. Use the same ${skill.toLowerCase()} priority from this item, but treat the scenario as new: ${item.stem}`
  };
}

function hasTopicSignal(input = "") {
  return /\b(pharm|pharmacology|med|drug|cardiac|heart|respiratory|copd|asthma|endocrine|dka|diabetic|neuro|stroke|seizure|icp|gcs|glasgow|complex|critical|icu|adult health|sepsis|shock|maternal|newborn|postpartum|pregnan|pediatric|pediatrics|peds|child|infant|fundamentals|delegat|priority|prioritization|pathophys)\b/i.test(normalizeIntentText(input));
}

function hasClinicalSignal(input = "") {
  const lower = normalizeIntentText(input);
  return hasTopicSignal(lower)
    || /\b(nurse|nursing|client|patient|symptom|assessment|intervention|diagnosis|lab|labs|vitals|vital signs|bp|hr|rr|spo2|oxygen|airway|breathing|circulation|perfusion|infection|pain|risk|safety|protocol|treatment|therapy|side effect|adverse|contraindication|indication|dose|hold|notify|provider|priority|expected|unexpected|electrolyte|potassium|sodium|calcium|magnesium|glucose|insulin|thyroid storm|myxedema|thrombolytic|anticoagulation|heparin|warfarin|aspirin|alteplase|tpa|lactate|map|vasopressor)\b/i.test(lower);
}

function isBareTopicSelection(input = "", hasTaskRequest = false) {
  const cleaned = input.trim();
  return Boolean(cleaned)
    && !hasTaskRequest
    && hasTopicSignal(cleaned)
    && cleaned.split(/\s+/).length <= 4
    && !hasQuestionShape(cleaned)
    && !/\b(what|why|how|explain|teach|lecture|question|quiz|test|practice|drill|answer|rationale)\b/i.test(cleaned);
}

function wantsClinicalExplanation(input = "") {
  const lower = normalizeIntentText(input);
  return hasClinicalSignal(input)
    && /\b(what is|what'?s|why|how|explain|tell me about|talk me through|walk me through|remind me|define|difference between|compare|does that mean|meaning of)\b/i.test(lower)
    && !asksForQuestionNow(input);
}

function isHeartBlockLectureTopic(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(?:heart\s*blocks?|av\s*blocks?|a\s*v\s*blocks?|atrioventricular\s*blocks?|first[-\s]?degree\s*(?:av\s*)?blocks?|second[-\s]?degree\s*(?:av\s*)?blocks?|third[-\s]?degree\s*(?:av\s*)?blocks?|complete\s*(?:heart|av)?\s*blocks?|mobitz|wenckebach)\b/i.test(lower);
}

function isAntiarrhythmicLectureTopic(input = "") {
  return /\b(?:anti.?arrhyth|antidysrhyth|dysrhythmia meds?|arrhythmia meds?|class\s*(?:i|ii|iii|iv)\b)/i.test(normalizeIntentText(input));
}

function normalizeLectureLookupText(input = "") {
  return normalizeOfflineLookupText(input, { dropLookupWords: true })
    .replace(/\b(lecture|mode|rant|lesson|lesson plan|teaching|teach|talk|talking|go|over|cover|covers|covered|focus|focused|deep|dive|walk|through)\b/gi, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function hasPathologyLectureCue(input = "") {
  return /\b(disease|condition|syndrome|disorder|failure|shock|crisis|injury|infection|anemia|anaemia|deficiency|insufficiency|cancer|leukemia|lymphoma|sepsis|diabetes|dka|hhs|pneumonia|asthma|copd|stroke|seizure|preeclampsia|hellp)\b/i.test(normalizeIntentText(input));
}

function hasMedicationLectureCue(input = "") {
  return /\b(drug|med|medication|pharm|pharmacology|dose|side effect|adverse|black box|boxed warning|interaction|contraindication|class|mechanism|antidote)\b/i.test(normalizeIntentText(input));
}

function lectureDirectCandidate(input = "", type = "") {
  const lookup = normalizeLectureLookupText(input) || input;
  const sharedIdentity = resolveEncyclopediaIdentity(lookup, { mode: "navigate", limit: 8 });
  if (sharedIdentity.mayAutoOpen && sharedIdentity.preferred?.type === type) {
    return {
      type,
      item: sharedIdentity.preferred.item,
      score: sharedIdentity.matchKind === "reviewed-prefix" ? 3900 : 3720,
      exactIdentity: sharedIdentity.matchKind === "exact-identity",
      reviewedPrefixIdentity: sharedIdentity.matchKind === "reviewed-prefix",
      sharedIdentityResolution: true
    };
  }
  const suggestions = offlineLookupSuggestions(lookup);
  return suggestions.find((candidate) => (
    candidate.type === type
    && candidate.ambiguousIdentity !== true
    && (candidate.clinicalClueMatch !== true || candidate.mayAutoOpen === true)
    && (candidate.nearIdentity === true
      || (inputDirectlyNamesOfflineCandidate(lookup, candidate)
        && offlineLookupIsDirectEnough(lookup, candidate)))
  )) || null;
}

function lectureTextMentionsTopic(topic = "", text = "") {
  const cleanTopic = normalizePharmText(topic);
  const cleanText = normalizePharmText(text);
  if (!cleanTopic || !cleanText) return true;
  if (cleanText.includes(cleanTopic)) return true;
  const topicTokens = cleanTopic
    .split(" ")
    .filter((token) => token.length >= 4 && !["disease", "syndrome", "condition", "disorder"].includes(token));
  if (!topicTokens.length) return true;
  const needed = topicTokens.length >= 2 ? topicTokens : topicTokens.slice(0, 1);
  return needed.every((token) => cleanText.includes(token));
}

function pathologyLectureDetails(disease = {}) {
  const name = safeText(disease.name) || "the condition";
  const signs = pathologyListText(disease.signsSymptoms);
  const diagnostics = pathologyListText(disease.diagnostics);
  const treatments = pathologyListText(disease.treatments);
  const priorities = pathologyListText(disease.nursingPriorities);
  const complications = pathologyListText(disease.complications);
  const traps = pathologyListText(disease.nclexTraps);

  return {
    label: name,
    frame: `${safeText(disease.pathology) || `${name} is a disease process the nurse studies by linking the underlying pathology to assessment cues, risk, and priority action.`}`,
    patho: `${disease.etiology ? `Etiology/risk factors: ${disease.etiology}` : "Start with the cause, then ask what body system is failing and what the nurse can detect first."} Key clinical cues include: ${signs || "abnormal assessment findings, unstable trends, and expected versus unexpected symptoms."}`,
    nclex: `NCLEX cares about ${name} because it tests recognition of cues, priority nursing actions, complications, diagnostics, safety, and what finding requires escalation.`,
    trapSummary: traps ? `Common NCLEX trap: ${traps}.` : `Do not memorize ${name} as a label. Tie the label to the client danger pattern and the first nursing action.`,
    details: [
      diagnostics && `Diagnostics and assessment clues: ${diagnostics}.`,
      treatments && `Treatment direction: ${treatments}.`,
      priorities && `Priority nursing actions: ${priorities}.`,
      complications && `Complications to monitor: ${complications}.`,
      traps && `Common NCLEX trap: ${traps}.`
    ].filter(Boolean).join(" "),
    redirect: `For ${name}, drill this sequence: identify the pathology, cluster the assessment cues, protect immediate safety, anticipate diagnostics/treatment, and monitor whether the client is improving or deteriorating.`
  };
}

function normalizeLectureTopic(input = "") {
  const cleaned = input
    .replace(/\b(lecture mode|lecture|rant|teach me|talk about|explain|go over|focus on|start lecture|start a lecture|lesson plan)\b\s*:?\s*/gi, " ")
    .replace(/^\s*[:,-]*\s*(?:hey|hi|hello|yo)\s*,?\s*(?:ani|annie)\s*,?\s*/i, "")
    .replace(/\b(?:can|could|would)\s+you\b/gi, "")
    .replace(/\b(?:please|brief(?:ly)?|summary|summarize|tell me|tell us|give me|what is|what's|could you tell me|about|on)\b/gi, " ")
    .replace(/^\s*[:,-]+\s*/g, "")
    .replace(/[?.!]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (offlineDoseUnitExpressionOnly(cleaned || input)) {
    return cleaned || currentTopic;
  }
  if (isHeartBlockLectureTopic(input) || isHeartBlockLectureTopic(cleaned)) {
    return "Atrioventricular heart blocks";
  }
  if (isAntiarrhythmicLectureTopic(input) || isAntiarrhythmicLectureTopic(cleaned)) {
    return "Antiarrhythmic medication classes";
  }
  const lookup = normalizeLectureLookupText(input) || cleaned;
  const directTopicResolution = resolveTopicRequest(cleaned || input, {
    mode: "suggest",
    limit: 8,
    allowClinicalClues: false
  });
  const lookupTopicResolution = resolveTopicRequest(lookup, { mode: "suggest", limit: 8 });
  const directSharedIdentity = directTopicResolution.identity;
  const sharedIdentity = directSharedIdentity.mayAutoOpen || directSharedIdentity.suppressUnrelatedMatches === true
    ? directSharedIdentity
    : lookupTopicResolution.identity;
  if (sharedIdentity.suppressUnrelatedMatches === true) {
    return cleaned || currentTopic;
  }
  if (sharedIdentity.mayAutoOpen && sharedIdentity.preferred?.item) {
    return sharedIdentity.preferred.type === "drug"
      ? pharmDrugDisplayName(sharedIdentity.preferred.item)
      : safeText(sharedIdentity.preferred.item.displayName || sharedIdentity.preferred.item.name || cleaned || currentTopic);
  }
  const directReviewedResolution = directTopicResolution.reviewed;
  const lookupReviewedResolution = lookupTopicResolution.reviewed;
  const normalizedLookupConfirmsDirectReviewedTarget = Boolean(
    lookupReviewedResolution?.mayAutoOpen
      && directReviewedResolution?.preferred?.item
      && lookupReviewedResolution.preferred?.item
      && directReviewedResolution.preferred.type === lookupReviewedResolution.preferred.type
      && directReviewedResolution.preferred.item === lookupReviewedResolution.preferred.item
  );
  // Preserve an exact reviewed route before lecture lookup normalization can
  // remove identity-bearing punctuation. A normalized lecture lookup may
  // still promote the same bound target when the raw wording was treated as
  // a personal narrative, but it may never substitute a different target.
  const reviewedResolution = lookupReviewedResolution?.mayAutoOpen
    && (!directReviewedResolution?.candidates.length || normalizedLookupConfirmsDirectReviewedTarget)
    ? lookupReviewedResolution
    : directReviewedResolution?.candidates.length
      ? directReviewedResolution
      : lookupReviewedResolution;
  if (reviewedResolution?.mayAutoOpen && reviewedResolution.preferred?.item) {
    return reviewedResolution.preferred.type === "drug"
      ? pharmDrugDisplayName(reviewedResolution.preferred.item)
      : safeText(reviewedResolution.preferred.item.displayName
        || reviewedResolution.preferred.item.name
        || cleaned
        || currentTopic);
  }
  if (reviewedResolution?.candidates.length) {
    return cleaned || currentTopic;
  }
  const clinicalResolution = lookupTopicResolution.clinical
    || clinicalSearchIntelligence(lookup, { limit: 4 });
  if (clinicalResolution.mayAutoOpen && clinicalResolution.preferred?.item) {
    return safeText(clinicalResolution.preferred.item.displayName
      || clinicalResolution.preferred.item.name
      || cleaned
      || currentTopic);
  }
  if (clinicalResolution.candidates.length) {
    // A plausible but insufficiently separated clue match is a choice, not a
    // lecture identity. Do not let older broad drug/pathology scorers replace
    // that explicit uncertainty with a different auto-selected topic.
    return cleaned || currentTopic;
  }
  const directPathology = lectureDirectCandidate(lookup, "pathology");
  const directDrug = lectureDirectCandidate(lookup, "drug");
  if (directDrug?.item?.name && (!directPathology || (hasMedicationLectureCue(lookup) && !hasPathologyLectureCue(lookup)))) {
    return pharmDrugDisplayName(directDrug.item);
  }
  if (directPathology?.item?.name && (!directDrug || hasPathologyLectureCue(lookup) || !hasMedicationLectureCue(lookup))) {
    return directPathology.item.name;
  }
  if (!lookup.includes(" ") && !sharedIdentity.mayAutoOpen) {
    // Short fragments and ordinary words may display suggestions, but lecture
    // mode must not convert a body-text coincidence into the lecture topic.
    return cleaned || currentTopic;
  }
  const medicationMatch = bestPharmMatch(lookup, { requireIdentityMatch: true })
    || bestPharmMatch(input, { requireIdentityMatch: true })
    || bestPharmMatch(cleaned, { requireIdentityMatch: true });
  if (medicationMatch?.name && !directPathology && !hasPathologyLectureCue(lookup)) {
    return medicationMatch.name;
  }
  const pathologyMatch = bestPathologyMatch(lookup) || bestPathologyMatch(input) || bestPathologyMatch(cleaned);
  if (pathologyMatch?.name && !directDrug && !/\b(drug|med|medication|pharm|class|dose|side effect|black box|boxed warning|interaction)\b/i.test(cleaned)) {
    return pathologyMatch.name;
  }
  if (medicationMatch?.name && !/\b(lab|range|urine output|map|anion gap)\b/i.test(cleaned)) {
    return medicationMatch.name;
  }
  return cleaned || currentTopic;
}

function lectureDetails(topic) {
  const lookupTopic = normalizeLectureLookupText(topic) || topic;
  const lower = lookupTopic.toLowerCase();
  const sharedIdentity = resolveEncyclopediaIdentity(lookupTopic, { mode: "suggest", limit: 8 });
  const suppressBareContentMatch = sharedIdentity.suppressUnrelatedMatches === true
    || (!lookupTopic.includes(" ") && !sharedIdentity.mayAutoOpen);
  const pathologyMatch = suppressBareContentMatch ? null : (bestPathologyMatch(lookupTopic) || bestPathologyMatch(topic));
  const matchedDrug = suppressBareContentMatch ? null : (bestPharmMatch(lookupTopic, { requireIdentityMatch: true })
    || bestPharmMatch(topic, { requireIdentityMatch: true }));
  const pathologyCandidate = pathologyMatch ? { type: "pathology", item: pathologyMatch, score: 999 } : null;
  const drugCandidate = matchedDrug ? { type: "drug", item: matchedDrug, score: 999 } : null;
  const pathologyDirect = pathologyCandidate && inputDirectlyNamesOfflineCandidate(lookupTopic, pathologyCandidate);
  const drugDirect = drugCandidate && inputDirectlyNamesOfflineCandidate(lookupTopic, drugCandidate);

  if (isHeartBlockLectureTopic(topic)) {
    return {
      label: "Atrioventricular heart blocks",
      frame: "Heart blocks are conduction delays or interruptions between the atria and ventricles, usually at or below the AV node. The nurse reads the rhythm by asking: **Are P waves present, is every P followed by a QRS, is the PR interval stable, and are the atria and ventricles communicating?**",
      patho: "**First-degree AV block** is delayed conduction: every P wave conducts, but the PR interval is longer than 0.20 seconds. **Second-degree Type I, Mobitz I/Wenckebach** is progressively slower AV conduction until one QRS drops. **Second-degree Type II, Mobitz II** drops QRS complexes without progressive PR lengthening, which is more dangerous. **Third-degree, or complete heart block,** means atria and ventricles are electrically dissociated.",
      nclex: "NCLEX tests whether you identify the danger level. **First-degree and Mobitz I are often monitored if stable. Mobitz II and third-degree heart block are high-risk rhythms because they can reduce cardiac output and require pacing.**",
      details: "Spotting them: first-degree has a constant PR interval greater than 0.20 seconds with no dropped QRS. Mobitz I has a PR interval that gets longer, longer, longer, then drops a QRS. Mobitz II has sudden dropped QRS complexes with a PR interval that is usually constant in conducted beats. Third-degree has AV dissociation: P waves and QRS complexes march independently. Medication causes matter: beta blockers, diltiazem, verapamil, digoxin, amiodarone, and some electrolyte/ischemia problems can worsen conduction. **Question AV-nodal blockers in symptomatic bradycardia or high-grade AV block unless a pacer/specialist plan is in place.**",
      redirect: "For heart blocks, repeat the nursing sequence: check symptoms and perfusion, read P-QRS-PR relationships, identify the block, hold/clarify unsafe AV-nodal drugs, prepare pacing for unstable Mobitz II or third-degree block, and monitor for improved cardiac output."
    };
  }

  if (isAntiarrhythmicLectureTopic(topic)) {
    return {
      label: "Antiarrhythmic medication classes",
      frame: "Antiarrhythmics are rhythm-control medications that change cardiac electrical conduction. For NCLEX, keep the four classic Vaughan Williams buckets separate: **Class I sodium-channel blockers**, **Class II beta blockers**, **Class III potassium-channel blockers**, and **Class IV non-dihydropyridine calcium-channel blockers**.",
      patho: "**Class I** slows fast sodium influx and affects depolarization, so think conduction slowing and QRS/proarrhythmia risk. **Class II** reduces sympathetic stimulation at the SA/AV node, so think slower rate, lower automaticity, and AV-node slowing. **Class III** prolongs potassium-mediated repolarization, so think longer QT and torsades risk. **Class IV** slows AV-node calcium conduction, so think rate control for selected supraventricular rhythms plus bradycardia/heart block risk.",
      nclex: "NCLEX usually does not ask you to recite every subclass. It asks whether the nurse catches rhythm danger, bradycardia, hypotension, QT prolongation, heart block, electrolyte triggers, and interactions with other rate-slowing or QT-prolonging drugs.",
      details: "Class I examples: procainamide, flecainide, propafenone, lidocaine. Class II examples: metoprolol, propranolol, esmolol. Class III examples: amiodarone, sotalol, dofetilide, ibutilide. Class IV examples: diltiazem and verapamil. Adenosine is important for PSVT but is not one of the four classic classes; keep it as an AV-nodal emergency medication with a very short half-life.",
      redirect: "The board-safe sequence is: identify rhythm and stability, check perfusion, check ECG/QT/heart rate/BP, check potassium and magnesium, look for AV block, then question unsafe combinations."
    };
  }

  if (pathologyMatch && (pathologyDirect || (!drugDirect && hasPathologyLectureCue(lookupTopic)))) {
    return pathologyLectureDetails(pathologyMatch);
  }

  if (isNavigationOnlyGeneratedMedicationClass(matchedDrug)
    && (drugDirect || hasMedicationLectureCue(lookupTopic))) {
    const classPathway = pharmClassPathwayText(matchedDrug);
    const examples = normalizeMedicationClassExampleNames(matchedDrug.classExampleNames || []).join(", ");
    return {
      label: pharmDrugDisplayName(matchedDrug),
      frame: generatedMedicationClassNavigationDescription(matchedDrug.generatedClassSegment, matchedDrug.classExampleNames),
      patho: "This generated entry is a navigation index, not a reviewed class-level clinical teaching profile.",
      nclex: "No class-wide NCLEX, mechanism, safety, monitoring, or administration teaching is published for this index. Open an exact linked medication card for drug-specific guidance.",
      details: [
        classPathway && `Specific class / pathway: ${classPathway}.`,
        examples && `Linked medication examples: ${examples}.`
      ].filter(Boolean).join(" "),
      redirect: "Choose an individual linked medication card before studying indications, mechanism, warnings, interactions, monitoring, or nursing actions."
    };
  }

  if (matchedDrug && !matchedDrug.expandedIndex && (drugDirect || hasMedicationLectureCue(lookupTopic))) {
    const essentials = pharmListText(matchedDrug.nursingEssentials);
    const interactions = pharmListText(matchedDrug.interactions);
    const contraindications = pharmListText(matchedDrug.contraindications);
    const traps = pharmListText(matchedDrug.nclexTraps);
    const labs = pharmListText(matchedDrug.keyLabs);
    const uses = pharmUsedToTreat(matchedDrug);
    return {
      label: matchedDrug.name,
      frame: `${matchedDrug.name} is ${matchedDrug.class}. It is commonly used for: ${uses || "its labeled indication"}. Start there: class, mechanism, major safety warnings, and the nursing assessments that decide whether it is safe to give.`,
      patho: matchedDrug.mechanism || "Connect the medication to the body system it changes, then ask what can become unsafe if that effect is too strong, too weak, or paired with the wrong client condition.",
      nclex: `NCLEX cares about ${matchedDrug.name} because medication questions test safety before memorization: contraindications, interactions, adverse effects, hold parameters, teaching, and what to monitor before and after administration.`,
      details: [
        pharmBoxedWarningDisplay(matchedDrug),
        uses && `Used to treat/common uses: ${uses}`,
        contraindications && `Contraindications/clarify-before-giving: ${contraindications}`,
        essentials && `Key nursing concepts: ${essentials}`,
        interactions && `Interactions to watch: ${interactions}`,
        labs && `Labs/assessment: ${labs}`,
        traps && `Common NCLEX trap: ${traps}`
      ].filter(Boolean).join(" "),
      redirect: `For ${matchedDrug.name}, drill this sequence: identify the class, know the dangerous interaction/contraindication, assess the client, give or hold safely, then monitor for the expected therapeutic response and the most dangerous adverse effect.`
    };
  }

  if (/thyroid storm|graves/.test(lower)) {
    return {
      label: "Thyroid storm",
      frame: "Thyroid storm is a life-threatening hypermetabolic crisis from extreme excess thyroid hormone effect. Think fever, severe tachycardia, agitation, vomiting or diarrhea, hypertension early, possible heart failure, and altered mental status.",
      patho: "The body is essentially stuck with the metabolic gas pedal down. Increased beta-adrenergic sensitivity drives tachycardia, hyperthermia, increased oxygen demand, fluid loss, and cardiovascular strain.",
      nclex: "NCLEX wants you to recognize fever plus severe tachycardia plus neuro or GI changes as more than anxiety. Priorities are airway, breathing, circulation, cooling, cardiac monitoring, IV fluids, and prescribed antithyroid and beta-blocking therapy.",
      details: "Do not confuse thyroid storm with myxedema coma. Thyroid storm is hot, fast, restless, and hypermetabolic. Myxedema coma is cold, slow, lethargic, and hypometabolic.",
      redirect: "If a stem gives Graves disease with fever, confusion, vomiting, and a very high heart rate, treat it like an endocrine emergency."
    };
  }

  if (/\bdka\b|diabetic ketoacidosis|ketoacidosis|potassium.*insulin|insulin.*potassium/.test(lower)) {
    return {
      label: "DKA potassium safety",
      frame: "DKA is not just high glucose. It is insulin deficiency causing hyperglycemia, ketosis, acidosis, dehydration, and dangerous electrolyte shifts.",
      patho: "Even when serum potassium looks normal or high at first, total body potassium is depleted from osmotic diuresis and vomiting. When insulin is started, potassium shifts into cells and the serum level can drop fast.",
      nclex: "NCLEX loves the safety move: check potassium before and during insulin therapy. If potassium is very low, potassium replacement comes before continuing insulin because hypokalemia can cause lethal dysrhythmias.",
      details: "The trap is chasing glucose while ignoring potassium. Glucose is loud, but potassium is what can suddenly kill the client during treatment.",
      redirect: "For DKA questions, read glucose, pH or bicarbonate, potassium, mental status, hydration, and rhythm together."
    };
  }

  if (/glasgow|gcs/.test(lower)) {
    return {
      label: "Glasgow Coma Scale",
      frame: "GCS is a standardized neurologic assessment that scores eye opening, verbal response, and motor response. The total ranges from 3 to 15, and the trend matters more than one lonely number.",
      patho: "It is not diagnosing the cause of altered level of consciousness. It is quantifying arousal and cortical/brainstem response so you can detect deterioration, communicate clearly, and prioritize airway protection.",
      nclex: "NCLEX loves the pieces: eye 4, verbal 5, motor 6. It also loves the safety implication: a GCS of 8 or less means the airway is in danger and the client may need advanced airway support.",
      details: "Motor response is weighted heavily because it is often the best neurologic predictor: obeys commands, localizes pain, withdraws, abnormal flexion, extension, none. For intubated clients, document verbal as not testable rather than inventing a score.",
      redirect: "Before we return, lock this in: if the score drops by 2 or more, if pupils change, or if motor response worsens, that is not a cute little charting detail. That is notify, reassess ABCs, prepare escalation."
    };
  }

  if (/neuro|stroke|brain|intracranial|complex adult/.test(lower)) {
    return {
      label: topic,
      frame: "Complex adult neuro is about perfusion, oxygenation, intracranial dynamics, and level of consciousness. ANI rule: neuro is quiet until it is not, so subtle change is a loud finding.",
      patho: "Start with cerebral perfusion pressure: CPP is MAP minus ICP. If ICP climbs or MAP falls, brain tissue gets less oxygenated blood. That gives altered LOC, headache, vomiting, pupil changes, motor changes, and eventually Cushing physiology.",
      nclex: "NCLEX tests early signs first: new confusion, restlessness, decreased LOC, slurred speech, unequal grips, pupil change, seizure precautions, aspiration risk, and airway protection. Glasgow Coma Scale belongs here because it gives you a reproducible way to trend neuro status.",
      details: "Stroke care adds time: last known well, glucose check, CT before thrombolytics, dysphagia screen before PO intake, BP parameters, anticoagulant history, and rapid escalation. Seizure care adds safety, lateral positioning, timing, oxygen, suction, and postictal assessment.",
      redirect: "Big nooks and crannies: do not cluster neuro checks so aggressively that you miss respiratory decline, do not give oral meds before swallow screening, and do not treat a late Cushing triad as an early warning sign."
    };
  }

  if (/complex|critical|icu|shock|sepsis|multi.?system|hemodynamic|ventilator|vasopressor|lactate|map|deteriorat/.test(lower)) {
    return {
      label: topic,
      frame: "Complex care is the NCLEX zone where one client has several systems tugging on each other at once. Think oxygenation, perfusion, neurologic status, renal output, infection, labs, and whether interventions are working.",
      patho: "The big mechanism is compensation turning into decompensation. A client may maintain pressure until vasodilation, capillary leak, dysrhythmia, hypoxemia, bleeding, acidosis, or fluid shifts overwhelm perfusion. Then you see altered LOC, falling MAP, low urine output, rising lactate, worsening work of breathing, or unstable rhythm.",
      nclex: "NCLEX loves complex care because it tests synthesis: who is unstable, what trend matters, what action comes first, what can be delegated, what order is expected, and when to escalate. Prioritize airway, breathing, circulation, safety, then acute changes and failed response to treatment.",
      details: "Watch MAP under 65, urine output under 30 mL/hr, rising lactate, new confusion, escalating oxygen needs, chest pain, dysrhythmias, fresh bleeding, and hypotension after fluids. Those cues beat routine pain, teaching, discharge, or chronic-but-stable problems.",
      redirect: "Do not answer complex care from a single lab. Build the movie: baseline, current trend, intervention already tried, response, and what can kill the client fastest."
    };
  }

  const data = getTopicData(topic);
  return {
    label: topic,
    frame: `Start ${topic} by naming the body system involved, the client safety threat, and the nursing assessment that proves whether the client is stable or deteriorating.`,
    patho: data.rationale,
    nclex: `NCLEX applicability is high when ${topic} touches prioritization, adverse effects, delegation, teaching, ABCs, perfusion, oxygenation, medication holds, or unexpected findings.`,
    details: `${data.trap} Tie every fact to a nursing action: assess, hold, position, oxygenate, isolate, notify, teach, or evaluate response.`,
    redirect: `For boards, do not memorize ${topic} as trivia. Convert it into cues, risks, interventions, and patient teaching.`
  };
}

function lectureList(items = []) {
  return items
    .filter(Boolean)
    .map((item) => `- ${item}`)
    .join("\n");
}

function lectureCareMap(topic = "", details = {}) {
  const lower = topic.toLowerCase();
  const trapLead = details.trapSummary || details.details;
  const map = {
    diagnostics: [
      "**Focused assessment first:** airway, breathing, circulation, pain, mental status, vital signs, oxygenation, perfusion, and trend from baseline.",
      "**Diagnostic tools:** choose labs/imaging/tests that explain the pathophysiology, not just random data collection.",
      "**Trend matters:** one abnormal value is a snapshot; a worsening trend is the movie NCLEX wants you to see."
    ],
    firstActions: [
      "**First nursing action:** assess the client in front of you, stabilize ABCs, verify safety, and identify whether this is acute deterioration.",
      "**If unstable:** call for help early, stay with the client, prepare oxygen/monitoring/IV access, and notify the provider or rapid response per acuity.",
      "**Do not delay safety:** hold unsafe meds, keep NPO when aspiration/procedure risk exists, and use precautions immediately when indicated."
    ],
    priorityActions: [
      "**Prioritize airway, breathing, circulation, safety, acute change, and unstable trends before teaching or routine care.**",
      "**Cluster cues:** vital signs, labs, assessment, medication risks, and response to prior treatment should agree with your priority.",
      "**Escalate when treatment is failing:** worsening mentation, oxygen needs, urine output, MAP, rhythm, bleeding, or lactate is not a wait-and-see finding."
    ],
    treatment: [
      "**Collaborative treatment:** expect orders that reverse the cause, support perfusion/oxygenation, prevent complications, and evaluate response.",
      "**Nursing treatment role:** administer safely, monitor before/during/after, catch contraindications, and question unsafe orders.",
      "**Patient teaching comes after stabilization** unless the client is stable and education is the actual priority."
    ],
    monitor: [
      "**Improvement looks like:** better mental status, safer vital signs, less work of breathing, improved pain, stable rhythm, adequate urine output, and labs trending toward normal.",
      "**If the client does not improve after the expected intervention, that is new data. Reassess and escalate.**",
      "**Document trends clearly:** what you saw, what you did, how the client responded, and who was notified."
    ],
    traps: [
      trapLead,
      "**NCLEX trap:** do not pick the answer that explains the disease but does nothing for the immediate safety problem.",
      "**NCLEX trap:** do not normalize abnormal findings just because the diagnosis makes them possible."
    ],
    repeat: [
      "**Drill this in:** assess first when unstable or unclear.",
      "**Drill this in:** stabilize before teaching.",
      "**Drill this in:** trends beat isolated numbers.",
      "**Drill this in:** if a medication is unsafe, hold and clarify before harm happens."
    ]
  };

  if (isHeartBlockLectureTopic(topic)) {
    map.diagnostics = [
      "**Rhythm strip method:** find P waves, find QRS complexes, measure PR intervals, then ask whether every P conducts to a QRS.",
      "**First-degree AV block:** PR interval is greater than 0.20 seconds and stays consistent; every P wave still has a QRS.",
      "**Mobitz I/Wenckebach:** PR interval gets progressively longer until a QRS drops.",
      "**Mobitz II:** conducted beats usually have a constant PR, but QRS complexes suddenly drop. This is a high-risk rhythm.",
      "**Third-degree/complete heart block:** P waves and QRS complexes are independent. Atria and ventricles are not talking to each other."
    ];
    map.firstActions = [
      "**First nursing actions:** assess the client, not just the rhythm strip: pulse, blood pressure, mental status, chest pain, dyspnea, dizziness/syncope, skin signs, and perfusion.",
      "**If symptomatic or unstable:** call for help, apply oxygen if needed, place on cardiac monitor/defibrillator pads per protocol, obtain IV access, and prepare pacing.",
      "**Medication safety first:** hold and clarify AV-nodal blockers such as beta blockers, diltiazem, verapamil, digoxin, or amiodarone if the client is bradycardic, hypotensive, or in high-grade block."
    ];
    map.priorityActions = [
      "**First-degree stable:** monitor, assess meds/electrolytes/ischemia, and report new symptoms or worsening conduction.",
      "**Mobitz I stable:** monitor and look for reversible causes; treat if symptomatic.",
      "**Mobitz II:** treat as dangerous because it can progress to complete heart block. Prepare transcutaneous pacing and anticipate a pacemaker plan.",
      "**Third-degree block:** this is an emergency if symptomatic or poorly perfusing. Prepare pacing and urgent provider/rapid response involvement."
    ];
    map.treatment = [
      "**Collaborative treatment:** remove reversible causes, correct potassium/magnesium abnormalities as ordered, review AV-nodal medications, treat ischemia, and prepare pacing when indicated.",
      "**Atropine nuance:** atropine may help symptomatic bradycardia from nodal blocks, but it may not fix Mobitz II or complete heart block because the problem can be below the AV node.",
      "**Pacing:** transcutaneous pacing is a bridge for unstable high-grade block; transvenous or permanent pacemaker therapy may follow depending cause and persistence."
    ];
    map.monitor = [
      "**Improvement:** stronger pulse, improved blood pressure/MAP, improved mentation, less dizziness/syncope, less chest pain/dyspnea, and a rhythm that supports cardiac output.",
      "**Worsening:** hypotension, syncope, altered mental status, ischemic chest pain, heart failure signs, widening QRS escape rhythm, or progression to more dropped beats/complete block.",
      "**Trend PR interval and dropped beats** because a rhythm can evolve from mild delay into higher-grade block."
    ];
    map.traps = [
      "**NCLEX trap:** first-degree heart block is not dropped beats. It is delayed conduction with a long PR interval.",
      "**NCLEX trap:** Mobitz I gets longer, longer, longer, then drops. Mobitz II drops without that warning pattern.",
      "**NCLEX trap:** do not reassure yourself because the client is awake if Mobitz II or complete block is present. Ask whether cardiac output is safe.",
      "**NCLEX trap:** do not give another AV-nodal blocker to a client already in symptomatic bradycardia or high-grade AV block unless the order is clearly safe/specialist-directed."
    ];
    map.repeat = [
      "**Repeat it slowly: first-degree is long PR, no dropped QRS.**",
      "**Repeat it again: Mobitz I gets longer, longer, longer, then drops.**",
      "**Repeat it again: Mobitz II suddenly drops QRS complexes and is dangerous.**",
      "**Repeat it again: third-degree means P waves and QRS complexes are independent, so prepare pacing if perfusion is poor.**"
    ];
  } else if (/\b(aplastic anemia|bone marrow failure|pancytopenia)\b/.test(lower)) {
    map.diagnostics = [
      "**Core diagnostic pattern:** pancytopenia: low RBCs/Hgb, low WBCs or ANC, and low platelets from failed marrow production.",
      "**Reticulocyte count is low** because the marrow is not responding properly.",
      "**Bone marrow biopsy** shows hypocellular marrow/fatty replacement and helps distinguish aplastic anemia from leukemia, myelodysplasia, nutritional anemia, or hemolysis.",
      "**Trend CBC with differential, ANC, platelets, Hgb/Hct, infection signs, and bleeding signs together.**"
    ];
    map.firstActions = [
      "**First nursing actions:** assess ABCs, oxygenation, chest pain/dyspnea, fatigue, fever, bleeding, bruising, petechiae, and vital-sign stability.",
      "**Fever is urgent when neutropenic.** Do not wait for dramatic infection signs; escalate per protocol.",
      "**Start safety precautions early:** neutropenic precautions and bleeding precautions when counts are low."
    ];
    map.priorityActions = [
      "**Priority danger 1: infection.** Low neutrophils can make infection subtle but life-threatening.",
      "**Priority danger 2: bleeding.** Low platelets mean petechiae, mucosal bleeding, GI bleeding, and hemorrhage risk.",
      "**Priority danger 3: poor oxygen delivery.** Low Hgb can cause dyspnea, tachycardia, chest pain, syncope, and activity intolerance.",
      "**Avoid rectal temperatures, IM injections, aspirin/NSAIDs, and unnecessary invasive procedures** when platelets are low unless specifically ordered."
    ];
    map.treatment = [
      "**Collaborative treatment:** remove suspected trigger if possible, transfuse RBCs/platelets when ordered, treat fever/infection rapidly, and support marrow recovery or replacement.",
      "**Severe/selected cases:** immunosuppression such as antithymocyte globulin plus cyclosporine, or hematopoietic stem cell transplant if eligible.",
      "**Nursing role:** administer blood products safely, monitor for transfusion reactions, protect from infection/bleeding, and teach urgent red flags."
    ];
    map.monitor = [
      "**Improvement:** rising or stabilizing ANC, platelets, and Hgb/Hct; fewer infections; less bleeding; better activity tolerance; improved oxygenation/perfusion.",
      "**Worsening:** fever, chills, hypotension, new petechiae/bruising, epistaxis/gum bleeding, black stools, increasing fatigue, dyspnea, chest pain, or falling CBC counts.",
      "**Watch for transfusion complications** and iron overload risk if repeated transfusions are needed."
    ];
    map.traps = [
      "**NCLEX trap:** do not treat aplastic anemia like iron-deficiency anemia. The problem is bone marrow production failure.",
      "**NCLEX trap:** fever in neutropenia is a priority even if the client looks 'okay.'",
      "**NCLEX trap:** bleeding plus infection plus fatigue points to pancytopenia, not three unrelated complaints.",
      "**NCLEX trap:** low reticulocytes tell you the marrow is not compensating."
    ];
    map.repeat = [
      "**Repeat it slowly: aplastic anemia equals marrow failure.**",
      "**Repeat it again: marrow failure causes pancytopenia.**",
      "**Repeat it again: pancytopenia means anemia plus infection risk plus bleeding risk.**",
      "**Repeat it again: fever or bleeding gets priority attention.**"
    ];
  } else if (/\bdka\b|diabetic ketoacidosis|ketoacidosis|potassium.*insulin|insulin.*potassium/.test(lower)) {
    map.diagnostics = [
      "**Pathology clue:** insulin deficiency causes ketosis, acidosis, dehydration, and total-body potassium depletion.",
      "**Diagnostics:** glucose, serum/urine ketones or beta-hydroxybutyrate, pH, bicarbonate, anion gap, potassium, BUN/creatinine, mental status, and hydration.",
      "**ECG/telemetry matters** when potassium is abnormal or IV insulin/electrolyte replacement is running."
    ];
    map.firstActions = [
      "**First nursing actions:** assess airway/breathing/circulation, mental status, hydration, IV access, glucose, and potassium.",
      "**Start fluids as prescribed** because dehydration and perfusion problems are immediate.",
      "**Check potassium before insulin. Repeat that: check potassium before insulin.**"
    ];
    map.priorityActions = [
      "**If potassium is dangerously low, potassium replacement comes before continuing insulin** because insulin can worsen hypokalemia.",
      "**Use continuous monitoring** for unstable potassium, altered LOC, severe acidosis, or dysrhythmia risk.",
      "**Watch cerebral edema risk** especially in younger clients or overly rapid shifts."
    ];
    map.treatment = [
      "**Treatment sequence:** IV fluids, potassium-safe insulin therapy, electrolyte replacement, identify trigger, close glucose/anion-gap monitoring.",
      "**Collaborative care:** insulin infusion, potassium replacement protocol, antiemetics/antibiotics if indicated, and transition to subcutaneous insulin when criteria are met.",
      "**Do not stop insulin too early:** the anion gap must close, not just the glucose number."
    ];
    map.monitor = [
      "**Improvement:** closing anion gap, rising bicarbonate/pH, safer potassium, improving mental status, improving perfusion, adequate urine output.",
      "**Glucose falling alone is not enough.** DKA resolves when acidosis and ketone production resolve.",
      "**Recheck often:** glucose, potassium, anion gap, neurologic status, intake/output, and rhythm."
    ];
    map.traps = [
      "**NCLEX trap:** chasing glucose while ignoring potassium.",
      "**NCLEX trap:** assuming a normal/high initial potassium means the body has enough potassium.",
      "**NCLEX trap:** stopping insulin because glucose improved while acidosis continues."
    ];
    map.repeat = [
      "**Repeat it slowly: DKA is glucose plus ketones plus acidosis plus dehydration plus potassium danger.**",
      "**Repeat it again: check potassium before insulin.**",
      "**Repeat it again: glucose improvement is not the same as DKA resolution.**"
    ];
  } else if (/thyroid storm|graves/.test(lower)) {
    map.diagnostics = [
      "**Pathology clue:** extreme thyroid hormone effect creates a hypermetabolic crisis.",
      "**Findings:** high fever, severe tachycardia, agitation/confusion, vomiting/diarrhea, tremor, diaphoresis, hypertension early, possible heart failure.",
      "**Diagnostics:** TSH/free T4 support the diagnosis, but treatment is clinical when the client is crashing. Also watch ECG, glucose, electrolytes, liver function, and temperature."
    ];
    map.firstActions = [
      "**First nursing actions:** ABCs, cardiac monitoring, temperature reduction, IV access, fluids as prescribed, and rapid provider/rapid response escalation.",
      "**Reduce stimulation** and protect from injury while hyperadrenergic.",
      "**Do not treat it like anxiety** when fever and severe tachycardia are present."
    ];
    map.priorityActions = [
      "**Priority:** control hyperthermia, support circulation, prevent dysrhythmias, and administer prescribed antithyroid/beta-blocking therapy safely.",
      "**Watch heart failure and dysrhythmias** because the metabolic demand is extreme.",
      "**Medication nuance:** iodine is usually given after antithyroid medication when ordered, not before."
    ];
    map.treatment = [
      "**Treatment:** beta blocker, antithyroid medication, iodine after antithyroid therapy when prescribed, glucocorticoids, cooling, fluids, oxygen/supportive care.",
      "**Nursing role:** monitor response, adverse effects, contraindications, temperature, rhythm, perfusion, and mental status.",
      "**Collaborative care** may include ICU-level monitoring."
    ];
    map.monitor = [
      "**Improvement:** lower temperature, slower heart rate, calmer mentation, improved BP/perfusion, decreased GI losses, stable rhythm.",
      "**Worsening:** confusion, chest pain, heart failure signs, hypotension, persistent fever, or dysrhythmia.",
      "**Trend vitals frequently** because this condition can pivot fast."
    ];
    map.traps = [
      "**NCLEX trap:** confusing thyroid storm with myxedema coma.",
      "**NCLEX trap:** waiting for labs before acting on a crashing clinical picture.",
      "**NCLEX trap:** missing that fever plus tachycardia plus mental status/GI symptoms is an endocrine emergency."
    ];
    map.repeat = [
      "**Repeat it: thyroid storm is hot, fast, restless, and dangerous.**",
      "**Repeat it: cool, monitor the heart, give ordered antithyroid therapy, and escalate.**",
      "**Repeat it: myxedema is cold and slow; thyroid storm is hot and fast.**"
    ];
  } else if (/glasgow|gcs/.test(lower)) {
    map.diagnostics = [
      "**Diagnostic tool:** GCS scores eye opening, verbal response, and motor response.",
      "**Range:** 3 to 15. Eye is 4, verbal is 5, motor is 6.",
      "**Trend matters more than a lonely score.** A drop is deterioration until proven otherwise."
    ];
    map.firstActions = [
      "**First nursing actions:** assess ABCs, LOC, pupils, motor response, glucose if altered, and compare to baseline.",
      "**If the score is low or dropping, protect airway and escalate.**",
      "**Document what you can and cannot test, especially if intubated.**"
    ];
    map.priorityActions = [
      "**GCS 8 or less means airway danger.** Prepare for advanced airway support per protocol.",
      "**New pupil change, worsening motor response, or decreasing LOC is not routine.**",
      "**Neuro checks are trend tools, not box-checking rituals.**"
    ];
    map.treatment = [
      "**Treatment depends on cause:** hypoglycemia, stroke, seizure, ICP, intoxication, infection, trauma, or hypoxia all need different follow-through.",
      "**Nursing role:** keep oxygenation/perfusion safe while the team identifies the cause.",
      "**Prevent secondary injury:** avoid hypoxia, hypotension, aspiration, and delayed escalation."
    ];
    map.monitor = [
      "**Improvement:** higher or stable GCS, better orientation, stronger motor response, stable pupils, protected airway.",
      "**Deterioration:** drop of 2 or more, new unequal pupils, abnormal posturing, vomiting, seizure, or worsening LOC.",
      "**Repeat neuro assessment consistently** so the trend is meaningful."
    ];
    map.traps = [
      "**NCLEX trap:** treating GCS as a diagnosis. It is an assessment score.",
      "**NCLEX trap:** ignoring airway implications of a low score.",
      "**NCLEX trap:** inventing a verbal score for an intubated client instead of documenting not testable."
    ];
    map.repeat = [
      "**Repeat it: eye 4, verbal 5, motor 6.**",
      "**Repeat it: GCS 8 or less means airway risk.**",
      "**Repeat it: trend beats one isolated score.**"
    ];
  } else if (/neuro|stroke|brain|intracranial|complex adult/.test(lower)) {
    map.diagnostics = [
      "**Findings:** new confusion, decreased LOC, slurred speech, pupil change, unequal grips, seizure, vomiting, headache, abnormal posturing.",
      "**Diagnostic tools:** GCS, NIH stroke scale when appropriate, glucose, CT before thrombolytic pathway, swallow screen before PO intake, pupil/motor trends.",
      "**Pathology lens:** cerebral perfusion depends on oxygenation, MAP, ICP, glucose, and vascular patency."
    ];
    map.firstActions = [
      "**First nursing actions:** ABCs, glucose if acute neuro change, last known well if stroke symptoms, rapid neuro assessment, safety, and escalation.",
      "**Keep NPO until swallow screen** when stroke or impaired LOC is possible.",
      "**Protect airway and seizure safety** before education or routine tasks."
    ];
    map.priorityActions = [
      "**Priority:** preserve oxygenation and cerebral perfusion.",
      "**Stroke priority:** time, glucose, CT, BP parameters, anticoagulant screen, thrombolytic/thrombectomy eligibility.",
      "**ICP priority:** head midline, HOB per protocol, avoid hypoxia/hypotension, trend LOC, prepare ordered osmotic therapy."
    ];
    map.treatment = [
      "**Treatment varies by cause:** thrombolytic/thrombectomy pathway, seizure meds, ICP management, oxygen/ventilation, glucose correction, infection treatment.",
      "**Nursing role:** catch deterioration early and keep the client safe while definitive treatment happens.",
      "**Do not give oral meds/food** until swallowing and LOC are safe."
    ];
    map.monitor = [
      "**Improvement:** stable or improved LOC/GCS, symmetric pupils, stronger motor response, safe swallow, stable oxygenation/perfusion.",
      "**Worsening:** lower GCS, new pupil asymmetry, Cushing signs, seizure, aspiration, worsening weakness/speech.",
      "**Monitor trends** because neuro decline can be subtle before it becomes catastrophic."
    ];
  } else if (/complex|critical|icu|shock|sepsis|multi.?system|hemodynamic|ventilator|vasopressor|lactate|map|deteriorat/.test(lower)) {
    map.diagnostics = [
      "**Findings:** altered LOC, rising oxygen needs, hypotension, MAP under goal, low urine output, rising lactate, dysrhythmias, cool/mottled skin, bleeding.",
      "**Diagnostic tools:** serial vitals, MAP, lactate, ABG/VBG, CBC, CMP, cultures, ECG, urine output, chest imaging, response to fluid/oxygen/medications.",
      "**Pathology lens:** compensation is failing when perfusion, oxygenation, renal output, or mentation worsen."
    ];
    map.firstActions = [
      "**First nursing actions:** ABCs, call for help, oxygen/monitoring, IV access, rapid focused assessment, verify code/rapid response criteria.",
      "**Do not leave an unstable client alone.**",
      "**Report trends, not vibes:** BP/MAP, HR, RR, SpO2, LOC, urine output, lactate, rhythm, and what was already tried."
    ];
    map.priorityActions = [
      "**Priority:** restore oxygen delivery and perfusion.",
      "**If fluids fail and shock persists, anticipate vasopressors per protocol.**",
      "**Treat source and support organs:** antibiotics/source control for sepsis, blood for hemorrhage, ventilation for respiratory failure, etc."
    ];
    map.treatment = [
      "**Treatment:** oxygen/ventilation, fluids, vasopressors, antibiotics/source control, blood products, dysrhythmia management, renal support depending cause.",
      "**Nursing role:** titrate/monitor ordered therapies, watch IV sites, reassess frequently, and catch treatment failure.",
      "**Safety:** medication compatibility, line access, fall/skin/aspiration precautions, and clear escalation."
    ];
    map.monitor = [
      "**Improvement:** MAP at goal, urine output at least about 30 mL/hr in adults, mentation improving, lactate trending down, oxygen needs stabilizing, rhythm stable.",
      "**Worsening:** new confusion, falling BP/MAP, escalating oxygen, low urine output, rising lactate, chest pain, bleeding, dysrhythmia.",
      "**Trend response after each intervention.**"
    ];
  } else if (isAntiarrhythmicLectureTopic(topic)) {
    map.diagnostics = [
      "**Before any antiarrhythmic:** assess stability first. Unstable rhythm signs are hypotension, altered mental status, ischemic chest pain, shock, acute heart failure, or severe respiratory distress.",
      "**Diagnostics:** rhythm strip/12-lead ECG, heart rate, blood pressure, QTc, QRS width, PR interval, potassium, magnesium, renal function, liver function for selected meds, and medication list.",
      "**Class sorting:** Class I affects sodium/depolarization, Class II is beta blockade, Class III prolongs repolarization/QT, Class IV slows AV-node calcium conduction."
    ];
    map.firstActions = [
      "**First nursing actions:** check the client, not just the monitor. Assess pulse, perfusion, mentation, chest pain, dyspnea, BP, and rhythm.",
      "**If unstable:** call for help and prepare synchronized cardioversion or defibrillation depending rhythm/pulse per protocol.",
      "**Hold and clarify** if severe bradycardia, hypotension, high-grade AV block, prolonged QT, or dangerous electrolyte abnormality is present."
    ];
    map.priorityActions = [
      "**Class I priority:** watch QRS widening, proarrhythmia, hypotension, and neurologic toxicity depending medication.",
      "**Class II priority:** beta blockers can cause bradycardia, hypotension, bronchospasm in susceptible clients, and mask hypoglycemia symptoms.",
      "**Class III priority:** QT prolongation and torsades risk. Potassium and magnesium matter a lot.",
      "**Class IV priority:** diltiazem/verapamil can worsen bradycardia, AV block, hypotension, and heart failure in vulnerable clients."
    ];
    map.treatment = [
      "**Treatment depends on rhythm and stability:** medication is not always first if the client is unstable.",
      "**Collaborative care:** ECG monitoring, electrolyte replacement, antiarrhythmic administration, cardioversion/defibrillation readiness, and underlying-cause treatment.",
      "**Medication nuance:** amiodarone has multi-class effects and long-term lung, thyroid, liver, eye/skin, and interaction issues."
    ];
    map.monitor = [
      "**Improvement:** safer rhythm, adequate BP/MAP, better mentation, less chest pain/dyspnea, stable QTc/QRS/PR, potassium and magnesium corrected.",
      "**Worsening:** syncope, hypotension, new heart block, severe bradycardia, wide QRS, prolonged QT, torsades, or worsening heart failure.",
      "**Trend after each dose** because antiarrhythmics can create new rhythm problems while treating the old one."
    ];
    map.traps = [
      "**NCLEX trap:** giving another AV-nodal blocker to a client already bradycardic or in high-grade block.",
      "**NCLEX trap:** forgetting potassium and magnesium before QT-prolonging rhythm meds.",
      "**NCLEX trap:** treating stable and unstable dysrhythmias the same way.",
      "**NCLEX trap:** assuming adenosine is one of the four classes; it is high-yield, but it sits outside that classic four-class frame."
    ];
    map.repeat = [
      "**Repeat it: Class I sodium, Class II beta blocker, Class III potassium/QT, Class IV calcium AV node.**",
      "**Repeat it again: unstable rhythm means electricity/protocol escalation beats slow medication pondering.**",
      "**Repeat it again: antiarrhythmics can cause arrhythmias, so ECG and electrolytes are not optional background noise.**"
    ];
  }

  return map;
}

function formatLecture(topic, options = {}) {
  const details = lectureDetails(topic);
  const intro = options.returning
    ? `Back to the original lecture: ${details.label}.`
    : options.redirect
      ? `Good interruption. We are zooming in on ${details.label}.`
      : `**Lecture mode:** ${details.label}. We are going slow, building the concept like a nurse, and repeating the essentials on purpose.`;
  const careMap = lectureCareMap(topic, details);

  return `${intro}

**1. Pathophysiology - what is actually happening**
${details.frame}

${details.patho}

**Repeat this core idea:** ${details.redirect}

**2. Findings and diagnostic tools**
${lectureList(careMap.diagnostics)}

**3. Treatment plan - first nursing actions**
${lectureList(careMap.firstActions)}

**4. Treatment plan - priority nursing actions**
${lectureList(careMap.priorityActions)}

**5. Collaborative treatment and nursing role**
${lectureList(careMap.treatment)}

**6. What to monitor to show improvement**
${lectureList(careMap.monitor)}

**7. Common NCLEX traps**
${lectureList(careMap.traps)}

**8. Nooks and crannies nurses should know**
${details.details}

**Drill-it-in repetition**
${lectureList(careMap.repeat)}

**Instructor checkpoint:** Let me know if you have questions, want to zoom into one piece, want a practice question from this lecture, or want me to return to the original lecture.`;
}

function makeFocusedExplanation(input = "") {
  const detail = lectureDetails(input);

  return `Focused answer: ${detail.label}\n\nPlain English: ${detail.frame}\n\nClinical depth: ${detail.patho}\n\nNCLEX applicability: ${detail.nclex}\n\nTighten-up point: ${detail.redirect}`;
}

function handleLectureInput(input) {
  const lower = input.toLowerCase();

  if (lectureState.awaitingChoice && /back|return|original|resume/.test(lower) && lectureState.parkedTopic) {
    lectureState.currentTopic = lectureState.parkedTopic;
    lectureState.parkedTopic = "";
    lectureState.awaitingChoice = true;
    return formatLecture(lectureState.currentTopic, { returning: true });
  }

  if (lectureState.awaitingChoice && /that'?s all|all for today|done|stop|wrap/.test(lower)) {
    lectureState.active = false;
    lectureState.awaitingChoice = false;
    const topic = lectureState.currentTopic || lectureState.originalTopic || "today's topic";
    lectureState.currentTopic = "";
    lectureState.originalTopic = "";
    lectureState.parkedTopic = "";
    return `You got it. We will pause the lecture here.\n\nQuick closing note: for ${topic}, keep sorting facts into assessment cues, pathophysiology, priority actions, and NCLEX traps. That is how you turn a huge topic into testable nursing judgment.`;
  }

  const topic = normalizeLectureTopic(input);
  if (!lectureState.active) {
    lectureState.originalTopic = topic;
    lectureState.currentTopic = topic;
    lectureState.parkedTopic = "";
    lectureState.active = true;
    lectureState.awaitingChoice = true;
    return formatLecture(topic);
  }

  if (lectureState.awaitingChoice && /question|why|how|what|when|where|can you|could you/.test(lower) && topic.length < 80) {
    return `${makeFocusedExplanation(input)}\n\nLecture checkpoint: any other questions, would you like me to get back to the original lecture, or will that be all for today?`;
  }

  lectureState.parkedTopic = lectureState.currentTopic || lectureState.originalTopic;
  lectureState.currentTopic = topic;
  lectureState.awaitingChoice = true;
  return formatLecture(topic, { redirect: true });
}

function wantsLectureContinuation(input = "") {
  const lower = normalizeIntentText(input);
  if (!lectureState.active || !lectureState.awaitingChoice) {
    return false;
  }
  return /\b(back|return|original|resume|that'?s all|all for today|done|stop|wrap|question|why|how|what|when|where|zoom|focus|go deeper|explain|clarify)\b/i.test(lower)
    || (hasClinicalSignal(input) && hasQuestionShape(input));
}

function shouldBypassLectureForFreshQuestion(input = "") {
  if (!input?.trim()) {
    return false;
  }

  return asksForQuestionNow(input)
    || isClearFreshQuestionRequest(input)
    || wantsDefaultStandardQuestion(input)
    || wantsRandomPracticeRequest(input)
    || wantsStandardQuestionGeneration(input)
    || wantsGenericPracticeProblem(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || shouldChooseQuestionTypeForUser(input);
}

function shouldHandleLectureMode(input = "") {
  if (shouldBypassLectureForFreshQuestion(input) && !wantsLecture(input)) {
    return false;
  }
  return lectureModePrimed || wantsLecture(input) || wantsLectureContinuation(input);
}

function lecturePromptForModel(input = "", localDraft = "") {
  const topic = normalizeLectureTopic(input);
  return `Student asked for ANI Lecture Mode on: ${topic}

Produce a full nursing lecture script that follows this exact teaching flow:
1. Pathophysiology - start with what is happening in the body.
2. Findings and diagnostic tools.
3. Treatment plan - first nursing actions.
4. Treatment plan - priority nursing actions.
5. Collaborative treatment and nursing role.
6. What to monitor to show improvement.
7. Common NCLEX traps.
8. Nooks and crannies all nurses should know.
9. Drill-it-in repetition.

Style requirements:
- Be deep but teach slowly.
- Build enough content for an audio lecture, not a short chat answer. Aim for a complete, paced lesson unless the student explicitly asks for brief.
- Stay strictly on the requested topic. If the topic is heart blocks, cover first-degree AV block, Mobitz I/Wenckebach, Mobitz II, and third-degree/complete heart block. Do not switch to antiarrhythmic drugs, albuterol, bronchodilators, or another nearby cardiac topic except as a brief safety caution.
- Do not quote, restate, or role-play the student's prompt.
- Do not say "Hey ANI/Annie" or reference ANI as if the student sentence is part of the lesson.
- Start directly with useful clinical teaching. No fluffy setup.
- Repeat the most important safety essentials in plain language.
- Bold the must-know NCLEX information with **double asterisks**.
- Use nursing vocabulary but explain it cleanly.
- Include first nursing actions before collaborative treatment.
- Include priority nursing actions and what improvement looks like.
- Mention NCLEX traps and subtle nuances.
- End with an open invitation, not a pushy demand.

Local ANI lecture scaffold to preserve if useful:
${localDraft}`;
}

function hasCompleteLectureStructure(text = "") {
  const lower = text.toLowerCase();
  return [
    "pathophysiology",
    "findings",
    "diagnostic",
    "first nursing actions",
    "priority nursing actions",
    "monitor",
    "improvement",
    "nclex traps",
    "nooks",
    "repetition"
  ].every((term) => lower.includes(term));
}

function isLectureTopicAligned(topic = "", text = "") {
  const lowerTopic = normalizeIntentText(topic);
  const lowerText = normalizeIntentText(text);

  if (isHeartBlockLectureTopic(lowerTopic)) {
    const requiredSignals = [
      /first[-\s]?degree|1st[-\s]?degree|long\s+pr|prolonged\s+pr/i,
      /mobitz\s*i|wenckebach|type\s*i/i,
      /mobitz\s*ii|type\s*ii/i,
      /third[-\s]?degree|3rd[-\s]?degree|complete\s+(?:heart|av)?\s*block|av\s+dissociation/i
    ];
    const hasHeartBlockSignals = requiredSignals.every((pattern) => pattern.test(text));
    const hasOffTopicLead = /\b(albuterol|bronchodilator|asthma|copd|ssri|fluoxetine)\b/i.test(text.slice(0, 1200));
    return hasHeartBlockSignals && !hasOffTopicLead;
  }

  if (isAntiarrhythmicLectureTopic(lowerTopic)) {
    return /\bclass\s*i\b/i.test(text)
      && /\bclass\s*ii\b/i.test(text)
      && /\bclass\s*iii\b/i.test(text)
      && /\bclass\s*iv\b/i.test(text);
  }

  const lookupTopic = normalizeLectureLookupText(topic) || topic;
  const pathologyMatch = bestPathologyMatch(lookupTopic);
  if (pathologyMatch && inputDirectlyNamesOfflineCandidate(lookupTopic, { type: "pathology", item: pathologyMatch, score: 999 })) {
    return lectureTextMentionsTopic(pathologyMatch.name, text);
  }

  const drugMatch = bestPharmMatch(lookupTopic, { requireIdentityMatch: true });
  if (drugMatch && inputDirectlyNamesOfflineCandidate(lookupTopic, { type: "drug", item: drugMatch, score: 999 })) {
    return lectureTextMentionsTopic(drugMatch.name, text);
  }

  return true;
}

async function makeLectureModeResponse(input = "") {
  const localDraft = handleLectureInput(input);
  const lower = normalizeIntentText(input);
  if (/\b(that'?s all|all for today|done|stop|wrap)\b/i.test(lower)) {
    return localDraft;
  }

  const modelPrompt = lecturePromptForModel(input, localDraft);
  const adaptive = await requestAdaptiveTextResponse(modelPrompt, [], [], localDraft, {
    allowFallbackText: true,
    feature: "lecture_mode"
  });
  const unusable = !adaptive
    || /cannot reach|not configured|api key|quota|billing|server is running|try again/i.test(adaptive);
  if (unusable) {
    return localDraft;
  }
  if (/\bhey\s+(?:ani|annie)\b|student asked|could you tell me|the student asked/i.test(adaptive.slice(0, 900))) {
    return localDraft;
  }
  if (!/\*\*.+\*\*/.test(adaptive) || !hasCompleteLectureStructure(adaptive)) {
    return localDraft;
  }
  if (!isLectureTopicAligned(normalizeLectureTopic(input), adaptive)) {
    return localDraft;
  }
  return adaptive;
}

function questionRequestIntro(data, input = "") {
  const lower = normalizeIntentText(input);
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(data.difficulty || currentDifficulty)];
  const topic = data.topic || currentTopic;
  const complexAngle = /\b(complex|critical|icu|high acuity|adult health|mix it up)\b/i.test(input);
  const another = /\b(another|next|more)\b/i.test(input);

  if (!input.trim()) {
    return "";
  }

  if (topic === "Endocrine" && complexAngle) {
    return `I’ll make this one clinically layered.`;
  }

  if (/\bmix it up\b/i.test(lower)) {
    return `Mixing it up with a ${difficulty.toLowerCase()} item.`;
  }

  if (another) {
    return `Sure. Here is another ${difficulty.toLowerCase()} item.`;
  }

  return `Here is a ${difficulty.toLowerCase()} item.`;
}

function formatQuestion(data, input = "") {
  lastQuestion = data;
  rememberQuestionFormat("standard");
  rememberStandardCorrectLetter(data);
  rememberStandardQuestionSignature(data.stem);
  markActiveLearningContext("standard-question", {
    id: data.id || standardQuestionId(data, data.topic || currentTopic),
    topic: data.topic || currentTopic,
    title: data.concept || "NCLEX-style item"
  });
  setActiveExamContext("standard-question", data);
  const topicKeys = Object.keys(nclexBank);
  const questionTopic = data.topic || currentTopic;
  const questionDifficulty = normalizeQuestionDifficulty(data.difficulty || currentDifficulty);
  const dataTopicIndex = topicKeys.findIndex((topic) => topic === questionTopic || nclexBank[topic] === data);
  if (dataTopicIndex >= 0) {
    questionRotationIndex = dataTopicIndex;
  }
  currentTopic = questionTopic;
  saveDifficulty(questionDifficulty);
  updateFocus();

  const intro = questionRequestIntro(data, input);
  const question = standardQuestionReadableText(data, input);

  return {
    type: "standard-question",
    item: data,
    sourceInput: input,
    preface: intro,
    text: intro ? `${intro}\n\n${question}` : question,
    toString() {
      return this.text;
    }
  };
}

function standardQuestionReadableText(data = {}) {
  const questionDifficulty = normalizeQuestionDifficulty(data.difficulty || currentDifficulty);
  const optionLines = (data.options || [])
    .map((option, index) => `${optionLetter(index)}. ${option}`)
    .join("\n");

  return `NCLEX-style item: ${data.stem}\n\nDifficulty: ${difficultyLabels[questionDifficulty]}\nClinical judgment target: ${data.skill || "Recognize cues"}\n\n${optionLines}\n\nSelect the best answer.`;
}

function standardQuestionResultText(item = {}, selectedIndex = -1) {
  const correctIndex = (item.options || []).findIndex((option) => option === item.answer);
  const selectedOption = item.options?.[selectedIndex] || "";
  const correctLetter = optionLetter(correctIndex);
  const selectedLetter = optionLetter(selectedIndex);
  const isCorrect = selectedIndex === correctIndex;
  const lead = isCorrect
    ? `Correct. ${selectedLetter} is the best answer.`
    : `Not quite. You selected ${selectedLetter}: ${selectedOption}. The best answer is ${correctLetter}: ${item.answer}.`;

  return `${lead}\n\nRationale: ${item.rationale || "The correct answer follows NCLEX priority, safety, and clinical judgment logic."}\n\nNCLEX applicability: high. This is the kind of safety cue, priority cue, or mechanism cue the exam likes to test.\n\nNook-and-cranny detail: ${item.trap || "The trap is anchoring on a familiar cue without prioritizing the most urgent risk."}`;
}

function addStandardQuestionRationale(result, item = {}, selectedIndex = -1) {
  const correctIndex = (item.options || []).findIndex((option) => option === item.answer);
  const isCorrect = selectedIndex === correctIndex;
  result.hidden = false;
  result.textContent = "";

  const title = document.createElement("strong");
  title.textContent = isCorrect
    ? `Correct: ${optionLetter(correctIndex)}`
    : `Best answer: ${optionLetter(correctIndex)}`;

  const summary = document.createElement("p");
  summary.textContent = isCorrect
    ? "Clean clinical judgment."
    : `You selected ${optionLetter(selectedIndex)}. Read the distractor as a trap, then anchor back to the priority cue.`;

  const rationale = document.createElement("p");
  appendFormattedText(rationale, applyNclexEssentialMarkup(`Rationale: ${item.rationale || ""}`));

  const trap = document.createElement("p");
  appendFormattedText(trap, applyNclexEssentialMarkup(`Nook-and-cranny detail: ${item.trap || ""}`));

  result.append(title, summary, rationale, trap);
}

function gradeStandardQuestionCard(card, item = {}, selectedIndex = -1) {
  const buttons = Array.from(card.querySelectorAll(".standard-option-button"));
  const result = card.querySelector(".standard-result");
  const correctIndex = (item.options || []).findIndex((option) => option === item.answer);
  const selectedOption = item.options?.[selectedIndex] || "";
  const isCorrect = selectedIndex === correctIndex;

  buttons.forEach((button, index) => {
    button.disabled = true;
    button.classList.toggle("is-selected", index === selectedIndex);
    button.classList.toggle("is-correct", index === correctIndex);
    button.classList.toggle("is-incorrect", index === selectedIndex && !isCorrect);
  });

  lastQuestion = {
    ...item,
    topic: item.topic || currentTopic,
    difficulty: item.difficulty || currentDifficulty
  };
  updateActiveExamContextGrade(
    "standard-question",
    lastQuestion,
    {
      selectedOption,
      selectedLetter: optionLetter(selectedIndex),
      rawStudentAnswer: `${optionLetter(selectedIndex)}. ${selectedOption}`
    },
    {
      score: isCorrect ? 1 : 0,
      maxScore: 1,
      scoreText: `${isCorrect ? 1 : 0}/1`,
      isCorrect,
      correct: {
        option: item.answer,
        letter: optionLetter(correctIndex)
      },
      rationale: item.rationale || "",
      trap: item.trap || "",
      feedback: isCorrect ? "Correct final answer." : "Incorrect final answer."
    }
  );

  addStandardQuestionRationale(result, item, selectedIndex);
  const feedbackText = standardQuestionResultText(item, selectedIndex);
  rememberConversation("user", `Selected ${optionLetter(selectedIndex)}: ${selectedOption}`);
  rememberConversation("assistant", feedbackText);
  lastAssistantText = feedbackText;
  if (!aniMuted) {
    speak(feedbackText);
  }
  scrollChatToBottom();
}

function createStandardQuestionCard(item = {}) {
  const card = document.createElement("section");
  card.className = "standard-question-card";
  card.setAttribute("aria-label", "Standard NCLEX multiple-choice question");

  const header = document.createElement("div");
  header.className = "standard-question-header";
  const title = document.createElement("strong");
  title.textContent = "NCLEX-style item";
  const meta = document.createElement("span");
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(item.difficulty || currentDifficulty)];
  meta.textContent = `${difficulty} | ${item.skill || "Recognize cues"}`;
  header.append(title, meta);

  const stem = document.createElement("p");
  stem.className = "standard-question-stem";
  stem.textContent = item.stem || "Which nursing action is priority?";

  const options = document.createElement("div");
  options.className = "standard-options";
  (item.options || []).forEach((option, index) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "standard-option-button";
    button.dataset.optionIndex = String(index);

    const letter = document.createElement("span");
    letter.className = "standard-option-letter";
    letter.textContent = optionLetter(index);
    const text = document.createElement("span");
    text.className = "standard-option-text";
    text.textContent = option;

    button.append(letter, text);
    button.addEventListener("click", () => gradeStandardQuestionCard(card, item, index));
    options.append(button);
  });

  const result = document.createElement("div");
  result.className = "standard-result";
  result.hidden = true;

  card.append(header, stem, options, result);
  return card;
}

function addStandardQuestionMessage(response = {}) {
  const item = response.item || response;
  const readable = response.text || standardQuestionReadableText(item, response.sourceInput || "");
  markActiveLearningContext("standard-question", {
    id: item.id || standardQuestionId(item, item.topic || currentTopic),
    topic: item.topic || currentTopic,
    title: item.concept || "NCLEX-style item"
  });
  setActiveExamContext("standard-question", item);
  lastQuestion = item;

  const article = document.createElement("article");
  article.className = "message assistant";

  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva(readable);
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble standard-question-bubble";
  if (response.preface) {
    const intro = document.createElement("p");
    intro.className = "standard-question-intro";
    appendFormattedText(intro, applyNclexEssentialMarkup(response.preface));
    bubble.append(intro);
  }
  bubble.append(createStandardQuestionCard(item));

  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, readable);
  chatLog.append(article);
  scrollChatToBottom();

  rememberConversation("assistant", readable);
  lastAssistantText = readable;
  if (!aniMuted) {
    speak(`I built you a standard NCLEX item. Select the best answer, then I will grade it and explain the rationale.`);
  }
}

function wantsNewQuestion(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(another|next|new|different|more)\b.{0,34}\b(question|item|quiz|nclex)\b/i.test(lower)
    || /\b(question|item|quiz|nclex)\b.{0,34}\b(another|next|new|different|more)\b/i.test(lower)
    || /\b(ask|give|hit)\s+me\s+(with\s+)?(one|another|a new|a different|the next)\b/i.test(lower);
}

function isContextRepairMessage(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(hold on|wait|pause|no|stop|actually|we were|we had|we just|you forgot|did you forget|already forget|do you remember|you lost|wrong question|not that question|the previous question|the last question|question before|first question|second question)\b/i.test(lower)
    && /\b(question|item|case|problem|stem|answer|rationale|topic|hepatitis|previous|last|before|doing|review)\b/i.test(lower);
}

function wantsRepeatReplacement(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(already|before|same|repeat|repeated|duplicate|had this|seen this|gave me this|asked me this)\b.{0,70}\b(question|item|problem|one|stem)\b/i.test(lower)
    || /\b(question|item|problem|stem)\b.{0,70}\b(already|before|same|repeat|duplicate|had this|seen this|gave me this)\b/i.test(lower)
    || /\b(i had this|i have had this|you gave me this|you already gave me|same one|same question|not new)\b/i.test(lower);
}

function wantsLecture(input = "") {
  return /\b(lecture|rant|teach me|walk me through|go over|deep dive|explain in depth|cover)\b/i.test(input);
}

function wantsRapidFire(input = "") {
  return /\b(rapid fire|drill me|challenge me|quick drill|speed round|flashcard|recall)\b/i.test(input);
}

function wantsBreakdown(input = "") {
  return /\b(break it down|simplify|plain english|explain that|what does that mean|i don'?t get|confused|clarify|why is that)\b/i.test(input);
}

function wantsTopicShift(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(i'?d rather|i rather|instead|switch|change|move|focus)\b/i.test(lower)
    && /\b(question|quiz|topic|lecture|practice|talk|focus|about|on)\b/i.test(lower);
}

function wantsTestFormatList(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(what|which|list|show|tell me|name)\b.{0,40}\b(test|tests|question|questions|item|items|format|formats|practice problem|practice problems)\b.{0,40}\b(have|available|can you do|can you make|types?|kinds?|options?)\b/i.test(lower)
    || /\b(what|which)\s+(?:types?|kinds?)\s+of\s+(?:tests?|questions?|items?|practice problems?)\b/i.test(lower)
    || /\b(test|question|item|practice)\s+formats?\b/i.test(lower);
}

function wantsGenericPracticeProblem(input = "") {
  const lower = normalizeIntentText(input);
  if (shouldChooseQuestionTypeForUser(input)) {
    return false;
  }
  if (wantsSameQuestionTypeFollowup(input)) {
    return false;
  }
  if (wantsDefaultStandardQuestion(input)) {
    return false;
  }

  const asksForPractice = /\b(make|create|give|write|generate|start|do|try|practice)\b.{0,60}\b(practice problem|practice question|practice item|problem|question|item|quiz)\b/i.test(lower)
    || /\b(can|could|would)\s+you\b.{0,60}\b(practice problem|practice question|practice item)\b/i.test(lower)
    || /^\s*(?:practice problem|practice question|practice item|quiz me|test me)\s*[\?.!]*\s*$/i.test(lower);
  const specifiesFormat = wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || shouldChooseQuestionTypeForUser(input)
    || wantsRapidFire(input)
    || /\b(multiple choice|mcq|standard question|single best|single answer|sata|select all|all that apply|bow[-\s]?tie|butterfly|case study|unfolding|ordering|drag|matrix|highlight|chart|notes|priority|procedure)\b/i.test(lower);
  const asksSpecificTopicQuestion = hasTopicSignal(lower)
    && /\b(question|item|quiz|problem)\b/i.test(lower)
    && !/\b(format|type|kind|which)\b/i.test(lower);

  return asksForPractice && !specifiesFormat && !asksSpecificTopicQuestion;
}

function wantsQuestionPickerComplaint(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(why|what|how come|no|stop|don'?t|do not|shouldn'?t|should not)\b.{0,90}\b(choose|pick|picker|menu|format|test type|question type)\b/i.test(lower)
    && /\b(already|told|said|asked|want|wanted|random|nclex|question|item|quiz|practice)\b/i.test(lower);
}

function wantsDefaultStandardQuestion(input = "") {
  const lower = normalizeIntentText(input);
  if (wantsAvoidStandardQuestionFormat(input) || shouldChooseQuestionTypeForUser(input)) {
    return false;
  }

  if (wantsExplicitAdvancedQuestionFormat(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || wantsUnfoldingCase(input)
    || wantsRapidFire(input)
    || wantsClassSpecificExam(input)
    || wantsTestFormatList(input)) {
    return false;
  }

  return wantsQuestionPickerComplaint(input)
    || /\b(random|one|single|just|another|next|new|fresh|any)\b.{0,60}\b(nclex|practice)?\s*(question|item|quiz|problem)\b/i.test(lower)
    || /\b(nclex|practice)\b.{0,60}\b(random|one|single|just|another|next|new|fresh|any)?\s*(question|item|quiz|problem)\b/i.test(lower)
    || /\b(ask|give|hit|quiz|test|challenge)\s+me\b/i.test(lower);
}

function isClearFreshQuestionRequest(input = "") {
  const lower = normalizeIntentText(input);
  const createQuestionRequest = /\b(?:give|make|create|generate|build|ask|hit)\s+(?:me\s+)?(?:with\s+)?(?:a\s+|an\s+|one\s+|another\s+|new\s+|fresh\s+|random\s+|hard\s+|normal\s+|easy\s+|next\s+|different\s+|standard\s+|nclex\s+|practice\s+){0,8}\b(?:question|item|case|quiz|problem)\b/i.test(lower)
    || /\b(?:question|item|case|quiz|problem)\b.{0,34}\b(?:please|pls|now|next|new|fresh|random|hard|normal|easy)\b/i.test(lower)
    || wantsNewQuestion(input)
    || wantsDefaultStandardQuestion(input);

  if (!createQuestionRequest) {
    return false;
  }

  return !/\b(?:previous|prior|earlier|last|old|above|ignored|disregarded|review|grade|graded|rationale|why|what did i|what was wrong|wrong with|correct|incorrect|choice\s+[abcd]|option\s+[abcd]|answer\s+(?:is|was)?\s*[abcd]|i\s+(?:choose|chose|pick|picked)\s+[abcd])\b/i.test(lower);
}

function testFormatListResponse(input = "") {
  const wantsPractice = wantsGenericPracticeProblem(input);
  const opener = wantsPractice
    ? "Before I build it, pick the format you want so I do not guess wrong."
    : "ANI can make several NCLEX/NGN-style test formats.";

  return `${opener}\n\nAvailable test formats:\n- Standard NCLEX multiple-choice: one best answer with full rationale.\n- Select all that apply (SATA): multiple correct choices, with cross-out elimination.\n- Cloze/drop-down sentence completion: fill in the safest clinical sentence with drop-down choices.\n- CJE butterfly/bow-tie: condition in the center, interventions on the wings, monitoring on the wings.\n- Full CJE case card: tabs for notes, vital signs, labs, collaborative care, and medication prescriptions.\n- Draggable ordering: organize clients by priority or put procedure steps in sequence.\n- Chart cue question: inspect notes/vitals/labs and pick the finding causing the most concern or the order to question.\n- Bullet/matrix: classify findings or interventions, including indicated/not indicated, expected/complication, improving/unchanged/deteriorating, and symptom-to-disease charts.\n- Highlight/time-chart item: select the time row or chart cue where the nurse should act or hold a med.\n- Full six-question ongoing case study: the same client evolves through six chart-tabbed questions with notes, vitals, labs, collaborative care, and prescriptions updating over time.\n- Condensed six-question ongoing case study: a faster version with shorter chart updates for quick drills.\n- Rapid fire: quick recall and prioritization drills.\n\nYou can say something like, "Give me a hard neuro SATA," "Make me a trach procedure ordering question," "Start a full neuro ongoing case," or "Give me a condensed sepsis case."`;
}

