const nursingClassNames = [
  "Fundamentals of Nursing",
  "Health Assessment",
  "Pathophysiology",
  "Pharmacology",
  "Med-Surge",
  "Mental Health Nursing",
  "Maternal-Newborn Nursing",
  "Pediatric Nursing",
  "Evidence-Based Practice",
  "Complex Adult Health Nursing",
  "Community Health Nursing",
  "Collaborative Healthcare",
  "Capstone"
];

function inferNursingClass(input = "") {
  const lower = input.toLowerCase();
  const matchers = [
    ["Fundamentals of Nursing", /fundamentals?/],
    ["Health Assessment", /health assessment|assessment class/],
    ["Pathophysiology", /pathophys|pathophysiology/],
    ["Pharmacology", /pharm|pharmacology/],
    ["Med-Surge", /med[-\s]?surge|medical surgical/],
    ["Mental Health Nursing", /mental health|psych/],
    ["Maternal-Newborn Nursing", /maternal|newborn|ob\b|postpartum|pregnan/],
    ["Pediatric Nursing", /pediatric|peds|child|infant/],
    ["Evidence-Based Practice", /evidence|ebp|research/],
    ["Complex Adult Health Nursing", /complex adult|complex health|adult health|critical care|icu/],
    ["Community Health Nursing", /community|public health/],
    ["Collaborative Healthcare", /collaborative|interprofessional/],
    ["Capstone", /capstone/]
  ];
  return matchers.find(([, pattern]) => pattern.test(lower))?.[0] || "";
}

function wantsClassSpecificExam(input = "") {
  const explicitClassCue = /\b(class[-\s]?specific|for my class|my class|course|midterm|final)\b/i.test(input);
  const namedClassCue = Boolean(inferNursingClass(input));
  const coreExamCue = /\b(exam|midterm|final|practice test|practice exam|nclex[-\s]?style exam|quiz|test me|class test|unit test)\b/i.test(input);
  const explicitBareTestCue = explicitClassCue && /\btest\b/i.test(input);
  const examCue = coreExamCue || explicitBareTestCue;
  const genericCjeOnly = /\b(cje|clinical judgment|ngn)\b/i.test(input) && !explicitClassCue && !namedClassCue;

  if (genericCjeOnly) {
    return false;
  }

  return examCue && (explicitClassCue || namedClassCue);
}

function classSpecificExamResponse(input = "") {
  const className = inferNursingClass(input);
  const systemsMentioned = /\b(neuro|cardiac|respiratory|endocrine|renal|gi|gastrointestinal|hematology|oncology|immune|musculoskeletal|reproductive|ob|peds|psych|mental health|infection|sepsis|shock|burns|trauma|perioperative)\b/i.test(input);
  const formatMentioned = wantsCjeChallenge(input) || wantsUnfoldingCase(input) || wantsAdvancedItem(input) || /\b(sata|multiple choice|standard|matrix|highlight|ordering|case study|bow[-\s]?tie|butterfly)\b/i.test(input);

  const classLine = className
    ? `Class: ${className}.`
    : `First, tell me which class this is for: ${nursingClassNames.join(", ")}.`;
  const systemsLine = systemsMentioned
    ? "I see at least one system/topic in your request."
    : "What systems or units are on the exam?";
  const formatLine = formatMentioned
    ? "I see the question format direction."
    : "Do you want standard NCLEX, SATA-heavy, drop-down/cloze, CJE/butterfly, ongoing case study, ordering/priority, matrix/highlight, or mixed?";

  return `I can build this like a class-targeted NCLEX exam instead of a random quiz.\n\n${classLine}\n${systemsLine}\n${formatLine}\n\nOnce I have those pieces, I will make it harder than a normal review set: direct concept checks, then multi-step clinical judgment items that force you to filter normal findings from concerning cues.`;
}

function buildTestPickerPrompt(testType, questionType) {
  const topic = currentTopic || "the current focus";
  const difficulty = difficultyLabels[normalizeQuestionDifficulty(currentDifficulty)] || "Hard";
  const testLabel = testType?.label || "NCLEX";
  const questionLabel = questionType?.label || "Standard MCQ";
  const baseRequest = questionType?.prompt
    ? `${questionType.prompt}${topic}`
    : `Give me a ${questionLabel} question on ${topic}`;

  if (testLabel === "Rapid Fire") {
    return `Rapid fire me with ${difficulty.toLowerCase()} ${questionLabel} prompts on ${topic}.`;
  }

  if (testLabel === "Class Exam" || testLabel === "Midterm / Final") {
    return `${baseRequest}. Make it ${testLabel.toLowerCase()} style for ${topic}, ${difficulty.toLowerCase()} difficulty, and use ANI's interactive template.`;
  }

  if (questionLabel === "Random Mix") {
    return `Surprise me with a hard NCLEX-style interactive question on ${topic}. Avoid the big picker and choose an appropriate format yourself.`;
  }

  if (testLabel === "CJE / NGN") {
    return `${baseRequest}. Make it CJE/NGN style, ${difficulty.toLowerCase()} difficulty, and use ANI's interactive template.`;
  }

  return `${baseRequest}. Make it ${testLabel} style, ${difficulty.toLowerCase()} difficulty, and use ANI's interactive template.`;
}

function createPickerOptionButton(option, groupName, pickerState, syncPickerState) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "test-picker-button";
  button.dataset.pickerGroup = groupName;
  button.textContent = option.label;
  button.setAttribute("aria-pressed", "false");
  button.addEventListener("click", () => {
    pickerState[groupName] = option;
    syncPickerState();
  });
  return button;
}

function appendPickerSection(card, titleText, options, groupName, pickerState, syncPickerState) {
  const section = document.createElement("section");
  section.className = "test-picker-section";
  const title = document.createElement("strong");
  title.textContent = titleText;
  const optionsWrap = document.createElement("div");
  optionsWrap.className = "test-picker-options";
  options.forEach((option) => {
    optionsWrap.append(createPickerOptionButton(option, groupName, pickerState, syncPickerState));
  });
  section.append(title, optionsWrap);
  card.append(section);
}

function addTestFormatPickerMessage(wantsPractice = false) {
  const article = document.createElement("article");
  article.className = "message assistant";
  const label = document.createElement("span");
  label.className = "message-label";
  label.textContent = "ANI";

  const row = document.createElement("div");
  row.className = "assistant-row";
  const miniAvatar = createMiniAva("Test format picker");
  miniAvatar.classList.toggle("is-muted", aniMuted);
  miniAvatar.setAttribute("aria-label", miniAvaActionLabel());
  miniAvatar.title = miniAvaActionLabel();
  miniAvatar.setAttribute("aria-pressed", String(aniMuted));

  const bubble = document.createElement("div");
  bubble.className = "bubble test-picker-bubble";
  const intro = document.createElement("p");
  intro.className = "advanced-intro";
  intro.textContent = "Pick one test type and one question type, then confirm. ANI will generate it directly in the interactive format.";

  const card = document.createElement("div");
  card.className = "test-picker-card";
  const pickerState = {
    testType: null,
    questionType: null
  };
  const status = document.createElement("p");
  status.className = "test-picker-status";
  status.textContent = "Choose a test type and question type.";
  const confirmButton = document.createElement("button");
  confirmButton.type = "button";
  confirmButton.className = "test-picker-confirm";
  confirmButton.textContent = "Confirm";
  confirmButton.disabled = true;
  const syncPickerState = () => {
    card.querySelectorAll(".test-picker-button").forEach((button) => {
      const group = button.dataset.pickerGroup;
      const selected = pickerState[group]?.label === button.textContent;
      button.classList.toggle("selected", selected);
      button.setAttribute("aria-pressed", String(selected));
    });
    confirmButton.disabled = !(pickerState.testType && pickerState.questionType);
    status.textContent = pickerState.testType && pickerState.questionType
      ? `${pickerState.testType.label} + ${pickerState.questionType.label}`
      : "Choose a test type and question type.";
  };
  confirmButton.addEventListener("click", () => {
    if (!pickerState.testType || !pickerState.questionType) {
      return;
    }
    const prompt = buildTestPickerPrompt(pickerState.testType, pickerState.questionType);
    const displayText = `${pickerState.testType.label} + ${pickerState.questionType.label}`;
    card.classList.add("is-submitted");
    card.querySelectorAll("button").forEach((button) => {
      button.disabled = true;
    });
    status.textContent = `Generating ${displayText}...`;
    voiceStatus.textContent = `Generating: ${pickerState.testType.label} + ${pickerState.questionType.label}`;
    sendUserMessage(prompt, { displayText });
  });
  appendPickerSection(card, "Test type", testTypeOptions, "testType", pickerState, syncPickerState);
  appendPickerSection(card, "Question type", questionTypeOptions, "questionType", pickerState, syncPickerState);
  card.append(status, confirmButton);
  syncPickerState();

  bubble.append(intro, card);
  row.append(miniAvatar, bubble);
  article.append(label, row);
  attachAssistantAccessibility(article, miniAvatar, bubble, "Test format picker");
  chatLog.append(article);
  scrollChatToBottom();

  const remembered = "ANI showed selectable test and question format options.";
  rememberConversation("assistant", remembered);
  lastAssistantText = remembered;
  speak("Pick one test type and one question type, then confirm.");
}

function retireOpenTestPickers(message = "Picker skipped because the chat moved on.") {
  document.querySelectorAll(".test-picker-card:not(.is-submitted):not(.is-retired)").forEach((card) => {
    card.classList.add("is-retired");
    card.querySelectorAll("button").forEach((button) => {
      button.disabled = true;
    });
    const status = card.querySelector(".test-picker-status");
    if (status) {
      status.textContent = message;
    }
  });
}

function normalizePharmText(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

