const SPOKEN_LETTER_VARIANTS = {
  a: ["a", "ay", "hey"],
  b: ["b", "bee", "be"],
  c: ["c", "see", "sea"],
  d: ["d", "dee"],
  e: ["e", "ee"],
  f: ["f", "eff", "ef"],
  g: ["g", "gee"],
  h: ["h", "aitch", "etch"],
  i: ["i", "eye"],
  j: ["j", "jay"],
  k: ["k", "kay"],
  l: ["l", "ell", "el"],
  m: ["m", "em"],
  n: ["n", "en", "enn", "in", "and"],
  o: ["o", "oh"],
  p: ["p", "pee"],
  q: ["q", "cue", "queue"],
  r: ["r", "are", "ar", "our"],
  s: ["s", "ess", "es"],
  t: ["t", "tee", "tea"],
  u: ["u", "you"],
  v: ["v", "vee"],
  w: ["w", "double u", "double you"],
  x: ["x", "ex"],
  y: ["y", "why"],
  z: ["z", "zee", "zed"]
};

function acronymSpacingPattern(acronym = "") {
  const clean = normalizePharmText(acronym).replace(/\s+/g, "");
  if (!clean || clean.length < 2) return null;
  const letters = clean.split("");
  const escapedLetters = letters.map((letter) => letter.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  const patterns = [escapedLetters.join("\\s+")];
  if (letters.length >= 4) {
    patterns.push(`${escapedLetters[0]}\\s+${escapedLetters.slice(1).join("")}`);
    patterns.push(`${escapedLetters.slice(0, -1).join("")}\\s+${escapedLetters.at(-1)}`);
    patterns.push(`${escapedLetters.slice(0, 2).join("\\s+")}\\s+${escapedLetters.slice(2).join("")}`);
  }
  return new RegExp(`\\b(?:${patterns.join("|")})\\b`, "gi");
}

function acronymPhoneticPattern(acronym = "") {
  const clean = normalizePharmText(acronym).replace(/\s+/g, "");
  if (!clean || clean.length < 2) return null;
  const letterPatterns = clean.split("").map((letter) => {
    const variants = SPOKEN_LETTER_VARIANTS[letter] || [letter];
    const escaped = variants
      .map((variant) => normalizePharmText(variant))
      .filter(Boolean)
      .map((variant) => variant
        .replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
        .replace(/\s+/g, "\\s+"));
    return `(?:${Array.from(new Set(escaped)).join("|")})`;
  });
  return new RegExp(`\\b${letterPatterns.join("\\s+")}\\b`, "gi");
}

const SPOKEN_ACRONYM_PATTERNS = SPOKEN_MEDICAL_ACRONYMS
  .flatMap((acronym) => [
    { acronym, pattern: acronymSpacingPattern(acronym) },
    { acronym, pattern: acronymPhoneticPattern(acronym) }
  ])
  .filter((entry) => entry.pattern);

function compactSpokenMedicalAcronyms(value = "") {
  let text = normalizePharmText(value);
  if (!text) return "";
  SPOKEN_ACRONYM_FIXUPS.forEach((replacement, phrase) => {
    text = text.replace(new RegExp(`\\b${phrase.replace(/\s+/g, "\\s+")}\\b`, "g"), replacement);
  });
  SPOKEN_ACRONYM_PATTERNS.forEach(({ acronym, pattern }) => {
    text = text.replace(pattern, acronym);
  });
  return text.replace(/\s+/g, " ").trim();
}

function applyLabSpellingFixups(value = "") {
  return safeText(value)
    .replace(/\bhematocrite\b/gi, "hematocrit")
    .replace(/\bhematacrit\b/gi, "hematocrit")
    .replace(/\bhemotocrit\b/gi, "hematocrit")
    .replace(/\bhaematocrit\b/gi, "hematocrit")
    .replace(/\bhemoglobn\b/gi, "hemoglobin")
    .replace(/\bhemogloben\b/gi, "hemoglobin")
    .replace(/\bhaemoglobin\b/gi, "hemoglobin")
    .replace(/\bplatlets?\b/gi, "platelets")
    .replace(/\bplatlet\b/gi, "platelet")
    .replace(/\bthrombocites?\b/gi, "thrombocytes")
    .replace(/\bleukocites?\b/gi, "leukocytes")
    .replace(/\bleucocites?\b/gi, "leukocytes")
    .replace(/\bneutrophils?\b/gi, "neutrophil")
    .replace(/\b(?:potasium|potassiums)\b/gi, "potassium")
    .replace(/\bsodiums\b/gi, "sodium")
    .replace(/\bmagnesum\b/gi, "magnesium")
    .replace(/\bphosporus\b/gi, "phosphorus")
    .replace(/\bbilrubin\b/gi, "bilirubin")
    .replace(/\balbumen\b/gi, "albumin");
}

function applyClinicalSpeechFixups(value = "") {
  let text = cleanSpeechTranscript(value);
  if (!text) return "";
  text = applyMedicationSpellingFixups(text);
  text = applyLabSpellingFixups(text);
  text = text
    .replace(/\b(?:diabetis|diabtes|diabeties|diebetes|diabetees)\b/gi, "diabetes")
    // Speech engines commonly return numbered diabetes identities as words.
    // Keep these replacements phrase-scoped so ordinary wording such as
    // "I have diabetes too" is never reclassified as type 2 diabetes.
    .replace(/\btype\s+(?:one|won)\s+diabet(?:es|ic)\b/gi, "type 1 diabetes")
    .replace(/\bdiabet(?:es|ic)\s+(?:type\s+)?(?:one|won)\b/gi, "diabetes type 1")
    .replace(/\btype\s+(?:two|too|to)\s+diabet(?:es|ic)\b/gi, "type 2 diabetes")
    .replace(/\bdiabet(?:es|ic)\s+(?:type\s+)?two\b/gi, "diabetes type 2")
    .replace(/\bdiabet(?:es|ic)\s+type\s+(?:too|to)\b/gi, "diabetes type 2")
    .replace(/\btype\s+three\s*c\s+diabet(?:es|ic)\b/gi, "type 3c diabetes")
    .replace(/\bdiabet(?:es|ic)\s+(?:type\s+)?three\s*c\b/gi, "diabetes type 3c")
    .replace(/\b(?:estimated\s+|e\s+)?gee\s+(?:eff|if|of|f)\s+(?:are|r)\b/gi, (match) => /^(?:estimated|e)\s/i.test(match) ? "eGFR" : "GFR")
    .replace(/\b(?:g|gee)\s+(?:f|eff|if|of)\s+(?:r|are|our)\b/gi, "GFR")
    .replace(/\b(?:g\s+r\s+f|grf|jeff\s+(?:are|r)|gfrs)\b/gi, "GFR")
    .replace(/\b(?:e\s+g\s+f\s+(?:r|are)|e\s+grf|eg\s+f\s+(?:r|are)|egfr\s+rate|estimated\s+g\s+f\s+r)\b/gi, "eGFR")
    .replace(/\bglomer(?:ula|ular|uller|ulars)?\s+(?:filter\s+asian|filteration|filter\s+ration|filtration|filtrate)\s+rate\b/gi, "glomerular filtration rate")
    .replace(/\b(?:global|glamorous|glamour|glom\s+air|glow\s+mirror|glow\s+maryland)\s+(?:filter|filtration)\s+rate\b/gi, "glomerular filtration rate")
    .replace(/\b(?:(?:seagal|seagull|segel|fecle|fecel|fecial|facial|feco|fecal)\s+)?(?:a\s+)?(?:cult|occult|ocult|occults?)\s+blood\s+test\b/gi, "fecal occult blood test")
    .replace(/\b(?:fico|fiko|fecle|fecel|fecial|facial|feco|fecal|seagal|seagull|segel)\s+(?:a\s+|the\s+|of\s+)?(?:cold|cult|called|caught|coat|coal|occult|ocult|occults?)\s+blood(?:\s+test)?\b/gi, "fecal occult blood test")
    .replace(/\b(?:a\s+|the\s+|of\s+)?cold\s+blood\s+test\b/gi, "fecal occult blood test")
    .replace(/\b(?:fico|fiko|fecle|fecel|fecial|facial|feco|fecal|seagal|seagull|segel)\s+(?:blood\s+stool|stool\s+blood)\s+test\b/gi, "fecal occult blood test")
    .replace(/\b(?:seagal|seagull|segel)\s+occult\s+blood\b/gi, "fecal occult blood")
    .replace(/\bstool\s+(?:a\s+)?(?:cult|occult|ocult)\s+blood\b/gi, "stool occult blood")
    .replace(/\bcooms?\b/gi, "Coombs")
    .replace(/\bcreatine\s+range\b/gi, "creatinine range")
    .replace(/\bcreatine\s+level\b/gi, "creatinine level")
    .replace(/\bcreatine\s+(?:clearance|clearence)\b/gi, "creatinine clearance")
    .replace(/\b(?:what is|find|show|open|range for|level for)\s+creatine\b/gi, (match) => match.replace(/creatine/i, "creatinine"))
    .replace(/\bpharmaco\s+kinetics\b/gi, "pharmacokinetics")
    .replace(/\b(?:pharma|pharm|farma|farmaco|pharmaco)\s+kinetics\b/gi, "pharmacokinetics")
    .replace(/\bpharmaco\s+dynamics\b/gi, "pharmacodynamics")
    .replace(/\b(?:pharma|pharm|farma|farmaco|pharmaco)\s+dynamics\b/gi, "pharmacodynamics")
    .replace(/\bbio\s+availability\b/gi, "bioavailability")
    .replace(/\bfirst\s+pass\s+(?:effect|metabolism)\b/gi, "first-pass metabolism")
    .replace(/\btherapeutic\s+(?:window|windows)\b/gi, "therapeutic index")
    .replace(/\b(?:m\s+i\s+c|em\s+eye\s+see|minimum\s+inhibitory\s+concentration)\b/gi, "minimum inhibitory concentration")
    .replace(/\bt\s+(?:greater\s+than|above|over)\s+mic\b/gi, "time-dependent killing")
    .replace(/\bpost\s+antibiotic\s+effect\b/gi, "post-antibiotic effect")
    .replace(/\bconcentration\s+dependent\s+killing\b/gi, "concentration-dependent killing")
    .replace(/\btime\s+dependent\s+killing\b/gi, "time-dependent killing")
    .replace(/\b(?:l\s+r\s+positive|lr\s+positive)\b/gi, "positive likelihood ratio")
    .replace(/\b(?:l\s+r\s+negative|lr\s+negative)\b/gi, "negative likelihood ratio")
    // These phrases are clinically specific to the Bipolar II card when no
    // lifetime manic episode is named. Canonicalizing them prevents generic
    // depression content from outranking the dedicated subtype entry.
    .replace(/\b(?:bipolar|major|recurrent)\s+depression\s+with\s+hypomania\b/gi, "Bipolar II disorder");
  return applyMedicationSpellingFixups(applyLabSpellingFixups(compactSpokenMedicalAcronyms(text)));
}

