function isLikelyLabOnlyLookup(input = "") {
  if (/\b(dermatome\s+map|cranial\s+nerve\s+map)\b/i.test(normalizeIntentText(input))) {
    return false;
  }
  const core = normalizePharmText(compactSpokenMedicalAcronyms(applyClinicalSpeechFixups(input) || input))
    .split(" ")
    .filter((token) => token.length > 1 && !["what", "is", "are", "the", "a", "an", "about", "tell", "me", "for", "of", "show", "open", "find", "search", "lookup", "look", "up", "lab", "labs", "range", "ranges", "level", "levels", "normal", "value", "values"].includes(token))
    .join(" ");
  return Boolean(core && LAB_ONLY_LOOKUP_TERMS.has(core));
}

const LAB_MEDICAL_ABBREVIATION_FULL_PATTERN = /\b(hemoglobin|hematocrit|blood gas|blood count|neutrophil|aminotransferase|natriuretic peptide|blood urea nitrogen|creatine kinase|glomerular filtration|bicarbonate|normalized ratio|prothrombin|thromboplastin|mean arterial pressure|partial pressure|oxygen saturation|thyroid|glycated hemoglobin)\b/i;

function hasLabAbbreviationIntent(input = "") {
  const normalized = normalizePharmText(compactSpokenMedicalAcronyms(input));
  if (!normalized) return false;
  return medicalAbbreviationEntriesForText(normalized, 20).some((entry) => {
    const short = normalizePharmText(entry.short);
    const expandedText = normalizePharmText([entry.full, ...(entry.aliases || [])].join(" "));
    return LAB_MEDICAL_ABBREVIATION_SHORTS.has(short)
      || LAB_MEDICAL_ABBREVIATION_FULL_PATTERN.test(expandedText);
  });
}

function hasLabLookupIntent(input = "") {
  const normalized = normalizePharmText(compactSpokenMedicalAcronyms(input));
  return Boolean(normalized && (LAB_LOOKUP_INTENT_PATTERN.test(normalized) || hasLabAbbreviationIntent(normalized)));
}

function appendMedicalAbbreviationSection(container, pieces = []) {
  if (!container) return;
  const entries = medicalAbbreviationEntriesForText(pieces, 24);
  if (!entries.length) return;
  const section = document.createElement("section");
  section.className = "pharm-abbreviation-section is-collapsed";
  section.dataset.skipRead = "true";
  section.setAttribute("aria-label", "Abbreviations written out, collapsed by default");
  const toggle = document.createElement("button");
  toggle.type = "button";
  toggle.className = "pharm-abbreviation-toggle";
  toggle.setAttribute("aria-expanded", "false");
  const heading = document.createElement("strong");
  heading.textContent = "Abbreviations written out";
  const arrow = document.createElement("span");
  arrow.className = "pharm-abbreviation-arrow";
  arrow.setAttribute("aria-hidden", "true");
  arrow.textContent = "\u25BE";
  toggle.append(heading, arrow);
  const text = document.createElement("div");
  text.className = "pharm-detail-text";
  text.hidden = true;
  text.dataset.skipRead = "true";
  text.setAttribute("aria-hidden", "true");
  appendReadableDetailText(
    text,
    entries.map((entry) => `${entry.short}: ${entry.displayFull || entry.full}`).join("; "),
    { currentLabel: "Abbreviations" }
  );
  toggle.addEventListener("click", () => {
    const nextExpanded = toggle.getAttribute("aria-expanded") !== "true";
    toggle.setAttribute("aria-expanded", String(nextExpanded));
    section.classList.toggle("is-expanded", nextExpanded);
    section.classList.toggle("is-collapsed", !nextExpanded);
    text.hidden = !nextExpanded;
    text.setAttribute("aria-hidden", String(!nextExpanded));
  });
  section.append(toggle, text);
  container.append(section);
}

function medicalWordPartText(part = {}) {
  if (typeof part === "string") return safeText(part);
  const root = safeText(part.root || part.part || part.term || part.prefix || part.suffix);
  const meaning = safeText(part.meaning || part.definition);
  const note = safeText(part.note || part.example);
  const rootText = root && meaning ? `${root} = ${meaning}` : root || meaning;
  return [rootText, note].filter(Boolean).join("; ");
}

function learnerSupportVisibleText(value, authoredSection = null) {
  const standard = window.ANI_LEARNER_LANGUAGE_STANDARD;
  if (authoredSection && value && typeof value === "object"
    && standard && typeof standard.clinicalReferenceStructuredSectionProjection === "function") {
    return safeText(standard.clinicalReferenceStructuredSectionProjection(authoredSection).text);
  }
  return safeText(value);
}

function learnerSupportSafetyVisible(label = "", authoredSection = null) {
  return safeText(authoredSection && authoredSection.presentation).toLowerCase() === "urgent"
    || /(?:urgent|warning|contraindication|adverse|toxicity|red flag|escalat|priority action|safety)/i.test(safeText(label));
}

function learnerSupportVisibleBlocks(sections = [], options = {}) {
  const prefix = safeText(options.prefix || "visible-section");
  return (Array.isArray(sections) ? sections : []).map((entry, index) => {
    const source = entry && typeof entry === "object" && !Array.isArray(entry)
      ? entry
      : { label: Array.isArray(entry) ? entry[0] : "", value: Array.isArray(entry) ? entry[1] : entry };
    const authoredSection = source.authoredSection || null;
    const sourceIndex = Number.isInteger(authoredSection && authoredSection.sourceIndex)
      ? authoredSection.sourceIndex
      : index;
    return {
      id: safeText(source.id) || `${prefix}-${index + 1}`,
      path: safeText(source.path) || (authoredSection
        ? `sections.${sourceIndex}.value`
        : `visibleSections.${index}`),
      label: safeText(source.label),
      text: learnerSupportVisibleText(
        Object.prototype.hasOwnProperty.call(source, "learnerText") ? source.learnerText : source.value,
        authoredSection
      ),
      safetyVisible: source.safetyVisible === true || learnerSupportSafetyVisible(source.label, authoredSection),
      sourceIndex
    };
  }).filter((block) => block.text);
}

function projectVisibleLearnerSupport(item = {}, sections = [], options = {}) {
  const standard = window.ANI_LEARNER_LANGUAGE_STANDARD;
  if (!standard || typeof standard.visibleLearnerSupportProjection !== "function") {
    return { blocks: [], byId: new Map(), metrics: {} };
  }
  const blocks = learnerSupportVisibleBlocks(sections, options);
  const projection = standard.visibleLearnerSupportProjection(item, blocks, {
    maximumInferredGlossesPerBlock: 3
  });
  return {
    ...projection,
    byId: new Map(projection.blocks.map((block) => [block.id, block]))
  };
}

function runtimeVisibleLearnerSupportBlocks(sourceCollection = "", item = {}) {
  let sections = [];
  let prefix = "visible-section";
  if (sourceCollection === "pharmSearchableLabRanges") {
    sections = labVisibleLearnerSections(item);
    prefix = "lab-visible-section";
  } else if (sourceCollection === "pathologyDiseases") {
    sections = pathologyVisibleLearnerDetail(item).learnerSections;
    prefix = "pathology-visible-section";
  } else if (sourceCollection === "holisticRemedies") {
    sections = holisticVisibleLearnerSections(item);
    prefix = "holistic-visible-section";
  } else if (sourceCollection === "pharmDrugs") {
    sections = pharmacyVisibleLearnerSections(item);
    prefix = "pharmacy-visible-section";
  }
  return learnerSupportVisibleBlocks(sections, { prefix });
}

function runtimeVisibleLearnerSupportProjection(sourceCollection = "", item = {}) {
  const blocks = runtimeVisibleLearnerSupportBlocks(sourceCollection, item)
    .map((block) => Object.freeze({ ...block }));
  const labStructuredSections = sourceCollection === "pharmSearchableLabRanges"
    ? labStructuredSectionProjection(item)
    : null;
  return Object.freeze({
    schemaVersion: "ani-runtime-visible-learner-blocks-v1",
    sourceCollection: safeText(sourceCollection),
    blocks: Object.freeze(blocks),
    ...(labStructuredSections ? {
      labStructuredSections: Object.freeze({
        schemaVersion: labStructuredSections.schemaVersion,
        recognized: labStructuredSections.recognized,
        hasValidAuthoredSections: labStructuredSections.hasValidAuthoredSections,
        suppressGeneratedTeaching: labStructuredSections.suppressGeneratedTeaching,
        coverageComplete: labStructuredSections.coverageComplete,
        recognizedFields: Object.freeze(Array.from(labStructuredSections.recognizedFields || [])),
        validFields: Object.freeze(Array.from(labStructuredSections.validFields || [])),
        emptyFields: Object.freeze(Array.from(labStructuredSections.emptyFields || [])),
        malformedFields: Object.freeze(Array.from(labStructuredSections.malformedFields || [])),
        projectedSectionPaths: Object.freeze((labStructuredSections.sections || []).map((section) => section.path)),
        projectedLeafPaths: Object.freeze((labStructuredSections.sections || [])
          .flatMap((section) => (section.items || []).map((item) => item.path))),
        sourceItemCount: Number(labStructuredSections.sourceItemCount || 0),
        projectedLeafCount: Number(labStructuredSections.projectedLeafCount || 0),
        automaticRewritePerformed: false,
        populationSiblingInheritancePerformed: false,
        mutationTargetAuthorized: false
      })
    } : {})
  });
}

function appendLearnerLanguageSupport(container, item = {}, options = {}) {
  if (!container || !item) return false;
  const standard = window.ANI_LEARNER_LANGUAGE_STANDARD;
  if (!standard || typeof standard.supportForItem !== "function") return false;
  const projectedBlock = options.projectedBlock && typeof options.projectedBlock === "object"
    ? options.projectedBlock
    : null;
  const support = projectedBlock
    ? {
        version: standard.version,
        plainLanguage: safeText(item.plainLanguage || item.plainMeaning || item.termMeaning || item.literalMeaning),
        glosses: Array.isArray(projectedBlock.glosses) ? projectedBlock.glosses : [],
        analysis: { supportRecommended: true }
      }
    : standard.supportForItem(item, {
        maxGlosses: 6,
        maxInferredGlosses: 3,
        visibleText: safeText(options.visibleText)
      });
  const plainLanguage = options.includePlainLanguage === false ? "" : safeText(support.plainLanguage);
  const glosses = Array.isArray(support.glosses) ? support.glosses.filter((entry) => entry && entry.term && entry.plainLanguage) : [];
  const hasReviewedGlosses = projectedBlock
    ? projectedBlock.hasValidExplicitGlosses === true
    : Boolean(standard.explicitGlosses?.(item)?.some((entry) => Array.isArray(entry.sourceKeys) && entry.sourceKeys.length));
  if ((!glosses.length && !(plainLanguage && hasReviewedGlosses))
    || (!support.analysis?.supportRecommended && !hasReviewedGlosses)) return false;

  const existingText = normalizePharmText(container.textContent || "");
  const visibleSupportText = safeText(projectedBlock?.text || options.visibleText);
  const comparable = typeof standard.openingOwnershipComparable === "function"
    ? standard.openingOwnershipComparable
    : normalizePharmText;
  const uniquePlainLanguage = plainLanguage
    && comparable(visibleSupportText) !== comparable(plainLanguage)
    ? plainLanguage
    : "";
  const uniqueGlosses = projectedBlock
    ? glosses
    : glosses.filter((entry) => !existingText.includes(normalizePharmText(entry.plainLanguage)));
  const reviewedPlainLanguage = hasReviewedGlosses ? uniquePlainLanguage : "";
  if (!reviewedPlainLanguage && !uniqueGlosses.length) return false;

  const section = document.createElement("section");
  section.className = ["learner-language-support", projectedBlock ? "is-section-adjacent" : ""]
    .filter(Boolean).join(" ");
  section.dataset.learnerLanguageVersion = safeText(support.version || standard.version);
  if (projectedBlock) {
    section.dataset.learnerBlockId = safeText(projectedBlock.id);
    section.dataset.learnerBlockPath = safeText(projectedBlock.path);
    section.dataset.learnerSupportTrigger = safeText(projectedBlock.trigger);
    section.dataset.safetyVisible = String(Boolean(projectedBlock.safetyVisible));
  }
  section.setAttribute("aria-label", "Medical terms explained");
  const heading = document.createElement("strong");
  heading.textContent = safeText(options.heading) || "Medical terms explained";
  const grid = document.createElement("div");
  grid.className = "learner-language-grid";
  const currentLabel = safeText(options.currentLabel || item.name || item.displayName || item.generic || item.title);

  const addRow = (label, value, className = "", metadata = null) => {
    const text = safeText(value);
    if (!text) return;
    const row = document.createElement("div");
    row.className = ["learner-language-row", className].filter(Boolean).join(" ");
    if (metadata) {
      row.dataset.learnerTerm = safeText(metadata.term || label);
      row.dataset.learnerSourceKind = safeText(metadata.kind);
      row.dataset.learnerSourceKeys = Array.isArray(metadata.sourceKeys) ? metadata.sourceKeys.join("|") : "";
    }
    const rowLabel = document.createElement("span");
    rowLabel.className = "learner-language-label";
    rowLabel.textContent = label;
    const rowValue = document.createElement("div");
    rowValue.className = "learner-language-value";
    appendReadableDetailText(rowValue, text, { currentLabel });
    row.append(rowLabel, rowValue);
    grid.append(row);
  };

  addRow("In everyday words", reviewedPlainLanguage, "is-plain-language");
  uniqueGlosses.forEach((entry) => addRow(entry.term, entry.plainLanguage, "is-glossary-term", entry));
  section.append(heading, grid);
  container.append(section);
  return true;
}

function appendMedicalTermTeachingSection(container, item = {}) {
  if (!container || !item) return false;
  const pronunciation = safeText(item.pronunciation || item.pronouncesAs || item.phonetic);
  const plainMeaning = safeText(item.plainMeaning || item.termMeaning || item.literalMeaning);
  const wordParts = (Array.isArray(item.wordParts) ? item.wordParts : [])
    .map((part) => medicalWordPartText(part))
    .filter(Boolean);
  const wordOrigin = safeText(item.wordOrigin || item.originNote || item.etymology);
  if (!pronunciation && !plainMeaning && !wordParts.length && !wordOrigin) return false;

  const section = document.createElement("section");
  section.className = "medical-term-teaching-section";
  const heading = document.createElement("strong");
  heading.textContent = "Pronunciation / word roots";
  const grid = document.createElement("div");
  grid.className = "medical-term-root-grid";
  const currentLabel = safeText(item.name || item.displayName || item.generic || item.fullForm);

  const addRow = (label, value) => {
    if (!value) return;
    const row = document.createElement("div");
    row.className = "medical-term-root-row";
    const rowLabel = document.createElement("span");
    rowLabel.className = "medical-term-root-label";
    rowLabel.textContent = label;
    const rowValue = document.createElement("div");
    rowValue.className = "medical-term-root-value";
    appendReadableDetailText(rowValue, value, { currentLabel });
    row.append(rowLabel, rowValue);
    grid.append(row);
  };

  addRow("Pronunciation", pronunciation);
  addRow("Plain meaning", plainMeaning);
  addRow("Word parts", wordParts.join(". "));
  addRow("Origin note", wordOrigin);
  section.append(heading, grid);
  container.append(section);
  return true;
}

function appendClinicalReferenceResultMeaningSection(container, entry = {}) {
  if (!container || !entry) return false;
  const rows = clinicalReferenceResultMeaningRows(entry);
  if (!rows.length) return false;
  const section = document.createElement("section");
  section.className = "clinical-result-meaning-section";
  const heading = document.createElement("strong");
  heading.textContent = "Results - what each result means";
  const grid = document.createElement("div");
  grid.className = "clinical-result-meaning-grid";
  const currentLabel = clinicalReferenceDisplayName(entry) || safeText(entry.name);

  rows.forEach((row) => {
    const card = document.createElement("article");
    card.className = "clinical-result-meaning-card";
    const label = document.createElement("b");
    label.textContent = row.label;
    const meaning = document.createElement("div");
    meaning.className = "pharm-detail-text clinical-result-meaning-text";
    appendReadableDetailText(meaning, row.meaning, { currentLabel });
    card.append(label, meaning);
    grid.append(card);
  });

  section.append(heading, grid);
  container.append(section);
  return true;
}

function normalizeOfflineLookupText(value = "", options = {}) {
  const dropLookupWords = options.dropLookupWords !== false;
  let text = compactSpokenMedicalAcronyms(value)
    .replace(/\b(addison|cushing|parkinson|alzheimer|hodgkin|hashimoto|bell|wilson|paget|meniere|raynaud|sjogren|reye|kawasaki)\s+s\b/g, "$1")
    .replace(/\b([a-z]{3,})\s+s\s+(?=(disease|syndrome|crisis|triad|deficiency|insufficiency|disorder|phenomenon|sign)\b)/g, "$1 ")
    .replace(/\b(addisons|cushings|parkinsons|alzheimers|hodgkins|hashimotos|bells|wilsons|pagets|menieres|raynauds|sjogrens|reyes|kawasakis)\b/g, (match) => ({
      addisons: "addison",
      cushings: "cushing",
      parkinsons: "parkinson",
      alzheimers: "alzheimer",
      hodgkins: "hodgkin",
      hashimotos: "hashimoto",
      bells: "bell",
      wilsons: "wilson",
      pagets: "paget",
      menieres: "meniere",
      raynauds: "raynaud",
      sjogrens: "sjogren",
      reyes: "reye",
      kawasakis: "kawasaki"
    })[match] || match);

  if (dropLookupWords) {
    text = text.replace(/\b(ani|annie|hey|please|what|whats|is|are|the|a|an|about|tell|me|show|open|look|lookup|find|search|range|normal|value|level|for|of|with|on|how|do|does|did|can|could|would|should|you|your|i|need|want|see|example|examples|give|pull|up|bring|lecture|mode|lesson|rant|teach|teaching|cover|covers|covered|focus|focused|treat|treats|treated|treating|treatment|treatments|manage|manages|managed|managing|management|therapy|therapies|clinical|quick|brief|summary|explain|explains|explained|describes|describe)\b/g, " ");
  }

  return text.replace(/\s+/g, " ").trim();
}

const LAB_POPULATION_ALIAS_GROUPS = {
  adult: [
    "adult",
    "adults",
    "general adult",
    "standard adult",
    "nonpregnant",
    "non pregnant",
    "non pregnant adult",
    "grown up",
    "grown ups"
  ],
  pediatric: [
    "pediatric",
    "pediatrics",
    "peds",
    "ped",
    "kid",
    "kids",
    "child",
    "children",
    "infant",
    "infants",
    "toddler",
    "toddlers",
    "baby",
    "babies",
    "adolescent",
    "adolescents",
    "teen",
    "teens",
    "newborn",
    "newborns",
    "neonate",
    "neonates"
  ],
  maternal: [
    "maternal",
    "maternity",
    "pregnancy",
    "pregnant",
    "preg",
    "ob",
    "obstetric",
    "obstetrics",
    "prenatal",
    "antepartum",
    "postpartum",
    "labor",
    "delivery"
  ],
  geriatric: [
    "geriatric",
    "geriatrics",
    "older adult",
    "older adults",
    "elderly",
    "elder",
    "senior",
    "seniors",
    "aging",
    "older client",
    "older patient"
  ],
  female: ["female", "females", "woman", "women"],
  male: ["male", "males", "man", "men"]
};
const SPECIAL_LAB_POPULATIONS = new Set(["pediatric", "maternal", "geriatric"]);
const labPopulationIntentCache = new Map();
const PEDIATRIC_AGE_WORD_VALUES = {
  zero: 0,
  one: 1,
  two: 2,
  three: 3,
  four: 4,
  five: 5,
  six: 6,
  seven: 7,
  eight: 8,
  nine: 9,
  ten: 10,
  eleven: 11,
  twelve: 12,
  thirteen: 13,
  fourteen: 14,
  fifteen: 15,
  sixteen: 16,
  seventeen: 17,
  eighteen: 18
};
const PEDIATRIC_AGE_WORD_PATTERN = Object.keys(PEDIATRIC_AGE_WORD_VALUES).join("|");

function pediatricAgeValueFromMatch(value = "") {
  const numeric = Number(value);
  if (Number.isFinite(numeric)) return numeric;
  return PEDIATRIC_AGE_WORD_VALUES[normalizeIntentText(value)] ?? NaN;
}

function normalizedTextHasPhrase(cleanText = "", phrase = "") {
  const cleanPhrase = normalizePharmText(phrase);
  if (!cleanText || !cleanPhrase) return false;
  const pattern = new RegExp(`(^|\\s)${escapeRegex(cleanPhrase).replace(/\\s+/g, "\\s+")}(?=\\s|$)`);
  return pattern.test(cleanText);
}

function detectLabPopulationIntent(input = "") {
  const cacheKey = normalizePharmText(input);
  if (labPopulationIntentCache.has(cacheKey)) {
    return new Set(labPopulationIntentCache.get(cacheKey));
  }
  const clean = cacheKey;
  const populations = new Set();
  if (!clean) return populations;
  Object.entries(LAB_POPULATION_ALIAS_GROUPS).forEach(([population, aliases]) => {
    if (aliases.some((alias) => normalizedTextHasPhrase(clean, alias))) {
      populations.add(population);
    }
  });
  if (populations.has("geriatric") && populations.has("adult")) {
    const cleanWithoutOlderAdultPhrases = [
      "older adult",
      "older adults",
      "older client",
      "older patient"
    ].reduce((text, phrase) => text.replace(new RegExp(`(^|\\s)${escapeRegex(normalizePharmText(phrase)).replace(/\\s+/g, "\\s+")}(?=\\s|$)`, "g"), " "), clean);
    const hasSeparateAdultIntent = LAB_POPULATION_ALIAS_GROUPS.adult
      .some((alias) => normalizedTextHasPhrase(cleanWithoutOlderAdultPhrases, alias));
    if (!hasSeparateAdultIntent) {
      populations.delete("adult");
    }
  }
  const pediatricAge = detectPediatricAgeIntent(input);
  if (pediatricAge && Number.isFinite(Number(pediatricAge.years)) && Number(pediatricAge.years) <= 18) {
    populations.add("pediatric");
    populations.delete("adult");
  }
  const numericAge = clean.match(/\bage\s*(\d{1,3})(?:\b|$)|\b(\d{1,3})\s*(?:years?|yrs?|yr|yo|y o)\s*old\b/i);
  const years = numericAge ? Number(numericAge[1] || numericAge[2]) : NaN;
  if (Number.isFinite(years) && years >= 65 && !populations.has("pediatric")) {
    populations.add("geriatric");
    populations.delete("adult");
  }
  labPopulationIntentCache.set(cacheKey, Array.from(populations));
  if (labPopulationIntentCache.size > 500) {
    labPopulationIntentCache.delete(labPopulationIntentCache.keys().next().value);
  }
  return populations;
}

function detectPediatricAgeIntent(input = "") {
  const lower = normalizeIntentText(input);
  if (!lower) return null;

  if (/\b(newborn|newborns|neonate|neonates)\b/i.test(lower)) {
    return { years: 0, months: 0, days: 0, label: "newborn" };
  }

  const monthMatch = lower.match(/\b(?:age\s*)?(\d+(?:\.\d+)?)\s*(?:months?|mos?|mo)\b/i)
    || lower.match(new RegExp(`\\b(?:age\\s*)?(${PEDIATRIC_AGE_WORD_PATTERN})\\s*(?:months?|mos?|mo)\\b`, "i"));
  if (monthMatch) {
    const months = pediatricAgeValueFromMatch(monthMatch[1]);
    if (Number.isFinite(months)) {
      return { years: months / 12, months, days: months * 30.4375, label: `${months} month${months === 1 ? "" : "s"}` };
    }
  }

  const yearMatch = lower.match(/\b(?:age\s*)?(\d+(?:\.\d+)?)\s*[-\s]*(?:years?|yrs?|yr|y\/o|yo)(?:[-\s]*old)?\b/i)
    || lower.match(/\bage\s*(\d+(?:\.\d+)?)\b/i)
    || lower.match(/\b(\d+(?:\.\d+)?)\s*[-\s]*(?:years?|yrs?)\s*[-\s]*old\b/i)
    || lower.match(new RegExp(`\\b(?:age\\s*)?(${PEDIATRIC_AGE_WORD_PATTERN})\\s*[-\\s]*(?:years?|yrs?|yr)(?:[-\\s]*old)?\\b`, "i"));
  if (yearMatch) {
    const years = pediatricAgeValueFromMatch(yearMatch[1]);
    if (Number.isFinite(years)) {
      return { years, months: years * 12, days: years * 365.25, label: `age ${years}` };
    }
  }

  const pediatricCue = /\b(pediatric|peds|kid|kids|child|children|boy|boys|girl|girls)\b/i.test(lower);
  const bareAge = pediatricCue ? lower.match(/\b(?:at|for)\s+(\d{1,2})(?:\b|$)/i) : null;
  if (bareAge) {
    const years = Number(bareAge[1]);
    if (Number.isFinite(years)) {
      return { years, months: years * 12, days: years * 365.25, label: `age ${years}` };
    }
  }

  return null;
}

function pediatricAgeLabel(age = null) {
  if (!age) return "Pediatric value";
  return age.label === "newborn" ? "Newborn value" : `${age.label} value`;
}

function pediatricRangeSegmentAgeMatchScore(segment = "", age = null) {
  if (!age) return 0;
  const raw = safeText(segment);
  const text = normalizePharmText(raw);
  if (!text) return 0;

  const days = Number(age.days);
  const months = Number(age.months);
  const years = Number(age.years);

  if (/\b(newborn|neonate)\b/i.test(text)) {
    return days <= 30 ? 80 : -140;
  }

  const lessThanDays = raw.match(/<\s*(\d+(?:\.\d+)?)\s*(?:day|days)\b/i);
  if (lessThanDays && Number.isFinite(days)) {
    return days < Number(lessThanDays[1]) ? 72 : -90;
  }

  const greaterThanDays = raw.match(/>\s*(\d+(?:\.\d+)?)\s*(?:day|days)\b/i);
  if (greaterThanDays && Number.isFinite(days)) {
    return days > Number(greaterThanDays[1]) ? 42 : -45;
  }

  const monthRange = raw.match(/\b(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*(?:mo|mos|month|months)\b/i);
  if (monthRange && Number.isFinite(months)) {
    const low = Number(monthRange[1]);
    const high = Number(monthRange[2]);
    return months >= low && months < high ? 90 - Math.max(0, high - low) / 10 : -80;
  }

  const greaterThanMonth = raw.match(/>\s*(\d+(?:\.\d+)?)\s*(?:mo|mos|month|months)\b/i);
  if (greaterThanMonth && Number.isFinite(months)) {
    return months > Number(greaterThanMonth[1]) ? 34 : -35;
  }

  const yearRange = raw.match(/\b(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*(?:yr|yrs|year|years)\b/i);
  if (yearRange && Number.isFinite(years)) {
    const low = Number(yearRange[1]);
    const high = Number(yearRange[2]);
    return years >= low && years < high ? 110 - Math.max(0, high - low) : -95;
  }

  if (/\b(child|children|pediatric|peds|school age|school aged)\b/i.test(text)) {
    return years >= 1 && years < 12 ? 28 : 8;
  }

  return 0;
}

function bestPediatricRangeSegmentForAge(range = "", age = null) {
  if (!age) return "";
  const parts = safeText(range).split(";").map((part) => part.trim()).filter(Boolean);
  if (!parts.length) return "";
  const scored = parts
    .map((part) => ({ part, score: pediatricRangeSegmentAgeMatchScore(part, age) }))
    .filter((entry) => entry.score > 0)
    .sort((a, b) => b.score - a.score || a.part.length - b.part.length);
  return scored[0]?.part || "";
}

function pediatricLabMatchesRequestedAge(lab = {}, age = null) {
  if (!age) return true;
  const raw = [lab.name, lab.range, lab.why].map(safeText).join(" ");
  const text = normalizePharmText(raw);
  if (!text) return true;
  if (bestPediatricRangeSegmentForAge(lab.range, age)) return true;
  if (/\b(child|children|pediatric|peds|school age|school aged)\b/i.test(text)) return true;
  if (age.years >= 1 && /\b(newborn|neonate|0\s*-\s*1\s*mo|0\s*-\s*30\s*days?|<\s*10\s*days?)\b/i.test(raw)) {
    return false;
  }
  return !/\b\d+(?:\.\d+)?\s*-\s*\d+(?:\.\d+)?\s*(?:mo|mos|month|months|yr|yrs|year|years)\b/i.test(raw);
}

function labPopulationProfile(lab = {}) {
  const profile = new Set();
  const identityText = normalizePharmText([
    lab.populationGroup,
    lab.category,
    lab.sourceType
  ].join(" "));
  Object.entries(LAB_POPULATION_ALIAS_GROUPS).forEach(([population, aliases]) => {
    if (aliases.some((alias) => normalizedTextHasPhrase(identityText, alias))) {
      profile.add(population);
    }
  });

  const rangeText = normalizePharmText([lab.name, lab.range].join(" "));
  if (["female", "females", "woman", "women"].some((alias) => normalizedTextHasPhrase(rangeText, alias))) {
    profile.add("female");
  }
  if (["male", "males", "man", "men"].some((alias) => normalizedTextHasPhrase(rangeText, alias))) {
    profile.add("male");
  }

  const isCoreAdultLab = !safeText(lab.populationGroup)
    || /essential lab|core lab|core labs/i.test(safeText(`${lab.sourceType} ${lab.category}`));
  if (isCoreAdultLab && ![...SPECIAL_LAB_POPULATIONS].some((population) => profile.has(population))) {
    profile.add("adult");
    profile.add("general");
  }
  return profile;
}

function labPopulationIndexTerms(lab = {}) {
  const profile = labPopulationProfile(lab);
  const terms = new Set();
  profile.forEach((population) => {
    (LAB_POPULATION_ALIAS_GROUPS[population] || []).forEach((alias) => terms.add(alias));
  });
  if (profile.has("adult")) {
    terms.add("adult lab");
    terms.add("adult range");
  }
  if (profile.has("pediatric")) {
    terms.add("pediatric lab");
    terms.add("pediatric range");
  }
  if (profile.has("maternal")) {
    terms.add("pregnancy lab");
    terms.add("maternal range");
  }
  if (profile.has("geriatric")) {
    terms.add("geriatric lab");
    terms.add("older adult range");
  }
  return Array.from(terms);
}

function labPopulationKey(lab = {}) {
  const profile = Array.from(labPopulationProfile(lab))
    .filter((population) => population !== "general")
    .sort();
  const populationLabel = profile.length
    ? profile.join("-")
    : normalizePharmText([lab.populationGroup, lab.category, lab.sourceType].join(" ")) || "general";
  return populationLabel || "general";
}

function labPopulationLookupPrefix(lab = {}) {
  const profile = labPopulationProfile(lab);
  if (profile.has("pediatric")) return "pediatric";
  if (profile.has("maternal")) return "pregnancy";
  if (profile.has("geriatric")) return "geriatric";
  if (profile.has("adult")) return "adult";
  if (profile.has("female")) return "female";
  if (profile.has("male")) return "male";
  return "";
}

function pharmLabLookupQuery(lab = {}) {
  const label = safeText(lab.name);
  if (!label) return "";
  const prefix = labPopulationLookupPrefix(lab);
  return prefix ? `${prefix} ${label}` : label;
}

function scoreLabPopulationFit(lab = {}, query = "") {
  const intent = detectLabPopulationIntent(query);
  if (!intent.size) return 0;
  const profile = labPopulationProfile(lab);
  const profileHasSpecial = [...SPECIAL_LAB_POPULATIONS].some((population) => profile.has(population));
  const intentHasSpecial = [...SPECIAL_LAB_POPULATIONS].some((population) => intent.has(population));
  let score = 0;

  intent.forEach((population) => {
    if (profile.has(population)) {
      score += ["adult", "female", "male"].includes(population) ? 260 : 320;
    } else if (population === "adult" && profileHasSpecial) {
      score -= 340;
    } else if (SPECIAL_LAB_POPULATIONS.has(population) && profile.has("adult") && !profileHasSpecial) {
      score -= 130;
    } else if (["female", "male"].includes(population)) {
      score -= 90;
    } else {
      score -= 35;
    }
  });

  if (intent.has("adult") && !intentHasSpecial && profileHasSpecial) {
    score -= 120;
  }
  if (!intent.has("maternal") && !intent.has("pregnancy") && profile.has("maternal") && (intent.has("adult") || intent.has("male"))) {
    score -= 160;
  }
  return score;
}

const FAST_LOOKUP_STOP_WORDS = new Set([
  "ani",
  "annie",
  "hey",
  "please",
  "what",
  "whats",
  "about",
  "tell",
  "show",
  "open",
  "look",
  "lookup",
  "find",
  "range",
  "normal",
  "value",
  "level",
  "levels",
  "drug",
  "med",
  "medication",
  "lab",
  "labs",
  "disease",
  "pathology",
  "condition",
  "clinical",
  "sign",
  "signs",
  "finding",
  "findings",
  "exam",
  "examination",
  "test",
  "tests",
  "the",
  "and",
  "or",
  "for",
  "from",
  "with",
  "into",
  "onto",
  "that",
  "this",
  "these",
  "those",
  "does",
  "how",
  "why",
  "who",
  "which",
  "mean",
  "means",
  "result",
  "results",
  "positive",
  "negative",
  "abnormal",
  "mechanism",
  "warning",
  "warnings",
  "contraindication",
  "contraindications",
  "treatment",
  "treatments"
]);
const fastIndexMembershipCache = new WeakMap();

function addFastIndexCandidate(indexMap, key = "", candidate = {}) {
  const cleanKey = normalizePharmText(key);
  if (!cleanKey) return;
  if (!indexMap.has(cleanKey)) {
    indexMap.set(cleanKey, []);
  }
  if (!fastIndexMembershipCache.has(indexMap)) fastIndexMembershipCache.set(indexMap, new Map());
  const membershipByKey = fastIndexMembershipCache.get(indexMap);
  if (!membershipByKey.has(cleanKey)) membershipByKey.set(cleanKey, new WeakSet());
  const membership = membershipByKey.get(cleanKey);
  if (candidate.item && typeof candidate.item === "object" && membership.has(candidate.item)) return;
  const bucket = indexMap.get(cleanKey);
  bucket.push(candidate);
  if (candidate.item && typeof candidate.item === "object") membership.add(candidate.item);
}

function fastLookupPrefixesForTerm(term = "") {
  const clean = normalizePharmText(term);
  if (!clean) return [];
  const keys = new Set();
  if (clean.length >= 3) {
    keys.add(clean.slice(0, 3));
    if (clean.length >= 4) keys.add(clean.slice(0, 4));
  }
  clean
    .split(" ")
    .filter((token) => token.length >= 3 && !FAST_LOOKUP_STOP_WORDS.has(token))
    .forEach((token) => {
      keys.add(token.slice(0, 3));
      if (token.length >= 4) keys.add(token.slice(0, 4));
    });
  return Array.from(keys);
}

function addFastLookupTerm(indexes, type = "", item = null, term = "", weight = 100) {
  const clean = normalizePharmText(term);
  if (!clean || !item) return;
  const exactMap = indexes[`${type}Exact`];
  const prefixMap = indexes[`${type}Prefix`];
  const candidate = { type, item, fastBoost: weight };
  addFastIndexCandidate(exactMap, clean, candidate);
  const compact = clean.replace(/\s+/g, "");
  if (compact !== clean && compact.length >= 4) {
    addFastIndexCandidate(exactMap, compact, candidate);
  }
  fastLookupPrefixesForTerm(clean).forEach((prefix) => {
    addFastIndexCandidate(prefixMap, prefix, { ...candidate, fastBoost: Math.max(30, weight - 70) });
  });
}

function addFastLookupSynonym(indexes, type = "", item = null, term = "", weight = 210) {
  const clean = normalizePharmText(term);
  if (!clean || !item) return;
  addFastLookupTerm(indexes, type, item, clean, weight);
  addFastIndexCandidate(indexes.synonymExact, clean, { type, item, fastBoost: weight + 40 });
  const compact = clean.replace(/\s+/g, "");
  if (compact !== clean && compact.length >= 4) {
    addFastIndexCandidate(indexes.synonymExact, compact, { type, item, fastBoost: weight + 30 });
  }
  // Keep multiword aliases and natural-language search terms phrase-scoped.
  // Treating every contained word as an exact synonym lets generic concepts
  // such as "liver" or "pain" hijack an otherwise specific educational query.
  // Token and prefix discovery still comes from addFastLookupTerm above.
}

function addFastLookupContent(indexes, type = "", item = null, values = []) {
  const tokens = new Set((Array.isArray(values) ? values : [values])
    .flatMap((value) => normalizePharmText(value).split(" "))
    .filter((token) => token.length >= 3 && !FAST_LOOKUP_STOP_WORDS.has(token)));
  tokens.forEach((token) => addFastLookupTerm(indexes, type, item, token, 38));
}

function getPharmFastIndexes(requestedTypes = ["drug", "lab", "pathology", "reference", "holistic"]) {
  if (!pharmFastIndexes) {
    pharmFastIndexes = {
    drugExact: new Map(),
    drugPrefix: new Map(),
    labExact: new Map(),
    labPrefix: new Map(),
    pathologyExact: new Map(),
    pathologyPrefix: new Map(),
    referenceExact: new Map(),
    referencePrefix: new Map(),
    holisticExact: new Map(),
    holisticPrefix: new Map(),
    synonymExact: new Map()
    };
  }
  const indexes = pharmFastIndexes;
  const requested = new Set(Array.isArray(requestedTypes) ? requestedTypes : [requestedTypes]);

  if (requested.has("drug") && !pharmFastIndexTypesReady.has("drug")) pharmDrugs.forEach((drug) => {
    pharmIdentityTermsForEntry(drug)
      .forEach((term) => addFastLookupTerm(indexes, "drug", drug, term, 180));
    [pharmDrugDisplayName(drug, ""), drug.name, drug.generic, drug.displayName, ...(drug.aliases || []), ...(drug.brandExamples || [])]
      .forEach((term) => addFastLookupSynonym(indexes, "drug", drug, term));
    const classTerms = [
      drug.class,
      drug.templateKey,
      ...medicalAbbreviationSearchTermsForText([drug.class, drug.templateKey].join(" "))
    ].filter(Boolean);
    if (!drug.expandedIndex || drug.nclexEssential || drug.nclexEssentialRank || drug.templateKey) {
      classTerms.forEach((term) => addFastLookupTerm(indexes, "drug", drug, term, drug.expandedIndex ? 125 : 105));
    }
    if (!drug.expandedIndex) {
      (drug.tags || []).forEach((term) => addFastLookupTerm(indexes, "drug", drug, term, 95));
    }
  });
  if (requested.has("drug")) pharmFastIndexTypesReady.add("drug");

  if (requested.has("lab") && !pharmFastIndexTypesReady.has("lab")) pharmSearchableLabRanges.forEach((lab) => {
    const labIdentityPieces = [lab.name, lab.category, lab.sourceType, lab.populationGroup, ...labPopulationIndexTerms(lab)];
    [
      ...labIdentityPieces,
      ...medicalAbbreviationSearchTermsForText(labIdentityPieces.join(" "))
    ]
      .forEach((term) => addFastLookupTerm(indexes, "lab", lab, term, 190));
    [lab.name, lab.displayName, ...(lab.aliases || [])].forEach((term) => addFastLookupSynonym(indexes, "lab", lab, term));
  });
  if (requested.has("lab")) pharmFastIndexTypesReady.add("lab");

  if (requested.has("pathology") && !pharmFastIndexTypesReady.has("pathology")) pathologyDiseases.forEach((disease) => {
    [disease.name, ...(disease.aliases || [])]
      .forEach((term) => addFastLookupTerm(indexes, "pathology", disease, term, 190));
    [disease.name, disease.displayName, ...(disease.aliases || []), ...(disease.abbreviations || []), ...(disease.commonMisspellings || [])]
      .forEach((term) => addFastLookupSynonym(indexes, "pathology", disease, term));
    [disease.category, ...(disease.tags || [])]
      .forEach((term) => addFastLookupTerm(indexes, "pathology", disease, term, 85));
  });
  if (requested.has("pathology")) pharmFastIndexTypesReady.add("pathology");

  if (requested.has("holistic") && !pharmFastIndexTypesReady.has("holistic")) holisticRemedies.forEach((remedy) => {
    [remedy.name, ...(remedy.aliases || [])]
      .forEach((term) => addFastLookupTerm(indexes, "holistic", remedy, term, 190));
    [remedy.name, remedy.displayName, ...(remedy.aliases || [])].forEach((term) => addFastLookupSynonym(indexes, "holistic", remedy, term));
    [remedy.category]
      .forEach((term) => addFastLookupTerm(indexes, "holistic", remedy, term, 80));
  });
  if (requested.has("holistic")) pharmFastIndexTypesReady.add("holistic");

  if (requested.has("reference") && !pharmFastIndexTypesReady.has("reference")) clinicalReferenceEntries.forEach((entry) => {
    [entry.name, entry.displayName, entry.fullForm, ...(entry.aliases || []), ...(entry.abbreviations || [])]
      .forEach((term) => addFastLookupTerm(indexes, "reference", entry, term, 205));
    [entry.name, entry.displayName, entry.fullForm, ...(entry.aliases || []), ...(entry.abbreviations || []), ...(entry.commonMisspellings || [])]
      .forEach((term) => addFastLookupSynonym(indexes, "reference", entry, term, 225));
    // Search terms include associated diseases and contextual findings. They
    // help discovery, but they are not alternate identities for the card.
    // Treating them as exact synonyms caused a query such as "diabetes" to
    // open Terry nails merely because diabetes appears in its associations.
    (entry.searchTerms || [])
      .forEach((term) => addFastLookupTerm(indexes, "reference", entry, term, 72));
    [entry.category, entry.type, ...(entry.tags || [])]
      .forEach((term) => addFastLookupTerm(indexes, "reference", entry, term, 95));
  });
  if (requested.has("reference")) pharmFastIndexTypesReady.add("reference");

  return pharmFastIndexes;
}

function getPharmContentIndexQueue() {
  if (pharmContentIndexQueue) return pharmContentIndexQueue;
  const groups = [
    clinicalReferenceEntries.map((item) => ({ type: "reference", item })),
    pathologyDiseases.map((item) => ({ type: "pathology", item })),
    pharmSearchableLabRanges.map((item) => ({ type: "lab", item })),
    pharmDrugs.map((item) => ({ type: "drug", item })),
    holisticRemedies.map((item) => ({ type: "holistic", item }))
  ];
  // Round-robin the collections so early idle chunks improve every search
  // category instead of indexing hundreds of references before touching the
  // first disease, lab, medication, or holistic entry.
  pharmContentIndexQueue = [];
  const longest = Math.max(...groups.map((group) => group.length), 0);
  for (let index = 0; index < longest; index += 1) {
    groups.forEach((group) => {
      if (group[index]) pharmContentIndexQueue.push(group[index]);
    });
  }
  return pharmContentIndexQueue;
}

function pharmContentIndexValues(record = {}) {
  if (record.type === "reference") return clinicalReferenceSearchBlob(record.item);
  if (record.type === "pathology") return pathologyEntryTerms(record.item);
  if (record.type === "lab") return pharmLabContentIndexValues(record.item);
  if (record.type === "drug") return pharmEntryTerms(record.item);
  if (record.type === "holistic") return holisticEntryTerms(record.item);
  return [];
}

function processPharmContentIndexChunk(deadline = null, maxItems = isPhoneDeviceMode() ? 4 : 8) {
  const indexes = getPharmFastIndexes([]);
  const queue = getPharmContentIndexQueue();
  const startedAt = window.performance?.now?.() || Date.now();
  const unboundedAuditRun = maxItems === Number.MAX_SAFE_INTEGER;
  let processed = 0;
  while (pharmContentIndexCursor < queue.length && processed < maxItems) {
    if (processed > 0 && deadline?.timeRemaining && deadline.timeRemaining() < 2) break;
    if (!unboundedAuditRun && processed > 0) {
      const elapsed = (window.performance?.now?.() || Date.now()) - startedAt;
      if (elapsed >= 5) break;
    }
    const record = queue[pharmContentIndexCursor];
    pharmContentIndexCursor += 1;
    processed += 1;
    // Content indexing must stay genuinely incremental. Building the record's
    // entire collection here made the first item of each nominal "chunk"
    // synchronous and could freeze typing for many seconds on mobile hardware.
    addFastLookupContent(indexes, record.type, record.item, pharmContentIndexValues(record));
    addClinicalSearchIntelligenceRecord(record);
    // Populate pathology identities one record at a time during the same idle
    // pass. This makes full disease names, abbreviations, misspellings, and
    // natural-language aliases immediately addressable once their record has
    // been indexed without constructing the complete identity map on a search
    // keystroke.
    if (record.type === "pathology") {
      [
        record.item?.name,
        record.item?.displayName,
        ...(record.item?.aliases || []),
        ...(record.item?.abbreviations || []),
        ...(record.item?.commonMisspellings || [])
      ].forEach((term) => addFastLookupSynonym(indexes, "pathology", record.item, term, 225));
    }
  }
  const wasReady = pharmContentIndexesReady;
  pharmContentIndexesReady = pharmContentIndexCursor >= queue.length;
  if (!wasReady && pharmContentIndexesReady) {
    // Replace cold fallback snapshots and repaint an active query once the
    // deterministic field-aware index is ready. The learner should not need
    // to type another character to receive the stronger completed ranking.
    offlineLookupSuggestionCache.clear();
    if (typeof clinicalSpeechCandidateScoreCache !== "undefined") {
      clinicalSpeechCandidateScoreCache.clear();
    }
    if (pharmSearchInput?.value && pharmDatabaseScreen && !pharmDatabaseScreen.hidden) {
      queuePharmSearchRender();
    }
    if (medicalSearchAssistInput?.value && document.activeElement === medicalSearchAssistInput) {
      queueMedicalSearchAssist(medicalSearchAssistInput, 0);
    }
  }
  return {
    processed,
    indexed: pharmContentIndexCursor,
    total: queue.length,
    complete: pharmContentIndexesReady
  };
}

function schedulePharmContentIndexBuild() {
  if (pharmContentIndexesReady || pharmContentIndexScheduled) return;
  pharmContentIndexScheduled = true;
  const runChunk = (deadline = null) => {
    pharmContentIndexScheduled = false;
    if (Date.now() - lastAniInteractiveInputAt < 650) {
      window.setTimeout(schedulePharmContentIndexBuild, 180);
      return;
    }
    const status = processPharmContentIndexChunk(deadline);
    if (!status.complete) schedulePharmContentIndexBuild();
  };
  if (window.requestIdleCallback) {
    window.requestIdleCallback(runChunk, { timeout: 4000 });
  } else {
    window.setTimeout(() => runChunk(null), 80);
  }
}

function completePharmContentIndexForAudit() {
  let status = processPharmContentIndexChunk(null, Number.MAX_SAFE_INTEGER);
  while (!status.complete) {
    status = processPharmContentIndexChunk(null, Number.MAX_SAFE_INTEGER);
  }
  return status;
}

function pharmContentIndexStatus() {
  const total = getPharmContentIndexQueue().length;
  return { indexed: pharmContentIndexCursor, total, complete: pharmContentIndexesReady };
}

function fastLookupQueryParts(input = "") {
  const variants = Array.from(new Set([
    normalizePharmText(input),
    normalizeOfflineLookupText(input),
    normalizeOfflineLookupText(input, { dropLookupWords: false }),
    normalizeHolisticSearchText(input)
  ].filter(Boolean)));
  const exactKeys = new Set();
  const prefixKeys = new Set();
  variants.forEach((variant) => {
    if (variant.length >= 2) exactKeys.add(variant);
    const compact = variant.replace(/\s+/g, "");
    if (compact !== variant && compact.length >= 4) exactKeys.add(compact);
    fastLookupPrefixesForTerm(variant).forEach((prefix) => prefixKeys.add(prefix));
    const tokens = variant
      .split(" ")
      .filter((token) => token.length >= 3 && !FAST_LOOKUP_STOP_WORDS.has(token));
    tokens.forEach((token) => {
      exactKeys.add(token);
      prefixKeys.add(token.slice(0, 3));
      if (token.length >= 4) prefixKeys.add(token.slice(0, 4));
    });
    for (let size = 2; size <= Math.min(5, tokens.length); size += 1) {
      for (let index = 0; index <= tokens.length - size; index += 1) {
        const phrase = tokens.slice(index, index + size).join(" ");
        if (phrase.length >= 5) {
          exactKeys.add(phrase);
          const phraseCompact = phrase.replace(/\s+/g, "");
          if (phraseCompact.length >= 6) exactKeys.add(phraseCompact);
        }
      }
    }
  });
  return {
    variants,
    exactKeys: Array.from(exactKeys),
    prefixKeys: Array.from(prefixKeys)
  };
}

function collectFastLookupCandidates(input = "", types = ["lab", "pathology", "holistic", "drug"]) {
  const indexes = getPharmFastIndexes(types);
  const { exactKeys, prefixKeys } = fastLookupQueryParts(input);
  const collected = new Map();
  const add = (candidate = {}, boost = 0) => {
    const label = offlineLookupEntityLabel(candidate);
    if (!label) return;
    const key = offlineLookupEntityKey(candidate);
    const scoreBoost = Math.max(candidate.fastBoost || 0, boost);
    const existing = collected.get(key);
    if (!existing || scoreBoost > existing.fastBoost) {
      collected.set(key, { type: candidate.type, item: candidate.item, fastBoost: scoreBoost });
    }
  };

  types.forEach((type) => {
    exactKeys.forEach((key) => {
      (indexes[`${type}Exact`]?.get(key) || []).forEach((candidate) => add(candidate, 220));
    });
    prefixKeys.forEach((key) => {
      (indexes[`${type}Prefix`]?.get(key) || []).forEach((candidate) => add(candidate, 80));
    });
  });
  exactKeys.forEach((key) => {
    (indexes.synonymExact.get(key) || [])
      .filter((candidate) => types.includes(candidate.type))
      .forEach((candidate) => add(candidate, 280));
  });

  return Array.from(collected.values());
}

function collectReadyFastLookupCandidates(input = "", types = ["lab", "pathology", "reference", "holistic", "drug"], limit = 80) {
  // UI typing must never synchronously build every collection. Query whatever
  // the compact reference index and idle content chunks have already made
  // available; strict identity matches are added separately below.
  const indexes = getPharmFastIndexes([]);
  const { variants, exactKeys, prefixKeys } = fastLookupQueryParts(input);
  const fullQueryKeys = new Set(variants.flatMap((variant) => {
    const compact = variant.replace(/\s+/g, "");
    return compact && compact !== variant ? [variant, compact] : [variant];
  }));
  const collected = new Map();
  const add = (candidate = {}, boost = 0, evidenceKey = "", evidenceKind = "exact") => {
    const label = offlineLookupEntityLabel(candidate);
    if (!label) return;
    const key = offlineLookupEntityKey(candidate);
    const scoreBoost = Math.max(candidate.fastBoost || 0, boost);
    let existing = collected.get(key);
    if (!existing) {
      existing = {
        type: candidate.type,
        item: candidate.item,
        fastBoost: scoreBoost,
        fastEvidenceScore: 0,
        fastEvidenceKeys: new Set()
      };
      collected.set(key, existing);
    } else if (scoreBoost > existing.fastBoost) {
      existing.fastBoost = scoreBoost;
    }
    const evidenceId = `${evidenceKind}:${evidenceKey}`;
    if (evidenceKey && !existing.fastEvidenceKeys.has(evidenceId)) {
      existing.fastEvidenceKeys.add(evidenceId);
      const isFullQuery = fullQueryKeys.has(evidenceKey);
      const isPhrase = evidenceKey.includes(" ");
      existing.fastEvidenceScore += evidenceKind === "synonym"
        ? (isFullQuery ? 240 : isPhrase ? 110 : 44)
        : evidenceKind === "prefix"
          ? 5
          : (isFullQuery ? 170 : isPhrase ? 68 : evidenceKey.length >= 6 ? 26 : 18);
    }
  };

  types.forEach((type) => {
    exactKeys.forEach((key) => {
      (indexes[`${type}Exact`]?.get(key) || []).forEach((candidate) => add(candidate, 220, key, "exact"));
    });
    prefixKeys.forEach((key) => {
      (indexes[`${type}Prefix`]?.get(key) || []).forEach((candidate) => add(candidate, 80, key, "prefix"));
    });
  });
  exactKeys.forEach((key) => {
    (indexes.synonymExact.get(key) || [])
      .filter((candidate) => types.includes(candidate.type))
      .forEach((candidate) => add(candidate, 280, key, "synonym"));
  });

  return Array.from(collected.values())
    .map((candidate) => ({
      type: candidate.type,
      item: candidate.item,
      fastBoost: candidate.fastBoost,
      fastEvidenceScore: candidate.fastEvidenceScore,
      fastMatchCount: candidate.fastEvidenceKeys.size
    }))
    .sort((a, b) => (b.fastEvidenceScore || 0) - (a.fastEvidenceScore || 0)
      || (b.fastMatchCount || 0) - (a.fastMatchCount || 0)
      || (b.fastBoost || 0) - (a.fastBoost || 0)
      || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .slice(0, Math.max(1, limit));
}

const responsiveDrugIdentityCache = new Map();

function responsiveExactDrugIdentityMatch(input = "") {
  const clean = compactMedicationIdentityQuery(input);
  if (!clean || clean.length < 3 || clean.split(" ").length > 4) return null;
  if (responsiveDrugIdentityCache.has(clean)) return responsiveDrugIdentityCache.get(clean);
  const matches = fastVoiceIdentityCandidates(clean).filter((candidate) => candidate.type === "drug");
  const match = matches.find((candidate) => [
    candidate.item?.name,
    candidate.item?.generic,
    candidate.item?.displayName,
    pharmDrugDisplayName(candidate.item, "")
  ].some((term) => normalizePharmText(term) === clean))?.item
    || matches[0]?.item
    || null;
  responsiveDrugIdentityCache.set(clean, match);
  return match;
}

const REVIEWED_ENCYCLOPEDIA_PREFIX_PRIORITIES = Object.freeze({
  // "succ" is the common bedside shorthand used when searching for the
  // paralytic succinylcholine. Succimer remains available immediately below;
  // this exact, reviewed prefix rule avoids guessing on broader fragments.
  succ: { type: "drug", identity: "succinylcholine" }
});

function encyclopediaIdentityPrimaryTerms(candidate = {}) {
  const item = candidate.item || {};
  if (candidate.type === "drug") {
    return [item.name, item.generic, item.displayName, pharmDrugDisplayName(item, "")];
  }
  if (candidate.type === "reference") {
    return [item.name, item.displayName, item.fullForm];
  }
  return [item.name, item.displayName];
}

const ENCYCLOPEDIA_IDENTITY_TERM_KIND_RANK = Object.freeze({
  "preferred-bare-alias": 500,
  abbreviation: 400,
  "acronym-alias": 350,
  "identity-alias": 300,
  brand: 200,
  misspelling: 100
});

function encyclopediaIdentityOwnerRank(candidate = {}) {
  return Math.max(0, ...(candidate.termKinds || [])
    .map((kind) => ENCYCLOPEDIA_IDENTITY_TERM_KIND_RANK[kind] || 0));
}

function stableEncyclopediaIdentityOwners(candidates = []) {
  return Array.from(new Map((candidates || [])
    .filter((candidate) => candidate?.type && candidate?.item)
    .map((candidate) => [offlineLookupEntityKey(candidate), candidate])).values())
    .sort((a, b) => offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b))
      || safeText(a.type).localeCompare(safeText(b.type)));
}

function highestRankedEncyclopediaIdentityOwners(candidates = []) {
  const ranked = stableEncyclopediaIdentityOwners(candidates);
  const highestRank = Math.max(0, ...ranked.map(encyclopediaIdentityOwnerRank));
  return highestRank > 0
    ? ranked.filter((candidate) => encyclopediaIdentityOwnerRank(candidate) === highestRank)
    : ranked;
}

function medicalAbbreviationEntryForExactCore(core = "") {
  return MEDICAL_ABBREVIATION_EXPANSIONS.find((entry) => (
    Array.isArray(entry.searchTerms) && entry.searchTerms.includes(core)
  )) || null;
}

function reviewedMedicalAbbreviationExpansionResolution(core = "") {
  const entry = medicalAbbreviationEntryForExactCore(core);
  if (!entry || entry.contextRequired === true) return null;
  const fullCore = normalizePharmText(entry.full);
  const owners = highestRankedEncyclopediaIdentityOwners(
    fastVoiceIdentityCandidates(fullCore).filter((candidate) => (
      encyclopediaIdentityPrimaryTerms(candidate)
        .some((term) => normalizePharmText(term) === fullCore)
    ))
  );
  // This learner-display registry explains abbreviations but is not card
  // ownership metadata. It may surface the exact full-form destination as a
  // suggestion, but automatic navigation requires an installed card alias,
  // abbreviation, or reviewed preferred-bare owner.
  return {
    recognized: true,
    preferred: null,
    candidates: owners,
    matchKind: owners.length > 1
      ? "exact-abbreviation-ambiguity"
      : owners.length === 1
        ? "reviewed-abbreviation-owner-missing"
        : "unresolved-reviewed-abbreviation",
    intentRoute: `reviewed-abbreviation-owner-missing-${normalizePharmText(entry.short)}`
  };
}

function reviewedSharedContextualIdentityResolution(input = "") {
  const route = fastReviewedContextualIdentityResolution(input);
  if (!route) return null;
  if (route.ambiguousIdentity === true) {
    return {
      recognized: true,
      preferred: null,
      candidates: stableEncyclopediaIdentityOwners(route.ambiguityCandidates || []),
      matchKind: "reviewed-contextual-ambiguity",
      intentRoute: route.intentRoute || "reviewed-contextual-identity-required"
    };
  }
  if (!route.type || !route.item) return null;
  return {
    recognized: true,
    preferred: route,
    candidates: [route],
    matchKind: "reviewed-contextual-identity",
    intentRoute: route.intentRoute || "reviewed-contextual-identity"
  };
}

function explicitMedicalAbbreviationFullFormResolution(input = "") {
  const normalized = normalizePharmText(applyClinicalSpeechFixups(input) || input);
  if (!normalized) return null;
  const entry = MEDICAL_ABBREVIATION_EXPANSIONS.find((candidate) => {
    const short = normalizePharmText(candidate.short);
    const full = normalizePharmText(candidate.full);
    return short && full && (normalized === `${short} ${full}` || normalized === `${full} ${short}`);
  });
  if (!entry) return null;
  const full = normalizePharmText(entry.full);
  const exactOwners = stableEncyclopediaIdentityOwners(fastVoiceIdentityCandidates(full));
  const canonicalOwners = exactOwners.filter((candidate) => (
    encyclopediaIdentityPrimaryTerms(candidate)
      .some((term) => normalizePharmText(term) === full)
  ));
  const combinedExplicitOwners = stableEncyclopediaIdentityOwners(
    fastVoiceIdentityCandidates(input).filter((candidate) => (
      Array.isArray(candidate.termKinds) && candidate.termKinds.includes("abbreviation")
    ))
  );
  // A canonical full-form destination remains authoritative. If the full form
  // itself is an alias shared by multiple cards, one exact authored
  // abbreviation owner may still resolve the combined "SHORT full form"
  // expression. Multiple authored owners stay ambiguous.
  const owners = canonicalOwners.length
    ? canonicalOwners
    : combinedExplicitOwners.length === 1
      ? combinedExplicitOwners
      : exactOwners;
  if (!owners.length) return null;
  return {
    recognized: true,
    preferred: owners.length === 1 ? owners[0] : null,
    candidates: owners,
    matchKind: owners.length === 1
      ? "reviewed-abbreviation-full-form-identity"
      : "reviewed-abbreviation-full-form-ambiguity",
    intentRoute: `reviewed-abbreviation-full-form-${normalizePharmText(entry.short)}`
  };
}

function reviewedContextualMedicalAbbreviationResolution(input = "", core = "") {
  const rawInput = safeText(input);
  const normalized = normalizePharmText(applyClinicalSpeechFixups(input) || input);
  if (!normalized) return null;
  const entries = MEDICAL_ABBREVIATION_EXPANSIONS.filter((candidate) => (
    candidate.contextRequired === true
    && Array.isArray(candidate.reviewedMeanings)
    && new RegExp(`(?:^|[^A-Za-z0-9-])${escapeRegExpText(safeText(candidate.short))}(?=$|[^A-Za-z0-9-])`, "i").test(rawInput)
  ));
  // A query that contains two independently reviewed short forms is not one
  // abbreviation-resolution request. Keep every installed exact owner visible
  // and require the learner to choose instead of letting registry order make
  // the first abbreviation silently win.
  if (entries.length > 1) {
    const owners = stableEncyclopediaIdentityOwners(entries.flatMap((candidate) => (
      fastVoiceIdentityCandidates(candidate.short)
    )));
    return {
      recognized: true,
      preferred: null,
      candidates: owners,
      matchKind: "reviewed-multiple-abbreviation-ambiguity",
      intentRoute: "reviewed-multiple-abbreviation-context-required"
    };
  }
  const entry = entries[0] || null;
  if (!entry) return null;
  const exactShortOwners = fastVoiceIdentityCandidates(entry.short);
  const reviewedOwnerContracts = Array.isArray(entry.reviewedOwners)
    ? entry.reviewedOwners
    : entry.reviewedMeanings.filter((meaning) => meaning.type !== "reference");
  const reviewedOwnerTitles = new Set(reviewedOwnerContracts
    .map((meaning) => `${meaning.type}:${normalizePharmText(meaning.canonicalTitle)}`));
  const boundShortOwners = exactShortOwners.filter((owner) => reviewedOwnerTitles.has(
    `${owner.type}:${normalizePharmText(owner.item?.name || owner.item?.displayName)}`
  ));
  // The reviewed contextual policy may not fabricate ownership. If a future
  // catalog edit removes or adds a bare GBS owner, fall back to the exact
  // installed-card contenders and require explicit user selection.
  if (boundShortOwners.length !== reviewedOwnerTitles.size
    || exactShortOwners.some((owner) => !boundShortOwners.includes(owner))) {
    return {
      recognized: true,
      preferred: null,
      candidates: stableEncyclopediaIdentityOwners(exactShortOwners),
      matchKind: "exact-abbreviation-ambiguity",
      intentRoute: "reviewed-abbreviation-owner-drift"
    };
  }
  const narrativeFrame = normalized.replace(/\bpatient controlled analgesia\b/g, " ");
  if (/\b(?:i|my|me|we|our|patient|client|child|baby|toddler)\b/.test(narrativeFrame)) {
    return {
      recognized: true,
      preferred: null,
      candidates: stableEncyclopediaIdentityOwners(exactShortOwners),
      matchKind: "reviewed-abbreviation-clinical-narrative",
      intentRoute: "reviewed-abbreviation-clinical-narrative"
    };
  }
  const matchedMeanings = entry.reviewedMeanings.filter((meaning) => (
    meaning.includePattern instanceof RegExp && meaning.includePattern.test(normalized)
  ));
  const selectedMeanings = matchedMeanings.length
    ? matchedMeanings
    : entry.reviewedMeanings.filter((meaning) => meaning.preferredBare === true);
  const candidates = stableEncyclopediaIdentityOwners(selectedMeanings.map((meaning) => {
    const candidate = fastReviewedOwnerCandidate(
      meaning.type,
      meaning.canonicalTitle,
      meaning.intentRoute,
      { exactIdentity: false, score: 3950 }
    );
    return candidate ? {
      ...candidate,
      reviewedAbbreviation: entry.short,
      reviewedAbbreviationMeaning: meaning.full,
      termKinds: [meaning.preferredBare ? "preferred-bare-alias" : "abbreviation"]
    } : null;
  }));
  if (candidates.length === 1) {
    return {
      recognized: true,
      preferred: candidates[0],
      candidates,
      matchKind: matchedMeanings.length ? "reviewed-contextual-abbreviation" : "reviewed-preferred-abbreviation",
      intentRoute: candidates[0].intentRoute
    };
  }
  return {
    recognized: true,
    preferred: null,
    candidates: candidates.length ? candidates : stableEncyclopediaIdentityOwners(exactShortOwners),
    matchKind: "reviewed-abbreviation-ambiguity",
    intentRoute: "reviewed-abbreviation-context-required"
  };
}

function reviewedMedicalAbbreviationPrefixSuggestionResolution(input = "", core = "") {
  const normalized = normalizePharmText(applyClinicalSpeechFixups(input) || input);
  if (!normalized || !core.includes(" ")) return null;
  const words = normalized.split(" ").filter(Boolean);
  const matches = MEDICAL_ABBREVIATION_EXPANSIONS.map((entry) => {
    if (entry.contextRequired !== true || !Array.isArray(entry.reviewedMeanings)) return null;
    const short = normalizePharmText(entry.short);
    const prefix = words.find((word) => word.length === 2
      && short.length > word.length
      && short.startsWith(word));
    return prefix ? { entry, prefix } : null;
  }).filter(Boolean);
  // An incomplete abbreviation is recommendation evidence only. If more than
  // one reviewed abbreviation starts with the same fragment, do not guess.
  if (matches.length !== 1) return null;
  const { entry, prefix } = matches[0];
  const matchedMeanings = entry.reviewedMeanings.filter((meaning) => (
    meaning.includePattern instanceof RegExp && meaning.includePattern.test(normalized)
  ));
  const selectedMeanings = matchedMeanings.length
    ? matchedMeanings
    : entry.reviewedMeanings.filter((meaning) => meaning.preferredBare === true);
  const candidates = stableEncyclopediaIdentityOwners(selectedMeanings.map((meaning) => {
    const candidate = fastReviewedOwnerCandidate(
      meaning.type,
      meaning.canonicalTitle,
      meaning.intentRoute,
      { exactIdentity: false, score: 3940 }
    );
    return candidate ? {
      ...candidate,
      reviewedAbbreviation: entry.short,
      reviewedAbbreviationPrefix: prefix,
      reviewedAbbreviationMeaning: meaning.full,
      termKinds: [meaning.preferredBare ? "preferred-bare-alias" : "abbreviation"]
    } : null;
  }));
  if (!candidates.length) return null;
  return {
    recognized: true,
    preferred: null,
    candidates,
    matchKind: candidates.length > 1
      ? "reviewed-abbreviation-prefix-ambiguity"
      : "reviewed-abbreviation-prefix-suggestion",
    intentRoute: `reviewed-abbreviation-prefix-${prefix}-suggestion`
  };
}

function installedAbbreviationTermsInQuery(input = "") {
  const rawInput = safeText(input);
  const normalized = normalizePharmText(applyClinicalSpeechFixups(rawInput) || rawInput);
  if (!normalized) return [];
  const words = normalized.split(" ").filter(Boolean);
  const possibleTerms = new Set(words);
  for (let width = 2; width <= Math.min(3, words.length); width += 1) {
    for (let index = 0; index <= words.length - width; index += 1) {
      possibleTerms.add(words.slice(index, index + width).join(" "));
    }
  }
  const identityIndex = getFastVoiceIdentityIndex();
  return Array.from(possibleTerms).map((term) => {
    const isNumericUnit = ["mcg", "ug", "mg", "g", "kg", "ml", "l", "meq", "mmol", "unit", "units", "mmhg", "bpm"].includes(term)
      && new RegExp(`(?:\\b\\d+(?:\\.\\d+)?\\s*${escapeRegExpText(term)}\\b|\\b${escapeRegExpText(term)}\\s*\\/(?:kg|ml|l|min|hr|day)\\b)`, "i").test(rawInput);
    if (isNumericUnit) return { term, owners: [] };
    if (commonWordAbbreviationNeedsExplicitContext(rawInput, term)) return { term, owners: [] };
    const owners = identityIndex.get(term) || [];
    const recognized = owners.some((owner) => (
      owner.termKinds?.includes("abbreviation")
      || owner.termKinds?.includes("acronym-alias")
      || owner.termKinds?.includes("preferred-bare-alias")
    ));
    return { term, owners: recognized ? owners : [] };
  }).filter((record) => record.owners.length);
}

function commonWordAbbreviationNeedsExplicitContext(input = "", term = "") {
  const raw = safeText(input);
  const normalizedInput = normalizePharmText(raw);
  const normalizedTerm = normalizePharmText(term);
  if (normalizedTerm === "ten") {
    const explicitlyUppercase = /\bTEN\b/.test(raw);
    const conditionContext = /\b(?:toxic epidermal necrolysis|lyell|sjs[\s/-]*ten|epidermal detachment|mucosal lesions?|scorten)\b/i.test(raw);
    return !explicitlyUppercase && !conditionContext;
  }
  if (normalizedTerm === "fast") {
    const explicitlyUppercase = /\b(?:BE[- ]?FAST|FAST)\b/.test(raw);
    const strokeContext = /\b(?:stroke|face droop|arm weakness|speech difficulty|balance loss|vision loss)\b/i.test(normalizedInput);
    return !explicitlyUppercase && !strokeContext;
  }
  return false;
}

function contextualInstalledAbbreviationResolution(input = "") {
  const normalized = normalizePharmText(applyClinicalSpeechFixups(input) || input);
  const installedTerms = installedAbbreviationTermsInQuery(input);
  if (installedTerms.length !== 1) return null;
  const { term, owners } = installedTerms[0];
  const stableOwners = stableEncyclopediaIdentityOwners(owners);
  if (stableOwners.length < 2) return null;
  const preferredOwners = stableOwners.filter((owner) => (
    owner.termKinds?.includes("preferred-bare-alias")
    || (Array.isArray(owner.item?.preferredBareAliases)
      && owner.item.preferredBareAliases.some((value) => normalizePharmText(value) === term))
  ));
  const personalNarrative = /\b(?:i|my|me|we|our|patient|client|child|baby|toddler)\b/.test(normalized);
  const typeCues = new Set();
  if (/\b(?:level|levels|range|ranges|normal|serum|plasma|blood value|lab|laboratory|trough|peak|therapeutic value)\b/.test(normalized)) {
    typeCues.add("lab");
  }
  if (/\b(?:drug|medication|medicine|med|dose|dosing|administer|administration|injection|tablet|capsule|side effect|adverse effect|contraindication|interaction)\b/.test(normalized)) {
    typeCues.add("drug");
  }
  if (/\b(?:syndrome|disease|disorder|condition|symptom|symptoms|signs|pathology|pathophysiology|diagnosis|cause|causes|complication|complications)\b/.test(normalized)) {
    typeCues.add("pathology");
  }
  if (/\b(?:screen|screening|procedure|surgery|anatomy|physiology|maneuver|assessment|score|scale)\b/.test(normalized)) {
    typeCues.add("reference");
  }
  if (/\b(?:supplement|herb|herbal|remedy|complementary|integrative)\b/.test(normalized)) {
    typeCues.add("holistic");
  }
  const termPattern = term.split(/\s+/).filter(Boolean).map(escapeRegExpText).join("\\s+");
  const contextualIdentityCore = normalizePharmText(termPattern
    ? normalized.replace(new RegExp(`\\b${termPattern}\\b`, "gi"), " ")
    : normalized);
  const explicitlyNamedContextOwners = contextualIdentityCore
    ? stableOwners.filter((owner) => encyclopediaIdentityPrimaryTerms(owner)
        .map((value) => normalizePharmText(value))
        .filter(Boolean)
        .some((primaryTerm) => primaryTerm === contextualIdentityCore
          || (primaryTerm.length >= 4 && new RegExp(`\\b${escapeRegExpText(primaryTerm)}\\b`, "i")
            .test(contextualIdentityCore))))
    : [];
  const contextualOwners = typeCues.size === 1
    ? stableOwners.filter((owner) => owner.type === Array.from(typeCues)[0])
    : [];
  const explicitlyNamedContextOwner = explicitlyNamedContextOwners.length === 1
    && (typeCues.size === 0 || typeCues.has(explicitlyNamedContextOwners[0].type))
    ? explicitlyNamedContextOwners[0]
    : null;
  const selected = !personalNarrative && explicitlyNamedContextOwner
    ? explicitlyNamedContextOwner
    : !personalNarrative && contextualOwners.length === 1
      ? contextualOwners[0]
    : !personalNarrative && typeCues.size === 0 && preferredOwners.length === 1
      ? preferredOwners[0]
      : null;
  if (selected) {
    return {
      recognized: true,
      preferred: selected,
      candidates: [selected, ...stableOwners.filter((owner) => owner !== selected)],
      matchKind: explicitlyNamedContextOwner
        ? "contextual-abbreviation-named-owner"
        : contextualOwners.length === 1
          ? "contextual-abbreviation"
        : "reviewed-preferred-abbreviation",
      intentRoute: `installed-abbreviation-${term}-${selected.type}`
    };
  }
  return {
    recognized: true,
    preferred: null,
    candidates: stableOwners,
    matchKind: personalNarrative
      ? "abbreviation-clinical-narrative"
      : typeCues.size > 1
        ? "contextual-abbreviation-ambiguity"
        : "exact-abbreviation-ambiguity",
    intentRoute: `installed-abbreviation-${term}-context-required`
  };
}

/*
 * One identity resolver serves encyclopedia typing, chat, lecture, and voice
 * navigation. Body-text relevance is intentionally excluded: a short fragment
 * may suggest canonical identities, but it may auto-open only an exact owner or
 * an explicitly reviewed route such as "succ" -> Succinylcholine.
 */
function resolveEncyclopediaIdentity(input = "", options = {}) {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const core = fastCanonicalLookupCore(fixed) || normalizePharmText(fixed);
  const limit = Math.max(1, Math.min(12, Number(options.limit || 8)));
  if (!core || core.length < 2) {
    return { core, candidates: [], preferred: null, matchKind: "none", unique: false, mayAutoOpen: false };
  }
  if (commonWordAbbreviationNeedsExplicitContext(input, core)) {
    return {
      core,
      candidates: [],
      preferred: null,
      matchKind: "common-word-abbreviation-context-required",
      unique: false,
      mayAutoOpen: false,
      recognizedAbbreviation: false,
      suppressUnrelatedMatches: true,
      intentRoute: `common-word-${core}-not-medical-abbreviation`
    };
  }

  const reviewed = REVIEWED_ENCYCLOPEDIA_PREFIX_PRIORITIES[core] || null;
  const exactOwners = commonWordAbbreviationNeedsExplicitContext(input, core)
    ? []
    : fastVoiceIdentityCandidates(input);
  const prefixOwners = fastVoiceIdentitySearchCandidates(core, Math.max(limit * 3, 18));
  const deduped = Array.from(new Map([...exactOwners, ...prefixOwners]
    .filter((candidate) => candidate?.type && candidate?.item)
    .map((candidate) => [offlineLookupEntityKey(candidate), candidate])).values());
  const primaryExactOwners = deduped.filter((candidate) => encyclopediaIdentityPrimaryTerms(candidate)
    .some((term) => normalizePharmText(term) === core));
  const primaryExactOwnerTypes = new Set(primaryExactOwners.map((candidate) => candidate.type));
  const unqualifiedPrimaryOwners = primaryExactOwners.filter((candidate) => (
    !safeText(candidate.item?.populationGroup).trim()
  ));
  const uniqueUnqualifiedPrimaryOwner = primaryExactOwners.length > 1
    && primaryExactOwnerTypes.size === 1
    && unqualifiedPrimaryOwners.length === 1
    && primaryExactOwners.every((candidate) => (
      candidate === unqualifiedPrimaryOwners[0]
      || safeText(candidate.item?.populationGroup).trim()
    ))
    ? unqualifiedPrimaryOwners[0]
    : null;
  // When one base card and one or more explicitly population-qualified cards
  // share a canonical label, the bare label belongs to the base card. The
  // qualified aliases remain exact routes to their own population records.
  const canonicalExactOwner = primaryExactOwners.length === 1
    ? primaryExactOwners[0]
    : uniqueUnqualifiedPrimaryOwner;
  const standaloneReviewedShort = MEDICAL_ABBREVIATION_EXPANSIONS.some((entry) => (
    entry.contextRequired === true && normalizePharmText(entry.short) === core
  ));
  const reviewedContextualIdentity = reviewedSharedContextualIdentityResolution(fixed);
  const reviewedContextualAbbreviation = standaloneReviewedShort
    ? reviewedContextualMedicalAbbreviationResolution(fixed, core)
    : canonicalExactOwner || exactOwners.length === 1
      ? null
      : reviewedContextualMedicalAbbreviationResolution(fixed, core);
  const contextualAbbreviation = reviewedContextualIdentity
    || reviewedContextualAbbreviation
    || (canonicalExactOwner
      ? null
      : explicitMedicalAbbreviationFullFormResolution(fixed)
        || contextualInstalledAbbreviationResolution(input));
  const preferredBareOwners = canonicalExactOwner || contextualAbbreviation
    ? []
    : exactOwners.filter((candidate) => (
      candidate.termKinds?.includes("preferred-bare-alias")
      || (Array.isArray(candidate.item?.preferredBareAliases)
        && candidate.item.preferredBareAliases.some((term) => normalizePharmText(term) === core))
    ));
  const preferredBareOwner = preferredBareOwners.length === 1 ? preferredBareOwners[0] : null;
  const expansionAbbreviation = canonicalExactOwner
    || contextualAbbreviation
    || preferredBareOwner
    || exactOwners.length
    ? null
    : reviewedMedicalAbbreviationExpansionResolution(core);
  const incompleteAbbreviationPrefix = canonicalExactOwner
    || contextualAbbreviation
    || preferredBareOwner
    || exactOwners.length
    ? null
    : reviewedMedicalAbbreviationPrefixSuggestionResolution(fixed, core);
  const abbreviationResolution = contextualAbbreviation
    || expansionAbbreviation
    || incompleteAbbreviationPrefix;
  const reviewedOwner = reviewed
    ? deduped.find((candidate) => candidate.type === reviewed.type
      && encyclopediaIdentityPrimaryTerms(candidate)
        .some((term) => normalizePharmText(term) === reviewed.identity)) || null
    : null;
  const exactOwner = canonicalExactOwner
    || preferredBareOwner
    || (exactOwners.length === 1 ? exactOwners[0] : null);
  const abbreviationOwner = abbreviationResolution?.preferred || null;
  const exactAmbiguityOwners = !canonicalExactOwner
    && !preferredBareOwner
    && !abbreviationOwner
    && exactOwners.length > 1
    ? stableEncyclopediaIdentityOwners(exactOwners)
    : [];
  const abbreviationAmbiguityOwners = !abbreviationOwner && abbreviationResolution?.recognized === true
    ? stableEncyclopediaIdentityOwners(abbreviationResolution.candidates || [])
    : [];
  const ambiguityOwners = abbreviationAmbiguityOwners.length
    ? abbreviationAmbiguityOwners
    : exactAmbiguityOwners;
  if (ambiguityOwners.length || (abbreviationResolution?.recognized === true && !abbreviationOwner)) {
    return {
      core,
      candidates: ambiguityOwners.slice(0, limit).map((candidate) => ({
        ...candidate,
        ambiguousIdentity: true,
        identitySuggestionOnly: true,
        mayAutoOpen: false
      })),
      preferred: null,
      matchKind: abbreviationResolution?.matchKind
        || (exactAmbiguityOwners.length ? "exact-identity-ambiguity" : "unresolved-reviewed-abbreviation"),
      unique: false,
      mayAutoOpen: false,
      reviewed: Boolean(abbreviationResolution),
      recognizedAbbreviation: Boolean(abbreviationResolution),
      suppressUnrelatedMatches: true,
      intentRoute: abbreviationResolution?.intentRoute || "exact-identity-context-required"
    };
  }
  // Sound-alike medication help is suggestion-only. When the reviewed
  // phonetic index already has a candidate, do not spend time on fuzzy search
  // and never convert that sound-alike into an automatic navigation route.
  const restrictedPhoneticInput = isRestrictedMedicalPhoneticInput(fixed);
  const readyPhoneticSuggestions = !deduped.length && medicalPhoneticIdentityIndex
    ? medicalPhoneticIdentityCandidates(fixed, limit)
    : [];
  const nearIdentityAssessment = !deduped.length
    && core.length >= 5
    && !restrictedPhoneticInput
    ? fastVoiceNearIdentityAssessment(fixed, {
        preferredTypes: offlineNearIdentityExplicitTypes(fixed)
      })
    : { match: null, ambiguous: false, candidates: [] };
  const safeNearIdentityOwner = nearIdentityAssessment.match?.type
    && nearIdentityAssessment.match?.item
    ? {
        type: nearIdentityAssessment.match.type,
        item: nearIdentityAssessment.match.item,
        score: 2700 + Math.round(nearIdentityAssessment.match.similarity * 100),
        nearIdentity: true,
        nearIdentityScore: nearIdentityAssessment.match.similarity,
        nearIdentityQuery: nearIdentityAssessment.match.identity
      }
    : null;
  const safeNearIdentityAmbiguities = nearIdentityAssessment.ambiguous === true
    ? nearIdentityAssessment.candidates
      .filter((candidate) => candidate?.type && candidate?.item)
      .map((candidate) => ({
        type: candidate.type,
        item: candidate.item,
        score: 2700 + Math.round(candidate.similarity * 100),
        exactIdentity: false,
        nearIdentity: true,
        nearIdentityScore: candidate.similarity,
        nearIdentityQuery: candidate.identity,
        ambiguousIdentity: true,
        mayAutoOpen: false
      }))
    : [];
  const preferred = canonicalExactOwner
    || preferredBareOwner
    || abbreviationOwner
    || exactOwner
    || reviewedOwner
    || safeNearIdentityOwner;
  const matchKind = canonicalExactOwner
    ? "exact-identity"
    : preferredBareOwner
      ? "reviewed-preferred-abbreviation"
      : abbreviationOwner
        ? abbreviationResolution.matchKind
    : reviewedOwner
    ? "reviewed-prefix"
    : exactOwner
      ? "exact-identity"
      : safeNearIdentityOwner
      ? "near-identity"
      : safeNearIdentityAmbiguities.length > 1
        ? "near-identity-ambiguity"
      : readyPhoneticSuggestions.length
        ? "phonetic-suggestions"
      : deduped.length
        ? "prefix-suggestions"
        : "none";
  const candidates = preferred
    ? [preferred, ...deduped.filter((candidate) => offlineLookupEntityKey(candidate) !== offlineLookupEntityKey(preferred))]
    : safeNearIdentityAmbiguities.length
      ? safeNearIdentityAmbiguities
      : readyPhoneticSuggestions.length
        ? readyPhoneticSuggestions
      : deduped;
  const unresolvedShortPrefix = !preferred
    && matchKind === "prefix-suggestions"
    && core.length === 2
    && !core.includes(" ")
    && candidates.length > 0;
  const visibleCandidates = candidates.slice(0, limit).map((candidate) => (
    unresolvedShortPrefix ? {
      ...candidate,
      ambiguousIdentity: true,
      identitySuggestionOnly: true,
      mayAutoOpen: false
    } : candidate
  ));
  return {
    core,
    candidates: visibleCandidates,
    preferred,
    matchKind,
    unique: Boolean(preferred) && (canonicalExactOwner
      ? true
      : preferredBareOwner
        ? true
        : abbreviationOwner
          ? true
      : reviewedOwner
      ? true
      : safeNearIdentityOwner
        ? true
        : primaryExactOwners.length === 1 || exactOwners.length === 1),
    mayAutoOpen: Boolean(preferred),
    reviewed: Boolean(reviewedOwner || preferredBareOwner || abbreviationOwner),
    recognizedAbbreviation: Boolean(preferredBareOwner || abbreviationResolution),
    suppressUnrelatedMatches: unresolvedShortPrefix,
    intentRoute: abbreviationResolution?.intentRoute
      || (unresolvedShortPrefix ? "short-prefix-suggestion-only" : "")
  };
}

// Reviewed exact-query routes for common clinical wording that does not match
// the canonical card title literally. These rules bind to an existing card by
// its canonical title; they do not promote an alias to identity ownership and
// they never run for a partial or fuzzy query.
const RESPONSIVE_ENCYCLOPEDIA_EXACT_PRIORITIES = Object.freeze({
  "kayser fleischer rings": { type: "reference", identity: "kayser fleischer ring" },
  "cotton wool spots": { type: "reference", identity: "cotton wool spot" },
  "cheyne stokes respirations": { type: "reference", identity: "cheyne stokes breathing" },
  "biot respirations": { type: "reference", identity: "biot breathing" },
  "homans sign historical not reliable for dvt": { type: "reference", identity: "homan sign" },
  "raccoon eyes": { type: "reference", identity: "raccoon eye sign" },
  "patrick faber test": { type: "reference", identity: "faber test" },
  "group a strep": { type: "reference", identity: "streptococcus pyogenes" },
  "heart block": { type: "pathology", identity: "heart blocks" },
  "mobitz i": { type: "pathology", identity: "second degree av block type i" },
  "heart block 1": { type: "pathology", identity: "first degree av block" },
  hb1: { type: "pathology", identity: "first degree av block" },
  "heart block 3": { type: "pathology", identity: "third degree av block" },
  "bipolar 2": { type: "pathology", identity: "bipolar ii disorder" },
  cte: { type: "pathology", identity: "chronic traumatic encephalopathy" }
});

const RESPONSIVE_ENCYCLOPEDIA_FAMILY_QUERIES = Object.freeze({
  "heart blocks": Object.freeze([
    "heart blocks",
    "first degree av block",
    "second degree av block type i",
    "second degree av block type ii",
    "third degree av block"
  ])
});

function responsiveEncyclopediaFamilyCandidates(input = "") {
  const identities = RESPONSIVE_ENCYCLOPEDIA_FAMILY_QUERIES[normalizePharmText(input)];
  if (!identities) return [];
  return identities.map((identity) => {
    const item = pathologyDiseases.find((entry) => normalizePharmText(entry?.name) === identity);
    return item ? { type: "pathology", item } : null;
  }).filter(Boolean);
}

function responsiveEncyclopediaExactPriority(input = "") {
  const priority = RESPONSIVE_ENCYCLOPEDIA_EXACT_PRIORITIES[normalizePharmText(input)];
  if (!priority) return null;
  const pools = {
    drug: pharmDrugs,
    lab: pharmSearchableLabRanges,
    pathology: pathologyDiseases,
    reference: clinicalReferenceEntries,
    holistic: holisticRemedies
  };
  const item = (pools[priority.type] || []).find((entry) => [
    entry?.name,
    entry?.generic,
    entry?.displayName,
    entry?.fullForm,
    priority.type === "drug" ? pharmDrugDisplayName(entry, "") : ""
  ].some((value) => normalizePharmText(value) === priority.identity));
  return item ? {
    type: priority.type,
    item,
    fastBoost: 1000,
    fastEvidenceScore: 1000,
    fastMatchCount: 1
  } : null;
}

function responsiveEncyclopediaPrefixPriority(input = "", scored = []) {
  const priority = REVIEWED_ENCYCLOPEDIA_PREFIX_PRIORITIES[fastCanonicalLookupCore(input) || normalizePharmText(input)];
  if (!priority) return null;
  return scored.find((candidate) => (
    candidate.type === priority.type
    && [
      candidate.item?.name,
      candidate.item?.generic,
      candidate.item?.displayName,
      pharmDrugDisplayName(candidate.item, "")
    ].some((value) => normalizePharmText(value) === priority.identity)
  )) || null;
}

function responsiveEncyclopediaSearchMatches(input = "") {
  const familyCandidates = responsiveEncyclopediaFamilyCandidates(input);
  if (familyCandidates.length) {
    return {
      lab: [],
      pathology: familyCandidates.map((candidate) => candidate.item),
      reference: [],
      holistic: [],
      drug: [],
      preferred: null,
      candidateCount: familyCandidates.length
    };
  }
  const types = ["lab", "pathology", "reference", "holistic", "drug"];
  const exactPrioritySource = responsiveEncyclopediaExactPriority(input);
  const topicResolution = resolveTopicRequest(input, { mode: "suggest", limit: 12 });
  const sharedIdentityResolution = topicResolution.identity;
  if (!exactPrioritySource && sharedIdentityResolution.suppressUnrelatedMatches === true) {
    const groups = { lab: [], pathology: [], reference: [], holistic: [], drug: [] };
    sharedIdentityResolution.candidates.forEach((candidate) => {
      if (groups[candidate.type] && !groups[candidate.type].includes(candidate.item)) {
        groups[candidate.type].push(candidate.item);
      }
    });
    return {
      ...groups,
      preferred: null,
      candidateCount: sharedIdentityResolution.candidates.length,
      ambiguousIdentity: true,
      matchKind: sharedIdentityResolution.matchKind
    };
  }
  const candidateMap = new Map();
  const add = (type, item, fastBoost = 0, fastEvidenceScore = 0, fastMatchCount = 0) => {
    if (!item) return;
    const candidate = { type, item, fastBoost, fastEvidenceScore, fastMatchCount };
    const key = offlineLookupEntityKey(candidate);
    const existing = candidateMap.get(key);
    if (!existing) {
      candidateMap.set(key, candidate);
      return;
    }
    existing.fastBoost = Math.max(existing.fastBoost || 0, fastBoost || 0);
    existing.fastEvidenceScore = Math.max(existing.fastEvidenceScore || 0, fastEvidenceScore || 0);
    existing.fastMatchCount = Math.max(existing.fastMatchCount || 0, fastMatchCount || 0);
  };
  collectReadyFastLookupCandidates(input, types).forEach((candidate) => add(
    candidate.type,
    candidate.item,
    candidate.fastBoost,
    candidate.fastEvidenceScore,
    candidate.fastMatchCount
  ));
  if (exactPrioritySource) add(
    exactPrioritySource.type,
    exactPrioritySource.item,
    exactPrioritySource.fastBoost,
    exactPrioritySource.fastEvidenceScore,
    exactPrioritySource.fastMatchCount
  );
  // Seed every category from the compact true-identity layer. This supports
  // title, alias, abbreviation, misspelling, brand, and partial-prefix search
  // immediately after launch without constructing the multi-second deep maps
  // on the user's keystroke. Contextual association terms remain in the
  // incremental content index and are never promoted to identity ownership.
  fastVoiceIdentitySearchCandidates(input, 80).forEach((candidate) => add(
    candidate.type,
    candidate.item,
    candidate.fastBoost,
    candidate.fastEvidenceScore,
    candidate.fastMatchCount
  ));
  sharedIdentityResolution.candidates.forEach((candidate) => add(
    candidate.type,
    candidate.item,
    candidate === sharedIdentityResolution.preferred ? 1700 : 340,
    candidate === sharedIdentityResolution.preferred ? 1700 : 340,
    1
  ));
  const reviewedResolution = topicResolution.resolutionKind === "reviewed-route"
    || topicResolution.resolutionKind === "ambiguous-reviewed-route"
    ? topicResolution.reviewed
    : null;
  (reviewedResolution?.candidates || []).forEach((candidate) => add(
    candidate.type,
    candidate.item,
    candidate.mayAutoOpen ? 1900 : 760,
    candidate.mayAutoOpen ? 1900 : 760,
    1
  ));
  const clinicalResolution = topicResolution.resolutionKind === "clinical-clue"
    ? topicResolution.clinical
    : null;
  (clinicalResolution?.candidates || []).forEach((candidate) => add(
    candidate.type,
    candidate.item,
    260 + Math.round(candidate.confidence * 360),
    540 + Math.round(candidate.score * 18),
    candidate.matchedClues.length
  ));

  // The inverted index has already reduced the corpus to records that share
  // query evidence. Deep scorers perform fuzzy description work, including
  // edit-distance checks across long educational cards, so run them only on
  // the strongest evidence-ranked candidates instead of all 80 retrieved
  // records. Exact aliases and records matching several query terms naturally
  // stay at the front of this shortlist.
  const deepScoreCandidates = Array.from(candidateMap.values())
    .sort((a, b) => (b.fastEvidenceScore || 0) - (a.fastEvidenceScore || 0)
      || (b.fastMatchCount || 0) - (a.fastMatchCount || 0)
      || (b.fastBoost || 0) - (a.fastBoost || 0)
      || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .slice(0, 10);
  const scored = deepScoreCandidates
    .map((candidate) => scoreFastLookupCandidate(candidate, input))
    .filter((candidate) => candidate.score >= 14)
    .sort((a, b) => b.score - a.score || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)));
  const groups = { lab: [], pathology: [], reference: [], holistic: [], drug: [] };
  scored.forEach((candidate) => {
    if (groups[candidate.type]?.length < 36) groups[candidate.type].push(candidate.item);
  });
  const exactPriority = exactPrioritySource
    ? scored.find((candidate) => candidate.type === exactPrioritySource.type
      && candidate.item === exactPrioritySource.item) || exactPrioritySource
    : null;
  if (exactPriority) {
    groups[exactPriority.type] = [
      exactPriority.item,
      ...groups[exactPriority.type].filter((item) => item !== exactPriority.item)
    ];
  }
  const prefixPriority = responsiveEncyclopediaPrefixPriority(input, scored);
  if (prefixPriority) {
    groups[prefixPriority.type] = [
      prefixPriority.item,
      ...groups[prefixPriority.type].filter((item) => item !== prefixPriority.item)
    ];
  }
  const sharedPreferred = sharedIdentityResolution.mayAutoOpen && sharedIdentityResolution.preferred
    ? scored.find((candidate) => candidate.type === sharedIdentityResolution.preferred.type
      && candidate.item === sharedIdentityResolution.preferred.item)
      || {
        type: sharedIdentityResolution.preferred.type,
        item: sharedIdentityResolution.preferred.item,
        score: 3900,
        sharedIdentityResolution: true
      }
    : null;
  if (!exactPriority && !prefixPriority && sharedPreferred && groups[sharedPreferred.type]) {
    groups[sharedPreferred.type] = [
      sharedPreferred.item,
      ...groups[sharedPreferred.type].filter((item) => item !== sharedPreferred.item)
    ];
  }
  const directPreferred = scored
    .filter((candidate) => inputDirectlyNamesOfflineCandidate(input, candidate)
      && offlineLookupIsDirectEnough(input, candidate))
    .map((candidate) => ({ candidate, mentionIndex: namedEncyclopediaCandidateMentionIndex(input, candidate) }))
    .filter((record) => Number.isFinite(record.mentionIndex))
    .sort((a, b) => a.mentionIndex - b.mentionIndex
      || b.candidate.score - a.candidate.score
      || offlineLookupEntityLabel(a.candidate).localeCompare(offlineLookupEntityLabel(b.candidate)))[0]?.candidate || null;
  const clinicalPreferred = clinicalResolution?.preferred
    ? scored.find((candidate) => candidate.type === clinicalResolution.preferred.type
      && candidate.item === clinicalResolution.preferred.item)
      || clinicalResolution.preferred
    : null;
  const reviewedPreferred = reviewedResolution?.preferred
    ? scored.find((candidate) => candidate.type === reviewedResolution.preferred.type
      && candidate.item === reviewedResolution.preferred.item)
      || reviewedResolution.preferred
    : null;
  if (!exactPriority && !prefixPriority && !sharedPreferred && reviewedPreferred && groups[reviewedPreferred.type]) {
    groups[reviewedPreferred.type] = [
      reviewedPreferred.item,
      ...groups[reviewedPreferred.type].filter((item) => item !== reviewedPreferred.item)
    ];
  }
  if (!exactPriority && !prefixPriority && !sharedPreferred && clinicalPreferred && groups[clinicalPreferred.type]) {
    groups[clinicalPreferred.type] = [
      clinicalPreferred.item,
      ...groups[clinicalPreferred.type].filter((item) => item !== clinicalPreferred.item)
    ];
  }
  const preferred = exactPriority || prefixPriority || sharedPreferred || reviewedPreferred || clinicalPreferred || directPreferred;
  return {
    ...groups,
    preferred,
    candidateCount: scored.length,
    reviewedRoute: reviewedResolution ? {
      status: reviewedResolution.status,
      mayAutoOpen: reviewedResolution.mayAutoOpen,
      ambiguousIdentity: reviewedResolution.ambiguousIdentity === true
    } : null,
    clinicalSearch: clinicalResolution ? {
      status: clinicalResolution.status,
      confidence: clinicalResolution.confidence,
      confidenceTier: clinicalResolution.confidenceTier,
      margin: clinicalResolution.margin,
      mayAutoOpen: clinicalResolution.mayAutoOpen,
      matchedClues: clinicalResolution.preferred?.matchedClues || [],
      unmatchedClues: clinicalResolution.preferred?.unmatchedClues || []
    } : null
  };
}

let medicalPhoneticIdentityIndex = null;
let medicalPhoneticIndexScheduled = false;

function medicalPhoneticForms(value = "") {
  const normalized = normalizePharmText(value);
  if (!normalized) return [];
  // Restricted, reviewed sound-to-spelling bridges. These generate
  // suggestions only; they never authorize automatic navigation.
  const hardCholine = normalized.replace(/ch(?=olin)/g, "k");
  const heardLol = normalized.replace(/lawl\b/g, "lol");
  const combined = hardCholine.replace(/lawl\b/g, "lol");
  return Array.from(new Map([
    { text: normalized, rule: "standard" },
    { text: hardCholine, rule: "hard-choline" },
    { text: heardLol, rule: "heard-lol" },
    { text: combined, rule: "combined" }
  ].map((record) => [record.text, record])).values());
}

function isRestrictedMedicalPhoneticInput(input = "") {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const core = fastCanonicalLookupCore(fixed) || normalizePharmText(fixed);
  if (!core) return false;
  return medicalPhoneticForms(core).some((form) => (
    form.text !== core && fastVoiceIdentityCandidates(form.text).length > 0
  ));
}

function medicalPhoneticKey(value = "") {
  const words = normalizePharmText(value)
    .split(" ")
    .filter((word) => word.length >= 2 && !FAST_LOOKUP_STOP_WORDS.has(word));
  if (!words.length) return "";
  return words.map((word) => {
    let token = word
      .replace(/^kn/, "n")
      .replace(/^wr/, "r")
      .replace(/sch/g, "sk")
      .replace(/tch|ch|sh/g, "j")
      .replace(/ph/g, "f")
      .replace(/ght/g, "t")
      .replace(/qu/g, "k")
      .replace(/ck/g, "k")
      .replace(/c(?=[eiy])/g, "s")
      .replace(/c/g, "k")
      .replace(/g(?=[eiy])/g, "j")
      .replace(/x/g, "ks")
      .replace(/z/g, "s")
      .replace(/v/g, "f")
      .replace(/y/g, "i")
      .replace(/[^a-z]/g, "");
    const first = token.charAt(0);
    token = `${first}${token.slice(1).replace(/[aeiou]/g, "")}`
      .replace(/(.)\1+/g, "$1");
    return token;
  }).join("");
}

function buildMedicalPhoneticIdentityIndex() {
  if (medicalPhoneticIdentityIndex) return medicalPhoneticIdentityIndex;
  const index = new Map();
  getFastVoiceIdentityIndex().forEach((owners, identity) => {
    medicalPhoneticForms(identity).forEach((form) => {
      const key = medicalPhoneticKey(form.text);
      if (!key || key.length < 4) return;
      const records = index.get(key) || [];
      owners.forEach((owner) => {
        if (!records.some((candidate) => candidate.type === owner.type && candidate.item === owner.item)) {
          records.push({
            type: owner.type,
            item: owner.item,
            phoneticIdentity: identity,
            phoneticRule: form.rule
          });
        }
      });
      index.set(key, records);
    });
  });
  medicalPhoneticIdentityIndex = index;
  medicalPhoneticIndexScheduled = false;
  if (typeof CustomEvent === "function") {
    window.dispatchEvent?.(new CustomEvent("ani-medical-phonetic-index-ready"));
  }
  return medicalPhoneticIdentityIndex;
}

function scheduleMedicalPhoneticIdentityIndex() {
  if (medicalPhoneticIdentityIndex || medicalPhoneticIndexScheduled) return;
  medicalPhoneticIndexScheduled = true;
  const build = () => {
    try {
      buildMedicalPhoneticIdentityIndex();
    } catch {
      medicalPhoneticIndexScheduled = false;
    }
  };
  if (window.requestIdleCallback) {
    window.requestIdleCallback(build, { timeout: 850 });
  } else {
    window.setTimeout(build, 80);
  }
}

function completeMedicalPhoneticIndexForAudit() {
  return buildMedicalPhoneticIdentityIndex();
}

function medicalPhoneticIdentityCandidates(input = "", limit = 4) {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const core = fastCanonicalLookupCore(fixed) || normalizePharmText(fixed);
  if (!core || core.length < 4 || core.split(" ").length > 4) return [];
  if (!medicalPhoneticIdentityIndex) {
    scheduleMedicalPhoneticIdentityIndex();
    return [];
  }
  const matches = [];
  medicalPhoneticForms(core).forEach((form) => {
    const key = medicalPhoneticKey(form.text);
    if (!key || key.length < 4) return;
    (medicalPhoneticIdentityIndex.get(key) || []).forEach((candidate) => matches.push({
      ...candidate,
      queryPhoneticRule: form.rule
    }));
  });
  return Array.from(new Map(matches
    .filter((candidate) => normalizePharmText(offlineLookupEntityLabel(candidate)) !== core)
    .map((candidate) => [offlineLookupEntityKey(candidate), {
      ...candidate,
      score: 720,
      phoneticMatch: true,
      identitySuggestionOnly: true,
      mayAutoOpen: false
    }])).values())
    .sort((a, b) => offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .slice(0, Math.max(1, limit));
}

function medicalSearchAssistCandidates(input = "", limit = 6) {
  const familyCandidates = responsiveEncyclopediaFamilyCandidates(input);
  if (familyCandidates.length) {
    return {
      query: safeText(input),
      core: normalizePharmText(input),
      candidates: familyCandidates.slice(0, Math.max(1, limit)).map((candidate) => ({
        type: candidate.type,
        item: candidate.item,
        label: offlineLookupEntityLabel(candidate),
        kind: offlineLookupEntityKind(candidate),
        matchKind: "reviewed-family",
        mayAutoOpen: false
      })),
      preferred: null,
      matchKind: "reviewed-family",
      mayAutoOpen: false
    };
  }
  const exactPriority = responsiveEncyclopediaExactPriority(input);
  if (exactPriority) {
    const preferred = { type: exactPriority.type, item: exactPriority.item };
    return {
      query: safeText(input),
      core: normalizePharmText(input),
      candidates: [{
        ...preferred,
        label: offlineLookupEntityLabel(preferred),
        kind: offlineLookupEntityKind(preferred),
        matchKind: "reviewed-exact",
        mayAutoOpen: true
      }],
      preferred,
      matchKind: "reviewed-exact",
      mayAutoOpen: true
    };
  }
  const topicResolution = resolveTopicRequest(input, { mode: "suggest", limit });
  const identity = topicResolution.identity;
  const reviewedResolution = topicResolution.resolutionKind === "reviewed-route"
    || topicResolution.resolutionKind === "ambiguous-reviewed-route"
    ? topicResolution.reviewed
    : null;
  const clinicalResolution = topicResolution.resolutionKind === "clinical-clue"
    ? topicResolution.clinical
    : null;
  const candidateSource = identity.candidates.length
    ? identity.candidates
    : reviewedResolution?.candidates || clinicalResolution?.candidates || [];
  const candidates = candidateSource.map((candidate) => ({
    type: candidate.type,
    item: candidate.item,
    label: offlineLookupEntityLabel(candidate),
    kind: offlineLookupEntityKind(candidate),
    matchKind: candidate.reviewedRoute === true
      ? "reviewed-route"
      : candidate.clinicalClueMatch === true
      ? "clinical-clue"
      : candidate.phoneticMatch === true || identity.matchKind === "phonetic-suggestions"
      ? "phonetic-suggestion"
      : candidate === identity.preferred || identity.suppressUnrelatedMatches === true
      ? identity.matchKind
      : "prefix-suggestion",
    mayAutoOpen: candidate.phoneticMatch === true
      ? false
      : candidate.reviewedRoute === true
      ? candidate.mayAutoOpen === true
      : candidate.clinicalClueMatch === true
      ? candidate.mayAutoOpen === true
      : candidate === identity.preferred && identity.mayAutoOpen,
    ambiguousIdentity: candidate.ambiguousIdentity === true || identity.suppressUnrelatedMatches === true,
    identitySuggestionOnly: candidate.identitySuggestionOnly === true || identity.suppressUnrelatedMatches === true,
    termKinds: Array.isArray(candidate.termKinds) ? [...candidate.termKinds] : [],
    sourceFields: Array.isArray(candidate.sourceFields) ? [...candidate.sourceFields] : [],
    confidence: Number(candidate.confidence || 0),
    confidenceTier: candidate.confidenceTier || "",
    matchedClues: Array.isArray(candidate.matchedClues) ? [...candidate.matchedClues] : [],
    unmatchedClues: Array.isArray(candidate.unmatchedClues) ? [...candidate.unmatchedClues] : [],
    fieldPaths: Array.isArray(candidate.fieldPaths) ? [...candidate.fieldPaths] : []
  }));
  if (!candidates.length) {
    medicalPhoneticIdentityCandidates(input, limit).forEach((candidate) => candidates.push({
      type: candidate.type,
      item: candidate.item,
      label: offlineLookupEntityLabel(candidate),
      kind: offlineLookupEntityKind(candidate),
      matchKind: "phonetic-suggestion",
      mayAutoOpen: false
    }));
  }
  return {
    query: safeText(input),
    core: identity.core,
    candidates: Array.from(new Map(candidates
      .filter((candidate) => candidate.label)
      .map((candidate) => [`${candidate.type}:${normalizePharmText(candidate.label)}`, candidate])).values())
      .slice(0, Math.max(1, limit)),
    preferred: topicResolution.preferred,
    matchKind: identity.candidates.length
      ? identity.matchKind
      : reviewedResolution?.preferred ? "reviewed-route" : clinicalResolution?.preferred ? "clinical-clue" : identity.matchKind,
    mayAutoOpen: topicResolution.mayAutoOpen === true,
    confidence: Number(clinicalResolution?.confidence || 0),
    confidenceTier: clinicalResolution?.confidenceTier || "",
    margin: Number(clinicalResolution?.margin || 0),
    ambiguousIdentity: identity.suppressUnrelatedMatches === true,
    recognizedAbbreviation: identity.recognizedAbbreviation === true
  };
}

function encyclopediaSynonymCandidates(input = "", types = ["lab", "pathology", "reference", "holistic", "drug"]) {
  const indexes = getPharmFastIndexes(types);
  const { exactKeys } = fastLookupQueryParts(input);
  const typeSet = new Set(types);
  const matches = new Map();
  exactKeys.forEach((key) => {
    (indexes.synonymExact.get(key) || []).forEach((candidate) => {
      if (!typeSet.has(candidate.type)) return;
      matches.set(offlineLookupEntityKey(candidate), { type: candidate.type, item: candidate.item });
    });
  });
  return Array.from(matches.values());
}

function indexedEncyclopediaSearchPool(type = "", sourceItems = [], query = "") {
  if (!query || !sourceItems.length) return sourceItems;
  const allowed = new Set(sourceItems);
  const indexed = collectFastLookupCandidates(query, [type])
    .filter((candidate) => candidate.type === type && allowed.has(candidate.item))
    .map((candidate) => candidate.item);
  const aliases = encyclopediaSynonymCandidates(query, [type])
    .filter((candidate) => allowed.has(candidate.item))
    .map((candidate) => candidate.item);
  // A synonym hit narrows identity, but it must not discard indexed records
  // with that same canonical identity. Include only those peers so population
  // scoring can choose pediatric, maternal, geriatric, or adult ranges without
  // widening every synonym lookup into a slower general candidate pool.
  if (aliases.length) {
    const aliasIdentityNames = new Set(aliases
      .flatMap((item) => [item?.name, item?.displayName])
      .map((term) => normalizePharmText(term))
      .filter(Boolean));
    const identityPeers = indexed.filter((item) => [item?.name, item?.displayName]
      .map((term) => normalizePharmText(term))
      .some((term) => term && aliasIdentityNames.has(term)));
    return Array.from(new Set([...aliases, ...identityPeers]));
  }
  const candidates = Array.from(new Set([...aliases, ...indexed]));
  if (candidates.length) return candidates;
  const meaningfulTokens = normalizePharmText(query)
    .split(" ")
    .filter((token) => token.length >= 3 && !FAST_LOOKUP_STOP_WORDS.has(token));
  return meaningfulTokens.length ? [] : sourceItems;
}

function scoreFastLookupCandidate(candidate = {}, input = "") {
  const { variants } = fastLookupQueryParts(input);
  const labIntent = wantsLabRangeLookup(input);
  const scoreFrom = (scorer) => Math.max(...variants.map((variant) => scorer(variant)), 0);
  let score = candidate.fastBoost || 0;
  if (candidate.type === "lab") {
    score += scoreFrom((variant) => scorePharmLabEntry(candidate.item, variant));
    if (labIntent) score += 180;
    score += scoreLabPopulationFit(candidate.item, input);
  } else if (candidate.type === "pathology") {
    score += scoreFrom((variant) => scorePathologyEntry(candidate.item, variant));
  } else if (candidate.type === "holistic") {
    score += scoreFrom((variant) => scoreHolisticEntry(candidate.item, variant));
  } else if (candidate.type === "reference") {
    // "HINTS" is a clinical acronym only in a vestibular context. A token hit
    // from ordinary study language must be a hard rejection so the fast-index
    // boost cannot resurrect a match that the reference scorer excluded.
    if (normalizePharmText(candidate.item?.name) === "hints examination"
      && queryUsesHintsAsOrdinaryLanguage(input)) {
      return { type: candidate.type, item: candidate.item, score: 0 };
    }
    score += scoreFrom((variant) => scoreClinicalReferenceEntry(candidate.item, variant));
    if (candidate.item?.type === "growth" && wantsGrowthReference(input)) score += 260;
    if (candidate.item?.type === "maternity" && wantsPregnancyMilestoneReference(input)) score += 240;
    if (candidate.item?.type === "maternity" && wantsGestationalWeightGainReference(input)) score += 500;
    if (candidate.item?.type === "procedure" && wantsProcedureTestReference(input)) score += 160;
  } else if (candidate.type === "drug") {
    score += scoreFrom((variant) => scorePharmEntry(candidate.item, variant));
    if (labIntent) score -= 90;
  }
  return { type: candidate.type, item: candidate.item, score };
}

function fastOfflineLookupSuggestions(input = "", types = ["lab", "pathology", "holistic", "drug"]) {
  const candidates = collectFastLookupCandidates(input, types);
  if (!candidates.length) return [];
  return candidates
    .map((candidate) => scoreFastLookupCandidate(candidate, input))
    .filter((candidate) => candidate.score >= 38)
    .sort((a, b) => b.score - a.score || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .slice(0, 8);
}

function pharmSearchUseText(drug = {}) {
  return pharmUsedToTreat(drug);
}

function pharmEntryTerms(drug = {}, options = {}) {
  const includeTags = options.includeTags !== false;
  const navigationOnlyGeneratedClass = drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only";
  const cacheKey = navigationOnlyGeneratedClass
    ? (includeTags ? "navigationWithTags" : "navigationWithoutTags")
    : (includeTags ? "withTags" : "withoutTags");
  const cached = pharmEntryTermCache.get(drug);
  if (cached?.[cacheKey]) {
    return cached[cacheKey];
  }
  if (navigationOnlyGeneratedClass) {
    const navigationTerms = [
      pharmDrugDisplayName(drug, ""),
      drug.name,
      drug.generic,
      drug.displayName,
      drug.class,
      pharmClassPathwayText(drug),
      drug.templateKey,
      ...medicalAbbreviationSearchTermsForText([drug.class, drug.templateKey, pharmClassPathwayText(drug)].join(" ")),
      ...(drug.brandExamples || []),
      ...(drug.aliases || []),
      ...(Array.isArray(drug.classPathway) ? drug.classPathway : []),
      ...(includeTags ? (drug.tags || []) : [])
    ]
      .map((term) => normalizePharmText(term))
      .filter(Boolean)
      .filter((term) => isAllowedStandaloneMedicationSearchTerm(drug, term, { allowPrimary: true }));
    const uniqueNavigationTerms = Array.from(new Set(navigationTerms));
    pharmEntryTermCache.set(drug, { ...(cached || {}), [cacheKey]: uniqueNavigationTerms });
    return uniqueNavigationTerms;
  }
  const terms = [
    pharmDrugDisplayName(drug, ""),
    drug.name,
    drug.generic,
    drug.displayName,
    drug.class,
    pharmInferredClassText(drug),
    pharmClassPathwayText(drug),
    drug.templateKey,
    ...medicalAbbreviationSearchTermsForText([drug.class, drug.templateKey, pharmClassPathwayText(drug)].join(" ")),
    drug.mechanism,
    pharmSearchUseText(drug),
    drug.sourceNote,
    drug.boxedWarning,
    pharmSpecificBoxedWarningText(drug),
    ...(drug.brandExamples || []),
    ...(drug.aliases || []),
    ...(Array.isArray(drug.classPathway) ? drug.classPathway : []),
    ...(drug.contraindications || []),
    ...((drug.populationRisks || []).flatMap((risk) => [risk.type, risk.label, risk.note])),
    ...(includeTags ? (drug.tags || []) : [])
  ]
    .map((term) => normalizePharmText(term))
    .filter(Boolean)
    .filter((term) => isAllowedStandaloneMedicationSearchTerm(drug, term, { allowPrimary: true }));
  const uniqueTerms = Array.from(new Set(terms));
  pharmEntryTermCache.set(drug, { ...(cached || {}), [cacheKey]: uniqueTerms });
  return uniqueTerms;
}

function pharmEntrySearchBlob(drug = {}) {
  const cached = pharmEntrySearchBlobCache.get(drug);
  if (cached) return cached;
  const blob = pharmEntryTerms(drug).join(" ");
  pharmEntrySearchBlobCache.set(drug, blob);
  return blob;
}

function pharmEntryCouldMatchQuery(drug = {}, cleanQuery = "") {
  if (!cleanQuery) return true;
  const blob = pharmEntrySearchBlob(drug);
  if (blob.includes(cleanQuery)) return true;
  const tokens = cleanQuery.split(" ").filter((token) => token.length >= 4);
  if (!tokens.length) return false;
  return tokens.some((token) => {
    if (blob.includes(token)) return true;
    const prefix = token.slice(0, Math.min(5, Math.max(3, token.length - 1)));
    return prefix.length >= 3 && blob.includes(prefix);
  });
}

const DESCRIPTION_LOOKUP_STOP_WORDS = new Set([
  ...FAST_LOOKUP_STOP_WORDS,
  "one",
  "two",
  "three",
  "and",
  "or",
  "of",
  "for",
  "to",
  "from",
  "in",
  "into",
  "at",
  "by",
  "as",
  "be",
  "it",
  "this",
  "that",
  "these",
  "those",
  "there",
  "their",
  "they",
  "has",
  "have",
  "having",
  "had",
  "made",
  "makes",
  "make",
  "with",
  "without",
  "thing",
  "stuff",
  "item",
  "concept",
  "called",
  "named",
  "name",
  "remember",
  "recall",
  "similar",
  "like",
  "kind",
  "type",
  "types",
  "client",
  "patient",
  "nurse",
  "nursing",
  "symptom",
  "symptoms",
  "sign",
  "signs",
  "finding",
  "findings",
  "cause",
  "causes",
  "caused",
  "trigger",
  "triggers",
  "happen",
  "happens",
  "work",
  "works",
  "body",
  "system",
  "problem",
  "issues",
  "issue"
]);

const DESCRIPTION_SYNONYM_GROUPS = [
  ["low", "decreased", "decrease", "reduced", "deficient", "deficiency", "hypo", "down"],
  ["high", "elevated", "increase", "increased", "excess", "hyper", "up"],
  ["kids", "kid", "child", "children", "pediatric", "peds", "infant", "adolescent"],
  ["older", "elderly", "geriatric", "senior", "adult"],
  ["pregnancy", "pregnant", "maternal", "maternity", "prenatal", "obstetric"],
  ["heart", "cardiac", "cardio"],
  ["kidney", "renal", "nephro"],
  ["liver", "hepatic", "hepat"],
  ["lung", "pulmonary", "respiratory"],
  ["sugar", "glucose", "glycemic"],
  ["blood", "hematologic", "hematology"],
  ["clot", "coagulation", "coagulopathy", "thrombus", "thrombosis"],
  ["breathing", "respiration", "respiratory", "ventilation"],
  ["airway", "laryngeal", "laryngospasm", "stridor"],
  ["fever", "temperature", "temp"],
  ["hidden", "occult"],
  ["stool", "fecal", "feces", "bowel"],
  ["reversal", "antidote", "reverse", "treats toxicity", "toxicity"],
  ["poison", "toxicity", "overdose", "toxic"],
  ["rash", "dermatitis", "eczema", "skin"],
  ["swelling", "edema", "fluid"]
];

const DESCRIPTION_SYNONYMS = DESCRIPTION_SYNONYM_GROUPS.reduce((map, group) => {
  group.forEach((term) => {
    const clean = normalizePharmText(term);
    if (clean) {
      map.set(clean, group.map((item) => normalizePharmText(item)).filter(Boolean));
    }
  });
  return map;
}, new Map());

function descriptionStemToken(token = "") {
  const clean = normalizePharmText(token);
  if (clean.length <= 4) return clean;
  return clean
    .replace(/(?:ing|ed)$/i, "")
    .replace(/(?:ies)$/i, "y")
    .replace(/(?:es|s)$/i, "");
}

function descriptionQueryTokens(query = "") {
  const fixed = applyClinicalSpeechFixups(query) || query;
  const clean = normalizeOfflineLookupText(fixed, { dropLookupWords: false }) || normalizePharmText(fixed);
  return Array.from(new Set(clean
    .split(" ")
    .map((token) => descriptionStemToken(token))
    .filter((token) => token.length >= 3 && !DESCRIPTION_LOOKUP_STOP_WORDS.has(token))));
}

function descriptionTokenVariants(token = "") {
  const clean = descriptionStemToken(token);
  if (!clean) return [];
  const variants = new Set([clean]);
  const synonymSet = DESCRIPTION_SYNONYMS.get(clean);
  if (synonymSet) {
    synonymSet.forEach((term) => variants.add(descriptionStemToken(term)));
  }
  if (clean.startsWith("hyper") && clean.length > 7) {
    variants.add(clean.replace(/^hyper/, "high "));
  }
  if (clean.startsWith("hypo") && clean.length > 6) {
    variants.add(clean.replace(/^hypo/, "low "));
  }
  return Array.from(variants).filter(Boolean);
}

function descriptionCacheRecord(item = {}) {
  if (!item || typeof item !== "object") return {};
  const cached = pharmDescriptionMatchCache.get(item);
  if (cached) return cached;
  const record = {};
  pharmDescriptionMatchCache.set(item, record);
  return record;
}

function flattenDescriptionPieces(value) {
  if (!value) return [];
  if (Array.isArray(value)) return value.flatMap((item) => flattenDescriptionPieces(item));
  if (typeof value === "object") {
    return Object.values(value).flatMap((item) => flattenDescriptionPieces(item));
  }
  return [safeText(value)];
}

function descriptionPiecesForCandidate(type = "", item = {}) {
  if (type === "drug") {
    if (isNavigationOnlyGeneratedMedicationClass(item)) {
      return flattenDescriptionPieces([
        pharmDrugDisplayName(item, ""),
        item.name,
        item.generic,
        item.displayName,
        item.class,
        pharmClassPathwayText(item),
        item.templateKey,
        item.brandExamples,
        item.aliases,
        item.tags
      ]);
    }
    return flattenDescriptionPieces([
      pharmDrugDisplayName(item, ""),
      item.name,
      item.generic,
      item.class,
      item.templateKey,
      item.mechanism,
      pharmUsedToTreat(item),
      item.boxedWarning,
      item.sourceNote,
      item.brandExamples,
      item.aliases,
      item.contraindications,
      item.interactions,
      item.keyLabs,
      item.nursingEssentials,
      item.routes,
      item.administration,
      item.seriousAdverseReactions,
      item.toxicityManagement,
      item.specialPopulations,
      item.patientEducation,
      item.nclexTraps,
      item.tags,
      item.populationRisks
    ]);
  }
  if (type === "lab") {
    return flattenDescriptionPieces([
      item.name,
      item.category,
      item.populationGroup,
      item.sourceType,
      item.range,
      item.why,
      item.groupNote,
      item.tags,
      typeof labProjectedTeachingSections === "function"
        ? labProjectedTeachingSections(item).map((section) => section.value)
        : []
    ]);
  }
  if (type === "pathology") {
    return flattenDescriptionPieces([
      item.name,
      item.category,
      item.pathology,
      item.etiology,
      item.aliases,
      item.signsSymptoms,
      item.diagnostics,
      typeof pathologyDiagnosticAlterationText === "function" ? pathologyDiagnosticAlterationText(item) : "",
      item.treatments,
      item.nursingPriorities,
      item.complications,
      item.patientEducation,
      item.nclexTraps,
      item.tags
    ]);
  }
  if (type === "reference") {
    return flattenDescriptionPieces([
      item.name,
      item.displayName,
      item.fullForm,
      item.type,
      item.category,
      item.aliases,
      item.abbreviations,
      item.commonMisspellings,
      item.searchTerms,
      item.summary,
      item.quickAnswer,
      item.whyItMatters,
      item.associatedConditions,
      item.clinicalInterpretation,
      item.diagnosticUsefulness,
      item.nursingRelevance,
      item.urgentEscalation,
      item.evidenceLimitations,
      item.resultMeanings,
      item.tags,
      item.sections,
      item.sourceNote
    ]);
  }
  if (type === "holistic") {
    return flattenDescriptionPieces([
      item.name,
      item.category,
      item.mechanism,
      item.aliases,
      item.usedFor,
      item.majorRisks,
      item.interactions,
      item.contraindications,
      item.nursingAssessment,
      item.teaching,
      item.nclexTraps,
      item.tags,
      item.populationRisks
    ]);
  }
  return [];
}

/*
 * ANI's clinical search intelligence is a derived, in-memory view of the same
 * five production collections used by the encyclopedia. It adds no medical
 * claims and never treats clue text as an alias. Instead, it retains the
 * authored field that supplied each clue, measures how rare that clue is
 * across the installed corpus, and combines several independent clues before
 * offering a card. The index is filled by the existing idle content-index
 * queue so it does not add a second startup scan or block typing.
 */
function clinicalSearchIntelligenceFields(record = {}) {
  const item = record.item || {};
  const fields = [];
  const add = (path, weight, value) => {
    const pieces = flattenDescriptionPieces(value).map(safeText).filter(Boolean);
    if (pieces.length) fields.push({ path, weight, pieces });
  };
  add("identity", 3.4, [item.name, item.generic, item.displayName, item.fullForm]);
  add("aliases", 3.1, [item.aliases, item.abbreviations, item.commonMisspellings]);
  add("category", 1.15, [item.type, item.category, item.class, item.templateKey]);
  add("tags", 1.35, [item.tags, item.searchTerms]);

  if (record.type === "reference") {
    add("quickAnswer", 2.9, item.quickAnswer);
    add("summary", 2.6, item.summary);
    add("associatedConditions", 2.9, item.associatedConditions);
    add("clinicalInterpretation", 2.75, item.clinicalInterpretation);
    add("whyItMatters", 2.55, item.whyItMatters);
    add("diagnosticUsefulness", 2.35, item.diagnosticUsefulness);
    add("urgentEscalation", 2.4, item.urgentEscalation);
    add("nursingRelevance", 2.15, item.nursingRelevance);
    add("evidenceLimitations", 1.8, item.evidenceLimitations);
    add("resultMeanings", 2.2, item.resultMeanings);
    clinicalReferenceSectionPairs(item).forEach((section, index) => {
      add(`sections.${index}`, 2.25, section);
    });
  } else if (record.type === "pathology") {
    add("signsSymptoms", 2.9, item.signsSymptoms);
    add("diagnostics", 2.55, [item.diagnostics, typeof pathologyDiagnosticAlterationText === "function"
      ? pathologyDiagnosticAlterationText(item)
      : ""]);
    add("pathology", 2.3, item.pathology);
    add("etiology", 2.15, item.etiology);
    add("complications", 2.35, item.complications);
    add("nursingPriorities", 2.15, item.nursingPriorities);
    add("treatments", 1.75, item.treatments);
    add("nclexTraps", 1.9, item.nclexTraps);
  } else if (record.type === "drug") {
    add("usedToTreat", 2.7, pharmUsedToTreat(item));
    add("mechanism", 2.55, item.mechanism);
    add("boxedWarning", 2.75, item.boxedWarning);
    add("seriousAdverseReactions", 2.65, item.seriousAdverseReactions);
    add("toxicityManagement", 2.6, item.toxicityManagement);
    add("contraindications", 2.5, item.contraindications);
    add("interactions", 2.25, item.interactions);
    add("keyLabs", 2.3, item.keyLabs);
    add("nursingEssentials", 2.15, item.nursingEssentials);
    add("administration", 1.95, [item.routes, item.administration]);
    add("specialPopulations", 2.0, [item.specialPopulations, item.populationRisks]);
    add("patientEducation", 1.85, item.patientEducation);
    add("nclexTraps", 1.9, item.nclexTraps);
  } else if (record.type === "lab") {
    add("why", 2.8, item.why);
    add("range", 2.25, [item.range, item.groupNote]);
    add("highCauses", 2.65, item.highCauses);
    add("lowCauses", 2.65, item.lowCauses);
    add("criticalConcerns", 2.8, item.criticalConcerns);
    add("nursingConsiderations", 2.25, item.nursingConsiderations);
    add("nclexTraps", 2.0, item.nclexTraps);
  } else if (record.type === "holistic") {
    add("usedFor", 2.6, item.usedFor);
    add("mechanism", 2.35, item.mechanism);
    add("majorRisks", 2.65, item.majorRisks);
    add("contraindications", 2.5, item.contraindications);
    add("interactions", 2.4, item.interactions);
    add("nursingAssessment", 2.2, item.nursingAssessment);
    add("teaching", 1.9, item.teaching);
    add("nclexTraps", 1.9, item.nclexTraps);
  }
  return fields;
}

function clinicalSearchIntelligenceTokens(value = "") {
  return normalizePharmText(value)
    .split(" ")
    .map((token) => descriptionStemToken(token))
    .filter((token) => token.length >= 3 && !DESCRIPTION_LOOKUP_STOP_WORDS.has(token));
}

function ensureClinicalSearchIntelligenceIndex() {
  if (clinicalSearchIntelligenceIndex) return clinicalSearchIntelligenceIndex;
  clinicalSearchIntelligenceIndex = {
    records: [],
    recordMembership: new WeakSet(),
    postings: new Map(),
    documentFrequency: new Map(),
    byFirstLength: new Map(),
    byInnerLength: new Map()
  };
  return clinicalSearchIntelligenceIndex;
}

function addClinicalSearchIntelligenceRecord(record = {}) {
  const item = record.item;
  if (!item || typeof item !== "object") return false;
  const index = ensureClinicalSearchIntelligenceIndex();
  if (index.recordMembership.has(item)) return false;
  const tokenEvidence = new Map();
  const clueSets = [];
  clinicalSearchIntelligenceFields(record).forEach((field) => {
    field.pieces.forEach((piece) => {
      const pieceTokens = Array.from(new Set(clinicalSearchIntelligenceTokens(piece)));
      if (pieceTokens.length >= 2) {
        clueSets.push({ path: field.path, weight: field.weight, tokens: pieceTokens });
      }
      pieceTokens.forEach((token) => {
        const previous = tokenEvidence.get(token);
        if (!previous) {
          tokenEvidence.set(token, { weight: field.weight, paths: new Set([field.path]) });
          return;
        }
        previous.weight = Math.max(previous.weight, field.weight);
        previous.paths.add(field.path);
      });
    });
  });
  if (!tokenEvidence.size) return false;
  const indexedRecord = {
    type: record.type,
    item,
    tokenEvidence,
    clueSets,
    blob: descriptionSearchBlob(record.type, item)
  };
  index.records.push(indexedRecord);
  index.recordMembership.add(item);
  tokenEvidence.forEach((evidence, token) => {
    if (!index.postings.has(token)) index.postings.set(token, []);
    index.postings.get(token).push({ record: indexedRecord, evidence });
    index.documentFrequency.set(token, (index.documentFrequency.get(token) || 0) + 1);
    const firstKey = `${token[0]}:${token.length}`;
    const innerKey = `${token.slice(1, 3)}:${token.length}`;
    if (!index.byFirstLength.has(firstKey)) index.byFirstLength.set(firstKey, new Set());
    if (!index.byInnerLength.has(innerKey)) index.byInnerLength.set(innerKey, new Set());
    index.byFirstLength.get(firstKey).add(token);
    index.byInnerLength.get(innerKey).add(token);
  });
  return true;
}

function clinicalSearchTokenImportance(token = "", index = ensureClinicalSearchIntelligenceIndex()) {
  const documents = Math.max(1, index.records.length);
  const frequency = Math.max(0, index.documentFrequency.get(token) || 0);
  return Math.min(4.8, Math.max(0.18, Math.log((documents + 1) / (frequency + 1))));
}

function clinicalSearchFuzzyTokens(queryToken = "", index = ensureClinicalSearchIntelligenceIndex()) {
  const token = descriptionStemToken(queryToken);
  if (token.length < 5) return [];
  const radius = token.length <= 7 ? 1 : 2;
  const candidates = new Set();
  for (let length = Math.max(5, token.length - radius); length <= token.length + radius; length += 1) {
    (index.byFirstLength.get(`${token[0]}:${length}`) || []).forEach((candidate) => candidates.add(candidate));
    (index.byInnerLength.get(`${token.slice(1, 3)}:${length}`) || []).forEach((candidate) => candidates.add(candidate));
  }
  return Array.from(candidates)
    .map((candidate) => {
      const distance = nearIdentityEditDistance(token, candidate);
      const maximumLength = Math.max(token.length, candidate.length);
      return { token: candidate, distance, similarity: 1 - (distance / maximumLength) };
    })
    .filter((candidate) => candidate.distance > 0
      && candidate.distance <= radius
      && candidate.similarity >= (token.length <= 7 ? 0.82 : 0.78))
    .sort((left, right) => right.similarity - left.similarity
      || clinicalSearchTokenImportance(right.token, index) - clinicalSearchTokenImportance(left.token, index)
      || left.token.localeCompare(right.token))
    .slice(0, 4);
}

function clinicalSearchConfidenceTier(value = 0) {
  if (value >= 0.82) return "high";
  if (value >= 0.62) return "moderate";
  return "low";
}

function isPersonalClinicalNarrative(input = "") {
  const inputText = safeText(input);
  return /\b(?:i|i'm|im|i've|ive|my|me|we|we're|our)\b/i.test(inputText)
    || /\b(?:my|our|this|the)\s+(?:patient|client|child|baby|toddler)\b/i.test(inputText)
    || /\b(?:patient|client|child|baby|toddler)\s+(?:has|have|is|are|was|were|feels?|reports?|developed?|started?|cannot|can't)\b/i.test(inputText);
}

function clinicalSearchIntelligence(input = "", options = {}) {
  const limit = Math.max(1, Math.min(12, Number(options.limit || 8)));
  const index = ensureClinicalSearchIntelligenceIndex();
  const queryTokens = descriptionQueryTokens(input).slice(0, 18);
  const personalClinicalNarrative = isPersonalClinicalNarrative(input);
  const unavailable = (status) => ({
    schemaVersion: "ani-clinical-search-intelligence-v1",
    status,
    queryTokens,
    candidates: [],
    preferred: null,
    confidence: 0,
    confidenceTier: "low",
    margin: 0,
    mayAutoOpen: false
  });
  if (!pharmContentIndexesReady) return unavailable("INDEXING");
  if (queryTokens.length < 2) return unavailable("INSUFFICIENT_CLUES");
  const cacheKey = `${personalClinicalNarrative ? "personal" : "reference"}|${queryTokens.join("|")}`;
  if (clinicalSearchIntelligenceCache.has(cacheKey)) {
    const cached = clinicalSearchIntelligenceCache.get(cacheKey);
    clinicalSearchIntelligenceCache.delete(cacheKey);
    clinicalSearchIntelligenceCache.set(cacheKey, cached);
    return { ...cached, candidates: cached.candidates.slice(0, limit) };
  }

  const candidateEvidence = new Map();
  const addPosting = (queryToken, matchedToken, matchQuality, matchKind) => {
    const importance = clinicalSearchTokenImportance(matchedToken, index);
    (index.postings.get(matchedToken) || []).forEach((posting) => {
      let candidate = candidateEvidence.get(posting.record);
      if (!candidate) {
        candidate = { record: posting.record, byQueryToken: new Map() };
        candidateEvidence.set(posting.record, candidate);
      }
      const fieldFactor = 0.34 + (Math.min(3.4, posting.evidence.weight) / 3.4) * 1.16;
      const contribution = importance * matchQuality * fieldFactor;
      const previous = candidate.byQueryToken.get(queryToken);
      if (!previous || contribution > previous.contribution) {
        candidate.byQueryToken.set(queryToken, {
          queryToken,
          matchedToken,
          matchKind,
          matchQuality,
          importance,
          contribution,
          paths: Array.from(posting.evidence.paths).sort()
        });
      }
    });
  };
  queryTokens.forEach((queryToken) => {
    if (index.postings.has(queryToken)) addPosting(queryToken, queryToken, 1, "exact-clue");
    clinicalSearchFuzzyTokens(queryToken, index).forEach((candidate) => {
      addPosting(queryToken, candidate.token, candidate.similarity * 0.86, "fuzzy-clue");
    });
  });

  const fallbackImportance = queryTokens.reduce((sum, token) => (
    sum + (index.postings.has(token) ? clinicalSearchTokenImportance(token, index) : 2.4)
  ), 0) || 1;
  const candidates = Array.from(candidateEvidence.values()).map((candidate) => {
    const matches = Array.from(candidate.byQueryToken.values())
      .sort((left, right) => right.contribution - left.contribution || left.queryToken.localeCompare(right.queryToken));
    const matchedTokens = new Set(matches.map((match) => match.queryToken));
    const matchedImportance = matches.reduce((sum, match) => sum + (match.importance * match.matchQuality), 0);
    const coverage = Math.min(1, matchedImportance / fallbackImportance);
    const fuzzyCount = matches.filter((match) => match.matchKind === "fuzzy-clue").length;
    const distinctiveMatches = matches.filter((match) => match.importance >= 2.5).length;
    const fieldPaths = Array.from(new Set(matches.flatMap((match) => match.paths))).sort();
    const unmatchedClues = queryTokens.filter((token) => !matchedTokens.has(token));
    const bestClueSet = candidate.record.clueSets.map((clueSet) => {
      const tokens = clueSet.tokens.filter((token) => matchedTokens.has(token));
      return {
        path: clueSet.path,
        weight: clueSet.weight,
        tokens,
        coverage: tokens.length / Math.max(1, clueSet.tokens.length)
      };
    }).filter((clueSet) => clueSet.tokens.length >= 2)
      .sort((left, right) => right.tokens.length - left.tokens.length
        || right.coverage - left.coverage
        || right.weight - left.weight)[0] || null;
    const signatureBonus = bestClueSet
      ? bestClueSet.tokens.length * bestClueSet.weight * 0.52
        + Math.min(2.8, bestClueSet.coverage * bestClueSet.weight)
        + (bestClueSet.path === "aliases" ? 2.4 : bestClueSet.path === "identity" ? 1.8 : 0)
      : 0;
    const phraseBonus = matches.length >= 2 && candidate.record.blob.includes(
      matches.slice().sort((left, right) => queryTokens.indexOf(left.queryToken) - queryTokens.indexOf(right.queryToken))
        .map((match) => match.matchedToken).join(" ")
    ) ? 1.2 : 0;
    const score = matches.reduce((sum, match) => sum + match.contribution, 0)
      + Math.min(3.2, matches.length * 0.45)
      + Math.min(2.4, distinctiveMatches * 0.5)
      + signatureBonus
      + phraseBonus
      - Math.max(0, unmatchedClues.length - 1) * 0.18;
    return {
      type: candidate.record.type,
      item: candidate.record.item,
      score,
      coverage,
      matches,
      matchedClues: matches.map((match) => match.queryToken),
      unmatchedClues,
      fieldPaths,
      bestClueSet,
      signatureBonus,
      fuzzyCount,
      distinctiveMatches
    };
  }).filter((candidate) => candidate.matchedClues.length >= 2
    && candidate.coverage >= 0.3
    && (candidate.distinctiveMatches >= 1 || candidate.matchedClues.length >= 3))
    .sort((left, right) => right.score - left.score
      || right.coverage - left.coverage
      || right.distinctiveMatches - left.distinctiveMatches
      || offlineLookupEntityLabel(left).localeCompare(offlineLookupEntityLabel(right)));

  const top = candidates[0] || null;
  const runnerUp = candidates.find((candidate) => candidate.item !== top?.item || candidate.type !== top?.type) || null;
  const margin = top
    ? Math.max(0, Math.min(1, runnerUp ? (top.score - runnerUp.score) / Math.max(top.score, 1) : 1))
    : 0;
  candidates.forEach((candidate, rank) => {
    const noiseRatio = candidate.unmatchedClues.length / Math.max(1, queryTokens.length);
    const rankMargin = rank === 0 ? margin : Math.max(0, (candidate.score - (candidates[rank + 1]?.score || 0)) / Math.max(candidate.score, 1));
    const signatureConfidence = candidate.bestClueSet
      ? Math.min(0.18, 0.05 + candidate.bestClueSet.tokens.length * 0.025
        + (candidate.bestClueSet.path === "aliases" ? 0.055 : 0))
      : 0;
    const confidence = Math.max(0, Math.min(0.98,
      0.15 + candidate.coverage * 0.5 + Math.min(0.12, candidate.distinctiveMatches * 0.035)
      + Math.min(0.15, rankMargin * 0.22) + signatureConfidence
      - noiseRatio * 0.2 - candidate.fuzzyCount * 0.015));
    const coherentEvidence = candidate.score >= 12 && candidate.bestClueSet?.tokens?.length >= 2;
    const calibratedConfidence = coherentEvidence ? confidence : Math.min(confidence, 0.59);
    candidate.confidence = Number(calibratedConfidence.toFixed(3));
    candidate.confidenceTier = clinicalSearchConfidenceTier(calibratedConfidence);
    candidate.rank = rank + 1;
    candidate.clinicalClueMatch = true;
    candidate.matchKind = "clinical-clue";
    candidate.mayAutoOpen = rank === 0
      && confidence >= 0.78
      && margin >= 0.12
      && !personalClinicalNarrative
      && coherentEvidence
      && candidate.unmatchedClues.length <= Math.max(1, Math.floor(queryTokens.length / 4));
    candidate.identitySuggestionOnly = candidate.mayAutoOpen !== true;
  });
  // Confidence is meaningful only relative to the ranked result set. Keep a
  // lower-ranked choice from displaying a stronger confidence label than the
  // actual winner merely because its own next-runner gap is wider.
  const topConfidence = candidates[0]?.confidence || 0;
  candidates.slice(1).forEach((candidate, index) => {
    const rankCeiling = Math.max(0.05, topConfidence - Math.min(0.32, (index + 1) * 0.035));
    candidate.confidence = Number(Math.min(candidate.confidence, rankCeiling).toFixed(3));
    candidate.confidenceTier = clinicalSearchConfidenceTier(candidate.confidence);
  });
  const resultConfidenceTier = top
    ? (!top.mayAutoOpen && (margin < 0.12 || top.unmatchedClues.length > Math.max(1, Math.floor(queryTokens.length / 4)))
      ? "uncertain"
      : top.confidenceTier)
    : "low";
  if (top && resultConfidenceTier === "uncertain") {
    top.confidenceTier = "uncertain";
  }
  const result = {
    schemaVersion: "ani-clinical-search-intelligence-v1",
    status: top ? "MATCHED" : "NO_CONFIDENT_MATCH",
    queryTokens,
    candidates,
    preferred: top || null,
    confidence: top?.confidence || 0,
    confidenceTier: resultConfidenceTier,
    margin: Number(margin.toFixed(3)),
    mayAutoOpen: top?.mayAutoOpen === true,
    personalClinicalNarrative
  };
  clinicalSearchIntelligenceCache.set(cacheKey, result);
  while (clinicalSearchIntelligenceCache.size > 96) {
    clinicalSearchIntelligenceCache.delete(clinicalSearchIntelligenceCache.keys().next().value);
  }
  return { ...result, candidates: result.candidates.slice(0, limit) };
}

function runtimeTopicRequestCandidateIsBound(candidate = {}) {
  if (!candidate?.item || !candidate.type) return false;
  const pools = {
    drug: pharmDrugs,
    lab: pharmSearchableLabRanges,
    pathology: pathologyDiseases,
    reference: clinicalReferenceEntries,
    holistic: holisticRemedies
  };
  return Array.isArray(pools[candidate.type]) && pools[candidate.type].includes(candidate.item);
}

function registerReviewedTopicRequestResolver(registration = {}) {
  const id = safeText(registration.id).trim();
  const version = safeText(registration.version).trim();
  if (!/^[a-z0-9][a-z0-9._-]{2,80}$/i.test(id)
    || !version
    || typeof registration.resolve !== "function") {
    return false;
  }
  const existing = reviewedTopicRequestResolvers.get(id);
  if (existing) return existing.version === version;
  reviewedTopicRequestResolvers.set(id, Object.freeze({
    id,
    version,
    resolve: registration.resolve
  }));
  return true;
}

window.ANI_REGISTER_REVIEWED_TOPIC_REQUEST_RESOLVER = registerReviewedTopicRequestResolver;

function resolveReviewedTopicRequest(input = "", options = {}) {
  const limit = Math.max(1, Math.min(12, Number(options.limit || 8)));
  const personalClinicalNarrative = isPersonalClinicalNarrative(input);
  const byTarget = new Map();
  Array.from(reviewedTopicRequestResolvers.values())
    .sort((left, right) => left.id.localeCompare(right.id))
    .forEach((registration) => {
      let resolved = null;
      try {
        resolved = registration.resolve(safeText(input), {
          mode: options.mode === "navigate" ? "navigate" : "suggest",
          limit
        });
      } catch {
        return;
      }
      const rows = Array.isArray(resolved) ? resolved : resolved ? [resolved] : [];
      rows.forEach((row) => {
        const candidate = row?.candidate?.item ? row.candidate : row;
        if (!runtimeTopicRequestCandidateIsBound(candidate)) return;
        const key = offlineLookupEntityKey(candidate);
        if (!key) return;
        const mayAutoOpen = row.mayAutoOpen === true
          && row.activeCurrent !== true
          && !personalClinicalNarrative;
        const proposal = {
          type: candidate.type,
          item: candidate.item,
          score: Number(row.score || 0),
          reviewedRoute: true,
          reviewedRouteId: safeText(row.routeId || row.id),
          reviewedResolverIds: [registration.id],
          matchKind: "reviewed-route",
          mayAutoOpen,
          identitySuggestionOnly: !mayAutoOpen,
          activeCurrent: row.activeCurrent === true
        };
        const existing = byTarget.get(key);
        if (!existing) {
          byTarget.set(key, proposal);
          return;
        }
        existing.score = Math.max(existing.score, proposal.score);
        existing.mayAutoOpen = existing.mayAutoOpen && proposal.mayAutoOpen;
        existing.identitySuggestionOnly = !existing.mayAutoOpen;
        existing.activeCurrent = existing.activeCurrent || proposal.activeCurrent;
        existing.reviewedResolverIds = Array.from(new Set(
          existing.reviewedResolverIds.concat(proposal.reviewedResolverIds)
        )).sort();
      });
    });
  const candidates = Array.from(byTarget.values())
    .sort((left, right) => right.score - left.score
      || offlineLookupEntityLabel(left).localeCompare(offlineLookupEntityLabel(right)))
    .slice(0, limit);
  const ambiguous = candidates.length > 1;
  if (ambiguous) {
    candidates.forEach((candidate) => {
      candidate.mayAutoOpen = false;
      candidate.identitySuggestionOnly = true;
      candidate.ambiguousIdentity = true;
    });
  }
  return {
    schemaVersion: "ani-reviewed-topic-request-resolution-v1",
    status: ambiguous ? "AMBIGUOUS_REVIEWED_ROUTE" : candidates.length ? "MATCHED" : "NO_MATCH",
    candidates,
    preferred: ambiguous ? null : candidates[0] || null,
    mayAutoOpen: !ambiguous && candidates[0]?.mayAutoOpen === true,
    ambiguousIdentity: ambiguous,
    personalClinicalNarrative
  };
}

function resolveTopicRequest(input = "", options = {}) {
  const limit = Math.max(1, Math.min(12, Number(options.limit || 8)));
  const mode = options.mode === "navigate" ? "navigate" : "suggest";
  const identity = resolveEncyclopediaIdentity(input, { mode, limit });
  const identityOwnsRequest = identity.candidates.length > 0
    || identity.suppressUnrelatedMatches === true;
  const reviewed = identityOwnsRequest
    ? null
    : resolveReviewedTopicRequest(input, { mode, limit });
  const reviewedOwnsRequest = Boolean(reviewed?.candidates.length);
  const clinical = options.allowClinicalClues === false || identityOwnsRequest || reviewedOwnsRequest
    ? null
    : clinicalSearchIntelligence(input, { limit });
  const clinicalOwnsRequest = Boolean(clinical?.preferred);
  const preferred = identity.preferred || reviewed?.preferred || clinical?.preferred || null;
  return {
    schemaVersion: "ani-topic-request-resolution-v1",
    status: identityOwnsRequest
      ? (identity.suppressUnrelatedMatches === true ? "AMBIGUOUS_IDENTITY" : "IDENTITY_MATCHED")
      : reviewedOwnsRequest ? reviewed.status : clinical?.status || "NO_MATCH",
    resolutionKind: identityOwnsRequest
      ? (identity.suppressUnrelatedMatches === true ? "ambiguous-identity" : identity.matchKind || "identity")
      : reviewedOwnsRequest
        ? (reviewed.ambiguousIdentity ? "ambiguous-reviewed-route" : "reviewed-route")
        : clinicalOwnsRequest ? "clinical-clue" : "none",
    identity,
    reviewed,
    clinical,
    candidates: identityOwnsRequest
      ? identity.candidates
      : reviewedOwnsRequest ? reviewed.candidates : clinical?.candidates || [],
    preferred,
    mayAutoOpen: identityOwnsRequest
      ? identity.mayAutoOpen === true
      : reviewedOwnsRequest ? reviewed.mayAutoOpen === true : clinical?.mayAutoOpen === true,
    identitySuggestionOnly: identityOwnsRequest
      ? identity.mayAutoOpen !== true
      : reviewedOwnsRequest ? reviewed.mayAutoOpen !== true : clinicalOwnsRequest && clinical.mayAutoOpen !== true,
    ambiguousIdentity: identity.suppressUnrelatedMatches === true || reviewed?.ambiguousIdentity === true,
    personalClinicalNarrative: reviewed?.personalClinicalNarrative === true
      || clinical?.personalClinicalNarrative === true,
    confidence: Number(clinical?.confidence || 0),
    confidenceTier: clinical?.confidenceTier || "",
    margin: Number(clinical?.margin || 0)
  };
}

function descriptionSearchBlob(type = "", item = {}) {
  const record = descriptionCacheRecord(item);
  const key = `${type}Blob`;
  if (record[key]) return record[key];
  const blob = normalizePharmText(descriptionPiecesForCandidate(type, item).join(" "));
  record[key] = blob;
  return blob;
}

function descriptionSearchTokens(type = "", item = {}) {
  const record = descriptionCacheRecord(item);
  const key = `${type}Tokens`;
  if (record[key]) return record[key];
  const tokens = Array.from(new Set(descriptionSearchBlob(type, item)
    .split(" ")
    .map((token) => descriptionStemToken(token))
    .filter((token) => token.length >= 3 && !DESCRIPTION_LOOKUP_STOP_WORDS.has(token))))
    .slice(0, 520);
  record[key] = tokens;
  return tokens;
}

function descriptionCloseTokenScore(token = "", candidateTokens = []) {
  const clean = descriptionStemToken(token);
  if (clean.length < 5) return 0;
  const prefix = clean.slice(0, Math.min(5, clean.length - 1));
  let best = 0;
  for (const candidateToken of candidateTokens) {
    if (candidateToken === clean) return 14;
    if (prefix.length >= 4 && candidateToken.startsWith(prefix)) best = Math.max(best, 9);
    if (candidateToken.length < 5) continue;
    const distance = levenshteinDistance(clean, candidateToken);
    const maxLength = Math.max(clean.length, candidateToken.length);
    if (distance <= 1 && maxLength <= 7) best = Math.max(best, 8);
    else if (distance <= 2 && maxLength >= 7) best = Math.max(best, 7);
  }
  return best;
}

function scoreDescriptionMatch(type = "", item = {}, query = "") {
  const tokens = descriptionQueryTokens(query);
  if (tokens.length < 2) return 0;
  const blob = descriptionSearchBlob(type, item);
  if (!blob) return 0;
  const candidateTokens = descriptionSearchTokens(type, item);
  let score = 0;
  let hits = 0;
  let closeHits = 0;

  tokens.forEach((token) => {
    const variants = descriptionTokenVariants(token);
    const exactHit = variants.some((variant) => {
      if (!variant || variant.length < 3) return false;
      if (variant.includes(" ")) return blob.includes(variant);
      return candidateTokens.includes(variant) || blob.includes(variant);
    });
    if (exactHit) {
      hits += 1;
      score += token.length >= 7 ? 24 : 16;
      if (/^(hyper|hypo)/.test(token) || ["cortisol", "aldosterone", "potassium", "sodium", "calcium", "glucose", "platelet", "creatinine", "bilirubin", "lipase", "airway", "stridor", "occult"].includes(token)) {
        score += 10;
      }
      return;
    }

    const closeScore = descriptionCloseTokenScore(token, candidateTokens);
    if (closeScore) {
      closeHits += 1;
      score += closeScore;
    }
  });

  const phraseTokens = tokens.filter((token) => token.length >= 3);
  for (let size = 2; size <= Math.min(4, phraseTokens.length); size += 1) {
    for (let index = 0; index <= phraseTokens.length - size; index += 1) {
      const phrase = phraseTokens.slice(index, index + size).join(" ");
      if (phrase.length >= 7 && blob.includes(phrase)) {
        score += size >= 3 ? 34 : 22;
      }
    }
  }

  const coverage = (hits + closeHits) / tokens.length;
  if (hits >= 2 && coverage >= 0.45) score += Math.round(coverage * 60);
  if (hits >= 3) score += 28;
  if (closeHits && hits >= 1) score += 10;
  return score;
}

function looksLikeDescriptionLookupQuery(input = "") {
  const tokens = descriptionQueryTokens(input);
  if (tokens.length < 3) return false;
  return /\b(what|which|where|called|name|remember|recall|one|thing|condition|disease|drug|med|medication|lab|test|procedure|with|without|causes?|caused|trigger|high|low|elevated|decreased|deficiency|excess|toxicity|poison|rash|airway|fever|pain|bleeding|pregnan|pediatric|kid|child|geriatric|older)\b/i.test(input);
}

function looksLikeDrugDescriptionLookup(input = "") {
  return /\b(drug|drugs|med|meds|medication|medications|medicine|pharm|pharmacology|class|antidote|reversal|reverse|overdose|toxicity|toxic|poison|black box|boxed warning|contraindication|contraindications|side effect|side effects|adverse|interaction|interactions|treat|treats|treating|treatment|used for|used to|example|examples)\b/i.test(input);
}

function isDrugSectionLookupIntent(input = "") {
  return looksLikeDrugDescriptionLookup(input)
    || offlineSegmentIntents(input).some((intent) => [
      "mechanism",
      "warning",
      "contraindications",
      "interactions",
      "risks",
      "labs",
      "nursing",
      "uses",
      "class",
      "treatment"
    ].includes(intent));
}

function isPathologySectionLookupIntent(input = "") {
  return offlineSegmentIntents(input).some((intent) => [
    "mechanism",
    "signs",
    "diagnostics",
    "etiology",
    "pathophysiology",
    "treatment",
    "teaching",
    "nursing",
    "risks",
    "labs",
    "nclex"
  ].includes(intent));
}

function scoreOfflineDescriptionForCandidate(candidate = {}, query = "") {
  if (!candidate?.item) return 0;
  return scoreDescriptionMatch(candidate.type, candidate.item, query);
}

function levenshteinDistance(a = "", b = "") {
  const source = normalizePharmText(a);
  const target = normalizePharmText(b);
  if (!source) return target.length;
  if (!target) return source.length;
  const rows = Array.from({ length: source.length + 1 }, (_, index) => index);

  for (let targetIndex = 1; targetIndex <= target.length; targetIndex += 1) {
    let previous = rows[0];
    rows[0] = targetIndex;
    for (let sourceIndex = 1; sourceIndex <= source.length; sourceIndex += 1) {
      const temp = rows[sourceIndex];
      const cost = source[sourceIndex - 1] === target[targetIndex - 1] ? 0 : 1;
      rows[sourceIndex] = Math.min(
        rows[sourceIndex] + 1,
        rows[sourceIndex - 1] + 1,
        previous + cost
      );
      previous = temp;
    }
  }

  return rows[source.length];
}

function pharmTokenCloseness(token = "", term = "") {
  const cleanToken = normalizePharmText(token);
  const cleanTerm = normalizePharmText(term);
  if (!cleanToken || !cleanTerm) return 0;
  if (cleanTerm === cleanToken) return 12;
  if (cleanTerm.includes(cleanToken) || cleanToken.includes(cleanTerm)) return cleanToken.length >= 3 ? 8 : 0;

  const termTokens = cleanTerm.split(" ");
  return Math.max(...termTokens.map((termToken) => {
    if (termToken.length < 4 || cleanToken.length < 4) return 0;
    const distance = levenshteinDistance(cleanToken, termToken);
    const maxLength = Math.max(cleanToken.length, termToken.length);
    if (distance <= 1 && maxLength <= 7) return 7;
    if (distance <= 2 && maxLength >= 7) return 6;
    return 0;
  }), 0);
}

function pharmSubclassQualifierScore(cleanQuery = "", terms = []) {
  if (!cleanQuery || !Array.isArray(terms) || !terms.length) return 0;
  const blob = ` ${normalizePharmText(terms.join(" "))} `;
  const has = (pattern) => pattern.test(blob);
  let score = 0;

  if (/\b(non dihydropyridine|non dhp)\b/.test(cleanQuery)) {
    if (has(/\b(non dihydropyridine|non dhp|class iv|diltiazem|verapamil)\b/)) score += 90;
    if (has(/\bdihydropyridine\b/) && !has(/\bnon dihydropyridine\b/)) score -= 120;
  } else if (/\b(dihydropyridine|dhp)\b/.test(cleanQuery)) {
    if (has(/\bdihydropyridine\b/) && !has(/\bnon dihydropyridine\b/)) score += 70;
    if (has(/\bnon dihydropyridine\b/)) score -= 70;
  }

  if (/\bnonselective beta\b/.test(cleanQuery)) {
    if (has(/\bnonselective beta\b/)) score += 80;
    if (has(/\b(beta 1 selective|cardioselective)\b/)) score -= 80;
  } else if (/\b(beta 1 selective|cardioselective|beta 1 blocker|beta one blocker|beta 1 blockers|beta one blockers)\b/.test(cleanQuery)) {
    if (has(/\b(beta 1 selective|cardioselective|metoprolol|atenolol|bisoprolol|esmolol|nebivolol|betaxolol|acebutolol)\b/)) score += 260;
    if (has(/\bbeta blockers?\b/) && has(/\b(class card|drug subclass card|drug class card)\b/)) score += 100;
    if (has(/\bnonselective beta\b/)) score -= 45;
    if (has(/\b(glucagon|beta blocker overdose|overdose reversal|antidote)\b/)) score -= 320;
  }

  if (/\bnondepolarizing\b/.test(cleanQuery)) {
    if (has(/\bnondepolarizing\b/)) score += 90;
    if (has(/\bdepolarizing\b/) && !has(/\bnondepolarizing\b/)) score -= 120;
  } else if (/\bdepolarizing\b/.test(cleanQuery)) {
    if (has(/\bdepolarizing\b/) && !has(/\bnondepolarizing\b/)) score += 70;
    if (has(/\bnondepolarizing\b/)) score -= 70;
  }

  if (/\bshort acting\b/.test(cleanQuery)) {
    if (has(/\bshort acting\b/)) score += 65;
    if (has(/\blong acting\b/) && !has(/\bshort acting\b/)) score -= 45;
  } else if (/\blong acting\b/.test(cleanQuery)) {
    if (has(/\blong acting\b/)) score += 65;
    if (has(/\bshort acting\b/) && !has(/\blong acting\b/)) score -= 45;
  }

  if (/\b(high potency|low potency)\b/.test(cleanQuery)) {
    if (cleanQuery.includes("high potency") && has(/\bhigh potency\b/)) score += 60;
    if (cleanQuery.includes("high potency") && has(/\blow potency\b/)) score -= 75;
    if (cleanQuery.includes("low potency") && has(/\blow potency\b/)) score += 60;
    if (cleanQuery.includes("low potency") && has(/\bhigh potency\b/)) score -= 75;
  }

  if (/\b(cdk4|cdk 4|cdk4 6|cdk 4 6)\b/.test(cleanQuery)) {
    if (has(/\b(cdk4|cdk 4|cdk4 6|cdk 4 6|palbociclib|ribociclib|abemaciclib)\b/)) score += 120;
    if (has(/\b(ace inhibitor|dpp 4|factor xa)\b/) && !has(/\b(cdk4|cdk 4|cdk4 6|cdk 4 6)\b/)) score -= 90;
  }

  if (/\banaerobic\b/.test(cleanQuery)) {
    const hasAnaerobicAnchor = terms.some((term) => {
      const cleanTerm = normalizePharmText(term);
      return /\b(metronidazole|clindamycin|fidaxomicin|c difficile|c diff)\b/.test(cleanTerm)
        || /\b(anaerobic antibiotics?|anaerobic antimicrobial|anaerobic coverage|anaerobic infection|nitroimidazole anaerobic)\b/.test(cleanTerm);
    });
    if (hasAnaerobicAnchor) score += 130;
    if (/\banaerobic antibiotic/.test(cleanQuery) && hasAnaerobicAnchor) score += 210;
    if (has(/\bantibiotics?\b/) && !hasAnaerobicAnchor) score -= /\banaerobic antibiotics?\b/.test(cleanQuery) ? 420 : 180;
  }

  if (/\b(pd 1|pd l1|ctla 4|checkpoint)\b/.test(cleanQuery)) {
    if (has(/\b(pd 1|pd l1|ctla 4|checkpoint|pembrolizumab|nivolumab|ipilimumab|atezolizumab|durvalumab)\b/)) score += 100;
    if (has(/\bace inhibitor\b/)) score -= 70;
  }

  if (/\bpd 1\b/.test(cleanQuery) && !/\bpd l1\b/.test(cleanQuery)) {
    if (has(/\bpd 1\b/) && !has(/\bpd l1\b/)) score += 360;
    if (has(/\b(pd l1|ctla 4)\b/)) score -= 260;
  } else if (/\bpd l1\b/.test(cleanQuery)) {
    if (has(/\bpd l1\b/)) score += 360;
    if (has(/\bpd 1\b/) && !has(/\bpd l1\b/)) score -= 160;
    if (has(/\bctla 4\b/)) score -= 260;
  } else if (/\bctla 4\b/.test(cleanQuery)) {
    if (has(/\bctla 4\b/)) score += 360;
    if (has(/\bpd 1|pd l1\b/)) score -= 180;
  }

  if (/\b(tnf|her2|vegf|bcr abl|btk)\b/.test(cleanQuery)) {
    if (has(/\b(tnf|her2|vegf|bcr abl|btk|adalimumab|trastuzumab|bevacizumab|imatinib|ibrutinib)\b/)) score += 90;
  }

  return score;
}

function scorePharmEntry(drug = {}, query = "") {
  const cleanQuery = normalizePharmText(applyMedicationSpellingFixups(query));
  if (!cleanQuery) return 1;
  const terms = pharmEntryTerms(drug);
  const queryTokens = cleanQuery.split(" ").filter((token) => token.length > 1);
  const primaryNames = pharmIdentityTermsForEntry(drug);
  let score = 0;

  primaryNames.forEach((term) => {
    if (term === cleanQuery) {
      score += 260;
    } else if (term.startsWith(cleanQuery)) {
      score += 120;
    } else if (cleanQuery.length >= 4 && term.includes(cleanQuery)) {
      score += 54;
    }
  });
  queryTokens.forEach((token) => {
    if (token.length >= 3 && primaryNames.some((term) => term.split(" ").some((word) => word.startsWith(token)))) {
      score += 12;
    }
  });
  if (isLikelyCombinationDrugEntry(drug) && !primaryNames.includes(cleanQuery)) {
    score -= 80;
  }

  terms.forEach((term) => {
    if (term === cleanQuery) score += 80;
    else if (term.includes(cleanQuery)) score += 36;
    else if (cleanQuery.includes(term) && term.length >= 4) score += 24;
  });

  queryTokens.forEach((token) => {
    score += Math.max(...terms.map((term) => pharmTokenCloseness(token, term)), 0);
  });
  score += pharmSubclassQualifierScore(cleanQuery, terms);

  if (isNavigationOnlyGeneratedMedicationClass(drug)) {
    return score;
  }

  const searchableText = normalizePharmText([
    pharmUsedToTreat(drug),
    pharmBoxedWarningDisplay(drug),
    sanitizeMedicalReferenceText(drug.sourceNote),
    drug.mechanism,
    ...(drug.nursingEssentials || []),
    ...(drug.contraindications || []),
    ...(drug.interactions || []),
    ...(drug.keyLabs || []),
    ...(drug.nclexTraps || []),
    ...((drug.populationRisks || []).flatMap((risk) => [risk.type, risk.label, risk.note]))
  ].join(" "));

  queryTokens.forEach((token) => {
    if (token.length >= 4 && searchableText.includes(token)) {
      score += 3;
    }
  });

  if (looksLikeDrugDescriptionLookup(query)) {
    score += scoreDescriptionMatch("drug", drug, query);
  }

  return score;
}

function pharmLabTerms(lab = {}) {
  const cached = pharmLabTermCache.get(lab);
  if (cached) {
    return cached;
  }
  const identityPieces = [
    lab.name,
    lab.category,
    lab.populationGroup,
    lab.sourceType,
    ...labPopulationIndexTerms(lab)
  ];
  const pieces = [
    ...identityPieces,
    lab.range,
    lab.why,
    lab.groupNote
  ];
  const terms = [
    ...pieces,
    ...medicalAbbreviationSearchTermsForText(identityPieces)
  ]
    .map((term) => normalizePharmText(term))
    .filter(Boolean);
  pharmLabTermCache.set(lab, terms);
  return terms;
}

function pharmLabContentIndexValues(lab = {}) {
  const projectedTeaching = labProjectedTeachingSections(lab)
    .flatMap((section) => (Array.isArray(section.items) && section.items.length
      ? section.items.map((item) => item.text)
      : [section.value]))
    .map((value) => normalizePharmText(value))
    .filter(Boolean);
  return Array.from(new Set([
    ...pharmLabTerms(lab),
    ...projectedTeaching
  ]));
}

function pharmTermContainsQuery(term = "", cleanQuery = "") {
  if (!term || !cleanQuery) return false;
  if (cleanQuery.length < 4) {
    return term.split(" ").some((word) => word.startsWith(cleanQuery));
  }
  return term.includes(cleanQuery);
}

function pharmLabTokenCloseness(token = "", term = "") {
  const cleanToken = normalizePharmText(token);
  const cleanTerm = normalizePharmText(term);
  if (!cleanToken || !cleanTerm) return 0;
  if (cleanTerm === cleanToken) return 12;
  const termTokens = cleanTerm.split(" ");
  if (cleanToken.length < 4) {
    return termTokens.some((termToken) => termToken.startsWith(cleanToken)) ? 8 : 0;
  }
  if (cleanTerm.includes(cleanToken) || (cleanTerm.length >= 4 && cleanToken.includes(cleanTerm))) return 8;

  return Math.max(...termTokens.map((termToken) => {
    if (termToken.length < 4 || cleanToken.length < 4) return 0;
    const distance = levenshteinDistance(cleanToken, termToken);
    const maxLength = Math.max(cleanToken.length, termToken.length);
    if (distance <= 1 && maxLength <= 7) return 7;
    if (distance <= 2 && maxLength >= 7) return 6;
    return 0;
  }), 0);
}

function scorePharmLabEntry(lab = {}, query = "") {
  const cleanQuery = normalizePharmText(query);
  if (!cleanQuery) return 0;
  const terms = pharmLabTerms(lab);
  const queryTokens = cleanQuery.split(" ").filter((token) => token.length > 1);
  const labName = normalizePharmText(lab.name);
  const abbreviationTerms = medicalAbbreviationSearchTermsForText(cleanQuery);
  const abbreviationEntries = medicalAbbreviationEntriesForText(cleanQuery, 20);
  let score = 0;

  if (labName === cleanQuery) {
    score += 520;
  } else if (pharmTermContainsQuery(labName, cleanQuery) || (labName.length >= 4 && cleanQuery.includes(labName))) {
    score += 180;
  }
  queryTokens.forEach((token) => {
    if (pharmTermContainsQuery(labName, token)) {
      score += 18;
    }
  });

  terms.forEach((term) => {
    if (term === cleanQuery) score += 90;
    else if (pharmTermContainsQuery(term, cleanQuery)) score += 42;
    else if (cleanQuery.includes(term) && term.length >= 4) score += 28;
  });

  if (abbreviationTerms.some((term) => terms.includes(term))) {
    score += 220;
  }
  if (abbreviationEntries.some((entry) => {
    const names = [entry.short, ...(entry.aliases || [])].map((term) => normalizePharmText(term));
    return names.includes(labName);
  })) {
    score += 420;
  }
  if (queryTokens.some((token) => token.length <= 5 && terms.includes(token))) {
    score += 120;
  }

  queryTokens.forEach((token) => {
    const tokenScore = Math.max(...terms.map((term) => pharmLabTokenCloseness(token, term)), 0);
    score += tokenScore;
    if (terms.some((term) => pharmTermContainsQuery(term, token))) {
      score += 4;
    }
  });

  score += scoreLabPopulationFit(lab, query);
  score += scoreDescriptionMatch("lab", lab, query);

  return score;
}

function searchPharmLabEntries(query = "", letter = activePharmLetter) {
  if (wantsMedicationClassLookup(query)) return [];
  const fixedQuery = applyClinicalSpeechFixups(query) || query;
  const searchQuery = normalizeOfflineLookupText(fixedQuery) || fixedQuery;
  const cleanQuery = normalizePharmText(searchQuery);
  const byLetter = letter && letter !== "All"
    ? pharmSearchableLabRanges.filter((lab) => safeText(lab.name).toUpperCase().startsWith(letter))
    : pharmSearchableLabRanges;
  if (!cleanQuery) return byLetter;
  const candidates = indexedEncyclopediaSearchPool("lab", byLetter, fixedQuery);

  return candidates
    .map((lab) => ({
      lab,
      // Preserve age/population words for population-specific ranges. The
      // normalized lookup text intentionally drops wrapper words, but scoring
      // must still see context such as "6 year old", pregnancy, or geriatric.
      score: scorePharmLabEntry(lab, fixedQuery)
    }))
    .filter((entry) => entry.score >= 6)
    .sort((a, b) => b.score - a.score || safeText(a.lab.name).localeCompare(safeText(b.lab.name)))
    .map((entry) => entry.lab);
}

function pathologyListText(items = []) {
  return Array.isArray(items) ? readableListText(items) : softenSemicolonProse(safeText(items));
}

