function normalizedTextIncludesPhrase(haystackNorm = "", phrase = "") {
  const term = normalizePharmText(phrase);
  if (!term || (term.length < 4 && !["asa", "nac", "tpa"].includes(term))) return false;
  return ` ${haystackNorm} `.includes(` ${term} `);
}

function pathologyTreatmentIdentityText(disease = {}) {
  return safeText([
    disease.name,
    disease.category,
    ...(Array.isArray(disease.aliases) ? disease.aliases : []),
    disease.definition
  ].join(" "));
}

const PATHOLOGY_TREATMENT_NEGATION_PATTERN = /\b(?:avoid|avoided|do not|don't|never|not indicated|not recommended|not routinely|not use|should not|must not|contraindicat(?:e|ed|ion|ions)|withhold|hold|stop|discontinue|caution|unsafe|worsen|increases? (?:the )?risk|bleeding risk|allergy|hypersensitiv|screen for|history of)\b/i;

function pathologyTreatmentPositiveSegments(disease = {}) {
  const values = Array.isArray(disease.treatments)
    ? disease.treatments
    : [disease.treatments];
  return values
    .flatMap((value) => safeText(value)
      .split(/(?:\s*[|;]\s*|(?<=[.!?])\s+|\s+\b(?:but|however|whereas)\b\s*)/i))
    .map((value) => safeText(value))
    .filter(Boolean)
    .filter((value) => !PATHOLOGY_TREATMENT_NEGATION_PATTERN.test(value));
}

function pathologyTreatmentSourceText(disease = {}) {
  // Treatment links must come from affirmative treatment content only. Nursing
  // precautions deliberately mention medicines to avoid, hold, or monitor; using
  // those warnings as a treatment source previously inverted their meaning.
  return safeText(pathologyTreatmentPositiveSegments(disease).join(" "));
}

function pathologyExplicitMedicationNames(disease = {}) {
  if (safeText(disease.medicationTreatmentSafetyPolicy) !== "curated-explicit-v2") return [];
  const names = Array.isArray(disease.directTreatmentMedications)
    ? disease.directTreatmentMedications
    : [];
  return names.map((name) => safeText(name)).filter(Boolean);
}

function pathologyMedicationEntryTerms(drug = {}) {
  return pharmIdentityTermsForEntry(drug)
    .map((term) => safeText(term))
    .filter(Boolean);
}

function pathologyTreatmentMedicationSearchBlob(drug = {}) {
  const identityTerms = pharmIdentityTermsForEntry(drug);
  return normalizePharmText([
    ...identityTerms,
    pharmDisplayClass(drug),
    pharmUsedToTreat(drug),
    ...sanitizeMedicationTermListForSingleDrug(drug, drug.tags || [])
  ].join(" "));
}

function pathologyTreatmentDrugBaseScore(drug = {}) {
  let score = 0;
  if (isNclexCorePharmEntry(drug)) score += 60;
  if (!drug.expandedIndex) score += 30;
  const rank = Number(drug.nclexEssentialRank || 0);
  if (rank > 0) score += Math.max(5, 45 - rank);
  if (safeText(drug.mechanism)) score += 4;
  if (safeText(pharmUsedToTreat(drug))) score += 4;
  return score;
}

function pathologyTreatmentMedicationDrugPool() {
  if (pathologyTreatmentMedicationDrugPoolCache) {
    return pathologyTreatmentMedicationDrugPoolCache;
  }
  pathologyTreatmentMedicationDrugPoolCache = pharmDrugs
    .filter((drug) => drug && typeof drug === "object")
    .filter(isVisibleMedicationEntry)
    .filter((drug) => !isLikelyCombinationDrugEntry(drug))
    .filter((drug) => !drug.expandedIndex || drug.nclexEssentialRank || drug.nclexEssential || hasNclexEssentialPharmOverride(drug) || isNclexCorePharmEntry(drug))
    .map((drug) => ({
      drug,
      key: pharmEntryNameKey(drug) || normalizePharmText(drug.name),
      terms: pathologyMedicationEntryTerms(drug),
      blob: pathologyTreatmentMedicationSearchBlob(drug),
      baseScore: pathologyTreatmentDrugBaseScore(drug)
    }))
    .filter((entry) => entry.key && entry.terms.length);
  return pathologyTreatmentMedicationDrugPoolCache;
}

function pathologyCuratedTreatmentMedicationDrugPool() {
  if (pathologyCuratedTreatmentMedicationDrugPoolCache) {
    return pathologyCuratedTreatmentMedicationDrugPoolCache;
  }
  // Curated-explicit-v2 names have already been reviewed as exact condition-
  // medication pairs. Their resolver may therefore use every visible exact
  // medication identity, including factor concentrates that the conservative
  // combination-product heuristic can misclassify because several product
  // brands appear on one educational card. No class or fuzzy inference occurs.
  pathologyCuratedTreatmentMedicationDrugPoolCache = pharmDrugs
    .filter((drug) => drug && typeof drug === "object")
    .filter(isVisibleMedicationEntry)
    .map((drug) => ({
      drug,
      key: pharmEntryNameKey(drug) || normalizePharmText(drug.name),
      terms: pathologyMedicationEntryTerms(drug),
      blob: pathologyTreatmentMedicationSearchBlob(drug),
      baseScore: pathologyTreatmentDrugBaseScore(drug)
    }))
    .filter((entry) => entry.key && entry.terms.length);
  return pathologyCuratedTreatmentMedicationDrugPoolCache;
}

function pathologyTreatmentEntryMatchesDrugName(entry = {}, drugName = "") {
  const target = normalizePharmText(drugName);
  if (!target) return false;
  if (entry.key === target) return true;
  return entry.terms.some((term) => normalizePharmText(term) === target);
}

function addPathologyDiseaseRuleMatches(rule = {}, pool = [], seen = new Set(), addMatch = () => {}) {
  const orderedNames = Array.isArray(rule.drugNames) ? rule.drugNames.map((name) => normalizePharmText(name)).filter(Boolean) : [];
  if (!orderedNames.length) {
    pool
      .filter((entry) => !seen.has(entry.key) && rule.drugPattern.test(entry.blob))
      .sort((a, b) => b.baseScore - a.baseScore || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
      .slice(0, rule.limit || 6)
      .forEach((entry) => {
        addMatch(entry, `${rule.label}: commonly used or considered when ordered and clinically appropriate.`, 90);
      });
    return;
  }

  const addedForRule = [];
  orderedNames.forEach((drugName) => {
    if (addedForRule.length >= (rule.limit || orderedNames.length)) return;
    const entry = pool.find((candidate) => !seen.has(candidate.key) && pathologyTreatmentEntryMatchesDrugName(candidate, drugName));
    if (!entry) return;
    addedForRule.push(entry);
    addMatch(entry, `${rule.label}: commonly used or considered when ordered and clinically appropriate.`, 110);
  });
}

function relatedPathologyTreatmentMedications(disease = {}) {
  if (!disease || typeof disease !== "object") return [];
  if (pathologyTreatmentMedicationCache.has(disease)) {
    return pathologyTreatmentMedicationCache.get(disease);
  }
  const treatmentText = pathologyTreatmentSourceText(disease);
  const treatmentNorm = normalizePharmText(treatmentText);
  const identityText = pathologyTreatmentIdentityText(disease);
  const explicitMedicationNames = pathologyExplicitMedicationNames(disease);
  if (!treatmentNorm && !identityText && !explicitMedicationNames.length) {
    pathologyTreatmentMedicationCache.set(disease, []);
    return [];
  }

  const matches = [];
  const seen = new Set();
  const addMatch = (entry, reason = "", scoreBoost = 0) => {
    if (!entry?.drug || seen.has(entry.key)) return;
    seen.add(entry.key);
    matches.push({
      drug: entry.drug,
      reason,
      score: entry.baseScore + scoreBoost
    });
  };

  if (explicitMedicationNames.length) {
    const curatedPool = pathologyCuratedTreatmentMedicationDrugPool();
    explicitMedicationNames.forEach((drugName) => {
      const target = normalizePharmText(drugName);
      const entry = curatedPool.find((candidate) => !seen.has(candidate.key) && candidate.key === target)
        || curatedPool.find((candidate) => !seen.has(candidate.key) && pathologyTreatmentEntryMatchesDrugName(candidate, drugName));
      if (!entry) return;
      addMatch(entry, "Explicitly named in this pathology card's treatment plan.", 200);
    });
    const explicitResult = matches
      .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
      .slice(0, 18);
    pathologyTreatmentMedicationCache.set(disease, explicitResult);
    return explicitResult;
  }

  const pool = pathologyTreatmentMedicationDrugPool();

  if (disease.allowExactTreatmentMedicationLinks !== true
      && disease.allowInferredTreatmentMedicationLinks !== true) {
    // Legacy `medicationsCommonlyUsed` arrays mixed direct disease therapy with
    // prevention, postoperative care, symptom relief, and complication-only
    // drugs. They remain available for source audit but cannot produce buttons
    // until the disease-drug pairs are re-reviewed under curated-explicit-v2.
    pathologyTreatmentMedicationCache.set(disease, []);
    return [];
  }

  pool.forEach((entry) => {
    const exactTerm = entry.terms.find((term) => normalizedTextIncludesPhrase(treatmentNorm, term));
    if (exactTerm) {
      addMatch(entry, "Listed directly in this pathology's treatment or nursing action plan.", 120);
    }
  });

  // Broad disease/class inference is opt-in. A label such as "cardiomyopathy"
  // or "bleeding disorder" is too broad to safely generate patient-facing drug
  // recommendations. Curated cards can opt in deliberately after a pairwise
  // review; otherwise ANI links only exact medicines named affirmatively above.
  if (disease.allowInferredTreatmentMedicationLinks === true) {
    PATHOLOGY_TREATMENT_DISEASE_RULES.forEach((rule) => {
      if (!rule.diseasePattern.test(identityText)) return;
      addPathologyDiseaseRuleMatches(rule, pool, seen, addMatch);
    });

    PATHOLOGY_TREATMENT_CLASS_RULES.forEach((rule) => {
      if (!rule.pattern.test(treatmentText)) return;
      pool
        .filter((entry) => !seen.has(entry.key) && rule.drugPattern.test(entry.blob))
        .sort((a, b) => b.baseScore - a.baseScore || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
        .slice(0, rule.limit || 5)
        .forEach((entry) => {
          const note = rule.note
            ? `${rule.label}: ${rule.note}`
            : `Matches treatment class named in this pathology: ${rule.label}.`;
          addMatch(entry, note, 70);
        });
    });
  }

  const result = matches
    .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
    .slice(0, 18);
  pathologyTreatmentMedicationCache.set(disease, result);
  return result;
}

function appendPathologyTreatmentMedicationSection(disease = {}) {
  const medications = relatedPathologyTreatmentMedications(disease);

  // A missing reviewed disease-medication relationship is validation evidence,
  // not learner-facing medical content. Keep the treatment section authored by
  // the card and omit this generated navigation block until exact links exist.
  if (!medications.length) return false;

  const section = document.createElement("section");
  section.className = "pathology-treatment-med-section";
  const heading = document.createElement("strong");
  heading.textContent = "Safety-reviewed treatment medication references";

  const grid = document.createElement("div");
  grid.className = "pathology-treatment-med-grid";

  medications.forEach(({ drug, reason }) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pathology-treatment-med-button";
    const name = document.createElement("strong");
    name.textContent = pharmDrugDisplayName(drug);
    const drugClass = document.createElement("span");
    drugClass.textContent = pharmDrugMetaText(drug);
    const note = document.createElement("small");
    note.textContent = safeText(reason);
    button.append(name, drugClass, note);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPharmDetailCandidate({ type: "drug", item: drug });
    });
    grid.append(button);
  });

  const safety = document.createElement("p");
  safety.className = "pathology-treatment-med-note";
  safety.textContent = "These links passed ANI's direct-treatment relationship review. They remain educational references, not patient-specific prescribing advice; actual selection still depends on subtype, severity, contraindications, organ function, pregnancy status, interactions, and the treating team's plan.";
  section.append(heading, grid, safety);
  pharmDrugDetail.append(section);
  return true;
}

