function makeOfflineLabRangeAnswer(input = "") {
  // Keep the reviewed lab-spelling corrections consistent with search scoring.
  // This remains a range/population intent path; it does not promote fuzzy
  // suggestions or relax the fail-closed identity routing rules.
  const fixedInput = applyClinicalSpeechFixups(input) || input;
  const populationIntent = detectLabPopulationIntent(fixedInput);
  if (!wantsLabRangeLookup(fixedInput) || (!hasExplicitLabRangeCue(fixedInput) && !populationIntent.size)) return "";
  const lab = bestLabMatch(fixedInput);
  if (!lab) return "";
  const ageIntent = detectPediatricAgeIntent(fixedInput);
  const pediatricSegment = ageIntent ? bestPediatricRangeSegmentForAge(lab.range, ageIntent) : "";
  const populationLine = ageIntent
    ? `**Requested population:** ${ageIntent.label}.`
    : populationIntent.size
      ? `**Requested population:** ${Array.from(populationIntent).join(", ")}.`
      : "";
  currentTopic = lab.name;
  updateFocus();
  return [
    `**${lab.name} - reference range / value**`,
    populationLine,
    pediatricSegment ? `**Best age-matched anchor:** ${pediatricSegment}.` : "",
    `**Stored range:** ${lab.range}`,
    lab.why ? `**Why it matters:** ${lab.why}` : "",
    lab.groupNote ? `**Population note:** ${lab.groupNote}` : "",
    "**Nursing interpretation:** compare to the printed facility range, the client's trend, symptoms, hydration/perfusion status, bleeding/infection clues, and medication context. Do not force adult values onto pediatric or pregnancy questions."
  ].filter(Boolean).join("\n\n");
}

function inputHasAnyPhrase(input = "", phrases = []) {
  const lower = normalizeIntentText(input);
  return phrases.some((phrase) => new RegExp(`\\b${escapeRegex(normalizeIntentText(phrase)).replace(/\\s+/g, "\\s+")}\\b`, "i").test(lower));
}

