function offlineAbgNumbers(input = "") {
  const lower = normalizeIntentText(String(input || "")
    .replace(/\u2082/g, "2")
    .replace(/\u2083/g, "3"));
  const numberAfter = (pattern) => {
    const match = lower.match(pattern);
    return match ? Number(match[1]) : NaN;
  };
  const valid = (value, minimum, maximum) => Number.isFinite(value) && value >= minimum && value <= maximum
    ? value
    : NaN;
  const explicitVbg = /\b(vbg|venous blood gas|venous gas)\b/i.test(lower)
    || /\b(pvco2|pv\s*co2)\b/i.test(lower);
  const explicitAbg = !explicitVbg && (/\b(abg|arterial blood gas|arterial gas)\b/i.test(lower)
    || /\b(paco2|pa\s*co2)\b/i.test(lower));
  const explicitGasCue = explicitVbg || explicitAbg || /\bblood gas\b/i.test(lower);
  const labelledPco2 = numberAfter(/\b(?:paco2|pa\s*co2|pvco2|pv\s*co2|pco2|p\s*co2)\s*(?:is|=|of|:)?\s*([0-9]+(?:\.[0-9]+)?)/i);
  const labelledHco3 = numberAfter(/\b(?:hco\s*3|bicarb|bicarbonate)\s*-?\s*(?:is|=|of|:)?\s*([0-9]+(?:\.[0-9]+)?)/i);
  const labelledPo2 = numberAfter(/\b(?:pao2|pa\s*o2|pvo2|pv\s*o2|po2|p\s*o2)\s*(?:is|=|of|:)?\s*([0-9]+(?:\.[0-9]+)?)/i);
  let ph = numberAfter(/\bph\s*(?:is|=|of|:)?\s*([0-9]+(?:\.[0-9]+)?)/i);
  let paco2 = labelledPco2;
  let hco3 = labelledHco3;
  let po2 = labelledPo2;
  let slashFormat = false;

  /* Common bedside shorthand is pH/PCO2/HCO3. When four values are supplied,
     ANI treats them as pH/PCO2/PO2/HCO3. A gas cue is required so dates, ratios,
     and other slash-delimited numbers cannot become blood gases accidentally. */
  if (explicitGasCue) {
    const slash = lower.match(/\b(?:abg|vbg|arterial blood gas|venous blood gas|blood gas)\b[^0-9]{0,24}([0-9](?:\.[0-9]{1,3})?)\s*\/\s*([0-9]{1,3}(?:\.[0-9]+)?)\s*\/\s*([0-9]{1,3}(?:\.[0-9]+)?)(?:\s*\/\s*([0-9]{1,3}(?:\.[0-9]+)?))?/i);
    if (slash) {
      slashFormat = true;
      if (!Number.isFinite(ph)) ph = Number(slash[1]);
      if (!Number.isFinite(paco2)) paco2 = Number(slash[2]);
      if (slash[4] !== undefined) {
        if (!Number.isFinite(po2)) po2 = Number(slash[3]);
        if (!Number.isFinite(hco3)) hco3 = Number(slash[4]);
      } else if (!Number.isFinite(hco3)) {
        hco3 = Number(slash[3]);
      }
    }
  }

  /* Bare "CO2" is ambiguous with chemistry total CO2 and environmental CO2.
     Accept it as PCO2 only when the user explicitly identified a blood gas. */
  if (!Number.isFinite(paco2) && explicitGasCue) {
    paco2 = numberAfter(/\bco2\s*(?:is|=|of|:)?\s*([0-9]+(?:\.[0-9]+)?)/i);
  }

  const specimen = explicitVbg ? "VBG" : explicitAbg ? "ABG" : "blood gas";
  return {
    ph: valid(ph, 6, 8),
    paco2: valid(paco2, 5, 250),
    hco3: valid(hco3, 1, 100),
    po2: valid(po2, 5, 800),
    specimen,
    co2Label: specimen === "VBG" ? "PvCO2" : specimen === "ABG" ? "PaCO2" : "PCO2",
    slashFormat
  };
}

function wantsOfflineAbgInterpretationAnswer(input = "") {
  const lower = normalizeIntentText(input);
  const values = offlineAbgNumbers(input);
  return (values.slashFormat || /\b(abg|vbg|arterial blood gas|venous blood gas|blood gas|ph|paco2|pa\s*co2|pvco2|pv\s*co2|pco2|hco3|hco\s*3|bicarb|bicarbonate)\b/i.test(lower))
    && Number.isFinite(values.ph)
    && (Number.isFinite(values.paco2) || Number.isFinite(values.hco3));
}

function makeOfflineAbgInterpretationAnswer(input = "") {
  if (!wantsOfflineAbgInterpretationAnswer(input)) return "";
  const values = offlineAbgNumbers(input);
  const { ph, paco2, hco3, po2, specimen, co2Label } = values;
  const hasPco2 = Number.isFinite(paco2);
  const hasHco3 = Number.isFinite(hco3);
  const acidemia = ph < 7.35;
  const alkalemia = ph > 7.45;
  const pHState = acidemia ? "acidemia" : alkalemia ? "alkalemia" : "a near-normal pH";
  const numberText = (value) => Number.isInteger(value)
    ? String(value)
    : String(Math.round(value * 100) / 100);
  const rangeText = (low, high) => `${numberText(low)}-${numberText(high)}`;
  const result = {
    label: "indeterminate acid-base pattern",
    why: "The pH state and the available component do not yet establish one complete primary process.",
    compensation: "A quantitative compensation check needs pH, PCO2, and HCO3 from the same time point."
  };

  const metabolicAcidosisResult = () => {
    if (!hasPco2) {
      return {
        label: "metabolic acidosis",
        why: "HCO3 is low, so bicarbonate loss or acid gain is pushing the bicarbonate-to-CO2 ratio downward.",
        compensation: "PCO2 was not provided, so respiratory compensation and a second respiratory process cannot be tested."
      };
    }
    const expected = (1.5 * hco3) + 8;
    const low = expected - 2;
    const high = expected + 2;
    if (paco2 > high) {
      return {
        label: "mixed metabolic and respiratory acidosis",
        why: `${co2Label} is ${numberText(paco2)}, above the Winter screening range ${rangeText(low, high)}. Ventilation is not lowering CO2 enough for this bicarbonate, so added CO2 retention is worsening the acidosis.`,
        compensation: `Winter formula: expected PaCO2 = 1.5 x HCO3 + 8 +/-2, here about ${rangeText(low, high)} mm Hg. The measured value is above that estimate.`
      };
    }
    if (paco2 < low) {
      return {
        label: "mixed metabolic acidosis and respiratory alkalosis",
        why: `${co2Label} is ${numberText(paco2)}, below the Winter screening range ${rangeText(low, high)}. CO2 is being removed beyond expected compensation, so a primary respiratory alkalosis is also present.`,
        compensation: `Winter formula: expected PaCO2 = 1.5 x HCO3 + 8 +/-2, here about ${rangeText(low, high)} mm Hg. The measured value is below that estimate.`
      };
    }
    return {
      label: "metabolic acidosis with expected respiratory compensation",
      why: `Low HCO3 is the primary acidifying process, and ${co2Label} falls within the Winter screening range, so the low CO2 is an appropriate ventilatory response rather than a separate respiratory diagnosis.`,
      compensation: `Winter formula: expected PaCO2 = 1.5 x HCO3 + 8 +/-2, here about ${rangeText(low, high)} mm Hg; measured ${co2Label} is ${numberText(paco2)}.`
    };
  };

  const metabolicAlkalosisResult = () => {
    if (!hasPco2) {
      return {
        label: "metabolic alkalosis",
        why: "HCO3 is high, so bicarbonate gain or hydrogen loss is pushing the bicarbonate-to-CO2 ratio upward.",
        compensation: "PCO2 was not provided, so respiratory compensation and a second respiratory process cannot be tested."
      };
    }
    const expected = 40 + (0.7 * (hco3 - 24));
    const low = expected - 5;
    const high = expected + 5;
    if (paco2 > high) {
      return {
        label: "mixed metabolic alkalosis and respiratory acidosis",
        why: `${co2Label} is ${numberText(paco2)}, above the metabolic-alkalosis screening range ${rangeText(low, high)}. CO2 retention is greater than expected compensation, so respiratory acidosis is also present.`,
        compensation: `Screening estimate: expected PaCO2 is about 40 + 0.7 x (HCO3 - 24), here approximately ${numberText(expected)} mm Hg with a rough ${rangeText(low, high)} range. The measured value is above it.`
      };
    }
    if (paco2 < low) {
      return {
        label: "mixed metabolic and respiratory alkalosis",
        why: `${co2Label} is ${numberText(paco2)}, below the metabolic-alkalosis screening range ${rangeText(low, high)}. Excess CO2 removal adds a primary respiratory alkalosis.`,
        compensation: `Screening estimate: expected PaCO2 is about 40 + 0.7 x (HCO3 - 24), here approximately ${numberText(expected)} mm Hg with a rough ${rangeText(low, high)} range. The measured value is below it.`
      };
    }
    return {
      label: "metabolic alkalosis with expected respiratory compensation",
      why: `High HCO3 is the primary alkalinizing process, and ${co2Label} is within the expected hypoventilatory response.`,
      compensation: `Screening estimate: expected PaCO2 is about 40 + 0.7 x (HCO3 - 24), here approximately ${numberText(expected)} mm Hg with a rough ${rangeText(low, high)} range; measured ${co2Label} is ${numberText(paco2)}.`
    };
  };

  const respiratoryAcidosisResult = () => {
    if (!hasHco3) {
      return {
        label: "respiratory acidosis",
        why: `${co2Label} is high, so CO2 retention is pushing pH downward.`,
        compensation: "HCO3 was not provided, so acute versus chronic renal response and an added metabolic process cannot be tested."
      };
    }
    const delta = Math.max(0, (paco2 - 40) / 10);
    const acuteExpected = 24 + delta;
    const acuteLow = acuteExpected - 2;
    const acuteHigh = acuteExpected + 2;
    const chronicLow = 24 + (3.5 * delta);
    const chronicHigh = 24 + (4 * delta);
    const acuteMatch = hco3 >= acuteLow && hco3 <= acuteHigh;
    const chronicMatch = hco3 >= chronicLow - 1 && hco3 <= chronicHigh + 1;
    const screen = `Acute screen: HCO3 rises about 1 mEq/L per 10-mm Hg PaCO2 rise (about ${numberText(acuteExpected)} here). Chronic screen: HCO3 rises about 3.5-4 per 10 (about ${rangeText(chronicLow, chronicHigh)} here).`;
    if (hco3 < acuteLow) {
      return {
        label: "mixed respiratory and metabolic acidosis",
        why: `${co2Label} is high from CO2 retention, while HCO3 ${numberText(hco3)} is below even the approximate acute response. Low bicarbonate is therefore an additional primary metabolic acidosis, not compensation.`,
        compensation: screen
      };
    }
    if (hco3 > chronicHigh + 1) {
      return {
        label: "mixed respiratory acidosis and metabolic alkalosis",
        why: `${co2Label} is high from CO2 retention, but HCO3 ${numberText(hco3)} exceeds the approximate chronic renal response. A separate bicarbonate-raising process is also present.`,
        compensation: screen
      };
    }
    if (acuteMatch && chronicMatch) {
      const predictedAcuteP = 7.4 - (0.08 * delta);
      const predictedChronicP = 7.4 - (0.03 * delta);
      const chronicCloser = Math.abs(ph - predictedChronicP) < Math.abs(ph - predictedAcuteP);
      return {
        label: `${chronicCloser ? "chronic" : "acute"} respiratory acidosis with an expected renal response`,
        why: `${co2Label} is high from CO2 retention, and HCO3 fits both overlapping screening ranges; the pH is closer to the ${chronicCloser ? "chronic" : "acute"} teaching pattern. Clinical duration and prior gases still decide timing.`,
        compensation: screen
      };
    }
    if (acuteMatch) {
      return {
        label: "acute respiratory acidosis with an expected early renal response",
        why: `${co2Label} is high from CO2 retention, and HCO3 is near the acute estimate rather than the larger chronic adaptation.`,
        compensation: screen
      };
    }
    if (chronicMatch) {
      return {
        label: "chronic respiratory acidosis with an expected renal response",
        why: `${co2Label} is high from CO2 retention, and the larger HCO3 rise fits time-dependent kidney adaptation.`,
        compensation: screen
      };
    }
    return {
      label: "respiratory acidosis with an intermediate or evolving renal response",
      why: `${co2Label} is high from CO2 retention, while HCO3 falls between the usual acute and chronic estimates. Acute-on-chronic disease, evolving adaptation, treatment timing, or another metabolic process must be resolved clinically.`,
      compensation: screen
    };
  };

  const respiratoryAlkalosisResult = () => {
    if (!hasHco3) {
      return {
        label: "respiratory alkalosis",
        why: `${co2Label} is low, so excess ventilation and CO2 removal are pushing pH upward.`,
        compensation: "HCO3 was not provided, so acute versus chronic renal response and an added metabolic process cannot be tested."
      };
    }
    const delta = Math.max(0, (40 - paco2) / 10);
    const acuteExpected = 24 - (2 * delta);
    const acuteLow = acuteExpected - 2;
    const acuteHigh = acuteExpected + 2;
    const chronicLow = 24 - (5 * delta);
    const chronicHigh = 24 - (4 * delta);
    const acuteMatch = hco3 >= acuteLow && hco3 <= acuteHigh;
    const chronicMatch = hco3 >= chronicLow - 1 && hco3 <= chronicHigh + 1;
    const screen = `Acute screen: HCO3 falls about 2 mEq/L per 10-mm Hg PaCO2 fall (about ${numberText(acuteExpected)} here). Chronic screen: HCO3 falls about 4-5 per 10 (about ${rangeText(chronicLow, chronicHigh)} here).`;
    if (hco3 < chronicLow - 1) {
      return {
        label: "mixed respiratory alkalosis and metabolic acidosis",
        why: `${co2Label} is low from excess ventilation, while HCO3 ${numberText(hco3)} is below the approximate chronic response. A separate bicarbonate-lowering metabolic acidosis is also present.`,
        compensation: screen
      };
    }
    if (hco3 > acuteHigh) {
      return {
        label: "mixed respiratory and metabolic alkalosis",
        why: `${co2Label} is low from excess ventilation, while HCO3 ${numberText(hco3)} is above the expected acute response. A separate bicarbonate-raising metabolic alkalosis is also present.`,
        compensation: screen
      };
    }
    if (acuteMatch && chronicMatch) {
      const predictedAcuteP = 7.4 + (0.08 * delta);
      const predictedChronicP = 7.4 + (0.03 * delta);
      const chronicCloser = Math.abs(ph - predictedChronicP) < Math.abs(ph - predictedAcuteP);
      return {
        label: `${chronicCloser ? "chronic" : "acute"} respiratory alkalosis with an expected renal response`,
        why: `${co2Label} is low from excess ventilation, and HCO3 fits overlapping screening ranges; the pH is closer to the ${chronicCloser ? "chronic" : "acute"} teaching pattern. Clinical duration and prior gases still decide timing.`,
        compensation: screen
      };
    }
    if (acuteMatch) {
      return {
        label: "acute respiratory alkalosis with an expected early renal response",
        why: `${co2Label} is low from excess ventilation, and HCO3 is near the acute estimate rather than the larger chronic adaptation.`,
        compensation: screen
      };
    }
    if (chronicMatch) {
      return {
        label: "chronic respiratory alkalosis with an expected renal response",
        why: `${co2Label} is low from excess ventilation, and the larger HCO3 fall fits time-dependent kidney adaptation.`,
        compensation: screen
      };
    }
    return {
      label: "respiratory alkalosis with an intermediate or evolving renal response",
      why: `${co2Label} is low from excess ventilation, while HCO3 falls between the usual acute and chronic estimates. Evolving disease, treatment timing, or another metabolic process must be resolved clinically.`,
      compensation: screen
    };
  };

  const pco2Acidifying = hasPco2 && paco2 > 45;
  const pco2Alkalinizing = hasPco2 && paco2 < 35;
  const hco3Acidifying = hasHco3 && hco3 < 22;
  const hco3Alkalinizing = hasHco3 && hco3 > 26;
  let interpretation;

  if (hasPco2 && hasHco3 && pco2Acidifying && hco3Acidifying) {
    interpretation = {
      label: "mixed respiratory and metabolic acidosis",
      why: `${co2Label} is high, so CO2 retention is acidifying; HCO3 is low, so acid gain or bicarbonate loss is also acidifying. Because both are primary acidifying changes, one cannot be compensation for the other.`,
      compensation: "No simple compensation rule explains high PCO2 plus low HCO3; this is a same-direction mixed disorder."
    };
  } else if (hasPco2 && hasHco3 && pco2Alkalinizing && hco3Alkalinizing) {
    interpretation = {
      label: "mixed respiratory and metabolic alkalosis",
      why: `${co2Label} is low, so excess CO2 removal is alkalinizing; HCO3 is high, so bicarbonate gain or hydrogen loss is also alkalinizing. Because both are primary alkalinizing changes, one cannot be compensation for the other.`,
      compensation: "No simple compensation rule explains low PCO2 plus high HCO3; this is a same-direction mixed disorder."
    };
  } else if (acidemia) {
    if (hco3Acidifying) interpretation = metabolicAcidosisResult();
    else if (pco2Acidifying) interpretation = respiratoryAcidosisResult();
    else interpretation = { ...result };
  } else if (alkalemia) {
    if (hco3Alkalinizing) interpretation = metabolicAlkalosisResult();
    else if (pco2Alkalinizing) interpretation = respiratoryAlkalosisResult();
    else interpretation = { ...result };
  } else if (hco3Acidifying && pco2Alkalinizing) {
    const respiratoryCandidate = respiratoryAlkalosisResult();
    interpretation = /with an expected (?:early )?renal response/i.test(respiratoryCandidate.label)
      ? respiratoryCandidate
      : metabolicAcidosisResult();
  } else if (hco3Alkalinizing && pco2Acidifying) {
    interpretation = respiratoryAcidosisResult();
  } else if (pco2Acidifying) {
    interpretation = respiratoryAcidosisResult();
  } else if (pco2Alkalinizing) {
    interpretation = respiratoryAlkalosisResult();
  } else if (hco3Acidifying) {
    interpretation = metabolicAcidosisResult();
  } else if (hco3Alkalinizing) {
    interpretation = metabolicAlkalosisResult();
  } else {
    interpretation = { ...result };
  }

  const specimenLabel = specimen === "VBG" ? "VBG" : specimen === "ABG" ? "ABG" : "Blood gas";
  const numberParts = [`pH ${numberText(ph)}`];
  if (hasPco2) numberParts.push(`${co2Label} ${numberText(paco2)}`);
  if (specimen === "ABG" && Number.isFinite(po2)) numberParts.push(`PaO2 ${numberText(po2)}`);
  if (specimen === "VBG" && Number.isFinite(po2)) numberParts.push(`venous PO2 ${numberText(po2)}`);
  if (hasHco3) numberParts.push(`HCO3 ${numberText(hco3)}`);
  const specimenNote = specimen === "VBG"
    ? "**VBG limit:** this is venous blood, so the CO2 value is PvCO2 and any PO2 is venous PO2. A VBG can support acid-base screening, but it does not provide PaO2 or establish arterial oxygenation; confirm an ABG when exact PaCO2 or arterial oxygenation would change urgent care."
    : specimen === "ABG"
      ? "**ABG context:** PaCO2 reflects arterial ventilation. Interpret any PaO2 with FiO2, oxygen device, SpO2, work of breathing, and perfusion rather than as an isolated number."
      : "**Specimen check:** confirm whether this was arterial or venous before using PCO2 for a high-stakes ventilation decision; venous PO2 cannot establish arterial oxygenation.";
  const venousFormulaNote = specimen === "VBG" && hasPco2 && hasHco3
    ? " The compensation equations are centered on arterial PaCO2; using PvCO2 here is only a screening heuristic because venous-to-arterial CO2 agreement varies."
    : "";

  currentTopic = `${specimenLabel} interpretation`;
  updateFocus();
  return [
    `**${specimenLabel} quick read - ${interpretation.label}**`,
    `**Numbers given:** ${numberParts.join(", ")}. This is ${pHState}. ${acidemia ? "Acidemia is the measured low-pH state; acidosis names the process or processes driving it." : alkalemia ? "Alkalemia is the measured high-pH state; alkalosis names the process or processes driving it." : "A near-normal pH does not exclude offsetting primary acidosis and alkalosis."}`,
    `**Why:** ${interpretation.why}`,
    `**Expected-compensation screen:** ${interpretation.compensation}${venousFormulaNote}`,
    specimenNote,
    "**Clinical priority:** these equations are approximate screening heuristics, not treatment targets or ventilator prescriptions. Connect the pattern to airway and ventilation, oxygenation, mental status, work and fatigue, sedatives or opioids, COPD or asthma, sepsis or shock, kidney failure, DKA, vomiting or suction, electrolytes, toxins, and the treatment timeline.",
    "**NCLEX trap:** compensation changes the other component in a predictable direction; a value outside the expected range identifies another primary process. Do not call a near-normal pH normal when PaCO2 and HCO3 are both markedly abnormal."
  ].join("\n\n");
}

