function potassiumDirectionIntent(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  const value = potassiumValueFromInput(lower);
  const lowCue = /\b(hypokalemia|hypokalaemia|hypo k|low potassium|low serum potassium|low k|k low|potassium low)\b/i.test(lower)
    || (Number.isFinite(value) && value < 3.5);
  const highCue = /\b(hyperkalemia|hyperkalaemia|hyper k|high potassium|high serum potassium|high k|k high|potassium high)\b/i.test(lower)
    || (Number.isFinite(value) && value > 5);
  if (lowCue && highCue) return "both";
  if (lowCue) return "low";
  if (highCue) return "high";
  return "unspecified";
}

