function isCkdPathology(disease = {}) {
  return /\b(chronic kidney disease|ckd|chronic renal failure|end-stage renal|esrd)\b/i.test([
    disease.name,
    ...(disease.aliases || []),
    disease.pathology,
    disease.category
  ].join(" "));
}

function isGfrLab(lab = {}) {
  return labTextIncludes(lab, ["egfr", "gfr", "glomerular filtration", "glomerular filtration rate", "creatinine egfr"]);
}

function buildCkdStageDetailSection() {
  const section = document.createElement("section");
  section.className = "ckd-stage-section";
  const heading = document.createElement("strong");
  heading.textContent = "CKD stages by eGFR";
  const note = document.createElement("p");
  note.className = "pharm-detail-text";
  note.textContent = "Use eGFR in mL/min/1.73 m2 as the staging anchor, then confirm kidney damage evidence, persistence, albuminuria/proteinuria, and clinical trend.";
  const wrap = document.createElement("div");
  wrap.className = "ckd-stage-table-wrap";
  const table = document.createElement("table");
  table.className = "ckd-stage-table";
  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  ["Stage", "eGFR", "Nursing meaning"].forEach((label) => {
    const th = document.createElement("th");
    th.textContent = label;
    headRow.append(th);
  });
  thead.append(headRow);
  const tbody = document.createElement("tbody");
  CKD_STAGE_ROWS.forEach((row) => {
    const tr = document.createElement("tr");
    [row.stage, row.egfr, `${row.meaning} ${row.nursing}`].forEach((cellText, index) => {
      const td = document.createElement("td");
      td.dataset.label = ["Stage", "eGFR", "Nursing meaning"][index];
      appendReadableDetailText(td, cellText, { currentLabel: "Chronic kidney disease" });
      tr.append(td);
    });
    tbody.append(tr);
  });
  table.append(thead, tbody);
  wrap.append(table);
  const footer = document.createElement("p");
  footer.className = "pharm-detail-text";
  footer.textContent = "NCLEX trap: a GFR value is not enough by itself. Stage the severity, then look for potassium retention, fluid overload, anemia, metabolic acidosis, bone-mineral changes, nephrotoxic exposure, and renal-dose medication issues.";
  section.append(heading, note, wrap, footer);
  return section;
}

