function compactClinicalReferenceIdentityQuery(input = "") {
  const protectedTokens = normalizeOfflineLookupText(
    protectClinicalIdentityLetters(applyClinicalSpeechFixups(input) || input),
    { dropLookupWords: false }
  ).split(" ");
  return restoreClinicalIdentityLetters(protectedTokens
    .filter((token, index) => token && (
      !CLINICAL_REFERENCE_LOOKUP_DROP_WORDS.has(token)
      || /^aniclinicalletter[a-d]$/.test(token)
      || (CLINICAL_IDENTITY_LETTER_MARKERS.has(token) && /^aniclinicalletter[a-d]$/.test(protectedTokens[index + 1] || ""))
    ))
    .join(" "));
}

function clinicalReferenceWordMatchesToken(word = "", token = "") {
  if (!word || !token) return false;
  if (word === token && token.length >= 2) return true;
  if (word.length < 3 || token.length < 3) return false;
  return word.startsWith(token) || token.startsWith(word);
}

function exactClinicalReferenceIdentityMatch(input = "") {
  const fixedQuery = applyClinicalSpeechFixups(input) || input;
  const cleanQuery = normalizePharmText(fixedQuery);
  const lookupQuery = normalizeOfflineLookupText(fixedQuery, { dropLookupWords: false });
  const compactQuery = compactClinicalReferenceIdentityQuery(fixedQuery);
  const variants = Array.from(new Set([cleanQuery, lookupQuery, compactQuery].filter(Boolean)));
  if (!variants.length) return null;
  const queryTokens = compactQuery.split(" ").filter((token) => token.length >= 2);
  let bestEntry = null;
  let bestScore = 0;

  clinicalReferenceEntries.forEach((entry) => {
    const terms = clinicalReferencePrimaryIdentityTerms(entry);
    let score = 0;
    terms.forEach((term) => {
      const words = term.split(" ").filter(Boolean);
      variants.forEach((variant) => {
        const variantTokens = variant.split(" ").filter(Boolean);
        if (term === variant) {
          score = Math.max(score, 980 + Math.min(term.length, 80));
        } else if (term.length >= 4 && variant.includes(term)) {
          score = Math.max(score, 760 + Math.min(term.length, 80));
        } else if (variant.length >= 4 && term.includes(variant)) {
          score = Math.max(score, 560 + Math.min(variant.length, 80));
        } else if (queryTokens.length && queryTokens.every((token) =>
          words.some((word) => clinicalReferenceWordMatchesToken(word, token))
        )) {
          score = Math.max(score, 500 + queryTokens.length * 30);
        } else if (variantTokens.length >= 2 && variantTokens.every((token) =>
          words.some((word) => clinicalReferenceWordMatchesToken(word, token))
        )) {
          score = Math.max(score, 430 + variantTokens.length * 24);
        }
      });
    });
    if (score && entry.nclexEssential) score += 18;
    if (score > bestScore) {
      bestScore = score;
      bestEntry = entry;
    }
  });

  return bestScore >= 520 ? bestEntry : null;
}

let registeredClinicalReferenceIdentityExactIndex = null;
let fastCanonicalEncyclopediaIndexes = null;
let fastVoiceIdentityIndex = null;
let fastVoiceIdentityRoutingIndex = null;
let fastStandaloneComponentIdentityIndex = null;

function fastCanonicalLookupCore(input = "") {
  return normalizePharmText(applyClinicalSpeechFixups(input) || input)
    .replace(/^\s*(?:(?:hey\s+)?(?:ani|annie)\s+)?(?:what\s+is|what\s+s|whats|define|explain|describe|tell\s+me\s+about|teach\s+me\s+about|open|show|find|search\s+for|look\s+up)\s+/, "")
    .replace(/\s+(?:please|for\s+me)\s*$/, "")
    .trim();
}

function getFastCanonicalEncyclopediaIndexes() {
  if (fastCanonicalEncyclopediaIndexes) return fastCanonicalEncyclopediaIndexes;
  const indexes = {
    pathology: new Map(),
    reference: new Map(),
    lab: new Map(),
    holistic: new Map(),
    drug: new Map()
  };
  const register = (map, item, terms = []) => {
    terms.map((term) => normalizePharmText(term)).filter(Boolean).forEach((key) => {
      if (!map.has(key)) map.set(key, item);
      else if (map.get(key) !== item) map.set(key, null);
    });
  };
  pathologyDiseases.forEach((item) => register(indexes.pathology, item, [item.name, item.displayName]));
  clinicalReferenceEntries.forEach((item) => register(indexes.reference, item, [item.name, item.displayName, item.fullForm]));
  const labBuckets = new Map();
  pharmSearchableLabRanges.forEach((item) => {
    [item.name, item.displayName].map((term) => normalizePharmText(term)).filter(Boolean).forEach((key) => {
      const bucket = labBuckets.get(key) || [];
      if (!bucket.includes(item)) bucket.push(item);
      labBuckets.set(key, bucket);
    });
  });
  labBuckets.forEach((items, key) => {
    const canonicalNames = new Set(items.map((item) => normalizePharmText(item.name || item.displayName)).filter(Boolean));
    if (canonicalNames.size > 1) {
      indexes.lab.set(key, null);
      return;
    }
    const preferred = items.find((item) => !safeText(item.populationGroup).trim())
      || items.find((item) => /adult|general/i.test(safeText(item.populationGroup)))
      || items[0];
    indexes.lab.set(key, preferred || null);
  });
  holisticRemedies.forEach((item) => register(indexes.holistic, item, [item.name, item.displayName]));
  pharmDrugs.forEach((item) => register(indexes.drug, item, [item.name, item.generic, item.displayName, pharmDrugDisplayName(item, "")]));
  fastCanonicalEncyclopediaIndexes = indexes;
  return fastCanonicalEncyclopediaIndexes;
}

function fastIdentityText(value = "") {
  if (typeof value === "string" || typeof value === "number") return safeText(value);
  return safeText(value?.name || value?.displayName || value?.brand || value?.label || value?.term || "");
}

function isAcronymShapedIdentityAlias(value = "") {
  const text = fastIdentityText(value).trim();
  if (!text || text.length > 16 || text.split(/\s+/).length > 2) return false;
  return /[A-Z].*[A-Z]/.test(text) || /[A-Za-z].*\d|\d.*[A-Za-z]/.test(text);
}

function encyclopediaIdentityTermGroups(type = "", item = {}) {
  const shared = [
    { values: item.preferredBareAliases || [], termKind: "preferred-bare-alias", sourceField: "preferredBareAliases" },
    { values: item.abbreviations || [], termKind: "abbreviation", sourceField: "abbreviations" },
    { values: item.aliases || [], termKind: "identity-alias", sourceField: "aliases" },
    { values: item.commonMisspellings || [], termKind: "misspelling", sourceField: "commonMisspellings" }
  ];
  if (type === "drug") {
    return [
      { values: [item.name, item.generic, item.displayName, pharmDrugDisplayName(item, "")], termKind: "canonical", sourceField: "name/generic/displayName" },
      ...shared.slice(0, 3),
      { values: [item.brandExamples || [], item.brands || []], termKind: "brand", sourceField: "brandExamples/brands" },
      shared[3]
    ];
  }
  if (type === "reference") {
    return [
      { values: [item.name, item.displayName, item.fullForm], termKind: "canonical", sourceField: "name/displayName/fullForm" },
      ...shared
    ];
  }
  return [
    { values: [item.name, item.displayName], termKind: "canonical", sourceField: "name/displayName" },
    ...shared
  ];
}

function getFastVoiceIdentityIndex() {
  if (fastVoiceIdentityIndex) return fastVoiceIdentityIndex;
  const index = new Map();
  const register = (type, item, groups = []) => {
    groups.forEach((group) => {
      const declaredTermKind = safeText(group?.termKind || "identity-alias");
      const sourceField = safeText(group?.sourceField || "aliases");
      (Array.isArray(group?.values) ? group.values.flat() : [group?.values]).forEach((value) => {
        const termKind = declaredTermKind === "identity-alias" && isAcronymShapedIdentityAlias(value)
          ? "acronym-alias"
          : declaredTermKind;
        const key = normalizePharmText(fastIdentityText(value));
        if (!key) return;
        const owners = index.get(key) || [];
        let owner = owners.find((candidate) => candidate.type === type && candidate.item === item);
        if (!owner) {
          owner = { type, item, termKinds: [], sourceFields: [], matchedIdentity: key };
          owners.push(owner);
          index.set(key, owners);
        }
        if (!owner.termKinds.includes(termKind)) owner.termKinds.push(termKind);
        if (!owner.sourceFields.includes(sourceField)) owner.sourceFields.push(sourceField);
      });
    });
  };
  pathologyDiseases.forEach((item) => register("pathology", item, encyclopediaIdentityTermGroups("pathology", item)));
  clinicalReferenceEntries.forEach((item) => register("reference", item, encyclopediaIdentityTermGroups("reference", item)));
  pharmSearchableLabRanges.forEach((item) => register("lab", item, encyclopediaIdentityTermGroups("lab", item)));
  holisticRemedies.forEach((item) => register("holistic", item, encyclopediaIdentityTermGroups("holistic", item)));
  pharmDrugs.forEach((item) => register("drug", item, encyclopediaIdentityTermGroups("drug", item)));
  fastVoiceIdentityIndex = index;
  return fastVoiceIdentityIndex;
}

function addFastVoiceRoutingBucket(map, key, value) {
  if (!key) return;
  const bucket = map.get(key) || [];
  if (!bucket.includes(value)) bucket.push(value);
  map.set(key, bucket);
}

function getFastVoiceIdentityRoutingIndex() {
  if (fastVoiceIdentityRoutingIndex) return fastVoiceIdentityRoutingIndex;
  const identityIndex = getFastVoiceIdentityIndex();
  const sortedIdentities = Array.from(identityIndex.keys()).sort();
  const tokenPrefixBuckets = new Map();
  const byFirstLength = new Map();
  const byInnerLength = new Map();
  sortedIdentities.forEach((identity) => {
    const tokenPrefixes = new Set(identity
      .split(" ")
      .filter((token) => token.length >= 3)
      .map((token) => token.slice(0, 3)));
    tokenPrefixes.forEach((prefix) => addFastVoiceRoutingBucket(tokenPrefixBuckets, prefix, identity));
    addFastVoiceRoutingBucket(byFirstLength, `${identity[0]}:${identity.length}`, identity);
    addFastVoiceRoutingBucket(byInnerLength, `${identity.slice(1, 3)}:${identity.length}`, identity);
  });
  fastVoiceIdentityRoutingIndex = {
    identityIndex,
    sortedIdentities,
    tokenPrefixBuckets,
    byFirstLength,
    byInnerLength
  };
  return fastVoiceIdentityRoutingIndex;
}

function fastVoiceSortedIdentityStart(sortedIdentities = [], query = "") {
  let low = 0;
  let high = sortedIdentities.length;
  while (low < high) {
    const middle = (low + high) >> 1;
    if (sortedIdentities[middle] < query) low = middle + 1;
    else high = middle;
  }
  return low;
}

function fastVoiceIdentityCandidates(input = "") {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const variants = Array.from(new Set([
    normalizePharmText(input),
    normalizeOfflineLookupText(input, { dropLookupWords: false }),
    normalizePharmText(fixed),
    normalizeOfflineLookupText(fixed, { dropLookupWords: false })
  ].filter(Boolean)));
  const index = getFastVoiceIdentityIndex();
  const candidates = [];
  variants.forEach((variant) => {
    (index.get(variant) || []).forEach((candidate) => {
      const existing = candidates.find((owner) => owner.type === candidate.type && owner.item === candidate.item);
      if (!existing) {
        candidates.push({
          ...candidate,
          termKinds: Array.from(new Set(candidate.termKinds || [])),
          sourceFields: Array.from(new Set(candidate.sourceFields || [])),
          matchedIdentities: [variant]
        });
        return;
      }
      existing.termKinds = Array.from(new Set([
        ...(existing.termKinds || []),
        ...(candidate.termKinds || [])
      ]));
      existing.sourceFields = Array.from(new Set([
        ...(existing.sourceFields || []),
        ...(candidate.sourceFields || [])
      ]));
      existing.matchedIdentities = Array.from(new Set([
        ...(existing.matchedIdentities || []),
        variant
      ]));
    });
  });
  return candidates;
}

function fastVoiceIdentitySearchCandidates(input = "", limit = 80) {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const query = fastCanonicalLookupCore(fixed) || normalizePharmText(fixed);
  if (!query || query.length < 2) return [];
  const singleTokenQuery = !query.includes(" ");
  const collected = new Map();
  const routing = getFastVoiceIdentityRoutingIndex();
  const candidateIdentities = new Set();
  if (routing.identityIndex.has(query)) candidateIdentities.add(query);
  const prefixStart = fastVoiceSortedIdentityStart(routing.sortedIdentities, query);
  for (let index = prefixStart; index < routing.sortedIdentities.length; index += 1) {
    const identity = routing.sortedIdentities[index];
    if (!identity.startsWith(query)) break;
    candidateIdentities.add(identity);
  }
  if (singleTokenQuery && query.length >= 3) {
    (routing.tokenPrefixBuckets.get(query.slice(0, 3)) || []).forEach((identity) => {
      if (identity.split(" ").some((token) => token.startsWith(query))) candidateIdentities.add(identity);
    });
  }
  candidateIdentities.forEach((identity) => {
    const owners = routing.identityIndex.get(identity) || [];
    let evidence = 0;
    if (identity === query) {
      evidence = 1000;
    } else if (identity.startsWith(query)) {
      evidence = 700 + Math.min(query.length, 80);
    } else if (singleTokenQuery && query.length >= 3
      && identity.split(" ").some((token) => token.startsWith(query))) {
      evidence = 320 + Math.min(query.length, 40);
    }
    if (!evidence) return;
    owners.forEach((owner) => {
      const item = owner.item || {};
      const primaryTerms = owner.type === "drug"
        ? [item.name, item.generic, item.displayName, pharmDrugDisplayName(item, "")]
        : owner.type === "reference"
          ? [item.name, item.displayName, item.fullForm]
          : [item.name, item.displayName];
      const normalizedPrimaryTerms = primaryTerms.map((term) => normalizePharmText(term)).filter(Boolean);
      const primaryEvidence = normalizedPrimaryTerms.includes(query)
        ? 520
        : normalizedPrimaryTerms.some((term) => term.startsWith(query))
          ? 380
          : 0;
      const preferredBarePrefixEvidence = identity !== query
        && owner.termKinds?.includes("preferred-bare-alias")
        ? ENCYCLOPEDIA_IDENTITY_TERM_KIND_RANK["preferred-bare-alias"]
        : 0;
      const ownerEvidence = evidence + primaryEvidence + preferredBarePrefixEvidence;
      const key = offlineLookupEntityKey(owner);
      const previous = collected.get(key);
      if (!previous || ownerEvidence > previous.fastEvidenceScore) {
        collected.set(key, {
          type: owner.type,
          item: owner.item,
          termKinds: Array.isArray(owner.termKinds) ? [...owner.termKinds] : [],
          sourceFields: Array.isArray(owner.sourceFields) ? [...owner.sourceFields] : [],
          matchedIdentity: identity,
          fastBoost: ownerEvidence >= 1000 ? 520 : 300,
          fastEvidenceScore: ownerEvidence,
          fastMatchCount: 1,
          compactIdentityMatch: true
        });
      }
    });
  });
  return Array.from(collected.values())
    .sort((a, b) => b.fastEvidenceScore - a.fastEvidenceScore
      || Boolean(b.item?.nclexEssential) - Boolean(a.item?.nclexEssential)
      || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .slice(0, Math.max(1, limit));
}

function fastVoiceNearIdentityAssessment(input = "", options = {}) {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const query = fastCanonicalLookupCore(fixed) || normalizePharmText(fixed);
  const empty = { match: null, ambiguous: false, candidates: [] };
  if (!query || query.length < 5 || query.split(" ").length > 7) return empty;
  const routing = getFastVoiceIdentityRoutingIndex();
  const queryTokenCount = query.split(" ").filter(Boolean).length;
  const radius = Math.max(3, Math.ceil(query.length * 0.15));
  const identities = new Set();
  for (let length = Math.max(5, query.length - radius); length <= query.length + radius; length += 1) {
    (routing.byFirstLength.get(`${query[0]}:${length}`) || []).forEach((identity) => identities.add(identity));
    (routing.byInnerLength.get(`${query.slice(1, 3)}:${length}`) || []).forEach((identity) => identities.add(identity));
  }
  const preferredTypes = options.preferredTypes instanceof Set
    ? options.preferredTypes
    : new Set(Array.isArray(options.preferredTypes) ? options.preferredTypes : []);
  const ownerScores = new Map();
  identities.forEach((identity) => {
    if (identity === query) return;
    const maxLength = Math.max(query.length, identity.length);
    const allowedDistance = maxLength <= 7
      ? 1
      : maxLength <= 18
        ? 2
        : Math.max(3, Math.floor(maxLength * 0.12));
    if (Math.abs(query.length - identity.length) > allowedDistance) return;
    if (query[0] !== identity[0] && query.slice(1, 3) !== identity.slice(1, 3)) return;
    const identityTokenCount = identity.split(" ").filter(Boolean).length;
    if (queryTokenCount >= 2 && Math.abs(queryTokenCount - identityTokenCount) > 1) return;
    const distance = nearIdentityEditDistance(query, identity);
    if (!distance || distance > allowedDistance) return;
    const similarity = 1 - (distance / maxLength);
    const identityOwners = routing.identityIndex.get(identity) || [];
    const compactCanonicalMedicationSingleEdit = queryTokenCount === 1
      && distance === 1
      && Math.min(query.length, identity.length) <= 8
      && identityOwners.some((owner) => owner.type === "drug"
        && encyclopediaIdentityPrimaryTerms(owner)
          .some((term) => normalizePharmText(term) === identity));
    // Short medication names have little room for a single keyboard error:
    // one changed/transposed/repeated letter in a seven- or eight-character
    // canonical name produces roughly 0.84-0.88 similarity, and a repeated
    // letter can make the misspelled query itself nine characters. Preserve
    // that reviewed canonical-medication boundary while retaining the stricter
    // 0.90 floor for other longer single-token identities and 0.86 for
    // multiword identities.
    const minimumSimilarity = queryTokenCount >= 2
      ? 0.86
      : compactCanonicalMedicationSingleEdit
        ? 0.84
        : 0.9;
    if (similarity < minimumSimilarity) return;
    identityOwners.forEach((owner) => {
      const primaryIdentity = encyclopediaIdentityPrimaryTerms(owner)
        .some((term) => normalizePharmText(term) === identity);
      const preferred = preferredTypes.has(owner.type);
      const rankScore = similarity + (primaryIdentity ? 0.04 : 0) + (preferred ? 0.055 : 0);
      const key = offlineLookupEntityKey(owner);
      const previous = ownerScores.get(key);
      if (!previous || rankScore > previous.rankScore) {
        ownerScores.set(key, {
          type: owner.type,
          item: owner.item,
          identity,
          similarity,
          rankScore,
          primaryIdentity,
          explicit: preferred
        });
      }
    });
  });
  const candidates = Array.from(ownerScores.values())
    .sort((left, right) => right.rankScore - left.rankScore
      || Number(right.primaryIdentity) - Number(left.primaryIdentity)
      || offlineLookupEntityLabel(left).localeCompare(offlineLookupEntityLabel(right)));
  const best = candidates[0] || null;
  const runnerUp = candidates.find((candidate) => candidate.type !== best?.type || candidate.item !== best?.item) || null;
  if (!best) return empty;
  const sameIdentity = runnerUp && normalizePharmText(best.identity) === normalizePharmText(runnerUp.identity);
  const explicitWinner = runnerUp && best.explicit && !runnerUp.explicit;
  const uniquePrimaryWinner = sameIdentity && best.primaryIdentity && !runnerUp.primaryIdentity;
  if (runnerUp
    && !explicitWinner
    && !uniquePrimaryWinner
    && (sameIdentity || best.rankScore - runnerUp.rankScore < 0.035)) {
    return { match: null, ambiguous: true, candidates: [best, runnerUp] };
  }
  return { match: best, ambiguous: false, candidates: [best] };
}

function isStandaloneComponentParityEntry(item = {}) {
  return item?.componentParityWave44 === true || item?.wave44ComponentParity === true;
}

function getFastStandaloneComponentIdentityIndex() {
  if (fastStandaloneComponentIdentityIndex) return fastStandaloneComponentIdentityIndex;
  const index = new Map();
  const register = (type, item, terms = []) => {
    if (!isStandaloneComponentParityEntry(item)) return;
    const seen = new Set();
    terms.flat().forEach((term) => {
      const key = normalizePharmText(term);
      if (!key || seen.has(key)) return;
      seen.add(key);
      const prior = index.get(key);
      if (!prior) index.set(key, { type, item });
      else if (prior.type !== type || prior.item !== item) index.set(key, null);
    });
  };
  pathologyDiseases.forEach((item) => register("pathology", item, [
    item.name,
    item.displayName,
    item.aliases || [],
    item.abbreviations || [],
    item.commonMisspellings || []
  ]));
  clinicalReferenceEntries.forEach((item) => register("reference", item, [
    item.name,
    item.displayName,
    item.fullForm,
    item.aliases || [],
    item.abbreviations || [],
    item.commonMisspellings || []
  ]));
  pharmSearchableLabRanges.forEach((item) => register("lab", item, [
    item.name,
    item.displayName,
    item.aliases || [],
    item.abbreviations || [],
    item.commonMisspellings || []
  ]));
  holisticRemedies.forEach((item) => register("holistic", item, [
    item.name,
    item.displayName,
    item.aliases || [],
    item.abbreviations || [],
    item.commonMisspellings || []
  ]));
  pharmDrugs.forEach((item) => register("drug", item, [
    item.name,
    item.generic,
    item.displayName,
    pharmDrugDisplayName(item, ""),
    item.aliases || [],
    item.brandExamples || [],
    item.brands || [],
    item.abbreviations || [],
    item.commonMisspellings || []
  ]));
  fastStandaloneComponentIdentityIndex = index;
  return fastStandaloneComponentIdentityIndex;
}

function fastStandaloneComponentCandidate(input = "") {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const canonicalCore = fastCanonicalLookupCore(fixed);
  const variants = Array.from(new Set([
    canonicalCore,
    normalizePharmText(fixed),
    normalizeOfflineLookupText(fixed),
    normalizeOfflineLookupText(fixed, { dropLookupWords: false })
  ].filter(Boolean)));
  const index = getFastStandaloneComponentIdentityIndex();
  const matches = Array.from(new Map(variants
    .map((variant) => index.get(variant))
    .filter(Boolean)
    .map((candidate) => [offlineLookupEntityKey(candidate), candidate])).values());
  if (matches.length !== 1) return null;
  const preferredBareAliasOwners = canonicalCore
    ? fastVoiceIdentityCandidates(canonicalCore).filter((candidate) => (
      Array.isArray(candidate.item?.preferredBareAliases)
      && candidate.item.preferredBareAliases.some((term) => normalizePharmText(term) === canonicalCore)
    ))
    : [];
  if (preferredBareAliasOwners.length
    && !preferredBareAliasOwners.some((candidate) => (
      candidate.type === matches[0].type && candidate.item === matches[0].item
    ))) {
    // A component-only alias must not preempt a separately reviewed preferred
    // owner of the same bare term. Contextual component queries remain free to
    // resolve once they include their distinguishing words.
    return null;
  }
  // A component alias must never steal the exact title of its comparison or
  // combination parent.  Preserve any other canonical card that the raw query
  // names exactly; aliases remain available when no competing canonical owner
  // exists (for example, "Ca-DTPA" -> pentetate calcium trisodium).
  const canonicalIndexes = getFastCanonicalEncyclopediaIndexes();
  const canonicalOwners = canonicalCore
    ? ["pathology", "reference", "lab", "holistic", "drug"]
      .map((type) => canonicalIndexes[type].get(canonicalCore))
      .filter(Boolean)
      .map((item, position, items) => ({
        type: ["pathology", "reference", "lab", "holistic", "drug"]
          .find((type) => canonicalIndexes[type].get(canonicalCore) === item),
        item
      }))
      .filter((owner, position, owners) => owners.findIndex((candidate) => (
        candidate.type === owner.type && candidate.item === owner.item
      )) === position)
    : [];
  if (canonicalOwners.length !== 0
      && (canonicalOwners.length !== 1
        || offlineLookupEntityKey(canonicalOwners[0]) !== offlineLookupEntityKey(matches[0]))) {
    return null;
  }
  return {
    ...matches[0],
    score: 3740,
    exactIdentity: true,
    nearIdentity: false,
    fastCanonical: true,
    standaloneComponentOwner: true
  };
}

function fastCanonicalEncyclopediaCandidate(input = "") {
  const core = fastCanonicalLookupCore(input);
  if (!core) return null;
  const indexes = getFastCanonicalEncyclopediaIndexes();
  const candidateFor = (type, item) => item ? {
    type,
    item,
    score: 3700,
    exactIdentity: true,
    nearIdentity: false,
    fastCanonical: true
  } : null;
  const matchesFor = (key) => ["pathology", "reference", "lab", "holistic", "drug"]
    .map((type) => candidateFor(type, indexes[type].get(key)))
    .filter(Boolean);
  const normalizedInput = normalizeIntentText(applyClinicalSpeechFixups(input) || input);
  const labIntent = /\b(?:level|levels|range|ranges|normal|serum|plasma|blood|trough|peak|therapeutic|lab|labs|test|tests|value|values|monitor|monitoring)\b/i.test(normalizedInput);
  const medicationIntent = /\b(?:drug|medication|medicine|med|dose|dosing|administer|administration|give|take|side effect|adverse effect|contraindication|interaction|mechanism of action)\b/i.test(normalizedInput);
  const toxicityIntent = /\b(?:toxic|toxicity|overdose|poisoning)\b/i.test(normalizedInput);
  const labCore = core
    .replace(/\b(?:normal|serum|plasma|blood|therapeutic|toxic|toxicity|lab|labs|test|tests|level|levels|range|ranges|value|values|trough|peak|monitor|monitoring)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const medicationCore = core
    .replace(/\b(?:side\s+effects?|adverse\s+effects?|mechanism\s+of\s+action|drug|medication|medicine|med|dose|dosing|administer|administration|give|take|contraindications?|interactions?|toxic|toxicity)\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  const canonicalMatches = matchesFor(core).map((candidate) => ({ ...candidate, canonicalMatch: true }));
  const aliasMatches = fastVoiceIdentityCandidates(core).map((candidate) => ({
    ...candidate,
    score: 3680,
    exactIdentity: true,
    nearIdentity: false,
    fastCanonical: true,
    fastAlias: true
  }));
  let matches = [...canonicalMatches, ...aliasMatches].filter((candidate, index, all) =>
    all.findIndex((owner) => owner.type === candidate.type && owner.item === candidate.item) === index
  );
  if (labIntent && labCore && labCore !== core) {
    const labItem = indexes.lab.get(labCore);
    const referenceItem = indexes.reference.get(labCore);
    [candidateFor("lab", labItem), candidateFor("reference", referenceItem)].filter(Boolean).forEach((candidate) => {
      if (!matches.some((owner) => owner.type === candidate.type && owner.item === candidate.item)) matches.push(candidate);
    });
  }
  if (!matches.length && (medicationIntent || toxicityIntent) && medicationCore && medicationCore !== core) {
    const drugItem = indexes.drug.get(medicationCore);
    matches = [candidateFor("drug", drugItem)].filter(Boolean);
  }
  if (!matches.length) return null;

  const primaryTermsFor = (candidate) => {
    const item = candidate.item || {};
    if (candidate.type === "drug") return [item.name, item.generic, item.displayName, pharmDrugDisplayName(item, "")];
    if (candidate.type === "reference") return [item.name, item.displayName, item.fullForm];
    return [item.name, item.displayName];
  };
  const candidateQuality = (candidate) => {
    const primaryMatch = primaryTermsFor(candidate).some((term) => normalizePharmText(term) === core);
    const noPopulationQualifier = !safeText(candidate.item?.populationGroup).trim();
    const preferredBareAlias = Array.isArray(candidate.item?.preferredBareAliases)
      && candidate.item.preferredBareAliases.some((term) => normalizePharmText(term) === core);
    return (primaryMatch ? 1000 : 0)
      + (candidate.canonicalMatch ? 200 : 0)
      + (preferredBareAlias ? 800 : 0)
      + (noPopulationQualifier ? 40 : 0)
      + (candidate.item?.nclexEssential ? 10 : 0);
  };
  const byType = new Map();
  matches.forEach((candidate) => {
    const previous = byType.get(candidate.type);
    if (!previous || candidateQuality(candidate) > candidateQuality(previous)) {
      byType.set(candidate.type, candidate);
    }
  });
  if (labIntent && byType.has("lab")) return byType.get("lab");
  if (medicationIntent && byType.has("drug")) return byType.get("drug");
  if (toxicityIntent && byType.has("pathology")) return byType.get("pathology");
  if (matches.length === 1) return matches[0];
  if (byType.has("drug") && byType.has("lab")) {
    const labItem = byType.get("lab")?.item || {};
    const labMonitoringContext = normalizePharmText([
      labItem.category,
      labItem.sourceType,
      labItem.range,
      labItem.why
    ].filter(Boolean).join(" "));
    // Bare names such as digoxin or lithium mean the medication; adding
    // "level", "trough", or another laboratory cue selects monitoring.
    // For non-drug laboratory analytes such as albumin, the lab remains the
    // more natural unqualified owner.
    return /therapeutic|toxicity|toxic|trough|peak|drug level|nomogram/.test(labMonitoringContext)
      ? byType.get("drug")
      : byType.get("lab");
  }
  if (byType.has("lab") && byType.has("reference")) return byType.get("lab");
  if (byType.has("pathology")) return byType.get("pathology");
  // A genuine unresolved cross-domain identity should fall through to ANI's
  // richer intent resolver instead of being claimed by arbitrary type order.
  return null;
}

// Strict canonical ownership is intentionally narrower than the broader fast
// candidate helper above. It never considers aliases, associated search terms,
// or fuzzy intent. A user who types the exact title of an installed card must
// reach that card before any alias/routing overlay is allowed to reinterpret
// the query. Genuine cross-domain canonical collisions remain unresolved so a
// preferred type or deliberate disambiguation can decide them.
function strictCanonicalEncyclopediaCandidate(input = "", preferredType = "") {
  const normalizedPreferredType = preferredType === "procedures" ? "reference" : safeText(preferredType);
  const indexes = getFastCanonicalEncyclopediaIndexes();
  const typeOrder = normalizedPreferredType
    ? [normalizedPreferredType]
    : ["pathology", "reference", "lab", "holistic", "drug"];
  // Check the literal normalized phrase before interpreting leading words such
  // as "open", "show", or "find" as commands. Otherwise a real title such as
  // "Open fracture" is reduced to "fracture" and silently opens its parent.
  const rawLiteralCore = normalizePharmText(input).trim();
  const literalCore = normalizePharmText(applyClinicalSpeechFixups(input) || input).trim();
  const commandCore = fastCanonicalLookupCore(input);
  const cores = Array.from(new Set([rawLiteralCore, literalCore, commandCore].filter(Boolean)));
  for (const core of cores) {
    const matches = typeOrder
      .map((type) => ({ type, item: indexes[type]?.get(core) || null }))
      .filter((candidate) => candidate.item)
      .filter((candidate, index, all) => all.findIndex((owner) => owner.item === candidate.item) === index);
    if (matches.length !== 1) continue;
    return {
      ...matches[0],
      score: 3900,
      exactIdentity: true,
      nearIdentity: false,
      strictCanonical: true
    };
  }
  return null;
}

function getRegisteredClinicalReferenceIdentityExactIndex() {
  if (registeredClinicalReferenceIdentityExactIndex) return registeredClinicalReferenceIdentityExactIndex;
  const index = new Map();
  clinicalReferenceEntries.forEach((entry) => {
    [
      entry.name,
      entry.displayName,
      entry.fullForm,
      ...(entry.aliases || []),
      ...(entry.abbreviations || []),
      ...(entry.commonMisspellings || [])
    ].forEach((term) => {
      [
        normalizePharmText(term),
        normalizeOfflineLookupText(term),
        normalizeOfflineLookupText(term, { dropLookupWords: false })
      ].filter(Boolean).forEach((identity) => {
        if (!index.has(identity)) index.set(identity, entry);
        else if (index.get(identity) !== entry) index.set(identity, null);
      });
    });
  });
  registeredClinicalReferenceIdentityExactIndex = index;
  return registeredClinicalReferenceIdentityExactIndex;
}

function exactRegisteredClinicalReferenceIdentityMatch(input = "") {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const variants = [
    normalizePharmText(fixed),
    normalizeOfflineLookupText(fixed),
    normalizeOfflineLookupText(fixed, { dropLookupWords: false })
  ].filter(Boolean);
  if (!variants.length) return null;
  const index = getRegisteredClinicalReferenceIdentityExactIndex();
  const matches = Array.from(new Set(variants.map((variant) => index.get(variant)).filter(Boolean)));
  return matches.length === 1 ? matches[0] : null;
}

let registeredLabIdentityExactIndex = null;

function getRegisteredLabIdentityExactIndex() {
  if (registeredLabIdentityExactIndex) return registeredLabIdentityExactIndex;
  const index = new Map();
  pharmSearchableLabRanges.forEach((lab) => {
    [lab.name, lab.displayName, ...(lab.aliases || [])].forEach((term) => {
      [
        normalizePharmText(term),
        normalizeOfflineLookupText(term, { dropLookupWords: false })
      ].filter(Boolean).forEach((identity) => {
        if (!index.has(identity)) {
          index.set(identity, lab);
          return;
        }
        const existing = index.get(identity);
        if (existing && normalizePharmText(existing.name || existing.displayName) === normalizePharmText(lab.name || lab.displayName)) return;
        index.set(identity, null);
      });
    });
  });
  registeredLabIdentityExactIndex = index;
  return registeredLabIdentityExactIndex;
}

function exactRegisteredLabIdentityMatch(input = "") {
  const fixed = applyClinicalSpeechFixups(input) || input;
  const index = getRegisteredLabIdentityExactIndex();
  const matches = Array.from(new Set([
    normalizePharmText(fixed),
    normalizeOfflineLookupText(fixed),
    normalizeOfflineLookupText(fixed, { dropLookupWords: false })
  ].filter(Boolean).map((variant) => index.get(variant)).filter(Boolean)));
  return matches.length === 1 ? matches[0] : null;
}

function exactRegisteredNonReferenceIdentityMatch(input = "") {
  const fixed = applyMedicationSpellingFixups(applyClinicalSpeechFixups(input) || input);
  const variants = Array.from(new Set([
    normalizePharmText(fixed),
    normalizeOfflineLookupText(fixed, { dropLookupWords: false })
  ].filter(Boolean)));
  const exactDrugMatches = Array.from(new Set(variants
    .map((variant) => getPharmIdentityExactIndex().get(variant))
    .filter(Boolean)));
  if (exactDrugMatches.length === 1) return { type: "drug", item: exactDrugMatches[0] };

  const registeredPathology = exactRegisteredPathologyIdentityMatch(fixed);
  const exactLab = exactRegisteredLabIdentityMatch(fixed);
  if (registeredPathology && exactLab) {
    const pathologyIsCanonical = [registeredPathology.name, registeredPathology.displayName]
      .filter(Boolean)
      .some((term) => variants.includes(normalizePharmText(term)));
    const labIsCanonical = [exactLab.name, exactLab.displayName]
      .filter(Boolean)
      .some((term) => variants.includes(normalizePharmText(term)));
    if (labIsCanonical && !pathologyIsCanonical) return { type: "lab", item: exactLab };
    if (pathologyIsCanonical && !labIsCanonical) return { type: "pathology", item: registeredPathology };
  }
  if (registeredPathology) return { type: "pathology", item: registeredPathology };
  const indexedPathology = exactPathologyIdentityMatch(fixed);
  if (indexedPathology && pathologyIdentityMatchesCompactQuery(indexedPathology, fixed)) {
    return { type: "pathology", item: indexedPathology };
  }

  return exactLab ? { type: "lab", item: exactLab } : null;
}

function clinicalReferenceSearchBlob(entry = {}) {
  const cached = clinicalReferenceSearchBlobCache.get(entry);
  if (cached) return cached;
  const blob = normalizePharmText([
    entry.name,
    entry.displayName,
    entry.fullForm,
    entry.type,
    entry.category,
    ...(entry.aliases || []),
    ...(entry.abbreviations || []),
    ...(entry.commonMisspellings || []),
    ...(entry.searchTerms || []),
    entry.summary,
    entry.quickAnswer,
    clinicalReferenceResultMeaningText(entry),
    ...(entry.tags || []),
    ...clinicalReferenceSectionPairs(entry).flat()
  ].join(" "));
  clinicalReferenceSearchBlobCache.set(entry, blob);
  return blob;
}

function queryUsesHintsAsOrdinaryLanguage(input = "") {
  const text = safeText(input);
  if (!/\bhints?\b/i.test(text)) return false;
  const hasClinicalContext = /\b(acute vestibular|vertigo|dizz(?:y|iness)?|nystagmus|skew|head impulse|vestibular neuritis|posterior(?: circulation)? stroke|neurologic|eye movement|hints\s*(?:exam|examination|test|plus))\b/i.test(text);
  if (hasClinicalContext) return false;
  return /\b(study|studying|study tips?|homework|test[-\s]?taking|exam prep|clues?|advice|helpful|general tips?)\b/i.test(text);
}

function scoreClinicalReferenceEntry(entry = {}, query = "") {
  if (normalizePharmText(entry?.name) === "hints examination" && queryUsesHintsAsOrdinaryLanguage(query)) {
    return 0;
  }
  const fixedQuery = applyClinicalSpeechFixups(query) || query;
  const cleanQuery = normalizePharmText(fixedQuery);
  const lookupQuery = normalizeOfflineLookupText(fixedQuery) || cleanQuery;
  const scoreQuery = lookupQuery || cleanQuery;
  if (!scoreQuery) return 0;
  const identityTerms = clinicalReferenceIdentityTerms(entry);
  const blob = clinicalReferenceSearchBlob(entry);
  const tokens = scoreQuery.split(" ").filter((token) => token.length > 1 && !FAST_LOOKUP_STOP_WORDS.has(token));
  let score = 0;
  const hasOccultBloodIntent = /\b(?:fecal\s+)?occult\s+blood(?:\s+test)?\b|\bstool\s+(?:occult\s+)?blood(?:\s+test)?\b|\bfobt\b/i.test(fixedQuery)
    || /\b(?:a\s+|the\s+|of\s+)?cold\s+blood\s+test\b/i.test(query);
  const entryIsFobt = identityTerms.includes("fobt")
    || identityTerms.includes("fecal occult blood test")
    || identityTerms.includes("occult blood test")
    || identityTerms.includes("stool occult blood test");
  const entryIsBloodCulture = identityTerms.some((term) => /\bblood culture\b/.test(term));
  const queryNamesIndirectCoombs = /\bindirect\s+coombs|\bindirect\s+antiglobulin|\biat\b|\bantibody\s+screen\b/i.test(fixedQuery);
  const queryNamesDirectCoombs = /\bdirect\s+coombs|\bdirect\s+antiglobulin|\bdat\b/i.test(fixedQuery);
  const entryIsIndirectCoombs = identityTerms.some((term) => /\bindirect\s+coombs|\bindirect\s+antiglobulin|\biat\b|\bantibody\s+screen\b/.test(term));
  const entryIsDirectCoombs = identityTerms.some((term) => /^coombs$|\bdirect\s+coombs|\bdirect\s+antiglobulin|\bdat\b/.test(term));

  if (hasOccultBloodIntent && entryIsFobt) {
    score += 980;
  }
  if (hasOccultBloodIntent && entryIsBloodCulture) {
    score -= 260;
  }
  if (queryNamesIndirectCoombs) {
    score += entryIsIndirectCoombs ? 620 : entryIsDirectCoombs ? -240 : 0;
  }
  if (queryNamesDirectCoombs) {
    score += entryIsDirectCoombs ? 420 : entryIsIndirectCoombs ? -180 : 0;
  }

  if (identityTerms.includes(scoreQuery)) {
    score += 620;
  }
  identityTerms.forEach((term) => {
    if (term === scoreQuery) score += 280;
    else if (term.length >= 4 && scoreQuery.includes(term)) score += term.includes(" ") ? 260 : 170;
    else if (pharmTermContainsQuery(term, scoreQuery) || (scoreQuery.length >= 4 && term.includes(scoreQuery))) score += 145;
  });
  tokens.forEach((token) => {
    if (identityTerms.some((term) => term === token || pharmTermContainsQuery(term, token))) score += 42;
    else if (blob.includes(token)) score += 12;
    score += Math.max(...identityTerms.map((term) => pharmTokenCloseness(token, term)), 0);
  });

  if (entry.type === "growth" && /\b(height|weight|growth|percentile|percentiles|kid|child|pediatric|peds|age\s*\d|years?\s*old|yo)\b/i.test(query)) {
    score += 360;
  }
  if (entry.type === "maternity" && /\b(trimester|pregnancy|pregnant|prenatal|maternity|maternal|obstetric|weeks?)\b/i.test(query)) {
    score += 340;
  }
  if (entry.type === "maternity" && wantsGestationalWeightGainReference(query)) {
    score += /\bgestational\s+weight\s+gain|pregnancy\s+weight\s+gain|pregnant\s+\w*\s*weight/i.test([entry.name, ...(entry.aliases || [])].join(" "))
      ? 1200
      : 220;
  }
  if (entry.type === "procedure" && /\b(procedure|test|diagnostic|collection|collect|before|after|during|position|steps|prep|teaching)\b/i.test(query)) {
    score += 140;
  }
  if (entry.type === "procedure" && clinicalReferenceResultMeaningRows(entry).length
    && /\b(positive|negative|reactive|nonreactive|non-reactive|abnormal|normal result|result|results|meaning|mean|means|interpret|interpretation|indicate|indicates|suggest|suggests|shows?|high|low|elevated|decreased)\b/i.test(fixedQuery)) {
    score += 240;
  }
  if (entry.type === "assessment" && /\b(low[-\s]?grade fever|mild fever|slight fever|borderline fever|low fever|fever definition|temperature elevation|temp elevation|vital signs?|assessment)\b/i.test(query)) {
    score += 360;
  }
  score += scoreDescriptionMatch("reference", entry, fixedQuery);
  return score;
}

function isClinicalSignReferenceEntry(entry = {}) {
  return !isMicrobiologyReferenceEntry(entry) && (entry.encyclopediaSection === "clinical-signs"
    || ["clinical-sign", "eponymous-sign", "physical-examination-maneuver"].includes(entry.type));
}

const MICROBIOLOGY_FALLBACK_BROWSE_BRANCHES = Object.freeze([
  { id: "infectious-agents", label: "Infectious agents" },
  { id: "host-microbe-ecology", label: "Host-microbe ecology" },
  { id: "biology-pathogenesis", label: "Microbial biology and pathogenesis" },
  { id: "antimicrobial-resistance", label: "Antimicrobial resistance" },
  { id: "diagnostic-microbiology", label: "Diagnostic microbiology" },
  { id: "infection-prevention-control", label: "Infection prevention and control" },
  { id: "disease-gateway", label: "Related diseases" },
  { id: "therapy-vaccine-gateway", label: "Therapies and vaccines" }
]);

function microbiologyBrowseBranches() {
  const configured = Array.isArray(microbiologyDomainCore.BROWSE_BRANCHES)
    ? microbiologyDomainCore.BROWSE_BRANCHES
    : (Array.isArray(microbiologyDatabase.architecture?.browseBranches)
      ? microbiologyDatabase.architecture.browseBranches
      : []);
  const branchById = new Map(configured
    .filter((branch) => branch && safeText(branch.id))
    .map((branch) => [safeText(branch.id), branch]));
  const depthFor = (branch) => {
    let depth = 0;
    let parentId = safeText(branch?.parentId);
    const seen = new Set();
    while (parentId && branchById.has(parentId) && !seen.has(parentId)) {
      seen.add(parentId);
      depth += 1;
      parentId = safeText(branchById.get(parentId)?.parentId);
    }
    return depth;
  };
  const allBranches = configured
    .filter((branch) => branch && safeText(branch.id))
    .map((branch) => ({
      id: safeText(branch.id),
      label: safeText(branch.label || branch.name || branch.id),
      parentId: safeText(branch.parentId),
      depth: depthFor(branch),
      kind: safeText(branch.kind)
    }))
    .filter((branch) => branch.id && branch.label);
  return allBranches.length ? allBranches : MICROBIOLOGY_FALLBACK_BROWSE_BRANCHES.map((branch) => ({ ...branch, parentId: "", depth: 0 }));
}

function microbiologyArchitectureStatus() {
  return safeText(
    microbiologyDatabase.status?.architectureStatus
      || microbiologyDatabase.architectureStatus
      || "AWAITING_APPROVAL"
  );
}

function microbiologyRuntimeCollections() {
  return [
    { targetCollection: "pharmDrugs", type: "drug", items: pharmDrugs },
    { targetCollection: "pathologyDiseases", type: "pathology", items: pathologyDiseases },
    { targetCollection: "labValues", type: "lab", items: pharmSearchableLabRanges },
    { targetCollection: "clinicalReferenceEntries", type: "reference", items: clinicalReferenceEntries },
    { targetCollection: "holisticRemedies", type: "holistic", items: holisticRemedies }
  ];
}

function microbiologyCanonicalRuntimeTitle(item = {}) {
  return safeText(item.name || item.generic || item.displayName);
}

function microbiologyStableRuntimeIds(item = {}) {
  return [item.id, item.cardId, item.topicId, item.directTargetId]
    .map((value) => safeText(value))
    .filter(Boolean);
}

function microbiologyRuntimeTargetFields(target = {}) {
  const nestedTarget = target.target && typeof target.target === "object" ? target.target : {};
  return {
    targetId: safeText(
      target.targetId
        || target.directTargetId
        || target.destinationId
        || target.cardId
        || nestedTarget.targetId
        || nestedTarget.directTargetId
        || nestedTarget.destinationId
        || nestedTarget.cardId
    ),
    targetCollection: safeText(
      target.targetCollection
        || target.declaredCollection
        || target.collection
        || target.targetOwner
        || target.ownerCollection
        || nestedTarget.targetCollection
        || nestedTarget.declaredCollection
        || nestedTarget.collection
        || nestedTarget.ownerCollection
    ),
    canonicalTitle: safeText(
      target.targetName
        || target.canonicalTitle
        || target.label
        || target.name
        || target.title
        || (typeof target.target === "string" ? target.target : "")
        || nestedTarget.targetName
        || nestedTarget.canonicalTitle
        || nestedTarget.name
        || nestedTarget.title
        || nestedTarget.label
    )
  };
}

function resolveMicrobiologyRuntimeTarget(target = {}) {
  const collections = microbiologyRuntimeCollections();
  const { targetId, targetCollection, canonicalTitle } = microbiologyRuntimeTargetFields(target);
  if (targetId) {
    const matches = collections.flatMap((collection) => collection.items
      .filter((item) => microbiologyStableRuntimeIds(item).includes(targetId))
      .map((item) => ({ type: collection.type, item, targetCollection: collection.targetCollection })));
    if (matches.length !== 1) return null;
    const match = matches[0];
    if (targetCollection && match.targetCollection !== targetCollection) return null;
    if (canonicalTitle && microbiologyCanonicalRuntimeTitle(match.item) !== canonicalTitle) return null;
    return match;
  }

  if (!targetCollection || !canonicalTitle) return null;
  const collection = collections.find((candidate) => candidate.targetCollection === targetCollection);
  if (!collection) return null;
  const matches = collection.items
    .filter((item) => microbiologyCanonicalRuntimeTitle(item) === canonicalTitle)
    .map((item) => ({ type: collection.type, item, targetCollection: collection.targetCollection }));
  return matches.length === 1 ? matches[0] : null;
}

let microbiologyResolvedMembershipsCache = null;
let microbiologyBrowseCandidatesCache = null;

function microbiologyResolvedMemberships() {
  if (microbiologyResolvedMembershipsCache) return microbiologyResolvedMembershipsCache;
  microbiologyResolvedMembershipsCache = (Array.isArray(microbiologyDatabase.memberships) ? microbiologyDatabase.memberships : [])
    .map((membership) => ({ membership, candidate: resolveMicrobiologyRuntimeTarget(membership) }))
    .filter((record) => record.candidate?.item);
  return microbiologyResolvedMembershipsCache;
}

function microbiologyBrowseCandidates() {
  if (microbiologyBrowseCandidatesCache) return microbiologyBrowseCandidatesCache;
  const resolvedMemberships = microbiologyResolvedMemberships();
  const output = [];
  const seenByType = new Map();
  microbiologyRuntimeCollections().forEach((collection) => {
    collection.items.forEach((item) => {
      const memberships = resolvedMemberships
        .filter((record) => record.candidate.type === collection.type && record.candidate.item === item)
        .map((record) => record.membership);
      const microbiologyOwned = collection.targetCollection === "clinicalReferenceEntries"
        && microbiologyReferenceEntries.includes(item)
        && isMicrobiologyReferenceEntry(item);
      if (!memberships.length && !microbiologyOwned) return;
      if (!seenByType.has(collection.type)) seenByType.set(collection.type, new Set());
      if (seenByType.get(collection.type).has(item)) return;
      seenByType.get(collection.type).add(item);
      output.push({ type: collection.type, item, memberships });
    });
  });
  microbiologyBrowseCandidatesCache = output;
  return microbiologyBrowseCandidatesCache;
}

function microbiologyBranchIdsForValue(value = {}) {
  const domainRecords = Array.isArray(value.encyclopediaDomains) ? value.encyclopediaDomains : [];
  return [
    value.branchId,
    value.gateway,
    value.browse?.branchId,
    value.microbiology?.browse?.branchId,
    ...(Array.isArray(value.browse?.path) ? value.browse.path : []),
    ...domainRecords.map((domain) => domain && typeof domain === "object" ? domain.branchId : "")
  ].map((entry) => safeText(entry)).filter(Boolean);
}

function microbiologyCandidateMatchesBrowseBranch(candidate = {}, branchId = activeMicrobiologyBrowseBranch) {
  if (!branchId || branchId === "all") return true;
  const candidateBranchIds = [
    ...microbiologyBranchIdsForValue(candidate.item),
    ...(candidate.memberships || []).flatMap((membership) => microbiologyBranchIdsForValue(membership))
  ];
  return candidateBranchIds.some((candidateBranchId) => candidateBranchId === branchId || candidateBranchId.startsWith(`${branchId}/`));
}

function updateMicrobiologyBrowseUi() {
  if (!microbiologyBrowseControls || !microbiologyBranchSelect) return;
  const active = activePharmIndexMode === "microbiology";
  microbiologyBrowseControls.hidden = !active;
  if (!active) return;

  const branches = microbiologyBrowseBranches();
  const validBranchIds = new Set(["all", ...branches.map((branch) => branch.id)]);
  if (!validBranchIds.has(activeMicrobiologyBrowseBranch)) {
    activeMicrobiologyBrowseBranch = "all";
    localStorage.setItem(MICROBIOLOGY_BROWSE_BRANCH_KEY, activeMicrobiologyBrowseBranch);
  }
  const candidates = microbiologyBrowseCandidates();
  microbiologyBranchSelect.textContent = "";
  const allOption = document.createElement("option");
  allOption.value = "all";
  allOption.textContent = `All Microbiology branches (${candidates.length})`;
  microbiologyBranchSelect.append(allOption);
  branches.forEach((branch) => {
    const option = document.createElement("option");
    const count = candidates.filter((candidate) => microbiologyCandidateMatchesBrowseBranch(candidate, branch.id)).length;
    option.value = branch.id;
    option.textContent = `${branch.depth ? `${"— ".repeat(branch.depth)}` : ""}${branch.label} (${count})`;
    microbiologyBranchSelect.append(option);
  });
  microbiologyBranchSelect.value = activeMicrobiologyBrowseBranch;
  if (microbiologyBrowseCount) {
    const visible = candidates.filter((candidate) => microbiologyCandidateMatchesBrowseBranch(candidate)).length;
    const ownedCount = microbiologyReferenceEntries.length;
    microbiologyBrowseCount.textContent = candidates.length
      ? `${visible} of ${candidates.length} Microbiology browse entries; ${ownedCount} Microbiology-owned`
      : `${ownedCount} production Microbiology entries; ${microbiologyArchitectureStatus()}`;
  }
}

function renderMicrobiologyArchitecturePanel() {
  const panel = document.createElement("section");
  panel.className = "pharm-pathology-index pharm-microbiology-index";
  panel.setAttribute("aria-label", "Microbiology architecture and browse status");
  const heading = document.createElement("strong");
  const candidates = microbiologyBrowseCandidates();
  heading.textContent = candidates.length ? "Microbiology browse" : "Microbiology architecture ready";
  const status = document.createElement("p");
  status.textContent = candidates.length
    ? `${candidates.length} canonical Microbiology or federated entries are available. Typing in the search box still searches the complete encyclopedia.`
    : `Content expansion status: ${microbiologyArchitectureStatus()}. There are 0 production Microbiology entries; no organism cards have been published.`;
  const branchHeading = document.createElement("strong");
  const selectedBranchLabel = activeMicrobiologyBrowseBranch === "all"
    ? "All canonical branches"
    : microbiologyBrowseBranches().find((branch) => branch.id === activeMicrobiologyBrowseBranch)?.label || activeMicrobiologyBrowseBranch;
  branchHeading.textContent = `Showing: ${selectedBranchLabel}`;
  const branchHint = document.createElement("p");
  branchHint.textContent = "Use the branch selector above to narrow the cards. Empty branches remain visible there so future expansion has one stable home.";
  panel.append(heading, status, branchHeading, branchHint);
  return panel;
}

function renderMicrobiologyArchitectureDetail() {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  setPharmDetailTheme("microbiology");
  const candidates = microbiologyBrowseCandidates();
  const ownedCount = microbiologyReferenceEntries.length;
  const organismCount = microbiologyReferenceEntries.filter((entry) => entry.microbiology?.entryKind === "organism").length;
  const title = document.createElement("div");
  title.className = "pharm-detail-title pharm-microbiology-title";
  const name = document.createElement("h2");
  name.textContent = "Microbiology";
  const status = document.createElement("span");
  status.textContent = microbiologyArchitectureStatus();
  title.append(name, status);
  const note = document.createElement("p");
  note.textContent = candidates.length
    ? `${ownedCount} reviewed Microbiology cards are available, including ${organismCount} ${organismCount === 1 ? "organism profile" : "organism profiles"}. Choose a canonical branch to browse them, or type an organism, alias, disease, toxin, transmission route, or precaution in the search box.`
    : "The browse architecture is installed, but no production Microbiology entries or organism cards are published. Choose a canonical branch to inspect its current count, or type a query to search the complete encyclopedia.";
  pharmDrugDetail.append(title, note);
  syncPharmDetailReadableText();
}

function clinicalSignBrowseFacets(entry = {}) {
  if (!isClinicalSignReferenceEntry(entry)) return [];
  const facets = [];
  const specialties = [entry.specialty, ...(entry.specialties || [])].map((value) => safeText(value).trim()).filter(Boolean);
  specialties.forEach((value) => facets.push({ value: `specialty:${normalizePharmText(value)}`, label: value, group: "Specialty" }));
  [entry.bodySystem, entry.system]
    .map((value) => safeText(value).trim())
    .filter(Boolean)
    .forEach((value) => facets.push({ value: `body-system:${normalizePharmText(value)}`, label: value, group: "Body system" }));
  if (!specialties.length) {
    const category = safeText(entry.category).split("/").map((value) => value.trim()).filter(Boolean).pop();
    if (category) facets.push({ value: `category:${normalizePharmText(category)}`, label: category, group: "Category" });
  }
  return facets.filter((facet, index, all) => all.findIndex((candidate) => candidate.value === facet.value) === index);
}

function clinicalSignMatchesBrowseFacet(entry = {}) {
  return activeClinicalSignBrowseFacet === "all"
    || clinicalSignBrowseFacets(entry).some((facet) => facet.value === activeClinicalSignBrowseFacet);
}

function clinicalSignBrowseCatalog() {
  if (clinicalSignBrowseCatalogCache) return clinicalSignBrowseCatalogCache;
  const groups = new Map();
  clinicalReferenceEntries.filter(isClinicalSignReferenceEntry).forEach((entry) => {
    clinicalSignBrowseFacets(entry).forEach((facet) => {
      if (!groups.has(facet.group)) groups.set(facet.group, new Map());
      const group = groups.get(facet.group);
      if (!group.has(facet.value)) group.set(facet.value, { ...facet, count: 0 });
      group.get(facet.value).count += 1;
    });
  });
  clinicalSignBrowseCatalogCache = groups;
  return clinicalSignBrowseCatalogCache;
}

function updateClinicalSignBrowseUi() {
  if (!clinicalSignBrowseControls || !clinicalSignSpecialtySelect) return;
  const active = activePharmIndexMode === "clinical-signs";
  clinicalSignBrowseControls.hidden = !active;
  if (!active) return;
  const catalog = clinicalSignBrowseCatalog();
  const validValues = new Set(["all"]);
  if (!clinicalSignBrowseOptionsReady) {
    clinicalSignSpecialtySelect.textContent = "";
    const allOption = document.createElement("option");
    allOption.value = "all";
    allOption.textContent = "All specialties and body systems";
    clinicalSignSpecialtySelect.append(allOption);
  }
  ["Specialty", "Body system", "Category"].forEach((groupName) => {
    const facets = Array.from(catalog.get(groupName)?.values() || [])
      .sort((a, b) => a.label.localeCompare(b.label));
    if (!facets.length) return;
    facets.forEach((facet) => validValues.add(facet.value));
    if (clinicalSignBrowseOptionsReady) return;
    const optgroup = document.createElement("optgroup");
    optgroup.label = groupName;
    facets.forEach((facet) => {
      const option = document.createElement("option");
      option.value = facet.value;
      option.textContent = `${facet.label} (${facet.count})`;
      optgroup.append(option);
    });
    clinicalSignSpecialtySelect.append(optgroup);
  });
  clinicalSignBrowseOptionsReady = true;
  if (!validValues.has(activeClinicalSignBrowseFacet)) {
    activeClinicalSignBrowseFacet = "all";
    localStorage.setItem(CLINICAL_SIGN_BROWSE_FACET_KEY, activeClinicalSignBrowseFacet);
  }
  clinicalSignSpecialtySelect.value = activeClinicalSignBrowseFacet;
  if (clinicalSignBrowseCount) {
    const total = clinicalReferenceEntries.filter(isClinicalSignReferenceEntry).length;
    const visible = clinicalReferenceEntries.filter((entry) => isClinicalSignReferenceEntry(entry) && clinicalSignMatchesBrowseFacet(entry)).length;
    clinicalSignBrowseCount.textContent = activeClinicalSignBrowseFacet === "all"
      ? `${total} signs in the alphabetical index`
      : `${visible} of ${total} signs; searching still checks every specialty`;
  }
}

function foundationBrowseDomain(entry = {}) {
  if (entry.type !== "foundation" && entry.educationalArticle !== true) return "";
  return safeText(entry.foundationDomain || entry.learningDomain || entry.category || "General foundations").trim();
}

function foundationMatchesBrowseDomain(entry = {}, domain = activeFoundationBrowseDomain) {
  if (!domain || domain === "all") return true;
  return normalizePharmText(foundationBrowseDomain(entry)) === domain;
}

function updateFoundationBrowseUi() {
  if (!foundationBrowseControls || !foundationDomainSelect) return;
  const active = activePharmIndexMode === "foundations";
  foundationBrowseControls.hidden = !active;
  if (!active) return;
  const entries = clinicalReferenceEntries.filter((entry) => (entry.type === "foundation" || entry.educationalArticle === true)
    && !isMicrobiologyReferenceEntry(entry)
    && !isHolisticClinicalReferenceEntry(entry));
  const domainCounts = new Map();
  entries.forEach((entry) => {
    const label = foundationBrowseDomain(entry);
    const value = normalizePharmText(label);
    if (!value) return;
    const current = domainCounts.get(value) || { label, count: 0 };
    current.count += 1;
    domainCounts.set(value, current);
  });
  const validValues = new Set(["all", ...domainCounts.keys()]);
  if (!validValues.has(activeFoundationBrowseDomain)) {
    activeFoundationBrowseDomain = "all";
    localStorage.setItem(FOUNDATION_BROWSE_DOMAIN_KEY, activeFoundationBrowseDomain);
  }
  if (!foundationBrowseOptionsReady) {
    foundationDomainSelect.textContent = "";
    const allOption = document.createElement("option");
    allOption.value = "all";
    allOption.textContent = `All Foundation domains (${entries.length})`;
    foundationDomainSelect.append(allOption);
    Array.from(domainCounts.entries())
      .sort((a, b) => a[1].label.localeCompare(b[1].label))
      .forEach(([value, record]) => {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = `${record.label} (${record.count})`;
        foundationDomainSelect.append(option);
      });
    foundationBrowseOptionsReady = true;
  }
  foundationDomainSelect.value = activeFoundationBrowseDomain;
  if (foundationBrowseCount) {
    const visible = entries.filter((entry) => foundationMatchesBrowseDomain(entry)).length;
    foundationBrowseCount.textContent = activeFoundationBrowseDomain === "all"
      ? `${entries.length} foundations in the alphabetical index`
      : `${visible} of ${entries.length} foundations; searching still checks every domain`;
  }
}

function holisticSubcategoryLabel(subcategory = activeHolisticBrowseSubcategory) {
  return HOLISTIC_BROWSE_SUBCATEGORIES.find((record) => record.id === subcategory)?.label
    || HOLISTIC_BROWSE_SUBCATEGORIES[0].label;
}

function updateHolisticBrowseUi() {
  if (!holisticBrowseControls || !holisticSubcategorySelect) return;
  const active = activePharmIndexMode === "holistic";
  holisticBrowseControls.hidden = !active;
  if (!active) return;
  const validValues = new Set(HOLISTIC_BROWSE_SUBCATEGORIES.map((record) => record.id));
  if (!validValues.has(activeHolisticBrowseSubcategory)) {
    activeHolisticBrowseSubcategory = "all";
    localStorage.setItem(HOLISTIC_BROWSE_SUBCATEGORY_KEY, activeHolisticBrowseSubcategory);
  }
  holisticSubcategorySelect.value = activeHolisticBrowseSubcategory;
  if (holisticBrowseCount) {
    const allCount = holisticVisibleBrowseCandidates({ subcategory: "all", letter: "All" }).length;
    const visibleCount = holisticVisibleBrowseCandidates({ letter: "All" }).length;
    const filterLabel = activePharmNclexOnly ? " NCLEX Essential" : "";
    holisticBrowseCount.textContent = activeHolisticBrowseSubcategory === "all"
      ? `${allCount}${filterLabel} Holistic ${allCount === 1 ? "topic" : "topics"} in the alphabetical index`
      : `${visibleCount} of ${allCount}${filterLabel} Holistic topics; searching still checks the complete encyclopedia`;
  }
}

function surgeryProcedureBrowseLabel(entry = {}) {
  const categoryLabel = safeText(entry.category).replace(/^Surgeries\s*&\s*Procedures\s*\/\s*/i, "");
  return safeText(entry.browse?.label || entry.procedure?.primaryBranchLabel || categoryLabel || "General procedures").trim();
}

function surgeryProcedureBrowseValue(entry = {}) {
  return safeText(entry.procedure?.primaryBranchId || entry.browse?.branchId || normalizePharmText(surgeryProcedureBrowseLabel(entry))).trim();
}

function surgeryProcedureMatchesBrowseSpecialty(entry = {}, specialty = activeSurgeryProcedureBrowseSpecialty) {
  if (!specialty || specialty === "all") return true;
  const branchIds = [
    surgeryProcedureBrowseValue(entry),
    ...(Array.isArray(entry.browse?.branchIds) ? entry.browse.branchIds : []),
    ...(Array.isArray(entry.procedure?.browseBranchIds) ? entry.procedure.browseBranchIds : [])
  ].map((value) => safeText(value)).filter(Boolean);
  return branchIds.includes(specialty);
}

function updateSurgeryProcedureBrowseUi() {
  if (!procedureBrowseControls || !procedureSpecialtySelect) return;
  const active = activePharmIndexMode === "surgeries";
  procedureBrowseControls.hidden = !active;
  if (!active) return;
  const entries = clinicalReferenceEntries.filter(isSurgeryProcedureReferenceEntry);
  const specialtyCounts = new Map();
  entries.forEach((entry) => {
    const value = surgeryProcedureBrowseValue(entry);
    const label = surgeryProcedureBrowseLabel(entry);
    if (!value) return;
    const current = specialtyCounts.get(value) || { label, count: 0 };
    current.count += 1;
    specialtyCounts.set(value, current);
  });
  const validValues = new Set(["all", ...specialtyCounts.keys()]);
  if (!validValues.has(activeSurgeryProcedureBrowseSpecialty)) {
    activeSurgeryProcedureBrowseSpecialty = "all";
    localStorage.setItem(SURGERY_PROCEDURE_BROWSE_SPECIALTY_KEY, activeSurgeryProcedureBrowseSpecialty);
  }
  if (!surgeryProcedureBrowseOptionsReady) {
    procedureSpecialtySelect.textContent = "";
    const allOption = document.createElement("option");
    allOption.value = "all";
    allOption.textContent = `All procedure specialties (${entries.length})`;
    procedureSpecialtySelect.append(allOption);
    Array.from(specialtyCounts.entries())
      .sort((a, b) => a[1].label.localeCompare(b[1].label))
      .forEach(([value, record]) => {
        const option = document.createElement("option");
        option.value = value;
        option.textContent = `${record.label} (${record.count})`;
        procedureSpecialtySelect.append(option);
      });
    surgeryProcedureBrowseOptionsReady = true;
  }
  procedureSpecialtySelect.value = activeSurgeryProcedureBrowseSpecialty;
  if (procedureBrowseCount) {
    const visible = entries.filter((entry) => surgeryProcedureMatchesBrowseSpecialty(entry)).length;
    procedureBrowseCount.textContent = activeSurgeryProcedureBrowseSpecialty === "all"
      ? `${entries.length} surgeries and procedures in the alphabetical index`
      : `${visible} of ${entries.length} procedures; searching still checks every specialty`;
  }
}

function clinicalReferenceMatchesActiveMode(entry = {}) {
  const isClinicalSign = isClinicalSignReferenceEntry(entry);
  const isMicrobiology = isMicrobiologyReferenceEntry(entry);
  const isSurgeryProcedure = isSurgeryProcedureReferenceEntry(entry);
  if (activePharmIndexMode === "procedures") return entry.type !== "foundation" && !isClinicalSign && !isMicrobiology && !isSurgeryProcedure;
  if (activePharmIndexMode === "surgeries") return isSurgeryProcedure && surgeryProcedureMatchesBrowseSpecialty(entry);
  if (activePharmIndexMode === "foundations") return entry.type === "foundation" && !isMicrobiology && !isHolisticClinicalReferenceEntry(entry) && foundationMatchesBrowseDomain(entry);
  if (activePharmIndexMode === "clinical-signs") return isClinicalSign && clinicalSignMatchesBrowseFacet(entry);
  if (activePharmIndexMode === "holistic") {
    const candidate = { type: "reference", item: entry };
    return isHolisticClinicalReferenceEntry(entry)
      && holisticCandidateMatchesBrowseSubcategory(candidate)
      && (!activePharmNclexOnly || isNclexEssentialEncyclopediaEntry(candidate.type, entry));
  }
  if (activePharmIndexMode === "microbiology") {
    return microbiologyBrowseCandidates()
      .some((candidate) => candidate.type === "reference" && candidate.item === entry && microbiologyCandidateMatchesBrowseBranch(candidate));
  }
  return true;
}

function searchClinicalReferenceEntries(query = "", letter = activePharmLetter) {
  const cleanQuery = normalizePharmText(applyClinicalSpeechFixups(query) || query);
  const byLetter = letter && letter !== "All"
    ? clinicalReferenceEntries.filter((entry) => safeText(entry.name).toUpperCase().startsWith(letter))
    : clinicalReferenceEntries;
  if (!cleanQuery) return byLetter.filter((entry) => clinicalReferenceMatchesActiveMode(entry));
  const indirectCoombsPriority = /\b(indirect coombs|indirect antiglobulin|iat|antibody screen)\b/i.test(cleanQuery)
    ? byLetter.find((entry) => normalizePharmText(clinicalReferenceDisplayName(entry)).startsWith("indirect coombs"))
    : null;
  // Category modes scope browsing only. Once the user types a query, search the
  // complete reference index so a persisted mode cannot hide an exact match.
  const candidates = indexedEncyclopediaSearchPool("reference", byLetter, query);
  const ranked = candidates
    .map((entry) => ({ entry, score: scoreClinicalReferenceEntry(entry, query) }))
    .filter(({ score }) => score >= 14)
    .sort((a, b) => b.score - a.score || safeText(a.entry.name).localeCompare(safeText(b.entry.name)))
    .map(({ entry }) => entry);
  return indirectCoombsPriority
    ? [indirectCoombsPriority, ...ranked.filter((entry) => entry !== indirectCoombsPriority)]
    : ranked;
}

function bestClinicalReferenceMatch(input = "", options = {}) {
  const type = safeText(options.type);
  const candidates = clinicalReferenceEntries
    .filter((entry) => !type || entry.type === type)
    .map((entry) => ({ entry, score: scoreClinicalReferenceEntry(entry, input) }))
    .sort((a, b) => b.score - a.score || safeText(a.entry.name).localeCompare(safeText(b.entry.name)));
  return candidates[0]?.score >= 75 ? candidates[0].entry : null;
}

function pathologyEntryTerms(disease = {}) {
  const cached = pathologyEntryTermCache.get(disease);
  if (cached) return cached;
  const terms = [
    disease.name,
    disease.category,
    disease.pathology,
    disease.pathophysiology,
    disease.etiology,
    ...(disease.aliases || []),
    ...(disease.abbreviations || []),
    ...(disease.commonMisspellings || []),
    ...(disease.riskFactors || []),
    ...(disease.signsSymptoms || []),
    ...(disease.diagnostics || []),
    ...(disease.treatments || []),
    ...(disease.contraindications || []),
    ...(disease.nursingPriorities || []),
    ...(disease.complications || []),
    ...(disease.patientEducation || []),
    ...(disease.nclexTraps || []),
    ...(disease.relatedTopics || []),
    ...(disease.tags || [])
  ]
    .flatMap((term) => Array.isArray(term) ? term : [term])
    .map((term) => normalizePharmText(term))
    .filter(Boolean);
  pathologyEntryTermCache.set(disease, terms);
  return terms;
}

function primaryPathologyNameScore(term = "", variant = "", exactScore = 260, prefixScore = 130, containsScore = 62) {
  const cleanTerm = normalizePharmText(term);
  const cleanVariant = normalizePharmText(variant);
  if (!cleanTerm || !cleanVariant) return 0;
  const variantTokens = cleanVariant.split(" ").filter(Boolean);
  const termTokens = cleanTerm.split(" ").filter(Boolean);
  if (cleanTerm.length < 4) {
    if (variantTokens.includes(cleanTerm)) return exactScore;
    return 0;
  }
  if (cleanTerm === cleanVariant) return exactScore;
  if (cleanVariant.includes(cleanTerm)) {
    return termTokens.length > 1 ? exactScore + 90 : containsScore + 10;
  }
  if (cleanTerm.startsWith(cleanVariant)) return prefixScore;
  if (cleanVariant.length >= 4 && (cleanTerm.includes(cleanVariant) || variantTokens.some((token) => token.length >= 4 && termTokens.some((word) => word.startsWith(token))))) {
    return containsScore;
  }
  return 0;
}

function scorePathologyEntry(disease = {}, query = "") {
  const cleanQuery = normalizePharmText(query);
  const lookupQuery = normalizeOfflineLookupText(query);
  if (!cleanQuery && !lookupQuery) return 1;
  const terms = pathologyEntryTerms(disease);
  const queryTokens = (lookupQuery || cleanQuery).split(" ").filter((token) => token.length > 1);
  const primaryNames = [disease.name, ...(disease.aliases || [])].map((term) => normalizePharmText(term)).filter(Boolean);
  const primaryLookupNames = [disease.name, ...(disease.aliases || [])]
    .map((term) => normalizeOfflineLookupText(term, { dropLookupWords: false }))
    .filter(Boolean);
  const queryVariants = Array.from(new Set([cleanQuery, lookupQuery].filter(Boolean)));
  const diseaseName = normalizePharmText(disease.name);
  const diseaseLookupName = normalizeOfflineLookupText(disease.name, { dropLookupWords: false });
  let score = 0;

  if (queryVariants.some((variant) => variant === diseaseName || variant === diseaseLookupName)) {
    score += 720;
  } else if (queryVariants.some((variant) => primaryNames.includes(variant) || primaryLookupNames.includes(variant))) {
    score += 320;
  }

  primaryNames.forEach((term) => {
    queryVariants.forEach((variant) => {
      score += primaryPathologyNameScore(term, variant);
    });
  });

  primaryLookupNames.forEach((term) => {
    queryVariants.forEach((variant) => {
      const lookupVariant = normalizeOfflineLookupText(variant, { dropLookupWords: false });
      score += primaryPathologyNameScore(term, lookupVariant);
    });
  });

  queryTokens.forEach((token) => {
    if ([...primaryNames, ...primaryLookupNames].some((term) => term.split(" ").some((word) => word.startsWith(token)))) {
      score += 14;
    }
  });

  terms.forEach((term) => {
    if (term === cleanQuery) score += 90;
    else if (pharmTermContainsQuery(term, cleanQuery)) score += 38;
    else if (cleanQuery.includes(term) && term.length >= 4) score += 24;
  });

  queryTokens.forEach((token) => {
    score += Math.max(...terms.map((term) => pharmTokenCloseness(token, term)), 0);
    if (token.length >= 4 && terms.some((term) => term.includes(token))) {
      score += 3;
    }
  });

  score += scoreDescriptionMatch("pathology", disease, query);

  return score;
}

function searchPathologyEntries(query = "", letter = activePharmLetter) {
  if (wantsMedicationClassLookup(query)) return [];
  const fixedQuery = applyClinicalSpeechFixups(query) || query;
  const searchQuery = normalizeOfflineLookupText(fixedQuery) || fixedQuery;
  const cleanQuery = normalizePharmText(searchQuery);
  const byLetter = letter && letter !== "All"
    ? pathologyDiseases.filter((disease) => safeText(disease.name).toUpperCase().startsWith(letter))
    : pathologyDiseases;
  if (!cleanQuery) return byLetter;
  const registeredExactPathology = letter && letter !== "All" ? null : exactRegisteredPathologyIdentityMatch(fixedQuery);
  if (registeredExactPathology && byLetter.includes(registeredExactPathology)) {
    return [registeredExactPathology];
  }
  const priorityPathology = wantsLiverDamageProgression(fixedQuery) ? liverDamageProgressionCard() : null;
  const priorityDiabetesPathology = letter && letter !== "All"
    ? null
    : wave41DiabetesPathologyIntentSuggestion(fixedQuery)?.item || null;
  const candidates = indexedEncyclopediaSearchPool("pathology", byLetter, fixedQuery);

  const results = candidates
    .map((disease) => ({
      disease,
      score: scorePathologyEntry(disease, cleanQuery)
    }))
    .filter((entry) => entry.score >= 7)
    .sort((a, b) => b.score - a.score || safeText(a.disease.name).localeCompare(safeText(b.disease.name)))
    .map((entry) => entry.disease);
  const priorityCandidates = [priorityDiabetesPathology, priorityPathology]
    .filter((disease, index, values) => disease && byLetter.includes(disease) && values.indexOf(disease) === index);
  if (priorityCandidates.length) {
    return [...priorityCandidates, ...results.filter((disease) => !priorityCandidates.includes(disease))];
  }
  return results;
}

function holisticListText(items = []) {
  return Array.isArray(items) ? readableListText(items) : softenSemicolonProse(safeText(items));
}

function normalizeHolisticSearchText(value = "") {
  let clean = normalizePharmText(value);
  [
    [/\bst\s+joh\s+s\s+wart\b/g, "st johns wort"],
    [/\bst\s+johs?\s+wart\b/g, "st johns wort"],
    [/\bst\s+john\s+s\s+wart\b/g, "st johns wort"],
    [/\bst\s+johns?\s+wart\b/g, "st johns wort"],
    [/\bsaint\s+joh\s+s\s+wart\b/g, "saint johns wort"],
    [/\bsaint\s+johs?\s+wart\b/g, "saint johns wort"],
    [/\bsaint\s+john\s+s\s+wart\b/g, "saint johns wort"],
    [/\bsaint\s+johns?\s+wart\b/g, "saint johns wort"],
    [/\bst\s+joh\s+s\s+wort\b/g, "st johns wort"],
    [/\bst\s+johs?\s+wort\b/g, "st johns wort"],
    [/\bst\s+john\s+s\s+wort\b/g, "st johns wort"],
    [/\bst\s+john\s+wort\b/g, "st johns wort"],
    [/\bsaint\s+john\s+wort\b/g, "saint johns wort"]
  ].forEach(([pattern, replacement]) => {
    clean = clean.replace(pattern, replacement);
  });
  return clean.replace(/\s+/g, " ").trim();
}

function holisticSourceLabels(remedy = {}) {
  const keys = Array.isArray(remedy.sourceKeys) ? remedy.sourceKeys : [];
  return readableListText(keys
    .map((key) => holisticDatabase.sourceReferences?.find((source) => source.key === key)?.label || key)
    .filter(Boolean));
}

function holisticEntryTerms(remedy = {}) {
  const cached = holisticEntryTermCache.get(remedy);
  if (cached) return cached;
  const terms = [
    remedy.name,
    remedy.category,
    remedy.mechanism,
    ...(remedy.aliases || []),
    ...(remedy.usedFor || []),
    ...(remedy.majorRisks || []),
    ...(remedy.interactions || []),
    ...(remedy.contraindications || []),
    ...(remedy.nursingAssessment || []),
    ...(remedy.teaching || []),
    ...(remedy.nclexTraps || []),
    ...(remedy.tags || []),
    ...((remedy.populationRisks || []).flatMap((risk) => [risk.type, risk.label, risk.note]))
  ]
    .map((term) => normalizeHolisticSearchText(term))
    .filter(Boolean);
  holisticEntryTermCache.set(remedy, terms);
  return terms;
}

function scoreHolisticEntry(remedy = {}, query = "") {
  const cleanQuery = normalizeHolisticSearchText(query);
  if (!cleanQuery) return 1;
  const terms = holisticEntryTerms(remedy);
  const queryTokens = cleanQuery.split(" ").filter((token) => token.length > 1);
  const primaryNames = [remedy.name, ...(remedy.aliases || [])].map((term) => normalizeHolisticSearchText(term)).filter(Boolean);
  let score = 0;

  primaryNames.forEach((term) => {
    if (term === cleanQuery) {
      score += 260;
    } else if (term.startsWith(cleanQuery)) {
      score += 135;
    } else if (cleanQuery.length >= 4 && (term.includes(cleanQuery) || cleanQuery.includes(term))) {
      score += 68;
    }
  });

  queryTokens.forEach((token) => {
    if (primaryNames.some((term) => term.split(" ").some((word) => word.startsWith(token)))) {
      score += 16;
    }
  });

  terms.forEach((term) => {
    if (term === cleanQuery) score += 90;
    else if (pharmTermContainsQuery(term, cleanQuery)) score += 40;
    else if (cleanQuery.includes(term) && term.length >= 4) score += 26;
  });

  queryTokens.forEach((token) => {
    score += Math.max(...terms.map((term) => pharmTokenCloseness(token, term)), 0);
    if (token.length >= 4 && terms.some((term) => term.includes(token))) {
      score += 4;
    }
  });

  score += scoreDescriptionMatch("holistic", remedy, query);

  return score;
}

function searchHolisticEntries(query = "", letter = activePharmLetter) {
  if (wantsMedicationClassLookup(query)) return [];
  const fixedQuery = applyClinicalSpeechFixups(query) || query;
  const searchQuery = normalizeOfflineLookupText(fixedQuery) || fixedQuery;
  const cleanQuery = normalizeHolisticSearchText(searchQuery);
  const byLetter = letter && letter !== "All"
    ? holisticRemedies.filter((remedy) => safeText(remedy.name).toUpperCase().startsWith(letter))
    : holisticRemedies;
  if (!cleanQuery) return byLetter;
  const candidates = indexedEncyclopediaSearchPool("holistic", byLetter, fixedQuery);

  return candidates
    .map((remedy) => ({
      remedy,
      score: scoreHolisticEntry(remedy, cleanQuery)
    }))
    .filter((entry) => entry.score >= 7)
    .sort((a, b) => b.score - a.score || safeText(a.remedy.name).localeCompare(safeText(b.remedy.name)))
    .map((entry) => entry.remedy);
}

function isMetforminMechanismRiskTeachingQuery(input = "") {
  const text = normalizePharmText(applyMedicationSpellingFixups(applyClinicalSpeechFixups(input) || input));
  if (!/\b(metformin|glucophage|biguanide)\b/i.test(text)) return false;
  if (/\b(poison(?:ed|ing)?|toxicity|toxic|overdose|overdosed|mala|mila|rescue|dialysis|extracorporeal|ectr|extrip|shock|severe acidemia)\b/i.test(text)) return false;
  const teachingCue = /\b(which|what|why|how|mechanism|lowers?|reduces?|inhibits?|hepatic glucose|liver glucose|gluconeogenesis|diabetes drug|adverse effect|risk)\b/i.test(text);
  const riskCue = /\b(lactic acidosis|lactate|kidney failure|renal failure|kidney disease|renal impairment)\b/i.test(text);
  return teachingCue && riskCue;
}

function isTheophyllineRiskTeachingQuery(input = "") {
  const text = normalizePharmText(applyMedicationSpellingFixups(applyClinicalSpeechFixups(input) || input));
  if (!/\b(theophylline|theophyline|aminophylline|methylxanthine|theo 24|uniphyl|elixophyllin)\b/i.test(text)) return false;
  if (/\b(poison(?:ed|ing)?|overdose|overdosed|rescue|dialysis|extracorporeal|ectr|extrip)\b/i.test(text)) return false;
  const levelTeachingCue = /\b(narrow therapeutic index|therapeutic drug monitoring|therapeutic level|serum level|after stopping (?:smoking|cigarettes?)|smoking cessation|cigarettes?|tobacco|cyp1a2|ciprofloxacin|fluoroquinolone|fever)\b/i.test(text);
  if (!levelTeachingCue) return false;
  if (!/\b(toxicity|toxic)\b/i.test(text)) return true;
  return /\b(after|because|interaction|interactions|raises?|increases?|level|levels|fever|ciprofloxacin|cyp1a2|smoking|cigarettes?|risk)\b/i.test(text);
}

function isBetaLactamValproateTeachingQuery(input = "") {
  const text = normalizePharmText(applyMedicationSpellingFixups(applyClinicalSpeechFixups(input) || input));
  return /\b(penicillin|cephalosporin|carbapenem|beta lactam|meropenem|imipenem|ertapenem|doripenem)\b/i.test(text)
    && /\b(valproate|valproic acid|depakote|divalproex)\b/i.test(text)
    && /\b(why|interaction|level|levels|seizure|neurotoxicity|clearance|concentration)\b/i.test(text)
    && !/\b(valproate poisoning|valproic acid poisoning|depakote overdose|divalproex overdose|rescue|dialysis|extracorporeal|ectr|extrip)\b/i.test(text);
}

function isDimercaprolAntidoteQuery(input = "") {
  const text = normalizePharmText(applyMedicationSpellingFixups(applyClinicalSpeechFixups(input) || input));
  return /\b(dimercaprol|british anti lewisite|bal)\b/i.test(text)
    && /\b(antidote|chelat|arsenic|mercury|lewisite|metal poisoning)\b/i.test(text);
}

function searchPharmEntries(query = "", letter = activePharmLetter) {
  const fixedQuery = applyClinicalSpeechFixups(query) || query;
  const searchQuery = normalizeOfflineLookupText(fixedQuery) || fixedQuery;
  const cleanQuery = normalizePharmText(searchQuery);
  const drugPool = activePharmDrugPool();
  const byLetter = letter && letter !== "All"
    ? drugPool.filter((drug) => pharmDrugDisplayName(drug).toUpperCase().startsWith(letter))
    : drugPool;

  if (!cleanQuery) {
    return byLetter;
  }
  if (PHARM_FALSE_BETA_BLOCKER_TEMPLATE_NAMES.has(cleanQuery)) {
    return [];
  }
  const explicitNonDrugReferenceQuery = /\b(sign|maneuver|bedside finding|physical exam|examination finding|test|imaging sign)\b/i.test(fixedQuery)
    && !/\b(drug|medication|medicine|pharmacy|pharmacology|treat(?:s|ed|ment)?|therapy|antidote)\b/i.test(fixedQuery);
  if (explicitNonDrugReferenceQuery) return [];
  const initialFastDrugCandidates = collectFastLookupCandidates(searchQuery, ["drug"])
    .filter((candidate) => candidate.type === "drug")
    .map((candidate) => candidate.item);
  const meaningfulDrugQueryTokens = cleanQuery
    .split(" ")
    .filter((token) => token.length >= 3 && !FAST_LOOKUP_STOP_WORDS.has(token));
  if (!initialFastDrugCandidates.length && meaningfulDrugQueryTokens.length && !wantsMedicationClassLookup(searchQuery)) {
    return [];
  }

  // exact-primary-class-title-precedence
  const exactPrimaryClassQuery = normalizePharmText(fixedQuery);
  const exactPrimaryClassCard = byLetter.find((drug) => isMedicationClassCardEntry(drug) && [
    pharmDrugDisplayName(drug, ""), drug.name, drug.generic, drug.displayName
  ].map((term) => normalizePharmText(term)).includes(exactPrimaryClassQuery));
  const exactClassCandidate = exactPrimaryClassCard || exactMedicationClassCardMatch(searchQuery);
  const rawExactClassQuery = normalizePharmText(query);
  const exactClassPrimaryTerms = exactClassCandidate
    ? [pharmDrugDisplayName(exactClassCandidate, ""), exactClassCandidate.name, exactClassCandidate.generic, exactClassCandidate.displayName]
      .map((term) => normalizePharmText(term))
      .filter(Boolean)
    : [];
  const exactIndividualIdentityExists = byLetter.some((drug) => !isMedicationClassCardEntry(drug)
    && pharmIdentityTermsForEntry(drug).some((term) => term === cleanQuery || term === rawExactClassQuery));
  const exactClassCard = exactClassCandidate
    && !exactIndividualIdentityExists
    && (exactClassPrimaryTerms.includes(cleanQuery)
      || exactClassPrimaryTerms.includes(rawExactClassQuery)
      || wantsMedicationClassLookup(searchQuery)
      || pharmIdentityTermsForEntry(exactClassCandidate).includes(cleanQuery))
    ? exactClassCandidate
    : null;
  if (exactClassCard) {
    const classExampleTerms = [
      ...(Array.isArray(exactClassCard.classExampleKeys) ? exactClassCard.classExampleKeys : []),
      ...(Array.isArray(exactClassCard.classExampleNames) ? exactClassCard.classExampleNames : [])
    ].map((term) => normalizePharmText(term)).filter(Boolean);
    const classExampleSet = new Set(classExampleTerms);
    const classExampleOrder = new Map(classExampleTerms.map((term, index) => [term, index]));
    const exampleMatches = classExampleSet.size
      ? byLetter
        .filter((drug) => drug !== exactClassCard && !isMedicationClassCardEntry(drug))
        .map((drug) => ({
          drug,
          order: Math.min(
            ...pharmIdentityTermsForEntry(drug)
              .filter((term) => classExampleSet.has(term))
              .map((term) => classExampleOrder.get(term) ?? 999)
          )
        }))
        .filter((entry) => Number.isFinite(entry.order))
        .sort((a, b) => a.order - b.order || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
        .map((entry) => entry.drug)
      : [];
    const relatedMatches = byLetter
      .filter((drug) => drug !== exactClassCard && !exampleMatches.includes(drug) && pharmEntryCouldMatchQuery(drug, cleanQuery))
      .map((drug) => ({
        drug,
        score: scorePharmEntry(drug, cleanQuery) + (isMedicationClassCardEntry(drug) ? 280 : 0)
      }))
      .filter((entry) => entry.score >= 6)
      .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
      .slice(0, 40)
      .map((entry) => entry.drug);
    const seenClassSearch = new Set();
    return [exactClassCard, ...exampleMatches, ...relatedMatches]
      .filter((drug) => {
        const key = pharmDrugDisplayName(drug, "") || drug.name || drug.generic || drug.displayName;
        if (seenClassSearch.has(key)) return false;
        seenClassSearch.add(key);
        return true;
      });
  }

  const rawExactIdentityQueries = Array.from(new Set([
    query,
    fixedQuery,
    searchQuery
  ].map((value) => normalizePharmText(applyMedicationSpellingFixups(value))).filter(Boolean)));
  const rawExactCanonicalDrug = wantsMedicationClassLookup(searchQuery)
    ? null
    : byLetter.find((candidate) => rawExactIdentityQueries.some((identity) => [
      candidate.name,
      candidate.generic,
      candidate.displayName,
      pharmDrugDisplayName(candidate, "")
    ].map((value) => normalizePharmText(applyMedicationSpellingFixups(value))).filter(Boolean).includes(identity)));
  const matchesRawStandaloneIdentity = (candidate) => rawExactIdentityQueries.some((identity) => [
    candidate.name,
    candidate.generic,
    candidate.displayName,
    ...(candidate.brandExamples || [])
  ].map((value) => normalizePharmText(applyMedicationSpellingFixups(value))).filter(Boolean).includes(identity));
  const rawExactStandaloneDrug = wantsMedicationClassLookup(searchQuery)
    ? null
    : byLetter.find((candidate) => normalizePharmText(candidate.entryType) !== "clinical guide"
        && !isMedicationClassCardEntry(candidate)
        && matchesRawStandaloneIdentity(candidate))
      || byLetter.find((candidate) => normalizePharmText(candidate.entryType) !== "clinical guide"
        && matchesRawStandaloneIdentity(candidate));
  const rawExactIndexedDrug = wantsMedicationClassLookup(searchQuery)
    ? null
    : rawExactIdentityQueries
      .map((identity) => getPharmPrimaryIdentityExactIndex().get(identity) || getPharmIdentityExactIndex().get(identity))
      .find((candidate) => candidate && byLetter.includes(candidate));
  const metforminTeachingDrug = isMetforminMechanismRiskTeachingQuery(query)
    ? byLetter.find((candidate) => normalizePharmText(candidate.entryType) !== "clinical guide" && [
      candidate.name,
      candidate.generic,
      candidate.displayName,
      pharmDrugDisplayName(candidate, "")
    ].map((value) => normalizePharmText(value)).includes("metformin"))
    : null;
  const theophyllineTeachingDrug = isTheophyllineRiskTeachingQuery(query)
    ? byLetter.find((candidate) => normalizePharmText(candidate.entryType) !== "clinical guide" && [
      candidate.name,
      candidate.generic,
      candidate.displayName,
      pharmDrugDisplayName(candidate, "")
    ].map((value) => normalizePharmText(value)).includes("theophylline"))
    : null;
  const betaLactamValproateGuide = isBetaLactamValproateTeachingQuery(query)
    ? pharmDrugs.find((candidate) => isVisibleMedicationEntry(candidate)
      && normalizePharmText(pharmDrugDisplayName(candidate, "")) === "beta lactam renal accumulation neurotoxicity and valproate pathway")
    : null;
  const dimercaprolAntidoteDrug = isDimercaprolAntidoteQuery(query)
    ? byLetter.find((candidate) => normalizePharmText(candidate.entryType) !== "clinical guide" && [
      candidate.name,
      candidate.generic,
      candidate.displayName,
      pharmDrugDisplayName(candidate, "")
    ].map((value) => normalizePharmText(value)).includes("dimercaprol"))
    : null;
  const rawExactDrug = rawExactCanonicalDrug || rawExactStandaloneDrug || rawExactIndexedDrug;
  const exactDrug = metforminTeachingDrug || theophyllineTeachingDrug || betaLactamValproateGuide || dimercaprolAntidoteDrug || rawExactDrug || (wantsMedicationClassLookup(searchQuery) ? null : exactPharmIdentityMatch(searchQuery));
  if (exactDrug && (byLetter.includes(exactDrug) || exactDrug === betaLactamValproateGuide)) {
    const relatedMatches = byLetter
      .filter((drug) => drug !== exactDrug && pharmEntryCouldMatchQuery(drug, cleanQuery))
      .map((drug) => ({
        drug,
        score: scorePharmEntry(drug, cleanQuery)
      }))
      .filter((entry) => entry.score >= 6)
      .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
      .slice(0, 40)
      .map((entry) => entry.drug);
    return [exactDrug, ...relatedMatches];
  }

  const fastDrugCandidates = initialFastDrugCandidates;
  const byLetterSet = fastDrugCandidates.length ? new Set(byLetter) : null;
  const fastCandidates = fastDrugCandidates.length
    ? Array.from(new Set(fastDrugCandidates)).filter((drug) => byLetterSet.has(drug))
    : [];
  const candidates = fastCandidates.length
    ? fastCandidates
    : byLetter.filter((drug) => pharmEntryCouldMatchQuery(drug, cleanQuery));

  return candidates
    .map((drug) => ({
      drug,
      score: scorePharmEntry(drug, cleanQuery)
    }))
    .filter((entry) => entry.score >= 6)
    .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))
    .map((entry) => entry.drug);
}

function renderPharmLabs() {
  if (!pharmLabList) return;
  if (isPhoneDeviceMode()) {
    pharmLabList.textContent = "";
    return;
  }
  pharmLabList.textContent = "";
  const legend = renderPharmRiskLegend();
  if (legend) {
    pharmLabList.append(legend);
  }
  pharmLabList.append(renderPharmCategoryKey());
  const note = document.createElement("p");
  note.className = "pharm-reference-note";
  note.textContent = "Use the clinical index and search to open full lab, pharmacy, pathology, anatomy/physiology, diagnostic, and holistic entries. This column only explains visual cues.";
  pharmLabList.append(note);
}

function renderPharmAlphabet() {
  if (!pharmAlphabetStrip) return;
  updatePharmIndexModeUi();
  pharmAlphabetStrip.textContent = "";
  pharmAlphabetStrip.hidden = pharmIndexShowsUpdates();
  if (pharmIndexShowsUpdates()) {
    activePharmLetter = "All";
    return;
  }
  const favoritesOnly = pharmIndexShowsFavorites();
  const baseDrugPool = activePharmDrugPool();
  const subsectionDrugPool = activePharmIndexMode === "drugs"
    ? baseDrugPool.filter((drug) => drugMatchesPharmacySubsection(drug))
    : baseDrugPool;
  const drugPool = favoritesOnly ? filterPharmFavorites("drugs", subsectionDrugPool) : subsectionDrugPool;
  const labPool = favoritesOnly ? filterPharmFavorites("labs", pharmSearchableLabRanges) : pharmSearchableLabRanges;
  const diseasePool = favoritesOnly ? filterPharmFavorites("diseases", pathologyDiseases) : pathologyDiseases;
  const referencePool = favoritesOnly ? filterPharmFavorites("procedures", clinicalReferenceEntries) : clinicalReferenceEntries;
  const holisticPool = favoritesOnly ? filterPharmFavorites("holistic", holisticRemedies) : holisticRemedies;
  const holisticFederatedPool = activePharmIndexMode === "holistic" ? holisticVisibleBrowseCandidates({ letter: "All" }) : [];
  const microbiologyPool = pharmIndexShowsMicrobiology()
    ? microbiologyBrowseCandidates().filter((candidate) => microbiologyCandidateMatchesBrowseBranch(candidate))
    : [];
  const letterSources = [
    ...(pharmIndexShowsLabs() ? labPool.map((lab) => safeText(lab.name)[0]?.toUpperCase()) : []),
    ...(pharmIndexShowsDrugs() ? drugPool.map((drug) => pharmDrugDisplayName(drug)[0]?.toUpperCase()) : []),
    ...(pharmIndexShowsDiseases() ? diseasePool.map((disease) => safeText(disease.name)[0]?.toUpperCase()) : []),
    ...((pharmIndexShowsProcedures() || pharmIndexShowsSurgeries() || pharmIndexShowsFoundations() || pharmIndexShowsClinicalSigns()) ? referencePool
      .filter((entry) => clinicalReferenceMatchesActiveMode(entry))
      .map((entry) => safeText(entry.name)[0]?.toUpperCase()) : []),
    ...(pharmIndexShowsMicrobiology() ? microbiologyPool
      .map((candidate) => safeText(offlineLookupEntityLabel(candidate))[0]?.toUpperCase()) : []),
    ...(activePharmIndexMode === "holistic"
      ? holisticFederatedPool.map((candidate) => safeText(candidate.item?.name || candidate.item?.displayName)[0]?.toUpperCase())
      : (pharmIndexShowsHolistic() ? holisticPool.map((remedy) => safeText(remedy.name)[0]?.toUpperCase()) : []))
  ].filter(Boolean);
  const letters = ["All", ...Array.from(new Set(letterSources)).sort()];
  if (!letters.includes(activePharmLetter)) {
    activePharmLetter = "All";
  }
  letters.forEach((letter) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = letter;
    button.className = letter === activePharmLetter ? "active" : "";
    button.addEventListener("click", () => {
      closePharmDetailPage();
      activePharmLetter = letter;
      renderPharmDatabase();
    });
    pharmAlphabetStrip.append(button);
  });
}

function pharmListText(items = []) {
  return readableListText(items || []);
}

function pharmFieldList(value) {
  if (Array.isArray(value)) {
    return value.flatMap(pharmFieldList).filter(Boolean);
  }
  if (value && typeof value === "object") {
    return Object.values(value).flatMap(pharmFieldList).filter(Boolean);
  }
  const text = safeText(value);
  return text ? [text] : [];
}

function isExpandedBoxedWarningPlaceholder(value = "") {
  const text = safeText(value).toLowerCase();
  return !text
    || /boxed-warning status must be verified/.test(text)
    || /drug-specific boxed warning status is not stored/.test(text)
    || /drug-specific label warnings should be verified/.test(text)
    || /exact boxed-warning status is not listed/.test(text)
    || /exact boxed-warning status is not encoded/.test(text);
}

function isClassLevelBoxedWarningText(value = "") {
  const text = safeText(value).toLowerCase();
  return /\b(class boxed warnings?|class warning|warnings vary|warnings are product-specific|warnings are product specific|no universal boxed warning|no single universal boxed warning|many agents carry boxed warning|selected agents have drug-specific boxed warnings)\b/.test(text);
}

function isNoKnownBoxedWarningText(value = "") {
  const text = safeText(value).toLowerCase();
  return /\b(no (?:(?:current|known)\s+)?(?:(?:(?:u\.?s\.?\s+)?fda|u\.?s\.?)\s+)?boxed warning|no (?:single )?universal boxed warning)\b/.test(text);
}

function stripNoKnownBoxedWarningLead(value = "") {
  return safeText(value)
    .replace(/^no (?:(?:current|known)\s+)?(?:(?:(?:u\.?s\.?\s+)?fda|u\.?s\.?)\s+)?boxed warning/i, "")
    .replace(/^no boxed warning(?:\s+in\s+most\s+common\s+[^;.]*)?/i, "")
    .replace(/^no boxed warning commonly emphasized(?:\s+for\s+NCLEX-style\s+study|\s+for\s+NCLEX|\s+for\s+obstetric\s+use|\s+for\s+IV\s+use)?/i, "")
    .replace(/^no universal boxed warning(?:\s+for\s+all\s+[^;.]*)?/i, "")
    .replace(/^no single universal boxed warning(?:\s+for\s+all\s+[^;.]*)?/i, "")
    .replace(/^no known boxed warning/i, "")
    .replace(/^[;:.,\s-]+/, "")
    .trim();
}

function boxedWarningLooksThin(value = "") {
  const text = safeText(value);
  if (!text) return true;
  return text.length < 260
    || /\b(confirm|verify|not listed|not stored|not encoded|product-specific|product specific|warnings vary|class warning context|no drug-specific boxed warning)\b/i.test(text)
    || isExpandedBoxedWarningPlaceholder(text)
    || isClassLevelBoxedWarningText(text)
    || isNoKnownBoxedWarningText(text);
}

function pharmSpecificBoxedWarningText(drug = {}) {
  if (drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only") {
    return "";
  }
  const name = pharmDrugDisplayName(drug, "This medication");
  const identityTerms = pharmIdentityTermsForEntry(drug);
  const identityBlob = normalizePharmText([
    ...identityTerms,
    drug.name,
    drug.generic,
    drug.displayName
  ].join(" "));
  const blob = normalizePharmText([
    ...identityTerms,
    drug.class,
    pharmInferredClassText(drug),
    pharmClassPathwayText(drug),
    drug.templateKey,
    ...(Array.isArray(drug.classPathway) ? drug.classPathway : [])
  ].join(" "));
  if (!blob) return "";
  const has = (pattern) => pattern.test(blob);
  const isDrug = (pattern) => pattern.test(identityBlob);
  const isPrimaryDrug = (pattern) => pattern.test(normalizePharmText(drug.generic || drug.name || drug.displayName));

  if (isDrug(/\b(fresh frozen plasma|ffp)\b/)) {
    return "High-alert transfusion warning: fresh frozen plasma is plasma clotting-factor replacement, not a thrombolytic. Major dangers are transfusion reaction, TRALI, TACO/volume overload, citrate-related hypocalcemia with large transfusion, infectious risk, and ABO compatibility error. Nursing anchor: verify blood product checks, indication/INR or bleeding context, baseline lungs/volume status, fever/chills/hives/back pain/dyspnea, and stop/escalate suspected reactions immediately.";
  }
  if (isDrug(/\b(prothrombin complex concentrate|4 factor pcc|four factor pcc|pcc)\b/)) {
    return "High-alert reversal warning: prothrombin complex concentrate rapidly replaces vitamin K-dependent clotting factors to reverse major anticoagulant-associated bleeding, but restoring coagulation can precipitate thrombosis, stroke, MI, DVT, or PE. Nursing anchor: confirm the anticoagulant/reversal indication, monitor bleeding control, neuro/chest/limb symptoms, INR or protocol labs, allergy history, and whether vitamin K is also ordered for warfarin reversal.";
  }
  if (isDrug(/\b(vitamin k phytonadione|phytonadione|vitamin k)\b/)) {
    return "High-alert reversal warning: phytonadione enables hepatic synthesis of vitamin K-dependent clotting factors, so warfarin reversal is delayed until new factors are made; it is not instant hemostasis. IV use can cause serious hypersensitivity/anaphylactoid reactions and over-reversal can create temporary warfarin resistance. Nursing anchor: clarify bleeding urgency, route/rate, INR trend, allergy history, and whether PCC/FFP is needed for life-threatening bleeding.";
  }
  if (isDrug(/\b(tranexamic acid|aminocaproic acid)\b/)) {
    return `${name} is an antifibrinolytic, not a thrombolytic: it blocks plasminogen/plasmin interaction with fibrin so clots resist breakdown. High-alert warning: avoid or clarify active intravascular clotting, history/risk of thrombosis, upper urinary tract bleeding with clot obstruction risk, severe renal impairment, and seizure risk with high IV exposure. Nursing anchor: monitor bleeding response, neuro symptoms, chest pain, dyspnea, limb swelling, hematuria/urinary obstruction, and renal dosing.`;
  }
  if (isDrug(/\b(alteplase|tenecteplase|reteplase|streptokinase)\b/)) {
    return `Boxed/high-alert warning: ${name} is a fibrinolytic thrombolytic that can cause severe or fatal bleeding, especially intracranial hemorrhage. Nursing anchor: screen for active bleeding, recent surgery/trauma/stroke, intracranial pathology, severe uncontrolled hypertension, anticoagulant exposure, and pregnancy/postpartum context; monitor neurologic status, puncture sites, BP, hemoglobin, and avoid unnecessary IM injections or invasive sticks.`;
  }
  if (isPrimaryDrug(/\bamiodarone\b/)) {
    return "Boxed warning: reserve oral amiodarone for indicated life-threatening ventricular arrhythmias when other therapy is inadequate because it can cause potentially fatal pulmonary toxicity, severe hepatic injury, and new or worsened arrhythmias. Initiate under hospital or specialist supervision. Nursing anchor: monitor ECG/rhythm, chest imaging and pulmonary status, AST/ALT, thyroid function, potassium/magnesium, bradycardia/QT, new cough or dyspnea, jaundice, and major interactions including warfarin and digoxin.";
  }
  if (isPrimaryDrug(/\bsotalol\b/)) {
    return "Boxed warning: sotalol can cause life-threatening ventricular tachycardia associated with QT prolongation. Initiate or reinitiate in a facility able to provide continuous ECG monitoring and cardiac resuscitation, calculate creatinine clearance for dosing, and check QTc, potassium, magnesium, heart rate, and interacting QT- or rate-slowing drugs.";
  }
  if (isPrimaryDrug(/\bdofetilide\b/)) {
    return "Boxed warning: dofetilide can cause torsades de pointes and must be initiated or reinitiated with continuous ECG monitoring in an appropriate facility. Nursing anchor: calculate creatinine clearance, use the renal-based dose, measure QTc after doses per protocol, correct potassium/magnesium, and screen contraindicated interacting drugs.";
  }
  if (isPrimaryDrug(/\bdronedarone\b/)) {
    return "Boxed warning: dronedarone increases death in symptomatic or recently decompensated heart failure and increases stroke, heart-failure hospitalization, and death in permanent atrial fibrillation. Verify rhythm strategy and heart-failure status, monitor ECG/rate, liver injury, QT/electrolytes, and stop/escalate if permanent atrial fibrillation or decompensated heart failure develops.";
  }
  if (isPrimaryDrug(/\bibutilide\b/)) {
    return "High-alert proarrhythmia warning: ibutilide can cause sustained polymorphic ventricular tachycardia and torsades, especially with prolonged QT, bradycardia, structural heart disease, or low potassium/magnesium. Give with continuous ECG and immediate defibrillation/resuscitation capability, correct electrolytes, and continue monitoring after the infusion per protocol.";
  }
  if (isDrug(/\b(beta blocker|metoprolol|atenolol|propranolol|carvedilol|labetalol|esmolol|bisoprolol|sotalol|nadolol|nebivolol|pindolol|timolol|acebutolol|alprenolol|betaxolol|bopindolol|bupranolol|carazolol|carteolol|celiprolol|landiolol|levobetaxolol|levobunolol|mepindolol|metipranolol|nadoxolol|oxprenolol|penbutolol|practolol|talinolol|tertatolol)\b/)) {
    return "Boxed/high-alert beta-blocker warning: abrupt discontinuation can rebound sympathetic tone and worsen angina, trigger dysrhythmias, or precipitate myocardial infarction in clients with coronary disease. Nursing anchor: taper only as ordered, check heart rate, blood pressure, heart block, acute decompensated heart failure, bronchospasm risk with nonselective agents, diabetes masking of hypoglycemia tachycardia, and hold/escalation parameters before giving.";
  }
  if (isDrug(/\bclarithromycin\b/)) {
    return "High-alert macrolide warning: clarithromycin can prolong QT and precipitate torsades risk, inhibits CYP3A4 and P-glycoprotein, and can cause serious drug interactions, hepatotoxicity, severe skin reactions, and myasthenia gravis worsening. Nursing anchor: screen baseline QT/electrolytes, antiarrhythmics, statins, colchicine, anticoagulants, digoxin, liver symptoms, severe diarrhea, and palpitations/syncope.";
  }
  if (isDrug(/\bfidaxomicin\b/)) {
    return "High-yield safety warning: fidaxomicin is a minimally absorbed macrocyclic antibiotic for C. difficile colitis, so it should not be taught like systemic macrolides with QT/CYP toxicity. Nursing anchor: monitor stool frequency, abdominal pain, fever, leukocytosis, dehydration, recurrence, hypersensitivity or angioedema, and whether symptoms suggest fulminant colitis needing escalation beyond oral gut-local therapy.";
  }
  if (isDrug(/\b(furosemide|bumetanide|torsemide|azosemide)\b/) || has(/\b(loop diuretic|potent diuresis)\b/)) {
    return `Boxed/high-alert diuretic warning: ${name} can cause profound water and electrolyte depletion, leading to dehydration, hypotension, prerenal kidney injury, hypokalemia/hyponatremia, metabolic alkalosis, and dysrhythmia risk; high IV doses or renal dysfunction increase ototoxicity risk. Nursing anchor: check BP, weight, intake/output, edema/lung response, creatinine, potassium, magnesium, sodium, hearing symptoms, and ordered hold parameters.`;
  }
  if (isDrug(/\b(levothyroxine|liothyronine|np thyroid|wp thyroid|renthyroid|thyroid)\b/) || has(/\bthyroid hormone\b/)) {
    return `Boxed warning: thyroid hormones such as ${name} must not be used for obesity or weight loss; excessive doses can cause serious or life-threatening thyrotoxicosis. Nursing anchor: monitor TSH/free T4, pulse, angina, atrial fibrillation, tremor, heat intolerance, insomnia, weight loss, bone loss risk, and uncorrected adrenal insufficiency because thyroid hormone can precipitate adrenal crisis.`;
  }
  if (isDrug(/\blithium\b/)) {
    return "Boxed/high-alert warning: lithium has a narrow therapeutic index; toxicity can occur near therapeutic levels and rises with dehydration, sodium depletion, renal impairment, NSAIDs, ACE inhibitors, ARBs, and diuretics. Nursing anchor: trend trough lithium level, creatinine/eGFR, sodium, thyroid function, fluid/salt intake, vomiting/diarrhea, tremor, ataxia, confusion, sedation, seizures, and when to hold and escalate.";
  }
  if (isDrug(/\bmetformin\b/)) {
    return "Boxed warning: metformin-associated lactic acidosis is rare but life-threatening, with risk increased by severe renal impairment, acute kidney injury, hypoxia, sepsis, shock, heart failure exacerbation, hepatic impairment, heavy alcohol use, older frailty, or iodinated contrast/procedures requiring a hold. Nursing anchor: check eGFR, acute illness status, lactate/acidosis symptoms, rapid breathing, severe weakness, abdominal pain, hypothermia, and hold instructions.";
  }
  if (isDrug(/\bmetronidazole\b/)) {
    return "High-alert warning: metronidazole has product-specific carcinogenicity concern from animal data and important bedside toxicities including peripheral neuropathy, encephalopathy/seizures, severe skin reactions, leukopenia, hepatotoxicity in high-risk clients, and alcohol/disulfiram-like reactions. Nursing anchor: teach no alcohol during and shortly after therapy per product guidance, monitor neuro symptoms, severe diarrhea, liver disease, warfarin interaction, and worsening infection.";
  }
  if (isDrug(/\bmisoprostol\b/)) {
    return "Boxed warning: misoprostol can cause uterine contractions, abortion, premature birth, birth defects, or uterine rupture when used in pregnancy for non-obstetric indications such as ulcer prevention. Nursing anchor: verify pregnancy status and indication before administration, distinguish GI protection from obstetric use, and monitor cramping, bleeding, severe abdominal pain, fever, or hemodynamic instability.";
  }
  if (isDrug(/\bmycophenolate\b/)) {
    return "Boxed warnings: mycophenolate causes embryo-fetal toxicity and pregnancy loss/congenital malformations, and increases risk of serious infections and malignancy such as lymphoma/skin cancer through immunosuppression. Nursing anchor: verify pregnancy testing/contraception counseling, CBC, infection signs, fever, unusual bruising, skin lesions, vaccine planning, and transplant rejection versus infection symptoms.";
  }
  if (isDrug(/\boxytocin\b/)) {
    return "Boxed/high-alert obstetric warning: oxytocin used for elective induction or labor augmentation requires appropriate supervision because excessive uterine stimulation can cause tachysystole, fetal distress, uterine rupture, placental abruption, postpartum hemorrhage risk, and water intoxication/hyponatremia with prolonged high-dose infusion. Nursing anchor: continuous fetal heart rate and contraction monitoring, maternal BP/pulse, intake/output, sodium symptoms, and stop/escalate for tachysystole or nonreassuring tracing.";
  }
  if (isDrug(/\bprasugrel\b/)) {
    return "Boxed warning: prasugrel can cause significant, sometimes fatal bleeding and is contraindicated with active bleeding or prior TIA/stroke; bleeding risk is higher with age 75 or older, low body weight, recent surgery/trauma, and concurrent anticoagulants or NSAIDs. Nursing anchor: assess bleeding, neuro change, planned procedures/hold timing, weight/age risk, CBC, stool/urine blood, and urgent ischemia versus bleeding clues.";
  }
  if (isDrug(/\bticagrelor\b/)) {
    return "Boxed warning: ticagrelor can cause serious bleeding, and aspirin maintenance doses above 100 mg daily reduce its effectiveness after loading. Nursing anchor: verify aspirin dose, procedure hold plan, bleeding history, anticoagulant/NSAID use, dyspnea, bradyarrhythmia/syncope symptoms, adherence to twice-daily dosing, and signs of stroke/MI if therapy is interrupted.";
  }
  if (isDrug(/\bcilostazol\b/)) {
    return "Boxed warning: cilostazol is contraindicated in heart failure because other PDE-3 inhibitor drugs increased mortality in heart-failure populations. Nursing anchor: do not confuse it with thrombolytics; screen heart-failure history, palpitations/tachycardia, bleeding with antiplatelets/anticoagulants, headache, diarrhea, and CYP3A4/CYP2C19 inhibitors that raise exposure.";
  }
  if (isDrug(/\bdipyridamole\b/)) {
    return "High-alert antiplatelet/vasodilator warning: dipyridamole can increase bleeding risk when combined with anticoagulants or antiplatelets and can provoke hypotension, headache, flushing, or ischemic chest symptoms in susceptible coronary disease. Nursing anchor: monitor bleeding, BP, chest pain, planned procedures, aspirin combination context, and do not teach it as a clot-dissolving thrombolytic.";
  }
  if (isDrug(/\b(eptifibatide|tirofiban)\b/)) {
    return `High-alert antiplatelet warning: ${name} is a glycoprotein IIb/IIIa inhibitor that prevents platelet aggregation and can cause major bleeding and thrombocytopenia, especially with renal impairment or invasive procedures. Nursing anchor: verify weight/renal dosing, sheath/vascular access bleeding, platelet count, hemoglobin, concurrent anticoagulants, and report back pain, hypotension, melena, hematuria, or neuro change.`;
  }
  if (isDrug(/\bdapsone\b/)) {
    return "High-alert sulfone warning: dapsone can cause hemolytic anemia, methemoglobinemia, agranulocytosis, severe hypersensitivity/DRESS, serious skin reactions, and hepatotoxicity; risk is higher with G6PD deficiency or oxidative stressors. Nursing anchor: monitor CBC, oxygen saturation that does not match symptoms, cyanosis, dyspnea, fatigue, jaundice, fever/sore throat, rash/mucosal lesions, and liver symptoms.";
  }
  if (isDrug(/\b(sulfadiazine|sulfamethoxazole|sulfasalazine)\b/)) {
    return `High-alert sulfonamide warning: ${name} can cause severe cutaneous reactions including SJS/TEN, blood dyscrasias, hepatotoxicity, hypersensitivity/DRESS, crystalluria or renal injury for selected agents, and kernicterus risk in vulnerable neonates/late pregnancy contexts. Nursing anchor: screen sulfonamide reaction history, hydration, renal/liver function, CBC if prolonged/high risk, rash/mucosal lesions, fever, sore throat, jaundice, and unusual bruising.`;
  }
  if (isDrug(/\bthalidomide\b/)) {
    return "Boxed warnings: thalidomide causes severe, life-threatening birth defects or embryo-fetal death after pregnancy exposure and also increases venous/arterial thromboembolism risk, especially with dexamethasone or chemotherapy regimens. Nursing anchor: verify REMS-style pregnancy prevention/testing, contraception, no blood or sperm donation, neuropathy, sedation/falls, constipation, and clot symptoms.";
  }

  if (isDrug(/\bclozapine\b/)) {
    return "Boxed warnings: severe neutropenia/agranulocytosis requiring ANC monitoring and REMS-style safety control; orthostatic hypotension, bradycardia, and syncope especially during titration; seizures, with risk increasing at higher doses; myocarditis/cardiomyopathy that can be fatal; and increased mortality in older adults with dementia-related psychosis. Nursing anchor: verify ANC eligibility, titrate carefully, monitor fever/sore throat/infection, chest pain, dyspnea, persistent tachycardia, syncope, seizure activity, severe constipation/ileus symptoms, and metabolic changes.";
  }
  if (has(/\b(antipsychotic|haloperidol|chlorpromazine|fluphenazine|risperidone|olanzapine|quetiapine|ziprasidone|aripiprazole|paliperidone|lurasidone)\b/)) {
    return `Boxed warning: ${name} and other antipsychotics increase mortality in older adults with dementia-related psychosis and are not approved for dementia-related psychosis. High-alert nursing detail: connect the warning to stroke/cardiac/infectious death signals in frail older adults, and still monitor all clients for neuroleptic malignant syndrome, tardive dyskinesia, EPS/akathisia, QT risk when relevant, sedation, orthostasis, falls, and metabolic effects.`;
  }
  if (isDrug(/\b(warfarin)\b/)) {
    return "Boxed warning: warfarin can cause major or fatal bleeding. Risk rises with high INR, interacting drugs, liver disease, older age, falls/trauma, recent surgery, uncontrolled hypertension, bleeding history, and inconsistent vitamin K intake. Nursing anchor: trend INR against the ordered goal, assess bleeding/bruising/black stools/neuro changes, reconcile antibiotics/NSAIDs/antiplatelets/herbals, teach consistent vitamin K intake, and know the reversal plan for serious bleeding.";
  }
  if (has(/\b(apixaban|rivaroxaban|edoxaban|dabigatran|direct oral anticoagulant|doac|factor xa|direct thrombin)\b/)) {
    return `Boxed warnings: premature discontinuation of ${name} can increase thrombotic events, and spinal/epidural hematoma can occur with neuraxial anesthesia or spinal puncture, potentially causing long-term paralysis. Nursing anchor: do not stop without an anticoagulation plan, assess renal function/adherence/bleeding, and urgently report new back pain, numbness, weakness, bowel/bladder dysfunction, or neurologic change after neuraxial procedures.`;
  }
  if (has(/\b(enoxaparin|dalteparin|fondaparinux|low molecular weight heparin|lmwh)\b/)) {
    return `Boxed warning: ${name} can cause spinal or epidural hematoma in clients receiving neuraxial anesthesia or spinal puncture, with possible long-term or permanent paralysis. Nursing anchor: screen for epidural/spinal procedures, indwelling catheters, traumatic puncture, anticoagulant/antiplatelet/NSAID co-use, renal impairment, and new back pain or neurologic deficits.`;
  }
  if (has(/\b(heparin|unfractionated heparin)\b/)) {
    return "High-alert anticoagulant warning: unfractionated heparin can cause serious bleeding and heparin-induced thrombocytopenia even when a boxed warning is not the main label teaching point. Nursing anchor: verify weight-based dosing/pump settings, aPTT or anti-Xa monitoring per protocol, platelet trend, bleeding, HIT clues, renal/hepatic context, and protamine reversal policy.";
  }
  if (isDrug(/\b(clopidogrel)\b/)) {
    return "Boxed warning: clopidogrel effectiveness depends on CYP2C19 activation. Poor metabolizers can have reduced antiplatelet effect and higher cardiovascular event risk after ACS or stenting. Nursing anchor: do not frame this as a bleeding-only drug; also watch adherence, stent-thrombosis risk, genotype/history clues when available, interacting CYP2C19 inhibitors, and signs of recurrent ischemia.";
  }
  const isExplicitOpioid = isDrug(/\b(morphine|hydromorphone|fentanyl|oxycodone|hydrocodone|codeine|methadone|tramadol|buprenorphine)\b/);
  const isOpioidClass = has(/\bopioid\b/) && !has(/\b(non opioid|opioid antagonist|opioid reversal)\b/);
  if (isExplicitOpioid || isOpioidClass) {
    return `Boxed warnings: ${name} can cause addiction, abuse, and misuse; life-threatening respiratory depression; accidental ingestion; neonatal opioid withdrawal with prolonged pregnancy exposure; and profound sedation, respiratory depression, coma, or death when combined with benzodiazepines, alcohol, or other CNS depressants. Nursing anchor: assess sedation/respiratory rate/oxygenation, opioid tolerance, renal/hepatic risk, naloxone access, bowel regimen, fall risk, and safe storage.`;
  }
  if (has(/\b(benzodiazepine|lorazepam|alprazolam|diazepam|clonazepam|midazolam|temazepam)\b/)) {
    return `Boxed warnings: ${name} carries risks of abuse, misuse, addiction, physical dependence, and withdrawal reactions; combined use with opioids or other CNS depressants can cause profound sedation, respiratory depression, coma, and death. Nursing anchor: assess respiratory status, sedation, alcohol/opioid use, fall/delirium risk, duration of therapy, withdrawal/seizure risk, and taper instructions instead of abrupt stopping.`;
  }
  if (has(/\b(fluoxetine|sertraline|citalopram|escitalopram|paroxetine|fluvoxamine|venlafaxine|desvenlafaxine|duloxetine|bupropion|mirtazapine|trazodone|antidepressant|ssri|snri|tca|maoi)\b/)) {
    return `Boxed warning: ${name} and other antidepressants can increase suicidal thoughts and behaviors in children, adolescents, and young adults, especially early in therapy or after dose changes. Nursing anchor: assess new agitation, insomnia, impulsivity, worsening depression, suicidal thinking, bipolar/mania history, serotonin syndrome risk when relevant, and family/client safety planning.`;
  }
  if (has(/\bfluoroquinolone\b/) || isDrug(/\b(ciprofloxacin|levofloxacin|moxifloxacin)\b/)) {
    return `Boxed warnings: systemic fluoroquinolones can cause disabling and potentially permanent adverse effects involving tendons, muscles, joints, nerves, and the CNS; tendinitis/tendon rupture can occur during or after therapy; peripheral neuropathy may be irreversible; CNS effects and serious mental health effects can occur; and myasthenia gravis can worsen, including respiratory failure. Nursing anchor: reserve for appropriate indications, clarify safer alternatives for uncomplicated infections, stop/notify for tendon pain, neuropathy, severe mood/CNS change, dysglycemia, QT risk, or aortic aneurysm/dissection risk.`;
  }
  if (has(/\b(aminoglycoside|gentamicin|tobramycin|amikacin|streptomycin)\b/)) {
    return `Boxed warnings: aminoglycosides such as ${name} can cause nephrotoxicity, ototoxicity that may be irreversible, and neuromuscular blockade with respiratory paralysis. Nursing anchor: monitor renal function, urine output, drug levels when ordered, hearing/vestibular symptoms, concurrent loop diuretics/vancomycin/nephrotoxins, and respiratory weakness risk with neuromuscular disorders or paralytics.`;
  }
  if (has(/\blincosamide\b/) || isDrug(/\bclindamycin\b/)) {
    return "Boxed warning: clindamycin can cause severe colitis, including C. difficile-associated diarrhea, which may be life-threatening and can occur during therapy or after stopping. Nursing anchor: new watery/bloody diarrhea, abdominal pain, fever, dehydration, or leukocytosis after antibiotics requires escalation, not routine antidiarrheal treatment without evaluation.";
  }
  if (has(/\b(ace inhibitor|lisinopril|enalapril|captopril|benazepril|ramipril|arb|losartan|valsartan|irbesartan|olmesartan|candesartan|telmisartan)\b/)) {
    return `Boxed warning: drugs that act on the renin-angiotensin system can cause fetal toxicity when used in pregnancy, especially in the second and third trimesters. Nursing anchor: verify pregnancy status when relevant, teach to report pregnancy immediately, and connect fetal renal injury/oligohydramnios/skull-lung effects to why the drug must be stopped and replaced if pregnancy occurs.`;
  }
  if (has(/\b(glp 1|gip glp 1)\b/) || isDrug(/\b(semaglutide|liraglutide|dulaglutide|exenatide|tirzepatide)\b/)) {
    return `Boxed warning: ${name} has thyroid C-cell tumor risk in rodent data and is contraindicated with personal/family history of medullary thyroid carcinoma or MEN2. Nursing anchor: screen MTC/MEN2 history, teach to report neck mass, dysphagia, dyspnea, or persistent hoarseness, and still monitor pancreatitis, gallbladder disease, dehydration from GI effects, and hypoglycemia when combined with insulin or sulfonylureas.`;
  }
  if (isDrug(/\b(methimazole|propylthiouracil|ptu)\b/)) {
    if (isDrug(/\b(propylthiouracil|ptu)\b/)) {
      return "Boxed warning: propylthiouracil can cause severe liver injury and acute liver failure, sometimes fatal or requiring transplant. Nursing anchor: use is usually reserved for specific situations such as first-trimester pregnancy or thyroid storm when appropriate; teach urgent reporting of jaundice, dark urine, RUQ pain, severe fatigue, anorexia, or pruritus and monitor liver concerns.";
    }
    return "High-alert antithyroid warning: methimazole does not carry PTU's same boxed liver-failure emphasis, but agranulocytosis and serious hepatotoxicity are major safety issues. Nursing anchor: fever or sore throat on a thionamide needs urgent CBC evaluation; jaundice/dark urine/RUQ pain need liver evaluation.";
  }
  if (isDrug(/\b(valproate|valproic acid|divalproex)\b/)) {
    return "Boxed warnings: valproate can cause fatal hepatotoxicity, life-threatening pancreatitis, and major fetal harm including neural tube defects and lower IQ/neurodevelopmental risk. Nursing anchor: avoid in pregnancy unless clearly necessary, verify contraception/pregnancy counseling, monitor LFTs, abdominal pain/vomiting, mental-status change, platelets, ammonia cues, and drug levels when ordered.";
  }
  if (isDrug(/\b(carbamazepine)\b/)) {
    return "Boxed warnings: carbamazepine can cause serious and sometimes fatal dermatologic reactions including SJS/TEN, especially with HLA-B*1502 risk ancestry, and aplastic anemia/agranulocytosis. Nursing anchor: screen ancestry/genetic testing when applicable, monitor CBC, fever/sore throat, mucosal rash, blistering, and stop/escalate for serious skin findings.";
  }
  if (isDrug(/\blamotrigine\b/)) {
    return "Boxed warning: lamotrigine can cause serious rashes requiring hospitalization, including Stevens-Johnson syndrome and toxic epidermal necrolysis, with higher risk from rapid titration, valproate co-use, or exceeding starting doses. Nursing anchor: teach immediate reporting of rash, mucosal lesions, fever, facial swelling, or systemic symptoms.";
  }
  if (isDrug(/\b(phenytoin|fosphenytoin)\b/)) {
    return "Boxed warning: rapid IV phenytoin can cause severe cardiovascular reactions including hypotension and arrhythmias; fosphenytoin still requires cardiac monitoring and correct dose units. Nursing anchor: verify route/rate, ECG/BP monitoring, compatibility, extravasation/purple glove risk for phenytoin, and therapeutic levels/toxicity cues.";
  }
  if (has(/\b(tnf|adalimumab|infliximab|etanercept|certolizumab|golimumab)\b/)) {
    return `Boxed warnings: TNF-alpha inhibitors such as ${name} increase risk of serious infections including TB, invasive fungal infections, bacterial sepsis, and opportunistic infections; malignancy including lymphoma has been reported, especially in children/adolescents/young adults for some agents. Nursing anchor: screen TB/hepatitis risk, hold/clarify active serious infection, teach fever/night sweats/weight loss/cough, avoid live vaccines when applicable, and monitor for unusual bruising, lymph nodes, or persistent infection.`;
  }
  if (has(/\b(jak inhibitor|tofacitinib|baricitinib|upadacitinib|ruxolitinib)\b/)) {
    return `Boxed warnings: JAK inhibitors can cause serious infections, mortality, malignancy, major adverse cardiovascular events, and thrombosis. Nursing anchor: screen TB/hepatitis and infection risk, assess cardiovascular/clot risk, counsel on VTE/MI/stroke symptoms, avoid live vaccines when applicable, and monitor CBC, lipids, liver tests, and infection signs.`;
  }
  if (has(/\b(bcr abl|imatinib|dasatinib|nilotinib|bosutinib|ponatinib)\b/)) {
    return `High-alert targeted-therapy warning: BCR-ABL TKIs such as ${name} have product-specific serious warnings, with recurring nursing priorities around myelosuppression, hepatotoxicity, fluid retention/heart failure or pleural effusion, QT/vascular events for selected agents, embryo-fetal harm, and CYP3A4/food interaction issues. Nursing anchor: monitor CBC, liver tests, edema/dyspnea, ECG/electrolytes when relevant, pregnancy avoidance, adherence, and interaction-heavy medication lists.`;
  }
  if (has(/\b(egfr|erlotinib|gefitinib|afatinib|osimertinib)\b/)) {
    return `High-alert targeted-therapy warning: EGFR TKIs such as ${name} can cause serious interstitial lung disease/pneumonitis, severe diarrhea/dehydration, hepatotoxicity, ocular toxicity, severe skin reactions, and QT/cardiomyopathy for selected agents. Nursing anchor: escalate new cough/dyspnea/fever, severe diarrhea, jaundice, eye pain/vision change, syncope/palpitations, or infected/severe rash.`;
  }
  if (has(/\b(btk|ibrutinib|acalabrutinib|zanubrutinib)\b/)) {
    return `High-alert targeted-therapy warning: BTK inhibitors such as ${name} can cause serious bleeding, infections, cytopenias, atrial fibrillation/flutter, hypertension, and second primary malignancies. Nursing anchor: review anticoagulants/antiplatelets and procedure holds, monitor CBC, fever, bruising/black stools, palpitations, blood pressure, and CYP3A interactions.`;
  }
  if (has(/\b(cdk4|cdk 4|palbociclib|ribociclib|abemaciclib)\b/)) {
    return `High-alert targeted-therapy warning: CDK4/6 inhibitors such as ${name} commonly cause neutropenia and can cause serious infection; class-specific concerns include hepatotoxicity, interstitial lung disease/pneumonitis, QT prolongation for ribociclib, severe diarrhea/VTE for abemaciclib, and embryo-fetal harm. Nursing anchor: monitor CBC, fever, LFTs, diarrhea/dehydration, dyspnea/cough, ECG/electrolytes when relevant, and cycle-specific hold parameters.`;
  }
  if (has(/\b(rituximab|obinutuzumab|ofatumumab|cd20)\b/)) {
    return `Boxed warnings: CD20-directed antibodies such as ${name} can cause fatal infusion reactions, severe mucocutaneous reactions, hepatitis B reactivation, and progressive multifocal leukoencephalopathy. Nursing anchor: verify hepatitis B screening, premedication/infusion monitoring, neurologic changes, severe rash/mucosal lesions, and delayed infection risk.`;
  }
  if (has(/\b(trastuzumab|pertuzumab|her2)\b/)) {
    return `Boxed warnings: HER2-directed therapy can cause cardiomyopathy/heart failure, infusion or pulmonary toxicity for selected products, and embryo-fetal toxicity. Nursing anchor: verify baseline and follow-up LVEF monitoring, dyspnea/edema/cough, infusion reaction readiness, pregnancy prevention, and coordination with anthracycline exposure history.`;
  }
  if (has(/\b(bevacizumab|vegf)\b/)) {
    return `Boxed warnings: bevacizumab/VEGF inhibition can cause gastrointestinal perforation and fistula, surgery/wound-healing complications, and severe or fatal hemorrhage. Nursing anchor: assess abdominal pain, GI bleeding, hemoptysis, wound status, recent/planned surgery timing, blood pressure, proteinuria, and thromboembolic symptoms.`;
  }
  if (has(/\b(immune checkpoint|pd 1|pd l1|ctla 4|pembrolizumab|nivolumab|ipilimumab|atezolizumab|durvalumab)\b/)) {
    return `High-alert oncology immunotherapy warning: checkpoint inhibitors may not all carry the same boxed warning, but the life-threatening safety pattern is immune-mediated organ inflammation. Nursing anchor: new diarrhea/colitis, cough/pneumonitis, hepatitis labs/jaundice, endocrinopathy, nephritis, severe rash, neurologic weakness, myocarditis symptoms, or infusion reaction requires early escalation and steroid/hold protocols when ordered.`;
  }
  if (has(/\b(methotrexate)\b/)) {
    return "Boxed warnings: methotrexate can cause severe toxicity including embryo-fetal death/teratogenicity, bone-marrow suppression, serious infections, hepatotoxicity, pulmonary toxicity, GI toxicity, severe skin reactions, renal toxicity, and secondary malignancy; dosing errors can be fatal. Nursing anchor: distinguish weekly low-dose regimens from daily chemotherapy schedules, verify pregnancy/renal/liver/CBC status, folic acid/leucovorin plan, infection signs, mouth sores, dyspnea/cough, and interacting NSAIDs/trimethoprim.";
  }
  if (has(/\b(doxorubicin|daunorubicin|epirubicin|anthracycline)\b/)) {
    return `Boxed warnings: anthracyclines such as ${name} can cause dose-related cardiomyopathy/heart failure, severe myelosuppression, secondary leukemia, and severe tissue injury with extravasation; some products have formulation-specific dosing warnings. Nursing anchor: verify lifetime cumulative dose/LVEF monitoring, vesicant precautions, CBC nadir/infection bleeding risk, and report chest symptoms, dyspnea, edema, or IV-site burning/swelling immediately.`;
  }
  if (has(/\b(cyclophosphamide|ifosfamide|alkylating)\b/)) {
    return `High-alert oncology warning: alkylating agents such as ${name} can cause severe myelosuppression, hemorrhagic cystitis, infertility, secondary malignancy, cardiopulmonary toxicity for selected regimens, and embryo-fetal harm. Nursing anchor: monitor CBC, hydration/mesna plan when ordered, hematuria, infection/bleeding, reproductive counseling, and extravasation/handling precautions.`;
  }
  if (has(/\b(cisplatin|carboplatin|oxaliplatin|platinum)\b/)) {
    return `High-alert oncology warning: platinum agents such as ${name} can cause severe myelosuppression, nephrotoxicity, neuropathy, ototoxicity, hypersensitivity reactions, and significant nausea/vomiting. Nursing anchor: monitor renal function, magnesium/potassium, hearing/neuropathy symptoms, hydration/antiemetic plan, CBC, and infusion reaction cues.`;
  }
  if (has(/\b(nsaid|ibuprofen|naproxen|ketorolac|celecoxib|diclofenac)\b/)) {
    return `Boxed warnings: non-aspirin NSAIDs can increase serious cardiovascular thrombotic events including MI and stroke, and can cause serious GI bleeding, ulceration, and perforation, which may be fatal. Nursing anchor: assess CAD/stroke risk, CABG contraindication context, GI bleed history, anticoagulants/steroids/SSRIs, kidney function, blood pressure, and lowest effective dose/duration.`;
  }
  if (has(/\b(beta lactam|penicillin|amoxicillin|ampicillin|piperacillin|tazobactam|cephalosporin|cefazolin|ceftriaxone|cefepime|carbapenem|meropenem|imipenem|ertapenem|aztreonam)\b/)) {
    return `High-alert antibiotic warning: ${name} does not share one universal boxed warning across all beta-lactams, but the clinically important danger pattern is immediate hypersensitivity/anaphylaxis, severe cutaneous reactions, C. difficile-associated diarrhea, seizure risk with selected high-dose/renal/CNS contexts, cytopenias or liver/kidney injury for selected agents, and organism/site mismatch. Nursing anchor: clarify allergy phenotype, culture/site, renal dosing, severe diarrhea, rash/mucosal lesions, seizure history, and timed administration.`;
  }
  if (isDrug(/\bisotretinoin\b/)) {
    return "Boxed warning: isotretinoin causes severe birth defects and fetal death if used during pregnancy. Nursing anchor: verify pregnancy-prevention program requirements, negative pregnancy testing, contraception requirements, no blood donation, and urgent reporting of pregnancy exposure.";
  }
  return "";
}

function boxedWarningContextIsGeneric(value = "") {
  const text = safeText(value).toLowerCase();
  if (!text) return true;
  return /confirm the current|current fda|dailymed|verify current|major safety review centers on|drug-specific boxed warning is listed|boxed-warning status|not encoded|label before clinical use|hypersensitivity, organ toxicity, route-specific hazards/i.test(text);
}
function pharmRawSafetyCueText(drug = {}) {
  return pharmListText([
    ...pharmFieldList(drug.adverseEffects),
    ...pharmFieldList(drug.adverseReactions),
    ...pharmFieldList(drug.sideEffects),
    ...pharmFieldList(drug.commonSideEffects),
    ...pharmFieldList(drug.seriousAdverseEffects),
    ...pharmFieldList(drug.toxicity),
    ...pharmFieldList(drug.contraindications),
    ...pharmFieldList(drug.interactions),
    ...pharmFieldList(drug.nursingEssentials),
    ...pharmFieldList(drug.keyLabs),
    ...pharmFieldList(drug.nclexTraps)
  ].filter((item) => {
    const clean = sanitizeMedicalReferenceText(item);
    return clean && !isNoKnownBoxedWarningText(clean) && !isExpandedBoxedWarningPlaceholder(clean);
  }));
}

function pharmFallbackSafetyPatternText(drug = {}) {
  if (drug.generatedClassCard === true) return "";
  const name = pharmDrugDisplayName(drug, "This medication");
  const classText = safeText(pharmDisplayClass(drug));
  const blob = normalizePharmText([
    name,
    classText,
    drug.class,
    pharmInferredClassText(drug),
    pharmClassPathwayText(drug),
    drug.templateKey,
    ...(Array.isArray(drug.tags) ? drug.tags : []),
    ...(Array.isArray(drug.classPathway) ? drug.classPathway : [])
  ].join(" "));
  const mechanism = safeText(drug.mechanism || pharmTeachingOverlay(drug).mechanism || "");
  const mechanismCue = mechanism && !pharmOpeningRawTextIsGeneric(mechanism)
    ? ` Mechanism link: ${pharmOpeningFirstSentences(mechanism, 1)}`
    : "";
  const rawCue = pharmRawSafetyCueText(drug);
  const cue = rawCue
    ? ` Card-specific cue: ${pharmOpeningFirstSentences(rawCue, 1)}`
    : "";
  const line = (detail) => `High-yield warning context: ${name}${classText ? ` is ${articleForPharmClassPhrase(classText)} ${pharmCrashCourseClassPhrase(pharmClassPhraseForDescription(classText))}.` : "."} ${detail}${mechanismCue}${cue}`.replace(/\s+/g, " ").trim();
  if (/\b(antibiotic|antimicrobial|antiviral|antifungal|antimalarial|aminoglycoside|macrolide|sulfonamide|fluoroquinolone|cephalosporin|penicillin|carbapenem|tetracycline|nitroimidazole)\b/i.test(blob)) {
    return line("Safety is driven by allergy phenotype, infection site/culture fit, renal or hepatic dosing, severe rash or mucosal lesions, C. difficile diarrhea, and whether toxicity is worse than the infection being treated. Nursing anchor: assess allergy details, cultures, fever/WBC trend, renal function, diarrhea, rash, and response to therapy.");
  }
  if (/\b(oncology|antineoplastic|chemotherapy|kinase|monoclonal|checkpoint|platinum|anthracycline|alkylating|antimetabolite|vinca|taxane|immunosuppress|transplant|biologic|jak inhibitor|tnf)\b/i.test(blob)) {
    return line("Safety is driven by immune suppression, myelosuppression, organ toxicity, infusion or hypersensitivity reactions, embryo-fetal harm, and drug-specific monitoring. Nursing anchor: check CBC, infection signs, liver/kidney tests, pregnancy status, infusion reaction readiness, vaccines/live-virus risk, and hold parameters.");
  }
  if (/\b(insulin|sulfonylurea|glp|sglt|diabetes|glucose|hypoglycemia|metformin|pramlintide)\b/i.test(blob)) {
    return line("Safety is driven by glucose movement and nutrition timing. Nursing anchor: match dose to meal status, glucose trend, renal function, dehydration/illness, hypoglycemia symptoms, ketone or acidosis risk when relevant, and whether the client can safely eat after receiving therapy.");
  }
  if (/\b(opioid|benzodiazepine|sedative|hypnotic|anesthetic|cns depressant|barbiturate|muscle relaxant|antipsychotic|antidepressant|antiepileptic|seizure)\b/i.test(blob)) {
    return line("Safety is driven by CNS depression or excitation, respiratory status, falls, delirium, withdrawal, and syndrome-specific toxicity. Nursing anchor: assess sedation, respiratory rate, oxygenation, mental status, fall risk, suicide or seizure risk when relevant, interacting CNS depressants, and taper/hold instructions.");
  }
  if (/\b(beta blocker|calcium channel|antihypertensive|antiarrhythmic|vasodilator|inotrope|pressor|cardiac|heart|angina|hypertension|dysrhythmia|diuretic|nitrate|raas|ace inhibitor|arb|aldosterone)\b/i.test(blob)) {
    return line("Safety is driven by perfusion, rhythm, pressure, renal blood flow, and electrolytes. Nursing anchor: check BP, pulse, ECG/rhythm cues when relevant, orthostasis, kidney function, potassium/magnesium/sodium, chest pain, dyspnea, edema, and ordered hold parameters.");
  }
  if (/\b(anticoagulant|antiplatelet|thrombolytic|fibrinolytic|heparin|warfarin|doac|bleeding|coagulation)\b/i.test(blob)) {
    return line("Safety is driven by the balance between clot prevention and bleeding. Nursing anchor: assess active bleeding, recent procedures/trauma, neurologic change, hemoglobin/platelets/coagulation labs when ordered, renal function, interacting antiplatelets/NSAIDs/anticoagulants, and reversal or hold plans.");
  }
  if (/\b(respiratory|bronchodilator|beta agonist|anticholinergic|inhaler|asthma|copd|methylxanthine)\b/i.test(blob)) {
    return line("Safety is driven by airway response versus cardiac stimulation or paradoxical worsening. Nursing anchor: assess work of breathing, wheeze, oxygenation, rescue-use frequency, heart rate, tremor, potassium when relevant, inhaler technique, and escalation signs.");
  }
  if (/\b(gi|gastrointestinal|laxative|antiemetic|acid|ppi|h2 blocker|bowel|phosphate binder|bile|pancreatic|sucralfate|ursodiol)\b/i.test(blob)) {
    return line("Safety is driven by hydration, electrolytes, obstruction or bleeding clues, liver/pancreas context, and drug-binding interactions. Nursing anchor: assess abdominal pain/distention, bowel pattern, vomiting, blood, renal function/electrolytes, timing separation from other meds, and red flags instead of treating symptoms blindly.");
  }
  if (/\b(hormone|thyroid|corticosteroid|estrogen|progestin|contraceptive|uterotonic|endocrine|bisphosphonate|serm|aromatase)\b/i.test(blob)) {
    return line("Safety is driven by endocrine overstimulation or suppression, pregnancy context, thromboembolism or bone risk when relevant, and slow lab/clinical feedback loops. Nursing anchor: check pregnancy status when relevant, vital signs, symptom trend, ordered hormone/lab monitoring, clot symptoms, and abrupt-stop risks.");
  }
  if (/\b(vaccine|immunoglobulin|antitoxin|toxoid|immune globulin)\b/i.test(blob)) {
    return line("Safety is driven by hypersensitivity, timing after exposure, immune status, and whether passive antibody and active vaccination are both needed. Nursing anchor: screen allergy history, immunocompromise, pregnancy context when relevant, injection/infusion reaction signs, and follow-up dose timing.");
  }
  if (/\b(herbal|supplement|vitamin|mineral|nutraceutical|omega|coenzyme|st john|echinacea|black cohosh)\b/i.test(blob)) {
    return line("Safety is driven by product variability, contamination/adulteration risk, pregnancy/lactation uncertainty, and drug interactions. Nursing anchor: reconcile prescription drugs, anticoagulants, sedatives, serotonergic agents, liver/kidney disease, surgery timing, and whether symptoms could be adverse effects rather than benefit.");
  }
  return line("Safety is driven by the specific mechanism, route, dose, organ clearance, interactions, population risks, and red-flag adverse effects on this card. Nursing anchor: assess allergies, pregnancy/population risk, renal/hepatic function, vitals, expected response, toxicity clues, and hold/escalation parameters before treating the entry as routine.");
}

function pharmBoxedWarningDisplay(drug = {}, fallback = "") {
  if (drug.generatedClassCard === true) {
    if (drug.generatedClassContentOwnership === "navigation-only") return "";
    return sanitizeMedicalReferenceText(drug.boxedWarning || "");
  }
  const overlayWarning = pharmTeachingOverlay(drug).warning;
  const isCuratedStudyCard = /\bcurated (?:full study|drug class) card\b/i.test([drug.confidenceTier, drug.templateKey].filter(Boolean).join(" "));
  const raw = sanitizeMedicalReferenceText(fallback || (isCuratedStudyCard ? drug.boxedWarning : "") || overlayWarning || drug.boxedWarning);
  const specificWarning = pharmSpecificBoxedWarningText(drug);
  const fallbackWarning = pharmFallbackSafetyPatternText(drug);
  const hasDetailedNoBoxedSafety = isNoKnownBoxedWarningText(raw)
    && raw.length >= 180
    && (isCuratedStudyCard || /\b(anaphylaxis|hypersensitivity|contraindicat|hepatotoxic|hepatic|transaminase|neurotoxic|seizure|infection|clostridioides|thrombocytopen|glomerulonephritis|malignancy|sedation|driving|hypertension|raynaud|pregnan|fetal|renal|dialysis|qtc|torsades|cyp|interaction|resistance|monitor|obtain|avoid|hold|discontinue|stop|escalat)\b/i.test(raw))
    && !boxedWarningContextIsGeneric(raw)
    && !isExpandedBoxedWarningPlaceholder(raw);

  if (hasDetailedNoBoxedSafety) {
    return raw;
  }

  if (specificWarning && boxedWarningLooksThin(raw)) {
    return specificWarning;
  }

  if (drug.expandedIndex) {
    if (isExpandedBoxedWarningPlaceholder(raw)) {
      return specificWarning || fallbackWarning;
    }
    if (isClassLevelBoxedWarningText(raw)) {
      return specificWarning || fallbackWarning;
    }
  }

  if (!raw) {
    return specificWarning || fallbackWarning;
  }

  if (isNoKnownBoxedWarningText(raw)) {
    const hasDetailedCardSpecificSafety = raw.length >= 180
      && /\b(anaphylaxis|hypersensitivity|contraindicat|hepatotoxic|thrombocytopen|glomerulonephritis|infection|malignancy|sedation|driving|hypertension|raynaud|pregnan|fetal|monitor|obtain|avoid|hold|discontinue|stop|escalat)\b/i.test(raw)
      && !boxedWarningContextIsGeneric(raw)
      && !isExpandedBoxedWarningPlaceholder(raw);
    if (hasDetailedCardSpecificSafety) return raw;
    return specificWarning || fallbackWarning;
  }

  if (boxedWarningContextIsGeneric(raw) || isExpandedBoxedWarningPlaceholder(raw)) {
    return specificWarning || fallbackWarning;
  }

  return raw;
}
function pharmAdverseEffectsText(drug = {}) {
  if (drug.generatedClassCard === true) {
    if (drug.generatedClassContentOwnership === "navigation-only") return "";
    return pharmListText([
      ...pharmFieldList(drug.adverseEffects),
      ...pharmFieldList(drug.adverseReactions),
      ...pharmFieldList(drug.sideEffects),
      ...pharmFieldList(drug.commonSideEffects),
      ...pharmFieldList(drug.seriousAdverseEffects),
      ...pharmFieldList(drug.toxicity)
    ].filter(Boolean));
  }
  const overlay = pharmTeachingOverlay(drug);
  const explicitAdverse = [
    ...pharmFieldList(overlay.adverseEffects),
    ...pharmFieldList(drug.adverseEffects),
    ...pharmFieldList(drug.adverseReactions),
    ...pharmFieldList(drug.sideEffects),
    ...pharmFieldList(drug.commonSideEffects),
    ...pharmFieldList(drug.seriousAdverseEffects),
    ...pharmFieldList(drug.toxicity)
  ].filter(Boolean);
  if (explicitAdverse.length) {
    return pharmListText(explicitAdverse);
  }

  return pharmListText([
    pharmBoxedWarningDisplay(drug),
    ...pharmFieldList(overlay.nursing),
    ...pharmFieldList(drug.nursingEssentials),
    ...pharmFieldList(drug.nclexTraps)
  ]);
}

