function renderClinicalReferenceIndex() {
  if (!clinicalReferenceEntries.length) return null;
  const query = pharmSearchInput?.value || "";
  const cleanQuery = normalizePharmText(query);
  const entriesToRender = cleanQuery
    ? searchClinicalReferenceEntries(query)
    : clinicalReferenceEntries.filter((entry) => clinicalReferenceMatchesActiveMode(entry));

  const panel = document.createElement("section");
  panel.className = "pharm-pathology-index pharm-procedure-index";
  const heading = document.createElement("strong");
  const foundationsOnly = activePharmIndexMode === "foundations";
  const clinicalSignsOnly = activePharmIndexMode === "clinical-signs";
  const microbiologyOnly = activePharmIndexMode === "microbiology";
  heading.textContent = microbiologyOnly
    ? (cleanQuery ? "Matching Microbiology references" : "Microbiology references")
    : clinicalSignsOnly
    ? (cleanQuery ? "Matching clinical signs and examination findings" : "Clinical signs and examination findings")
    : foundationsOnly
      ? (cleanQuery ? "Matching clinical foundations" : "Clinical foundations")
      : (cleanQuery ? "Matching diagnostics, procedures & specialty references" : "Diagnostics, procedures & specialty references");
  const note = document.createElement("p");
  note.textContent = cleanQuery
    ? `${entriesToRender.length} clinical reference ${entriesToRender.length === 1 ? "match" : "matches"} for "${query.trim()}".`
    : microbiologyOnly
      ? `${entriesToRender.length} Microbiology-owned or explicitly federated reference entries.`
      : clinicalSignsOnly
      ? `${entriesToRender.length} clinical-sign and bedside-examination cards with mechanism, interpretation, reliability limits, documentation, and escalation guidance.`
      : foundationsOnly
        ? `${entriesToRender.length} high-depth anatomy and physiology foundation cards.`
        : `${entriesToRender.length} high-yield diagnostic, procedure, and specialty reference cards.`;
  panel.append(heading, note);

  if (!entriesToRender.length) {
    return panel;
  }

  const grouped = entriesToRender.reduce((groups, entry) => {
    const letter = safeText(entry.name)[0]?.toUpperCase() || "#";
    if (!groups.has(letter)) groups.set(letter, []);
    groups.get(letter).push(entry);
    return groups;
  }, new Map());

  grouped.forEach((items, letter) => {
    const group = document.createElement("div");
    group.className = "pharm-pathology-letter-group";
    const letterLabel = document.createElement("b");
    letterLabel.textContent = letter;
    group.append(letterLabel);
    items.forEach((entry) => group.append(createClinicalReferenceIndexRow(entry)));
    panel.append(group);
  });

  return panel;
}

