function labTextIncludes(lab = {}, patterns = []) {
  const identities = [lab.name, lab.displayName, ...(lab.aliases || []), ...(lab.abbreviations || [])]
    .map((value) => normalizePharmText(value))
    .filter(Boolean);
  return patterns.some((pattern) => {
    const needle = normalizePharmText(pattern);
    if (!needle) return false;
    return identities.some((identity) => identity === needle || ` ${identity} `.includes(` ${needle} `));
  });
}

function labStructuredSectionProjection(lab = {}) {
  const standard = window.ANI_LEARNER_LANGUAGE_STANDARD;
  if (standard && typeof standard.labStructuredSectionProjection === "function") {
    return standard.labStructuredSectionProjection(lab);
  }
  return Object.freeze({
    schemaVersion: "ani-lab-structured-sections-unavailable",
    recognized: false,
    hasValidAuthoredSections: false,
    suppressGeneratedTeaching: false,
    coverageComplete: false,
    recognizedFields: Object.freeze([]),
    validFields: Object.freeze([]),
    emptyFields: Object.freeze([]),
    malformedFields: Object.freeze([]),
    sections: Object.freeze([]),
    sourceItemCount: 0,
    projectedLeafCount: 0,
    automaticRewritePerformed: false,
    populationSiblingInheritancePerformed: false,
    mutationTargetAuthorized: false
  });
}

function labTeachingSections(lab = {}) {
  if (labStructuredSectionProjection(lab).suppressGeneratedTeaching) return [];
  const name = safeText(lab.name, "this lab");
  if (labTextIncludes(lab, ["calcium", "ionized calcium"])) {
    return [
      ["What this lab tells you", "Calcium reflects neuromuscular excitability, cardiac conduction, parathyroid/vitamin D balance, renal handling, bone metabolism, and albumin binding. Ionized calcium is the physiologically active calcium."],
      ["Low pattern: hypocalcemia", "Think numbness/tingling around the mouth or fingers, muscle cramps, tetany, Chvostek/Trousseau signs, laryngospasm, seizures, prolonged QT, and dysrhythmias. After thyroid/parathyroid surgery, new tingling is a red flag."],
      ["High pattern: hypercalcemia", "Think weakness, constipation, polyuria, dehydration, kidney stones, bone pain, confusion, shortened QT, and dysrhythmias. Cancer, hyperparathyroidism, thiazides, lithium, and excess calcium/vitamin D can be clues."],
      ["Priority nursing actions / treatment direction", "For symptomatic hypocalcemia, protect the airway, use seizure precautions, place on telemetry if severe, verify magnesium, and anticipate calcium replacement such as IV calcium gluconate for severe symptoms. For hypercalcemia, anticipate isotonic fluids, mobility as tolerated, stopping contributors as ordered, and medications such as calcitonin or bisphosphonates when ordered."],
      ["Common NCLEX trap / nuance", "Always connect calcium to ECG changes and neuromuscular safety. Low albumin can make total calcium look low, so corrected calcium or ionized calcium may matter. Magnesium problems can make calcium correction fail."]
    ];
  }

  if (labTextIncludes(lab, ["potassium"])) {
    return [
      ["What this lab tells you", "Potassium is a cardiac conduction and muscle excitability lab. Even small abnormal shifts can matter when the client has renal impairment, digoxin therapy, insulin therapy, diuretics, ACE inhibitors, ARBs, or spironolactone."],
      ["Low pattern: hypokalemia", "Think muscle weakness, cramps, ileus, shallow respirations, U waves, ST depression, flattened T waves, and increased digoxin toxicity risk."],
      ["High pattern: hyperkalemia", "Think peaked T waves, widened QRS, bradycardia, weakness, paresthesias, renal failure, tissue breakdown, potassium-sparing meds, ACE inhibitors/ARBs, or salt substitutes."],
      ["Priority nursing actions / treatment direction", "Place the client on telemetry for dangerous levels or ECG changes, verify renal function and urine output, question potassium administration if urine output is inadequate, and anticipate ordered replacement for low potassium or calcium/insulin-glucose/albuterol/binders/dialysis direction for severe high potassium."],
      ["Common NCLEX trap / nuance", "Insulin shifts potassium into cells but does not remove it from the body. Calcium stabilizes the myocardium in severe hyperkalemia but also does not remove potassium."]
    ];
  }

  if (labTextIncludes(lab, ["sodium"])) {
    return [
      ["What this lab tells you", "Sodium reflects water balance more than salt intake alone. It is a neuro-safety lab tied to fluid volume, SIADH, diabetes insipidus, diuretics, SSRIs, heart failure, and kidney function."],
      ["Low pattern: hyponatremia", "Think headache, confusion, lethargy, nausea, seizures, falls, and worsening mental status. Acute or severe drops are most dangerous."],
      ["High pattern: hypernatremia", "Think dehydration, thirst, dry mucosa, restlessness, irritability, confusion, seizures, diabetes insipidus, or poor access to water."],
      ["Priority nursing actions / treatment direction", "Assess neuro status, seizure precautions for severe abnormalities, strict intake/output, daily weight, and clarify fluid restriction versus fluid replacement based on the cause."],
      ["Common NCLEX trap / nuance", "Do not correct sodium too fast. The board loves symptoms and trends more than a single number."]
    ];
  }

  if (labTextIncludes(lab, ["magnesium"])) {
    return [
      ["What this lab tells you", "Magnesium affects neuromuscular excitability, cardiac rhythm, potassium correction, calcium balance, and magnesium sulfate safety."],
      ["Low pattern: hypomagnesemia", "Think tremors, hyperreflexia, tetany, seizures, torsades risk, and refractory hypokalemia or hypocalcemia."],
      ["High pattern: hypermagnesemia", "Think lethargy, decreased deep tendon reflexes, respiratory depression, hypotension, bradycardia, and cardiac arrest risk."],
      ["Priority nursing actions / treatment direction", "For magnesium sulfate therapy, monitor respirations, deep tendon reflexes, urine output, and level trends. Calcium gluconate is the classic antidote for magnesium toxicity per protocol."],
      ["Common NCLEX trap / nuance", "If potassium will not correct, check magnesium. In maternity, loss of reflexes or respiratory depression during magnesium therapy is urgent."]
    ];
  }

  if (labTextIncludes(lab, ["glucose", "ketone", "beta hydroxybutyrate"])) {
    return [
      ["What this lab tells you", "Glucose and ketone markers connect directly to brain fuel, insulin safety, diabetes control, DKA/HHS patterns, infection stress, nutrition, and medication timing."],
      ["Low pattern / immediate danger", "Hypoglycemia can cause sweating, tremor, tachycardia, confusion, seizure, coma, and injury. Treat the client first, then analyze why it happened."],
      ["High pattern / decompensation clues", "Hyperglycemia with dehydration, ketones, acidosis, Kussmaul respirations, fruity breath, or altered mental status points toward DKA or HHS depending the full pattern."],
      ["Priority nursing actions / treatment direction", "Check mental status and swallowing safety, give fast glucose for symptomatic hypoglycemia per protocol, monitor potassium during insulin therapy, and trend fluids, electrolytes, anion gap, and urine output in DKA/HHS patterns."],
      ["Common NCLEX trap / nuance", "In DKA, potassium may look normal or high at first but total body potassium is depleted; insulin can drop potassium fast."]
    ];
  }

  if (isGfrLab(lab)) {
    return [
      ["What this lab tells you", `${name} estimates kidney filtration and is the main lab anchor for CKD severity. It matters for renal medication dosing, contrast risk, nephrotoxic exposure, fluid/electrolyte safety, and when to escalate kidney decline.`],
      ["CKD stages by eGFR", ckdStageInlineText()],
      ["Concerning pattern", "Falling eGFR with rising creatinine, proteinuria/albuminuria, low urine output, hyperkalemia, fluid overload, acidosis, anemia, or uremic symptoms is more important than one isolated number."],
      ["Priority nursing actions / treatment direction", "Trend intake/output, daily weight, edema, lung sounds, blood pressure, nephrotoxic medications, contrast exposure, and renal dosing. Report rapid eGFR decline, new oliguria, severe electrolyte shifts, or uremic symptoms."],
      ["Common NCLEX trap / nuance", "Stage CKD with eGFR, but do not stop there. The nurse must connect the stage to potassium retention, fluid overload, anemia, bone-mineral disease, drug accumulation, and dialysis/access planning when severe."]
    ];
  }

  if (labTextIncludes(lab, ["bun", "creatinine", "egfr", "urine output", "specific gravity", "urine protein"])) {
    return [
      ["What this lab tells you", `${name} helps the nurse judge kidney perfusion, filtration, hydration, medication clearance, and whether nephrotoxic or renally cleared medications are becoming dangerous.`],
      ["Concerning pattern", "Rising creatinine/eGFR decline, low urine output, dark concentrated urine, proteinuria with hypertension in pregnancy, or kidney injury plus potassium changes should trigger priority thinking."],
      ["Priority nursing actions / treatment direction", "Trend intake/output, daily weight, edema, lung sounds, blood pressure, nephrotoxic medication exposure, contrast exposure, and ordered renal dosing. Report acute declines in urine output or rapid worsening trends."],
      ["Common NCLEX trap / nuance", "Older adults can have deceptively normal creatinine because of low muscle mass. Urine output trend can reveal poor perfusion before a lab looks dramatic."]
    ];
  }

  if (labTextIncludes(lab, ["troponin", "ck mb", "ck", "myoglobin", "bnp", "lactate", "d dimer"])) {
    return [
      ["What this lab tells you", `${name} is a tissue injury, perfusion, clot-risk, or cardiac strain clue. The nurse should connect it to symptoms, vital sign trends, ECG/oxygenation, perfusion, and the timeline of the complaint.`],
      ["Concerning pattern", "Rapid rise, worsening symptoms, hypotension, dyspnea, chest pain, altered mental status, poor urine output, or increasing oxygen demand makes the number more urgent."],
      ["Priority nursing actions / treatment direction", "Assess airway, breathing, circulation, pain, mental status, perfusion, rhythm, and provider/rapid-response criteria. Trend repeat values when ordered because direction matters."],
      ["Common NCLEX trap / nuance", "NCLEX rarely wants a lab in isolation. Pair the abnormal result with the client who is unstable or trending worse."]
    ];
  }

  if (labTextIncludes(lab, ["ast", "alt", "bilirubin", "albumin", "ammonia", "lipase", "amylase"])) {
    return [
      ["What this lab tells you", `${name} helps the nurse connect liver, biliary, pancreatic, nutrition, protein binding, bleeding risk, encephalopathy, or medication toxicity patterns.`],
      ["Concerning pattern", "Jaundice, right upper quadrant pain, dark urine, clay-colored stools, confusion, bleeding, severe abdominal pain radiating to the back, or worsening nausea/vomiting makes these labs more clinically important."],
      ["Priority nursing actions / treatment direction", "Review hepatotoxic drugs, alcohol history, nutrition, coagulation risk, mental status, abdominal assessment, and provider notification thresholds. Protect safety if encephalopathy or bleeding risk is present."],
      ["Common NCLEX trap / nuance", "Albumin affects calcium interpretation and drug binding. Ammonia is about neuro safety, not just a liver number."]
    ];
  }

  if (labTextIncludes(lab, ["hemoglobin", "hematocrit", "platelet", "wbc", "anc", "neutrophil"])) {
    return [
      ["What this lab tells you", `${name} connects to oxygen-carrying capacity, bleeding risk, infection risk, inflammation, chemotherapy safety, bone marrow function, and the need for precautions.`],
      ["Concerning pattern", "Falling hemoglobin/hematocrit with tachycardia or hypotension suggests bleeding or poor oxygen delivery. Low platelets raise bleeding risk. Low WBC/ANC raises infection risk even without a dramatic fever."],
      ["Priority nursing actions / treatment direction", "Assess for bleeding, bruising, petechiae, infection symptoms, oxygenation, fatigue, orthostasis, medication causes, and whether bleeding/neutropenic precautions are indicated."],
      ["Common NCLEX trap / nuance", "Do not call anemia or leukopenia 'normal aging.' In neutropenia, fever can be an emergency."]
    ];
  }

  if (labTextIncludes(lab, ["inr", "aptt", "pt", "fibrinogen"])) {
    return [
      ["What this lab tells you", `${name} helps the nurse evaluate clotting status, anticoagulant effect, bleeding risk, liver synthetic function, DIC patterns, and procedure readiness.`],
      ["Concerning pattern", "Unexpected elevation, active bleeding, bruising, occult blood, sudden headache/neuro change on anticoagulants, or low fibrinogen in a DIC pattern raises priority."],
      ["Priority nursing actions / treatment direction", "Hold/question anticoagulants when ordered parameters are unsafe, assess bleeding, implement fall/bleeding precautions, verify antidote protocols, and report critical values."],
      ["Common NCLEX trap / nuance", "Warfarin tracks with INR; unfractionated heparin commonly tracks with aPTT or anti-Xa depending facility."]
    ];
  }

  if (labTextIncludes(lab, ["ph", "paco2", "hco3", "abg", "oxygen", "spo2"])) {
    return [
      ["What this lab tells you", `${name} connects ventilation, oxygenation, acid-base balance, respiratory compensation, metabolic compensation, and whether the client is tiring out.`],
      ["Concerning pattern", "Worsening pH, rising PaCO2 with decreasing mental status, severe hypoxemia, or increasing work of breathing suggests instability."],
      ["Priority nursing actions / treatment direction", "Assess airway, respiratory rate/effort, lung sounds, oxygen delivery, pulse oximetry trend, mental status, and whether escalation is needed."],
      ["Common NCLEX trap / nuance", "ABG interpretation starts with physiologic stability: oxygenation, ventilation, acid-base direction, compensation, mental status, work of breathing, and whether fatigue or airway failure is developing."]
    ];
  }

  if (labTextIncludes(lab, ["digoxin", "lithium", "phenytoin", "valproic", "vancomycin", "therapeutic"])) {
    return [
      ["What this lab tells you", `${name} is a narrow-therapeutic-index safety check. Toxicity can happen when levels rise, renal/hepatic clearance changes, interacting drugs are added, or dehydration occurs.`],
      ["Concerning pattern", "Neuro changes, GI symptoms, dysrhythmias, tremor, ataxia, visual changes, worsening renal function, or a level above the facility target should prompt hold/question thinking."],
      ["Priority nursing actions / treatment direction", "Verify timing of the level, renal/hepatic function, current symptoms, interacting medications, and ordered hold parameters before giving the next dose."],
      ["Common NCLEX trap / nuance", "A therapeutic level does not override a toxic-looking patient. Treat the client and the trend."]
    ];
  }

  return [];
}

function labProjectedTeachingSections(lab = {}) {
  const authored = labStructuredSectionProjection(lab);
  if (authored.suppressGeneratedTeaching) {
    return authored.sections.map((section) => ({
      ...section,
      kind: "authored-structured",
      authoredStructured: true,
      generatedTeaching: false,
      structuredSchema: authored.schemaVersion,
      structuredCoverageComplete: authored.coverageComplete === true
    }));
  }
  return labTeachingSections(lab).map(([label, value], index) => {
    const text = safeText(value);
    const path = `generatedLabTeachingSections.${index}`;
    return {
      key: "",
      label,
      path,
      sourceIndex: index,
      safetyVisible: /(?:critical|urgent|danger|concerning|red flag|priority action|safety)/i.test(label),
      items: text ? [{ field: "", fieldPath: path, path: `${path}.0`, index: 0, text }] : [],
      value,
      text,
      learnerText: text,
      kind: "generated-keyword",
      authoredStructured: false,
      generatedTeaching: true,
      structuredSchema: ""
    };
  });
}

function labVisibleLearnerSections(lab = {}) {
  const sections = [
    {
      key: "range",
      label: "Reference range / threshold",
      value: lab.range,
      path: "range",
      learnerText: lab.range
    },
    {
      key: "why",
      label: "Why every nurse should know it",
      value: lab.why,
      path: "why",
      learnerText: lab.why
    },
    {
      key: "groupNote",
      label: "Population note",
      value: lab.groupNote,
      path: "groupNote",
      learnerText: lab.groupNote
    },
    ...labProjectedTeachingSections(lab),
    {
      key: "nclexUse",
      label: "NCLEX use",
      value: "Use the range as a cue, then connect it to the client trend, symptoms, medication risks, and whether the nurse should hold, question, monitor, or intervene.",
      path: "runtimeSupport.nclexUse",
      learnerText: ""
    },
    {
      key: "studySafetyNote",
      label: "Study safety note",
      value: "Ranges can vary by facility, age, pregnancy status, specimen type, and lab method. Use these numbers as NCLEX study anchors and verify the printed lab reference range in real care.",
      path: "runtimeSupport.studySafetyNote",
      learnerText: ""
    }
  ];
  return sections.map((section, index) => ({
    ...section,
    id: `lab-visible-section-${index + 1}`,
    sourceIndex: index,
    safetyVisible: section.safetyVisible === true
  }));
}

function appendLabStructuredSectionItems(parent, section = {}, options = {}) {
  const items = Array.isArray(section.items)
    ? section.items.filter((item) => safeText(item && item.text))
    : [];
  parent.dataset.structuredSchema = safeText(section.structuredSchema || "ani-lab-structured-sections-v1");
  parent.dataset.structuredKind = "list";
  parent.dataset.structuredCoverage = section.structuredCoverageComplete === false ? "incomplete" : "complete";
  parent.dataset.structuredLeafCount = String(items.length);
  parent.dataset.rootPath = safeText(section.path);
  if (!items.length) return 0;
  const list = document.createElement("ul");
  list.className = "pharm-readable-list lab-structured-section-list";
  items.forEach((item) => {
    const li = document.createElement("li");
    li.dataset.leafPath = safeText(item.path);
    appendPharmDetailText(li, item.text, options);
    list.append(li);
  });
  parent.append(list);
  return items.length;
}

function renderPharmLabDetail(lab = activePharmLabResults[0]) {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  setPharmDetailTheme("labs");
  if (!lab) {
    renderPharmDrugDetail(null);
    return;
  }

  const title = document.createElement("div");
  title.className = "pharm-detail-title";
  const name = document.createElement("h2");
  name.textContent = safeText(lab.name);
  const category = document.createElement("span");
  category.textContent = safeText([lab.category, lab.populationGroup && lab.populationGroup !== lab.category ? lab.populationGroup : ""].filter(Boolean).join(" | "));
  title.append(name, category);
  appendPharmFavoriteButton(title, "labs", lab);
  pharmDrugDetail.append(title);

  const learnerSections = labVisibleLearnerSections(lab);
  const sections = learnerSections.map(({ label, value }) => [label, value]);
  const learnerProjection = projectVisibleLearnerSupport(lab, learnerSections, { prefix: "lab-visible-section" });
  const firstLearnerBlockId = learnerProjection.blocks[0]?.id || "";

  let treatmentMedicationsAppended = false;
  let authoredPresentationAttempted = false;
  learnerSections.forEach((learnerSection) => {
    const {
      id, key, label, value, path, items, authoredStructured, structuredSchema,
      structuredCoverageComplete, safetyVisible
    } = learnerSection;
    if (!value) return;
    const section = document.createElement("section");
    section.dataset.labSectionKey = safeText(key);
    section.dataset.labSectionPath = safeText(path);
    if (safetyVisible) section.dataset.safetyVisible = "true";
    const heading = document.createElement("strong");
    heading.textContent = label;
    const text = document.createElement("div");
    text.className = "pharm-detail-text";
    if (authoredStructured) {
      appendLabStructuredSectionItems(text, {
        ...learnerSection,
        items,
        structuredSchema,
        structuredCoverageComplete
      }, { currentLabel: lab.name });
    } else {
      appendReadableDetailText(text, value, { currentLabel: lab.name });
    }
    section.append(heading, text);
    pharmDrugDetail.append(section);
    const learnerBlock = learnerProjection.byId.get(id);
    if (learnerBlock) {
      appendLearnerLanguageSupport(pharmDrugDetail, lab, {
        currentLabel: lab.name,
        projectedBlock: learnerBlock,
        includePlainLanguage: learnerBlock.id === firstLearnerBlockId,
        heading: learnerBlock.id === firstLearnerBlockId ? "Medical terms explained" : "Terms in this section"
      });
    }
    if (label === "Reference range / threshold") {
      appendAuthoredPresentationVisuals(lab);
      authoredPresentationAttempted = true;
      appendMemoryBridgeSections(pharmDrugDetail, lab);
    }
  });
  if (!authoredPresentationAttempted) appendAuthoredPresentationVisuals(lab);
  if (isGfrLab(lab)) {
    pharmDrugDetail.append(buildCkdStageDetailSection());
  }
  appendMedicalAbbreviationSection(pharmDrugDetail, [
    lab.name,
    lab.category,
    lab.populationGroup,
    lab.sourceType,
    lab.range,
    lab.why,
    lab.groupNote,
    labProjectedTeachingSections(lab).map((section) => section.value)
  ]);
  appendMedicalTermTeachingSection(pharmDrugDetail, lab);
  appendHighYieldImageSection(pharmDrugDetail, lab, "labs");

  appendExploreRelatedConcepts(pharmDrugDetail, [
    lab.name,
    lab.category,
    lab.populationGroup,
    lab.range,
    lab.why,
    lab.groupNote,
    sections
  ], lab.name);
  syncPharmDetailReadableText();
}

function memoryBridgeStatusLabel(status = "") {
  const labels = {
    current: "Current clinical framework",
    limited: "Limited memory aid",
    historical: "Historical grouping",
    "current-clinical-framework": "Current clinical framework",
    "documentation-shorthand": "Documentation shorthand",
    "exam-oriented-memory-aid": "Exam-oriented memory aid",
    "historical-grouping": "Historical grouping"
  };
  return labels[safeText(status)] || "Reviewed memory aid";
}

function memoryBridgeLines(value = []) {
  return (Array.isArray(value) ? value : [value])
    .map((item) => safeText(item))
    .filter(Boolean);
}

function appendMemoryBridgeTextBlock(container, label, value, className = "", options = {}) {
  const lines = memoryBridgeLines(value);
  if (!lines.length) return;
  const block = document.createElement("div");
  block.className = ["pharm-memory-bridge-block", className].filter(Boolean).join(" ");
  const text = document.createElement("div");
  text.className = "pharm-detail-text";
  appendReadableDetailText(text, lines, { currentLabel: label });
  if (options.disclosure) {
    const details = document.createElement("details");
    details.className = "pharm-memory-bridge-disclosure";
    details.open = options.defaultOpen === true;
    const summary = document.createElement("summary");
    summary.textContent = label;
    summary.dataset.skipRead = "true";
    details.append(summary, text);
    block.append(details);
  } else {
    const heading = document.createElement("b");
    heading.textContent = label;
    block.append(heading, text);
  }
  container.append(block);
}

function appendMemoryBridgeSections(container, entry = {}) {
  const mnemonicCatalog = window.ANI_NURSING_MEMORY_BRIDGES || {};
  const referencesByKey = new Map((Array.isArray(mnemonicCatalog.sourceReferences) ? mnemonicCatalog.sourceReferences : [])
    .map((reference) => [safeText(reference && reference.key), reference])
    .filter(([key]) => key));
  const bridges = Array.isArray(entry && entry.memoryBridges)
    ? entry.memoryBridges.filter((bridge) => bridge && typeof bridge === "object")
    : [];
  const compactPresentation = entry?.presentation?.schemaVersion === "ani-card-presentation-v1";
  bridges.forEach((bridge) => {
    const section = document.createElement("section");
    section.className = "pharm-memory-bridge-section";
    if (bridge.id) section.dataset.memoryBridgeId = safeText(bridge.id);

    const header = document.createElement("div");
    header.className = "pharm-memory-bridge-header";
    const heading = document.createElement("strong");
    heading.textContent = `Memory bridge — ${safeText(bridge.cue || bridge.title || "study cue")}`;
    const badge = document.createElement("span");
    badge.className = "pharm-memory-bridge-status";
    badge.textContent = memoryBridgeStatusLabel(bridge.status);
    header.append(heading, badge);
    section.append(header);

    appendMemoryBridgeTextBlock(section, "Remember this", bridge.recallTarget);

    const expansionRows = Array.isArray(bridge.orderedExpansion) ? bridge.orderedExpansion : bridge.expansion;
    const expansion = Array.isArray(expansionRows)
      ? expansionRows.filter((item) => item && (item.key || item.cue || item.label || item.meaning))
      : [];
    if (expansion.length) {
      const list = document.createElement("ol");
      list.className = "pharm-memory-bridge-expansion";
      expansion.forEach((item) => {
        const row = document.createElement("li");
        const term = document.createElement("b");
        const cue = safeText(item.key || item.cue || item.label);
        const meaning = safeText(item.meaning || item.label);
        term.textContent = cue;
        row.append(term);
        if (meaning && normalizePharmText(meaning) !== normalizePharmText(cue)) {
          const explanation = document.createElement("span");
          explanation.textContent = ` — ${meaning}`;
          row.append(explanation);
        }
        const why = safeText(item.why);
        if (why) row.append(document.createTextNode(`: ${why}`));
        list.append(row);
      });
      if (compactPresentation) {
        const details = document.createElement("details");
        details.className = "pharm-memory-bridge-disclosure pharm-memory-bridge-expansion-disclosure";
        const summary = document.createElement("summary");
        summary.dataset.skipRead = "true";
        summary.textContent = "Open mnemonic breakdown";
        details.append(summary, list);
        section.append(details);
      } else {
        section.append(list);
      }
    }

    appendMemoryBridgeTextBlock(section, "Why the pieces connect", bridge.whyItWorks || bridge.why, "", { disclosure: true });
    appendMemoryBridgeTextBlock(section, "Nursing use", bridge.nursingApplication, "", { disclosure: compactPresentation });
    appendMemoryBridgeTextBlock(section, "What this does not tell you", bridge.limitations, "is-limitation", { disclosure: true });
    appendMemoryBridgeTextBlock(section, "Urgent exception", bridge.urgentExceptions, "is-urgent");
    const clinicalSources = (Array.isArray(bridge.clinicalSourceKeys) ? bridge.clinicalSourceKeys : [])
      .map((key) => referencesByKey.get(safeText(key)))
      .filter((reference) => reference && (reference.evidenceRole === "clinical" || reference.kind === "clinical-authority"));
    if (clinicalSources.length) {
      const sourceLine = document.createElement("div");
      sourceLine.className = "pharm-memory-bridge-sources";
      sourceLine.dataset.skipRead = "true";
      sourceLine.textContent = `Clinical review: ${clinicalSources.map((reference) => safeText(reference.authority || reference.label || reference.title)).filter(Boolean).join("; ")}.`;
      section.append(sourceLine);
    }
    container.append(section);
  });
}

function createSvgElement(tagName, attrs = {}) {
  const element = document.createElementNS("http://www.w3.org/2000/svg", tagName);
  Object.entries(attrs).forEach(([key, value]) => {
    if (value === undefined || value === null) return;
    element.setAttribute(key, String(value));
  });
  return element;
}

function chartTicks(min = 0, max = 1, step = 1) {
  const ticks = [];
  const safeStep = Math.max(Number(step) || 1, 1);
  for (let value = min; value <= max + 0.0001; value += safeStep) {
    ticks.push(Number(value.toFixed(2)));
  }
  return ticks;
}

function compactVisualText(value = "", maxLength = 170) {
  return safeText(value).replace(/\*\*/g, "").replace(/\s+/g, " ").trim();
}

function flowNodeTextParts(value = "", maxLength = 260) {
  const text = compactVisualText(value);
  if (text.length <= maxLength) {
    return { essential: text, extra: "" };
  }

  const sentences = text.match(/[^.!?]+(?:[.!?]+|$)/g) || [];
  let essential = "";
  sentences.some((sentence) => {
    const cleanSentence = sentence.trim();
    if (!cleanSentence) return false;
    const next = [essential, cleanSentence].filter(Boolean).join(" ");
    if (!essential || next.length <= maxLength) {
      essential = next;
      return false;
    }
    return true;
  });

  if (!essential || essential.length >= text.length - 3) {
    return { essential: text, extra: "" };
  }

  return {
    essential,
    extra: text.slice(essential.length).replace(/^[\s:;,.]+/, "").trim()
  };
}

function firstMatchingClinicalSection(sections = [], patterns = []) {
  const match = sections.find(([label, value]) => (
    value && patterns.some((pattern) => pattern.test(`${label} ${value}`))
  ));
  return match ? safeText(match[1]) : "";
}

function makeClinicalReferenceFlowVisualData(entry = {}) {
  const sections = clinicalReferenceSectionPairs(entry);
  const quick = safeText(entry.quickAnswer || entry.summary);
  const nodes = [
    {
      label: "Why it is done",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/why|interpretation|what it checks|evaluates|measure/i]) || quick)
    },
    {
      label: "Before",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/before|prep|prepare|consent|verify/i]) || "Verify order, consent if required, allergies, bleeding risk, baseline assessment, and safety preparation.")
    },
    {
      label: "During",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/during|perform|collection|specimen|position/i]) || "Protect airway, perfusion, sterile/clean technique, correct specimen handling, and patient tolerance.")
    },
    {
      label: "After",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/after|monitor|recovery|post/i]) || "Monitor vital signs, site or airway status, pain, bleeding, infection cues, sedation recovery, and ordered follow-up.")
    },
    {
      label: "Red flags",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/red flag|urgent|danger|report|complication/i]) || "Escalate new instability, bleeding, severe pain, respiratory distress, neuro change, infection cues, or unexpected deterioration.")
    },
    {
      label: "NCLEX trap",
      detail: compactVisualText(firstMatchingClinicalSection(sections, [/trap|nclex/i]) || "Do not memorize the test alone. Know the safety action before, during, and after it.")
    }
  ].filter((node) => node.detail);

  return {
    title: `${clinicalReferenceDisplayName(entry)} safety flow`,
    subtitle: "Visual sequence for quick NCLEX-style recall",
    theme: "procedure",
    nodes
  };
}

function makePathologyFlowVisualData(disease = {}) {
  const nodes = [
    {
      label: "Pathophysiology",
      detail: compactVisualText(disease.pathology)
    },
    {
      label: "Findings",
      detail: compactVisualText(pathologyListText(disease.signsSymptoms))
    },
    {
      label: "Diagnostics",
      detail: compactVisualText(pathologyListText(disease.diagnostics))
    },
    {
      label: "Treatment",
      detail: compactVisualText(pathologyListText(disease.treatments))
    },
    {
      label: "Nursing priority",
      detail: compactVisualText(pathologyListText(disease.nursingPriorities))
    },
    {
      label: "Watch for",
      detail: compactVisualText(pathologyListText(disease.complications) || pathologyListText(disease.nclexTraps))
    }
  ].filter((node) => node.detail);

  return {
    title: `${safeText(disease.name)} clinical pathway`,
    subtitle: "From disease process to what the nurse watches next",
    theme: "pathology",
    nodes
  };
}

function buildClinicalFlowVisual(flow = {}) {
  const section = document.createElement("section");
  section.className = "pharm-flow-visual";
  // The ordinary card sections already contain this teaching content. Keep
  // visual numbering and "More detail" controls out of spoken narration.
  section.dataset.skipRead = "true";
  section.dataset.theme = safeText(flow.theme || "clinical");
  section.dataset.readableText = [
    flow.title,
    flow.subtitle,
    ...(flow.nodes || []).map((node) => `${node.label}: ${node.detail}`)
  ].filter(Boolean).join(". ");

  const header = document.createElement("div");
  header.className = "pharm-flow-header";
  const title = document.createElement("strong");
  title.textContent = safeText(flow.title || "Clinical visual aid");
  const subtitle = document.createElement("span");
  subtitle.textContent = safeText(flow.subtitle || "Trace the sequence and priority cues.");
  header.append(title, subtitle);

  const track = document.createElement("div");
  track.className = "pharm-flow-track";
  (flow.nodes || []).slice(0, 6).forEach((node, index) => {
    const card = document.createElement("article");
    card.className = "pharm-flow-node";
    const marker = document.createElement("span");
    marker.className = "pharm-flow-marker";
    marker.textContent = String(index + 1);
    const nodeTitle = document.createElement("strong");
    nodeTitle.textContent = safeText(node.label);
    const nodeText = flowNodeTextParts(node.detail);
    const text = document.createElement("p");
    appendPharmDetailText(text, nodeText.essential, { currentLabel: flow.title });
    card.append(marker, nodeTitle, text);
    if (nodeText.extra) {
      const more = document.createElement("details");
      more.className = "pharm-flow-more";
      const summary = document.createElement("summary");
      summary.textContent = "More detail";
      const fullText = document.createElement("p");
      appendPharmDetailText(fullText, nodeText.extra, { currentLabel: flow.title });
      more.append(summary, fullText);
      card.append(more);
    }
    track.append(card);
  });

  section.append(header, track);
  return section;
}

function buildPercentileCurveVisual(visual = {}) {
  const section = document.createElement("section");
  section.className = "pharm-growth-visual";
  section.dataset.readableText = [
    visual.title,
    visual.subtitle,
    visual.footer
  ].filter(Boolean).join(". ");

  const heading = document.createElement("strong");
  heading.textContent = safeText(visual.title || "Percentile chart");

  const subtitle = document.createElement("p");
  subtitle.className = "pharm-growth-visual-subtitle";
  subtitle.textContent = safeText(visual.subtitle || "Percentile curve study anchor");

  const card = document.createElement("div");
  card.className = "pharm-growth-chart-card";

  const width = 640;
  const height = 330;
  const margin = { top: 22, right: 24, bottom: 48, left: 58 };
  const plotWidth = width - margin.left - margin.right;
  const plotHeight = height - margin.top - margin.bottom;
  const xMin = Number(visual.xMin ?? 0);
  const xMax = Number(visual.xMax ?? 1);
  const yMin = Number(visual.yMin ?? 0);
  const yMax = Number(visual.yMax ?? 1);
  const xScale = (x) => margin.left + ((Number(x) - xMin) / Math.max(1, xMax - xMin)) * plotWidth;
  const yScale = (y) => margin.top + (1 - ((Number(y) - yMin) / Math.max(1, yMax - yMin))) * plotHeight;

  const svg = createSvgElement("svg", {
    viewBox: `0 0 ${width} ${height}`,
    role: "img",
    "aria-label": safeText(`${visual.title || "Percentile chart"}: ${visual.subtitle || ""}`)
  });
  svg.classList.add("pharm-growth-chart");

  const grid = createSvgElement("g", { class: "pharm-growth-grid" });
  chartTicks(yMin, yMax, visual.yStep || 10).forEach((tick) => {
    const y = yScale(tick);
    grid.append(createSvgElement("line", { x1: margin.left, x2: width - margin.right, y1: y, y2: y }));
    const label = createSvgElement("text", { x: margin.left - 10, y: y + 4, "text-anchor": "end" });
    label.textContent = String(tick);
    grid.append(label);
  });
  chartTicks(xMin, xMax, visual.xStep || 1).forEach((tick) => {
    const x = xScale(tick);
    grid.append(createSvgElement("line", { x1: x, x2: x, y1: margin.top, y2: height - margin.bottom }));
    const label = createSvgElement("text", { x, y: height - margin.bottom + 22, "text-anchor": "middle" });
    label.textContent = String(tick);
    grid.append(label);
  });
  svg.append(grid);

  const axis = createSvgElement("g", { class: "pharm-growth-axis" });
  axis.append(createSvgElement("line", { x1: margin.left, x2: width - margin.right, y1: height - margin.bottom, y2: height - margin.bottom }));
  axis.append(createSvgElement("line", { x1: margin.left, x2: margin.left, y1: margin.top, y2: height - margin.bottom }));
  const xAxisLabel = createSvgElement("text", { x: margin.left + plotWidth / 2, y: height - 10, "text-anchor": "middle" });
  xAxisLabel.textContent = safeText(visual.xLabel || "Age");
  const yAxisLabel = createSvgElement("text", {
    x: 16,
    y: margin.top + plotHeight / 2,
    transform: `rotate(-90 16 ${margin.top + plotHeight / 2})`,
    "text-anchor": "middle"
  });
  yAxisLabel.textContent = safeText(visual.yLabel || "Value");
  axis.append(xAxisLabel, yAxisLabel);
  svg.append(axis);

  const curves = createSvgElement("g", { class: "pharm-growth-curves" });
  (visual.series || []).forEach((series) => {
    const points = (series.points || [])
      .map(([x, y]) => `${xScale(x).toFixed(1)},${yScale(y).toFixed(1)}`)
      .join(" ");
    if (!points) return;
    const polyline = createSvgElement("polyline", {
      class: `pharm-growth-line ${safeText(series.className || "").replace(/[^a-z0-9_-]/gi, "")}`,
      points
    });
    curves.append(polyline);
    (series.points || []).forEach(([x, y]) => {
      curves.append(createSvgElement("circle", {
        class: `pharm-growth-point ${safeText(series.className || "").replace(/[^a-z0-9_-]/gi, "")}`,
        cx: xScale(x).toFixed(1),
        cy: yScale(y).toFixed(1),
        r: series.className === "p50" ? 4.2 : 3.4
      }));
    });
  });
  svg.append(curves);

  const legend = document.createElement("div");
  legend.className = "pharm-growth-legend";
  (visual.series || []).forEach((series) => {
    const item = document.createElement("span");
    item.className = `pharm-growth-legend-item ${safeText(series.className || "").replace(/[^a-z0-9_-]/gi, "")}`;
    const swatch = document.createElement("i");
    const label = document.createElement("b");
    label.textContent = safeText(series.label);
    item.append(swatch, label);
    legend.append(item);
  });

  card.append(svg, legend);
  const footer = document.createElement("p");
  footer.className = "pharm-growth-chart-note";
  appendPharmDetailText(footer, visual.footer || "Use percentile curves as trend anchors, not isolated diagnostic cutoffs.", { currentLabel: visual.title });
  section.append(heading, subtitle, card, footer);
  return section;
}

const ANI_CARD_PRESENTATION_SCHEMA = "ani-card-presentation-v1";

function clinicalReferenceVisualSource(entry = {}, field = "") {
  const key = safeText(field);
  if (!/^[A-Za-z][A-Za-z0-9_]*$/.test(key)) return undefined;
  return entry[key];
}

function clinicalReferenceVisualHeading(section, visual = {}) {
  const heading = document.createElement("h2");
  heading.className = "pharm-learning-visual-title";
  heading.textContent = safeText(visual.title || "Visual study guide");
  if (visual.id) heading.id = `ani-visual-${safeText(visual.id).replace(/[^a-z0-9_-]+/gi, "-")}`;
  section.append(heading);
  return heading;
}

function clinicalReferenceVisualIntro(section, visual = {}, readableText = "") {
  const intro = document.createElement("div");
  intro.className = "pharm-detail-text pharm-learning-visual-intro";
  const introText = safeText(visual.narrationSummary || visual.intro)
    || "Use this structured view to scan the key information before opening the full detail.";
  appendReadableDetailText(intro, introText, {
    currentLabel: visual.title
  });
  // Read-aloud uses the concise authored intro. The complete visual source
  // remains available on screen without being narrated a second time.
  intro.dataset.readableText = introText;
  section.append(intro);
  return intro;
}

function aniPreferredScrollBehavior() {
  return window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches ? "auto" : "smooth";
}

function splitPresentationLabel(value = "") {
  const text = safeText(value);
  const separator = text.indexOf(":");
  if (separator <= 0 || separator > 90) return { label: "Key point", detail: text };
  return {
    label: text.slice(0, separator).trim(),
    detail: text.slice(separator + 1).trim()
  };
}

function presentationDetailRemainder(summary = "", detail = "") {
  const short = safeText(summary);
  const full = safeText(detail);
  if (!short || !full) return full;
  if (full.startsWith(short)) return full.slice(short.length).replace(/^[\s:;,.-]+/, "").trim();
  return full;
}

function appendClinicalReferenceVisualDisclosure(section, visual = {}, content, itemCount = 0) {
  if (visual.defaultOpen !== false) {
    section.append(content);
    return;
  }
  const details = document.createElement("details");
  details.className = "pharm-learning-visual-disclosure";
  details.open = false;
  const summary = document.createElement("summary");
  summary.dataset.skipRead = "true";
  summary.textContent = `Open ${safeText(visual.title || "details")}${itemCount ? ` (${itemCount})` : ""}`;
  details.append(summary, content);
  section.append(details);
}

function buildClinicalReferenceKeyValueVisual(entry = {}, visual = {}) {
  const source = clinicalReferenceVisualSource(entry, visual.sourceField);
  if (!source || typeof source !== "object" || Array.isArray(source)) return null;
  const rows = Object.entries(source).filter(([, value]) => safeText(value));
  if (!rows.length) return null;
  const section = document.createElement("section");
  section.className = "pharm-learning-visual pharm-learning-key-value";
  section.dataset.visualId = safeText(visual.id);
  clinicalReferenceVisualHeading(section, visual);
  const readable = rows.map(([key, value]) => `${safeText(visual.labels?.[key] || key)}: ${safeText(value)}`).join("\n");
  clinicalReferenceVisualIntro(section, visual, readable);
  const grid = document.createElement("div");
  grid.className = "pharm-learning-key-value-grid";
  rows.forEach(([key, value]) => {
    const card = document.createElement("article");
    card.className = "pharm-learning-key-value-card";
    const label = document.createElement("h3");
    label.textContent = safeText(visual.labels?.[key] || key);
    const detail = document.createElement("div");
    detail.className = "pharm-detail-text";
    appendReadableDetailText(detail, value, { currentLabel: clinicalReferenceDisplayName(entry) });
    card.append(label, detail);
    grid.append(card);
  });
  appendClinicalReferenceVisualDisclosure(section, visual, grid, rows.length);
  return section;
}

function clinicalReferenceTimelineTarget(record = {}) {
  const targetId = safeText(record.targetId);
  const targetName = safeText(record.targetName || record.label);
  const targetCollection = safeText(record.targetCollection);
  const targetType = safeText(record.targetType);
  const hasStableIdentity = Boolean(targetId && targetName);
  const hasCollectionIdentity = Boolean(targetCollection && targetName);
  if (!hasStableIdentity && !hasCollectionIdentity) return null;
  const collectionMatches = (collectionName = "") => !targetCollection
    || collectionName === targetCollection
    || (collectionName === "labValues" && targetCollection === "pharmSearchableLabRanges");
  const matches = microbiologyRuntimeCollections()
    .filter((collection) => collectionMatches(collection.targetCollection))
    .filter((collection) => !targetType || collection.type === targetType)
    .flatMap((collection) => collection.items
      .filter((item) => {
        const idMatches = !targetId || microbiologyStableRuntimeIds(item).includes(targetId);
        const nameMatches = normalizePharmText(microbiologyCanonicalRuntimeTitle(item)) === normalizePharmText(targetName);
        return idMatches && nameMatches;
      })
      .map((item) => ({ type: collection.type, item })));
  return matches.length === 1 ? matches[0] : null;
}

function buildClinicalReferenceTimelineVisual(entry = {}, visual = {}) {
  const rows = clinicalReferenceVisualSource(entry, visual.sourceField);
  if (!Array.isArray(rows) || !rows.length) return null;
  const fields = visual.fields || {};
  const rowKeyField = safeText(fields.rowKey || "sequence");
  const titleField = safeText(fields.title || "title");
  const badgeField = safeText(fields.badge || "class");
  const summaryField = safeText(fields.summary || "summary");
  const detailField = safeText(fields.detail || "text");
  const memoryCueField = safeText(fields.memoryCue || "memoryCue");
  const joinField = safeText(visual.linkJoinField || rowKeyField);
  const targetRecords = clinicalReferenceVisualSource(entry, visual.linkSourceField);
  const links = Array.isArray(targetRecords) ? targetRecords : [];
  const rowByKey = new Map(rows.map((row) => [String(row?.[rowKeyField]), row]));
  const configuredGroups = Array.isArray(visual.groups) && visual.groups.length
    ? visual.groups
    : [{
      id: "all",
      label: visual.title || "Timeline",
      rowKeys: rows.map((row) => row?.[rowKeyField]),
      defaultOpen: visual.defaultOpen !== false
    }];
  const orderedGroups = configuredGroups.map((group) => ({
    ...group,
    rows: (Array.isArray(group.rowKeys) ? group.rowKeys : []).map((key) => rowByKey.get(String(key))).filter(Boolean)
  })).filter((group) => group.rows.length);
  if (!orderedGroups.length) return null;
  const labels = visual.labels && typeof visual.labels === "object" ? visual.labels : {};
  const navigationLabel = safeText(labels.navigation || `${visual.title || "Structured timeline"} sections`);
  const checkpointLabel = safeText(labels.checkpoint || "checkpoint");
  const captionText = safeText(labels.caption || "Structured sequence with exact links to related ANI cards.");
  const columns = Array.isArray(labels.columns) && labels.columns.length === 4
    ? labels.columns.map(safeText)
    : ["Stage", "Category", "Related topics", "Key point"];
  const linkedTopicsLabel = safeText(labels.linkedTopics || "Related topics");
  const detailDisclosureLabel = safeText(labels.detailDisclosure || "More detail and rationale");

  const section = document.createElement("section");
  section.className = "pharm-learning-visual pharm-learning-timeline";
  section.dataset.visualId = safeText(visual.id);
  section.dataset.mobileMode = safeText(visual.mobileMode);
  const heading = clinicalReferenceVisualHeading(section, visual);
  const readableRows = orderedGroups.flatMap((group) => group.rows.map((row) => {
    const key = row?.[rowKeyField];
    const rowLinks = links.filter((record) => String(record?.[joinField]) === String(key));
    const cue = row?.[memoryCueField];
    return [
      group.label,
      row?.[titleField],
      row?.[badgeField],
      rowLinks.length ? `Vaccines: ${rowLinks.map((record) => safeText(record.targetName || record.label)).join(", ")}.` : "",
      row?.[summaryField],
      presentationDetailRemainder(row?.[summaryField], row?.[detailField]),
      cue && typeof cue === "object" ? `${safeText(cue.cue)}: ${safeText(cue.meaning)}` : safeText(cue)
    ].filter(Boolean).join(" ");
  })).join("\n");
  clinicalReferenceVisualIntro(section, visual, readableRows);

  const jump = document.createElement("nav");
  jump.className = "pharm-learning-stage-nav";
  jump.setAttribute("aria-label", navigationLabel);
  orderedGroups.forEach((group) => {
    const button = document.createElement("button");
    button.type = "button";
    button.textContent = safeText(group.label);
    button.addEventListener("click", () => {
      const target = document.getElementById(`ani-stage-${safeText(visual.id)}-${safeText(group.id)}`);
      if (target && "open" in target) target.open = true;
      target?.scrollIntoView?.({ block: "start", behavior: aniPreferredScrollBehavior() });
    });
    jump.append(button);
  });
  section.append(jump);

  const stageList = document.createElement("div");
  stageList.className = "pharm-learning-stage-list";
  orderedGroups.forEach((group) => {
    const stage = document.createElement("details");
    stage.className = "pharm-learning-stage-disclosure";
    stage.id = `ani-stage-${safeText(visual.id)}-${safeText(group.id)}`;
    stage.open = group.defaultOpen !== false;
    const stageSummary = document.createElement("summary");
    stageSummary.dataset.skipRead = "true";
    stageSummary.textContent = `${safeText(group.label)} (${group.rows.length} ${checkpointLabel}${group.rows.length === 1 ? "" : "s"})`;
    stage.append(stageSummary);

    const wrap = document.createElement("div");
    wrap.className = "pharm-learning-table-wrap";
    const table = document.createElement("table");
    table.className = "pharm-learning-timeline-table";
    table.setAttribute("aria-labelledby", heading.id);
    const caption = document.createElement("caption");
    caption.textContent = `${safeText(group.label)}: ${captionText}`;
    const thead = document.createElement("thead");
    const headerRow = document.createElement("tr");
    columns.forEach((label) => {
      const th = document.createElement("th");
      th.scope = "col";
      th.textContent = label;
      headerRow.append(th);
    });
    thead.append(headerRow);
    const tbody = document.createElement("tbody");

    group.rows.forEach((row) => {
      const key = row?.[rowKeyField];
      const tr = document.createElement("tr");
      tr.className = "pharm-learning-timeline-row";
      tr.dataset.rowKey = String(key ?? "");
      const age = document.createElement("th");
      age.scope = "row";
      age.dataset.label = columns[0];
      age.textContent = safeText(row?.[titleField]);

      const recommendation = document.createElement("td");
      recommendation.dataset.label = columns[1];
      const badge = document.createElement("span");
      badge.className = "pharm-learning-recommendation-badge";
      badge.textContent = safeText(row?.[badgeField]);
      recommendation.append(badge);

      const vaccines = document.createElement("td");
      vaccines.dataset.label = columns[2];
      const chipList = document.createElement("div");
      chipList.className = "pharm-learning-vaccine-chips";
      links.filter((record) => String(record?.[joinField]) === String(key)).forEach((record) => {
        const targetCandidate = clinicalReferenceTimelineTarget(record);
        const target = targetCandidate?.item || null;
        const label = safeText(record.targetName || record.label);
        const chip = document.createElement(target ? "button" : "span");
        chip.className = `pharm-learning-vaccine-chip${target ? "" : " is-unresolved"}`;
        chip.textContent = label;
        chip.dataset.targetId = safeText(record.targetId);
        chip.dataset.targetName = label;
        if (target) {
          chip.type = "button";
          chip.setAttribute("aria-label", `Open ${label} in ANI encyclopedia`);
          chip.addEventListener("click", (event) => {
            event.preventDefault();
            event.stopPropagation();
            openPharmDatabase(label, {
              openDetail: true,
              autoFocus: false,
              detailType: targetCandidate.type,
              fastDetail: true,
              targetCandidate
            });
          });
        }
        chipList.append(chip);
      });
      if (!chipList.children.length) {
        const emptyLinks = document.createElement("span");
        emptyLinks.className = "pharm-learning-no-related-links";
        emptyLinks.textContent = `No ${linkedTopicsLabel.toLowerCase()} are authored for this row.`;
        chipList.append(emptyLinks);
      }
      vaccines.append(chipList);

      const teaching = document.createElement("td");
      teaching.dataset.label = columns[3];
      const summary = document.createElement("p");
      summary.className = "pharm-learning-timeline-summary";
      appendReadableDetailText(summary, row?.[summaryField], { currentLabel: clinicalReferenceDisplayName(entry) });
      teaching.append(summary);
      const cue = row?.[memoryCueField];
      if (cue) {
        const cueBox = document.createElement("aside");
        cueBox.className = "pharm-learning-memory-cue";
        const cueLabel = document.createElement("b");
        cueLabel.textContent = safeText(cue.cue || "Memory cue");
        const cueMeaning = document.createElement("span");
        cueMeaning.textContent = safeText(cue.meaning || cue);
        cueBox.append(cueLabel, cueMeaning);
        teaching.append(cueBox);
      }
      const detailText = presentationDetailRemainder(row?.[summaryField], row?.[detailField]);
      if (detailText) {
        const details = document.createElement("details");
        details.className = "pharm-learning-row-details";
        const detailsLabel = document.createElement("summary");
        detailsLabel.textContent = detailDisclosureLabel;
        detailsLabel.dataset.skipRead = "true";
        const detail = document.createElement("div");
        detail.className = "pharm-detail-text";
        appendReadableDetailText(detail, detailText, { currentLabel: clinicalReferenceDisplayName(entry) });
        details.append(detailsLabel, detail);
        teaching.append(details);
      }
      tr.append(age, recommendation, vaccines, teaching);
      tbody.append(tr);
    });
    table.append(caption, thead, tbody);
    wrap.append(table);
    stage.append(wrap);
    stageList.append(stage);
  });
  section.append(stageList);
  return section;
}

function buildClinicalReferenceResponsiveTableVisual(entry = {}, visual = {}) {
  const source = clinicalReferenceVisualSource(entry, visual.sourceField);
  if (!Array.isArray(source) || !source.length) return null;
  const columns = Array.isArray(visual.columns) && visual.columns.length >= 2
    ? visual.columns.slice(0, 2).map(safeText)
    : ["Topic", "Key information"];
  const rows = source.map(splitPresentationLabel).filter((row) => row.detail);
  const section = document.createElement("section");
  section.className = "pharm-learning-visual pharm-learning-responsive-table";
  section.dataset.visualId = safeText(visual.id);
  section.dataset.mobileMode = safeText(visual.mobileMode);
  const heading = clinicalReferenceVisualHeading(section, visual);
  clinicalReferenceVisualIntro(section, visual, rows.map((row) => `${row.label}: ${row.detail}`).join("\n"));
  const wrap = document.createElement("div");
  wrap.className = "pharm-learning-table-wrap";
  const table = document.createElement("table");
  table.className = "pharm-learning-data-table";
  table.setAttribute("aria-labelledby", heading.id);
  const thead = document.createElement("thead");
  const header = document.createElement("tr");
  columns.forEach((label) => {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = label;
    header.append(th);
  });
  thead.append(header);
  const tbody = document.createElement("tbody");
  rows.forEach((row) => {
    const tr = document.createElement("tr");
    const label = document.createElement("th");
    label.scope = "row";
    label.dataset.label = columns[0];
    label.textContent = row.label;
    const detail = document.createElement("td");
    detail.dataset.label = columns[1];
    appendReadableDetailText(detail, row.detail, { currentLabel: clinicalReferenceDisplayName(entry) });
    tr.append(label, detail);
    tbody.append(tr);
  });
  table.append(thead, tbody);
  wrap.append(table);
  appendClinicalReferenceVisualDisclosure(section, visual, wrap, rows.length);
  return section;
}

function buildClinicalReferenceDisclosureListVisual(entry = {}, visual = {}) {
  const source = clinicalReferenceVisualSource(entry, visual.sourceField);
  if (!Array.isArray(source) || !source.length) return null;
  const rows = source.map(splitPresentationLabel).filter((row) => row.detail);
  const section = document.createElement("section");
  section.className = "pharm-learning-visual pharm-learning-disclosure-list";
  section.dataset.visualId = safeText(visual.id);
  clinicalReferenceVisualHeading(section, visual);
  clinicalReferenceVisualIntro(section, visual, rows.map((row) => `${row.label}: ${row.detail}`).join("\n"));
  const grid = document.createElement("div");
  grid.className = "pharm-learning-disclosure-grid";
  rows.forEach((row) => {
    const card = document.createElement("article");
    card.className = "pharm-learning-disclosure-card";
    const title = document.createElement("h3");
    title.textContent = row.label;
    const detail = document.createElement("div");
    detail.className = "pharm-detail-text";
    appendReadableDetailText(detail, row.detail, { currentLabel: clinicalReferenceDisplayName(entry) });
    card.append(title, detail);
    grid.append(card);
  });
  appendClinicalReferenceVisualDisclosure(section, visual, grid, rows.length);
  return section;
}

function buildClinicalReferenceCalloutVisual(entry = {}, visual = {}) {
  const source = clinicalReferenceVisualSource(entry, visual.sourceField);
  const value = safeText(source);
  if (!value) return null;
  const section = document.createElement("section");
  section.className = `pharm-learning-visual pharm-learning-callout is-${safeText(visual.tone || "note").replace(/[^a-z0-9_-]/gi, "")}`;
  section.dataset.visualId = safeText(visual.id);
  clinicalReferenceVisualHeading(section, visual);
  const text = document.createElement("div");
  text.className = "pharm-detail-text";
  text.dataset.readableText = value;
  appendReadableDetailText(text, value, { currentLabel: clinicalReferenceDisplayName(entry) });
  section.append(text);
  return section;
}

function buildClinicalReferenceAuthoredVisual(entry = {}, visual = {}) {
  if (!visual || typeof visual !== "object") return null;
  if (visual.type === "key-value-grid") return buildClinicalReferenceKeyValueVisual(entry, visual);
  if (visual.type === "timeline") return buildClinicalReferenceTimelineVisual(entry, visual);
  if (visual.type === "responsive-table") return buildClinicalReferenceResponsiveTableVisual(entry, visual);
  if (visual.type === "disclosure-list") return buildClinicalReferenceDisclosureListVisual(entry, visual);
  if (visual.type === "callout") return buildClinicalReferenceCalloutVisual(entry, visual);
  return null;
}

function authoredPresentationRuntimeStatus(entry = {}) {
  const presentation = entry?.presentation;
  if (!presentation || presentation.schemaVersion !== ANI_CARD_PRESENTATION_SCHEMA) {
    return { enabled: false, valid: false, errors: [] };
  }
  const visuals = Array.isArray(entry.visuals) ? entry.visuals : [];
  const allowedTypes = new Set(["timeline", "responsive-table", "key-value-grid", "disclosure-list", "callout", "percentile-curves"]);
  const standard = window.ANI_LEARNER_LANGUAGE_STANDARD?.presentationStandard || {};
  const ids = new Set();
  const sources = new Set();
  const errors = [];
  const standardWordLimit = Number(standard.maximumInitiallyVisibleWords || 650);
  const standardSectionLimit = Number(standard.maximumInitiallyVisibleSections || 7);
  const validLimit = (value, maximum) => value === undefined
    || (Number.isInteger(Number(value)) && Number(value) > 0 && Number(value) <= maximum);
  if (!validLimit(presentation.maximumInitiallyVisibleWords, standardWordLimit)
    || !validLimit(presentation.maximumInitiallyVisibleSections, standardSectionLimit)) {
    errors.push("presentation has an invalid or over-limit initial density declaration");
  }
  if (!visuals.length) errors.push("presentation has no visuals");
  visuals.forEach((visual, visualIndex) => {
    const id = safeText(visual?.id);
    const type = safeText(visual?.type);
    if (!id || ids.has(id)) errors.push(`visual ${visualIndex} has a missing or duplicate id`);
    if (id) ids.add(id);
    if (!allowedTypes.has(type)) errors.push(`visual ${id || visualIndex} has an unsupported type`);
    const sourceField = safeText(visual?.sourceField);
    const source = clinicalReferenceVisualSource(entry, sourceField);
    if (!sourceField || sources.has(sourceField)) errors.push(`visual ${id || visualIndex} has a missing or duplicate source field`);
    if (sourceField) sources.add(sourceField);
    const expectsArray = ["timeline", "responsive-table", "disclosure-list", "percentile-curves"].includes(type);
    const expectsObject = type === "key-value-grid";
    const expectsScalar = type === "callout";
    const arrayHasContent = Array.isArray(source) && source.some((item) => (
      item && typeof item === "object" ? Object.values(item).some((value) => safeText(value)) : safeText(item)
    ));
    const objectHasContent = source && typeof source === "object" && !Array.isArray(source)
      && Object.values(source).some((value) => safeText(value));
    if ((expectsArray && (!Array.isArray(source) || !arrayHasContent))
      || (expectsObject && !objectHasContent)
      || (expectsScalar && (!safeText(source) || visual.defaultOpen === false))) {
      errors.push(`visual ${id || visualIndex} has an empty or incompatible source`);
      return;
    }
    if (["timeline", "responsive-table"].includes(type) && safeText(visual.mobileMode) !== "stacked-cards") {
      errors.push(`visual ${id || visualIndex} has no supported mobile mode`);
    }
    if (type !== "timeline") return;
    const fields = visual.fields || {};
    const rowKeyField = safeText(fields.rowKey || "sequence");
    const summaryField = safeText(fields.summary || "summary");
    const detailField = safeText(fields.detail || "text");
    const sourceKeys = source.map((row) => safeText(row?.[rowKeyField]));
    if (sourceKeys.some((key) => !key) || new Set(sourceKeys).size !== sourceKeys.length) {
      errors.push(`visual ${id || visualIndex} has missing or duplicate source row keys`);
    }
    if (source.some((row) => !safeText(row?.[summaryField]))) {
      errors.push(`visual ${id || visualIndex} has a missing authored row summary`);
    }
    if (source.some((row) => !safeText(row?.[detailField]))) {
      errors.push(`visual ${id || visualIndex} has a missing authored row detail`);
    }
    const groups = Array.isArray(visual.groups) && visual.groups.length
      ? visual.groups
      : [{ rowKeys: sourceKeys }];
    const groupedKeys = groups.flatMap((group) => Array.isArray(group?.rowKeys) ? group.rowKeys.map((key) => safeText(key)) : []);
    const sourceSet = new Set(sourceKeys);
    const groupCounts = new Map();
    groupedKeys.forEach((key) => groupCounts.set(key, (groupCounts.get(key) || 0) + 1));
    if (groupedKeys.some((key) => !sourceSet.has(key))
      || sourceKeys.some((key) => groupCounts.get(key) !== 1)) {
      errors.push(`visual ${id || visualIndex} does not cover every source row exactly once`);
    }
    if (visual.linkSourceField) {
      const linkSource = clinicalReferenceVisualSource(entry, visual.linkSourceField);
      const joinField = safeText(visual.linkJoinField || rowKeyField);
      if (!Array.isArray(linkSource) || !linkSource.length) {
        errors.push(`visual ${id || visualIndex} has an invalid link source`);
      } else {
        const sourceSet = new Set(sourceKeys);
        const linkIdentities = new Set();
        linkSource.forEach((link) => {
          const joinKey = safeText(link?.[joinField]);
          const targetId = safeText(link?.targetId);
          const targetName = safeText(link?.targetName || link?.label);
          const targetCollection = safeText(link?.targetCollection);
          const hasStableIdentity = Boolean(targetId && targetName);
          const hasCollectionIdentity = Boolean(targetCollection && targetName);
          const identity = `${joinKey}|${targetCollection}|${targetId}|${normalizePharmText(targetName)}`;
          if (!sourceSet.has(joinKey) || (!hasStableIdentity && !hasCollectionIdentity) || linkIdentities.has(identity)) {
            errors.push(`visual ${id || visualIndex} has an invalid or duplicate deterministic link record`);
          }
          if (!clinicalReferenceTimelineTarget(link)) {
            errors.push(`visual ${id || visualIndex} has an unresolved or identity-mismatched stable link record`);
          }
          linkIdentities.add(identity);
        });
        const rowLinksField = safeText(fields.links);
        if (rowLinksField) {
          source.forEach((row) => {
            const key = safeText(row?.[rowKeyField]);
            const authoredNames = Array.isArray(row?.[rowLinksField])
              ? row[rowLinksField].map(normalizePharmText).filter(Boolean).sort()
              : [];
            const linkedNames = linkSource
              .filter((link) => safeText(link?.[joinField]) === key)
              .map((link) => normalizePharmText(link?.targetName || link?.label))
              .filter(Boolean)
              .sort();
            if (authoredNames.length !== linkedNames.length
              || authoredNames.some((name, index) => name !== linkedNames[index])) {
              errors.push(`visual ${id || visualIndex} has a row/link parity mismatch`);
            }
          });
        }
      }
    }
  });
  const visibleSafetyCallouts = new Map(visuals
    .filter((visual) => visual?.type === "callout" && visual.defaultOpen !== false)
    .map((visual) => [safeText(visual.sourceField), safeText(visual.safetyCoverageKey)])
    .filter(([sourceField, safetyCoverageKey]) => sourceField && safetyCoverageKey));
  [...visuals, ...(Array.isArray(entry.sections) ? entry.sections : [])].forEach((component, componentIndex) => {
    const visibleSafetySourceField = safeText(component?.visibleSafetySourceField);
    if (!visibleSafetySourceField) return;
    const safetyCoverageKey = safeText(component?.safetyCoverageKey);
    if (!safetyCoverageKey || visibleSafetyCallouts.get(visibleSafetySourceField) !== safetyCoverageKey) {
      errors.push(`presentation component ${component?.id || component?.label || componentIndex} has an unbound visible safety summary`);
    }
  });
  return { enabled: true, valid: errors.length === 0, errors };
}

function appendAuthoredPresentationVisuals(entry = {}) {
  const status = authoredPresentationRuntimeStatus(entry);
  if (!status.enabled || !status.valid) {
    if (status.enabled && pharmDrugDetail) {
      pharmDrugDetail.dataset.presentationContract = "invalid-blocked";
      pharmDrugDetail.dataset.presentationErrors = status.errors.join(" | ");
    }
    return 0;
  }
  let renderedCount = 0;
  (entry.visuals || []).forEach((visual) => {
    const rendered = visual?.type === "percentile-curves"
      ? buildPercentileCurveVisual({ ...visual, series: clinicalReferenceVisualSource(entry, visual.sourceField) })
      : buildClinicalReferenceAuthoredVisual(entry, visual);
    if (!rendered) return;
    pharmDrugDetail.append(rendered);
    renderedCount += 1;
  });
  if (pharmDrugDetail) pharmDrugDetail.dataset.presentationContract = "valid";
  return renderedCount;
}

function appendClinicalReferenceVisuals(entry = {}, input = "") {
  let renderedCount = appendAuthoredPresentationVisuals(entry);
  if (!entry.presentation && entry.type === "growth") {
    growthVisualsForInput(entry, input || "growth chart").forEach((visual) => {
      if (visual?.type !== "percentile-curves") return;
      pharmDrugDetail.append(buildPercentileCurveVisual(visual));
      renderedCount += 1;
    });
  }
  if (entry.type === "procedure") {
    pharmDrugDetail.append(buildClinicalFlowVisual(makeClinicalReferenceFlowVisualData(entry)));
    renderedCount += 1;
  }
  return renderedCount;
}

function renderClinicalReferenceDetail(entry = activeClinicalReferenceResults[0], options = {}) {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  const isHolisticReference = isHolisticClinicalReferenceEntry(entry);
  const isFoundation = (entry?.type === "foundation" || entry?.educationalArticle === true) && !isHolisticReference;
  const isMicrobiology = isMicrobiologyReferenceEntry(entry);
  const isSurgeryProcedure = isSurgeryProcedureReferenceEntry(entry);
  setPharmDetailTheme(isHolisticReference ? "holistic" : (isMicrobiology ? "microbiology" : (isSurgeryProcedure ? "surgeries" : (isFoundation ? "foundations" : "procedures"))));
  if (!entry) {
    renderPharmDrugDetail(null);
    return;
  }
  if (pharmDrugDetail) {
    pharmDrugDetail.dataset.narrationType = isClinicalSignReferenceEntry(entry)
      ? "clinical-signs"
      : (isHolisticReference ? "holistic" : (isMicrobiology ? "microbiology" : (isSurgeryProcedure ? "surgeries" : (isFoundation ? "foundations" : "procedures"))));
  }

  const title = document.createElement("div");
  title.className = `pharm-detail-title ${isHolisticReference ? "pharm-holistic-title" : (isMicrobiology ? "pharm-microbiology-title" : (isSurgeryProcedure ? "pharm-surgery-title" : (isFoundation ? "pharm-foundation-title" : "pharm-procedure-title")))}`;
  const name = document.createElement("h2");
  name.textContent = clinicalReferenceDisplayName(entry);
  const category = document.createElement("span");
  category.textContent = safeText(`${entry.icon ? `${entry.icon} | ` : ""}${entry.nclexEssential ? "NCLEX ESSENTIAL | " : ""}${isHolisticReference ? "Holistic | " : ""}${isMicrobiology ? "Microbiology | " : ""}${isSurgeryProcedure ? "Surgeries & Procedures | " : ""}${entry.category || "Clinical reference"}`);
  title.append(name, category);
  appendPharmFavoriteButton(title, "procedures", entry);
  pharmDrugDetail.append(title);

  const detailIntent = safeText(options.intent || pharmSearchInput?.value || "");
  const studySafetyNote = isHolisticReference
    ? (entry.studySafetyNote || entry.sourceNote || "Use this educational reference with the client's individualized orders, interdisciplinary recommendations, and current facility policy in clinical care.")
    : isMicrobiology
    ? (entry.sourceNote || "Use this Microbiology reference for study and follow current laboratory, infection-prevention, and facility guidance for real clinical decisions.")
    : isSurgeryProcedure
      ? (entry.sourceNote || "Use this procedure card for study and follow current procedural protocols, provider orders, facility policy, and the client's individualized plan in clinical care.")
    : isFoundation
      ? (entry.studySafetyNote || "Use this foundation to understand normal structure and physiology, then connect it with ANI's disease, medication, laboratory, and diagnostic cards. For real clinical decisions, follow current professional guidance and local policy.")
      : (entry.sourceNote || "Use these values as NCLEX study anchors. For real care, verify current facility references, provider orders, and official source materials.");
  const rawAuthoredSectionRecords = entry.type === "growth"
    ? growthFocusedSectionPairs(entry, detailIntent || "growth chart", 5)
      .map(([label, value], sourceIndex) => ({ label, value, presentation: "", defaultOpen: false, sourceIndex }))
    : clinicalReferenceSectionRecords(entry);
  const openingProjection = clinicalReferenceVisibleSectionProjection(entry, {
    sectionRecords: rawAuthoredSectionRecords,
    ...(entry.type === "growth"
      ? { quickAnswerOverride: growthQuickAnswerForInput(entry, detailIntent || "growth chart") }
      : {})
  });
  const authoredSectionRecords = openingProjection.sectionRecords;
  const hasStructuredPresentation = entry.presentation?.schemaVersion === ANI_CARD_PRESENTATION_SCHEMA;
  const sections = [
    { id: "clinical-reference-opening", path: "quickAnswer", label: "Quick answer", value: openingProjection.quickAnswer, authoredSection: null },
    { id: "clinical-reference-significance", path: "whyItMatters", label: "Why every nurse should know it", value: openingProjection.whyItMatters, authoredSection: null },
    ...authoredSectionRecords.map((section, index) => ({
      id: `clinical-reference-authored-${Number.isInteger(section.sourceIndex) ? section.sourceIndex : index}`,
      path: `sections.${Number.isInteger(section.sourceIndex) ? section.sourceIndex : index}.value`,
      label: section.label,
      value: section.value,
      authoredSection: section
    })),
    {
      id: "clinical-reference-study-safety",
      path: "studySafetyNote",
      label: "Study safety note",
      value: studySafetyNote,
      learnerText: "",
      authoredSection: null
    }
  ];
  const learnerSections = [
    ...sections,
    {
      id: "clinical-reference-result-meanings",
      path: "resultMeanings",
      label: "Results - what each result means",
      value: clinicalReferenceResultMeaningText(entry),
      authoredSection: null
    }
  ];
  const learnerProjection = projectVisibleLearnerSupport(entry, learnerSections, { prefix: "clinical-reference-visible-section" });
  const firstLearnerBlockId = learnerProjection.blocks[0]?.id || "";
  const visualAnchorLabel = openingProjection.whyItMatters
    ? "Why every nurse should know it"
    : (openingProjection.quickAnswer ? "Quick answer" : "");

  let memoryBridgeRendered = false;
  let structuredVisualsRendered = false;
  sections.forEach(({ id, label, value, authoredSection }) => {
    if (!value) return;
    const section = document.createElement("section");
    if (authoredSection?.id) section.dataset.sectionId = authoredSection.id;
    if (authoredSection?.presentation) section.dataset.presentation = authoredSection.presentation;
    if (Number.isInteger(authoredSection?.sourceIndex)) section.dataset.sourceIndex = String(authoredSection.sourceIndex);
    const heading = document.createElement("strong");
    heading.textContent = label;
    const text = document.createElement("div");
    text.className = "pharm-detail-text";
    const detailOptions = { currentLabel: clinicalReferenceDisplayName(entry) };
    const renderedLeafCount = authoredSection && typeof value === "object"
      ? appendClinicalReferenceStructuredDetail(text, authoredSection, detailOptions)
      : (appendReadableDetailText(text, value, detailOptions), safeText(value) ? 1 : 0);
    if (!renderedLeafCount) return;
    let learnerContainer = pharmDrugDetail;
    if (authoredSection?.presentation === "disclosure") {
      section.className = "pharm-progressive-section";
      const details = document.createElement("details");
      details.className = "pharm-progressive-disclosure";
      details.open = authoredSection.defaultOpen === true;
      const summary = document.createElement("summary");
      summary.dataset.skipRead = "true";
      summary.append(heading);
      details.append(summary, text);
      section.append(details);
      learnerContainer = details;
    } else {
      section.append(heading, text);
    }
    pharmDrugDetail.append(section);
    const learnerBlock = learnerProjection.byId.get(id);
    if (learnerBlock) {
      appendLearnerLanguageSupport(learnerContainer, entry, {
        currentLabel: clinicalReferenceDisplayName(entry),
        projectedBlock: learnerBlock,
        includePlainLanguage: learnerBlock.id === firstLearnerBlockId,
        heading: learnerBlock.id === firstLearnerBlockId ? "Medical terms explained" : "Terms in this section"
      });
    }
    if (label === "Quick answer") {
      if (!hasStructuredPresentation) {
        appendMemoryBridgeSections(pharmDrugDetail, entry);
        memoryBridgeRendered = true;
      }
    }
    if (label === visualAnchorLabel) {
      structuredVisualsRendered = appendClinicalReferenceVisuals(entry, detailIntent) > 0;
      if (hasStructuredPresentation && !memoryBridgeRendered) {
        appendMemoryBridgeSections(pharmDrugDetail, entry);
        memoryBridgeRendered = true;
      }
    }
  });
  if (hasStructuredPresentation && !structuredVisualsRendered) {
    appendClinicalReferenceVisuals(entry, detailIntent);
  }
  if (!memoryBridgeRendered) {
    appendMemoryBridgeSections(pharmDrugDetail, entry);
  }
  appendMedicalAbbreviationSection(pharmDrugDetail, [
    entry.name,
    entry.displayName,
    entry.fullForm,
    entry.category,
    ...(entry.aliases || []),
    ...(entry.abbreviations || []),
    ...(entry.commonMisspellings || []),
    entry.summary,
    entry.quickAnswer,
    clinicalReferenceResultMeaningText(entry),
    ...clinicalReferenceSectionPairs(entry).flat()
  ]);
  appendMedicalTermTeachingSection(pharmDrugDetail, entry);
  if (appendClinicalReferenceResultMeaningSection(pharmDrugDetail, entry)) {
    const resultMeaningLearnerBlock = learnerProjection.byId.get("clinical-reference-result-meanings");
    if (resultMeaningLearnerBlock) {
      appendLearnerLanguageSupport(pharmDrugDetail, entry, {
        currentLabel: clinicalReferenceDisplayName(entry),
        projectedBlock: resultMeaningLearnerBlock,
        includePlainLanguage: false,
        heading: "Terms in this section"
      });
    }
  }
  appendHighYieldImageSection(pharmDrugDetail, entry, "procedures");

  appendMicrobiologyRelationshipSection(pharmDrugDetail, entry);
  appendExploreRelatedConcepts(pharmDrugDetail, [
    entry.name,
    entry.displayName,
    entry.fullForm,
    entry.category,
    ...(entry.aliases || []),
    ...(entry.abbreviations || []),
    ...(entry.commonMisspellings || []),
    entry.summary,
    entry.quickAnswer,
    entry.sections,
    sections.map(({ label, value }) => [label, value])
  ], clinicalReferenceDisplayName(entry));
  if (isMicrobiology) {
    appendEvidenceSourceSection(pharmDrugDetail, microbiologyDatabase, entry);
  } else if (isSurgeryProcedure) {
    appendEvidenceSourceSection(pharmDrugDetail, surgeryProcedureDatabase, entry);
  } else if (isFoundation) {
    appendClinicalReferenceEvidenceSourceSection(pharmDrugDetail, { ...entry, sourceNote: entry.evidenceNote || "" });
  } else if (Array.isArray(entry.sourceKeys) && entry.sourceKeys.length) {
    appendClinicalReferenceEvidenceSourceSection(pharmDrugDetail, entry);
  }
  syncPharmDetailReadableText();
}

function pathologyOpeningSentencePieces(value = "", limit = 2) {
  const text = safeText(value).replace(/\s+/g, " ").trim();
  if (!text) return [];
  return (text.match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [text])
    .map((sentence) => normalizeReadableSentence(sentence))
    .filter(Boolean)
    .slice(0, limit);
}

function pathologyFirstGlanceText(disease = {}) {
  const reviewedPlainLanguage = safeText(
    disease.plainLanguage || disease.plainMeaning || disease.termMeaning || disease.literalMeaning
  ).replace(/\s+/g, " ").trim();
  if (reviewedPlainLanguage) return reviewedPlainLanguage;
  const pieces = [];
  const seen = new Set();
  const labelKeys = [disease.name, ...(Array.isArray(disease.aliases) ? disease.aliases : [])]
    .map((term) => normalizePharmText(term))
    .filter(Boolean)
    .sort((a, b) => b.length - a.length);
  const canonicalKey = (sentence = "") => {
    let key = normalizePharmText(sentence);
    labelKeys.forEach((labelKey) => {
      if (key === labelKey || key.startsWith(`${labelKey} `)) {
        key = key.slice(labelKey.length).trim();
      }
    });
    return key;
  };
  const keyTokens = (key = "") => normalizePharmText(key)
    .split(" ")
    .filter((token) => token.length > 3 && !["this", "that", "with", "from", "into", "inside", "especially", "usually", "often", "most"].includes(token));
  const isNearDuplicate = (key = "") => {
    const tokens = new Set(keyTokens(key));
    if (tokens.size < 5) return false;
    for (const existingKey of seen) {
      const existingTokens = new Set(keyTokens(existingKey));
      if (existingTokens.size < 5) continue;
      let overlap = 0;
      tokens.forEach((token) => {
        if (existingTokens.has(token)) overlap += 1;
      });
      if (overlap >= 5 && overlap / Math.min(tokens.size, existingTokens.size) >= 0.7) {
        return true;
      }
    }
    return false;
  };
  [
    disease.definition || disease.plainMeaning || "",
    disease.pathology || "",
    disease.pathophysiology || ""
  ].forEach((value) => {
    pathologyOpeningSentencePieces(value, 2).forEach((sentence) => {
      const key = canonicalKey(sentence);
      if (!key || seen.has(key) || isNearDuplicate(key)) return;
      seen.add(key);
      pieces.push(sentence);
    });
  });
  return pieces.slice(0, 3).join(" ");
}

function pathologyCanonicalOpeningKey(sentence = "", disease = {}) {
  let key = normalizePharmText(sentence);
  [disease.name, ...(Array.isArray(disease.aliases) ? disease.aliases : [])]
    .map((term) => normalizePharmText(term))
    .filter(Boolean)
    .sort((a, b) => b.length - a.length)
    .forEach((labelKey) => {
      if (key === labelKey || key.startsWith(`${labelKey} `)) {
        key = key.slice(labelKey.length).trim();
      }
    });
  return key;
}

function pathologySectionValueWithoutOpeningDuplicate(value = "", firstGlance = "", disease = {}) {
  const source = safeText(value).replace(/\s+/g, " ").trim();
  if (!source || !firstGlance) return source;
  const firstKeys = new Set(pathologyOpeningSentencePieces(firstGlance, 3).map((sentence) => pathologyCanonicalOpeningKey(sentence, disease)));
  const remaining = pathologyOpeningSentencePieces(source, 12)
    .filter((sentence) => !firstKeys.has(pathologyCanonicalOpeningKey(sentence, disease)));
  return remaining.length ? remaining.join(" ") : "";
}

function pathologyIsolationPrecautionRecords(disease = {}) {
  return (Array.isArray(disease.isolationPrecautions) ? disease.isolationPrecautions : [])
    .filter((record) => record && typeof record === "object")
    .filter((record) => {
      const target = microbiologyRuntimeTargetFields(record);
      return Boolean(target.targetId || (target.targetCollection && target.canonicalTitle));
    });
}

function pathologyIsolationPrecautionText(disease = {}) {
  return pathologyIsolationPrecautionRecords(disease)
    .map((record) => {
      const target = microbiologyRuntimeTargetFields(record);
      const label = safeText(record.label || target.canonicalTitle || "Transmission-based precautions");
      const context = safeText(record.context || record.note || record.rationale);
      return context ? `${label}: ${context}` : label;
    })
    .filter(Boolean)
    .join(" ");
}

function appendPathologyIsolationPrecautionLinks(container, disease = {}) {
  if (!container) return false;
  const seen = new Set();
  const resolved = pathologyIsolationPrecautionRecords(disease)
    .map((record) => ({ record, candidate: resolveMicrobiologyRuntimeTarget(record) }))
    .filter(({ candidate }) => candidate?.item)
    .filter(({ candidate }) => {
      const key = offlineLookupEntityKey(candidate);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  if (!resolved.length) return false;

  const grid = document.createElement("div");
  grid.className = "pharm-related-concept-grid";
  grid.dataset.skipRead = "true";
  resolved.forEach(({ record, candidate }) => {
    activePharmDetailLinkTargets.add(offlineLookupEntityKey(candidate));
    const button = document.createElement("button");
    button.type = "button";
    button.className = `pharm-related-concept-link pharm-related-${candidate.type}`;
    button.dataset.aniTargetType = candidate.type;
    button.dataset.aniTargetName = offlineLookupEntityLabel(candidate);
    button.dataset.aniTargetKey = offlineLookupEntityKey(candidate);
    button.dataset.aniResolution = "bound-runtime-object";
    button.dataset.aniRelationshipType = "requires-precaution";
    const label = document.createElement("span");
    label.textContent = safeText(record.label || offlineLookupEntityLabel(candidate));
    const meta = document.createElement("small");
    meta.textContent = `Open precaution card | ${offlineLookupEntityKind(candidate)}`;
    button.append(label, meta);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPharmDetailCandidate({ type: candidate.type, item: candidate.item });
    });
    grid.append(button);
  });
  container.append(grid);
  return true;
}

function pathologyVisibleLearnerDetail(disease = {}) {
  const diagnosticAlterations = pathologyDiagnosticAlterations(disease);
  const pathophysiologyText = pathologyListText(disease.pathophysiology);
  const pathologyText = safeText(disease.pathology);
  const reviewedPlainLanguage = safeText(
    disease.plainLanguage || disease.plainMeaning || disease.termMeaning || disease.literalMeaning
  ).replace(/\s+/g, " ").trim();
  const firstGlanceText = pathologyFirstGlanceText(disease);
  const definitionText = safeText(disease.definition).replace(/\s+/g, " ").trim();
  const openingComparable = window.ANI_LEARNER_LANGUAGE_STANDARD
    && typeof window.ANI_LEARNER_LANGUAGE_STANDARD.openingOwnershipComparable === "function"
    ? window.ANI_LEARNER_LANGUAGE_STANDARD.openingOwnershipComparable
    : normalizePharmText;
  const remainingDefinitionText = reviewedPlainLanguage
    ? (openingComparable(definitionText) === openingComparable(firstGlanceText) ? "" : definitionText)
    : pathologySectionValueWithoutOpeningDuplicate(definitionText, firstGlanceText, disease);
  const remainingPathologyText = pathologySectionValueWithoutOpeningDuplicate(pathologyText, firstGlanceText, disease);
  const remainingPathophysiologyText = pathologySectionValueWithoutOpeningDuplicate(pathophysiologyText, firstGlanceText, disease);
  const categoryText = normalizePharmText(disease.category || "");
  const isClinicalConcept = isExplicitPathologyClinicalConcept(disease);
  const isMechanismConceptCard = /\b(pharmacology foundations|antibiotic pharmacology|diagnostic reasoning)\b/i.test(categoryText);
  const definitionHeading = isClinicalConcept ? "Clinical meaning / assessment frame" : "Clinical definition / diagnostic frame";
  const coreMechanismHeading = isClinicalConcept
    ? "Observed pattern / assessment context"
    : (isMechanismConceptCard ? "Mechanism / concept - what is happening" : "Pathology - what is happening");
  const whyMechanismHeading = (isClinicalConcept || isMechanismConceptCard) ? "Why this matters clinically" : "Pathophysiology - why it happens";
  const driverHeading = (isClinicalConcept || isMechanismConceptCard) ? "What changes interpretation" : "Etiology / risk factors";
  const driverText = [safeText(disease.etiology), pathologyListText(disease.riskFactors)].filter(Boolean).join(" ");
  const sections = [
    ["Crash-course definition", firstGlanceText],
    [definitionHeading, remainingDefinitionText],
    ["Isolation precautions", pathologyIsolationPrecautionText(disease)],
    ["Priority nursing actions", pathologyListText(disease.nursingPriorities)],
    ["Urgent red flags / when to escalate", pathologyListText(disease.redFlags)],
    [coreMechanismHeading, remainingPathologyText || (!firstGlanceText ? pathologyText : "") || remainingPathophysiologyText],
    [whyMechanismHeading, remainingPathophysiologyText && normalizePharmText(pathophysiologyText) !== normalizePharmText(pathologyText) ? remainingPathophysiologyText : ""],
    [driverHeading, driverText],
    ["Signs and symptoms", pathologyListText(disease.signsSymptoms)],
    ["Diagnostics / assessment clues", pathologyListText(disease.diagnostics)],
    ["Lab/value alterations to expect", diagnosticAlterations.length ? diagnosticAlterations : ""],
    ["Treatment overview", pathologyListText(disease.treatments)],
    ["Contraindications / what to avoid", pathologyListText(disease.contraindications)],
    ["Complications to monitor", pathologyListText(disease.complications)],
    ["Patient education", pathologyListText(disease.patientEducation)],
    ["Common NCLEX traps / nuance", pathologyListText(disease.nclexTraps)],
    ["Related topics to explore", pathologyListText(disease.relatedTopics)]
  ];
  return {
    diagnosticAlterations,
    firstGlanceUsesPlainLanguage: Boolean(reviewedPlainLanguage),
    learnerSections: sections.map(([label, value], index) => ({
      id: `pathology-visible-section-${index + 1}`,
      label,
      value,
      path: `visiblePathologySections.${index}`,
      learnerText: label === "Lab/value alterations to expect" ? pathologyDiagnosticAlterationText(disease) : value
    }))
  };
}

function renderPathologyDetail(disease = activePathologyResults[0]) {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  const isHolisticPathology = isHolisticPathologyEntry(disease);
  setPharmDetailTheme(isHolisticPathology ? "holistic" : "diseases");
  if (!disease) {
    renderPharmDrugDetail(null);
    return;
  }
  const isClinicalConcept = isExplicitPathologyClinicalConcept(disease);

  const title = document.createElement("div");
  title.className = `pharm-detail-title ${isHolisticPathology ? "pharm-holistic-title" : "pharm-pathology-title"}`;
  const name = document.createElement("h2");
  name.textContent = safeText(disease.name);
  const category = document.createElement("span");
  category.textContent = isClinicalConcept
    ? pathologyClinicalConceptBanner(disease)
    : safeText(`${disease.nclexEssential ? "NCLEX ESSENTIAL | " : ""}${isHolisticPathology ? "Holistic | " : ""}${disease.category || "Pathology"} | DISEASE/PATHOLOGY CARD`);
  title.append(name, category);
  appendPharmFavoriteButton(title, "diseases", disease);
  pharmDrugDetail.append(title);

  const clinicalConceptCallout = pathologyClinicalConceptPresentation(disease)?.callout || "";
  if (clinicalConceptCallout) {
    const statusCallout = document.createElement("p");
    statusCallout.className = "pharm-pathology-status-callout";
    statusCallout.textContent = clinicalConceptCallout;
    pharmDrugDetail.append(statusCallout);
  }

  const aliases = Array.from(new Set([
    ...(Array.isArray(disease.abbreviations) ? disease.abbreviations : []),
    ...(Array.isArray(disease.aliases) ? disease.aliases : [])
  ].filter(Boolean)));
  const visibleDetail = pathologyVisibleLearnerDetail(disease);
  const diagnosticAlterations = visibleDetail.diagnosticAlterations;
  const learnerSections = visibleDetail.learnerSections;
  const sections = learnerSections.map(({ label, value }) => [label, value]);
  const learnerProjection = projectVisibleLearnerSupport(disease, learnerSections, { prefix: "pathology-visible-section" });
  const firstLearnerBlockId = learnerProjection.blocks[0]?.id || "";

  let treatmentMedicationsAppended = false;
  let authoredPresentationAttempted = false;
  learnerSections.forEach(({ id, label, value }) => {
    if (!value) return;
    const section = document.createElement("section");
    const heading = document.createElement("strong");
    heading.textContent = label;
    const isAlterationSection = label === "Lab/value alterations to expect";
    const isIsolationSection = label === "Isolation precautions";
    const text = document.createElement("div");
    if (isAlterationSection) {
      text.className = "pathology-diagnostic-cue-grid";
      appendPathologyDiagnosticCueChips(text, diagnosticAlterations);
    } else {
      text.className = "pharm-detail-text";
      appendReadableDetailText(text, value, { currentLabel: disease.name });
      if (isIsolationSection) appendPathologyIsolationPrecautionLinks(text, disease);
    }
    section.append(heading, text);
    pharmDrugDetail.append(section);
    const learnerBlock = learnerProjection.byId.get(id);
    if (learnerBlock) {
      appendLearnerLanguageSupport(pharmDrugDetail, disease, {
        currentLabel: disease.name,
        projectedBlock: learnerBlock,
        includePlainLanguage: learnerBlock.id === firstLearnerBlockId
          && visibleDetail.firstGlanceUsesPlainLanguage !== true,
        heading: learnerBlock.id === firstLearnerBlockId ? "Medical terms explained" : "Terms in this section"
      });
    }
    if (label === "Crash-course definition") {
      appendAuthoredPresentationVisuals(disease);
      authoredPresentationAttempted = true;
      appendMemoryBridgeSections(pharmDrugDetail, disease);
    }
    if (isAlterationSection && isCkdPathology(disease)) {
      pharmDrugDetail.append(buildCkdStageDetailSection());
    }
    if (label === "Treatment overview") {
      treatmentMedicationsAppended = appendPathologyTreatmentMedicationSection(disease) || treatmentMedicationsAppended;
    }
    if (label === "Pathology - what is happening") {
      pharmDrugDetail.append(buildClinicalFlowVisual(makePathologyFlowVisualData(disease)));
    }
  });
  if (!authoredPresentationAttempted) appendAuthoredPresentationVisuals(disease);
  if (!treatmentMedicationsAppended) {
    appendPathologyTreatmentMedicationSection(disease);
  }

  appendMedicalAbbreviationSection(pharmDrugDetail, [
    disease.name,
    disease.category,
    ...aliases,
    disease.pathology,
    disease.etiology,
    pathologyListText(disease.riskFactors),
    pathologyListText(disease.signsSymptoms),
    pathologyListText(disease.diagnostics),
    pathologyDiagnosticAlterationText(disease),
    pathologyListText(disease.treatments),
    pathologyListText(disease.contraindications),
    pathologyListText(disease.nursingPriorities),
    pathologyListText(disease.redFlags),
    pathologyIsolationPrecautionText(disease),
    pathologyListText(disease.complications),
    pathologyListText(disease.nclexTraps),
    pathologyListText(disease.relatedTopics),
    pathologySourceLabels(disease)
  ]);
  appendMedicalTermTeachingSection(pharmDrugDetail, disease);
  appendHighYieldImageSection(pharmDrugDetail, disease, "diseases");

  appendExploreRelatedConcepts(pharmDrugDetail, [
    disease.name,
    disease.category,
    aliases,
    disease.pathology,
    disease.pathophysiology,
    disease.etiology,
    disease.riskFactors,
    disease.signsSymptoms,
    disease.diagnostics,
    disease.treatments,
    disease.contraindications,
    disease.nursingPriorities,
    disease.redFlags,
    pathologyIsolationPrecautionText(disease),
    disease.complications,
    disease.nclexTraps,
    disease.relatedTopics,
    sections
  ], disease.name);

  appendEvidenceSourceSection(pharmDrugDetail, pathologyDatabase, disease);

  if (aliases.length) {
    const aliasSection = document.createElement("section");
    const aliasHeading = document.createElement("strong");
    aliasHeading.textContent = "Also searchable as";
    const chips = document.createElement("div");
    chips.className = "pharm-chip-row";
    aliases.slice(0, 10).forEach((alias) => {
      const chip = document.createElement("span");
      chip.textContent = alias;
      chips.append(chip);
    });
    aliasSection.append(aliasHeading, chips);
    pharmDrugDetail.append(aliasSection);
  }
  syncPharmDetailReadableText();
}

function holisticVisibleLearnerSections(remedy = {}) {
  const sections = [
    ["Used for / marketed for", holisticListText(remedy.usedFor)],
    ["Mechanism / how it works", holisticMechanismText(remedy)],
    ["Major risks every nurse should catch", holisticListText(remedy.majorRisks)],
    ["Interactions to watch", holisticListText(remedy.interactions)],
    ["Contraindications / clarify-before-use", holisticListText(remedy.contraindications)],
    ["Nursing assessment", holisticListText(remedy.nursingAssessment)],
    ["Client teaching", holisticListText(remedy.teaching)],
    ["Population risk notes", pharmPopulationRiskText(remedy)],
    ["Common NCLEX trap / nuance", holisticListText(remedy.nclexTraps)]
  ];
  return sections.map(([label, value], index) => ({
    id: `holistic-visible-section-${index + 1}`,
    label,
    value,
    path: `visibleHolisticSections.${index}`
  }));
}

function renderHolisticDetail(remedy = activeHolisticResults[0]) {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  setPharmDetailTheme("holistic");
  if (!remedy) {
    renderPharmDrugDetail(null);
    return;
  }

  const title = document.createElement("div");
  title.className = "pharm-detail-title pharm-holistic-title";
  const name = document.createElement("h2");
  name.textContent = safeText(remedy.name);
  const category = document.createElement("span");
  category.textContent = safeText(`${remedy.nclexEssential ? "NCLEX HERBAL SAFETY" : "HOLISTIC SAFETY"} | ${remedy.category || "Herbal/holistic entry"}`);
  title.append(name, category);
  appendPharmFavoriteButton(title, "holistic", remedy);
  const riskIcons = renderPharmRiskIcons(remedy);
  if (riskIcons) {
    title.append(riskIcons);
  }
  pharmDrugDetail.append(title);

  const learnerSections = holisticVisibleLearnerSections(remedy);
  const sections = learnerSections.map(({ label, value }) => [label, value]);
  const learnerProjection = projectVisibleLearnerSupport(remedy, learnerSections, { prefix: "holistic-visible-section" });
  const firstLearnerBlockId = learnerProjection.blocks[0]?.id || "";

  let authoredPresentationAttempted = false;
  learnerSections.forEach(({ id, label, value }) => {
    if (!value) return;
    const section = document.createElement("section");
    const heading = document.createElement("strong");
    heading.textContent = label;
    const text = document.createElement("div");
    text.className = "pharm-detail-text";
    appendReadableDetailText(text, value, { currentLabel: remedy.name });
    section.append(heading, text);
    pharmDrugDetail.append(section);
    const learnerBlock = learnerProjection.byId.get(id);
    if (learnerBlock) {
      appendLearnerLanguageSupport(pharmDrugDetail, remedy, {
        currentLabel: remedy.name,
        projectedBlock: learnerBlock,
        includePlainLanguage: learnerBlock.id === firstLearnerBlockId,
        heading: learnerBlock.id === firstLearnerBlockId ? "Medical terms explained" : "Terms in this section"
      });
    }
    if (label === "Used for / marketed for") {
      appendAuthoredPresentationVisuals(remedy);
      authoredPresentationAttempted = true;
      appendMemoryBridgeSections(pharmDrugDetail, remedy);
    }
  });
  if (!authoredPresentationAttempted) appendAuthoredPresentationVisuals(remedy);

  appendMedicalAbbreviationSection(pharmDrugDetail, [
    remedy.name,
    remedy.category,
    ...(remedy.aliases || []),
    holisticListText(remedy.usedFor),
    holisticListText(remedy.majorRisks),
    holisticListText(remedy.interactions),
    holisticListText(remedy.contraindications),
    holisticListText(remedy.nursingAssessment),
    holisticMechanismText(remedy),
    holisticListText(remedy.teaching),
    holisticListText(remedy.nclexTraps)
  ]);
  appendMedicalTermTeachingSection(pharmDrugDetail, remedy);

  const aliases = Array.isArray(remedy.aliases) ? remedy.aliases.filter(Boolean) : [];
  appendExploreRelatedConcepts(pharmDrugDetail, [
    remedy.name,
    remedy.category,
    aliases,
    remedy.usedFor,
    remedy.majorRisks,
    remedy.interactions,
    remedy.contraindications,
    remedy.nursingAssessment,
    remedy.teaching,
    remedy.nclexTraps,
    sections
  ], remedy.name);
  if (aliases.length) {
    const aliasSection = document.createElement("section");
    const aliasHeading = document.createElement("strong");
    aliasHeading.textContent = "Also searchable as";
    const chips = document.createElement("div");
    chips.className = "pharm-chip-row";
    aliases.slice(0, 10).forEach((alias) => {
      const chip = document.createElement("span");
      chip.textContent = alias;
      chips.append(chip);
    });
    aliasSection.append(aliasHeading, chips);
    pharmDrugDetail.append(aliasSection);
  }
  syncPharmDetailReadableText();
}

let pharmClassExampleDrugIndex = null;

function medicationClassExampleNamesForCard(card = {}) {
  return normalizeMedicationClassExampleNames([
    ...(Array.isArray(card.classExampleNames) ? card.classExampleNames : []),
    ...(Array.isArray(card.classExampleKeys) ? card.classExampleKeys : []),
    ...(Array.isArray(card.drugExamples) ? card.drugExamples : [])
  ]);
}

function pharmClassPhraseForDescription(value = "") {
  const text = safeText(value);
  if (!text) return "";
  if (/^[A-Z0-9]{2,}\b/.test(text)) return text;
  return text.replace(/^[A-Z]/, (letter) => letter.toLowerCase());
}

function articleForPharmClassPhrase(value = "") {
  const text = safeText(value).trim();
  if (!text) return "a";
  if (/^[aeiou]/i.test(text) || /^(?:8|11|18)\b/i.test(text)) return "an";
  if (/^(?:NMDA|SNRI|SSRI|NSAID|ACE|ARB|SGLT|HMG|RSV|RNA|mRNA)\b/i.test(text)) return "an";
  return "a";
}

function pharmSentenceContinuationPhrase(value = "") {
  const text = safeText(value);
  if (!text) return "";
  if (/^[A-Z0-9]{2,}\b/.test(text)) return text;
  return text.replace(/^[A-Z]/, (letter) => letter.toLowerCase());
}

function pharmCrashCourseClassPhrase(value = "") {
  return safeText(value)
    .replace(/\s*;\s*/g, " and ")
    .replace(/\s+/g, " ")
    .trim();
}

function pharmMechanismCrashCourseClause(value = "", name = "") {
  const text = pharmOpeningFirstSentences(value, 1)
    .replace(new RegExp(`^${escapeRegex(name)}\\s+works\\s+by\\s+`, "i"), "")
    .replace(new RegExp(`^${escapeRegex(name)}\\s+`, "i"), "")
    .replace(/^\w+\s+works\s+by\s+/i, "")
    .replace(/^works\s+by\s+/i, "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/[.!?]+$/, "");
  if (!text) return "";
  const identityPrefix = normalizePharmText(name).split(" ").filter((word) => word.length > 2).slice(-2).join("\\s+");
  const withoutRepeatedName = identityPrefix
    ? text.replace(new RegExp(`^(?:${identityPrefix})\\s+`, "i"), "")
    : text;
  const polishedMechanismLead = withoutRepeatedName
    .replace(/^products contain\b/i, "contains")
    .replace(/^supply\b/i, "supplies")
    .replace(/^acts? by\b/i, "acts by");
  const directVerbPattern = /^(?:it\s+)?(?:(?:primarily|selectively|competitively|irreversibly|reversibly|briefly|directly|indirectly|rapidly|slowly|locally|systemically)\s+)*(?:blocks?|inhibits?|stimulates?|activates?|binds?|exchanges?|replaces?|supplements?|opens?|closes?|relaxes?|suppresses?|enhances?|antagonizes?|agonizes?|prevents?|stabilizes?|increases?|decreases?|constricts?|dilates?|lowers?|raises?|converts?|mimics?|reduces?|promotes?|provides?|counteracts?|neutralizes?|targets?|interferes?|disrupts?|releases?|shifts?|cleaves?|generates?|removes?|supplies?)\b/i;
  if (directVerbPattern.test(polishedMechanismLead)) {
    return polishedMechanismLead.replace(/^it\s+/i, "");
  }
  if (/^(?:(?:primarily|selectively|competitively|irreversibly|reversibly|briefly|directly|indirectly|rapidly|slowly|locally|systemically)\s+)*(?:[a-z]+ing)\b/i.test(polishedMechanismLead)
    && !/^(?:during|following|according|including)\b/i.test(polishedMechanismLead)) {
    return `works by ${polishedMechanismLead}`;
  }
  return polishedMechanismLead;
}

function pharmOpeningFirstSentences(value = "", count = 2) {
  const decimalDot = "__ANI_DECIMAL_DOT__";
  const text = safeText(value)
    .replace(/(\d)\.(\d)/g, `$1${decimalDot}$2`)
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return "";
  const pieces = text.match(/[^.!?]+[.!?]+|[^.!?]+$/g) || [text];
  return pieces.slice(0, count).join(" ").replaceAll(decimalDot, ".").replace(/\s+/g, " ").trim();
}

function pharmOpeningDescriptionStartsTooBroad(value = "") {
  const first = pharmOpeningFirstSentences(value, 2);
  if (!first) return false;
  return /\bis an? (?:cardiovascular|respiratory|endocrine|renal|gastrointestinal|central nervous system|neurology|antiinfective|psychiatric\/?cns|emergency\/?critical-care|hematology|oncology|pain|anesthesia|dermatology|ophthalmic|otic) (?:drug|medication)\b/i.test(first)
    || /\bis an? [a-z, /-]{12,80} medication used in\b/i.test(first)
    || /\bis an? [a-z, /-]{12,80} drug used in\b/i.test(first)
    || /\bused in [a-z, /-]+ contexts\b/i.test(first)
    || /\bcurrent study anchor\b/i.test(first);
}

function pharmOpeningDescriptionHasCrashCourseShape(value = "", drug = {}) {
  const first = pharmOpeningFirstSentences(value, 2);
  if (!first) return false;
  if (pharmOpeningDescriptionStartsTooBroad(first) || pharmOpeningRawTextIsGeneric(first)) return false;
  const joined = normalizePharmText([
    first,
    pharmDisplayClass(drug),
    pharmMechanismText(drug),
    pharmUsedToTreat(drug)
  ].join(" "));
  const hasSpecificIdentity = /\b(inhibitor|agonist|antagonist|blocker|modulator|analog|antibiotic|antiviral|antifungal|anticoagulant|antiplatelet|diuretic|vasodilator|inodilator|stimulant|sedative|anesthetic|antipsychotic|antidepressant|resin|binder|electrolyte|hormone|vaccine|antidote|enzyme|receptor|channel|transporter|polymer|monoclonal|antibody|immunoglobulin|igg|kinase|biologic|beta|alpha|muscarinic|dopamine|serotonin|gaba|pde|phosphodiesterase|rna|dna|ribosomal|cell wall|osmotic|crystalloid)\b/i.test(joined);
  const firstJoined = normalizePharmText(first);
  const actionPattern = /\b(block\w*|inhibit\w*|stimulat\w*|activat\w*|bind\w*|exchang\w*|replac\w*|suppl\w*|open\w*|clos\w*|relax\w*|suppress\w*|enhanc\w*|antagoniz\w*|agoniz\w*|prevent\w*|stabiliz\w*|increas\w*|decreas\w*|constrict\w*|dilat\w*|lower\w*|rais\w*|convert\w*|mimic\w*|reduc\w*|promot\w*|produc\w*|provid\w*|expand\w*|support\w*|build\w*|donat\w*|interrupt\w*|trap\w*|form\w*|injur\w*|restor\w*|deliver\w*|counteract\w*|neutraliz\w*|target\w*|interfer\w*|disrupt\w*|releas\w*|shift\w*|us\w*|exert\w*|cleav\w*|generat\w*|hold\w*|flush\w*|displac\w*|monitor\w*)\b/i;
  const hasAction = actionPattern.test(joined);
  const firstHasAction = actionPattern.test(firstJoined);
  return hasSpecificIdentity && hasAction && firstHasAction;
}
function pharmOpeningFirstSentenceDelaysMechanism(value = "") {
  const first = pharmOpeningFirstSentences(value, 1);
  if (!first) return false;
  const normalized = normalizePharmText(first);
  const mechanismAction = /\b(block\w*|inhibit\w*|stimulat\w*|activat\w*|bind\w*|exchang\w*|replac\w*|open\w*|clos\w*|relax\w*|suppress\w*|enhanc\w*|antagoniz\w*|agoniz\w*|prevent\w*|stabiliz\w*|increas\w*|decreas\w*|constrict\w*|dilat\w*|lower\w*|rais\w*|convert\w*|mimic\w*|reduc\w*|promot\w*|produc\w*|provid\w*|support\w*|build\w*|donat\w*|interrupt\w*|trap\w*|form\w*|injur\w*|restore\w*|counteract\w*|neutraliz\w*|interfer\w*|disrupt\w*|releas\w*|shift\w*|cleav\w*|generat\w*|adsorb\w*|coat\w*|soften\w*|modulat\w*|depolariz\w*|cross-link\w*)\b/i;
  if (mechanismAction.test(normalized)) return false;
  return /^.+\s+is\s+an?\s+[^.:;!?]{8,150}\.$/i.test(first)
    || /^.+\s+is\s+an?\s+[^.:;!?]{8,150}\b(?:used|reference|therapy|agent|medication|drug)\b/i.test(first);
}

function pharmCardDescriptionText(drug = {}) {
  const placeholder = /\b(description pending|not fully curated|verify current|recognition only|expanded medication reference|works through its drug class|expected action should match|mechanism depends on the individual medication|class reference for medications|used in [a-z, /-]+ contexts|for nclex study, connect|labeled indication and formulation match|class suggests the main clinical role|this is a monitoring card)\b/i;
  // curated-frontier-opening-precedence
  const direct = pharmListText(Array.isArray(drug.description) ? drug.description : [drug.description || drug.summary || drug.overview]);
  if (isNavigationOnlyGeneratedMedicationClass(drug)) {
    return generatedMedicationClassNavigationDescription(drug.generatedClassSegment, drug.classExampleNames);
  }
  if (drug.generatedClassCard === true) return direct;
  const isCuratedFullStudyCard = /\bcurated (?:full study|drug class) card\b/i.test([drug.confidenceTier, drug.templateKey].filter(Boolean).join(" "))
    || (Array.isArray(drug.tags) && drug.tags.some((tag) => /^frontier wave\d+$/i.test(normalizePharmText(tag))));
  const overlayDescription = safeText(pharmTeachingOverlay(drug).description);
  if (!isCuratedFullStudyCard && overlayDescription
    && !placeholder.test(overlayDescription)
    && !pharmOpeningRawTextIsGeneric(overlayDescription)
    && !pharmOpeningDescriptionStartsTooBroad(overlayDescription)
    && !pharmOpeningFirstSentenceDelaysMechanism(overlayDescription)) {
    return overlayDescription;
  }
  if (isCuratedFullStudyCard
    && direct.length >= 160
    && !placeholder.test(direct)
    && !pharmOpeningRawTextIsGeneric(direct)
    && !pharmOpeningDescriptionStartsTooBroad(direct)) {
    return direct;
  }
  if (direct
    && !placeholder.test(direct)
    && pharmOpeningDescriptionHasCrashCourseShape(direct, drug)
    && !pharmOpeningFirstSentenceDelaysMechanism(direct)) {
    return direct;
  }
  const name = pharmDrugDisplayName(drug, "This medication class");
  if (!isMedicationClassCardEntry(drug)) {
    const classText = pharmDisplayClass(drug);
    const uses = pharmUsedToTreat(drug);
    const mechanism = pharmMechanismText(drug);
    const classPhrase = pharmCrashCourseClassPhrase(pharmClassPhraseForDescription(classText));
    const classArticle = articleForPharmClassPhrase(classPhrase);
    const usePhrase = pharmSentenceContinuationPhrase(uses.replace(/\.$/, ""));
    const mechanismPhrase = pharmMechanismCrashCourseClause(mechanism, name);
    const hasUsableClass = classText
      && !/^(medication reference|pharmacology reference|nclex medication reference)$/i.test(classText)
      && !pharmOpeningClassLooksUnhelpful(classText);
    const mechanismSentence = mechanismPhrase && !/[.!?]$/.test(mechanismPhrase) ? `${pharmSentenceContinuationPhrase(mechanismPhrase)}.` : mechanismPhrase;
    const mechanismLead = /^(?:this\s+is|an?\s+)\b/i.test(mechanismSentence)
      ? mechanismSentence
      : /^works\s+by\b/i.test(mechanismSentence)
        ? `it ${mechanismSentence}`
        : `it ${mechanismSentence}`;
    const classPart = hasUsableClass
      ? mechanismSentence
        ? `${name} is ${classArticle} ${classPhrase}: ${mechanismLead}`
        : `${name} is ${classArticle} ${classPhrase}.`
      : mechanismSentence
        ? /^works\s+by\b/i.test(mechanismSentence)
          ? `${name} ${mechanismSentence}`
          : `${name} works by ${mechanismSentence}`
        : `${name} is a medication entry.`;
    const mechanismPart = "";
    const usePart = usePhrase ? ` It is used for ${usePhrase}.` : "";
    return `${classPart}${mechanismPart}${usePart}`.trim();
  }
  const mechanism = safeText(drug.mechanism);
  const uses = pharmUsedToTreat(drug);
  const cleanClassLabel = name
    .replace(/\s+drugs$/i, "")
    .replace(/\s+class$/i, "")
    .replace(/\s+medications$/i, " medications")
    .trim();
  const mechanismCore = safeText(mechanism)
    .replace(/^Shared action:\s*/i, "")
    .replace(/\bmedication medications\b/gi, "medications")
    .replace(/\s+/g, " ")
    .trim();
  const usesCore = safeText(uses)
    .replace(/\s+/g, " ")
    .trim();
  if (mechanismCore && !pharmOpeningRawTextIsGeneric(mechanismCore)) {
    return `The ${cleanClassLabel || name} class targets a defined pharmacologic pathway: ${pharmSentenceContinuationPhrase(mechanismCore.replace(/\.$/, ""))}. ${usesCore ? `Clinical uses: ${usesCore}` : "Member indications depend on the specific drug and formulation."}`;
  }
  return [
    `${cleanClassLabel || name} are medications grouped by a shared clinical role, target, or bedside safety pattern.`,
    usesCore ? `Use pattern: ${usesCore}` : "Use pattern: compare whether the card is a treatment class, prevention class, rescue class, or monitoring/safety class.",
    "Learning hook: compare the organism or receptor target, route, contraindications, toxicity pattern, and monitoring clue that separates each example."
  ].filter(Boolean).join(" ");
}

function pharmOpeningRawTextIsGeneric(value = "") {
  return /\b(works through its(?: .*?)? pharmacology|works through its drug class|targeting bacterial structures or replication pathways|tie the mechanism|used when its pharmacologic effect fits|entries are used when their shared pharmacology matches|summarizes the class-level pharmacology|shared pharmacology pattern|share(?:s)? a class-level target|most important clinical anchors|for nclex study, connect|should be studied through|study it by|mechanism depends on the individual medication|mechanism depends on the drug class|intended therapeutic effect|expected action should match|it supply\b|it products contain\b|class reference for medications|name recognition only|not fully curated|needs mechanism review|this medication class is a medication entry|current study anchor|counteracts the toxic agent|the mechanism is antidote-specific|receptor displacement, cofactor repletion, chelation, immune binding)\b/i.test(safeText(value));
}

function pharmOpeningClassLooksUnhelpful(value = "") {
  const text = safeText(value).toLowerCase().replace(/\s+/g, " ").trim();
  if (!text) return true;
  if (/^(drug class card|medication reference|pharmacology reference|nclex medication reference|medication class reference|unknown)$/i.test(text)) return true;
  if (/^(cardiovascular|respiratory|renal|endocrine|gastrointestinal|central nervous system|neurology|antiinfective|psychiatric\/cns|emergency\/critical-care) medication$/i.test(text)) return true;
  if (pharmOpeningRawTextIsGeneric(text)) return true;
  return false;
}

function pharmOpeningHydrationList(value) {
  if (Array.isArray(value)) return value.filter(Boolean);
  return value ? [value] : [];
}

function hydratePharmCrashCourseOpeners() {
  if (pharmCrashCourseOpenersHydrated && pharmVisibleDrugPoolCache) return pharmVisibleDrugPoolCache;
  pharmCrashCourseOpenersHydrated = true;
  const visiblePool = pharmDrugs.filter(isVisibleMedicationEntry);
  visiblePool.forEach((drug) => {
    if (!drug || typeof drug !== "object") return;
    if (isMedicationClassCardEntry(drug)) return;

    const rawClass = safeText(drug.class);
    if (pharmOpeningClassLooksUnhelpful(rawClass)) {
      const displayClass = safeText(pharmDisplayClass(drug));
      if (displayClass && !pharmOpeningClassLooksUnhelpful(displayClass)) {
        drug.class = displayClass;
      }
    }

    const rawUses = pharmListText(pharmOpeningHydrationList(drug.usedToTreat || drug.indications || drug.commonUses));
    if (!rawUses || rawUses.length < 18 || pharmOpeningRawTextIsGeneric(rawUses)) {
      const uses = safeText(pharmUsedToTreat(drug));
      if (uses && uses.length >= 18 && !pharmOpeningRawTextIsGeneric(uses)) {
        drug.usedToTreat = uses;
      }
    }

    const rawMechanism = safeText(drug.mechanism);
    if (!rawMechanism || rawMechanism.length < 65 || pharmOpeningRawTextIsGeneric(rawMechanism) || pharmMechanismLooksShallow(rawMechanism)) {
      const mechanism = safeText(pharmMechanismText(drug));
      if (mechanism && mechanism.length >= 65 && !pharmOpeningRawTextIsGeneric(mechanism)) {
        drug.mechanism = mechanism;
      }
    }

    const rawDescription = pharmListText(pharmOpeningHydrationList(drug.description || drug.summary || drug.overview));
    if (!rawDescription || rawDescription.length < 80 || pharmOpeningRawTextIsGeneric(rawDescription) || !pharmOpeningDescriptionHasCrashCourseShape(rawDescription, drug)) {
      const description = safeText(pharmCardDescriptionText(drug));
      if (description && description.length >= 80 && !pharmOpeningRawTextIsGeneric(description)) {
        drug.description = description;
      }
    }
  });
  pharmVisibleDrugPoolCache = visiblePool;
  return pharmVisibleDrugPoolCache;
}

hydratePharmCrashCourseOpeners();
getPharmPrimaryIdentityExactIndex();

function getPharmClassExampleDrugIndex() {
  if (pharmClassExampleDrugIndex) return pharmClassExampleDrugIndex;
  const index = new Map();
  pharmDrugs.forEach((drug) => {
    if (!isVisibleMedicationEntry(drug) || isMedicationClassCardEntry(drug)) return;
    [
      drug.generic,
      drug.name,
      drug.displayName,
      pharmDrugDisplayName(drug, "")
    ].forEach((value) => {
      const key = normalizePharmText(value);
      if (key && !index.has(key)) {
        index.set(key, drug);
      }
    });
  });
  pharmClassExampleDrugIndex = index;
  return index;
}

function resolveMedicationClassExampleDrugs(card = {}) {
  const names = medicationClassExampleNamesForCard(card);
  if (!names.length) return [];
  const index = getPharmClassExampleDrugIndex();
  const seen = new Set();
  return names
    .map((name) => {
      const direct = index.get(normalizePharmText(name));
      return direct || exactPharmIdentityMatch(name);
    })
    .filter((drug) => drug && !isMedicationClassCardEntry(drug))
    .filter((drug) => {
      const key = normalizePharmText(drug.generic || pharmDrugDisplayName(drug, "") || drug.name);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .sort((a, b) => pharmDrugDisplayName(a, "").localeCompare(pharmDrugDisplayName(b, ""), undefined, { sensitivity: "base" }));
}

function appendMedicationClassExampleLinks(container, card = {}) {
  if (!container || !isMedicationClassCardEntry(card)) return;
  const examples = resolveMedicationClassExampleDrugs(card);
  if (!examples.length) return;
  const section = document.createElement("section");
  section.className = "pharm-class-examples-section";
  // This is navigation UI, not educational prose for card narration.
  section.dataset.skipRead = "true";
  const heading = document.createElement("strong");
  heading.textContent = "Drug examples in this class";
  const hint = document.createElement("p");
  hint.className = "pharm-class-example-hint";
  hint.textContent = "Tap any drug to open its full card.";
  const list = document.createElement("div");
  list.className = "pharm-class-example-list";
  const fragment = document.createDocumentFragment();
  examples.forEach((exampleDrug) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "pharm-class-example-link";
    const label = document.createElement("span");
    label.textContent = pharmDrugDisplayName(exampleDrug);
    const sublabel = document.createElement("small");
    sublabel.textContent = pharmDisplayClass(exampleDrug) || "Open drug card";
    button.append(label, sublabel);
    button.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      openPharmDetailCandidate({ type: "drug", item: exampleDrug }, { autoRead: false });
    });
    fragment.append(button);
  });
  list.append(fragment);
  section.append(heading, hint, list);
  container.append(section);
}

function pharmacyVisibleLearnerSections(drug = {}) {
  if (drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only") return [];
  const sections = [
    ["What this is", pharmCardDescriptionText(drug)],
    ["NCLEX status", isNclexCorePharmEntry(drug) ? `${pharmStudyTier(drug)}${drug.nclexEssentialRank ? ` #${drug.nclexEssentialRank}` : ""}` : ""],
    ["Specific class / pathway", pharmClassPathwayText(drug)],
    ["Used to treat / common uses", pharmUsedToTreat(drug)],
    ["Mechanism / how it works", pharmMechanismText(drug)],
    ["Action sequence / timing", pharmListText(drug.administrationTiming)],
    ["Boxed warning / high-alert warning", pharmBoxedWarningDisplay(drug, pharmOverlayValue(drug, "warning", drug.boxedWarning))],
    ["Major adverse effects / toxicity cues", pharmOverlayValue(drug, "adverseEffects", pharmAdverseEffectsText(drug))],
    ["Serious adverse reactions", pharmListText(drug.seriousAdverseReactions)],
    ["Contraindications / clarify-before-giving", pharmOverlayValue(drug, "contraindications", pharmListText(drug.contraindications))],
    ["Key nursing concepts", pharmOverlayValue(drug, "nursing", pharmListText(drug.nursingEssentials))],
    ["Interactions to watch", pharmOverlayValue(drug, "interactions", pharmListText(drug.interactions))],
    ["Routes / administration", pharmListText([drug.routes, drug.administration])],
    ["Toxicity / overdose response", pharmListText(drug.toxicityManagement)],
    ["Population risk notes", pharmPopulationRiskText(drug)],
    ["Special populations", pharmListText(drug.specialPopulations)],
    ["Labs / assessment", pharmOverlayValue(drug, "labs", pharmListText(drug.keyLabs))],
    ["Patient education", pharmListText(drug.patientEducation)],
    ["Escalation / recurrence", pharmListText(drug.escalationRecurrence)],
    ["Evidence boundaries", pharmListText(drug.evidenceLimitations)],
    ["Regulatory / approval context", drug.regulatoryStatus],
    ["NCLEX trap", pharmOverlayValue(drug, "trap", pharmListText(drug.nclexTraps))]
  ];
  return sections.map(([label, value], index) => ({
    id: `pharmacy-visible-section-${index + 1}`,
    label,
    value,
    path: `visiblePharmacySections.${index}`
  }));
}

function renderPharmDrugDetail(drug = activePharmResults[0]) {
  if (!pharmDrugDetail) return;
  resetPharmDetailCard();
  setPharmDetailTheme("drugs");
  if (!drug) {
    const empty = document.createElement("p");
    empty.textContent = "Search a medication, class, interaction, lab, disease, pathology, herbal, or supplement to see details.";
    pharmDrugDetail.append(empty);
    syncPharmDetailReadableText();
    return;
  }

  const navigationOnlyGeneratedClass = drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only";
  const title = document.createElement("div");
  title.className = "pharm-detail-title";
  const name = document.createElement("h2");
  name.textContent = pharmDrugDisplayName(drug);
  const drugClass = document.createElement("span");
  drugClass.textContent = pharmDrugMetaText(drug);
  title.append(name, drugClass);
  appendPharmFavoriteButton(title, "drugs", drug);
  appendPeptideStatusBadges(title, drug);
  const riskIcons = navigationOnlyGeneratedClass ? null : renderPharmRiskIcons(drug);
  if (riskIcons) {
    title.append(riskIcons);
  }
  pharmDrugDetail.append(title);

  if (navigationOnlyGeneratedClass) {
    [
      ["What this is", pharmCardDescriptionText(drug)],
      ["Specific class / pathway", pharmClassPathwayText(drug)]
    ].forEach(([label, value]) => {
      if (!value) return;
      const section = document.createElement("section");
      const heading = document.createElement("strong");
      heading.textContent = label;
      const text = document.createElement("div");
      text.className = "pharm-detail-text";
      appendReadableDetailText(text, value, { currentLabel: pharmDrugDisplayName(drug) });
      section.append(heading, text);
      pharmDrugDetail.append(section);
    });
    appendMedicationClassExampleLinks(pharmDrugDetail, drug);
    syncPharmDetailReadableText();
    return;
  }

  const learnerSections = pharmacyVisibleLearnerSections(drug);
  const sections = learnerSections.map(({ label, value }) => [label, value]);
  const learnerProjection = projectVisibleLearnerSupport(drug, learnerSections, { prefix: "pharmacy-visible-section" });
  const firstLearnerBlockId = learnerProjection.blocks[0]?.id || "";

  let classExampleLinksAdded = false;
  let authoredPresentationAttempted = false;
  learnerSections.forEach(({ id, label, value }) => {
    if (!value) return;
    const section = document.createElement("section");
    if (label === "NCLEX status") {
      // Preserve the visible study badge while skipping metadata in read-aloud.
      section.dataset.skipRead = "true";
    }
    const heading = document.createElement("strong");
    heading.textContent = label;
    const text = document.createElement("div");
    text.className = "pharm-detail-text";
    appendReadableDetailText(text, value, { currentLabel: pharmDrugDisplayName(drug) });
    section.append(heading, text);
    pharmDrugDetail.append(section);
    const learnerBlock = learnerProjection.byId.get(id);
    if (learnerBlock) {
      appendLearnerLanguageSupport(pharmDrugDetail, drug, {
        currentLabel: pharmDrugDisplayName(drug),
        projectedBlock: learnerBlock,
        includePlainLanguage: learnerBlock.id === firstLearnerBlockId,
        heading: learnerBlock.id === firstLearnerBlockId ? "Medical terms explained" : "Terms in this section"
      });
    }
    if (label === "What this is") {
      appendAuthoredPresentationVisuals(drug);
      authoredPresentationAttempted = true;
      appendMemoryBridgeSections(pharmDrugDetail, drug);
    }
    if (label === "What this is" && isMedicationClassCardEntry(drug)) {
      appendMedicationClassExampleLinks(pharmDrugDetail, drug);
      classExampleLinksAdded = true;
    }
  });
  if (!authoredPresentationAttempted) appendAuthoredPresentationVisuals(drug);
  if (isMedicationClassCardEntry(drug) && !classExampleLinksAdded) {
    appendMedicationClassExampleLinks(pharmDrugDetail, drug);
  }

  appendMedicalAbbreviationSection(pharmDrugDetail, [
    pharmDrugDisplayName(drug),
    drug.generic,
    pharmStudyTier(drug),
    pharmDisplayClass(drug),
    pharmClassPathwayText(drug),
    pharmCardDescriptionText(drug),
    pharmUsedToTreat(drug),
    pharmBoxedWarningDisplay(drug),
    pharmAdverseEffectsText(drug),
    pharmMechanismText(drug),
    pharmListText(drug.administrationTiming),
    pharmListText(drug.contraindications),
    pharmListText(drug.nursingEssentials),
    pharmListText(drug.interactions),
    pharmListText(drug.keyLabs),
    pharmListText(drug.escalationRecurrence),
    pharmListText(drug.evidenceLimitations),
    drug.regulatoryStatus,
    pharmListText(drug.nclexTraps),
    ...(drug.brandExamples || []),
    ...(drug.aliases || [])
  ]);
  appendMedicalTermTeachingSection(pharmDrugDetail, drug);
  appendHighYieldImageSection(pharmDrugDetail, drug, "drugs");

  const aliases = [
    ...(drug.brandExamples || []),
    ...(drug.aliases || [])
  ].filter(Boolean);
  appendExploreRelatedConcepts(pharmDrugDetail, [
    pharmDrugDisplayName(drug),
    drug.generic,
    pharmDisplayClass(drug),
    pharmClassPathwayText(drug),
    pharmCardDescriptionText(drug),
    pharmUsedToTreat(drug),
    pharmBoxedWarningDisplay(drug),
    pharmAdverseEffectsText(drug),
    pharmMechanismText(drug),
    drug.administrationTiming,
    drug.contraindications,
    drug.nursingEssentials,
    drug.interactions,
    drug.keyLabs,
    drug.escalationRecurrence,
    drug.evidenceLimitations,
    drug.regulatoryStatus,
    drug.nclexTraps,
    aliases,
    sections
  ], pharmDrugDisplayName(drug));
  appendEvidenceSourceSection(pharmDrugDetail, pharmDatabase, drug);
  if (aliases.length) {
    const aliasSection = document.createElement("section");
    const aliasHeading = document.createElement("strong");
    aliasHeading.textContent = "Brand names / aliases that may contain this generic";
    const chips = document.createElement("div");
    chips.className = "pharm-chip-row";
    aliases.slice(0, 8).forEach((alias) => {
      const chip = document.createElement("span");
      chip.textContent = alias;
      chips.append(chip);
    });
    aliasSection.append(aliasHeading, chips);
    pharmDrugDetail.append(aliasSection);
  }
  syncPharmDetailReadableText();
}

function encyclopediaExactIdentityIndex(items = [], namesForItem = () => [], exactQueryTexts = []) {
  const querySet = new Set((exactQueryTexts || []).map((value) => normalizePharmText(value)).filter(Boolean));
  if (!querySet.size) return -1;
  return (items || []).findIndex((item) => {
    const rawNames = namesForItem(item);
    const names = Array.isArray(rawNames) ? rawNames : [rawNames];
    return names
      .map((name) => normalizePharmText(name))
      .filter(Boolean)
      .some((name) => querySet.has(name));
  });
}

function encyclopediaNearIdentityNames(item = {}, namesForItem = () => []) {
  const cache = encyclopediaNearIdentityNames.cache || (encyclopediaNearIdentityNames.cache = new WeakMap());
  if (item && typeof item === "object" && cache.has(item)) return cache.get(item);
  const rawIdentityNames = namesForItem(item);
  const names = Array.from(new Set((Array.isArray(rawIdentityNames) ? rawIdentityNames : [rawIdentityNames])
    .map((name) => normalizePharmText(name))
    .filter((name) => name.length >= 5)));
  if (item && typeof item === "object") cache.set(item, names);
  return names;
}

function warmEncyclopediaNearIdentityCache(items = [], namesForItem = () => []) {
  encyclopediaNearIdentityCatalog(items, namesForItem);
}

function nearIdentityEditDistance(a = "", b = "") {
  const source = normalizePharmText(a);
  const target = normalizePharmText(b);
  const baseline = levenshteinDistance(source, target);
  if (baseline !== 2 || source.length !== target.length) return baseline;
  const mismatches = [];
  for (let index = 0; index < source.length; index += 1) {
    if (source[index] !== target[index]) mismatches.push(index);
    if (mismatches.length > 2) return baseline;
  }
  if (mismatches.length !== 2 || mismatches[1] !== mismatches[0] + 1) return baseline;
  const [left, right] = mismatches;
  return source[left] === target[right] && source[right] === target[left]
    ? 1
    : baseline;
}

function encyclopediaNearIdentityCatalog(items = [], namesForItem = () => []) {
  const cache = encyclopediaNearIdentityCatalog.cache || (encyclopediaNearIdentityCatalog.cache = new WeakMap());
  if (items && typeof items === "object" && cache.has(items)) return cache.get(items);
  const byFirstLength = new Map();
  const byInnerLength = new Map();
  const add = (map, key, record) => {
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(record);
  };
  (items || []).forEach((item, index) => {
    const primaryIdentities = new Set([
      item?.name,
      item?.generic,
      item?.displayName,
      item?.fullForm
    ].map((name) => normalizePharmText(name)).filter(Boolean));
    encyclopediaNearIdentityNames(item, namesForItem).forEach((name) => {
      const record = { index, item, name, primaryIdentity: primaryIdentities.has(name) };
      add(byFirstLength, name[0] + ":" + name.length, record);
      add(byInnerLength, name.slice(1, 3) + ":" + name.length, record);
    });
  });
  const catalog = { byFirstLength, byInnerLength };
  if (items && typeof items === "object") cache.set(items, catalog);
  return catalog;
}

function encyclopediaNearIdentityAssessment(items = [], namesForItem = () => [], queryTexts = []) {
  const queries = Array.from(new Set((queryTexts || [])
    .map((value) => normalizePharmText(value))
    .filter((value) => value.length >= 5)))
    .slice(0, 2);
  if (!queries.length) return { match: null, ambiguous: false, candidates: [] };
  const catalog = encyclopediaNearIdentityCatalog(items, namesForItem);
  const candidateScores = new Map();

  queries.forEach((query) => {
    const queryTokenCount = query.split(" ").filter(Boolean).length;
    const radius = Math.max(3, Math.ceil(query.length * 0.15));
    const records = new Set();
    for (let length = Math.max(5, query.length - radius); length <= query.length + radius; length += 1) {
      (catalog.byFirstLength.get(query[0] + ":" + length) || []).forEach((record) => records.add(record));
      (catalog.byInnerLength.get(query.slice(1, 3) + ":" + length) || []).forEach((record) => records.add(record));
    }
    records.forEach(({ index, item, name, primaryIdentity }) => {
        if (query === name) return;
        const maxLength = Math.max(query.length, name.length);
        const allowedDistance = maxLength <= 7
          ? 1
          : maxLength <= 18
            ? 2
            : Math.max(3, Math.floor(maxLength * 0.12));
        if (Math.abs(query.length - name.length) > allowedDistance) return;
        if (query[0] !== name[0] && query.slice(1, 3) !== name.slice(1, 3)) return;
        const nameTokenCount = name.split(" ").filter(Boolean).length;
        if (queryTokenCount >= 2 && Math.abs(queryTokenCount - nameTokenCount) > 1) return;
        const distance = nearIdentityEditDistance(query, name);
        if (!distance || distance > allowedDistance) return;
        const similarity = 1 - (distance / maxLength);
        const minimumSimilarity = queryTokenCount >= 2 ? 0.84 : (maxLength <= 7 ? 0.84 : 0.8);
        if (similarity < minimumSimilarity) return;
        const rankScore = similarity;
        const current = candidateScores.get(index);
        if (!current
          || rankScore > current.rankScore
          || (rankScore === current.rankScore && primaryIdentity && !current.primaryIdentity)) {
          candidateScores.set(index, { index, item, score: similarity, rankScore, identity: name, primaryIdentity });
        }
    });
  });

  const candidates = Array.from(candidateScores.values());
  candidates.sort((a, b) => b.rankScore - a.rankScore
    || Number(b.primaryIdentity) - Number(a.primaryIdentity)
    || a.index - b.index);
  const best = candidates[0] || null;
  const runnerUp = best ? candidates.find((candidate) => candidate.item !== best.item) || null : null;
  if (!best) return { match: null, ambiguous: false, candidates: [] };
  const sameIdentity = runnerUp && normalizePharmText(best.identity) === normalizePharmText(runnerUp.identity);
  const uniquePrimaryWinner = sameIdentity && best.primaryIdentity && !runnerUp.primaryIdentity;
  if (runnerUp
    && !uniquePrimaryWinner
    && (sameIdentity || (best.rankScore - runnerUp.rankScore < 0.035 && best.score < 0.96))) {
    return { match: null, ambiguous: true, candidates: [best, runnerUp], sameIdentity: Boolean(sameIdentity) };
  }
  return { match: best, ambiguous: false, candidates: [best] };
}

function encyclopediaNearIdentityMatch(items = [], namesForItem = () => [], queryTexts = []) {
  return encyclopediaNearIdentityAssessment(items, namesForItem, queryTexts).match;
}

