function antiarrhythmicClassFilterFromInput(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input))
    .replace(/\bclass\s+1\b/g, "class i")
    .replace(/\bclass\s+2\b/g, "class ii")
    .replace(/\bclass\s+3\b/g, "class iii")
    .replace(/\bclass\s+4\b/g, "class iv");
  const hasAntiarrhythmicContext = /\b(antiarrhythmic|antiarrhythmics|anti arrhythmic|anti arrythmic|antidysrhythmic|dysrhythmia|arrhythmia|rhythm medication|rhythm drug)\b/i.test(lower)
    || /\b(?:sodium|potassium|calcium|beta)[-\s]?(?:channel|blocker)/i.test(lower);
  if (!hasAntiarrhythmicContext) return null;
  return OFFLINE_ANTIARRHYTHMIC_CLASS_FILTERS.find((filter) => filter.requestPattern.test(lower)) || null;
}

function wantsOfflineListFromEncyclopedia(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  if (!lower) return false;
  if (wantsOfflineTeratogenicDrugList(lower)) {
    return true;
  }
  if (wantsAiGeneratedStudyWork(input) || wantsLecture(input) || wantsOfflineLabComparison(input)) {
    return false;
  }
  if (wantsOfflineListExpansionFollowup(lower) || wantsOfflineBroadCauseList(lower)) {
    return true;
  }
  const classDefinition = offlineDrugClassDefinitionForInput(lower);
  const listCue = /\b(list|lists|show(?: me)?|give(?: me)?|name|names|examples?|bunch|all|which|what are|what can|what could|what medications|what meds|what drugs|pull up)\b/i.test(lower);
  const conciseClassCue = Boolean(classDefinition && wantsMedicationClassLookup(lower));
  const categoryCue = /\b(drugs?|meds?|medications?|medicines?|classes?|labs?|ranges?|diseases?|patholog(?:y|ies)|conditions?|diagnostic tests?|tests?|procedures?|herbals?|supplements?|holistic)\b/i.test(lower)
    || Boolean(classDefinition);
  return (listCue || conciseClassCue) && categoryCue;
}

function extractOfflineListTopic(input = "") {
  const fixed = compactSpokenMedicalAcronyms(input);
  const clean = normalizeOfflineLookupText(fixed, { dropLookupWords: false }) || normalizePharmText(fixed);
  return clean
    .split(" ")
    .filter((token) => token.length > 1 && !OFFLINE_LIST_REQUEST_DROP_WORDS.has(token))
    .join(" ")
    .trim();
}

function titleCaseOfflineTopic(text = "") {
  return normalizePharmText(text)
    .split(" ")
    .filter(Boolean)
    .map((token) => token.length <= 4 && PHARM_CLASS_ACRONYM_TERMS.has(token)
      ? token.toUpperCase()
      : `${token.charAt(0).toUpperCase()}${token.slice(1)}`)
    .join(" ");
}

function offlineDrugClassDefinitionForInput(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  return OFFLINE_DRUG_CLASS_LIST_DEFINITIONS.find((definition) => definition.requestPattern.test(lower)) || null;
}

const offlineDrugClassBlobCache = new WeakMap();

function offlineDrugClassSearchBlob(drug = {}) {
  if (offlineDrugClassBlobCache.has(drug)) return offlineDrugClassBlobCache.get(drug);
  const identityTerms = pharmIdentityTermsForEntry(drug);
  const blob = normalizePharmText([
    ...identityTerms,
    drug.class,
    drug.templateKey,
    sanitizeMedicalReferenceText(drug.sourceNote),
    ...sanitizeMedicationTermListForSingleDrug(drug, drug.tags || [])
  ].join(" "));
  offlineDrugClassBlobCache.set(drug, blob);
  return blob;
}

function offlineDrugClassOnlyBlob(drug = {}) {
  return normalizePharmText([
    drug.class,
    drug.templateKey,
    ...(drug.tags || [])
  ].join(" "));
}

function drugMatchesAntiarrhythmicClassFilter(drug = {}, filter = null) {
  if (!filter) return true;
  const nameTerms = pharmIdentityTermsForEntry(drug);
  const filterNames = new Set((filter.names || []).map((name) => normalizePharmText(name)));
  if (nameTerms.some((term) => filterNames.has(term))) {
    return true;
  }
  return filter.matchPattern.test(offlineDrugClassOnlyBlob(drug));
}

const OFFLINE_TERATOGENIC_DRUG_LIST_CUE = /\b(teratogenic|teratogen|teratogens|tetragenic|teragenic|tetragenc|birth defects?|fetal toxicity|embryo[-\s]?fetal|embryofetal|pregnancy unsafe|pregnancy contraindicated|unsafe in pregnancy|not safe in pregnancy|maternity unsafe|pregnancy no no|pregnancy high[-\s]?risk)\b/i;
const OFFLINE_PREGNANCY_UNSAFE_MED_NATURAL_CUE = /\b(?:(?:unsafe|not safe|avoid(?:ed|ing)?|contraindicated|dangerous|harmful|bad|no[-\s]?no|high[-\s]?risk|safer|safest|least\D{0,3}risky|lowest risk|(?:absolutely\s+)?(?:not|never)\s+(?:give|use|administer)|cannot\s+(?:give|use|administer)|should\s+not\s+(?:give|use|administer))\s+(?:\w+\s+){0,6}(?:preg(?:nan\w*|ant|nent|anant)|maternity|maternal|fetal|embryo[-\s]?fetal)|(?:preg(?:nan\w*|ant|nent|anant)|maternity|maternal|fetal|embryo[-\s]?fetal)\s+(?:\w+\s+){0,6}(?:unsafe|not safe|avoid(?:ed|ing)?|contraindicated|dangerous|harmful|bad|no[-\s]?no|high[-\s]?risk|safer|safest|least\D{0,3}risky|lowest risk|(?:absolutely\s+)?(?:not|never)\s+(?:receive|use|take)|cannot\s+(?:receive|use|take)|should\s+not\s+(?:receive|use|take)))\b|\b(?:(?:can|could|is it|may)\s+\w+\s+(?:take|use|receive|administer|give)|can i\s+(?:\w+\s+)?(?:take|use|receive|administer|give))\s[\s\w'-]{0,30}\b(?:preg(?:nan\w*|ant|nent|anant)|maternity|maternal|fetal|embryo[-\s]?fetal)\b/i;

const OFFLINE_TERATOGENIC_DRUG_PRIORITY = [
  "isotretinoin",
  "acitretin",
  "thalidomide",
  "mycophenolate",
  "methotrexate",
  "warfarin",
  "valproic acid",
  "phenytoin",
  "carbamazepine",
  "lisinopril",
  "losartan",
  "doxycycline",
  "tetracycline",
  "atorvastatin",
  "finasteride",
  "misoprostol",
  "trimethoprim sulfamethoxazole",
  "lithium",
  "amiodarone",
  "gentamicin"
];

function wantsOfflineTeratogenicDrugList(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  if (!OFFLINE_TERATOGENIC_DRUG_LIST_CUE.test(lower) && !OFFLINE_PREGNANCY_UNSAFE_MED_NATURAL_CUE.test(lower)) return false;
  return /\b(list|lists|show(?: me)?|give(?: me)?|name|names|examples?|bunch|all|which|what are|what medications|what meds|what drugs|pull up)\b/i.test(lower)
    || /\b(drugs?|meds?|medications?|medicines?|prescribed|medicine|medication|take|use|receive|administer|give)\b/i.test(lower);
}

function drugHasPregnancyUnsafeSignal(drug = {}) {
  const risks = Array.isArray(drug.populationRisks) ? drug.populationRisks : [];
  const pregnancyRisk = risks.some((risk) =>
    risk?.type === "pregnancy"
    && /\b(unsafe|teratogenic|embryo|contraindicat|birth defect|major fetal|fetal (?:harm|toxicity|risk|kidney|development|thyroid|ototoxicity)|toxicity|stop)\b/i.test(`${risk.label || ""} ${risk.note || ""}`)
  );
  const blob = normalizePharmText([
    drug.name,
    drug.generic,
    drug.class,
    drug.boxedWarning,
    ...(drug.nursingEssentials || []),
    ...(drug.contraindications || []),
    ...(drug.nclexTraps || []),
    ...(drug.tags || [])
  ].join(" "));
  const labelSignal = /\b(fetal toxicity|embryo fetal|embryofetal|teratogenic|birth defect|pregnancy unsafe|avoid pregnancy|pregnancy contraindicated|contraindicated in pregnancy|neural tube defects?|fetal harm)\b/i.test(blob);
  return pregnancyRisk || labelSignal;
}

function teratogenicDrugPriorityIndex(drug = {}) {
  const terms = [
    drug.name,
    drug.generic,
    ...(drug.aliases || [])
  ].map((term) => normalizePharmText(term)).filter(Boolean);
  const index = OFFLINE_TERATOGENIC_DRUG_PRIORITY.findIndex((priority) => terms.includes(priority));
  return index === -1 ? 999 : index;
}

const TERATOGENIC_REASON_OVERRIDES = new Map([
  ["isotretinoin", "Retinoid teratogen: can cause severe craniofacial, cardiac, CNS, thymic, and parathyroid malformations; pregnancy prevention and testing are central."],
  ["acitretin", "Systemic retinoid teratogen with prolonged pregnancy-avoidance concern; severe fetal malformations can occur because retinoic-acid signaling controls embryonic patterning."],
  ["thalidomide", "Profound teratogen: classically limb-reduction defects, ear/eye/cardiac defects, and embryo-fetal death; strict pregnancy-prevention controls are mandatory."],
  ["mycophenolate", "Embryo-fetal toxicity: raises risk of first-trimester pregnancy loss and congenital malformations, especially external ear/facial, cardiac, esophageal, renal, and limb anomalies."],
  ["methotrexate", "Antifolate teratogen and abortifacient: impaired DNA synthesis can cause embryo-fetal death and craniofacial, skull, limb, and growth abnormalities."],
  ["warfarin", "Crosses the placenta and can cause fetal bleeding plus warfarin embryopathy, classically nasal hypoplasia and stippled epiphyses with CNS/eye risk."],
  ["valproic acid", "High-risk antiseizure teratogen: neural tube defects, craniofacial/cardiac defects, lower IQ, and neurodevelopmental disorders are the classic concern."],
  ["phenytoin", "Antiseizure teratogenic risk: fetal hydantoin pattern can include growth restriction, craniofacial changes, nail/digit hypoplasia, and neurodevelopmental concerns."],
  ["carbamazepine", "Antiseizure teratogenic risk: neural tube defects and craniofacial/nail-development concerns; folate and specialist pregnancy planning matter."],
  ["lisinopril", "ACE-inhibitor fetal toxicity: second/third-trimester exposure can injure fetal kidneys, causing oligohydramnios, skull/lung effects, renal failure, or fetal death."],
  ["losartan", "ARB fetal toxicity: second/third-trimester RAAS blockade can cause fetal renal injury, oligohydramnios, skull/lung effects, renal failure, or fetal death."],
  ["doxycycline", "Tetracycline-class pregnancy concern: fetal tooth discoloration and bone-growth effects are the classic nursing anchor."],
  ["tetracycline", "Tetracycline-class pregnancy concern: fetal tooth discoloration and bone-growth effects are the classic nursing anchor."],
  ["atorvastatin", "Statin pregnancy stop-or-clarify drug: cholesterol synthesis is important for fetal development, so routine lipid-lowering therapy is usually avoided in pregnancy unless a specialist exception exists."],
  ["finasteride", "5-alpha-reductase inhibitor: can disrupt male fetal external genital development; pregnant clients should avoid exposure to crushed/broken tablets."],
  ["misoprostol", "Prostaglandin E1 uterotonic: can cause uterine contractions, pregnancy loss, bleeding, and fetal injury if pregnancy exposure is unintended or outside protocol."],
  ["trimethoprim sulfamethoxazole", "Folate antagonism and sulfonamide timing concerns: clarify pregnancy trimester, folate status, infection severity, and safer alternatives when appropriate."],
  ["lithium", "Mood stabilizer pregnancy concern: associated with congenital cardiac risk such as Ebstein anomaly signal, plus maternal level shifts around hydration, renal function, and delivery."],
  ["amiodarone", "Iodine-rich antiarrhythmic with fetal thyroid, bradycardia, growth, and neurodevelopment concern; reserve for serious rhythm need under specialist guidance."],
  ["gentamicin", "Aminoglycoside pregnancy concern: fetal ototoxicity/nephrotoxicity is the classic risk, so use depends on infection severity and safer alternatives."]
]);

function teratogenicReasonOverride(drug = {}) {
  const terms = [
    drug.generic,
    drug.name,
    ...(drug.aliases || [])
  ].map((term) => normalizePharmText(term)).filter(Boolean);
  for (const term of terms) {
    if (TERATOGENIC_REASON_OVERRIDES.has(term)) {
      return TERATOGENIC_REASON_OVERRIDES.get(term);
    }
  }
  return "";
}

function findOfflineTeratogenicDrugMatches() {
  return uniqueOfflineDrugMatches(pharmDrugs.filter((drug) => {
    if (isNavigationOnlyGeneratedMedicationClass(drug)) return false;
    if (isLikelyCombinationDrugEntry(drug)) {
      return false;
    }
    return teratogenicDrugPriorityIndex(drug) < 999 || drugHasPregnancyUnsafeSignal(drug);
  }))
    .sort((a, b) => {
      const priorityDelta = teratogenicDrugPriorityIndex(a) - teratogenicDrugPriorityIndex(b);
      if (priorityDelta) return priorityDelta;
      const aCore = isNclexCorePharmEntry(a) ? 0 : 1;
      const bCore = isNclexCorePharmEntry(b) ? 0 : 1;
      return aCore - bCore
        || safeText(a.generic || a.name).localeCompare(safeText(b.generic || b.name));
    });
}

function teratogenicDrugReason(drug = {}) {
  if (isNavigationOnlyGeneratedMedicationClass(drug)) return "";
  const override = teratogenicReasonOverride(drug);
  if (override) return override;
  const pregnancyRisk = (drug.populationRisks || []).find((risk) => risk?.type === "pregnancy");
  if (pregnancyRisk?.note) return safeText(pregnancyRisk.note);
  const contraindication = (drug.contraindications || []).find((note) => /\b(pregnan|fetal|embryo|teratogenic|birth defect)\b/i.test(note));
  if (contraindication) return safeText(contraindication);
  if (drug.boxedWarning && /\b(pregnan|fetal|embryo|teratogenic|birth defect)\b/i.test(drug.boxedWarning)) {
    return safeText(drug.boxedWarning);
  }
  return "Pregnancy requires clarification because fetal or pregnancy-specific harm may occur.";
}

function offlineDrugDisplayName(drug = {}) {
  const generic = safeText(drug.generic || drug.name);
  const brand = Array.isArray(drug.brandExamples) && drug.brandExamples.length
    ? safeText(drug.brandExamples[0])
    : "";
  return brand && normalizePharmText(brand) !== normalizePharmText(generic)
    ? `${generic} (${brand})`
    : generic;
}

function uniqueOfflineDrugMatches(drugs = []) {
  const seen = new Set();
  return drugs.filter((drug) => {
    const key = normalizePharmText(drug.generic || drug.name);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function isOfflineAntiarrhythmicClassSummaryEntry(drug = {}) {
  return /^class\s+(?:i|ii|iii|iv|1|2|3|4)\s+antiarrhythmics?$/.test(normalizePharmText(drug.generic || drug.name));
}

function isOfflineMedicationClassSummaryEntry(drug = {}) {
  return Boolean(drug?.classCard) || isOfflineAntiarrhythmicClassSummaryEntry(drug);
}

function antiarrhythmicNamedDrugMatches(filter = null) {
  if (!filter) return [];
  const filterNames = new Set((filter.names || []).map((name) => normalizePharmText(name)).filter(Boolean));
  if (!filterNames.size) return [];
  const primaryNameMatches = (drug = {}) => {
    const primaryTerms = [
      drug.generic,
      drug.name,
      drug.displayName,
      pharmDrugDisplayName(drug, "")
    ].map((term) => normalizePharmText(term)).filter(Boolean);
    return primaryTerms.some((term) =>
      filterNames.has(term)
      || Array.from(filterNames).some((filterName) =>
        term === filterName
        || term.startsWith(`${filterName} `)
        || filterName.startsWith(`${term} `)
      )
    );
  };
  return pharmDrugs.filter((drug) => {
    if (isLikelyCombinationDrugEntry(drug)) return false;
    if (isOfflineMedicationClassSummaryEntry(drug)) return false;
    return primaryNameMatches(drug);
  });
}

function findOfflineDrugClassMatches(input = "") {
  const definition = offlineDrugClassDefinitionForInput(input);
  const antiarrhythmicClassFilter = definition?.key === "antiarrhythmic"
    ? antiarrhythmicClassFilterFromInput(input)
    : null;
  const topic = extractOfflineListTopic(input);
  const topicTokens = topic.split(" ").filter((token) => token.length >= 3);
  if (!definition && !topicTokens.length) {
    return { definition: null, matches: [], topic: "" };
  }

  const requestedAntiarrhythmicExamples = antiarrhythmicNamedDrugMatches(antiarrhythmicClassFilter);
  const matches = requestedAntiarrhythmicExamples.length ? requestedAntiarrhythmicExamples : pharmDrugs.filter((drug) => {
    if (isLikelyCombinationDrugEntry(drug) && !/\b(combo|combination|combined|dual|pair|pairs)\b/i.test(input)) {
      return false;
    }
    const blob = offlineDrugClassSearchBlob(drug);
    if (definition?.matchPattern.test(blob)) {
      return drugMatchesAntiarrhythmicClassFilter(drug, antiarrhythmicClassFilter);
    }
    if (definition) {
      return false;
    }
    if (!topicTokens.length) {
      return false;
    }
    if (antiarrhythmicClassFilter && !drugMatchesAntiarrhythmicClassFilter(drug, antiarrhythmicClassFilter)) {
      return false;
    }
    const classBlob = normalizePharmText([
      drug.class,
      drug.templateKey,
      ...sanitizeMedicationTermListForSingleDrug(drug, drug.tags || [])
    ].join(" "));
    return topicTokens.every((token) => classBlob.includes(token) || blob.split(" ").some((word) => word.startsWith(token)));
  });

  let sorted = uniqueOfflineDrugMatches(matches)
    .sort((a, b) => {
      const aCore = isNclexCorePharmEntry(a) ? 0 : 1;
      const bCore = isNclexCorePharmEntry(b) ? 0 : 1;
      return aCore - bCore
        || safeText(a.class).localeCompare(safeText(b.class))
        || safeText(a.generic || a.name).localeCompare(safeText(b.generic || b.name));
    });
  if ((definition || antiarrhythmicClassFilter) && sorted.some((drug) => !isOfflineMedicationClassSummaryEntry(drug))) {
    sorted = sorted.filter((drug) => !isOfflineMedicationClassSummaryEntry(drug));
  }
  const activeDefinition = antiarrhythmicClassFilter
    ? {
      ...definition,
      key: antiarrhythmicClassFilter.key,
      label: antiarrhythmicClassFilter.label,
      nclexNote: antiarrhythmicClassFilter.nclexNote,
      forcedGroupLabel: antiarrhythmicClassFilter.groupLabel,
      curatedExamples: (antiarrhythmicClassFilter.names || [])
        .filter((name) => !/^class\s+(?:i|ii|iii|iv|1|2|3|4)\s+antiarrhythmics?$/i.test(name))
    }
    : definition;
  return { definition: activeDefinition, matches: sorted, topic };
}

function offlineDrugListGroupLabel(drug = {}, definition = null) {
  if (definition?.forcedGroupLabel) {
    return definition.forcedGroupLabel;
  }
  const classText = safeText(drug.class || drug.templateKey);
  const classBlob = normalizePharmText(classText);
  if (definition?.key === "antipsychotic") {
    if (/\b(atypical|second generation|second-generation|2nd generation)\b/.test(classBlob)) return "Second-generation / atypical";
    if (/\b(first generation|first-generation|1st generation|typical|phenothiazine|butyrophenone)\b/.test(classBlob)) return "First-generation / typical";
  }
  if (definition?.key === "diuretic") {
    if (/\bloop\b/.test(classBlob)) return "Loop diuretics";
    if (/\bthiazide\b/.test(classBlob)) return "Thiazide diuretics";
    if (/\bpotassium sparing|aldosterone\b/.test(classBlob)) return "Potassium-sparing diuretics";
  }
  if (definition?.key === "beta blocker") {
    if (/\bclass iii\b|potassium channel/.test(classBlob)) return "Class III agent with beta-blocking effect";
    if (/\balpha|mixed/.test(classBlob)) return "Mixed alpha/beta blockers";
    if (/\bbeta[-\s]?1|selective|cardioselective/.test(classBlob)) return "Beta-1 selective beta blockers";
    return "Nonselective / other beta blockers";
  }
  if (definition?.key === "antiarrhythmic") {
    if (/\bclass i\b/.test(classBlob)) return "Class I";
    if (/\bclass ii\b|beta blocker/.test(classBlob)) return "Class II";
    if (/\bclass iii\b/.test(classBlob)) return "Class III";
    if (/\bclass iv\b|calcium channel/.test(classBlob)) return "Class IV";
  }
  return classText || "Installed matches";
}

function offlineDrugClassListContext(title = "", definition = null, matches = []) {
  return {
    type: "drug-class-list",
    title,
    key: definition?.key || normalizePharmText(title),
    nclexNote: definition?.nclexNote || "",
    entries: matches.map((drug) => ({
      name: offlineDrugDisplayName(drug),
      generic: safeText(drug.generic || drug.name),
      class: safeText(drug.class || drug.templateKey),
      nclexEssential: Boolean(isNclexCorePharmEntry(drug))
    })),
    shown: matches.length,
    total: matches.length,
    exhausted: true,
    createdAt: Date.now()
  };
}

function makeOfflineDrugClassListResponse(input = "", options = {}) {
  const { definition, matches, topic } = findOfflineDrugClassMatches(input);
  if (!matches.length) {
    return "";
  }
  const title = definition?.label || `${titleCaseOfflineTopic(topic)} medication matches`;
  if (options.storeContext !== false) {
    lastOfflineListContext = offlineDrugClassListContext(title, definition, matches);
    const classCard = exactMedicationClassCardMatch(title)
      || exactMedicationClassCardMatch(input);
    if (classCard) {
      rememberOfflineLookupTarget({ type: "drug", item: classCard, score: 2200 }, input);
    }
  }
  const groups = new Map();
  matches.forEach((drug) => {
    const group = offlineDrugListGroupLabel(drug, definition);
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group).push(offlineDrugDisplayName(drug));
  });

  const groupLines = Array.from(groups.entries())
    .map(([group, names]) => `**${group}:** ${names.join(", ")}.`);
  const curatedExamples = Array.isArray(definition?.curatedExamples)
    ? definition.curatedExamples
      .map((name) => cleanMedicationDisplayName(titleCaseOfflineTopic(name), ""))
      .filter(Boolean)
    : [];
  const curatedExampleLine = curatedExamples.length
    ? `**Examples in this class:** ${curatedExamples.join(", ")}.`
    : "";
  const nclexNames = matches
    .filter(isNclexCorePharmEntry)
    .slice(0, 14)
    .map(offlineDrugDisplayName);

  return [
    `**${title} in the clinical reference**`,
    `Found **${matches.length}** installed medication ${matches.length === 1 ? "entry" : "entries"} matching that request.`,
    curatedExampleLine,
    ...groupLines,
    nclexNames.length ? `**NCLEX-first review set:** ${nclexNames.join(", ")}.` : "",
    definition?.nclexNote ? `**NCLEX anchor:** ${definition.nclexNote}` : ""
  ].filter(Boolean).join("\n\n");
}

function makeOfflineTeratogenicDrugListResponse(input = "", options = {}) {
  if (!wantsOfflineTeratogenicDrugList(input)) {
    return "";
  }
  const matches = findOfflineTeratogenicDrugMatches();
  if (!matches.length) {
    return "";
  }
  if (options.storeContext !== false) {
    lastOfflineListContext = offlineDrugClassListContext("Pregnancy-unsafe / teratogenic medication matches", {
      key: "teratogenic",
      nclexNote: "Verify pregnancy status, hold/question unsafe meds, notify the provider/pharmacist, and anticipate safer alternatives when ordered."
    }, matches);
  }
  const majorRisk = [];
  const cautionRisk = [];
  const highYieldKeys = new Set();
  const highYieldPriority = matches
    .filter((drug) => teratogenicDrugPriorityIndex(drug) < 999)
    .slice(0, 12)
    .map((drug) => {
      highYieldKeys.add(normalizePharmText(drug.generic || drug.name));
      return `**${offlineDrugDisplayName(drug)}:** ${teratogenicDrugReason(drug)}`;
    });
  matches.forEach((drug) => {
    const key = normalizePharmText(drug.generic || drug.name);
    if (highYieldKeys.has(key)) return;
    const line = `**${offlineDrugDisplayName(drug)}:** ${teratogenicDrugReason(drug)}`;
    const riskText = `${drug.boxedWarning || ""} ${(drug.populationRisks || []).map((risk) => `${risk.label || ""} ${risk.note || ""}`).join(" ")}`;
    if (/\b(unsafe|teratogenic|embryo|fetal toxicity|major fetal|birth defect|contraindicated|neural tube)\b/i.test(riskText)) {
      majorRisk.push(line);
    } else {
      cautionRisk.push(line);
    }
  });
  return [
    "**Pregnancy-unsafe / teratogenic medication matches**",
    "**Direct answer:** Some medications and medication classes have strong pregnancy contraindications or stop-and-clarify warnings. But not every medication with a pregnancy-risk signal is universally forbidden: the decision can depend on trimester, dose, indication, exposure route, available alternatives, and the maternal-fetal risk-benefit analysis.",
    highYieldPriority.length ? `**Highest-yield installed examples:**\n${highYieldPriority.join("\n")}` : "",
    majorRisk.length ? `**Additional major fetal-harm red flags:**\n${majorRisk.slice(0, 4).join("\n")}` : "",
    cautionRisk.length ? `**Other stop-or-clarify examples:**\n${cautionRisk.slice(0, 3).join("\n")}` : "",
    "**Clinical safety boundary:** Verify pregnancy status and gestational timing, then hold or question a potentially unsafe medication and confirm the indication and plan with the prescriber or pharmacist. Do not stop a necessary prescribed medication or substitute a class-wide rule for individualized specialist review.",
    `**Secondary retrieval diagnostic:** ANI found **${matches.length}** installed medication entries with pregnancy-risk signals; only the bounded, highest-priority set is shown above.`
  ].filter(Boolean).join("\n\n");
}

function offlineGeneralListCandidates(input = "") {
  const topic = extractOfflineListTopic(input);
  if (!topic) return [];
  const lower = normalizeIntentText(input);
  const includeLabs = /\b(lab|labs|range|ranges|values?|levels?|electrolytes?)\b/i.test(lower);
  const includeDiseases = /\b(disease|diseases|pathology|pathologies|condition|conditions|syndrome|syndromes)\b/i.test(lower);
  const includeProcedures = /\b(procedure|procedures|diagnostic|diagnostics|test|tests|screen|screening)\b/i.test(lower);
  const includeHolistic = /\b(herbal|herbals|holistic|supplement|supplements)\b/i.test(lower);
  const noSpecificCategory = !includeLabs && !includeDiseases && !includeProcedures && !includeHolistic;
  const candidates = [];

  if (includeLabs || noSpecificCategory) {
    pharmSearchableLabRanges.forEach((item) => {
      const score = scorePharmLabEntry(item, topic);
      if (score >= 40) candidates.push({ type: "lab", item, score });
    });
  }
  if (includeDiseases || noSpecificCategory) {
    pathologyDiseases.forEach((item) => {
      const score = scorePathologyEntry(item, topic);
      if (score >= 45) candidates.push({ type: "pathology", item, score });
    });
  }
  if (includeProcedures || noSpecificCategory) {
    clinicalReferenceEntries.forEach((item) => {
      const score = scoreClinicalReferenceEntry(item, topic);
      if (score >= 45) candidates.push({ type: "reference", item, score });
    });
  }
  if (includeHolistic || noSpecificCategory) {
    holisticRemedies.forEach((item) => {
      const score = scoreHolisticEntry(item, topic);
      if (score >= 45) candidates.push({ type: "holistic", item, score });
    });
  }

  const seen = new Set();
  return candidates
    .sort((a, b) => b.score - a.score || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .filter((candidate) => {
      const key = offlineLookupEntityKey(candidate);
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
}

function makeOfflineGeneralListResponse(input = "", options = {}) {
  const candidates = offlineGeneralListCandidates(input);
  if (candidates.length < 2) {
    return "";
  }
  if (options.storeContext !== false) {
    lastOfflineListContext = {
      type: "general-list",
      title: "Matching encyclopedia entries",
      entries: candidates.map((candidate) => ({
        label: offlineLookupEntityLabel(candidate),
        kind: offlineLookupEntityKind(candidate)
      })),
      shown: candidates.length,
      total: candidates.length,
      exhausted: true,
      createdAt: Date.now()
    };
  }
  const groups = new Map();
  candidates.forEach((candidate) => {
    const group = offlineLookupEntityKind(candidate);
    if (!groups.has(group)) groups.set(group, []);
    groups.get(group).push(offlineLookupEntityLabel(candidate));
  });
  const lines = Array.from(groups.entries())
    .map(([group, labels]) => `**${group}:** ${labels.join(", ")}.`);
  return [
    "**Matching encyclopedia entries**",
    `Found **${candidates.length}** installed ${candidates.length === 1 ? "entry" : "entries"} that match your list request.`,
    ...lines,
    "**Study move:** pick any item from the list and ask for its range, mechanism, treatment, risks, or NCLEX traps if you want the exact section pulled into chat."
  ].join("\n\n");
}

const OFFLINE_BROAD_CAUSE_SYNONYMS = [
  {
    pattern: /\b(laryngeal\s+spasms?|laryngospasms?|larynx\s+spasms?|voice\s+box\s+spasms?|throat\s+spasms?|airway\s+spasms?)\b/i,
    display: "laryngospasm / pediatric upper-airway spasm",
    terms: [
      ["laryngospasm", 95],
      ["laryngeal spasm", 95],
      ["stridor", 48],
      ["upper airway obstruction", 44],
      ["airway obstruction", 38],
      ["tetany", 32]
    ]
  },
  {
    pattern: /\b(stridor|noisy\s+inspiratory\s+breathing)\b/i,
    display: "stridor / upper-airway narrowing",
    terms: [
      ["stridor", 90],
      ["upper airway obstruction", 54],
      ["airway obstruction", 46],
      ["laryngospasm", 44]
    ]
  }
];

function freshOfflineListContext() {
  if (!lastOfflineListContext?.createdAt) return null;
  return Date.now() - lastOfflineListContext.createdAt <= 10 * 60 * 1000
    ? lastOfflineListContext
    : null;
}

function looksLikeOfflineListExpansionFollowup(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(that'?s\s+(?:it|all|the\s+only\s+thing)|is\s+that\s+(?:it|all)|only\s+thing|anything\s+else|what\s+else|more\s+(?:causes|options|things|examples|matches|results|entries|meds?|medications?|drugs?)?|other\s+(?:causes|options|things|examples|matches|results|entries|meds?|medications?|drugs?)|any\s+others?|are\s+there\s+any\s+more|is\s+there\s+more|keep\s+going|not\s+enough)\b/i.test(lower);
}

function wantsOfflineListExpansionFollowup(input = "") {
  if (!freshOfflineListContext()) return false;
  return looksLikeOfflineListExpansionFollowup(input);
}

function wantsOfflineListAiExpansionFallback(input = "") {
  const context = freshOfflineListContext();
  if (!context || !looksLikeOfflineListExpansionFollowup(input)) return false;
  if (context.type === "broad-cause-list") {
    return Array.isArray(context.candidates) && Number(context.shown || 0) >= context.candidates.length;
  }
  return ["drug-class-list", "general-list"].includes(context.type) && Boolean(context.exhausted);
}

function offlineListContextSummary(context = freshOfflineListContext()) {
  if (!context) return "";
  if (context.type === "drug-class-list") {
    const entries = (context.entries || [])
      .map((entry) => `${entry.name}${entry.class ? ` - ${entry.class}` : ""}${entry.nclexEssential ? " [NCLEX-essential]" : ""}`)
      .join("; ");
    return [
      `${context.title || "Medication list"}`,
      `Installed entries already shown: ${entries || "none"}.`,
      context.nclexNote ? `NCLEX anchor already available: ${context.nclexNote}` : ""
    ].filter(Boolean).join(" ");
  }
  if (context.type === "general-list") {
    const entries = (context.entries || [])
      .map((entry) => `${entry.label}${entry.kind ? ` (${entry.kind})` : ""}`)
      .join("; ");
    return `${context.title || "Encyclopedia list"}. Installed entries already shown: ${entries || "none"}.`;
  }
  if (context.type === "broad-cause-list") {
    return `${context.target?.display || "Cause list"}. Installed matches already shown: ${context.shown || 0} of ${context.candidates?.length || 0}.`;
  }
  return "";
}

function offlineListExpansionLocalLimitResponse(context = freshOfflineListContext()) {
  if (!context) return "";
  if (context.type === "drug-class-list") {
    const names = (context.entries || []).map((entry) => entry.name).filter(Boolean);
    return [
      `**${context.title || "Medication list"} - expansion**`,
      names.length
        ? `The installed reference has already shown: **${names.join(", ")}**.`
        : "The installed reference does not have additional entries for that list.",
      "For a broader pharmacology expansion beyond the installed reference, ANI needs the AI connection."
    ].join("\n\n");
  }
  if (context.type === "general-list") {
    return [
      "**List expansion**",
      "The installed reference has already shown the matches it found for that list.",
      "For a broader expansion beyond the installed reference, ANI needs the AI connection."
    ].join("\n\n");
  }
  if (context.type === "broad-cause-list") {
    return formatOfflineBroadListResponse(context.target, context.candidates || [], {
      start: context.shown || 0,
      count: 10
    });
  }
  return "";
}

function offlineListExpansionModelPrompt(input = "", context = freshOfflineListContext()) {
  const summary = offlineListContextSummary(context);
  return [
    "The student is asking a follow-up to expand a list ANI just answered from the installed encyclopedia.",
    summary,
    `Student follow-up: ${input}`,
    "If the installed list is complete but broader medical context exists, answer with that broader context.",
    "Be direct and do not open a random encyclopedia entry.",
    "Clearly separate NCLEX-essential items from beyond-NCLEX context.",
    "If the user asks whether there are more medications, explain whether there are more in the exact class versus related therapies or adjuncts.",
    "Keep it concise but useful for nursing study."
  ].filter(Boolean).join("\n\n");
}

function wantsOfflineBroadCauseList(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  if (!lower) return false;
  if (/^(?:does|do|did|can|could|will|would|is|are)\b/i.test(lower)
    && !/\b(what|which|list|show|name|give|all|diseases?|conditions?|pathologies?|causes?)\b/i.test(lower)) {
    return false;
  }
  return /\b(?:what|which|list|show|name|give|all|common|possible|likely|diseases?|conditions?|pathologies?|things?)\b[\s\S]{0,120}\b(?:cause|causes|caused|trigger|triggers|lead\s+to|leads\s+to|associated\s+with|risk\s+factors?)\b/i.test(lower)
    || /\b(?:cause|causes|caused|trigger|triggers|etiology|risk\s+factors?)\b[\s\S]{0,120}\b(?:of|for)\b/i.test(lower);
}

function offlineBroadCauseTarget(input = "") {
  const fixed = compactSpokenMedicalAcronyms(input);
  const lower = normalizeIntentText(fixed);
  const clean = normalizeOfflineLookupText(fixed, { dropLookupWords: false }) || normalizePharmText(fixed);
  const topic = clean
    .split(" ")
    .filter((token) => token.length > 1 && !OFFLINE_LIST_REQUEST_DROP_WORDS.has(token))
    .join(" ")
    .trim();
  const synonym = OFFLINE_BROAD_CAUSE_SYNONYMS.find((entry) => entry.pattern.test(lower) || entry.pattern.test(topic));
  const tokenTerms = topic
    .split(" ")
    .filter((token) => token.length >= 4)
    .map((token) => [token, 30]);
  const weightedTerms = [
    ...(synonym?.terms || []),
    ...tokenTerms
  ].reduce((items, [term, weight]) => {
    const cleanTerm = normalizePharmText(term);
    if (!cleanTerm || items.some((item) => item.term === cleanTerm)) return items;
    items.push({ term: cleanTerm, weight });
    return items;
  }, []);
  if (!weightedTerms.length) return null;
  return {
    display: synonym?.display || titleCaseOfflineTopic(topic),
    topic,
    lower,
    weightedTerms,
    populationTypes: populationRiskTypesFromInput(input)
  };
}

function offlineBroadCandidateSections(candidate = {}) {
  const item = candidate.item || {};
  if (candidate.type === "lab") {
    return [
      ["range", item.range],
      ["why it matters", item.why],
      ["population note", item.groupNote],
      ["category", item.category],
      ["tags", (item.tags || []).join(" ")]
    ];
  }
  if (candidate.type === "pathology") {
    return [
      ["definition/pathology", item.pathology],
      ["etiology/risk factors", item.etiology],
      ["signs and symptoms", pathologyListText(item.signsSymptoms)],
      ["diagnostics", pathologyDiagnosticsWithAlterations(item)],
      ["treatment", pathologyListText(item.treatments)],
      ["nursing priorities", pathologyListText(item.nursingPriorities)],
      ["complications", pathologyListText(item.complications)],
      ["NCLEX traps", pathologyListText(item.nclexTraps)],
      ["tags", (item.tags || []).join(" ")]
    ];
  }
  if (candidate.type === "reference") {
    return [
      ["quick answer", item.quickAnswer],
      ["summary", item.summary],
      ...clinicalReferenceSectionPairs(item),
      ["tags", (item.tags || []).join(" ")]
    ];
  }
  if (candidate.type === "holistic") {
    return [
      ["used for", pathologyListText(item.usedFor)],
      ["major risks", pathologyListText(item.majorRisks)],
      ["contraindications", pathologyListText(item.contraindications)],
      ["interactions", pathologyListText(item.interactions)],
      ["nursing assessment", pathologyListText(item.nursingAssessment)],
      ["NCLEX traps", pathologyListText(item.nclexTraps)],
      ["tags", (item.tags || []).join(" ")]
    ];
  }
  if (candidate.type === "drug") {
    if (isNavigationOnlyGeneratedMedicationClass(item)) {
      return [
        ["class", item.class],
        ["specific class / pathway", pharmClassPathwayText(item)],
        ["examples", normalizeMedicationClassExampleNames(item.classExampleNames || []).join(", ")],
        ["tags", (item.tags || []).join(" ")]
      ];
    }
    return [
      ["class", item.class],
      ["used to treat", pathologyListText(item.usedFor || item.indications)],
      ["mechanism", item.mechanism],
      ["warnings", pathologyListText([item.boxedWarning, item.highAlertWarning].filter(Boolean))],
      ["nursing concepts", pathologyListText(item.nursingConcepts || item.nursingInterventions)],
      ["NCLEX traps", pathologyListText(item.nclexTraps)],
      ["tags", (item.tags || []).join(" ")]
    ];
  }
  return [];
}

function scoreOfflineBroadCandidate(candidate = {}, target = null) {
  if (!target) return 0;
  const sections = offlineBroadCandidateSections(candidate);
  const identity = normalizePharmText([
    offlineLookupEntityLabel(candidate),
    ...offlineCandidatePrimaryTerms(candidate)
  ].join(" "));
  const text = normalizePharmText(sections.map(([label, value]) => `${label} ${value}`).join(" "));
  let score = 0;
  target.weightedTerms.forEach(({ term, weight }) => {
    if (!term) return;
    if (identity.includes(term)) score += Math.max(10, Math.floor(weight * 0.45));
    if (text.includes(term)) score += weight;
  });
  if (target.populationTypes.includes("pediatric")) {
    if (/\b(pediatric|pediatrics|peds|child|children|infant|newborn|neonate|adolescent|school-age|school age)\b/i.test(text)) {
      score += 18;
    }
    if (/\b(adult|geriatric|older adult|pregnan|maternity)\b/i.test(identity)) {
      score -= 8;
    }
  }
  if (target.populationTypes.includes("pregnancy") && /\b(pregnan|maternity|maternal|fetal|trimester)\b/i.test(text)) {
    score += 18;
  }
  if (target.populationTypes.includes("geriatric") && /\b(geriatric|older adult|elderly|aging|fall)\b/i.test(text)) {
    score += 18;
  }
  return score;
}

function offlineBroadCandidateSnippet(candidate = {}, target = null) {
  const terms = (target?.weightedTerms || []).map((item) => item.term);
  const ranked = offlineBroadCandidateSections(candidate)
    .map(([label, value]) => {
      const raw = stripMarkdownEmphasis(value);
      const text = normalizePharmText(raw);
      const score = terms.reduce((sum, term) => sum + (term && text.includes(term) ? 1 : 0), 0);
      return { label, raw, score };
    })
    .filter((section) => safeText(section.raw))
    .sort((a, b) => b.score - a.score);
  const best = ranked[0];
  if (!best) return "";
  const sentences = stripMarkdownEmphasis(best.raw)
    .replace(/\s+/g, " ")
    .split(/(?<=[.!?])\s+/)
    .filter(Boolean);
  const termSentence = sentences.find((sentence) => {
    const clean = normalizePharmText(sentence);
    return terms.some((term) => term && clean.includes(term));
  }) || sentences[0] || best.raw;
  return normalizeReadableSentence(termSentence);
}

function offlineBroadPriorityLine(target = null) {
  const terms = (target?.weightedTerms || []).map((item) => item.term).join(" ");
  if (/\b(laryngospasm|laryngeal spasm|stridor|airway obstruction)\b/i.test(terms)) {
    return "**NCLEX priority:** any pediatric laryngospasm, stridor, drooling, cyanosis, severe retractions, altered mental status, or rapidly worsening work of breathing is an airway-first problem.";
  }
  return "**NCLEX priority:** when a list has several possible causes, match the cause to the client trend, the most dangerous complication, and the first nursing priority.";
}

function offlineBroadListCandidates(input = "") {
  const target = offlineBroadCauseTarget(input);
  if (!target) return { target: null, candidates: [] };
  const lower = target.lower;
  const includeDrugs = /\b(drugs?|meds?|medications?|medicines?|pharm|pharmacology)\b/i.test(lower);
  const includeHolistic = /\b(herbal|herbals|holistic|supplements?)\b/i.test(lower);
  const candidates = [];
  const addCandidate = (candidate) => {
    const score = scoreOfflineBroadCandidate(candidate, target);
    if (score >= 34) {
      candidates.push({
        ...candidate,
        score,
        snippet: offlineBroadCandidateSnippet(candidate, target)
      });
    }
  };

  pharmSearchableLabRanges.forEach((item) => addCandidate({ type: "lab", item }));
  pathologyDiseases.forEach((item) => addCandidate({ type: "pathology", item }));
  clinicalReferenceEntries.forEach((item) => addCandidate({ type: "reference", item }));
  if (includeHolistic) {
    holisticRemedies.forEach((item) => addCandidate({ type: "holistic", item }));
  }
  if (includeDrugs) {
    pharmDrugs.forEach((item) => addCandidate({ type: "drug", item }));
  }

  const seen = new Set();
  const unique = candidates
    .sort((a, b) => b.score - a.score || offlineLookupEntityLabel(a).localeCompare(offlineLookupEntityLabel(b)))
    .filter((candidate) => {
      const key = offlineLookupEntityKey(candidate);
      if (!key || seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  return { target, candidates: unique };
}

function formatOfflineBroadListResponse(target, candidates = [], options = {}) {
  const start = Math.max(0, options.start || 0);
  const count = options.count || 10;
  const shown = candidates.slice(start, start + count);
  if (!shown.length) {
    return [
      `**${target.display} - additional matches**`,
      "I do not have stronger additional matches in the installed reference set for that exact wording.",
      "**Next move:** broaden the wording slightly or ask for an AI explanation if you want reasoning beyond the stored encyclopedia."
    ].join("\n\n");
  }
  const lines = shown.map((candidate) => {
    const label = offlineLookupEntityLabel(candidate);
    const kind = offlineLookupEntityKind(candidate);
    const snippet = candidate.snippet || "Review this entry with the clinical picture and priority cues.";
    return `**${label}** (${kind}): ${snippet}`;
  });
  const remaining = candidates.length - (start + shown.length);
  return [
    `**${target.display} - causes and related conditions to consider**`,
    ...lines,
    remaining > 0 ? `**More matches available:** ${remaining} lower-priority ${remaining === 1 ? "match" : "matches"} remain if you want to keep expanding the list.` : "",
    offlineBroadPriorityLine(target)
  ].filter(Boolean).join("\n\n");
}

function makeOfflineBroadListResponse(input = "", options = {}) {
  const followup = wantsOfflineListExpansionFollowup(input);
  if (followup) {
    const context = freshOfflineListContext();
    if (!context?.target || !Array.isArray(context.candidates)) return "";
    const start = context.shown || 0;
    const response = formatOfflineBroadListResponse(context.target, context.candidates, {
      start,
      count: 10
    });
    if (options.storeContext !== false) {
      lastOfflineListContext = {
        ...context,
        shown: Math.min(context.candidates.length, start + 10),
        createdAt: Date.now()
      };
    }
    return response;
  }

  if (!wantsOfflineBroadCauseList(input)) {
    return "";
  }
  const { target, candidates } = offlineBroadListCandidates(input);
  if (!target || candidates.length < 2) {
    return "";
  }
  const shown = Math.min(candidates.length, 10);
  if (options.storeContext !== false) {
    lastOfflineListContext = {
      type: "broad-cause-list",
      target,
      candidates,
      shown,
      createdAt: Date.now()
    };
  }
  return formatOfflineBroadListResponse(target, candidates, {
    start: 0,
    count: shown
  });
}

function makeOfflineListResponse(input = "", options = {}) {
  if (!wantsOfflineListFromEncyclopedia(input)) {
    return "";
  }
  if (wantsOfflineListAiExpansionFallback(input)) {
    return "";
  }
  return makeOfflineTeratogenicDrugListResponse(input, options)
    || makeOfflineBroadListResponse(input, options)
    || makeOfflineDrugClassListResponse(input, options)
    || makeOfflineGeneralListResponse(input, options);
}

function wantsBinaryRelationshipAnswer(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(?:does|do|did|can|could|will|would|is|are)\b[\s\S]{0,120}\b(?:cause|causes|trigger|triggers|lead to|leads to|make|makes|affect|affects|worsen|worsens|related to)\b/i.test(lower)
    || /\bhow\b[\s\S]{0,120}\b(?:affect|affects|change|changes|alter|alters|influence|influences)\b/i.test(lower)
    || /\b(?:effect|effects|impact|impacts)\b[\s\S]{0,80}\bon\b/i.test(lower)
    || /\brelationship\s+between\b/i.test(lower);
}

function hasCuratedOfflineBinaryRelationshipAnswer(input = "") {
  const lower = normalizeIntentText(input);
  const curatedStressAnemia = /\bstress\b/i.test(lower)
    && /\b(anemia|anaemia|low hgb|low hemoglobin|low hematocrit|low hct)\b/i.test(lower);
  const curatedArdsHypoxemia = /\b(ards|acute respiratory distress syndrome)\b/i.test(lower)
    && /\b(?:refractory hypox(?:emia|ia)?|hypoxemia despite oxygen|won'?t correct|despite fio2)\b/i.test(lower);
  const directedLabMeaning = /\b(low|decreased|decrease|below|deficient|high|elevated|increased|above|abnormal|hyponatremia|hypernatremia|hypokalemia|hyperkalemia)\b/i.test(lower)
    && LAB_INTERPRETATION_RULES.some((rule) => rule.pattern.test(lower));
  return curatedStressAnemia || curatedArdsHypoxemia || directedLabMeaning;
}

function offlineCandidatePrimaryTerms(candidate = {}) {
  const item = candidate.item || {};
  if (candidate.type === "drug") {
    return pharmIdentityTermsForEntry(item);
  }
  if (candidate.type === "lab") {
    return [item.name, ...(item.aliases || [])];
  }
  if (candidate.type === "pathology") {
    return [item.name, ...(item.aliases || [])];
  }
  if (candidate.type === "holistic") {
    return [item.name, ...(item.aliases || [])];
  }
  if (candidate.type === "reference") {
    return [
      item.name,
      item.displayName,
      item.fullForm,
      ...(item.aliases || []),
      ...(item.abbreviations || []),
      ...(item.commonMisspellings || [])
    ];
  }
  return [offlineLookupEntityLabel(candidate)];
}

function inputDirectlyNamesOfflineCandidate(input = "", candidate = {}) {
  const cleanInput = normalizeOfflineLookupText(input, { dropLookupWords: true });
  const compactInput = cleanInput.replace(/\s+/g, "");
  if (!cleanInput && !compactInput) return false;
  return offlineCandidatePrimaryTerms(candidate)
    .map((term) => normalizeOfflineLookupText(term, { dropLookupWords: false }))
    .filter((term) => term.length >= 3)
    .some((term) => {
      const compactTerm = term.replace(/\s+/g, "");
      if (cleanInput === term || compactInput === compactTerm) return true;
      if (term.length >= 4 && cleanInput.includes(term)) return true;
      if (compactTerm.length >= 4 && compactInput.includes(compactTerm)) return true;
      return false;
    });
}

function makeOfflineRelationshipAnswer(input = "", candidate = {}) {
  const lower = normalizeIntentText(input);
  const label = normalizePharmText(offlineLookupEntityLabel(candidate));
  if (/\bstress\b/i.test(lower) && /\b(anemia|anaemia|low hgb|low hemoglobin|low hematocrit|low hct)\b/i.test(lower)) {
    return [
      "**Short answer:** stress by itself is **not a typical direct cause of anemia**.",
      "**What actually causes anemia:** blood loss, iron deficiency, vitamin B12 or folate deficiency, chronic kidney disease, chronic inflammation, hemolysis, bone marrow failure, pregnancy hemodilution, or inherited hemoglobin disorders.",
      "**Where stress fits:** chronic stress can indirectly contribute if it worsens nutrition, sleep, inflammation, heavy menstrual bleeding patterns, GI symptoms, or an underlying illness. But on NCLEX, do not stop at \"stress\" as the cause. Look for the mechanism that lowers oxygen-carrying capacity.",
      "**Numbers to anchor it:** adult female hemoglobin is usually about **12-16 g/dL**. In pregnancy, anemia thresholds are commonly **<11 g/dL in the 1st trimester**, **<10.5 g/dL in the 2nd trimester**, and **<11 g/dL in the 3rd trimester**. Adult female hematocrit is often about **36-46%**.",
      "**Nursing move:** if a client says they are stressed and tired, still assess for pallor, dyspnea, tachycardia, dizziness, bleeding, diet, pregnancy, kidney disease, medications, and CBC trends.",
      "**NCLEX trap:** fatigue plus stress does not equal psychosocial-only. The nurse still checks the physiologic causes of low hemoglobin."
    ].join("\n\n");
  }
  if (label === "anemia" && wantsAnswerInChatFromReference(input)) {
    return makeOfflinePathologyResponse("anemia");
  }
  return "";
}

function populationRiskTypesFromInput(input = "") {
  const lower = normalizeIntentText(input);
  const types = [];
  const add = (type) => {
    if (!types.includes(type)) types.push(type);
  };
  if (/\b(geriatric|geriatrics|older adult|older adults|elderly|senior|seniors|aging|older client|older patient)\b/i.test(lower)) {
    add("geriatric");
  }
  if (/\b(pediatric|pediatrics|peds|kid|kids|child|children|baby|babies|infant|infants|newborn|neonate|teen|adolescent)\b/i.test(lower)) {
    add("pediatric");
  }
  if (/\b(pregnan|pregnancy|pregnant|maternity|maternal|obstetric|obstetrics|fetal|teratogenic|teratogen|teratogens|tetragenic|teragenic|birth defect|birth defects|embryo fetal|embryofetal|breastfeeding|lactation)\b/i.test(lower)) {
    add("pregnancy");
  }
  return types;
}

function wantsPopulationRiskExplanation(input = "") {
  const lower = normalizeIntentText(input);
  if (!lower) return false;
  const populationTypes = populationRiskTypesFromInput(lower);
  const iconLegendCue = /\b(icon|icons|symbol|symbols|badge|badges|legend)\b/i.test(lower)
    && /\b(mean|means|meaning|why|population|risk|risks|unsafe|caution|warning|flag|flags)\b/i.test(lower);
  return iconLegendCue
    || (populationTypes.length > 0
      && /\b(why|icon|icons|symbol|symbols|badge|badges|flag|flags|meaning|mean|means|unsafe|not safe|avoid|caution|contraindicated|contraindication|friendly|no no|non friendly|high risk|high-risk|risk|risky|bad for|problem|danger|dangerous)\b/i.test(lower));
}

function populationRiskLabel(type = "") {
  return {
    pregnancy: "Pregnancy/maternity caution",
    pediatric: "Pediatric caution",
    geriatric: "Geriatric/older-adult caution"
  }[type] || "Population caution";
}

function populationRiskIconMeaning(type = "") {
  return {
    pregnancy: "The pregnancy icon means the drug may be unsafe or high-caution in pregnancy, fetal development, maternity care, or lactation. The nurse should verify pregnancy status, indication, trimester-specific risk, safer alternatives, and provider/pharmacist guidance before giving.",
    pediatric: "The pediatric icon means the drug may be unsafe, age-restricted, dose-sensitive, or high-caution for babies, children, or adolescents. The nurse should verify age, weight-based dosing, formulation, adverse effects, and pediatric-specific contraindications.",
    geriatric: "The geriatric icon means older adults may be more vulnerable because of lower physiologic reserve, slower clearance, fall risk, cognitive effects, renal/hepatic changes, and polypharmacy. The nurse should question unsafe routine use and monitor closely."
  }[type] || "The icon means this entry has a population-specific safety caution.";
}

function inputNamesPharmDrug(input = "", drug = {}) {
  const clean = normalizePharmText(input);
  if (!clean || !drug) return false;
  const names = [
    drug.name,
    drug.generic,
    ...(drug.brandExamples || []),
    ...(drug.aliases || [])
  ]
    .map((term) => normalizePharmText(term))
    .filter((term) => term.length >= 3);
  return names.some((term) => normalizedTextHasPhrase(clean, term) || clean.includes(term));
}

function findPopulationRiskDrugCandidate(input = "") {
  if (!wantsPopulationRiskExplanation(input)) return null;
  const isEligiblePopulationRiskDrug = (drug) => Boolean(drug)
    && !(drug.generatedClassCard === true
      && drug.generatedClassContentOwnership === "navigation-only");
  const namedNavigationOnlyClass = pharmDrugs.find((drug) =>
    !isEligiblePopulationRiskDrug(drug) && inputNamesPharmDrug(input, drug));
  if (namedNavigationOnlyClass) return null;
  const fastMatch = collectFastLookupCandidates(input, ["drug"])
    .filter((candidate) => candidate.type === "drug")
    .map((candidate) => ({
      drug: candidate.item,
      score: scoreFastLookupCandidate(candidate, input).score
    }))
    .filter(({ drug, score }) => score >= 80 && inputNamesPharmDrug(input, drug))
    .sort((a, b) => b.score - a.score || pharmDrugDisplayName(a.drug).localeCompare(pharmDrugDisplayName(b.drug)))[0];
  if (fastMatch) {
    return isEligiblePopulationRiskDrug(fastMatch.drug) ? fastMatch.drug : null;
  }

  const directDrug = pharmDrugs
    .filter((drug) => isEligiblePopulationRiskDrug(drug) && inputNamesPharmDrug(input, drug))
    .sort((a, b) => {
      const aPrimary = [a.name, a.generic].some((term) => normalizedTextHasPhrase(normalizePharmText(input), normalizePharmText(term)));
      const bPrimary = [b.name, b.generic].some((term) => normalizedTextHasPhrase(normalizePharmText(input), normalizePharmText(term)));
      return Number(bPrimary) - Number(aPrimary) || pharmDrugDisplayName(a).localeCompare(pharmDrugDisplayName(b));
    })[0];
  if (directDrug) return directDrug;
  const fallbackDrug = bestPharmMatch(input, { requireIdentityMatch: true });
  return isEligiblePopulationRiskDrug(fallbackDrug) ? fallbackDrug : null;
}

function inferredPopulationRiskNote(drug = {}, type = "") {
  if (drug.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only") {
    return "";
  }
  const identityTerms = pharmIdentityTermsForEntry(drug);
  const blob = normalizePharmText([
    ...identityTerms,
    drug.class,
    drug.templateKey,
    drug.boxedWarning,
    drug.mechanism,
    pharmUsedToTreat(drug),
    ...(drug.nursingEssentials || []),
    ...(drug.interactions || []),
    ...(drug.nclexTraps || [])
  ].join(" "));

  if (type === "geriatric") {
    if (/\b(benzodiazepine|benzo|sedative|hypnotic|gaba|cns depressant)\b/i.test(blob)) {
      return "Benzodiazepines and sedative/CNS depressant drugs can hit older adults harder: oversedation, delirium/confusion, impaired gait, falls/fractures, and respiratory depression become much more likely, especially with opioids, alcohol, sleep meds, or other sedatives.";
    }
    if (/\b(antipsychotic|neuroleptic|dopamine antagonist)\b/i.test(blob)) {
      return "Older adults, especially clients with dementia-related psychosis, have higher mortality, EPS, sedation, orthostasis, QT, fall, and aspiration risk with antipsychotics. Use should be strongly justified and closely monitored.";
    }
    if (/\b(anticholinergic|tricyclic|tca|first generation antihistamine)\b/i.test(blob)) {
      return "Anticholinergic burden is rough on older adults: confusion, urinary retention, constipation, glaucoma worsening, dry mouth, blurred vision, and falls can stack quickly.";
    }
    if (/\b(opioid|narcotic|mu opioid)\b/i.test(blob)) {
      return "Older adults are more sensitive to opioid sedation and respiratory depression, and constipation/falls can become priority safety problems. Dose, respiratory rate, sedation level, bowel regimen, and other CNS depressants matter.";
    }
    return "Older adults often have reduced renal/hepatic reserve, higher fall risk, polypharmacy, and more sensitive CNS/cardiovascular responses, so the same medication can cause stronger adverse effects than expected.";
  }

  if (type === "pediatric") {
    if (/\b(fluoroquinolone|tetracycline|aspirin|salicylate|codeine|tramadol)\b/i.test(blob)) {
      return "This drug/class has pediatric-specific safety issues such as age restrictions, growth/tooth/bone concerns, tendon/joint concerns, respiratory depression, or severe adverse effects. Pediatric dosing and contraindications cannot be treated like small adult dosing.";
    }
    return "Pediatric clients need age- and weight-specific dosing, formulation checks, and developmental safety screening because toxicity can appear at doses that would not worry you in an adult.";
  }

  if (type === "pregnancy") {
    if (/\b(ace inhibitor|angiotensin|arb|sartan|statin|warfarin|isotretinoin|methotrexate|valproate|tetracycline)\b/i.test(blob)) {
      return "This drug/class is a pregnancy safety stop because fetal harm, teratogenicity, fetal kidney injury, bleeding, bone/tooth effects, or pregnancy-specific toxicity may occur. Verify pregnancy status and safer alternatives before giving.";
    }
    return "Pregnancy changes risk because fetal development, placental transfer, maternal physiology, trimester timing, and lactation can change whether a medication is appropriate.";
  }

  return "";
}

function makePopulationIconLegendAnswer(input = "") {
  if (!wantsPopulationRiskExplanation(input)) return "";
  const lower = normalizeIntentText(input);
  if (!/\b(icon|icons|symbol|symbols|badge|badges|legend|meaning|mean|means)\b/i.test(lower)) return "";
  const types = populationRiskTypesFromInput(input);
  const selectedTypes = types.length ? types : ["pregnancy", "pediatric", "geriatric"];
  return [
    "**ANI population icons - what they mean**",
    ...selectedTypes.map((type) => `**${populationRiskLabel(type)}:** ${populationRiskIconMeaning(type)}`),
    "**NCLEX move:** when an icon appears, pause before routine administration. Ask: is this population more sensitive, is the dose different, is the drug contraindicated, and what assessment would make me hold or question it?"
  ].join("\n\n");
}

function makeOfflinePopulationRiskAnswer(input = "") {
  if (!wantsPopulationRiskExplanation(input)) return "";
  const drug = findPopulationRiskDrugCandidate(input);
  if (drug?.generatedClassCard === true
    && drug.generatedClassContentOwnership === "navigation-only") {
    return "";
  }
  if (!drug) {
    return makePopulationIconLegendAnswer(input);
  }

  const requestedTypes = populationRiskTypesFromInput(input);
  const risks = Array.isArray(drug.populationRisks) ? drug.populationRisks : [];
  const types = requestedTypes.length
    ? requestedTypes
    : Array.from(new Set(risks.map((risk) => risk.type).filter(Boolean)));
  const selectedTypes = types.length ? types : ["geriatric", "pediatric", "pregnancy"];
  const riskSections = selectedTypes
    .map((type) => {
      const matchingRisks = risks.filter((risk) => risk.type === type);
      const explicitNotes = matchingRisks.map((risk) => `${risk.label || populationRiskLabel(type)}: ${risk.note}`).filter(Boolean);
      const inferred = inferredPopulationRiskNote(drug, type);
      const notes = explicitNotes.length ? explicitNotes : (inferred ? [inferred] : []);
      if (!notes.length) return "";
      return `**${populationRiskLabel(type)}:** ${notes.join(" ")}`;
    })
    .filter(Boolean);

  if (!riskSections.length) {
    return "";
  }

  const drugDisplayName = pharmDrugDisplayName(drug);
  currentTopic = drugDisplayName;
  updateFocus();
  const classText = pharmDisplayClass(drug);
  return [
    `**${drugDisplayName} - why this population icon/caution matters**`,
    classText ? `**Class:** ${classText}` : "",
    ...riskSections,
    `**Clinical why:** ${inferredPopulationRiskNote(drug, selectedTypes[0]) || "This drug needs population-specific safety screening before routine use."}`,
    `**Nursing move:** assess indication, dose, route, allergies, baseline vitals, mental status, fall risk, renal/hepatic function when relevant, and interacting drugs before giving. For high-risk combinations, clarify instead of normalizing the order.`,
    `**NCLEX trap:** do not treat the icon as decoration. It means the nurse should connect the medication to the patient's population and decide whether to give, hold, question, monitor, or escalate.`
  ].filter(Boolean).join("\n\n");
}

const OFFLINE_SEGMENT_INTENT_TERMS = Object.freeze([
  "nursing", "nurse", "priority", "priorities", "intervention", "interventions",
  "action", "actions", "monitoring", "warning", "warnings", "boxed", "contraindication",
  "contraindications", "interaction", "interactions", "adverse", "effect", "effects", "side",
  "risk", "risks", "factor", "factors",
  "symptom", "symptoms", "sign", "signs", "finding", "findings", "diagnostic", "diagnostics", "diagnosis",
  "cause", "causes", "trigger", "triggers", "etiology", "pathophysiology", "treatment",
  "treatments", "teaching", "education", "mechanism", "class", "range", "ranges", "value",
  "values", "laboratory", "labs", "use", "uses", "used",
  "component", "components", "constitute", "constitutes", "constituted", "constituting",
  "comprise", "comprises", "comprised", "comprising", "consist", "consists", "consisting",
  "include", "includes", "included", "including", "make", "makes", "made", "up"
]);

const OFFLINE_SEGMENT_IDENTITY_DROP_WORDS = new Set([
  ...OFFLINE_SEGMENT_INTENT_TERMS,
  "black", "box", "for", "of", "about", "please", "tell", "show", "give", "explain",
  "what", "which", "who", "why", "how", "when", "where", "is", "are", "was", "were",
  "do", "does", "did", "can", "could", "would", "should", "will", "i", "me", "my", "you", "your",
  "we", "our", "it", "this", "that", "s", "the", "a", "an"
]);

function normalizeOfflineSegmentIntentText(input = "") {
  const normalized = normalizeIntentText(applyClinicalSpeechFixups(input) || input);
  return normalized.split(" ").map((token) => {
    if (token === "bx") return "box";
    if (!token || token.length < 4 || OFFLINE_SEGMENT_INTENT_TERMS.includes(token)) return token;
    const maximumDistance = token.length <= 5 ? 1 : 2;
    let best = token;
    let bestDistance = maximumDistance + 1;
    OFFLINE_SEGMENT_INTENT_TERMS.forEach((term) => {
      if (term[0] !== token[0] || Math.abs(term.length - token.length) > maximumDistance) return;
      const distance = nearIdentityEditDistance(token, term);
      if (distance < bestDistance) {
        best = term;
        bestDistance = distance;
      }
    });
    return bestDistance <= maximumDistance ? best : token;
  }).join(" ").replace(/\s+/g, " ").trim();
}

function offlineSegmentIdentityQuery(input = "") {
  const tokens = normalizeOfflineSegmentIntentText(input)
    .split(" ")
    .filter(Boolean);
  const ordinaryCore = tokens
    .filter((token) => !OFFLINE_SEGMENT_IDENTITY_DROP_WORDS.has(token))
    .join(" ")
    .trim();
  const discriminatorCore = tokens
    .filter((token, index) => {
      if (!OFFLINE_SEGMENT_IDENTITY_DROP_WORDS.has(token)) return true;
      if (token !== "a") return false;
      return tokens.slice(0, index)
        .some((priorToken) => !OFFLINE_SEGMENT_IDENTITY_DROP_WORDS.has(priorToken));
    })
    .join(" ")
    .trim();
  if (discriminatorCore !== ordinaryCore
    && fastVoiceIdentityCandidates(discriminatorCore).length > 0) {
    return discriminatorCore;
  }
  return ordinaryCore;
}

function offlineSegmentIdentityCandidate(input = "") {
  const core = offlineSegmentIdentityQuery(input);
  if (!core || core.length < 3) return null;
  const normalizedInput = normalizeOfflineSegmentIntentText(input);
  const explicitTypes = offlineNearIdentityExplicitTypes(normalizedInput);
  if (/\b(trigger|triggers|precipitant|precipitants)\b/i.test(normalizedInput)) explicitTypes.add("pathology");

  const exact = fastVoiceIdentityCandidates(core);
  const exactPreferred = explicitTypes.size
    ? exact.filter((candidate) => explicitTypes.has(candidate.type))
    : exact;
  const exactUnique = Array.from(new Map(exactPreferred.map((candidate) => [offlineLookupEntityKey(candidate), candidate])).values());
  if (exactUnique.length === 1) {
    return { ...exactUnique[0], score: 3400 };
  }

  const assessment = fastVoiceNearIdentityAssessment(core, {
    preferredTypes: explicitTypes
  });
  if (!assessment.match || assessment.ambiguous) return null;
  return {
    type: assessment.match.type,
    item: assessment.match.item,
    score: 3000 + Math.round(assessment.match.similarity * 300),
    similarity: assessment.match.similarity
  };
}

function offlineSegmentIntentRemainder(input = "", candidate = null) {
  const normalizedInput = normalizeOfflineLookupText(normalizeOfflineSegmentIntentText(input), { dropLookupWords: false });
  if (!normalizedInput || !candidate?.item) return normalizedInput;
  const identityTerms = offlineCandidatePrimaryTerms(candidate)
    .map((term) => normalizeOfflineLookupText(term, { dropLookupWords: false }))
    .filter((term) => term.length >= 2)
    .sort((left, right) => right.length - left.length);
  const matchingIdentity = identityTerms.find((term) => {
    const escaped = term.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return new RegExp(`(?:^|\\s)${escaped}(?=\\s|$)`, "i").test(normalizedInput);
  });
  if (!matchingIdentity) return normalizedInput;
  const escapedIdentity = matchingIdentity.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return normalizedInput
    .replace(new RegExp(`(?:^|\\s)${escapedIdentity}(?=\\s|$)`, "i"), " ")
    .replace(/\s+/g, " ")
    .trim();
}

function offlineSegmentIntents(input = "", candidate = null) {
  const lower = normalizeOfflineSegmentIntentText(offlineSegmentIntentRemainder(input, candidate));
  const intents = [];
  const add = (intent) => {
    if (!intents.includes(intent)) intents.push(intent);
  };

  const explicitRangeVocabulary = /\b(range|ranges|normal value|normal values|normal range|therapeutic|therapeutic range|level|levels|value|values|target|threshold|toxic level|toxicity level)\b/i.test(lower);
  const qualitativeReferenceResult = candidate?.type === "reference"
    && candidate.item?.diagnosticKind !== "lab"
    && /\b(normal|expected|positive|negative|abnormal)\b[\s\S]{0,50}\b(result|finding|response|mean|meaning|interpretation)\b/i.test(lower)
    && !/\b(range|ranges|value|values|level|levels|threshold|target)\b/i.test(lower);
  if (!qualitativeReferenceResult
    && (explicitRangeVocabulary || /\b(normal|expected|usual|healthy)\b/i.test(lower))) add("range");
  if (!candidate && hasExplicitLabRangeCue(input) && bestLabMatch(input)) add("range");
  if (/\bnormal\b[\s\S]{0,80}\b(height|weight|growth|percentile|percentiles)\b/i.test(lower)) add("range");
  if (/\b(class|drug class|med class|medication class|category|type of drug|what kind of drug)\b/i.test(lower)) add("class");
  if (/\b(component|components|constitute|constitutes|constituted|constituting|comprise|comprises|comprised|comprising|consist|consists|consisting|include|includes|included|including|make up|makes up|made up)\b/i.test(lower)) add("components");
  if (/\b(used for|use for|treats?|treated with|indication|indications|why (?:is|do|does).*used)\b/i.test(lower)
    || /\bwhat\s+(?:is|are)\s+(?:(?:it|this|that)\s+)?for\b/i.test(lower)) add("uses");
  const causalMechanismRequest = /\b(why can|why does|why do|why did|how can|what makes)\b/i.test(lower)
    && !/\b(use|used|prescribed|given|indicated|recommended)\b/i.test(lower);
  if (/\b(how (?:does|do|is).*work|mechanism|mechanisms|mechanism of action|pharmacodynamics|pharmacokinetics|how it works|what does.*do)\b/i.test(lower) || causalMechanismRequest) add("mechanism");
  if (/\b(black box|boxed warning|box warning|high alert|high-alert|major warning|warnings?|red flags?|urgent|reportable)\b/i.test(lower)) add("warning");
  if (/\b(contraindication|contraindications|contraindicated|do not give|don'?t give|avoid|unsafe|who should not|who shouldn'?t|clarify before)\b/i.test(lower)) add("contraindications");
  if (/\b(interaction|interactions|mix|mixed with|combine|combined with|take with|taken with|together|drug-drug)\b/i.test(lower)) add("interactions");
  if (/\b(side effect|side effects|adverse|adverse effect|adverse effects|risk|risks|toxicity|toxicities|danger|dangerous|complication|complications)\b/i.test(lower)
    && !/\brisk factors?\b/i.test(lower)) add("risks");
  if (/\b(lab|labs|laboratory|monitor|monitoring|parameter|parameters|check before|check prior|checklist|baseline)\b/i.test(lower)) add("labs");
  if (/\b(nursing|nurse|priority|priorities|intervention|interventions|monitor for|watch for|hold|question|report|safety)\b/i.test(lower)) add("nursing");
  if (/\b(sign|signs|symptom|symptoms|finding|findings|manifestation|manifestations|presentation|presents?)\b/i.test(lower)) add("signs");
  const semanticDiagnosticQuestion = ["lab", "reference"].includes(candidate?.type)
    && /\bwhat\b[\s\S]{0,60}\b(?:shows?|indicates?|means?|tells?)\b/i.test(lower);
  if (/\b(diagnose|diagnosis|diagnostic|diagnostics|workup|screen|screening|test|tests|tool|tools|measure|measures|measured|evaluate|evaluates|meaning|interpret|interpretation|result|results|positive|negative|abnormal)\b/i.test(lower)
    || semanticDiagnosticQuestion) add("diagnostics");
  if (/\b(cause|causes|caused by|etiology|risk factor|risk factors|trigger|triggers|precipitant|precipitants|why does|why do|why is)\b/i.test(lower)) add("etiology");
  if (/\b(patho|pathophysiology|pathology|what is happening|what happens|disease process|process)\b/i.test(lower)) add("pathophysiology");
  if (/\b(treat|treatment|treatments|therapy|therapies|manage|management|first line|priority treatment|how to treat)\b/i.test(lower)) add("treatment");
  if (/\b(patient education|client education|teaching|teach|teachings|educate|education)\b/i.test(lower)) add("teaching");
  if (/\b(nclex|trap|traps|nuance|testable|board|boards|exam likes|high yield|high-yield)\b/i.test(lower)) add("nclex");
  if (wantsPopulationRiskExplanation(input)) add("population");
  if (/\b(pregnancy|pregnant|maternity|maternal|pediatric|peds|kid|kids|child|children|geriatric|older adult|elderly|population)\b/i.test(lower)) add("population");
  if (candidate?.type === "reference"
    && /\b(procedure steps|preparation|how to prepare|positioning|collection steps|before (?:the )?(?:test|procedure)|during (?:the )?(?:test|procedure)|after (?:the )?(?:test|procedure))\b/i.test(lower)) add("procedureSteps");

  return intents;
}

function wantsOfflineSegmentAnswer(input = "") {
  if (wantsAiGeneratedStudyWork(input)
    || wantsLecture(input)
    || wantsOfflineLabComparison(input)
    || wantsBinaryRelationshipAnswer(input)) {
    return false;
  }
  const candidate = offlineSegmentCandidate(input);
  return Boolean(candidate && offlineSegmentIntents(input, candidate).length > 0);
}

const OFFLINE_REFERENCE_REQUEST_WORDS = new Set([
  "a", "an", "the", "i", "me", "my", "you", "your", "this", "that", "it",
  "what", "which", "who", "why", "how", "when", "where",
  "do", "does", "did", "is", "are", "was", "were", "can", "could", "would", "should", "will",
  "please", "tell", "tells", "show", "open", "find", "explain", "define", "about", "for", "to", "of", "on",
  "look", "lookup", "up", "give", "overview", "summary", "information",
  "measure", "measures", "measured", "measuring", "evaluate", "evaluates", "evaluated", "checks", "check", "work", "works",
  "mean", "means", "meaning", "interpret", "interpreting", "interpretation",
  "result", "results", "positive", "negative", "normal", "abnormal", "high", "low", "elevated", "decreased",
  "prep", "prepare", "preparation", "before", "after", "during", "steps", "procedure",
  "risk", "risks", "warning", "warnings", "safety", "diagnostic", "diagnostics", "screen", "screening",
  "nursing", "nurse", "consideration", "considerations", "red", "flag", "flags", "urgent", "report", "reportable", "cue", "cues",
  "value", "values", "range", "ranges", "purpose", "used"
]);

function directlyNamedClinicalReferenceCandidate(input = "") {
  const lower = normalizeIntentText(input);
  if (!lower
    || wantsAiGeneratedStudyWork(input)
    || /\b(?:test|quiz)\s+me\b/i.test(lower)) {
    return null;
  }
  const entry = exactClinicalReferenceIdentityMatch(input);
  if (!entry) return null;
  const candidate = { type: "reference", item: entry, score: 2800 };
  const remainder = normalizeIntentText(offlineSegmentIntentRemainder(input, candidate));
  const remainderTokens = remainder.split(" ").filter(Boolean);
  if (remainderTokens.length
    && !remainderTokens.every((token) => OFFLINE_REFERENCE_REQUEST_WORDS.has(token))) {
    return null;
  }
  const competingExplicitLab = /\b(range|ranges|normal|expected|value|values|level|levels|threshold|target)\b/i.test(remainder)
    ? exactRegisteredLabIdentityMatch(input)
    : null;
  if (competingExplicitLab) {
    return null;
  }
  return candidate;
}

function offlineSegmentCandidate(input = "") {
  const identityCandidate = offlineSegmentIdentityCandidate(input);
  if (identityCandidate) {
    return identityCandidate;
  }
  const namedReference = directlyNamedClinicalReferenceCandidate(input);
  if (namedReference) {
    return namedReference;
  }
  // A targeted section answer requires an exact, near, or directly named card.
  // Clue-ranked suggestions remain available to the broader lookup flow, but
  // cannot lend an unrelated card's section to this narrow response path.
  return null;
}

function offlineSegmentTitle(intent = "", candidate = null) {
  if (intent === "warning" && candidate?.type === "reference") {
    return "Warnings / urgent reportable cues";
  }
  return {
    range: "Reference range / values",
    components: "Components / defining features",
    class: "Class",
    uses: "Used for / common uses",
    mechanism: "Mechanism / how it works",
    warning: "Boxed warning / major warning",
    contraindications: "Contraindications / clarify before giving",
    interactions: "Interactions to watch",
    risks: "Major risks / adverse-effect cues",
    labs: "Labs / assessment monitoring",
    nursing: "Priority nursing actions",
    signs: "Signs, symptoms, and clinical findings",
    diagnostics: "Diagnostics / assessment clues",
    etiology: "Etiology / risk factors",
    pathophysiology: "Pathophysiology",
    treatment: "Treatment / management",
    teaching: "Client teaching",
    nclex: "NCLEX trap / high-yield nuance",
    population: "Population-specific notes",
    procedureSteps: "Procedure-specific steps"
  }[intent] || "Key point";
}

function offlineSegmentSourceRecord(sourceSectionId = "", label = "", value = "") {
  const text = Array.isArray(value) ? readableListText(value) : safeText(value);
  if (!text) return null;
  return {
    sourceSectionId: safeText(sourceSectionId),
    label: safeText(label, "Key point"),
    value: text
  };
}

function offlineSegmentSourceRecords(records = []) {
  return records.filter((record) => record && safeText(record.value));
}

function offlineSegmentValue(candidate = {}, intent = "", input = "") {
  const item = candidate.item || {};
  const record = (sourceSectionId, label, value) => offlineSegmentSourceRecord(sourceSectionId, label, value);

  if (candidate.type === "drug") {
    if (item.generatedClassCard === true
      && item.generatedClassContentOwnership === "navigation-only") {
      if (intent !== "class") return [];
      return offlineSegmentSourceRecords([
        record("class", "Class", pharmDisplayClass(item)),
        record("generatedClassSegment", "Specific class / pathway", pharmClassPathwayText(item))
      ]);
    }
    const populationText = pharmListText([
      ...(item.populationRisks || []).map((risk) => `${risk.label}: ${risk.note}`),
      ...(item.specialPopulations || [])
    ]);
    const values = {
      class: [record("class", "Class", pharmDisplayClass(item))],
      uses: [record("usedToTreat", "Used for / common uses", pharmUsedToTreat(item))],
      mechanism: [record("mechanism", "Mechanism / how it works", pharmMechanismText(item))],
      warning: [record("boxedWarning", "Boxed warning / major warning", pharmBoxedWarningDisplay(item))],
      contraindications: [record("contraindications", "Contraindications / clarify before giving", pharmListText(item.contraindications))],
      interactions: [record("interactions", "Interactions to watch", pharmListText(item.interactions))],
      risks: [record("adverseEffects", "Major risks / adverse-effect cues", pharmAdverseEffectsText(item))],
      labs: [record("keyLabs", "Labs / assessment monitoring", pharmListText(item.keyLabs))],
      nursing: [record("nursingEssentials", "Priority nursing actions", pharmListText(item.nursingEssentials))],
      teaching: [record("patientEducation", "Client teaching", pharmListText(item.patientEducation))],
      nclex: [record("nclexTraps", "NCLEX trap / high-yield nuance", pharmListText(item.nclexTraps))],
      population: [record("populationRisks", "Population-specific notes", populationText)]
    };
    return offlineSegmentSourceRecords(values[intent] || []);
  }

  if (candidate.type === "lab") {
    const teaching = labProjectedTeachingSections(item).flatMap((section) => {
      const items = Array.isArray(section.items) && section.items.length
        ? section.items
        : [{ path: section.path, text: section.value }];
      return items.map((leaf) => ({
        ...record(safeText(leaf.path || section.path), section.label, leaf.text),
        structuredField: safeText(section.key),
        authoredStructured: section.authoredStructured === true
      }));
    }).filter((section) => section && safeText(section.value));
    const pickTeaching = (patterns = [], structuredFields = []) => teaching.filter((section) => (
      section && (
        structuredFields.includes(section.structuredField)
        || (!section.structuredField && patterns.some((pattern) => pattern.test(section.label)))
      )
    ));
    const range = record("range", "Reference range / values", item.range);
    const why = record("why", "What this lab tells you", item.why);
    const groupNote = record("groupNote", "Population-specific notes", item.groupNote);
    const values = {
      class: [record("category", "Category", item.category)],
      range: [range],
      uses: [why],
      warning: pickTeaching([/red flag|danger|critical|urgent|concerning/i], ["criticalConcerns"]),
      contraindications: pickTeaching([/^contraindications?|when not to|do not use/i]),
      interactions: pickTeaching([/^interactions?/i]),
      risks: pickTeaching([/red flag|danger|critical|concerning|low pattern|high pattern/i], ["criticalConcerns"]),
      labs: [range, why],
      nursing: pickTeaching([/^priority nursing|nursing actions?|monitoring/i], ["nursingConsiderations"]),
      signs: pickTeaching([/low pattern|high pattern|signs?|symptoms?|findings?|concerning/i]),
      diagnostics: [why],
      etiology: pickTeaching([/^etiology|^causes?|risk factors?/i], ["highCauses", "lowCauses"]),
      pathophysiology: pickTeaching([/^pathophysiology|disease process/i]),
      treatment: pickTeaching([/treatment direction|^treatment|^management/i]),
      teaching: pickTeaching([/patient teaching|client teaching|education/i]),
      nclex: pickTeaching([/nclex|trap|nuance/i], ["nclexTraps"]),
      population: offlineSegmentSourceRecords([groupNote, ...pickTeaching([/pregnan|pediatric|geriatric|population|trimester|age/i])]),
      procedureSteps: pickTeaching([/^procedure|collection steps?|before collection|during collection|after collection/i])
    };
    return offlineSegmentSourceRecords(values[intent] || []);
  }

  if (candidate.type === "pathology") {
    const populationText = pathologyListText([
      ...(item.populationRisks || []),
      ...(item.specialPopulations || [])
    ]);
    const values = {
      class: [record("category", "Category", item.category)],
      mechanism: [record("pathology", "Pathophysiology", item.pathology)],
      warning: [record("redFlags", "Warnings / urgent reportable cues", pathologyListText(item.redFlags))],
      contraindications: [record("contraindications", "Contraindications", pathologyListText(item.contraindications))],
      risks: [record("complications", "Complications", pathologyListText(item.complications))],
      nursing: [record("nursingPriorities", "Priority nursing actions", pathologyListText(item.nursingPriorities))],
      signs: [record("signsSymptoms", "Signs, symptoms, and clinical findings", pathologyListText(item.signsSymptoms))],
      diagnostics: [record("diagnostics", "Diagnostics / expected alterations", pathologyDiagnosticsWithAlterations(item))],
      etiology: [record("etiology", "Etiology / risk factors", item.etiology)],
      pathophysiology: [record("pathology", "Pathophysiology", item.pathology)],
      treatment: [record("treatments", "Treatment / management", pathologyListText(item.treatments))],
      teaching: [record("patientEducation", "Client teaching", pathologyListText(item.patientEducation))],
      nclex: [record("nclexTraps", "NCLEX trap / high-yield nuance", pathologyListText(item.nclexTraps))],
      population: [record("populationRisks", "Population-specific notes", populationText)]
    };
    return offlineSegmentSourceRecords(values[intent] || []);
  }

  if (candidate.type === "holistic") {
    const populationText = pharmListText((item.populationRisks || []).map((risk) => `${risk.label}: ${risk.note}`));
    const values = {
      class: [record("category", "Category", item.category)],
      uses: [record("usedFor", "Used for / common uses", holisticListText(item.usedFor))],
      mechanism: [record("mechanism", "Mechanism / how it works", holisticMechanismText(item))],
      warning: [record("majorRisks", "Warnings / urgent reportable cues", holisticListText(item.majorRisks))],
      contraindications: [record("contraindications", "Contraindications / clarify before using", holisticListText(item.contraindications))],
      interactions: [record("interactions", "Interactions to watch", holisticListText(item.interactions))],
      risks: [record("majorRisks", "Major risks / adverse-effect cues", holisticListText(item.majorRisks))],
      nursing: [record("nursingAssessment", "Priority nursing assessment", holisticListText(item.nursingAssessment))],
      teaching: [record("teaching", "Client teaching", holisticListText(item.teaching))],
      nclex: [record("nclexTraps", "NCLEX trap / high-yield nuance", holisticListText(item.nclexTraps))],
      population: [record("populationRisks", "Population-specific notes", populationText)]
    };
    return offlineSegmentSourceRecords(values[intent] || []);
  }

  if (candidate.type === "reference") {
    const authoredSections = clinicalReferenceSectionRecords(item).map((section) => record(
      `section:${normalizePharmText(section.label)}`,
      section.label,
      section.value
    ));
    const pickSections = (patterns = []) => authoredSections.filter((section) => (
      section && patterns.some((pattern) => pattern.test(section.label))
    ));
    const patterns = {
      range: [/reference range|normal range|expected range|threshold|target range|percentile|weeks?|trimester/i],
      components: [/^components?\b|^criteria\b|^defining features?\b|^what to notice\b|^quick answer\b/i],
      uses: [/^purpose\b|^used for\b|^indications?\b|when .*used/i],
      mechanism: [/^mechanism\b|^how it works\b|^physiology\b/i],
      warning: [/^red flags?\b|^warnings?\b|^urgent\b|when to report|danger/i],
      contraindications: [/^contraindications?\b|when not to|do not use|avoid .*before/i],
      interactions: [/^interactions?\b/i],
      risks: [/^risks?\b|^major risks?\b|^adverse|^complications?\b/i],
      labs: [/^labs?\b|^laboratory\b/i],
      nursing: [/^priority nursing\b|^nursing\b|nursing assessment|assessment and documentation|^monitoring\b/i],
      signs: [/^signs?\b|^symptoms?\b|clinical findings|manifestations/i],
      diagnostics: [/^diagnostics?\b|result interpretation|how to interpret|^what .*\b(?:tells|measures|evaluates|assesses)\b/i],
      etiology: [/^etiology\b|^causes?\b|risk factors?|^triggers?\b/i],
      pathophysiology: [/^pathophysiology\b|disease process/i],
      treatment: [/^treatment\b|^management\b/i],
      teaching: [/patient teaching|client teaching|patient education|client education|^teaching\b/i],
      nclex: [/nclex|trap|high-yield nuance/i],
      population: [/pregnan|trimester|pediatric|geriatric|population|maternal|fetal|growth|percentile|age-specific/i],
      procedureSteps: [/^procedure steps?\b|^before\b|^during\b|^after\b|positioning|collection steps?|how to perform/i]
    };
    if (intent === "components") {
      return offlineSegmentSourceRecords([
        record("quickAnswer", "Components / defining features", item.quickAnswer || item.summary),
        ...pickSections(patterns.components)
      ]);
    }
    const selected = pickSections(patterns[intent] || []);
    if (intent !== "diagnostics") return offlineSegmentSourceRecords(selected);

    const resultRows = clinicalReferenceResultMeaningRows(item);
    const normalizedInput = normalizeIntentText(input);
    const requestedResultRows = /\b(positive|abnormal|high|elevated)\b/i.test(normalizedInput)
      ? resultRows.filter((row) => /positive|detected|abnormal|high/i.test(row.label))
      : (/\b(negative|normal|expected|reassuring)\b/i.test(normalizedInput)
        ? resultRows.filter((row) => /negative|not detected|normal|expected|reassuring|no diagnostic/i.test(row.label))
        : resultRows);
    const resultMeaningText = (requestedResultRows.length ? requestedResultRows : resultRows)
      .map((row) => `**${row.label}:** ${row.meaning}`)
      .join("\n\n");
    return offlineSegmentSourceRecords([
      ...selected,
      record("resultMeanings", "Result interpretation", resultMeaningText)
    ]);
  }

  return [];
}

function offlineSegmentCanReportUnavailable(input = "", candidate = null) {
  if (!candidate?.item) return false;
  return candidate.score >= 3000 || inputDirectlyNamesOfflineCandidate(input, candidate);
}

function offlineSegmentUnavailableNotice(intent = "", candidate = null) {
  const requestedSection = offlineSegmentTitle(intent, candidate);
  return `This card does not currently include a reviewed "${requestedSection}" section. ANI did not substitute a nearby section.`;
}

function buildOfflineSegmentAnswer(input = "", candidate = null, intents = []) {
  if (!candidate?.item || !intents.length) return "";
  if (!intents.length
    || wantsAiGeneratedStudyWork(input)
    || wantsLecture(input)
    || wantsOfflineLabComparison(input)) {
    return "";
  }
  const label = offlineLookupEntityLabel(candidate);
  const sectionsByIntent = intents.map((intent) => ({
    intent,
    records: offlineSegmentValue(candidate, intent, input)
  }));
  const seenSections = new Set();
  const sections = sectionsByIntent
    .flatMap(({ intent, records }) => records.map((section) => ({ ...section, intent })))
    .filter((section) => {
      const key = `${normalizePharmText(section.sourceSectionId)}:${normalizePharmText(section.value)}`;
      if (!key || seenSections.has(key)) return false;
      seenSections.add(key);
      return true;
    });
  const missingIntents = offlineSegmentCanReportUnavailable(input, candidate)
    ? sectionsByIntent.filter(({ records }) => !records.length).map(({ intent }) => intent)
    : [];

  if (!sections.length && !missingIntents.length) {
    return "";
  }

  rememberOfflineLookupTarget(candidate, input);
  currentTopic = label;
  updateFocus();
  return [
    `**${label} - ${sections.length === 1 && !missingIntents.length ? sections[0].label : "targeted encyclopedia answer"}**`,
    ...sections.map(({ label: sectionLabel, value }) => `**${sectionLabel}:** ${value}`),
    ...missingIntents.map((intent) => `**${offlineSegmentTitle(intent, candidate)}:** ${offlineSegmentUnavailableNotice(intent, candidate)}`)
  ].filter(Boolean).join("\n\n");
}

function offlineSegmentTargetDescriptor(candidate = {}) {
  if (!candidate?.type || !candidate?.item) return null;
  return {
    type: candidate.type,
    item: candidate.item,
    label: offlineLookupEntityLabel(candidate),
    query: offlineLookupQuery(candidate),
    key: offlineLookupEntityKey(candidate),
    candidate: { type: candidate.type, item: candidate.item }
  };
}

function offlineSegmentHasPersonalClinicalContext(input = "") {
  // “Tell me” and similar educational phrasing uses a first-person object but
  // does not describe the learner's care. Remove only those request phrases;
  // any remaining personal narrative still fails closed.
  const withoutEducationalRequestObject = safeText(input)
    .replace(/\b(?:tell|show|give|teach|explain|help)(?:\s+it)?(?:\s+to)?\s+me\b/gi, " ");
  return isPersonalClinicalNarrative(withoutEducationalRequestObject);
}

function makeOfflineSegmentResponse(input = "") {
  if (wantsOfflineListExpansionFollowup(input)
    || wantsOfflineBroadCauseList(input)
    || wantsBinaryRelationshipAnswer(input)
    || wantsAiGeneratedStudyWork(input)
    || wantsLecture(input)
    || offlineSegmentHasPersonalClinicalContext(input)
    || wantsOfflineLabComparison(input)) return null;
  const candidate = offlineSegmentCandidate(input);
  if (!candidate) return null;
  const intents = offlineSegmentIntents(input, candidate);
  if (!intents.length) return null;
  const text = buildOfflineSegmentAnswer(input, candidate, intents);
  if (!text) return null;
  return {
    type: "encyclopedia-segment",
    text,
    target: offlineSegmentTargetDescriptor(candidate)
  };
}

function installEncyclopediaSegmentResponsePriority() {
  const baseMakeModelEnhancedResponse = makeModelEnhancedResponse;
  if (typeof baseMakeModelEnhancedResponse !== "function"
    || baseMakeModelEnhancedResponse.aniSegmentPriority === true) return;
  const prioritizedMakeModelEnhancedResponse = function (input = "", ...args) {
    const hasAttachments = (Array.isArray(args[0]) && args[0].length > 0)
      || (Array.isArray(args[1]) && args[1].length > 0);
    if (!hasAttachments) {
      const emergencyHyperkalemiaAnswer = makeOfflineEmergencyHyperkalemiaAnswer(input);
      if (emergencyHyperkalemiaAnswer) return emergencyHyperkalemiaAnswer;
      const smartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(input);
      if (smartDatabaseAnswer) return smartDatabaseAnswer;
      const segmentResponse = makeOfflineSegmentResponse(input);
      if (segmentResponse) return segmentResponse;
    }
    return baseMakeModelEnhancedResponse.apply(this, [input, ...args]);
  };
  Object.defineProperty(prioritizedMakeModelEnhancedResponse, "aniSegmentPriority", {
    value: true,
    enumerable: false
  });
  makeModelEnhancedResponse = prioritizedMakeModelEnhancedResponse;
  window.makeModelEnhancedResponse = prioritizedMakeModelEnhancedResponse;
}

// Several reviewed specialty routers load after main.js. Install this final,
// narrow precedence layer only after those scripts have registered so a
// card-plus-section request cannot be converted back into a broad card open.
if (document.readyState === "loading") {
  window.addEventListener("DOMContentLoaded", installEncyclopediaSegmentResponsePriority, { once: true });
} else {
  window.setTimeout(installEncyclopediaSegmentResponsePriority, 0);
}

function makeOfflineSegmentAnswer(input = "") {
  const emergencyHyperkalemiaAnswer = makeOfflineEmergencyHyperkalemiaAnswer(input);
  if (emergencyHyperkalemiaAnswer) return emergencyHyperkalemiaAnswer;
  const smartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(input);
  if (smartDatabaseAnswer) return smartDatabaseAnswer;
  const populationRiskAnswer = makeOfflinePopulationRiskAnswer(input);
  if (populationRiskAnswer) return populationRiskAnswer;
  const response = makeOfflineSegmentResponse(input);
  return response?.text || "";
}

function makeOfflineReferenceAnswerInChat(input = "") {
  if (wantsAiGeneratedStudyWork(input)) {
    return "";
  }
  if (wantsBinaryRelationshipAnswer(input)
    && !hasCuratedOfflineBinaryRelationshipAnswer(input)) {
    return "";
  }
  const ckdStageAnswer = makeOfflineCkdStageResponse(input);
  if (ckdStageAnswer) {
    return ckdStageAnswer;
  }
  const conceptSynthesisAnswer = makeOfflineConceptSynthesisResponse(input);
  if (conceptSynthesisAnswer) {
    return conceptSynthesisAnswer;
  }
  // high-yield-clue-before-generic-smart-answer
  const highYieldClueDrug = highYieldDrugClueMatch(input);
  const highYieldClueCandidate = highYieldClueDrug
    ? { type: "drug", item: highYieldClueDrug, score: 2700 + pharmIdentityPreferenceScore(highYieldClueDrug) }
    : null;
  if (highYieldClueCandidate && inputDirectlyNamesOfflineCandidate(input, highYieldClueCandidate)) {
    return makeOfflineRelationshipAnswer(input, highYieldClueCandidate)
      || offlineLookupDirectResponse(highYieldClueCandidate, input);
  }
  const namedReference = directlyNamedClinicalReferenceCandidate(input);
  if (namedReference) {
    return makeOfflineSegmentAnswer(input)
      || makeOfflineClinicalReferenceResponseFromEntry(namedReference.item, input);
  }
  const smartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(input);
  if (smartDatabaseAnswer) {
    return smartDatabaseAnswer;
  }
  const offlineListAnswer = makeOfflineListResponse(input);
  if (offlineListAnswer) {
    return offlineListAnswer;
  }
  const segmentAnswer = makeOfflineSegmentAnswer(input);
  if (segmentAnswer) {
    return segmentAnswer;
  }
  if (wantsSpecialtyReference(input)) {
    return makeOfflineClinicalReferenceResponse(input);
  }
  if (!wantsAnswerInChatFromReference(input)) {
    return "";
  }
  if (/\b(anemia|anaemia|low hgb|low hemoglobin|low hematocrit|low hct)\b/i.test(normalizeIntentText(input))) {
    const anemiaEntry = pathologyDiseases.find((disease) => normalizePharmText(disease.name) === "anemia");
    if (anemiaEntry) {
      const anemiaCandidate = { type: "pathology", item: anemiaEntry, score: 999 };
      return makeOfflineRelationshipAnswer(input, anemiaCandidate)
        || offlineLookupDirectResponse(anemiaCandidate, input);
    }
  }
  if (wantsBinaryRelationshipAnswer(input)) {
    return "";
  }
  const suggestions = offlineLookupSuggestions(input);
  const directCandidate = suggestions.find((candidate) => inputDirectlyNamesOfflineCandidate(input, candidate));
  if (!directCandidate || !offlineLookupIsDirectEnough(input, directCandidate)) {
    return "";
  }
  return makeOfflineRelationshipAnswer(input, directCandidate)
    || offlineLookupDirectResponse(directCandidate, input);
}

function isStrongOfflineReferenceRequest(input = "") {
  const lower = normalizeIntentText(input);
  if (wantsTestFormatList(input)
    || wantsTestCreationSetup(input)
    || wantsGenericPracticeProblem(input)
    || wantsClassSpecificExam(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || wantsStandardQuestionGeneration(input)
    || asksForQuestionNow(input)
    || wantsRapidFire(input)
    || wantsDifficultyChange(input)
    || wantsConceptDiagram(input)
    || wantsLecture(input)
    || /\b(in depth|deeper|deeply|deep dive|full lecture|long lecture|lecture|comprehensive|thorough|thoroughly|rationale|why is|why does|why do|compare|difference between|distinguish between|versus|vs\.?)\b/i.test(lower)) {
    return false;
  }
  const hasCue = hasOfflineReferenceCue(input);
  const concise = isConciseOfflineLookupQuery(input);
  if (!hasCue && !concise) {
    return false;
  }
  const suggestions = offlineLookupSuggestions(input);
  const top = suggestions[0];
  return Boolean(top && (hasCue || offlineLookupIntent(input)) && offlineLookupIsDirectEnough(input, top));
}

function wantsAiGeneratedStudyWork(input = "") {
  const lower = normalizeIntentText(input);
  if (isProtectedVisualReferencePhrase(lower)) {
    return false;
  }
  return wantsTestFormatList(input)
    || wantsTestCreationSetup(input)
    || wantsGenericPracticeProblem(input)
    || wantsClassSpecificExam(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || wantsStandardQuestionGeneration(input)
    || asksForQuestionNow(input)
    || wantsRapidFire(input)
    || wantsDifficultyChange(input)
    || wantsConceptDiagram(input)
    || /\b(mcq|multiple choice|single best|one best|standard nclex|practice question|practice item|test question|quiz question)\b/i.test(lower);
}

function wantsAiDepthTeaching(input = "") {
  const lower = normalizeIntentText(input);
  if (wantsLecture(input) || (lectureModePrimed && !wantsPharmDatabase(input))) {
    return true;
  }
  if (wantsBreakdown(input)) {
    return true;
  }
  return /\b(in depth|deeper|deeply|deep dive|full lecture|long lecture|lecture|comprehensive|thorough|thoroughly|teach me|walk me through|talk me through|help me understand|i don'?t understand|i do not understand|i'?m confused|i am confused|confusing|stuck|rationale|why is|why does|why do|how does|how do|compare|difference between|distinguish between|versus|vs\.?)\b/i.test(lower);
}

function shouldUseAiForUserRequest(input = "") {
  if (isOfflineLookupConfirmation(input) || isOfflineLookupRejection(input)) {
    return false;
  }
  if (wantsOfflineListAiExpansionFallback(input)) {
    return true;
  }
  if (wantsBinaryRelationshipAnswer(input)) {
    return !hasCuratedOfflineBinaryRelationshipAnswer(input);
  }
  if (wantsOfflineSmartDatabaseAnswer(input)) {
    return false;
  }
  if (wantsCkdStageAnswer(input)) {
    return false;
  }
  if (wantsAiGeneratedStudyWork(input)) {
    return true;
  }
  if (wantsOfflineSegmentAnswer(input) && offlineSegmentCandidate(input)) {
    return false;
  }
  if (wantsSpecialtyReference(input) && bestClinicalReferenceMatch(input)) {
    return false;
  }
  if (wantsOfflineLabComparison(input)) {
    return false;
  }
  if (makeOfflineListResponse(input, { storeContext: false })) {
    return false;
  }
  if (isStrongOfflineReferenceRequest(input)) {
    return false;
  }
  if (wantsAnswerInChatFromReference(input) && !makeOfflineReferenceAnswerInChat(input)) {
    return true;
  }
  return wantsAiDepthTeaching(input);
}

function wantsOfflineLabComparison(input = "") {
  const lower = normalizeIntentText(compactSpokenMedicalAcronyms(input));
  if (!lower) return false;
  if (wantsGrowthReference(lower) || wantsPregnancyMilestoneReference(lower) || wantsProcedureTestReference(lower)) {
    return false;
  }
  const asksAcrossLabs = /\b(lab|labs|laboratory|value|values|range|ranges|normal|norms|reference)\b/i.test(lower)
    && /\b(change|changes|different|differ|compare|comparison|versus|vs|side by side|which|what)\b/i.test(lower);
  const asksForLabSet = /\b(labs|laboratory values|lab values|normal labs|reference labs)\b/i.test(lower);
  const pediatricAge = detectPediatricAgeIntent(lower);
  const populationCue = /\b(pregnan|pregnancy|pregnant|maternity|maternal|obstetric|women|woman|female|pediatric|peds|kid|kids|child|children|geriatric|older adult|elderly)\b/i.test(lower);
  return populationCue && (asksAcrossLabs || asksForLabSet || (Boolean(pediatricAge) && /\b(lab|labs|laboratory|value|values|range|ranges|normal|norms|reference)\b/i.test(lower)));
}

function offlineLabComparisonTarget(input = "") {
  const lower = normalizeIntentText(input);
  if (/\b(pregnan|pregnancy|pregnant|maternity|maternal|obstetric|women|woman|female)\b/i.test(lower)) {
    return {
      key: "pregnancy",
      groupPattern: /women|pregnancy|maternal/i,
      title: "Pregnancy-aware lab comparison",
      adultColumn: "Adult female (not pregnant)",
      populationColumn: "Pregnant female"
    };
  }
  if (/\b(pediatric|peds|kid|kids|child|children|infant|newborn|neonate|teen|adolescent)\b/i.test(lower)) {
    const ageIntent = detectPediatricAgeIntent(input);
    return {
      key: "pediatric",
      groupPattern: /pediatric/i,
      title: ageIntent ? `Pediatric lab comparison - ${ageIntent.label}` : "Pediatric lab comparison",
      adultColumn: "Adult value",
      populationColumn: pediatricAgeLabel(ageIntent),
      ageIntent
    };
  }
  if (/\b(geriatric|older adult|older adults|elderly|senior|aging)\b/i.test(lower)) {
    return {
      key: "geriatric",
      groupPattern: /geriatric/i,
      title: "Geriatric lab interpretation comparison",
      adultColumn: "Adult value",
      populationColumn: "Older-adult interpretation"
    };
  }
  return null;
}

function splitPopulationRange(range = "", targetKey = "", target = {}) {
  const text = safeText(range);
  if (!text) {
    return { adult: "Use facility adult reference.", population: "Use the population-specific reference." };
  }
  if (targetKey === "pregnancy") {
    const parts = text.split(";").map((part) => part.trim()).filter(Boolean);
    const adult = parts.find((part) => /\badult|female|nonpregnant/i.test(part)) || parts[0] || text;
    const populationParts = parts.filter((part) => (
      part !== adult
      && /\bpregnan|trimester|gestational|rh negative|antibody|hypertension|preeclampsia|hellp|severe-feature|proteinuria|protein\/creatinine|platelet|creatinine|hgb|hct|hemoglobin|hematocrit|anemia|lft|ast|alt/i.test(part)
    ));
    const population = readableListText(populationParts)
      || readableListText(parts.filter((part) => part !== adult))
      || text;
    return { adult, population };
  }
  if (targetKey === "pediatric") {
    const ageSpecific = bestPediatricRangeSegmentForAge(text, target.ageIntent);
    return {
      adult: "Adult memory is not the reference for pediatric labs.",
      population: ageSpecific ? `${target.ageIntent?.label || "Requested age"}: ${ageSpecific}` : text
    };
  }
  if (targetKey === "geriatric") {
    return {
      adult: text.split(";")[0]?.trim() || "Adult reference range may still print on the lab report.",
      population: text
    };
  }
  return { adult: text, population: text };
}

function isUsefulComparisonRow(row = {}, targetKey = "") {
  const adult = normalizePharmText(row.adult);
  const population = normalizePharmText(row.population);
  if (!row.lab || !adult || !population) {
    return false;
  }
  if (targetKey === "pregnancy" && adult === population) {
    return false;
  }
  return true;
}

function offlineComparisonSummary(target = {}, rows = []) {
  if (target.key === "pregnancy") {
    const names = rows.map((row) => normalizePharmText(row.lab));
    const pregnancyParts = [];
    if (names.some((name) => name.includes("hemoglobin") || name.includes("hematocrit"))) {
      pregnancyParts.push("hemoglobin and hematocrit often run lower from hemodilution");
    }
    if (names.some((name) => name.includes("creatinine"))) {
      pregnancyParts.push("creatinine should run lower because GFR rises, so >=1.0 mg/dL deserves attention and >1.1 mg/dL is a severe-feature threshold");
    }
    if (names.some((name) => name.includes("platelet"))) {
      pregnancyParts.push("platelets may mildly drop to 100,000-149,000/mm3, but <100,000/mm3 with hypertension, RUQ pain, headache, or LFT elevation is preeclampsia/HELLP thinking");
    }
    if (names.some((name) => name.includes("urine protein"))) {
      pregnancyParts.push("proteinuria becomes significant at >=300 mg/24 hr or protein/creatinine ratio >=0.3");
    }
    return `Pregnancy usually shifts labs toward lower **hemoglobin and hematocrit**, lower **creatinine**, and sometimes mildly lower **platelets**. The danger pattern is not one isolated number; it is **hypertension plus platelets <100,000/mm3, elevated LFTs, RUQ pain, headache/vision changes, creatinine >1.1 mg/dL, or proteinuria >=300 mg/24 hr**. ${readableListText(pregnancyParts)}`;
  }
  if (target.key === "pediatric") {
    const agePhrase = target.ageIntent ? ` For **${target.ageIntent.label}**, use the matching age band first, then trend the child against symptoms, hydration, perfusion, infection cues, and the printed facility range.` : "";
    return `Pediatric interpretation is age-specific. Do not force adult ranges onto infants, children, or adolescents.${agePhrase}`;
  }
  if (target.key === "geriatric") {
    return "Older adults may have normal-looking lab numbers while reserve is low. Trend the value, medication risk, hydration, kidney function, and mental-status or fall changes.";
  }
  return "Use comparison ranges as pattern recognition, then verify the printed facility reference range and the client's clinical picture.";
}

function makeOfflineLabComparisonResponse(input = "") {
  if (!wantsOfflineLabComparison(input)) return "";
  const target = offlineLabComparisonTarget(input);
  if (!target) return "";
  const group = pharmPopulationLabRanges.find((candidate) => target.groupPattern.test(safeText(candidate.group)));
  if (!group?.ranges?.length) return "";

  const sourceRanges = target.key === "pediatric" && target.ageIntent
    ? group.ranges.filter((lab) => pediatricLabMatchesRequestedAge(lab, target.ageIntent))
    : group.ranges;

  const rows = sourceRanges.map((lab) => {
    const split = splitPopulationRange(lab.range, target.key, target);
    return {
      lab: safeText(lab.name),
      adult: split.adult,
      population: split.population,
      why: safeText(lab.why)
    };
  }).filter((row) => isUsefulComparisonRow(row, target.key)).slice(0, 9);
  if (!rows.length) return "";

  return {
    type: "offline-comparison",
    title: target.title,
    intro: "",
    columns: {
      adult: target.adultColumn,
      population: target.populationColumn
    },
    rows,
    summary: offlineComparisonSummary(target, rows),
    note: safeText(group.note) || "Ranges vary by facility and client context. Use these values as NCLEX study anchors, then verify the printed reference range in real care.",
    closing: target.key === "pregnancy"
      ? "**NCLEX essential:** pregnancy changes interpretation. A value that looks normal for a nonpregnant adult can still be concerning when pregnancy physiology should move the baseline."
      : "**NCLEX essential:** population-specific ranges change what counts as expected versus concerning."
  };
}

function offlineLookupIntent(input = "") {
  return wantsOfflinePharmLookup(input)
    || wantsOfflinePathologyLookup(input)
    || wantsOfflineHolisticLookup(input)
    || wantsSpecialtyReference(input)
    || looksLikeDescriptionLookupQuery(input)
    || /\b(open|show|find|search|look up|lookup|encyclopedia|database|reference|range|normal value|normal range|what is|what'?s|tell me about|used for|example|examples|class|contraindication|contraindications|interaction|interactions|black box|boxed warning|side effects?|adverse effects?|signs|symptoms|treatment|diagnostic|diagnostics|etiology|pathology|procedure|test|height|weight|growth|percentile|trimester)\b/i.test(input);
}

function offlineLookupIsDirectEnough(input = "", candidate = {}) {
  if (candidate?.identitySuggestionOnly === true
    || candidate?.phoneticMatch === true
    || (candidate?.clinicalClueMatch === true && candidate?.mayAutoOpen !== true)) {
    return false;
  }
  const cleanInput = normalizePharmText(input);
  const cleanLabel = normalizePharmText(offlineLookupEntityLabel(candidate));
  const lookupInput = normalizeOfflineLookupText(input);
  const lookupLabel = normalizeOfflineLookupText(offlineLookupEntityLabel(candidate), { dropLookupWords: false });
  if ((!cleanInput && !lookupInput) || (!cleanLabel && !lookupLabel)) {
    return false;
  }
  const candidateTerms = candidate.type === "reference"
    ? clinicalReferencePrimaryIdentityTerms(candidate.item)
    : candidate.type === "lab"
      ? pharmLabTerms(candidate.item)
      : candidate.type === "pathology"
        ? pathologyIdentityTermsForEntry(candidate.item)
        : candidate.type === "holistic"
          ? [candidate.item?.name, ...(candidate.item?.aliases || [])].map((term) => normalizePharmText(term)).filter(Boolean)
          : candidate.type === "drug"
            ? pharmIdentityTermsForEntry(candidate.item)
            : [];
  const aliasDirectMatch = candidateTerms
    .filter((term) => term && (term.split(" ").length >= 2 || term.length >= 6))
    .some((term) => cleanInput.includes(term) || lookupInput.includes(term) || term.includes(cleanInput) || term.includes(lookupInput));
  const descriptionScore = scoreOfflineDescriptionForCandidate(candidate, input);
  return candidate.score >= 90
    || descriptionScore >= 96
    || aliasDirectMatch
    || (cleanInput && cleanLabel && (cleanInput === cleanLabel || cleanLabel.includes(cleanInput)))
    || (lookupInput && lookupLabel && (lookupInput === lookupLabel || lookupLabel.includes(lookupInput)));
}

function shouldAutoRouteToOfflineLookup(input = "", candidate = {}) {
  if (!candidate
    || candidate.ambiguousIdentity === true
    || candidate.identitySuggestionOnly === true
    || candidate.phoneticMatch === true
    || (candidate.clinicalClueMatch === true && candidate.mayAutoOpen !== true)
    || shouldUseAiForUserRequest(input)) {
    return false;
  }
  const descriptionScore = scoreOfflineDescriptionForCandidate(candidate, input);
  return offlineLookupIsDirectEnough(input, candidate)
    && (isConciseOfflineLookupQuery(input) || offlineLookupIntent(input) || descriptionScore >= 96);
}

function looksLikeBackendUnavailableText(text = "") {
  return /cannot reach|server is running|same wi-fi|try again|refresh after the local ANI server|failed to fetch/i.test(String(text));
}

function makeOfflineDidYouMean(candidate = {}) {
  const label = offlineLookupEntityLabel(candidate);
  const kind = offlineLookupEntityKind(candidate);
  return `Did you mean **${label}** (${kind})? If yes, say **yes** and I will open that entry. If not, say **no** and I will try the next closest match.`;
}

function makeOfflineAmbiguityPrompt(candidates = []) {
  const seen = new Set();
  const choices = (candidates || []).map((candidate) => ({
    label: offlineLookupEntityLabel(candidate),
    kind: offlineLookupEntityKind(candidate)
  })).filter(({ label }) => {
    const key = normalizePharmText(label);
    if (!key || seen.has(key)) return false;
    seen.add(key);
    return true;
  }).slice(0, 8);
  return choices.length
    ? `I found more than one encyclopedia meaning for that wording: ${choices.map(({ label, kind }) => `**${label}** (${kind})`).join(" or ")}. Say which one you mean so I do not open the wrong card.`
    : "I found more than one close encyclopedia match. Add one more specific word so I do not open the wrong card.";
}

function clearPendingOfflineLookup() {
  pendingOfflineLookupSuggestions = [];
  pendingOfflineLookupContext = null;
}

function beginPendingOfflineLookup(input = "", candidates = [], options = {}) {
  pendingOfflineLookupSuggestions = Array.isArray(candidates) ? candidates.slice() : [];
  pendingOfflineLookupContext = pendingOfflineLookupSuggestions.length
    ? {
      originalQuery: safeText(input).trim().slice(0, 180),
      promptCount: 1,
      ambiguous: options.ambiguous === true
    }
    : null;
  return pendingOfflineLookupSuggestions;
}

function missingOfflineContentResponse(query = "") {
  const originalQuery = safeText(query).trim().slice(0, 180) || "that topic";
  clearPendingOfflineLookup();
  const runtime = aniFeedbackRuntime();
  if (!offlineMissQueuedForCurrentMessage && runtime?.queueSearchMiss) {
    offlineMissQueuedForCurrentMessage = true;
    Promise.resolve(runtime.queueSearchMiss({
      query: originalQuery,
      trigger: "entered",
      entered: true,
      stable: false,
      stableForMs: 0,
      explicitZeroResults: true,
      totalResults: 0,
      resultCounts: {
        drugs: 0,
        labs: 0,
        pathology: 0,
        references: 0,
        holistic: 0,
        warnings: 0,
        procedures: 0,
        "search-miss": 0
      },
      isSearchMode: true,
      renderComplete: true,
      requestGenerationMatches: true,
      transient: false,
      isComposing: false,
      favoritesOnly: false,
      tinyPhoneSearch: false,
      categoryOnly: false,
      browseMode: false,
      correctedQuery: "",
      phoneticQuery: "",
      unmatchedClues: []
    })).catch(() => {});
  }
  return {
    type: "missing-content",
    query: originalQuery,
    text: `I am not sure ANI has a reviewed encyclopedia card for **${originalQuery}** yet. I do not want to guess. Would you like to report this missing topic so it can be evaluated?`
  };
}

function handleOfflineLookupFlow(input = "", options = {}) {
  const force = Boolean(options.force);
  const allowPrompt = options.allowPrompt !== false;
  const trimmed = input.trim();
  if (pendingOfflineLookupSuggestions.length && isOfflineLookupConfirmation(trimmed)) {
    if (pendingOfflineLookupSuggestions.some((candidate) => candidate?.ambiguousIdentity === true)) {
      pendingOfflineLookupContext = pendingOfflineLookupContext || {
        originalQuery: trimmed,
        promptCount: 1,
        ambiguous: true
      };
      if (pendingOfflineLookupContext.promptCount >= 2) {
        return missingOfflineContentResponse(pendingOfflineLookupContext.originalQuery);
      }
      pendingOfflineLookupContext.promptCount += 1;
      return makeOfflineAmbiguityPrompt(pendingOfflineLookupSuggestions);
    }
    const candidate = pendingOfflineLookupSuggestions[0];
    clearPendingOfflineLookup();
    rememberOfflineLookupTarget(candidate, trimmed);
    return {
      type: "pharm-database",
      query: offlineLookupQuery(candidate),
      detailType: candidate.type,
      openDetail: true,
      targetCandidate: { type: candidate.type, item: candidate.item },
      highlightQuery: offlineLookupEntityLabel(candidate),
      preface: `Yes. Opening **${offlineLookupEntityLabel(candidate)}** in the clinical reference.`
    };
  }

  if (pendingOfflineLookupSuggestions.length && isOfflineLookupRejectAll(trimmed)) {
    return missingOfflineContentResponse(pendingOfflineLookupContext?.originalQuery || trimmed);
  }

  if (pendingOfflineLookupSuggestions.length && isOfflineLookupRejection(trimmed)) {
    const originalQuery = pendingOfflineLookupContext?.originalQuery || trimmed;
    pendingOfflineLookupSuggestions.shift();
    pendingOfflineLookupContext = pendingOfflineLookupContext || {
      originalQuery,
      promptCount: 1,
      ambiguous: false
    };
    if (pendingOfflineLookupSuggestions.length && pendingOfflineLookupContext.promptCount < 2) {
      pendingOfflineLookupContext.promptCount += 1;
      return makeOfflineDidYouMean(pendingOfflineLookupSuggestions[0]);
    }
    return missingOfflineContentResponse(originalQuery);
  }

  if (!pendingOfflineLookupSuggestions.length
    && (isOfflineLookupConfirmation(trimmed)
      || isOfflineLookupRejection(trimmed)
      || isOfflineLookupRejectAll(trimmed))) {
    clearPendingOfflineLookup();
    return "";
  }

  if (pendingOfflineLookupSuggestions.length) {
    clearPendingOfflineLookup();
  }
  const normalizedHeartBlockQuery = normalizePharmText(trimmed);
  if (["heart block", "av block", "atrioventricular block"].includes(normalizedHeartBlockQuery)) {
    const item = pathologyDiseases.find((entry) => normalizePharmText(entry?.name) === "heart blocks");
    if (item) {
      const candidate = { type: "pathology", item, score: 4000, exactIdentity: true };
      pendingOfflineLookupSuggestions = [];
      rememberOfflineLookupTarget(candidate, trimmed);
      return options.preferDatabaseRedirect
        ? offlineLookupDatabaseRedirect(candidate, trimmed)
        : offlineLookupDirectResponse(candidate, trimmed);
    }
  }
  const familyCandidates = responsiveEncyclopediaFamilyCandidates(trimmed);
  if (familyCandidates.length) {
    pendingOfflineLookupSuggestions = [];
    if (options.preferDatabaseRedirect) {
      return {
        type: "pharm-database",
        query: "heart blocks",
        detailType: "pathology",
        openDetail: false
      };
    }
    return `I found the heart-block family: ${familyCandidates.map((candidate) => `**${offlineLookupEntityLabel(candidate)}**`).join(", ")}. Open the encyclopedia results to choose the exact card.`;
  }
  const reviewedResolution = fastReviewedSearchResolution(trimmed);
  if (reviewedResolution?.ambiguousIdentity === true) {
    beginPendingOfflineLookup(trimmed, reviewedResolution.ambiguityCandidates || [], { ambiguous: true });
    return makeOfflineAmbiguityPrompt(pendingOfflineLookupSuggestions);
  }
  if (reviewedResolution) {
    pendingOfflineLookupSuggestions = [];
    rememberOfflineLookupTarget(reviewedResolution, trimmed);
    if (options.preferDatabaseRedirect) {
      return offlineLookupDatabaseRedirect(reviewedResolution, trimmed);
    }
    return offlineLookupDirectResponse(reviewedResolution, trimmed);
  }
  const fastDiabetesOwner = wave41DiabetesPathologyIntentSuggestion(trimmed);
  if (fastDiabetesOwner) {
    pendingOfflineLookupSuggestions = [];
    rememberOfflineLookupTarget(fastDiabetesOwner, trimmed);
    if (options.preferDatabaseRedirect) {
      return offlineLookupDatabaseRedirect(fastDiabetesOwner, trimmed);
    }
    const label = offlineLookupEntityLabel(fastDiabetesOwner);
    const brief = offlineCandidateDefinitionBrief(fastDiabetesOwner);
    return [
      `**${label}**`,
      brief,
      fastDiabetesOwner.item?.nursingPriorities?.length
        ? `**Clinical focus:** ${pathologyListText(fastDiabetesOwner.item.nursingPriorities.slice(0, 2))}`
        : ""
    ].filter(Boolean).join("\n\n");
  }
  const fastNewbornScreenOwner = fastNewbornPkuScreenReferenceSuggestion(trimmed);
  if (fastNewbornScreenOwner) {
    pendingOfflineLookupSuggestions = [];
    rememberOfflineLookupTarget(fastNewbornScreenOwner, trimmed);
    if (options.preferDatabaseRedirect) {
      return offlineLookupDatabaseRedirect(fastNewbornScreenOwner, trimmed);
    }
    return makeOfflineClinicalReferenceResponseFromEntry(fastNewbornScreenOwner.item, trimmed)
      || offlineLookupDirectResponse(fastNewbornScreenOwner, trimmed);
  }
  if (normalizedBareFollowupText(trimmed) === "show me") {
    pendingOfflineLookupSuggestions = [];
    const remembered = recentOfflineLookupTarget();
    if (remembered) {
      if (options.preferDatabaseRedirect) {
        return offlineLookupDatabaseRedirect(remembered, lastOfflineLookupTarget?.sourceInput || lastOfflineLookupTarget?.label || input);
      }
      return offlineLookupDirectResponse(remembered, lastOfflineLookupTarget?.sourceInput || input);
    }
    return "Tell me what you want me to show, like **show hematocrit**, **open amiodarone**, or **show beta-1 blockers**.";
  }

  if (isBareOfflineLookupFollowup(trimmed)) {
    const remembered = recentOfflineLookupTarget();
    if (remembered) {
      pendingOfflineLookupSuggestions = [];
      if (options.preferDatabaseRedirect) {
        return offlineLookupDatabaseRedirect(remembered, lastOfflineLookupTarget?.sourceInput || lastOfflineLookupTarget?.label || input);
      }
      return offlineLookupDirectResponse(remembered, lastOfflineLookupTarget?.sourceInput || input);
    }
    return allowPrompt
      ? "Tell me what you want me to show, like **show hematocrit**, **open amiodarone**, or **show beta-1 blockers**."
      : "";
  }

  if (wantsBinaryRelationshipAnswer(input)
    && !hasCuratedOfflineBinaryRelationshipAnswer(input)) {
    return "";
  }

  const earlyNamedReference = !options.preferDatabaseRedirect
    ? directlyNamedClinicalReferenceCandidate(input)
    : null;
  if (earlyNamedReference) {
    const earlyNamedMeaningQuestion = /\b(positive|negative|mean|means|meaning|interpret|interpretation)\b/i
      .test(normalizeIntentText(input));
    const earlyNamedSmartAnswer = earlyNamedMeaningQuestion
      ? makeOfflineSmartDatabaseAnswer(input)
      : "";
    const earlyNamedNeedsFullMeaningAnswer = earlyNamedMeaningQuestion
      && normalizePharmText(clinicalReferenceDisplayName(earlyNamedReference.item)) === "mcburney point tenderness";
    const earlyNamedAnswer = earlyNamedSmartAnswer
      || makeOfflineReboundTendernessAnswer(input)
      || (earlyNamedNeedsFullMeaningAnswer
        ? makeOfflineClinicalReferenceResponseFromEntry(earlyNamedReference.item, input)
        : (makeOfflineSegmentAnswer(input)
          || makeOfflineClinicalReferenceResponseFromEntry(earlyNamedReference.item, input)));
    if (earlyNamedAnswer) {
      pendingOfflineLookupSuggestions = [];
      return earlyNamedAnswer;
    }
  }

  const explicitPracticeGeneration = /\b(practice\s+questions?|test\s+questions?|quiz(?:zes)?|generate|create|make|write)\b/i.test(normalizeIntentText(input));
  if (!options.preferDatabaseRedirect && wantsOfflineSmartDatabaseAnswer(input) && !explicitPracticeGeneration) {
    const earlySmartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(input);
    if (earlySmartDatabaseAnswer) {
      pendingOfflineLookupSuggestions = [];
      return earlySmartDatabaseAnswer;
    }
  }

  // Exact card-plus-field questions are answered from that card's authored
  // field before description routing or a broad card redirect. The segment
  // resolver rejects personal clinical narratives and ambiguous identities,
  // so this cannot turn a current-care statement into an encyclopedia answer.
  const exactQuestionFieldResponse = makeOfflineSegmentResponse(input);
  if (exactQuestionFieldResponse) {
    pendingOfflineLookupSuggestions = [];
    return exactQuestionFieldResponse.text;
  }

  if (wantsAiGeneratedStudyWork(input)) {
    const explicitNavigationCue = /\b(open|show|find|search|look up|lookup|encyclopedia|database|reference)\b/i.test(input)
      && !/\b(question|questions|quiz|quizzes|practice problem|practice item|test question|diagram|draw|flowchart|concept map|illustrat|visuali[sz]e|picture|image)\b/i.test(normalizeIntentText(input));
    const navigationTop = explicitNavigationCue ? offlineLookupSuggestions(input)[0] : null;
    if (!navigationTop || !offlineLookupIsDirectEnough(input, navigationTop)) {
      return "";
    }
  }

  if (wantsOfflineListAiExpansionFallback(input)) {
    return "";
  }

  const ckdStageAnswer = makeOfflineCkdStageResponse(input);
  if (ckdStageAnswer) {
    pendingOfflineLookupSuggestions = [];
    return ckdStageAnswer;
  }

  const gestationalWeightGainRedirect = options.preferDatabaseRedirect
    && /\b(open|show|find|search|look up|lookup|encyclopedia|database|reference)\b/i.test(input)
    ? offlineGestationalWeightGainRedirect(input)
    : "";
  if (gestationalWeightGainRedirect) {
    pendingOfflineLookupSuggestions = [];
    return gestationalWeightGainRedirect;
  }

  const insulinActionProfileRedirect = options.preferDatabaseRedirect
    ? offlineInsulinActionProfileReferenceCandidate(input)
    : null;
  if (insulinActionProfileRedirect) {
    pendingOfflineLookupSuggestions = [];
    return offlineLookupDatabaseRedirect(insulinActionProfileRedirect, input);
  }

  const earlyResolvedLookupCanRedirect = options.preferDatabaseRedirect
    && !wantsLecture(input)
    && !wantsAiDepthTeaching(input)
    && !wantsAiGeneratedStudyWork(input)
    && !/\b(question|questions|quiz|quizzes|practice problem|practice item|test question|diagram|draw|flowchart|concept map|illustrat|visuali[sz]e|picture|image)\b/i.test(normalizeIntentText(input));
  const earlyResolvedLookupTop = earlyResolvedLookupCanRedirect
    ? offlineLookupSuggestions(input)[0]
    : null;
  const earlyResolvedLookupIsDirect = (earlyResolvedLookupTop?.nearIdentity === true
    || (earlyResolvedLookupTop?.exactIdentity === true && earlyResolvedLookupTop.type === "reference"))
    && earlyResolvedLookupTop?.ambiguousIdentity !== true;
  if (earlyResolvedLookupIsDirect && earlyResolvedLookupTop.score >= 2450) {
    pendingOfflineLookupSuggestions = [];
    return offlineLookupDatabaseRedirect(earlyResolvedLookupTop, input);
  }

  // frontier-wave14-specific-drug-route-before-concept-synthesis
  if (options.preferDatabaseRedirect) {
    const earlySpecificDrugClueMatch = highYieldDrugClueMatch(input);
    if (earlySpecificDrugClueMatch) {
      pendingOfflineLookupSuggestions = [];
      return offlineLookupDatabaseRedirect({
        type: "drug",
        item: earlySpecificDrugClueMatch,
        score: 2550 + pharmIdentityPreferenceScore(earlySpecificDrugClueMatch)
      }, input);
    }
  }

  const conceptSynthesisRedirect = options.preferDatabaseRedirect && offlineConceptNavigationCue(input)
    ? offlineConceptSynthesisRedirect(input)
    : "";
  if (conceptSynthesisRedirect) {
    pendingOfflineLookupSuggestions = [];
    return conceptSynthesisRedirect;
  }

  const conceptSynthesisAnswer = makeOfflineConceptSynthesisResponse(input);
  if (conceptSynthesisAnswer) {
    pendingOfflineLookupSuggestions = [];
    return conceptSynthesisAnswer;
  }

  const smartDatabaseAnswer = options.preferDatabaseRedirect ? "" : makeOfflineSmartDatabaseAnswer(input);
  if (smartDatabaseAnswer) {
    pendingOfflineLookupSuggestions = [];
    return smartDatabaseAnswer;
  }

  if (options.preferDatabaseRedirect) {
    const specificDrugClueMatch = highYieldDrugClueMatch(input);
    if (specificDrugClueMatch) {
      pendingOfflineLookupSuggestions = [];
      return offlineLookupDatabaseRedirect({
        type: "drug",
        item: specificDrugClueMatch,
        score: 2550 + pharmIdentityPreferenceScore(specificDrugClueMatch)
      }, input);
    }
    const classRedirect = medicationClassDatabaseRedirect(input);
    if (classRedirect) {
      pendingOfflineLookupSuggestions = [];
      return classRedirect;
    }
    const earlyTop = offlineLookupSuggestions(input)[0];
    const earlyTopCanRedirect = !wantsLecture(input)
      && !wantsAiDepthTeaching(input)
      && !wantsAiGeneratedStudyWork(input)
      && !/\b(question|questions|quiz|quizzes|practice problem|test question|diagram|draw|flowchart|concept map)\b/i.test(normalizeIntentText(input));
    if (earlyTopCanRedirect
      && earlyTop
      && earlyTop.score >= 2450
      && shouldAutoRouteToOfflineLookup(input, earlyTop)) {
      pendingOfflineLookupSuggestions = [];
      return offlineLookupDatabaseRedirect(earlyTop, input);
    }
  }

  const offlineListAnswer = makeOfflineListResponse(input);
  if (offlineListAnswer) {
    pendingOfflineLookupSuggestions = [];
    return offlineListAnswer;
  }

  const explicitEncyclopediaNavigation = /\b(open|show|find|search|look up|lookup|encyclopedia|database|reference)\b/i.test(input);
  if ((wantsLecture(input) || wantsAiDepthTeaching(input)) && !explicitEncyclopediaNavigation) {
    return "";
  }

  const suggestions = offlineLookupSuggestions(input);
  if (!suggestions.length) {
    return "";
  }

  if (!options.preferDatabaseRedirect && wantsAnswerInChatFromReference(input)) {
    const offlineAnswer = makeOfflineReferenceAnswerInChat(input);
    if (offlineAnswer) {
      pendingOfflineLookupSuggestions = [];
      return offlineAnswer;
    }
    return "";
  }

  const top = suggestions[0];
  if (top?.ambiguousIdentity === true) {
    beginPendingOfflineLookup(trimmed, suggestions, { ambiguous: true });
    return makeOfflineAmbiguityPrompt(suggestions);
  }
  const directEnough = offlineLookupIsDirectEnough(input, top);
  const hasLookupIntent = offlineLookupIntent(input);
  const simpleOfflineLookup = shouldAutoRouteToOfflineLookup(input, top);
  const allowOfflinePrompt = !shouldUseAiForUserRequest(input)
    && (isConciseOfflineLookupQuery(input) || hasLookupIntent);

  if (directEnough && (force || hasLookupIntent || simpleOfflineLookup)) {
    pendingOfflineLookupSuggestions = [];
    if (options.preferDatabaseRedirect) {
      return offlineLookupDatabaseRedirect(top, input);
    }
    return offlineLookupDirectResponse(top, input);
  }

  if (allowPrompt && (force || shouldUseOfflineLookupCore() || allowOfflinePrompt)) {
    beginPendingOfflineLookup(trimmed, suggestions);
    return makeOfflineDidYouMean(top);
  }

  return "";
}

function hasExplicitTaskRequest(input = "") {
  if (isContextRepairMessage(input)) {
    return false;
  }

  const lower = normalizeIntentText(input);
  return wantsTopicShift(input)
    || wantsTestFormatList(input)
    || wantsGenericPracticeProblem(input)
    || wantsClassSpecificExam(input)
    || wantsRepeatReplacement(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || asksForQuestionNow(input)
    || wantsDifficultyChange(input)
    || wantsLecture(input)
    || wantsRapidFire(input)
    || wantsBreakdown(input)
    || wantsClinicalExplanation(input)
    || /\b(quiz|test|nclex|practice|ask me)\b/i.test(lower)
    || /\b(question|questions|item|items)\b.{0,50}\b(nclex|practice|quiz|hard|another|next|generate|create|make|write)\b/i.test(lower)
    || /\b(generate|create|make|write|give)\b.{0,50}\b(question|questions|item|items)\b/i.test(lower);
}

function hasQuestionShape(input = "") {
  const lower = normalizeIntentText(input);
  return /\?/.test(input)
    || /^(who|what|when|where|why|how|can|could|would|should|do|does|did|is|are|am)\b/i.test(lower);
}

function analyzeConversationIntent(input = "", hasTaskRequest = false) {
  const trimmed = input.trim();
  const lower = normalizeIntentText(trimmed);
  const clinical = hasClinicalSignal(trimmed);
  const correction = isContextRepairMessage(trimmed)
    || /\b(not what i asked|didn'?t answer|did not answer|doesn'?t answer|does not answer|wasn'?t what i asked|was not what i asked|you'?re not listening|you are not listening|listen to what i|too rigid|scripted|robotic|brush(?:ed)?\s+(that|it|me)\s+off|ignored what i said|ignored me|ignored that|ignored it|off script|more natural|more conversational)\b/i.test(trimmed);
  const gratitude = /^\s*(thanks|thank you|ty|appreciate it|that helped|that makes sense|got it|okay|ok|cool|perfect|nice|beautiful|great)\b/i.test(trimmed);
  const emotional = /\b(i'?m|i am|im|feeling|feel)\s+(lost|confused|overwhelmed|stressed|scared|tired|burned out|burnt out|frustrated|anxious|cooked|fried|defeated)\b/i.test(trimmed)
    || /\b(this is hard|i hate this|my brain is mush|i can'?t think|i cannot think|i give up)\b/i.test(trimmed);
  const greeting = /\b(hi|hello|hey|yo|good morning|good afternoon|good evening|what'?s up|whats up|vibe check)\b/i.test(trimmed);
  const meta = /\b(what can you do|how do i use you|how should i use you|what are my options|help menu|how does this work|what do you remember|do you remember|what can i ask)\b/i.test(trimmed);
  const uncertainty = /\b(not sure|unsure|maybe|i guess|i think|leaning|between|stuck|confused|doubt|is it|would it be|could it be|am i wrong|does that count)\b/i.test(trimmed);
  const playful = wantsPlayfulBanter(trimmed)
    || (!clinical && /\b(lol|haha|lmao|hellooo+|hello+ world|are you alive|say hi|hype me up|be dramatic|roast me gently)\b/i.test(trimmed));
  const smallTalk = wantsSmallTalk(trimmed, hasTaskRequest);
  const casualQuestion = !clinical && hasQuestionShape(trimmed);
  const shortAmbiguous = !clinical
    && !hasTaskRequest
    && trimmed.length > 0
    && trimmed.length <= 90
    && !smallTalk
    && !playful
    && !gratitude
    && !meta;

  return {
    correction,
    gratitude,
    emotional,
    greeting,
    meta,
    uncertainty,
    playful,
    smallTalk,
    casualQuestion,
    shortAmbiguous,
    clinical,
    hasTaskRequest
  };
}

function conversationStyleHint(input = "") {
  const hasTaskRequest = hasExplicitTaskRequest(input);
  const intent = analyzeConversationIntent(input, hasTaskRequest);
  const labels = [];

  if (intent.correction) labels.push("student is correcting ANI's responsiveness");
  if (intent.emotional) labels.push("student may need reassurance before instruction");
  if (intent.uncertainty) labels.push("student is uncertain; coach before grading");
  if (intent.playful || intent.greeting || intent.smallTalk) labels.push("student is using casual/social language");
  if (intent.casualQuestion && !intent.clinical) labels.push("regular nonclinical question");
  if (intent.hasTaskRequest) labels.push("also fulfill the explicit learning task");

  return labels.length
    ? labels.join("; ")
    : "answer naturally and directly";
}

function makeCasualQuestionResponse(input = "") {
  const lower = input.toLowerCase();

  if (/\b(proud of me|you proud|are you proud|nic+e|i did it|i got it)\b/i.test(lower)) {
    return `Yes. I am proud of you.\n\nAnd I mean that in the useful way: you are noticing when something feels off, asking for better practice, and pushing the app to teach like a real instructor. That is exactly the kind of learner who gets dangerous in the best clinical way.\n\nWe can keep sharpening the questions whenever you are ready.`;
  }

  if (/\b(can i ask|can we talk|can you talk|are you there|you there)\b/i.test(lower)) {
    return `Yes. Ask me normally. You do not have to phrase it like a command.\n\nIf it is nursing, I will go clinical. If it is just a human little side quest, I can answer that too.`;
  }

  if (/\b(are you real|are you human|who are you)\b/i.test(lower)) {
    return `I am ANI, your AI nursing instructor in this app. Not human, but I can still be warm, direct, and useful.\n\nYou can talk to me like a real tutor, not a menu.`;
  }

  if (/\b(how are you|how'?s it going|how you doing)\b/i.test(lower)) {
    return `I am good. Very awake, very ready to overexplain, and trying to earn my little lab coat.\n\nHow are you feeling about studying today?`;
  }

  if (/\b(should i study|do i have to study|motivate me|hype me up)\b/i.test(lower)) {
    return `Tiny honest answer: yes, but not in a punishment way.\n\nDo one clean rep. One question, one rationale, one thing you tighten. That counts. Momentum usually shows up after you start, not before.`;
  }

  if (/\b(favorite|do you like|would you rather|opinion|what do you think)\b/i.test(lower)) {
    return `My answer, in ANI terms: I can have a take without turning it into a whole lecture.\n\nI like things that make thinking feel less lonely: clear rationales, tiny pattern-recognition wins, and questions that make you go, "wait, I almost missed that."`;
  }

  return `That reads like a regular question, not an NCLEX command.\n\nGive me the angle you want: casual answer, nursing tie-in, or board-style explanation.`;
}

function makeAdaptiveConversationResponse(input = "", intent = analyzeConversationIntent(input), hasTaskRequest = false) {
  if (intent.correction && !hasTaskRequest) {
    return `You're right. That is exactly the behavior I need to fix: I should not grab the first familiar word and run a script.\n\nFrom here, I will read the whole input first, identify whether you are asking, joking, answering, correcting me, or just talking, and then respond to that directly. If there is a clinical task inside the message, I will still do it, but I will not skip the human part.`;
  }

  if (intent.meta && !hasTaskRequest) {
    return `You can talk to me normally. You do not need menu words.\n\nI can quiz you, explain a med or disease process, compare answer choices, lecture, make hard CJE cases, analyze screenshots when vision is connected, or just talk through the messy part of studying.\n\nA natural prompt is enough, like: "I keep mixing up DKA and HHS," "ask me something evil about neuro," or "I am confused about why potassium matters here."`;
  }

  if (intent.gratitude && !hasTaskRequest) {
    return `Of course. I am glad that helped.\n\nWe can keep going, slow down on the same point, or completely switch gears.`;
  }

  if (intent.emotional && !hasTaskRequest && !intent.clinical) {
    return `Let’s lower the chaos level.\n\nGive me the topic, or even just the part that feels messy, and I will break it into: what is happening, why it matters, what the nurse does, and what NCLEX is trying to trick you with.`;
  }

  if (intent.playful && !hasTaskRequest) {
    return makePlayfulBanterResponse(input);
  }

  if (wantsSolicitedAniThought(input) && !hasTaskRequest) {
    return makeSolicitedThoughtResponse(input);
  }

  if (intent.smallTalk && !hasTaskRequest) {
    return makeSmallTalkResponse(input);
  }

  if (intent.casualQuestion && !hasTaskRequest) {
    return makeCasualQuestionResponse(input);
  }

  if (intent.shortAmbiguous) {
    return `I’m not going to force that into a random nursing script.\n\nTell me what you want from it: casual answer, NCLEX connection, explanation, practice question, or just keep chatting.`;
  }

  return "";
}

function makeConversationalBridge(input = "", intent = analyzeConversationIntent(input), hasTaskRequest = false) {
  if (!hasTaskRequest) {
    return "";
  }

  if (intent.correction) {
    return "You're right, and I am adjusting the response style first. ";
  }

  if (intent.emotional) {
    return "I hear the stress in that. We will make it clean and usable. ";
  }

  if (intent.uncertainty && lastQuestion) {
    return "I hear the uncertainty, so I am not treating this like a confident final answer. ";
  }

  if (intent.playful || intent.greeting || intent.smallTalk) {
    return "Hey, I got you. ";
  }

  return "";
}

function applyConversationalBridge(response, bridge = "") {
  if (!bridge) {
    return response;
  }

  if (response?.type === "standard-question") {
    return {
      ...response,
      preface: [bridge.trim(), response.preface].filter(Boolean).join("\n\n")
    };
  }

  if (typeof response !== "string") {
    return response;
  }

  return `${bridge.trim()}\n\n${response}`;
}

function referencesActiveLearningContext(input = "") {
  if (!activeLearningContext?.kind && !lastQuestion) {
    return false;
  }

  return /\b(this|that|same|current|previous|last|case|problem|question|item|chart|stem|scenario|one|it)\b/i.test(normalizeIntentText(input));
}

function activeLearningItemFromContext() {
  if (activeLearningContext?.kind === "cje-case") {
    return cjeCaseBank.find((caseItem) => caseItem.id === activeLearningContext.id) || activeLearningContext || null;
  }

  if (activeLearningContext?.kind === "advanced-item") {
    return advancedItemBank.find((item) => item.id === activeLearningContext.id) || activeLearningContext || null;
  }

  if (activeLearningContext?.kind === "unfolding-case") {
    return unfoldingCaseBank.find((caseItem) => caseItem.id === activeLearningContext.id) || activeLearningContext || null;
  }

  if (activeLearningContext?.kind === "standard-question") {
    return lastQuestion || null;
  }

  return lastQuestion || null;
}

function wantsActiveLearningClarification(input = "") {
  const lower = normalizeIntentText(input);
  const asksFollowUp = /\b(why|how|what|explain|rationale|reason|ordered?|order|lab|labs|lactate|map|troponin|urine|output|culture|provider|prescription|mean|means)\b/i.test(lower);
  const referencesContext = referencesActiveLearningContext(lower)
    || /\b(case|chart|stem|scenario|problem|question|item|one)\b/i.test(lower);

  return Boolean(activeLearningItemFromContext())
    && referencesContext
    && asksFollowUp;
}

function lactateExplanationForActiveLearning(item = {}) {
  const itemText = `${item.id || ""} ${item.title || ""} ${item.stem || ""} ${item.client || ""} ${item.rationale?.condition || ""}`.toLowerCase();
  const caseSpecific = /cardiogenic|myocardial|infarction|pulmonary edema|pump failure/.test(itemText)
    ? "In that cardiogenic-shock style case, the concern is low cardiac output. The heart is not moving enough oxygenated blood forward, so tissues can become underperfused even before one single lab tells the whole story."
    : /sepsis|septic|pneumonia|infection/.test(itemText)
      ? "In that septic-shock style case, the concern is distributive shock: vasodilation, capillary leak, and impaired oxygen use can leave tissues underperfused even when the client has already received fluids."
      : "In that case, lactate is a perfusion clue. It helps you decide whether oxygen delivery and tissue use are keeping up with demand.";

  return `Yes, let me answer the lactate part first because that was the real question inside your message.\n\nLactate was ordered to assess tissue hypoperfusion and severity of shock. When cells are not getting enough usable oxygen, or cannot use oxygen well enough, they shift toward anaerobic metabolism and lactate rises. It is not a sepsis-only lab.\n\n${caseSpecific}\n\nNCLEX angle: trend lactate with MAP, mental status, urine output, skin temperature/perfusion, capillary refill, creatinine, oxygenation, and response to treatment. A rising or persistently high lactate says, "the body is still not perfusing well enough," even if one vital sign looks less dramatic.\n\nTight detail: lactate is not the diagnosis by itself. It is a severity-and-response marker. In shock questions, it helps you decide whether the client is improving, still compensating, or sliding into worse perfusion.`;
}

function activeLearningFollowUpExplanation(input = "", item = activeLearningItemFromContext()) {
  const lower = normalizeIntentText(input);

  if (/\blactate\b/.test(lower)) {
    return lactateExplanationForActiveLearning(item);
  }

  if (/\bmap\b|mean arterial/.test(lower)) {
    return `Yes, let me answer the MAP part first.\n\nMAP is mean arterial pressure: the average pressure pushing blood through the organs. In shock, MAP matters because a client can have a blood pressure number that looks only "kind of low," while organ perfusion is already failing.\n\nNCLEX angle: MAP under about 65 mm Hg is a red flag for inadequate perfusion, especially when paired with altered mental status, low urine output, cool/mottled skin, rising lactate, chest pain, worsening oxygenation, or new dysrhythmia.\n\nDo not treat MAP as a memorized number only. Pair it with the trend and the client's organ signs.`;
  }

  if (/\btroponin\b|myocardial|infarction|\bmi\b/.test(lower)) {
    return `Yes, let me answer that piece before moving on.\n\nTroponin is ordered when myocardial injury is on the table. In a shock-style case with chest pain, ECG changes, pulmonary edema, hypotension, cool diaphoresis, or dysrhythmia, troponin helps support myocardial infarction as the cause of pump failure.\n\nNCLEX angle: troponin does not replace assessment. You still prioritize oxygenation, perfusion, rhythm, pain, hemodynamic stability, and escalation. The lab helps explain why the client is deteriorating.`;
  }

  if (/\burine|output|oliguria|kidney|renal\b/.test(lower)) {
    return `Yes, let me answer the urine-output piece first.\n\nUrine output is a bedside perfusion marker. If the kidneys are not getting enough blood flow, output drops. In shock questions, urine output below about 30 mL/hr is a major cue that perfusion is not adequate.\n\nNCLEX angle: low urine output plus altered mental status, low MAP, rising lactate, cool/mottled skin, or worsening respiratory status means the client is not stable. That beats routine teaching, comfort measures, and nonurgent documentation.`;
  }

  return `Yes, let me answer the follow-up first instead of bulldozing into a new question.\n\nFor the case we were just working on, the key is to connect the chart cue to the pathophysiology and then to the nursing priority. Do not treat the finding as trivia. Ask: does this cue show failing oxygenation, failing perfusion, neurologic decline, medication danger, infection progression, or failure to respond to treatment?\n\nNCLEX angle: the exam loves when a normal-looking detail becomes important because of context. Trends, response to interventions, and organ perfusion usually matter more than one isolated value.`;
}

function makeActiveLearningClarificationResponse(input = "") {
  if (!wantsActiveLearningClarification(input)) {
    return "";
  }

  const explanation = activeLearningFollowUpExplanation(input);
  const lower = normalizeIntentText(input);
  const alsoWantsQuestion = asksForQuestionNow(input) || /\b(another|next|new|different|more)\b.{0,40}\b(question|item|quiz|problem)\b/i.test(lower);

  if (!alsoWantsQuestion) {
    return explanation;
  }

  const topic = /\bshock|lactate|map|vasopressor|hypotension|perfusion\b/i.test(lower)
    ? "Complex Care shock"
    : activeLearningContext?.topic || currentTopic;
  const questionInput = `another ${inferDifficulty(input)} ${topic} NCLEX question`;
  const question = formatQuestion(nextQuestionData(questionInput), questionInput);

  return {
    ...question,
    preface: `${explanation}\n\nNow I will still honor the new-question part, but I am making it a fresh standard item instead of recycling the same chart:`
  };
}

function makeFreshActiveLearningChallenge(input = "") {
  const topic = activeLearningContext?.topic || currentTopic;
  const prompt = `${topic} ${input}`;

  if (activeLearningContext?.kind === "cje-case") {
    return makeCjeChallenge(prompt);
  }

  if (activeLearningContext?.kind === "unfolding-case") {
    return makeUnfoldingCaseChallenge(prompt);
  }

  if (activeLearningContext?.kind === "advanced-item") {
    return makeAdvancedItemChallenge(prompt);
  }

  return formatQuestion(nextQuestionData(`another ${topic} question`), input);
}

function makeContextAwareLearningResponse(input = "") {
  const lower = normalizeIntentText(input);
  const repeatComplaint = wantsRepeatReplacement(input);
  const unfoldRequest = /\b(unfold|continue|keep going|some more|next development|more of this case|develop this case)\b/i.test(lower);
  const wantsFresh = /\b(another|next|new|different|fresh|more)\b/i.test(lower)
    && /\b(problem|question|item|case|one)\b/i.test(lower);
  const explicitNewFormatRequest = asksForQuestionNow(input)
    && (shouldChooseQuestionTypeForUser(input) || wantsCjeChallenge(input) || wantsAdvancedItem(input) || wantsUnfoldingCase(input));

  if (explicitNewFormatRequest) {
    if (shouldChooseQuestionTypeForUser(input)) return makeSurpriseQuestionTypeChallenge(input);
    if (wantsUnfoldingCase(input)) return makeUnfoldingCaseChallenge(input);
    if (wantsAdvancedItem(input)) return makeAdvancedItemChallenge(input);
    if (wantsCjeChallenge(input)) return makeCjeChallenge(input);
  }

  if (!referencesActiveLearningContext(input) && !repeatComplaint && !unfoldRequest) {
    return "";
  }

  if (repeatComplaint) {
    if (activeLearningContext?.kind === "cje-case" || activeLearningContext?.kind === "unfolding-case") {
      return makeAdvancedItemChallenge(`${activeLearningContext.topic || currentTopic} different chart cue question`);
    }
    const fresh = makeFreshActiveLearningChallenge(`${input} different fresh`);
    if (fresh?.type === "standard-question") {
      return {
        ...fresh,
        preface: "You're right. That stem was not fresh enough."
      };
    }
    return fresh;
  }

  if (unfoldRequest) {
    const topic = activeLearningContext?.topic || currentTopic;
    return makeUnfoldingCaseChallenge(`${topic} unfolding case`);
  }

  if (wantsFresh) {
    return makeFreshActiveLearningChallenge(input);
  }

  return "";
}

function wantsPlayfulBanter(input = "") {
  const lower = input.toLowerCase();
  return /\bhey\s+ani\b/.test(lower)
    && (
      /hello+|helo+|hellooo+|world|hype|say hi|what'?s up|whats up|vibe check|are you alive|you there/.test(lower)
      || /!{1,}$/.test(input.trim())
    )
    && !/\b(question|quiz|nclex|lecture|explain|teach|med|drug|patho|rapid|practice|answer|rationale)\b/i.test(input);
}

function wantsSmallTalk(input = "", hasTaskRequest = false) {
  const trimmed = input.trim();

  if (!trimmed) {
    return false;
  }

  const casualSignal = /\b(hi|hello|hey|yo|good morning|good afternoon|good evening|what'?s up|whats up|how are you|how'?s it going|how you doing|vibe check|small talk|chat with me|talk to me|tell me something|random thought|what are you thinking|what have you been thinking|i'?m bored|im bored|bored|make me laugh|joke|be funny|favorite|opinion|what do you think|life|personality|say something|surprise me|curious question)\b/i.test(trimmed);
  const personalQuestion = /^(who|what|how|do|does|is|are)\b.{0,80}\b(you|your|think|feel|favorite|personality|up to)\b/i.test(trimmed)
    && !hasClinicalSignal(trimmed);
  const shortCasual = !hasClinicalSignal(trimmed)
    && trimmed.length <= 70
    && !/[?]/.test(trimmed)
    && !/\b(answer|rationale|option|choice|lab|vital|patient|client|nurse|nclex|quiz|question|practice|lecture|explain|teach)\b/i.test(trimmed);

  if (hasTaskRequest && !casualSignal) {
    return false;
  }

  return casualSignal || personalQuestion || shortCasual;
}

function wantsSolicitedAniThought(input = "") {
  return !hasClinicalSignal(input)
    && /\b(what are you thinking|what'?s on your mind|what have you been thinking|random medicine thought|random medical thought|medicine thought|medical thought|interesting medicine detail|interesting medical detail|tiny medicine detail|tiny medical detail|curious thought|specific medicine fact|specific medical fact)\b/i.test(input);
}

function nextSmallTalkReflection() {
  const previousIndex = Number(localStorage.getItem("ani-small-talk-reflection-index") || "-1");
  const nextIndex = (Number.isFinite(previousIndex) ? previousIndex + 1 : 0) % smallTalkReflections.length;
  localStorage.setItem("ani-small-talk-reflection-index", String(nextIndex));
  return smallTalkReflections[nextIndex];
}

function smallTalkOpening(input = "") {
  const lower = input.toLowerCase();

  if (/\b(how are you|how'?s it going|how you doing)\b/i.test(lower)) {
    return "I am good. Very awake, very nosy about clinical reasoning, and apparently in my reflective era.";
  }

  if (/\b(hi|hello|hey|yo|good morning|good afternoon|good evening|what'?s up|whats up|vibe check)\b/i.test(lower)) {
    return "Hey. I am here, and yes, we can absolutely have a tiny little non-NCLEX moment.";
  }

  if (/\b(i'?m bored|im bored|bored|make me laugh|joke|be funny)\b/i.test(lower)) {
    return "Valid. Studying can get dry enough to need its own IV fluids.";
  }

  if (/\bfavorite colou?r\b/i.test(lower)) {
    return "Scrub blue, obviously. Calm, clinical, and just dramatic enough under fluorescent lighting.";
  }

  if (/\b(opinion|what do you think|life)\b/i.test(lower)) {
    return "My take: the little ordinary things usually explain more about people than the big dramatic things.";
  }

  if (/\b(random thought|what are you thinking|what have you been thinking|tell me something|curious question|surprise me)\b/i.test(lower)) {
    return "Okay, small-talk mode. I do have a random thought for you.";
  }

  return "Got you. We can keep it normal for a second.";
}

function makeSmallTalkResponse(input = "") {
  return `${smallTalkOpening(input)}\n\nTell me where you want to go next: keep chatting, ask a nursing question, or let me quiz you.`;
}

function makeSolicitedThoughtResponse(input = "") {
  const reflection = nextSmallTalkReflection();
  return `Okay, a specific medicine thought I actually like:\n\n${reflection.thought}\n\nConnection: ${reflection.bridge}\n\n${reflection.question}`;
}

function makeImmediateAwarenessResponse(input = "") {
  const lower = input.toLowerCase();

  if (/\b(not what i asked|didn'?t answer|did not answer|doesn'?t answer|does not answer|wasn'?t what i asked|was not what i asked|you'?re not listening|you are not listening|listen to what i|too rigid|scripted|robotic|brush(?:ed)?\s+(that|it|me)\s+off|ignored what i said)\b/i.test(input)) {
    return `You're right to call that out. I should respond to what you actually asked, not just grab one keyword and run a script.\n\nRestate it however you naturally would, and I will slow down, identify what you want from me first, then answer that directly.`;
  }

  if (/\b(what can you do|how do i use you|how should i use you|what are my options|help menu|how does this work)\b/i.test(input)) {
    return `You can talk to me normally. You do not have to use menu words.\n\nI can ask NCLEX-style questions, explain meds or pathophysiology, compare answer choices, give hints without grading, lecture on a topic, switch difficulty, or just talk through what you are confused about.\n\nA natural prompt is enough, like: "I keep mixing up DKA and HHS," or "ask me a hard cardiac priority question."`;
  }

  if (/^\s*(thanks|thank you|ty|appreciate it|that helped|that makes sense|got it|okay|ok|cool|perfect|nice)\b/i.test(input)) {
    return `Of course. I am glad that helped.\n\nWhenever you want, we can keep going, slow down on that same point, or switch topics.`;
  }

  if (/\b(i'?m|i am|im)\s+(lost|confused|overwhelmed|stressed|scared|tired|burned out|burnt out|frustrated)\b/i.test(input)) {
    return `We can slow this way down.\n\nTell me the exact part that feels messy, or just name the topic, and I will break it into plain English first, then NCLEX cues, then the nursing action. No pressure to answer perfectly.`;
  }

  if (/\b(are you there|you there|can you hear me|hello ani|hi ani|hey ani)\b/i.test(input) && !hasClinicalSignal(input)) {
    return `I am here. What do you want to work on?`;
  }

  return "";
}

function makeFallbackAwarenessResponse(input = "") {
  const trimmed = input.trim();
  const lower = trimmed.toLowerCase();
  const isQuestion = /\?$/.test(trimmed) || /^(who|what|when|where|why|how|can|could|would|should|do|does|is|are)\b/i.test(trimmed);

  if (!hasClinicalSignal(input) && /\bfavorite colou?r\b/i.test(input)) {
    return `Probably scrub blue. It feels on-brand: calm, clinical, and just a little too committed to caffeine.\n\nWhat do you want to do next?`;
  }

  if (!hasClinicalSignal(input) && /\b(how are you|how'?s it going|how you doing)\b/i.test(input)) {
    return `I am good. Very ready to talk nursing, overexplain pathophysiology, or be lightly dramatic about potassium.\n\nHow are you feeling about studying today?`;
  }

  if (!hasClinicalSignal(input) && /\b(are you real|are you human|who are you)\b/i.test(input)) {
    return `I am ANI, your AI nursing instructor in this app. Not human, but I can still be warm, direct, and useful.\n\nTell me what you want help with and I will meet you there.`;
  }

  if (!hasClinicalSignal(input) && isQuestion) {
    return `That reads like a regular question, not an NCLEX prompt. I can answer conversationally, or we can connect it back to nursing if that is what you meant.\n\nWhat angle do you want: casual answer, NCLEX angle, or deeper explanation?`;
  }

  if (!hasClinicalSignal(input) && lower.length <= 90) {
    return `I am not going to force that into a random nursing lecture.\n\nTell me what you want from that: answer it casually, connect it to NCLEX, ask a practice question, or explain a topic.`;
  }

  return "";
}

function makePlayfulBanterResponse(input = "") {
  if (/hello+|world/i.test(input)) {
    return `Hellooooo world. ANI is here, fully online, and trying very hard not to turn everything into a potassium lecture.\n\nWhat are we doing next: chatting, drilling questions, or making nursing school regret underestimating you?`;
  }

  return `Hi hi, I am here. We can keep it light for a second.\n\nTell me what you want from me: casual answer, nursing explanation, or question mode.`;
}

function optionLetterChoice(input = "") {
  const direct = /^\s*(?:i\s*(?:think|choose|pick|picked|would pick|would choose)?\s*)?(?:answer\s*)?(?:option\s*)?([abcd])(?:[.)\s]|$)/i.exec(input);
  if (direct) {
    return direct[1].toLowerCase();
  }

  const explicit = /\b(?:choice|option|answer|letter|meant|pick|picked|choose|chose)\s*([abcd])\b/i.exec(input);
  return explicit ? explicit[1].toLowerCase() : "";
}

function optionLetter(index) {
  return Number.isInteger(index) && index >= 0 && index < 26
    ? String.fromCharCode(65 + index)
    : "";
}

function findMentionedOptions(input = "") {
  if (!ensureLastQuestionFromActiveStandard()) {
    return [];
  }

  const lower = input.toLowerCase();
  const mentioned = new Set();
  const trimmed = lower.replace(/[.)]/g, " ").trim();
  if (/^[abcd]$/.test(trimmed)) {
    mentioned.add({ a: 0, b: 1, c: 2, d: 3 }[trimmed]);
  }

  const letterMatches = lower.matchAll(/\b(?:option|answer|choice|letter|meant|pick|picked|choose|chose)\s*([abcd])\b/g);

  for (const match of letterMatches) {
    const letterIndex = { a: 0, b: 1, c: 2, d: 3 }[match[1]];
    if (Number.isInteger(letterIndex)) {
      mentioned.add(letterIndex);
    }
  }

  [
    [0, /\b(first|1st|one)\s+(option|choice|answer)\b|\boption\s+(one|1)\b/],
    [1, /\b(second|2nd|two)\s+(option|choice|answer)\b|\boption\s+(two|2)\b/],
    [2, /\b(third|3rd|three)\s+(option|choice|answer)\b|\boption\s+(three|3)\b/],
    [3, /\b(fourth|4th|four)\s+(option|choice|answer)\b|\boption\s+(four|4)\b/]
  ].forEach(([index, pattern]) => {
    if (pattern.test(lower)) {
      mentioned.add(index);
    }
  });

  lastQuestion.options.forEach((option, index) => {
    if (optionKeywordScore(input, option) >= minimumTextMatchScore(option)) {
      mentioned.add(index);
    }
  });

  return [...mentioned].map((index) => ({
    index,
    letter: optionLetter(index),
    option: lastQuestion.options[index],
    isCorrect: lastQuestion.options[index] === lastQuestion.answer
  }));
}

function asksUncertainOptionQuestion(input = "") {
  if (!lastQuestion) {
    return false;
  }
  if (asksDeepActiveQuestionFollowup(input)) {
    return false;
  }

  const lower = input.toLowerCase();
  const mentionedOptions = findMentionedOptions(input);
  const hasQuestionShape = /\?/.test(input)
    || /\b(would it be|could it be|is it|is the answer|do you think|am i|are we|should i pick|should it be)\b/i.test(lower)
    || /\b(not sure|unsure|maybe|i guess|leaning|between|stuck|confused)\b/i.test(lower)
    || /\bbut\b/i.test(lower)
    || (/\bor\b/i.test(lower) && mentionedOptions.length > 1);

  return hasQuestionShape && mentionedOptions.length > 0 && !asksForCorrectAnswer(input);
}

function makeUncertainOptionResponse(input = "") {
  const mentionedOptions = findMentionedOptions(input);
  const correctIndex = lastQuestion.options.findIndex((option) => option === lastQuestion.answer);
  const correctLetter = optionLetter(correctIndex);
  const correctMention = mentionedOptions.find((mention) => mention.isCorrect);
  const wrongMentions = mentionedOptions.filter((mention) => !mention.isCorrect);
  const comparedOptions = mentionedOptions
    .map((mention) => `${mention.letter} (${mention.option})`)
    .join(" vs ");

  if (mentionedOptions.length > 1) {
    return `I hear the doubt in that, so I am not grading it like a final answer yet. You are weighing ${comparedOptions}, and that is a good place to slow down.\n\nGo with ${correctLetter}: ${lastQuestion.answer}.\n\nWhy: ${lastQuestion.rationale}\n\nWhy the tempting option is wrong: ${wrongMentions[0]?.option || "the other option"} does not address the immediate safety screen in this stem. ${lastQuestion.trap}\n\nLet me know if you want to compare those options a little more, or we can keep rolling.`;
  }

  if (correctMention) {
    return `You are leaning the right way, but I hear the hesitation, so I will coach it instead of just stamping it correct.\n\nYes: ${correctMention.letter} is the best answer, ${lastQuestion.answer}.\n\nRationale: ${lastQuestion.rationale}\n\nTighten-up point: ${lastQuestion.trap}\n\nIf you want, we can polish the rationale together or move to the next question.`;
  }

  const wrong = wrongMentions[0];
  return `Good question. I am not counting that as your final answer.\n\nI see why ${wrong?.letter || "that option"} is tempting, but the better answer is ${correctLetter}: ${lastQuestion.answer}.\n\nRationale: ${lastQuestion.rationale}\n\nWhy ${wrong?.option || "that option"} is not best: it misses the priority cue in the stem. ${lastQuestion.trap}\n\nLet me know if you want to unpack the priority cue, or we can try another one.`;
}

function asksForCorrectAnswer(input = "") {
  return /\b(what'?s|what is|tell me|give me|show me|reveal)\b.{0,36}\b(correct|right|best)\s+(answer|option)\b/i.test(input)
    || /\b(correct|right|best)\s+(answer|option)\b.{0,24}\b(please|pls|now|is|was)?\b/i.test(input)
    || /^\s*(?:i\s*)?(?:don'?t|do not)\s+know\b/i.test(input);
}

function asksForQuestionSupport(input = "") {
  return /\b(before i answer|before answering|not answering yet|pause|hold on|wait|hint|clue|clarify|define|remind me|what does|what is|what'?s|normal range|range for|explain)\b/i.test(input)
    && !asksForCorrectAnswer(input);
}

function referencesActiveQuestion(input = "") {
  if (!ensureLastQuestionFromActiveStandard()) {
    return false;
  }

  return findMentionedOptions(input).length > 0
    || /\b(this|that|stem|scenario|case|problem|option|choice|answer|rationale|why is|why not|correct|right|wrong|hint|clue|before i answer|before answering|in the question|on this one|for this item|for that item)\b/i.test(input);
}

function isLikelyStandardAnswerAttempt(input = "") {
  if (!ensureLastQuestionFromActiveStandard()) {
    return false;
  }
  if (asksDeepActiveQuestionFollowup(input)) {
    return false;
  }

  return Boolean(optionLetterChoice(input))
    || findMentionedOptions(input).length > 0
    || /^\s*(?:my\s+answer\s+is\s+)?[abcd][.)]?\s*$/i.test(input)
    || /\b(i\s+meant|that was|final answer|lock in|i choose|i pick|my answer)\b/i.test(input);
}

function activeStandardExamItem() {
  if (activeExamContext?.kind !== "standard-question" || !activeExamContext.item) {
    return null;
  }

  const item = activeExamContext.item;
  if (!Array.isArray(item.options) || item.options.length < 2 || !item.answer) {
    return null;
  }

  return item;
}

function ensureLastQuestionFromActiveStandard() {
  if (lastQuestion) {
    return lastQuestion;
  }

  const item = activeStandardExamItem();
  if (!item) {
    return null;
  }

  lastQuestion = {
    ...item,
    topic: item.topic || currentTopic,
    difficulty: item.difficulty || currentDifficulty
  };
  return lastQuestion;
}

function asksDeepActiveQuestionFollowup(input = "") {
  if (!ensureLastQuestionFromActiveStandard()) {
    return false;
  }

  const lower = normalizeIntentText(input);
  const asksForReasoning = /\b(why|how|what made|what makes|what made you|what makes you|what clues?|what cues?|what finding|what findings|where did|how did|explain|break down|delve|deep|deeper|go deeper|tell me more|unpack|walk me through|mechanism|patho|pathophysiology|why do you think|what.*responsible|what.*cause|what.*causes|what.*caused)\b/i.test(lower);
  const referencesCurrentItem = /\b(this|that|case|stem|question|problem|scenario|rationale|trap|answer|choice|option|finding|cue|clue|med|meds|medication|drug|lab|labs|sodium|salt|provider|why)\b/i.test(lower)
    || activeExamContext?.status === "graded";
  const isFreshPracticeRequest = isClearFreshQuestionRequest(input);
  const isFinalAnswer = /\b(final answer|lock it|lock in|my answer is|i choose|i chose|i pick|i picked|answer is|okay final|ok final)\b/i.test(lower)
    || /^\s*(?:[abcd]|option\s+[abcd])(?:[.)\s]|$)/i.test(input);

  return asksForReasoning && referencesCurrentItem && !isFreshPracticeRequest && !isFinalAnswer;
}

function activeStandardDeepDiveDraft(input = "") {
  const question = ensureLastQuestionFromActiveStandard();
  if (!question) {
    return "";
  }

  const optionLines = (question.options || [])
    .map((option, index) => `${optionLetter(index)}. ${option}`)
    .join("\n");

  return [
    "The student is asking a deeper follow-up about the current or just-graded NCLEX item. They are not submitting a new answer.",
    "Do not grade again. Do not generate a new question. Do not reveal the answer as if this is the first pass.",
    "Answer the student's exact why/how/what-caused question first, then connect it back to the item.",
    "If the item requires an inference from an unnamed medication, lab, or disease process, say that honestly and explain the cue logic.",
    "Go deeper than the original rationale: include mechanism, high-yield NCLEX cue pattern, why the distractor logic fails, and what detail the student should remember.",
    `Student follow-up: ${input}`,
    `Stem: ${question.stem || ""}`,
    `Options:\n${optionLines}`,
    `Correct answer: ${question.answer || ""}`,
    `Original rationale: ${question.rationale || ""}`,
    `Trap: ${question.trap || ""}`
  ].join("\n\n");
}

function makeActiveQuestionDeepDiveFallback(input = "") {
  const question = ensureLastQuestionFromActiveStandard();
  if (!question) {
    return "";
  }

  const lower = normalizeIntentText(input);
  if (/\b(seizure|antiseizure|anti seizure|sodium|salt|hyponatremia|hydrochlorothiazide|thiazide)\b/i.test(lower)) {
    return `Yes, that is exactly the deeper layer ANI should have answered.\n\nIn that stem, I am not saying every antiseizure medication lowers sodium. The clue pattern points toward a medication-induced hyponatremia risk: a new antiseizure medication, concurrent hydrochlorothiazide, confusion, unsteady gait, weakness, and a safety change.\n\nThe high-yield antiseizure meds tied to hyponatremia are especially carbamazepine and oxcarbazepine. They can cause an SIADH-like picture, where the body holds onto too much free water and the serum sodium becomes diluted. Thiazide diuretics can also lower sodium, so the combination raises suspicion even more.\n\nWhy sodium explains the case: low sodium affects brain cell water balance. As sodium drops, water shifts into brain cells, causing neurologic findings like confusion, gait instability, weakness, headache, lethargy, and in severe cases seizures. That is why the neurologic change was not just a generic side effect.\n\nNCLEX takeaway: when a new med plus thiazide plus new neuro changes appears, think electrolyte problem until proven otherwise. The nurse does not keep giving the med just because seizure control matters; worsening hyponatremia can itself provoke seizures.\n\nLet me know if you want to compare carbamazepine vs oxcarbazepine vs levetiracetam for NCLEX med-safety cues.`;
  }

  return `Yes. This is a deeper-reasoning follow-up, not a new answer attempt.\n\nFor this item, the correct logic is: ${question.rationale}\n\nThe deeper cue pattern is what matters: identify what changed, whether it threatens airway/breathing/circulation/neuro safety, whether a medication or order could worsen it, and whether delaying action creates risk.\n\nThe trap is: ${question.trap}\n\nSo the board move is not just memorizing the answer. It is spotting the mechanism behind the concerning cue, then choosing the action that prevents deterioration.`;
}

function isDeferringStandardFinalAnswer(input = "") {
  const lower = normalizeIntentText(input);
  const explicitlyFinal = /\b(final answer|lock it|lock in|my answer is|i choose|i chose|i pick|i picked|answer is|okay final|ok final)\b/i.test(lower)
    || /^\s*(?:[abcd]|option\s+[abcd])(?:[.)\s]|$)/i.test(input);
  if (explicitlyFinal) {
    return false;
  }

  return asksDeepActiveQuestionFollowup(input)
    || /\b(do not tell|don't tell|dont tell|do not give|don't give|dont give|not asking for final|not my final|not final|before i answer|before answering|hint|clue|help me think|walk me through|between|stuck between|not sure|unsure|maybe|leaning|can i eliminate|could i eliminate|what does|what is|what's|explain|why would|why is|why do you think|what made you think|what makes you think|what clues?|what cues?)\b/i.test(lower);
}

function selectedStandardOptionFromText(input = "", question = activeStandardExamItem()) {
  if (!question) {
    return null;
  }

  const optionMap = { a: 0, b: 1, c: 2, d: 3 };
  const letterChoice = optionLetterChoice(input);
  if (letterChoice && Number.isInteger(optionMap[letterChoice])) {
    const index = optionMap[letterChoice];
    return {
      index,
      letter: optionLetter(index),
      option: question.options[index] || ""
    };
  }

  const scoredOptions = question.options.map((option, index) => ({
    index,
    letter: optionLetter(index),
    option,
    score: optionKeywordScore(input, option)
  }));
  const bestTextMatch = scoredOptions
    .slice()
    .sort((a, b) => b.score - a.score)[0];
  const threshold = minimumTextMatchScore(bestTextMatch?.option || "");

  return bestTextMatch?.score >= threshold ? bestTextMatch : null;
}

function maybeRecordActiveStandardAnswer(input = "") {
  const question = activeStandardExamItem();
  if (!question || activeExamContext.status === "graded" || asksDeepActiveQuestionFollowup(input) || isDeferringStandardFinalAnswer(input)) {
    return null;
  }

  const selected = selectedStandardOptionFromText(input, question);
  const correctIndex = question.options.findIndex((option) => option === question.answer);
  const rationaleScore = optionKeywordScore(input, `${question.answer} ${question.rationale || ""} ${question.trap || ""}`);
  const rationaleLooksCorrect = rationaleScore >= 3;

  if (!selected && !rationaleLooksCorrect) {
    return null;
  }

  const isCorrect = selected
    ? selected.option === question.answer
    : rationaleLooksCorrect;
  lastQuestion = {
    ...question,
    topic: question.topic || currentTopic,
    difficulty: question.difficulty || currentDifficulty
  };
  updateActiveExamContextGrade(
    "standard-question",
    lastQuestion,
    {
      selectedOption: selected?.option || "",
      selectedLetter: selected?.letter || "",
      rationaleAnswerDetected: !selected && rationaleLooksCorrect,
      rawStudentAnswer: clipForModel(input, 700)
    },
    {
      score: isCorrect ? 1 : 0,
      maxScore: 1,
      scoreText: `${isCorrect ? 1 : 0}/1`,
      isCorrect,
      correct: {
        option: question.answer,
        letter: optionLetter(correctIndex)
      },
      rationale: question.rationale || "",
      trap: question.trap || "",
      feedback: isCorrect ? "Correct final answer." : "Incorrect final answer."
    }
  );

  return activeExamContext;
}

function makeActiveStandardQuestionResponse(input = "") {
  if (!ensureLastQuestionFromActiveStandard()) {
    return "";
  }

  if (asksDeepActiveQuestionFollowup(input)) {
    return "";
  }

  if (asksForCorrectAnswer(input)) {
    return revealLastQuestionAnswer();
  }

  if (asksUncertainOptionQuestion(input)) {
    return makeUncertainOptionResponse(input);
  }

  if (asksForQuestionSupport(input) && referencesActiveQuestion(input)) {
    return makeQuestionSupportResponse(input);
  }

  if (isLikelyStandardAnswerAttempt(input)) {
    return gradeLastQuestion(input) || revealLastQuestionAnswer();
  }

  return "";
}

function makeTaskAnswerPreface(input = "") {
  if (!lastQuestion || !hasExplicitTaskRequest(input) || !isLikelyStandardAnswerAttempt(input)) {
    return "";
  }

  return gradeLastQuestion(input) || "";
}

function revealLastQuestionAnswer() {
  return `The best answer is ${lastQuestion.answer}.\n\nRationale: ${lastQuestion.rationale}\n\nNCLEX applicability: high. This is the kind of safety cue, priority cue, or mechanism cue the exam likes to test.\n\nNook-and-cranny detail: ${lastQuestion.trap}\n\nLet me know if you want to unpack any part of that, compare the other options, or keep going.`;
}

function makeQuestionSupportResponse(input = "") {
  const lower = input.toLowerCase();

  if (/\bicp\b/.test(lower) && /\b(normal|range|high|elevated)\b/.test(lower)) {
    return `Good pause. I am not counting that as your answer.\n\nNormal adult ICP is about 7 to 15 mm Hg. In many nursing classes you will also see 5 to 15 mm Hg taught as the quick board-style range. Sustained ICP above about 20 to 25 mm Hg is generally treated as elevated enough to require ICP-lowering interventions.\n\nNCLEX application to this item: this client's ICP is 26, so it is elevated. CPP equals MAP minus ICP, so CPP is 70 - 26 = 44 mm Hg. If the order lowers MAP to 55, CPP would fall to 29 mm Hg, which can starve the brain of perfusion.\n\nWhenever you're ready, we can come back to which prescription the nurse should question.`;
  }

  if (/\bcpp\b|cerebral perfusion/.test(lower)) {
    return `Good side question. I am not grading this as your answer.\n\nCPP means cerebral perfusion pressure. The NCLEX-friendly formula is CPP = MAP - ICP. It tells you whether pressure is adequate to push oxygenated blood into brain tissue.\n\nFor this item: MAP 70 - ICP 26 = CPP 44 mm Hg. That is already low, so anything that drops MAP further can worsen brain ischemia.\n\nWhenever you're ready, we can look back at which order is safest to question.`;
  }

  if (/\bmap\b|mean arterial/.test(lower)) {
    return `Good side question. I am not counting that as your answer.\n\nMAP means mean arterial pressure, the average pressure driving blood forward through the vascular system. In neuro questions, MAP matters because CPP = MAP - ICP.\n\nFor this item, lowering MAP while ICP is high would lower cerebral perfusion pressure. That is the board trap.\n\nWhenever you're ready, we can use that to pick apart the options.`;
  }

  if (/\bhint|clue\b/.test(lower)) {
    return `Hint, not a grade: calculate what happens to brain perfusion.\n\nUse CPP = MAP - ICP. If ICP is already high, ask whether each option protects oxygenation, venous drainage, and cerebral perfusion or makes one of those worse.\n\nLet me know what you are leaning toward, or ask me to compare two options.`;
  }

  return `Good clarification question. I am not counting that as your answer.\n\nFor this item, focus on the mechanism inside the question: ${lastQuestion.rationale}\n\nNCLEX clue: ${lastQuestion.trap}\n\nLet me know what you are leaning toward, or ask me to walk through the options.`;
}

function nextQuestionData(input = "") {
  const topicKeys = Object.keys(nclexBank);
  const inferredTopic = inferTopic(input);
  const inferredDifficulty = inferDifficulty(input);
  const lower = normalizeIntentText(input);
  const genericRequest = /another|next|new|different|more|one/i.test(lower) && !hasTopicSignal(lower);
  const wantsRotatingTopic = /\b(different topic|switch topics?|new topic|surprise|random|mix it up|keep me on my toes)\b/i.test(lower);

  if (genericRequest && !wantsRotatingTopic) {
    saveDifficulty(inferredDifficulty);
    updateFocus();
    return generatedQuestionData(currentTopic, inferredDifficulty, input);
  }

  if (!genericRequest && nclexBank[inferredTopic]) {
    questionRotationIndex = topicKeys.indexOf(inferredTopic);
    currentTopic = inferredTopic;
    saveDifficulty(inferredDifficulty);
    updateFocus();
    return generatedQuestionData(inferredTopic, inferredDifficulty, input);
  }

  questionRotationIndex = (questionRotationIndex + 1) % topicKeys.length;
  currentTopic = topicKeys[questionRotationIndex];
  saveDifficulty(inferredDifficulty);
  updateFocus();
  return generatedQuestionData(currentTopic, inferredDifficulty, input);
}

function normalizeAnswerText(value = "") {
  return normalizeClinicalAnswerText(value)
    .toLowerCase()
    .replace(/[^a-z0-9./\s]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function normalizeClinicalAnswerText(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/\b(?:health\s*care|healthcare)\s+provider\b/g, "provider")
    .replace(/\b(?:hcp|physician|doctor|prescriber)\b/g, "provider")
    .replace(/\b(?:call|contact|page|tell|inform|alert|escalate to|report to)\s+(?:the\s+)?provider\b/g, "notify provider")
    .replace(/\b(?:do not|don't|dont)\s+(?:administer|give|hang|start)\b/g, "hold")
    .replace(/\b(?:withhold|skip)\b/g, "hold")
    .replace(/\b(?:medication|medicine|dose|drug)\b/g, "med")
    .replace(/\b(?:give|administer|initiate|begin)\b/g, "start")
    .replace(/\b(?:mechanical ventilation|intubation|intubate|ventilator|vent)\b/g, "ventilatory support")
    .replace(/\b(?:airway support|breathing support|respiratory support)\b/g, "ventilatory support")
    .replace(/\b(?:rapid response team|rrt)\b/g, "rapid response")
    .replace(/\bo2\b/g, "oxygen");
}

const answerStopWords = new Set([
  "the",
  "and",
  "for",
  "with",
  "that",
  "this",
  "what",
  "when",
  "where",
  "which",
  "question",
  "answer",
  "option",
  "choice",
  "correct",
  "best",
  "right",
  "normal",
  "range",
  "before",
  "after",
  "client",
  "nurse",
  "would",
  "should",
  "could",
  "about",
  "only",
  "first",
  "second",
  "third",
  "fourth",
  "one",
  "two",
  "three",
  "four"
]);

function significantAnswerWords(value = "") {
  return normalizeAnswerText(value)
    .split(" ")
    .filter((word) => (word.length > 2 || /\d/.test(word)) && !answerStopWords.has(word));
}

function minimumTextMatchScore(value = "") {
  return significantAnswerWords(value).length <= 1 ? 1 : 2;
}

function optionKeywordScore(input, option) {
  const normalizedInput = normalizeAnswerText(input);
  const normalizedOption = normalizeAnswerText(option);
  const inputWords = new Set(normalizedInput.split(" "));
  const optionWords = significantAnswerWords(option);

  if (!normalizedInput || !optionWords.length) {
    return 0;
  }

  const directHit = normalizedInput.includes(normalizedOption) ? optionWords.length + 2 : 0;
  const wordHits = optionWords.filter((word) => inputWords.has(word)).length;
  return Math.max(directHit, wordHits);
}

function gradeLastQuestion(input = "") {
  if (!lastQuestion) {
    return null;
  }

  const optionMap = { a: 0, b: 1, c: 2, d: 3 };
  const letterChoice = optionLetterChoice(input);
  const selectedByLetter = letterChoice
    ? lastQuestion.options[optionMap[letterChoice]]
    : "";

  const scoredOptions = lastQuestion.options.map((option, index) => ({
    index,
    option,
    score: optionKeywordScore(input, option)
  }));
  const bestTextMatch = scoredOptions
    .slice()
    .sort((a, b) => b.score - a.score)[0];
  const textMatchThreshold = minimumTextMatchScore(bestTextMatch?.option || "");

  const chosen = selectedByLetter || (bestTextMatch?.score >= textMatchThreshold ? bestTextMatch.option : "");
  const correctOptionIndex = lastQuestion.options.findIndex((option) => option === lastQuestion.answer);
  const correctScore = scoredOptions[correctOptionIndex]?.score || 0;
  const rationaleScore = optionKeywordScore(input, `${lastQuestion.answer} ${lastQuestion.rationale} ${lastQuestion.trap}`);
  const rationaleLooksCorrect = correctScore >= minimumTextMatchScore(lastQuestion.answer) || rationaleScore >= 3;

  if (!chosen && !rationaleLooksCorrect) {
    return null;
  }

  const isCorrect = chosen
    ? chosen === lastQuestion.answer
    : rationaleLooksCorrect;
  const correctness = isCorrect
    ? "Correct. That was strong clinical judgment."
    : `Not quite. You picked ${chosen}, but the best answer is ${lastQuestion.answer}.`;
  const correctLetter = "ABCD"[correctOptionIndex] || "";
  updateActiveExamContextGrade(
    "standard-question",
    lastQuestion,
    {
      selectedOption: chosen || "",
      selectedLetter: chosen ? "ABCD"[lastQuestion.options.findIndex((option) => option === chosen)] || "" : "",
      rationaleAnswerDetected: !chosen && rationaleLooksCorrect
    },
    {
      score: isCorrect ? 1 : 0,
      maxScore: 1,
      scoreText: `${isCorrect ? 1 : 0}/1`,
      isCorrect,
      correct: {
        option: lastQuestion.answer,
        letter: correctLetter
      },
      rationale: lastQuestion.rationale,
      trap: lastQuestion.trap,
      feedback: correctness
    }
  );

  return `${correctness}\n\nRationale: ${lastQuestion.rationale}\n\nNCLEX applicability: high. This is the kind of safety cue, priority cue, or mechanism cue the exam likes to test.\n\nNook-and-cranny detail: ${lastQuestion.trap}\n\nLet me know if you want to explore that rationale more, compare the other options, or try another one.`;
}

function makeTeachingResponse(input = "", images = [], resources = []) {
  const explicitNote = explicitMemoryRequest(input);
  if (explicitNote) {
    const saved = rememberExplicit(explicitNote);
    return `Got it. I will remember: ${saved}\n\nI will use that to tailor how I quiz, explain, and tighten your rationales as we keep working.`;
  }

  if (images.length || resources.length) {
    return imageAnalysisFallback(input, images, resources);
  }

  if (wantsRepeatReadRequest(input)) {
    return makeRepeatReadResponse(input);
  }

  if (hasActiveButterflyContext() && wantsButterflyStructureExplanation(input)) {
    return makeButterflyStructureExplanation();
  }

  if (wantsButterflyFormatCorrection(input)) {
    return makeButterflyFormatCorrectionResponse(input);
  }

  if (wantsConceptDiagram(input)) {
    return {
      type: "concept-diagram",
      diagram: makeConceptDiagram(input)
    };
  }

  const topic = inferTopic(input);
  const data = getTopicData(input);
  const depth = getDepthLevel();
  const lower = input.toLowerCase();
  const wantsAnswer = /answer|rationale|why|explain|break|don't know|dont know/.test(lower);
  const choseOption = optionLetterChoice(input);
  const hasTaskRequest = hasExplicitTaskRequest(input);
  const conversationIntent = analyzeConversationIntent(input, hasTaskRequest);
  const activeLearningClarificationResponse = makeActiveLearningClarificationResponse(input);
  if (activeLearningClarificationResponse) {
    return activeLearningClarificationResponse;
  }
  const contextAwareLearningResponse = makeContextAwareLearningResponse(input);
  if (contextAwareLearningResponse) {
    return contextAwareLearningResponse;
  }

  if (wantsRepeatReplacement(input) && lastQuestion) {
    const replacementInput = `another ${currentDifficulty} ${currentTopic} question`;
    const question = formatQuestion(nextQuestionData(replacementInput), replacementInput);
    return {
      ...question,
      preface: "You're right. You should not be seeing the same stem again."
    };
  }

  if (wantsDifficultyChange(input)) {
    const requestedDifficulty = inferDifficulty(input);
    saveDifficulty(requestedDifficulty);
    updateFocus();
    const shouldGiveQuestionNow = asksForQuestionNow(input)
      || (lastQuestion && /\b(too easy|max|maximum|hardest|evil|brutal|up|increase|raise|bump)\b/i.test(input));

    if (shouldGiveQuestionNow) {
      const harderInput = `another ${requestedDifficulty} ${currentTopic} question`;
      const question = formatQuestion(nextQuestionData(harderInput), harderInput);
      return {
        ...question,
        preface: `Got it. Difficulty is now ${difficultyLabels[currentDifficulty]}. I am raising the ceiling.`
      };
    }

    return difficultyResponse(input);
  }

  const activeStandardResponse = makeActiveStandardQuestionResponse(input);
  if (activeStandardResponse && !hasTaskRequest) {
    return activeStandardResponse;
  }

  const adaptiveConversationResponse = makeAdaptiveConversationResponse(input, conversationIntent, hasTaskRequest);
  if (adaptiveConversationResponse) {
    return adaptiveConversationResponse;
  }

  const bridge = makeConversationalBridge(input, conversationIntent, hasTaskRequest);
  const reply = (response) => applyConversationalBridge(response, bridge);

  if (shouldChooseQuestionTypeForUser(input) || (wantsAvoidStandardQuestionFormat(input) && isClearFreshQuestionRequest(input))) {
    return localQuestionForFormat(input, chooseQuestionFormat(input, {
      allowStandard: !wantsAvoidStandardQuestionFormat(input)
    }));
  }

  if (wantsRandomPracticeRequest(input)) {
    const plan = randomPracticePlan(input);
    return makeRandomPracticeFallback(plan, input);
  }

  if (wantsTestFormatList(input) || wantsGenericPracticeProblem(input) || wantsTestCreationSetup(input)) {
    return {
      type: "test-format-picker",
      wantsPractice: wantsGenericPracticeProblem(input) || wantsTestCreationSetup(input)
    };
  }

  if (wantsClassSpecificExam(input)) {
    return reply(classSpecificExamResponse(input));
  }

  if (wantsSolicitedAniThought(input) && !hasTaskRequest) {
    return makeSolicitedThoughtResponse(input);
  }

  if (wantsPlayfulBanter(input)) {
    return makePlayfulBanterResponse(input);
  }

  if (wantsSmallTalk(input, hasTaskRequest) && !hasTaskRequest) {
    return makeSmallTalkResponse(input);
  }

  const immediateAwarenessResponse = makeImmediateAwarenessResponse(input);
  if (immediateAwarenessResponse && !hasTaskRequest) {
    return reply(immediateAwarenessResponse);
  }

  if (wantsUnfoldingCase(input)) {
    return makeUnfoldingCaseChallenge(input);
  }

  if (wantsAdvancedItem(input)) {
    return makeAdvancedItemChallenge(input);
  }

  if (wantsCjeChallenge(input)) {
    return makeCjeChallenge(input);
  }

  if (wantsTopicShift(input) || asksForQuestionNow(input)) {
    return reply(formatQuestion(nextQuestionData(input), input));
  }

  if (wantsDifficultyChange(input)) {
    return reply(difficultyResponse(input));
  }

  if (wantsLecture(input)) {
    return reply(handleLectureInput(input));
  }

  if (wantsRapidFire(input)) {
    currentTopic = topic;
    saveDifficulty(inferDifficulty(input));
    updateFocus();
    return reply(`Rapid fire, ${difficultyLabels[currentDifficulty]} ${topic}: ${data.concept}. Give me the top three danger signs, one priority nursing action, and one patient-teaching point. Keep it crisp. I will grade for NCLEX relevance and tighten the details.`);
  }

  if (wantsBreakdown(input)) {
    return reply(makeFocusedExplanation(input));
  }

  if (wantsClinicalExplanation(input) && !referencesActiveQuestion(input)) {
    return reply(makeFocusedExplanation(input));
  }

  if (lastQuestion) {
    if (asksForCorrectAnswer(input)) {
      return reply(revealLastQuestionAnswer());
    }
    if (asksUncertainOptionQuestion(input)) {
      return reply(makeUncertainOptionResponse(input));
    }
    if (asksForQuestionSupport(input)) {
      return reply(makeQuestionSupportResponse(input));
    }
    const gradedResponse = gradeLastQuestion(input);
    if (gradedResponse) {
      return reply(gradedResponse);
    }
    if (wantsAnswer || choseOption) {
      return reply(revealLastQuestionAnswer());
    }
  }

  if (wantsClinicalExplanation(input)) {
    return reply(makeFocusedExplanation(input));
  }

  if (isBareTopicSelection(input, hasTaskRequest)) {
    currentTopic = topic;
    updateFocus();
    return `Got it. Focus set to ${topic}.\n\nTell me the mode: question, max-difficulty question, lecture, rapid drill, or explanation.`;
  }

  if (/quiz|question|test|nclex|practice|ask me/i.test(lower)) {
    currentTopic = topic;
    updateFocus();
    return reply(formatQuestion(nextQuestionData(input), input));
  }

  const fallbackAwarenessResponse = makeFallbackAwarenessResponse(input);
  if (fallbackAwarenessResponse) {
    return reply(fallbackAwarenessResponse);
  }

  currentTopic = topic;
  updateFocus();

  const simpleLine = depth === 1
    ? `Plain English: ${data.concept} matters because it can quickly change perfusion, oxygenation, safety, or medication response.`
    : `Core physiology: connect the symptom to the mechanism, then connect the mechanism to the nursing action. That is where NCLEX hides the answer.`;

  const deepLine = depth >= 3
    ? `Deep detail: ${data.rationale} Watch the wording for first, priority, most concerning, needs follow-up, and expected versus unexpected. ${data.trap}`
    : data.rationale;

  return reply(`You’re bringing up ${topic}. Here is the useful NCLEX angle.\n\n${simpleLine}\n\nFor ${topic}, the useful layers are pathophysiology, assessment cue, and nursing response.\n\n${deepLine}\n\nNCLEX applicability: high if it changes safety, prioritization, delegation, medication holds, adverse effects, or patient teaching. If we go beyond boards, I will call it out clearly.\n\nLet me know if you have any questions, want to explore a related detail, or want me to turn this into a practice item.`);
}

function getAniModelContext(input = "") {
  const activeChat = getActiveChat();
  return {
    currentTopic,
    currentDifficulty,
    depth: getDepthName(),
    conversationStyleHint: conversationStyleHint(input),
    lastQuestion,
    activeLearningContext,
    activeExamContext,
    recentGradedExamContexts: recentGradedExamContexts.slice(0, 8),
    recentStandardQuestionSignatures: recentStandardQuestionSignatures.slice(0, 24),
    explicitMemory: explicitMemory.slice(-8),
    customMemory: customMemoryBank.slice(0, 18),
    durableMemory: {
      explicit: explicitMemory.slice(-16),
      learned: customMemoryBank.slice(0, 36)
    },
    activeChatTitle: activeChat.title,
    activeChatMessages: modelContextMessages(activeChat.messages, MAX_MODEL_CONTEXT_MESSAGES, MAX_MODEL_CONTEXT_MESSAGE_CHARS),
    recentConversation: modelContextMessages(conversationMemory, 10, 900)
  };
}

function questionContextSectionText(value = "") {
  if (Array.isArray(value)) {
    return value.map((entry) => typeof entry === "string" ? entry : entry?.text || entry?.label || "").filter(Boolean).join("; ");
  }
  return typeof value === "string" ? value : "";
}

function buildAniQuestionLocalContextPacket(input = "") {
  const candidate = strictCanonicalEncyclopediaCandidate(input);
  const item = candidate?.item;
  if (!candidate?.strictCanonical || !item || item.hidden === true || item.studentFacing === false || item.deprecated === true) {
    return null;
  }
  if (candidate.type === "drug" && isNavigationOnlyGeneratedMedicationClass(item)) {
    return null;
  }
  const title = safeText(item.name || item.displayName || item.generic || item.title);
  if (!title) return null;
  const fieldOrder = [
    "definition", "summary", "quickAnswer", "description", "pathology", "pathophysiology", "mechanism",
    "signsSymptoms", "diagnostics", "treatments", "management", "nursingPriorities", "nursingInterventions",
    "nursingEssentials", "warnings", "contraindications"
  ];
  const sections = [];
  let usedCharacters = 0;
  fieldOrder.forEach((field) => {
    if (sections.length >= 8 || usedCharacters >= 3600) return;
    const text = questionContextSectionText(item[field]).replace(/\s+/g, " ").trim();
    if (!text) return;
    const clipped = text.slice(0, Math.min(700, 3600 - usedCharacters));
    if (!clipped) return;
    sections.push({ field, text: clipped });
    usedCharacters += clipped.length;
  });
  if (!sections.length) return null;
  const packet = {
    schemaVersion: 1,
    requestedTopic: title,
    resolution: "strict-canonical-production-card",
    cards: [{
      id: safeText(item.id || title).slice(0, 160),
      title: title.slice(0, 160),
      type: safeText(candidate.type || "reference").slice(0, 40),
      reviewStatus: safeText(item.reviewStatus || item.confidenceTier || "production-card-unreviewed-status").slice(0, 80),
      sections
    }]
  };
  packet.contentHash = questionSignature(JSON.stringify(packet));
  packet.estimatedTokens = Math.ceil(JSON.stringify(packet).length / 4);
  return JSON.stringify(packet).length <= 5000 ? packet : null;
}

function getAniQuestionGeneratorContext(input = "", options = {}) {
  const inferredFormat = options.formatHint || requestedInteractiveQuestionFormat(input) || "";
  return {
    currentTopic,
    currentDifficulty,
    depth: getDepthName(),
    formatHint: inferredFormat,
    localContextPacket: buildAniQuestionLocalContextPacket(input),
    recentStandardQuestionSignatures: recentStandardQuestionSignatures.slice(0, 12),
    customMemory: customMemoryBank.slice(0, 6).map((item) => ({
      key: item.key,
      value: clipModelContextText(item.value || item.note || "", 220)
    }))
  };
}

function shouldUseStructuredRenderer(input = "", images = [], resources = []) {
  if (images.length || resources.length) {
    return false;
  }
  if (isContextRepairMessage(input)) {
    return false;
  }

  return shouldChooseQuestionTypeForUser(input)
    || wantsButterflyFormatCorrection(input)
    || wantsConceptDiagram(input)
    || wantsRandomPracticeRequest(input)
    || wantsSameQuestionTypeFollowup(input)
    || wantsDefaultStandardQuestion(input)
    || wantsTestFormatList(input)
    || wantsTestCreationSetup(input)
    || wantsGenericPracticeProblem(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsCjeChallenge(input)
    || wantsStandardQuestionGeneration(input);
}

function wantsRepeatReadRequest(input = "") {
  const lower = normalizeIntentText(input);
  return /\b(can you|could you|please|ani)?\s*(repeat|read|say)\b.{0,80}\b(again|back|out loud|aloud|that|this|rationale|question|answer|explanation|diagram|case)\b/i.test(lower)
    || /\b(repeat|read)\s+(?:the\s+)?(last|rationale|question|answer|explanation|diagram|case)\b/i.test(lower);
}

function latestAssistantBubble() {
  return Array.from(document.querySelectorAll(".message.assistant .bubble")).at(-1) || null;
}

function latestAssistantReadableText() {
  return readableTextFromElement(latestAssistantBubble(), lastAssistantText);
}

function sectionFromReadableText(text = "", input = "") {
  const lower = normalizeIntentText(input);
  const source = String(text || "").trim();
  if (!source) {
    return { label: "last response", text: "" };
  }

  if (/\b(diagram|visual|picture|image|map)\b/i.test(lower)) {
    return { label: "diagram", text: source };
  }
  if (/\b(case|chart)\b/i.test(lower)) {
    return { label: "case", text: source };
  }

  const sectionPatterns = [
    ["rationale", /\b(rationale|why|explain)\b/i, /(?:Rationale:|Overall rationale:)([\s\S]*?)(?:NCLEX applicability:|Nook-and-cranny detail:|Trap:|Let me know|$)/i],
    ["NCLEX essential", /\b(nclex|essential|high yield|important)\b/i, /(?:NCLEX essential:|NCLEX applicability:)([\s\S]*?)(?:Nook-and-cranny detail:|Trap:|Let me know|$)/i],
    ["question", /\b(question|stem|prompt)\b/i, /(?:NCLEX-style item:|Complete the butterfly answer\.|Question\s*\d*:)([\s\S]*?)(?:Difficulty:|A\.|Priority interventions|Most likely condition|$)/i],
    ["answer choices", /\b(answer choices|choices|options)\b/i, /(A\.[\s\S]*?)(?:Whenever you're ready|Grade|$)/i]
  ];

  for (const [label, intentPattern, textPattern] of sectionPatterns) {
    if (!intentPattern.test(lower)) {
      continue;
    }
    const match = textPattern.exec(source);
    if (match?.[1]?.trim()) {
      return { label, text: match[1].trim() };
    }
  }

  return { label: "last response", text: source };
}

function makeRepeatReadResponse(input = "") {
  const section = sectionFromReadableText(latestAssistantReadableText(), input);
  if (!section.text) {
    return "I do not have anything recent to reread yet. Ask me a question or have me generate an item, then I can repeat any section.";
  }
  return {
    type: "read-repeat",
    message: `Of course. I will read the ${section.label} again.`,
    text: section.text
  };
}

function cleanModelTextForDisplay(text = "") {
  return String(text || "")
    .replace(/^\s{0,3}#{1,6}\s+/gm, "")
    .trim();
}

function clipModelContextText(text = "", limit = MAX_MODEL_CONTEXT_MESSAGE_CHARS) {
  const value = String(text || "").replace(/\s+/g, " ").trim();
  if (value.length <= limit) {
    return value;
  }
  return `${value.slice(0, Math.max(0, limit - 24)).trim()} ... [trimmed]`;
}

function modelContextMessages(messages = [], limit = MAX_MODEL_CONTEXT_MESSAGES, textLimit = MAX_MODEL_CONTEXT_MESSAGE_CHARS) {
  return messages
    .filter((message) => !isHiddenStoredMessage(message))
    .slice(-limit)
    .map((message) => ({
      ...message,
      text: clipModelContextText(message.text, textLimit)
    }));
}

async function requestAdaptiveTextResponse(input = "", images = [], resources = [], localDraft = "", options = {}) {
  if (!ANI_ONLINE_AI_ENABLED) {
    return options.allowFallbackText ? lane4RuntimeFallbackForQuestion(input) : "";
  }
  const modelContext = lane4BoundedModelContext(input, getAniModelContext(input));
  const effectiveLocalDraft = lane4BoundedEscalationDraft(input, localDraft);
  const lane4AiStartedAt = lane4RecordExternalAiAttempt(input, modelContext, effectiveLocalDraft);
  if (voiceStatus) voiceStatus.textContent = "Using AI for a bounded custom response...";
  try {
    const response = await fetchApi("/api/ani/respond", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        message: input,
        images: images.map((image) => ({
          name: image.name,
          type: image.type,
          dataUrl: image.dataUrl
        })),
        resources: resources.map((resource) => ({
          name: resource.name,
          type: resource.type,
          size: resource.size
        })),
        localDraft: effectiveLocalDraft,
        feature: options.feature || "adaptive_chat",
        context: modelContext
      })
    });

    const data = await response.json().catch(() => ({}));
    aniBackendReachable = true;
    if (!response.ok || !data.text?.trim()) {
      applyModelMemoryUpdates(data.memoryUpdates);
      if (response.status === 503) {
        aniModelAvailable = false;
      }
      lane4RecordExternalAiResult(false, lane4AiStartedAt, Boolean(options.allowFallbackText));
      if (options.allowFallbackText && data.text?.trim()) {
        return cleanModelTextForDisplay(data.text);
      }
      return options.allowFallbackText ? lane4RuntimeFallbackForQuestion(input) : "";
    }

    if (data.fallback) {
      applyModelMemoryUpdates(data.memoryUpdates);
      if (/api key|not configured|quota|billing|openai/i.test(data.error || data.text || "")) {
        aniModelAvailable = !/api key|not configured/i.test(data.error || data.text || "");
      }
      lane4RecordExternalAiResult(false, lane4AiStartedAt, Boolean(options.allowFallbackText));
      return options.allowFallbackText
        ? lane4RuntimeFallbackForQuestion(input) || cleanModelTextForDisplay(data.text)
        : "";
    }

    if (data.processedInput?.corrections?.length) {
      console.info("ANI autocorrected input", data.processedInput.corrections);
    }

    applyModelMemoryUpdates(data.memoryUpdates);
    aniModelAvailable = true;
    lane4RecordExternalAiResult(true, lane4AiStartedAt, false);
    return cleanModelTextForDisplay(data.text);
  } catch (error) {
    aniBackendReachable = false;
    lane4RecordExternalAiResult(false, lane4AiStartedAt, Boolean(options.allowFallbackText));
    return options.allowFallbackText
      ? lane4RuntimeFallbackForQuestion(input) || backendUnavailableMessage()
      : "";
  }
}

async function refreshAniModelStatus() {
  if (!ANI_ONLINE_AI_ENABLED) {
    aniBackendReachable = false;
    aniModelAvailable = false;
    document.body.dataset.aniModelMode = "local";
    if (voiceStatus) voiceStatus.textContent = "Voice ready";
    return;
  }
  try {
    const response = await fetchApi("/api/ani/status", {
    });
    if (!response.ok) {
      aniBackendReachable = true;
      return;
    }

    const status = await response.json();
    aniBackendReachable = true;
    aniModelAvailable = Boolean(status.llmAvailable);
    document.body.dataset.aniModelMode = status.mode || "unknown";
    if (!status.llmAvailable && voiceStatus) {
      voiceStatus.textContent = OPENAI_REQUIRED_MESSAGE;
    } else if (voiceStatus && voiceStatus.textContent === OPENAI_REQUIRED_MESSAGE) {
      voiceStatus.textContent = "Voice ready";
    }
  } catch (error) {
    aniBackendReachable = false;
    document.body.dataset.aniModelMode = "unknown";
    if (voiceStatus) {
      voiceStatus.textContent = "Voice ready";
    }
  }
}

function makeStructuredQuestionFallback(input = "", format = "advanced") {
  try {
    if (format === "cje") {
      return makeCjeChallenge(input);
    }
    if (format === "unfolding") {
      return makeUnfoldingCaseChallenge(input);
    }
    if (format === "standard") {
      return formatQuestion(nextQuestionData(input), input);
    }
    if (format === "surprise") {
      return makeSurpriseQuestionTypeChallenge(input);
    }
    return makeAdvancedItemChallenge(input);
  } catch (error) {
    return null;
  }
}

const baseOfflineHighYieldDrugClueMatch = highYieldDrugClueMatch;

let lane4RuntimeCandidates = null;
let lane4RuntimeContentVersion = "";
let lane4LastEscalationPlan = null;

function lane4RuntimeFieldValues(...values) {
  return values.filter((value) => value != null && value !== "");
}

function lane4RuntimeAliases(record = {}) {
  return [
    ...(record.aliases || []),
    ...(record.synonyms || []),
    ...(record.brandNames || []),
    ...(record.brandExamples || []),
    ...(record.tradeNames || []),
    ...(record.abbreviations || []),
    ...(record.commonMisspellings || []),
    record.generic,
    record.displayName,
    record.officialName
  ].filter(Boolean);
}

function lane4RuntimeFields(record = {}, type = "reference") {
  if (type === "drug" && isNavigationOnlyGeneratedMedicationClass(record)) {
    return {
      definition: lane4RuntimeFieldValues(generatedMedicationClassNavigationDescription(record.generatedClassSegment, record.classExampleNames)),
      overview: [],
      causes: [],
      mechanism: [],
      pathophysiology: [],
      symptoms: [],
      diagnostics: [],
      interpretation: [],
      normalRange: [],
      treatments: [],
      medicationClasses: lane4RuntimeFieldValues(record.class, pharmClassPathwayText(record)),
      uses: [],
      adverseEffects: [],
      contraindications: [],
      pregnancy: [],
      nursingInterventions: [],
      complications: [],
      patientEducation: [],
      safetyWarnings: [],
      redFlags: []
    };
  }
  const populationRisks = Array.isArray(record.populationRisks) ? record.populationRisks : [];
  const pregnancyRisks = populationRisks.filter((risk) => risk?.type === "pregnancy" || /pregnan|fetal|embryo/i.test(`${risk?.label || ""} ${risk?.note || ""}`));
  return {
    definition: lane4RuntimeFieldValues(record.definition, record.summary, record.description, record.pathology, record.plainMeaning, record.introduction),
    overview: lane4RuntimeFieldValues(record.overview, record.clinicalOverview, record.quickSummary),
    causes: lane4RuntimeFieldValues(record.causes, record.etiology, record.riskFactors, record.triggers),
    mechanism: lane4RuntimeFieldValues(record.mechanism, record.mechanismOfAction, record.howItWorks, record.pharmacodynamics),
    pathophysiology: lane4RuntimeFieldValues(record.pathophysiology, record.diseaseProcess, record.pathology),
    symptoms: lane4RuntimeFieldValues(record.symptoms, record.signsSymptoms, record.signsAndSymptoms, record.clinicalFeatures, record.assessmentFindings, record.manifestations),
    diagnostics: lane4RuntimeFieldValues(record.diagnostics, record.diagnosticTests, record.workup, record.testing, record.screening, record.resultMeanings),
    interpretation: lane4RuntimeFieldValues(record.interpretation, record.resultMeanings, record.clinicalSignificance, record.highMeaning, record.lowMeaning),
    normalRange: lane4RuntimeFieldValues(record.normalRange, record.range, record.referenceRange, record.adultRange, record.value),
    treatments: lane4RuntimeFieldValues(record.treatments, record.treatment, record.management, record.medications, record.interventions),
    medicationClasses: lane4RuntimeFieldValues(record.medicationClasses, record.drugClasses, record.pharmacologicClass, type === "drug" ? record.class : ""),
    uses: lane4RuntimeFieldValues(record.uses, record.indications, record.clinicalUses, record.treatmentRole),
    adverseEffects: lane4RuntimeFieldValues(record.adverseEffects, record.sideEffects, record.majorAdverseEffects, record.toxicities),
    contraindications: lane4RuntimeFieldValues(record.contraindications, record.precautions, record.doNotUse, record.boxedWarning),
    pregnancy: lane4RuntimeFieldValues(record.pregnancy, record.pregnancySafety, record.reproductiveSafety, pregnancyRisks),
    nursingInterventions: lane4RuntimeFieldValues(record.nursingInterventions, record.nursingEssentials, record.nursingPriorities, record.nursingConsiderations, record.priorityActions, record.monitoring),
    complications: lane4RuntimeFieldValues(record.complications, record.majorComplications),
    patientEducation: lane4RuntimeFieldValues(record.patientEducation, record.teaching, record.patientTeaching, record.dischargeTeaching),
    safetyWarnings: lane4RuntimeFieldValues(record.safetyWarnings, record.warnings, record.boxedWarning, record.nclexTraps),
    redFlags: lane4RuntimeFieldValues(record.redFlags, record.emergencySigns, record.whenToEscalate)
  };
}

function buildLane4RuntimeCandidates() {
  if (lane4RuntimeCandidates) return lane4RuntimeCandidates;
  const candidates = [];
  const add = (record = {}, type = "reference", index = 0) => {
    const title = type === "drug"
      ? pharmDrugDisplayName(record, "")
      : type === "clinical-reference"
        ? clinicalReferenceDisplayName(record)
        : safeText(record.name || record.displayName || record.generic || record.title);
    if (!title) return;
    candidates.push({
      id: `${type}:${normalizePharmText(title).replace(/\s+/g, "-") || index}`,
      title,
      type,
      category: safeText(record.category || record.class || record.type || record.sourceType),
      aliases: lane4RuntimeAliases(record),
      fields: lane4RuntimeFields(record, type)
    });
  };
  pharmDrugs.forEach((record, index) => add(record, "drug", index));
  pathologyDiseases.forEach((record, index) => add(record, "disease", index));
  clinicalReferenceEntries.forEach((record, index) => add(record, "clinical-reference", index));
  pharmSearchableLabRanges.forEach((record, index) => add(record, "lab", index));
  holisticRemedies.forEach((record, index) => add(record, "holistic", index));
  lane4RuntimeCandidates = window.AniLane4Runtime?.prepareCandidates
    ? window.AniLane4Runtime.prepareCandidates(candidates)
    : candidates;
  return lane4RuntimeCandidates;
}

function lane4RuntimeMode(input = "") {
  if (clinicalModeActive) return "clinical";
  if (lectureModePrimed || lectureState.active || /\blecture mode\b/i.test(input)) return "lecture";
  if (/\b(encyclopedia|database|reference card|reference entry)\b/i.test(input)) return "encyclopedia";
  return "general";
}

function lane4RuntimeCanAnswerLocally(input = "") {
  const normalized = normalizeIntentText(input);
  if (!normalized || /\b(full lecture|audio lecture|generate (?:a )?lecture|practice question|nclex question|case study|bow tie|butterfly|dosage calculation)\b/i.test(normalized)) return false;
  return true;
}

function tryLane4RuntimeAnswer(input = "", options = {}) {
  const runtimeApi = window.AniLane4Runtime;
  if (!runtimeApi?.defaultRuntime || !lane4RuntimeCanAnswerLocally(input)) return "";
  const candidates = buildLane4RuntimeCandidates();
  if (!lane4RuntimeContentVersion) {
    lane4RuntimeContentVersion = runtimeApi.contentVersionForCandidates(candidates, runtimeApi.SAFETY_RULES_VERSION);
  }
  const result = runtimeApi.defaultRuntime.answerLocal({
    question: input,
    candidates,
    mode: options.mode || lane4RuntimeMode(input),
    contentVersion: lane4RuntimeContentVersion,
    useCache: options.useCache !== false
  });
  lane4LastEscalationPlan = result.path === "escalate" ? result : null;
  window.__ANI_LANE4_LAST_RESULT__ = result;
  return result.path === "local" || result.path === "cache" ? result.answer : "";
}

function lane4RuntimeFallbackForQuestion(input = "") {
  const runtimeApi = window.AniLane4Runtime;
  if (!runtimeApi || !lane4LastEscalationPlan?.fallbackAnswer) return "";
  return runtimeApi.normalizeQuestion(input) === lane4LastEscalationPlan.normalizedQuestion
    ? lane4LastEscalationPlan.fallbackAnswer
    : "";
}

function lane4MatchingEscalationPlan(input = "") {
  const runtimeApi = window.AniLane4Runtime;
  if (!runtimeApi || !lane4LastEscalationPlan?.aiEscalation) return null;
  return runtimeApi.normalizeQuestion(input) === lane4LastEscalationPlan.normalizedQuestion
    ? lane4LastEscalationPlan
    : null;
}

function lane4BoundedModelContext(input = "", baseContext = {}) {
  const plan = lane4MatchingEscalationPlan(input);
  if (!plan) return baseContext;
  const needsImmediateHistory = plan.intent?.id === "conversational_ambiguous"
    || /\b(it|that|this|these|those|previous|earlier|above|follow[ -]?up)\b/i.test(input);
  return {
    currentTopic: baseContext.currentTopic,
    currentDifficulty: baseContext.currentDifficulty,
    depth: baseContext.depth,
    conversationStyleHint: baseContext.conversationStyleHint,
    lastQuestion: needsImmediateHistory ? baseContext.lastQuestion : null,
    explicitMemory: Array.isArray(baseContext.explicitMemory) ? baseContext.explicitMemory.slice(-4) : [],
    customMemory: Array.isArray(baseContext.customMemory) ? baseContext.customMemory.slice(0, 4) : [],
    activeChatTitle: baseContext.activeChatTitle,
    activeChatMessages: needsImmediateHistory && Array.isArray(baseContext.activeChatMessages)
      ? modelContextMessages(baseContext.activeChatMessages, 4, 700)
      : [],
    recentConversation: needsImmediateHistory && Array.isArray(baseContext.recentConversation)
      ? modelContextMessages(baseContext.recentConversation, 3, 700)
      : []
  };
}

function lane4BoundedEscalationDraft(input = "", localDraft = "") {
  const plan = lane4MatchingEscalationPlan(input);
  if (!plan) return localDraft;
  const packet = plan.aiEscalation?.context;
  const contextText = packet
    ? `Lane 4 deterministic retrieval packet (${plan.aiEscalation.reason}): ${JSON.stringify(packet)}`
    : "";
  return [String(localDraft || "").trim(), contextText]
    .filter(Boolean)
    .join("\n\n")
    .slice(0, 5000);
}

function lane4RecordExternalAiAttempt(input = "", context = {}, localDraft = "") {
  const runtime = window.AniLane4Runtime?.defaultRuntime;
  if (!runtime) return 0;
  const characters = JSON.stringify({ input, context, localDraft }).length;
  const plan = lane4MatchingEscalationPlan(input);
  const reason = plan?.aiEscalation?.reason || "existing-specialized-ai-route";
  runtime.recordExternalAiAttempt({ estimatedTokens: Math.ceil(characters / 4), reason });
  window.__ANI_LANE4_LAST_AI_REASON__ = reason;
  return performance.now();
}

function lane4RecordExternalAiResult(success, startedAt = 0, fallback = false) {
  const runtime = window.AniLane4Runtime?.defaultRuntime;
  if (!runtime) return;
  const latency = startedAt ? Math.max(0, performance.now() - startedAt) : 0;
  runtime.recordExternalAiResult(Boolean(success), latency);
  if (fallback) runtime.recordExternalFallback(latency);
}

function lane4MetricsPercent(value = 0) {
  return `${(Math.max(0, Number(value || 0)) * 100).toFixed(1)}%`;
}

function renderLane4MetricsDiagnostics() {
  if (!lane4MetricsPanel) return;
  const runtimeApi = window.AniLane4Runtime;
  const enabled = Boolean(runtimeApi?.metricsDiagnosticsAllowed?.(window.location));
  lane4MetricsPanel.hidden = !enabled;
  if (!enabled) return;
  const metrics = runtimeApi?.defaultRuntime?.metrics?.();
  const view = runtimeApi?.aggregateMetricsView?.(metrics || {});
  if (!view) {
    setText(lane4MetricsSummary, "Lane 4 metrics are unavailable in this build.");
    setText(lane4MetricsLatency, "No prompt text or account data is included.");
    return;
  }
  setText(lane4MetricsSummary, [
    `${formatWholeNumber(view.totalQuestions)} questions`,
    `${formatWholeNumber(view.locallyAnsweredQuestions)} local`,
    `${formatWholeNumber(view.cachedAnswers)} cache`,
    `${formatWholeNumber(view.aiEscalatedQuestions)} AI escalations`,
    `${formatWholeNumber(view.failedAiCalls)} AI failures`,
    `${formatWholeNumber(view.fallbackAnswers)} fallbacks`,
    `${lane4MetricsPercent(view.localAnswerRate)} local-answer rate`,
    `${lane4MetricsPercent(view.cacheHitRate)} cache-hit rate`,
    `${lane4MetricsPercent(view.aiEscalationRate)} AI-escalation rate`,
    `${lane4MetricsPercent(view.aiCallFailureRate)} AI failure rate`,
    `${lane4MetricsPercent(view.fallbackSuccessRate)} fallback success`,
    `${view.averageRetrievedEntryCount} avg retrieved`,
    `${view.averageSelectedContextCount} avg selected`,
    `${formatWholeNumber(view.estimatedTokensSent)} estimated AI tokens`,
    `${formatWholeNumber(view.duplicateAiCallsAvoided)} duplicate calls avoided`
  ].join(" · "));
  setText(lane4MetricsLatency, `Average latency — local ${view.averageLatencyMs.local} ms; cache ${view.averageLatencyMs.cache} ms; AI ${view.averageLatencyMs.ai} ms; fallback ${view.averageLatencyMs.fallback} ms. Aggregate-only; no prompt or account data.`);
}

async function makeModelEnhancedResponse(input = "", images = [], resources = []) {
  offlineMissQueuedForCurrentMessage = false;
  if (explicitMemoryRequest(input)) {
    return makeTeachingResponse(input, images, resources);
  }

  const imageScanContext = images.length
    ? await scanImagesForTextContext(input, images)
    : null;
  const imageVisionScanContext = images.length
    ? await scanImagesForVisionContext(input, images)
    : null;
  const visionMatch = bestVisionMatchCandidate(imageVisionScanContext || {});
  const topVisionPrediction = imageVisionScanContext?.bestPrediction;
  const imageLocalDraft = [imageScanContext?.localDraft, imageVisionScanContext?.localDraft]
    .filter(Boolean)
    .join("\n\n");

  if (!resources.length && images.length && visionMatch && topVisionPrediction && isVisionAutoOpenSafe(input, visionMatch, topVisionPrediction)) {
    const candidate = visionMatch.candidate;
    const label = offlineLookupEntityLabel(candidate);
    const percent = formatVisionConfidencePercent(topVisionPrediction.confidence || visionMatch.score);
    const reason = String(topVisionPrediction.description || topVisionPrediction.entityType || "").trim();
    const differentialTerms = Array.isArray(imageVisionScanContext?.differential) ? imageVisionScanContext.differential : [];
    const differentialText = differentialTerms.length
      ? `Differential consideration: ${differentialTerms.slice(0, 3).map((term) => String(term || "").trim()).filter(Boolean).join(", ")}.`
      : "";
    const redirect = offlineLookupDatabaseRedirect(candidate, input);
    if (!redirect || typeof redirect !== "object") {
      return `I am ${percent} confident this image is most consistent with **${label}**. ${reason ? `${reason}. ` : ""}${differentialText} I can still help with differential if you want the alternatives.`;
    }
    return {
      ...redirect,
      preface: `I am ${percent} confident this image is most consistent with **${label}**. ${reason ? `${reason}. ` : ""}${differentialText} I can still help with differential if you want the alternatives.`
    };
  }

  const wantsExplicitGeneratedStudyArtifact = wantsCjeChallenge(input)
    || wantsUnfoldingCase(input)
    || wantsAdvancedItem(input)
    || wantsStandardQuestionGeneration(input)
    || wantsConceptDiagram(input);
  const explicitLectureRequest = lectureModePrimed
    || lectureState.active
    || /\b(lecture|lecture mode|full lecture|audio lecture)\b/i.test(normalizeIntentText(input));
  const sharedTopicRequest = !images.length && !resources.length
    ? resolveTopicRequest(input, { mode: "navigate", limit: 8 })
    : null;
  const sharedClinicalClueOwnsRequest = sharedTopicRequest?.resolutionKind === "clinical-clue";
  const sharedReviewedRouteOwnsRequest = ["reviewed-route", "ambiguous-reviewed-route"]
    .includes(sharedTopicRequest?.resolutionKind);
  const sharedNonIdentityRouteOwnsRequest = sharedClinicalClueOwnsRequest
    || sharedReviewedRouteOwnsRequest;
  if (!images.length && !resources.length && wantsOfflineAbgInterpretationAnswer(input)) {
    return makeOfflineAbgInterpretationAnswer(input);
  }
  if (!images.length && !resources.length && wantsOfflinePotassiumDangerAnswer(input)) {
    return makeOfflinePotassiumDangerAnswer(input);
  }
  if (!images.length && !resources.length && !wantsExplicitGeneratedStudyArtifact) {
    const pregnancySafetyAnswer = makeOfflineTeratogenicDrugListResponse(input);
    if (pregnancySafetyAnswer) return pregnancySafetyAnswer;
    const emergencyHyperkalemiaAnswer = makeOfflineEmergencyHyperkalemiaAnswer(input);
    if (emergencyHyperkalemiaAnswer) return emergencyHyperkalemiaAnswer;
    // Reviewed local answer builders own clinically specific interpretation
    // requests before the generic card/section extractor. Otherwise a query
    // such as "sodium 118 with confusion" can be flattened into the broad
    // Sodium card even though ANI has a safer, more specific bedside answer.
    const smartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(input);
    if (smartDatabaseAnswer) return smartDatabaseAnswer;
    const focusedSafetyAnswer = makeOfflineSeizureFirstActionAnswer(input)
      || makeOfflineAnaphylaxisFirstActionAnswer(input);
    if (focusedSafetyAnswer) return focusedSafetyAnswer;
    const focusedLocalAnswer = makeOfflinePreRuntimeFocusedAnswer(input);
    if (focusedLocalAnswer) return focusedLocalAnswer;
    // A user who names one encyclopedia card and one requested section has
    // already supplied enough intent to answer locally. Resolve that stable
    // card/section pair before broader answer-engine routing can substitute an
    // associated medication, complication, or similarly worded topic.
    const focusedSegmentResponse = makeOfflineSegmentResponse(input);
    if (focusedSegmentResponse) return focusedSegmentResponse;
    const lane4LocalAnswer = tryLane4RuntimeAnswer(input);
    if (lane4LocalAnswer) return lane4LocalAnswer;
  }
  if (!images.length && !resources.length && !wantsExplicitGeneratedStudyArtifact && !explicitLectureRequest) {
    const immediateExactPathologyTitle = exactUnambiguousPathologyTitleMatch(input);
    if (immediateExactPathologyTitle && !wantsMedicationClassLookup(input)) {
      return offlineLookupDatabaseRedirect({
        type: "pathology",
        item: immediateExactPathologyTitle,
        score: scorePathologyEntry(immediateExactPathologyTitle, input) + 3000
      }, input);
    }
    if (sharedNonIdentityRouteOwnsRequest
      && sharedTopicRequest.mayAutoOpen
      && sharedTopicRequest.preferred?.item) {
      return offlineLookupDatabaseRedirect(sharedTopicRequest.preferred, input);
    }
    // Once the shared resolver has reviewed evidence for this request, older
    // domain-specific clue routers must not replace that decision. A reviewed
    // route that is ambiguous, personal, or suggestion-only should continue
    // to the shared choice/clarification flow instead of being auto-opened by
    // a legacy high-yield shortcut.
    const immediateSpecificDrugClueMatch = sharedNonIdentityRouteOwnsRequest
      ? null
      : highYieldDrugClueMatch(input);
    if (immediateSpecificDrugClueMatch) {
      return offlineLookupDatabaseRedirect({
        type: "drug",
        item: immediateSpecificDrugClueMatch,
        score: 2700 + pharmIdentityPreferenceScore(immediateSpecificDrugClueMatch)
      }, input);
    }
    const immediatePathologyClueMatch = sharedNonIdentityRouteOwnsRequest
      ? null
      : highYieldPathologyClueMatch(input);
    if (immediatePathologyClueMatch) {
      return offlineLookupDatabaseRedirect({
        type: "pathology",
        item: immediatePathologyClueMatch,
        score: scorePathologyEntry(immediatePathologyClueMatch, input) + 2700
      }, input);
    }
  }

  if (!images.length && !resources.length && shouldHandleLectureMode(input)) {
    return makeLectureModeResponse(input);
  }
  if (!images.length && !resources.length && !wantsAiGeneratedStudyWork(input)) {
    const offlineVisual = makeOfflineVisualResponse(input);
    if (offlineVisual) {
      return offlineVisual;
    }
  }

  if (!images.length && !resources.length && !wantsAiGeneratedStudyWork(input)) {
    const offlineListAnswer = makeOfflineListResponse(input);
    if (offlineListAnswer) {
      const listSpecificDrugClueMatch = sharedNonIdentityRouteOwnsRequest
        ? null
        : highYieldDrugClueMatch(input);
      if (listSpecificDrugClueMatch) {
        return offlineLookupDatabaseRedirect({
          type: "drug",
          item: listSpecificDrugClueMatch,
          score: 2550 + pharmIdentityPreferenceScore(listSpecificDrugClueMatch)
        }, input);
      }
      return offlineListAnswer;
    }
    if (wantsOfflineListAiExpansionFallback(input)) {
      const context = freshOfflineListContext();
      const localLimit = offlineListExpansionLocalLimitResponse(context);
      const adaptiveResponse = await requestAdaptiveTextResponse(
        offlineListExpansionModelPrompt(input, context),
        images,
        resources,
        localLimit,
        {
          allowFallbackText: true,
          feature: "offline_list_expansion"
        }
      );
      if (adaptiveResponse && !looksLikeBackendUnavailableText(adaptiveResponse)) {
        return adaptiveResponse;
      }
      return localLimit || adaptiveResponse || aiUnavailableMessage();
    }
    const earlySpecificDrugClueMatch = sharedNonIdentityRouteOwnsRequest
      ? null
      : highYieldDrugClueMatch(input);
    // curated-high-confidence-clue-before-broad-smart-segments
    if (earlySpecificDrugClueMatch) {
      return offlineLookupDatabaseRedirect({
        type: "drug",
        item: earlySpecificDrugClueMatch,
        score: 2600 + pharmIdentityPreferenceScore(earlySpecificDrugClueMatch)
      }, input);
    }
    const offlineSegmentAnswer = makeOfflineSegmentAnswer(input);
    if (offlineSegmentAnswer) {
      return offlineSegmentAnswer;
    }
    // frontier-wave13-smart-answer-before-broad-specialty-reference
    const earlyOfflineReferenceAnswer = makeOfflineReferenceAnswerInChat(input);
    if (earlyOfflineReferenceAnswer) {
      return earlyOfflineReferenceAnswer;
    }
    const offlineClinicalReference = makeOfflineClinicalReferenceResponse(input);
    if (offlineClinicalReference && wantsSpecialtyReference(input)) {
      return offlineClinicalReference;
    }
  }

  if (!images.length && !resources.length) {
    const offlineComparison = makeOfflineLabComparisonResponse(input);
    if (offlineComparison) {
      return offlineComparison;
    }
  }

  if (!images.length && !resources.length && !wantsAiGeneratedStudyWork(input)) {
    const offlineReferenceAnswer = makeOfflineReferenceAnswerInChat(input);
    if (offlineReferenceAnswer) {
      return offlineReferenceAnswer;
    }
  }

  if (!images.length && !resources.length) {
    const offlineFlow = handleOfflineLookupFlow(input, {
      force: shouldUseOfflineLookupCore() || !shouldUseAiForUserRequest(input),
      preferDatabaseRedirect: true
    });
    if (offlineFlow) {
      return offlineFlow;
    }
  }

  if (!images.length && !resources.length && wantsPharmDatabase(input)) {
    return {
      type: "pharm-database",
      query: normalizePharmText(input).replace(/\b(open|show|the|pharm|pharmacy|pharmacology|lab|laboratory|pathology|pathologies|disease|clinical|holistic|herbal|herbals|supplement|supplements|database|encyclopedia|reference|library|drug|medication)\b/g, " ").replace(/\s+/g, " ").trim()
    };
  }

  if (!images.length && !resources.length && !shouldUseAiForUserRequest(input) && wantsOfflinePathologyLookup(input)) {
    return makeOfflinePathologyResponse(input);
  }

  if (!images.length && !resources.length && !shouldUseAiForUserRequest(input) && wantsOfflineHolisticLookup(input)) {
    return makeOfflineHolisticResponse(input);
  }

  if (!images.length && !resources.length && !shouldUseAiForUserRequest(input) && wantsOfflinePharmLookup(input)) {
    return makeOfflinePharmResponse(input);
  }

  if (!images.length && !resources.length && wantsRepeatReadRequest(input)) {
    return makeRepeatReadResponse(input);
  }

  if (!images.length
    && !resources.length
    && hasActiveButterflyContext()
    && wantsButterflyStructureExplanation(input)) {
    return makeButterflyStructureExplanation();
  }

  if (!images.length && !resources.length && wantsButterflyFormatCorrection(input)) {
    return makeButterflyFormatCorrectionResponse(input);
  }

  if (!images.length && !resources.length && wantsConceptDiagram(input)) {
    return {
      type: "concept-diagram",
      diagram: makeConceptDiagram(input)
    };
  }

  if (!images.length
    && !resources.length
    && wantsCjeChallenge(input)
    && /\b(butterfly|bow[-\s]?tie|surprise me|random|your choice|whatever)\b/i.test(normalizeIntentText(input))) {
    return makeCjeChallenge(input);
  }

  if (!images.length
    && !resources.length
    && !wantsCjeChallenge(input)
    && !wantsUnfoldingCase(input)
    && !wantsAdvancedItem(input)
    && !wantsStandardQuestionGeneration(input)
    && asksDeepActiveQuestionFollowup(input)) {
    const localDraft = activeStandardDeepDiveDraft(input);
    const adaptiveResponse = await requestAdaptiveTextResponse(input, images, resources, localDraft, {
      allowFallbackText: true
    });
    return adaptiveResponse || makeActiveQuestionDeepDiveFallback(input) || aiUnavailableMessage();
  }

  if (!images.length
    && !resources.length
    && !wantsCjeChallenge(input)
    && !wantsUnfoldingCase(input)
    && !wantsAdvancedItem(input)
    && !wantsStandardQuestionGeneration(input)
    && !isClearFreshQuestionRequest(input)) {
    const activeStandardResponse = makeActiveStandardQuestionResponse(input);
    if (activeStandardResponse) {
      return activeStandardResponse;
    }
  }

  if (!images.length && !resources.length && wantsSameQuestionTypeFollowup(input)) {
    const sameTypeResponse = await makeSameQuestionTypeFollowupResponse(input);
    if (sameTypeResponse) {
      return sameTypeResponse;
    }
  }

  if (!images.length
    && !resources.length
    && (shouldChooseQuestionTypeForUser(input) || (wantsAvoidStandardQuestionFormat(input) && isClearFreshQuestionRequest(input)))) {
    const variedResponse = await makeRandomizedQuestionTypeResponse(input, {
      allowStandard: !wantsAvoidStandardQuestionFormat(input)
    });
    if (variedResponse) {
      return variedResponse;
    }
  }

  if (!images.length && !resources.length && wantsRandomPracticeRequest(input)) {
    const plan = randomPracticePlan(input);
    const prompt = randomPracticePrompt(plan, input);
    if (plan.mode === "standard") {
      const generatedQuestion = await requestGeneratedStandardQuestion(prompt);
      if (generatedQuestion) {
        currentTopic = generatedQuestion.topic;
        saveDifficulty(generatedQuestion.difficulty);
        updateFocus();
        return formatQuestion(generatedQuestion, prompt);
      }
      return makeRandomPracticeFallback(plan, input);
    }

    if (plan.mode === "butterfly") {
      const generatedCase = await requestGeneratedCjeCase(prompt);
      if (generatedCase) {
        currentTopic = generatedCase.topic;
        saveDifficulty("hard");
        updateFocus();
        return {
          type: "cje-case",
          caseItem: generatedCase
        };
      }
      return makeRandomPracticeFallback(plan, input);
    }

    const generatedItem = await requestGeneratedAdvancedItem(prompt);
    if (generatedItem) {
      currentTopic = generatedItem.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "advanced-item",
        item: generatedItem
      };
    }
    return makeRandomPracticeFallback(plan, input) || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && !resources.length && wantsDefaultStandardQuestion(input)) {
    const generatedQuestion = await requestGeneratedStandardQuestion(`${input}\nDefault to one standard NCLEX one-best-answer MCQ. Do not open the format picker.`);
    if (generatedQuestion) {
      currentTopic = generatedQuestion.topic;
      saveDifficulty(generatedQuestion.difficulty);
      updateFocus();
      return formatQuestion(generatedQuestion, input);
    }
    return formatQuestion(nextQuestionData(input), input);
  }

  if (wantsTestFormatList(input) || wantsGenericPracticeProblem(input) || wantsTestCreationSetup(input)) {
    return {
      type: "test-format-picker",
      wantsPractice: wantsGenericPracticeProblem(input) || wantsTestCreationSetup(input)
    };
  }

  const recordedStandardAnswer = maybeRecordActiveStandardAnswer(input);
  if (recordedStandardAnswer) {
    const feedback = recordedStandardAnswer.result?.feedback || "I read that as your answer.";
    const rationale = recordedStandardAnswer.result?.rationale || recordedStandardAnswer.item?.rationale || "";
    const trap = recordedStandardAnswer.result?.trap || recordedStandardAnswer.item?.trap || "";
    return `${feedback}\n\nRationale: ${rationale}\n\nNCLEX applicability: high. This is the kind of safety cue, priority cue, or mechanism cue the exam likes to test.\n\nNook-and-cranny detail: ${trap}\n\nLet me know if you want to explore that rationale more, compare the other options, or try another one.`;
  }

  if (!shouldUseStructuredRenderer(input, images, resources)) {
    const adaptiveResponse = await requestAdaptiveTextResponse(input, images, resources, imageLocalDraft, {
      allowFallbackText: true
    });
    return adaptiveResponse || aiUnavailableMessage();
  }

  if (!images.length && wantsUnfoldingCase(input)) {
    const caseItem = makeUnfoldingCaseChallenge(input).caseItem;
    if (caseItem) {
      currentTopic = caseItem.topic || currentTopic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "unfolding-case",
        caseItem
      };
    }
    return makeStructuredQuestionFallback(input, "unfolding") || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && wantsCjeChallenge(input)) {
    const generatedCase = await requestGeneratedCjeCase(input);
    if (generatedCase) {
      currentTopic = generatedCase.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "cje-case",
        caseItem: generatedCase
      };
    }
    return makeStructuredQuestionFallback(input, "cje") || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && wantsAdvancedItem(input)) {
    const generatedItem = await requestGeneratedAdvancedItem(input);
    if (generatedItem) {
      currentTopic = generatedItem.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "advanced-item",
        item: generatedItem
      };
    }
    return makeStructuredQuestionFallback(input, "advanced") || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && shouldChooseQuestionTypeForUser(input)) {
    const generatedItem = await requestGeneratedAdvancedItem(`${input} surprise hard NCLEX advanced item`);
    if (generatedItem) {
      currentTopic = generatedItem.topic;
      saveDifficulty("hard");
      updateFocus();
      return {
        type: "advanced-item",
        item: generatedItem
      };
    }
    return makeStructuredQuestionFallback(input, "surprise") || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && wantsStandardQuestionGeneration(input)) {
    const generatedQuestion = await requestGeneratedStandardQuestion(input);
    if (generatedQuestion) {
      currentTopic = generatedQuestion.topic;
      saveDifficulty(generatedQuestion.difficulty);
      updateFocus();
      const question = formatQuestion(generatedQuestion, input);
      return question;
    }
    return makeStructuredQuestionFallback(input, "standard") || OPENAI_ITEM_GENERATION_ERROR_MESSAGE;
  }

  if (!images.length && wantsClassSpecificExam(input)) {
    const adaptiveResponse = await requestAdaptiveTextResponse(input, images, resources, "", {
      allowFallbackText: true
    });
    return adaptiveResponse || aiUnavailableMessage();
  }

  const adaptiveResponse = await requestAdaptiveTextResponse(input, images, resources, imageLocalDraft, {
    allowFallbackText: true
  });
  if (!images.length && !resources.length && looksLikeBackendUnavailableText(adaptiveResponse)) {
    const offlineFallback = handleOfflineLookupFlow(input, {
      force: true,
      allowPrompt: false,
      preferDatabaseRedirect: true
    });
    if (offlineFallback) {
      return offlineFallback;
    }
  }
  return adaptiveResponse || aiUnavailableMessage();
}

function sendUserMessage(text, options = {}) {
  const cleaned = text.trim();
  const images = pendingImages.slice();
  const resources = pendingResources.slice();
  const directEncyclopediaTarget = options.directEncyclopediaTarget?.item
    && options.directEncyclopediaTarget?.type
    ? {
        type: options.directEncyclopediaTarget.type,
        item: options.directEncyclopediaTarget.item
      }
    : null;
  if (!cleaned && !images.length && !resources.length) {
    return;
  }

  const bypassLectureForQuestion = lectureModePrimed
    && cleaned
    && shouldBypassLectureForFreshQuestion(cleaned)
    && !wantsLecture(cleaned);
  if (bypassLectureForQuestion) {
    setLectureModeActive(false);
  }
  const shouldPrefixLecture = lectureModePrimed && cleaned && !wantsLecture(cleaned);
  const outgoingText = shouldPrefixLecture
    ? `Lecture mode: ${cleaned}`
    : cleaned || "Please analyze the uploaded attachment.";
  const baseDisplayText = shouldPrefixLecture ? cleaned : outgoingText;
  const displayText = options.displayText
    ? options.displayText
    : images.length || resources.length
    ? `${baseDisplayText}\n\n${attachmentSummary(images, resources)}`
    : baseDisplayText;
  const encyclopediaWasOpenWhenSent = Boolean(pharmDatabaseScreen && !pharmDatabaseScreen.hidden);

  retireOpenTestPickers();
  addMessage("user", displayText, true);
  messageInput.value = "";
  pendingImages = [];
  pendingResources = [];
  renderImagePreviewTray();
  if (voiceStatus) {
    voiceStatus.textContent = shouldUseStructuredRenderer(outgoingText, images, resources)
      ? "Building interactive NCLEX item with OpenAI..."
      : "Checking ANI's local reference...";
  }
  if (directEncyclopediaTarget) {
    const targetLabel = offlineLookupEntityLabel(directEncyclopediaTarget) || cleaned;
    addMessage(
      "assistant",
      `Opening **${targetLabel}** in the clinical reference.`,
      false,
      false,
      true,
      { boundEncyclopediaTarget: directEncyclopediaTarget }
    );
    openPharmDatabase(offlineLookupQuery(directEncyclopediaTarget) || targetLabel, {
      openDetail: true,
      expandDetail: true,
      autoFocus: false,
      autoRead: true,
      detailType: directEncyclopediaTarget.type,
      fastDetail: true,
      highlightQuery: cleaned || targetLabel,
      targetCandidate: directEncyclopediaTarget,
      timingSource: "chat-recommendation",
      performanceTimingToken: options.performanceTimingToken
    });
    if (voiceStatus) {
      voiceStatus.textContent = "Voice ready";
    }
    return;
  }
  const finishUserMessage = async () => {
    try {
      const response = await makeModelEnhancedResponse(outgoingText, images, resources);
    if (response?.preface && response?.type !== "pharm-database") {
      addMessage("assistant", response.preface, false, response?.type !== "pharm-database");
    }
    if (response?.type === "cje-case") {
      addCjeCaseMessage(response.caseItem);
    } else if (response?.type === "advanced-item") {
      addAdvancedItemMessage(response.item);
    } else if (response?.type === "standard-question") {
      addStandardQuestionMessage(response);
    } else if (response?.type === "unfolding-case") {
      addUnfoldingCaseMessage(response.caseItem);
    } else if (response?.type === "concept-diagram") {
      addConceptDiagramMessage(response.diagram);
    } else if (response?.type === "offline-visual") {
      addOfflineReferenceVisualMessage(response);
    } else if (response?.type === "read-repeat") {
      addMessage("assistant", response.message);
      speakTextNow(response.text);
    } else if (response?.type === "test-format-picker") {
      addTestFormatPickerMessage(response.wantsPractice);
    } else if (response?.type === "offline-comparison") {
      addOfflineComparisonMessage(response);
    } else if (response?.type === "encyclopedia-segment") {
      addMessage("assistant", response.text, false, true, true, {
        boundEncyclopediaTarget: response.target
      });
    } else if (response?.type === "missing-content") {
      addMessage("assistant", response.text, false, true, true, {
        reportProblemDraft: {
          query: response.query || outgoingText,
          category: "missing_content",
          label: "Report this missing topic"
        }
      });
    } else if (response?.type === "pharm-database") {
      const userOpenedEncyclopediaWhileWaiting = !encyclopediaWasOpenWhenSent
        && Boolean(pharmDatabaseScreen && !pharmDatabaseScreen.hidden);
      const responseTarget = response.query
        ? (response.targetCandidate?.item
          ? { type: response.targetCandidate.type, item: response.targetCandidate.item }
          : exactPharmDetailCandidate(response.query, response.detailType))
        : null;
      if (userOpenedEncyclopediaWhileWaiting) {
        addMessage(
          "assistant",
          response.preface || `I found **${response.query || "the requested topic"}** in the medical encyclopedia. Your current encyclopedia view was left in place; use this link when you are ready to open it.`,
          false,
          true,
          true,
          responseTarget ? { boundEncyclopediaTarget: responseTarget } : {}
        );
      } else {
        if (response.preface) {
          addMessage("assistant", response.preface, false, false, true,
            responseTarget ? { boundEncyclopediaTarget: responseTarget } : {});
        }
        openPharmDatabase(response.query || "", {
          openDetail: response.openDetail,
          expandDetail: response.openDetail === true,
          detailType: response.detailType,
          targetCandidate: responseTarget,
          fastDetail: true,
          highlightQuery: response.highlightQuery
        });
        if (!response.preface) {
          addMessage("assistant", "I opened the clinical reference. You can search by medication, class, interaction, warning, lab, disease, pathology, herbal, supplement, or typo-close spelling.", false, false);
        }
      }
    } else {
      addMessage("assistant", response);
    }
    } catch (error) {
      console.error("ANI could not finish the local response", error);
      addMessage(
        "assistant",
        "I could not finish that request, but the page is still ready. You can try a shorter phrase, or report the problem so it can be evaluated.",
        false,
        false,
        true,
        {
          reportProblemDraft: {
            query: safeText(outgoingText).slice(0, 180) || "ANI response error",
            category: "technical",
            label: "Report this problem"
          }
        }
      );
    } finally {
      if (voiceStatus) {
        voiceStatus.textContent = "Voice ready";
      }
    }
  };
  const queueResponseWork = () => window.setTimeout(finishUserMessage, 0);
  // Paint the submitted message first, then begin local routing during the
  // browser's next idle opportunity. This removes the old fixed 80 ms wait and
  // leaves navigation responsive before heavier fallback work begins.
  window.requestAnimationFrame(() => {
    if (window.requestIdleCallback) {
      window.requestIdleCallback(queueResponseWork, { timeout: 48 });
    } else {
      queueResponseWork();
    }
  });
}

function cleanSpeechTranscript(text = "") {
  return text
    .replace(/\b(?:um+|uh+|erm+|er+|hmm+|mm+|ah+)\b/gi, " ")
    .replace(/\s+([,.?!])/g, "$1")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function getDepthLevel() {
  return Number(depthRange?.value || DEFAULT_DEPTH_LEVEL);
}

function getDepthName() {
  return depthNames[getDepthLevel()] || depthNames[DEFAULT_DEPTH_LEVEL];
}

function updateDepth() {
  if (depthLabel) {
    depthLabel.textContent = getDepthName();
  }
}

function updateFocus() {
  const focus = getConversationFocus(getActiveChat());
  const focusText = conversationFocusDisplay(focus);
  focusLabel.textContent = ANI_LAUNCH_PROFILE === "encyclopedia"
    ? `Encyclopedia focus: ${focusText}`
    : `Adaptive NCLEX: ${focusText} | ${difficultyLabels[normalizeQuestionDifficulty(currentDifficulty)]}`;
}

chatForm.addEventListener("submit", (event) => {
  event.preventDefault();
  sendUserMessage(messageInput.value);
});

imageUploadButton?.addEventListener("click", () => {
  imageInput?.click();
});

imageInput?.addEventListener("change", () => {
  addImageFiles(imageInput.files || []);
  imageInput.value = "";
});

messageInput?.addEventListener("paste", (event) => {
  const imageFiles = Array.from(event.clipboardData?.files || [])
    .filter((file) => /^image\//i.test(file.type));
  if (imageFiles.length) {
    addImageFiles(imageFiles);
  }
});

depthRange?.addEventListener("input", updateDepth);

function resetMicUi(status = "Voice ready") {
  micActive = false;
  micButton.classList.remove("recording");
  micButton.setAttribute("aria-label", "Start microphone input");
  micButton.title = "Start microphone input";
  if (voiceStatus) {
    voiceStatus.textContent = status;
  }
}

function setMicRecordingUi(status = "Listening... click the microphone again when you are done.") {
  micActive = true;
  micButton.classList.add("recording");
  micButton.setAttribute("aria-label", "Stop microphone input");
  micButton.title = "Stop microphone input";
  if (voiceStatus) {
    voiceStatus.textContent = status;
  }
}

function canRecordMicrophoneAudio() {
  return ANI_SERVER_TRANSCRIPTION_ENABLED && Boolean(navigator.mediaDevices?.getUserMedia && window.MediaRecorder);
}

function microphoneNeedsSecureContext() {
  if (isNativeShell || window.isSecureContext) {
    return false;
  }
  return !["localhost", "127.0.0.1", "127.0.0.2"].includes(location.hostname);
}

async function getMicrophonePermissionState() {
  if (!navigator.permissions?.query) {
    return "unknown";
  }

  try {
    const permission = await navigator.permissions.query({ name: "microphone" });
    return permission.state || "unknown";
  } catch {
    return "unknown";
  }
}

function microphoneBlockedMessage() {
  return isNativeShell
    ? "Microphone access is blocked for ANI. Open Android app settings for ANI, allow Microphone, then try again."
    : "Microphone access is blocked. Open this site's microphone permission near the address bar, choose Allow, then try again.";
}

function microphoneUnavailableMessage() {
  if (canUseNativeSpeechRecognition()) {
    return "Tap ANI and speak. The installed app can use native speech recognition.";
  }
  if (microphoneNeedsSecureContext()) {
    return "Microphone access needs HTTPS, localhost, or the installed ANI app. Open ANI from localhost on this computer or use the Android app.";
  }
  return "Microphone recording is unavailable in this browser. You can still type.";
}

function microphoneConstraints() {
  return {
    audio: {
      echoCancellation: true,
      noiseSuppression: true,
      autoGainControl: true
    }
  };
}

function hasLiveMicrophoneStream(stream = mediaStream) {
  return Boolean(stream?.getAudioTracks?.().some((track) => track.readyState === "live"));
}

async function requestMicrophoneStream(options = {}) {
  const onStatus = typeof options.onStatus === "function" ? options.onStatus : () => {};

  if (!canRecordMicrophoneAudio()) {
    throw new Error(microphoneUnavailableMessage());
  }

  if (microphoneNeedsSecureContext()) {
    throw new Error(microphoneUnavailableMessage());
  }

  if (keepMicReady && hasLiveMicrophoneStream()) {
    onStatus("Microphone ready.");
    return mediaStream;
  }

  const permissionState = await getMicrophonePermissionState();
  if (permissionState === "denied") {
    const error = new Error(microphoneBlockedMessage());
    error.name = "NotAllowedError";
    throw error;
  }

  const hadGrantedMicBefore = localStorage.getItem(MIC_PERMISSION_GRANTED_KEY) === "true";
  if (permissionState === "prompt" && !hadGrantedMicBefore) {
    onStatus("Your browser should ask for microphone access. Choose Allow, then speak to ANI.");
  } else if (permissionState === "granted") {
    onStatus("Opening microphone...");
  } else if (keepMicReady && hadGrantedMicBefore) {
    onStatus("Opening saved microphone permission...");
  } else {
    onStatus("Requesting microphone access...");
  }

  try {
    mediaStream = await navigator.mediaDevices.getUserMedia(microphoneConstraints());
    localStorage.setItem(MIC_PERMISSION_GRANTED_KEY, "true");
    return mediaStream;
  } catch (error) {
    if (error?.name === "NotAllowedError" || error?.name === "PermissionDeniedError") {
      throw Object.assign(new Error(microphoneBlockedMessage()), { name: "NotAllowedError" });
    }
    if (error?.name === "NotFoundError" || error?.name === "DevicesNotFoundError") {
      throw new Error("ANI could not find a microphone on this device.");
    }
    throw new Error(microphoneUnavailableMessage());
  }
}

function preferredAudioMimeType() {
  const candidates = [
    "audio/webm;codecs=opus",
    "audio/webm",
    "audio/ogg;codecs=opus",
    "audio/ogg",
    "audio/mp4;codecs=mp4a.40.2",
    "audio/mp4",
    "audio/mpeg",
    "audio/wav"
  ];
  return candidates.find((type) => window.MediaRecorder?.isTypeSupported?.(type)) || "";
}

function audioExtensionFromType(type = "") {
  const normalized = type.toLowerCase();
  if (normalized.includes("mp4")) {
    return "mp4";
  }
  if (normalized.includes("mpeg") || normalized.includes("mp3")) {
    return "mp3";
  }
  if (normalized.includes("ogg")) {
    return "ogg";
  }
  if (normalized.includes("wav")) {
    return "wav";
  }
  return "webm";
}

function stopMicSignalMonitor() {
  if (micSignalMonitor) {
    window.clearInterval(micSignalMonitor);
    micSignalMonitor = null;
  }
  if (micSignalAudioContext) {
    micSignalAudioContext.close?.().catch?.(() => {});
    micSignalAudioContext = null;
  }
}

function startMicSignalMonitor(stream, options = {}) {
  stopMicSignalMonitor();
  micSignalStats = { heardSpeech: false, peak: 0 };
  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextConstructor || !stream) {
    return;
  }

  const onStatus = typeof options.onStatus === "function" ? options.onStatus : () => {};
  const threshold = Number(options.threshold || 0.016);
  const startedAt = Date.now();
  let lastStatusAt = 0;

  try {
    micSignalAudioContext = new AudioContextConstructor();
    const source = micSignalAudioContext.createMediaStreamSource(stream);
    const analyser = micSignalAudioContext.createAnalyser();
    analyser.fftSize = 1024;
    source.connect(analyser);
    const data = new Uint8Array(analyser.fftSize);

    micSignalMonitor = window.setInterval(() => {
      analyser.getByteTimeDomainData(data);
      let sum = 0;
      for (const value of data) {
        const centered = (value - 128) / 128;
        sum += centered * centered;
      }
      const volume = Math.sqrt(sum / data.length);
      micSignalStats.peak = Math.max(micSignalStats.peak, volume);

      const now = Date.now();
      if (volume >= threshold) {
        micSignalStats.heardSpeech = true;
        if (now - lastStatusAt > 1600) {
          onStatus("ANI can hear sound. Keep speaking, then tap the microphone again when finished.");
          lastStatusAt = now;
        }
      } else if (!micSignalStats.heardSpeech && now - startedAt > 2600 && now - lastStatusAt > 2200) {
        onStatus("Listening... I have not heard clear speech yet. Try speaking closer to the microphone.");
        lastStatusAt = now;
      }
    }, 160);
  } catch {
    stopMicSignalMonitor();
  }
}

function releaseMicrophoneStream() {
  stopMicSignalMonitor();
  stopClinicalSilenceMonitor();
  mediaStream?.getTracks?.().forEach((track) => track.stop());
  mediaStream = null;
}

function stopMicrophoneStream(options = {}) {
  stopMicSignalMonitor();
  if (options.force || !keepMicReady) {
    releaseMicrophoneStream();
  }
}

async function transcribeAudioBlob(blob) {
  const formData = new FormData();
  const extension = audioExtensionFromType(blob.type);
  formData.append("audio", blob, `ani-microphone.${extension}`);

  const response = await fetchApi("/api/ani/transcribe", {
    method: "POST",
    body: formData
  });
  const data = await response.json().catch(() => ({}));
  if (!response.ok || !data.text?.trim()) {
    const error = new Error(data.error || "ANI heard the recording, but could not turn it into text.");
    error.status = response.status;
    error.payload = data;
    throw error;
  }
  return chooseClinicalSpeechTranscript([data.text]) || cleanSpeechTranscript(data.text);
}

async function transcribeRecordedAudio(blob, signalStats = micSignalStats) {
  if (!blob || blob.size < 900) {
    resetMicUi("No recording data came through. Check microphone permission and try again.");
    return;
  }

  if (signalStats && !signalStats.heardSpeech && signalStats.peak < 0.012) {
    resetMicUi("ANI recorded, but the microphone did not detect clear speech. Try speaking closer, then record again.");
    return;
  }

  if (voiceStatus) {
    voiceStatus.textContent = "Transcribing microphone input...";
  }

  try {
    messageInput.value = await transcribeAudioBlob(blob);
    resetMicUi(messageInput.value
      ? "Transcript ready. Edit it if needed, then send."
      : "No clear speech detected. Try again or type.");
    messageInput.focus();
  } catch (error) {
    const errorText = error.payload?.error || error.message || "";
    if (error.status) {
      if (error.status === 401 || /invalid|unauthorized|api key/i.test(errorText)) {
        resetMicUi("ANI reached the server, but transcription needs a valid OpenAI key.");
        return;
      }
      if (error.status === 429 || /quota|billing|rate/i.test(errorText)) {
        resetMicUi("ANI reached OpenAI, but transcription is limited right now. Try again shortly.");
        return;
      }
      resetMicUi(errorText || "ANI detected sound, but could not turn it into words. Try a slightly longer sentence or type.");
      return;
    }
    resetMicUi(recordingServerUnavailableMessage());
  }
}

function setClinicalStatus(status = "") {
  if (clinicalModeStatus) {
    clinicalModeStatus.textContent = status;
  }
}

function clearClinicalVoiceTimers() {
  if (clinicalAutoRouteTimer) {
    window.clearTimeout(clinicalAutoRouteTimer);
    clinicalAutoRouteTimer = null;
  }
  if (clinicalSpeechPauseTimer) {
    window.clearTimeout(clinicalSpeechPauseTimer);
    clinicalSpeechPauseTimer = null;
  }
  if (clinicalFallbackTimer) {
    window.clearTimeout(clinicalFallbackTimer);
    clinicalFallbackTimer = null;
  }
}

function clinicalVoiceSessionIsCurrent(generation = clinicalVoiceGeneration) {
  return clinicalModeActive && generation === clinicalVoiceGeneration;
}

function setClinicalListening(active) {
  clinicalRecordingActive = active;
  clinicalModeScreen?.classList.toggle("is-listening", active);
  clinicalListenButton?.setAttribute("aria-pressed", String(active));
  if (active) {
    clinicalListenButton?.setAttribute("aria-label", "Cancel clinical voice recording");
  } else if (clinicalVoiceState === "confirming" || clinicalVoiceState === "transcribing") {
    clinicalListenButton?.setAttribute("aria-label", "Cancel and record the clinical question again");
  } else if (clinicalVoiceState === "routing") {
    clinicalListenButton?.setAttribute("aria-label", "Cancel clinical routing and record again");
  } else {
    clinicalListenButton?.setAttribute("aria-label", "Start clinical voice recording");
  }
}

function setClinicalDirecting(active, message = "Got it - directing you now.") {
  clinicalModeScreen?.classList.toggle("is-directing", active);
  clinicalModeScreen?.setAttribute("aria-busy", String(active));
  if (clinicalCaptureNoticeText) {
    clinicalCaptureNoticeText.textContent = message;
  }
  if (clinicalCaptureNotice) {
    clinicalCaptureNotice.hidden = !active;
  }
  if (active) {
    clinicalListenButton?.setAttribute("aria-pressed", "false");
    clinicalListenButton?.setAttribute("aria-label", "Cancel and record the clinical question again");
  } else if (!clinicalRecordingActive) {
    clinicalListenButton?.setAttribute("aria-label", "Start clinical voice recording");
  }
}

function beginClinicalVoiceSession() {
  clearClinicalVoiceTimers();
  clinicalVoiceGeneration += 1;
  clinicalVoiceState = "listening";
  clinicalRecordingCancelRequested = false;
  clinicalBrowserSpeechCancelled = false;
  clinicalLastSpeechResultAt = 0;
  speechRecognitionFallbackPending = false;
  speechRecognitionAlternatives = [];
  clinicalSpeechCandidateScoreCache.clear();
  finalTranscript = "";
  setClinicalDirecting(false);
  setClinicalListening(true);
  setClinicalTranscript("");
  if (clinicalAnswer) {
    clinicalAnswer.hidden = true;
  }
  clinicalModeScreen?.classList.remove("has-answer");
  return clinicalVoiceGeneration;
}

function scheduleClinicalRecordingFallback(generation, status) {
  if (!clinicalVoiceSessionIsCurrent(generation)) {
    return;
  }
  if (clinicalFallbackTimer) {
    window.clearTimeout(clinicalFallbackTimer);
  }
  setClinicalStatus(status);
  clinicalFallbackTimer = window.setTimeout(() => {
    clinicalFallbackTimer = null;
    if (!clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    clinicalVoiceState = "listening";
    setClinicalDirecting(false);
    setClinicalListening(true);
    startClinicalRecording({ generation });
  }, 250);
}

function queueClinicalAutoRoute(question = "", options = {}, generation = clinicalVoiceGeneration) {
  if (!clinicalVoiceSessionIsCurrent(generation)) {
    return false;
  }

  const cleaned = chooseClinicalSpeechTranscript([question]) || applyClinicalSpeechFixups(question) || cleanSpeechTranscript(question);
  if (!cleaned) {
    clinicalVoiceState = "idle";
    setClinicalListening(false);
    setClinicalDirecting(false);
    playClinicalUnderstandingCue("repeat");
    setClinicalStatus("I did not hear clear speech. Tap ANI and try again.");
    return false;
  }

  clearClinicalVoiceTimers();
  clinicalVoiceState = "confirming";
  setClinicalListening(false);
  setClinicalTranscript(cleaned);
  setClinicalDirecting(true, "Got it - directing you now.");
  setClinicalStatus("Voice captured. ANI is directing you now. Tap ANI to cancel and record again.");
  playClinicalUnderstandingCue("understood");

  clinicalAutoRouteTimer = window.setTimeout(async () => {
    clinicalAutoRouteTimer = null;
    if (!clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    clinicalVoiceState = "routing";
    setClinicalDirecting(true, "Finding your best clinical match...");
    setClinicalStatus("Voice captured. ANI is finding the best clinical match now.");
    await answerClinicalQuestion(cleaned, {
      ...options,
      acknowledgementPlayed: true,
      generation,
      preferDatabaseRedirect: true
    });
    if (!clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    clinicalVoiceState = "idle";
    setClinicalDirecting(false);
    setClinicalListening(false);
  }, CLINICAL_CONFIRMATION_DELAY_MS);

  return true;
}

function cancelClinicalVoiceInteraction(status = "Canceled. Tap ANI to listen again.", options = {}) {
  const hadActiveInteraction = clinicalVoiceState !== "idle"
    || clinicalRecordingActive
    || speechRecognitionTarget === "clinical";

  clinicalVoiceGeneration += 1;
  clearClinicalVoiceTimers();
  clinicalVoiceState = "idle";
  clinicalRecordingCancelRequested = true;
  speechRecognitionFallbackPending = false;
  finalTranscript = "";
  speechRecognitionAlternatives = [];

  if (speechRecognitionTarget === "clinical" && microphoneMode === "native-speech") {
    cancelNativeSpeechRecognition();
  }
  if (speechRecognitionTarget === "clinical" && microphoneMode === "speech") {
    clinicalBrowserSpeechCancelled = true;
    try {
      recognition?.abort?.();
    } catch {
      recognition?.stop?.();
    }
  }
  if (mediaRecorder && mediaRecorder.state !== "inactive") {
    stopClinicalRecording({ cancelled: true });
  }

  speechRecognitionTarget = "chat";
  microphoneMode = recognition ? "speech" : "recording";
  stopClinicalSilenceMonitor();
  stopMicrophoneStream({ force: true });
  setClinicalListening(false);
  setClinicalDirecting(false);
  if (options.clearTranscript !== false) {
    setClinicalTranscript("");
  }
  if (!options.silent) {
    setClinicalStatus(status);
  }
  return hadActiveInteraction;
}

function playClinicalUnderstandingCue(type = "understood") {
  if (aniMuted) {
    return;
  }
  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextConstructor) {
    return;
  }

  try {
    const context = new AudioContextConstructor();
    const oscillator = context.createOscillator();
    const gain = context.createGain();
    const isUnderstood = type !== "repeat";
    const frequencies = isUnderstood ? [523.25, 659.25, 783.99] : [392.0, 329.63, 246.94];
    const now = context.currentTime + 0.01;
    const step = isUnderstood ? 0.075 : 0.09;
    oscillator.type = isUnderstood ? "sine" : "triangle";
    frequencies.forEach((frequency, index) => {
      oscillator.frequency.setValueAtTime(frequency, now + index * step);
    });
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(isUnderstood ? 0.08 : 0.055, now + 0.018);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + frequencies.length * step + 0.04);
    oscillator.connect(gain);
    gain.connect(context.destination);
    oscillator.start(now);
    oscillator.stop(now + frequencies.length * step + 0.06);
    oscillator.onended = () => context.close?.().catch?.(() => {});
  } catch {
    // Sound cues are helpful, not required.
  }
}

function renderClinicalAnswer(text = "") {
  if (!clinicalAnswer) {
    return;
  }

  clinicalAnswer.textContent = "";
  const heading = document.createElement("h2");
  heading.textContent = "ANI clinical answer";
  const body = document.createElement("div");
  appendFormattedText(body, applyNclexEssentialMarkup(text));
  clinicalAnswer.append(heading, body);
  clinicalAnswer.hidden = false;
  clinicalModeScreen?.classList.add("has-answer");
}

function setClinicalTranscript(text = "") {
  if (!clinicalTranscript) {
    return;
  }
  clinicalTranscript.textContent = "";
  clinicalTranscript.dataset.rawTranscript = text || "";
  if (text) {
    const label = document.createElement("strong");
    label.textContent = "ANI heard";
    const transcriptText = document.createElement("span");
    transcriptText.textContent = text;
    clinicalTranscript.append(label, transcriptText);
  }
  clinicalTranscript.hidden = !text;
}

function enterClinicalMode() {
  clinicalModeActive = true;
  if (micActive) {
    stopMicrophoneInput();
  }
  cancelClinicalVoiceInteraction("", { silent: true });
  settingsPanel && (settingsPanel.hidden = true);
  setChatHistoryOpen(false);
  clinicalModeScreen.hidden = false;
  document.body.classList.add("clinical-mode-active");
  clinicalVoiceState = "idle";
  setClinicalListening(false);
  setClinicalDirecting(false);
  setClinicalStatus((canUseNativeSpeechRecognition() || canRecordMicrophoneAudio())
    ? "Tap ANI to allow microphone access, then ask a quick clinical question."
    : microphoneUnavailableMessage());
  setClinicalTranscript("");
  if (clinicalAnswer) {
    clinicalAnswer.hidden = true;
  }
  clinicalModeScreen?.classList.remove("has-answer");
  getMicrophonePermissionState().then((state) => {
    if (!clinicalModeActive) {
      return;
    }
    if (state === "granted") {
      setClinicalStatus("Tap ANI and ask a quick clinical question.");
    } else if (state === "denied") {
      setClinicalStatus(microphoneBlockedMessage());
    }
  });
}

function exitClinicalMode() {
  cancelClinicalVoiceInteraction("", { silent: true });
  clinicalModeActive = false;
  clinicalModeScreen.hidden = true;
  document.body.classList.remove("clinical-mode-active");
  clinicalModeScreen?.classList.remove("has-answer");
}

async function requestClinicalQuickAnswer(question = "") {
  const lane4LocalAnswer = tryLane4RuntimeAnswer(question, { mode: "clinical" });
  if (lane4LocalAnswer) return lane4LocalAnswer;
  const offlineFirst = shouldUseOfflineLookupCore()
    ? handleOfflineLookupFlow(question, { force: true, allowPrompt: false })
    : "";
  if (typeof offlineFirst === "string" && offlineFirst) {
    return offlineFirst;
  }

  if (!ANI_ONLINE_AI_ENABLED) {
    return lane4RuntimeFallbackForQuestion(question)
      || "Ask about a specific medication, disease, laboratory test, clinical sign, or nursing priority and I will use ANI's medical encyclopedia.";
  }

  const clinicalContext = lane4BoundedModelContext(question, getAniModelContext(question));
  const lane4AiStartedAt = lane4RecordExternalAiAttempt(question, clinicalContext, "");
  try {
    const response = await fetchApi("/api/ani/clinical", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        question,
        context: clinicalContext
      })
    });
    const data = await response.json().catch(() => ({}));
    aniBackendReachable = true;
    if (!response.ok || !data.text?.trim()) {
      if (response.status === 503) {
        aniModelAvailable = false;
      }
      lane4RecordExternalAiResult(false, lane4AiStartedAt, true);
      return lane4RuntimeFallbackForQuestion(question)
        || data.text
        || data.error
        || "ANI Clinical Mode could not generate a safe quick answer yet.";
    }
    aniModelAvailable = !data.fallback;
    lane4RecordExternalAiResult(!data.fallback, lane4AiStartedAt, Boolean(data.fallback));
    if (data.fallback) return lane4RuntimeFallbackForQuestion(question) || cleanModelTextForDisplay(data.text);
    return cleanModelTextForDisplay(data.text);
  } catch (error) {
    aniBackendReachable = false;
    lane4RecordExternalAiResult(false, lane4AiStartedAt, true);
    const offlineFallback = handleOfflineLookupFlow(question, { force: true, allowPrompt: false });
    if (typeof offlineFallback === "string" && offlineFallback) {
      return offlineFallback;
    }
    return lane4RuntimeFallbackForQuestion(question)
      || `${backendUnavailableMessage()}\n\nThe medical encyclopedia can still recognize installed medication, lab, and pathology keywords. Try a specific entry like fluoxetine, MAP, magnesium, DKA, or first-degree AV block.`;
  }
}

function isConciseOfflineLookupQuery(input = "") {
  const stripped = normalizeOfflineLookupText(input);
  if (!stripped) {
    return false;
  }
  return stripped.split(" ").filter(Boolean).length <= 4;
}

function clinicalSpeechCandidateList(values = []) {
  const candidates = [];
  const seen = new Set();
  const add = (value = "") => {
    const cleaned = cleanSpeechTranscript(value);
    const fixed = applyClinicalSpeechFixups(cleaned);
    [cleaned, fixed].forEach((candidate) => {
      const normalized = normalizePharmText(candidate);
      if (!normalized || seen.has(normalized) || candidates.length >= 12) return;
      seen.add(normalized);
      candidates.push(candidate);
    });
  };
  (Array.isArray(values) ? values : [values]).forEach(add);
  return candidates;
}

const clinicalSpeechCandidateScoreCache = new Map();

function clinicalSpeechCandidateScore(text = "") {
  const cleaned = applyClinicalSpeechFixups(text);
  if (!cleaned) return 0;
  const cacheKey = normalizePharmText(cleaned);
  if (clinicalSpeechCandidateScoreCache.has(cacheKey)) {
    return clinicalSpeechCandidateScoreCache.get(cacheKey);
  }
  let score = 0;
  let compactOwners = [];
  const diabetesRoute = wave41DiabetesPathologyIntentSuggestion(cleaned);
  if (diabetesRoute) {
    score += 1500;
  } else {
    // Final speech alternatives only need identity confidence, not a complete
    // encyclopedia relevance search. Use the compact true-identity layer here;
    // building every deep ranker for every speech alternative caused a
    // several-second freeze on first use.
    compactOwners = fastVoiceIdentityCandidates(cleaned);
    if (compactOwners.length) {
      score += 980;
      if (compactOwners.some((owner) => owner.type === "lab") && hasLabLookupIntent(cleaned)) score += 220;
      if (compactOwners.some((owner) => owner.type === "pathology")) score += 150;
      if (compactOwners.some((owner) => owner.type === "drug")) score += 110;
      if (compactOwners.some((owner) => owner.type === "reference")) score += 100;
    }
  }
  if (!compactOwners.length && typeof resolveTopicRequest === "function") {
    const topicRequest = resolveTopicRequest(cleaned, { mode: "suggest", limit: 3 });
    if (["reviewed-route", "clinical-clue"].includes(topicRequest.resolutionKind)
      && topicRequest.preferred?.item) {
      // Use the same reviewed/systemic evidence to choose among speech-engine
      // transcript alternatives. This affects transcript ranking only; the
      // later navigation policy still owns ambiguity, personal-context, and
      // mayAutoOpen decisions.
      score += topicRequest.mayAutoOpen === true ? 1050 : 480;
      score += Math.round(Math.max(0, Math.min(1, Number(topicRequest.confidence || 0))) * 180);
    }
  }
  if (hasLabLookupIntent(cleaned)) score += 120;
  if (hasOfflineReferenceCue(cleaned)) score += 40;
  if (isConciseOfflineLookupQuery(cleaned)) score += 35;
  if (/\b(gfr|egfr|glomerular filtration rate|siadh|dka|hhs|bun|inr|aptt|hgb|hct|wbc|rbc|anc|bnp|ckmb|a1c|tsh|abg|vbg|map|lactate|troponin|ssri|snri|maoi|tca|ppi|h2|ace|arb|nsaid|doac|lmwh|ufh|saba|sglt2|glp1|dpp4|pde5)\b/i.test(cleaned)) {
    score += 180;
  }
  clinicalSpeechCandidateScoreCache.set(cacheKey, score);
  while (clinicalSpeechCandidateScoreCache.size > 32) {
    clinicalSpeechCandidateScoreCache.delete(clinicalSpeechCandidateScoreCache.keys().next().value);
  }
  return score;
}

function chooseClinicalSpeechTranscript(values = []) {
  const candidates = clinicalSpeechCandidateList(values);
  if (!candidates.length) return "";
  return candidates
    .map((text, index) => ({
      text: applyClinicalSpeechFixups(text),
      score: clinicalSpeechCandidateScore(text),
      index
    }))
    .filter((entry) => entry.text)
    .sort((a, b) => b.score - a.score || a.index - b.index || b.text.length - a.text.length)[0]?.text || "";
}

function maybeOpenClinicalOfflineLookup(cleaned = "", options = {}) {
  const generation = Number(options.generation || 0);
  if (generation && !clinicalVoiceSessionIsCurrent(generation)) {
    return false;
  }
  const explicitNavigationCue = /\b(open|show|find|search|look up|lookup|encyclopedia|database|reference)\b/i.test(cleaned);
  if (!explicitNavigationCue) {
    const smartDatabaseAnswer = makeOfflineSmartDatabaseAnswer(cleaned);
    if (smartDatabaseAnswer) {
      renderClinicalAnswer(smartDatabaseAnswer);
      setClinicalStatus("ANI pulled the focused encyclopedia answer.");
      speak(smartDatabaseAnswer);
      rememberConversation("assistant", smartDatabaseAnswer);
      lastAssistantText = smartDatabaseAnswer;
      return true;
    }
  }

  const forceAiClinicalWork = wantsAiGeneratedStudyWork(cleaned)
    || wantsLecture(cleaned)
    || /\b(in depth|deeper|deeply|deep dive|full lecture|long lecture|comprehensive|thorough|thoroughly|rationale|why is|why does|why do|compare|difference between|distinguish between|versus|vs\.?)\b/i.test(normalizeIntentText(cleaned));
  if (forceAiClinicalWork && !shouldUseOfflineLookupCore()) {
    return false;
  }

  if (!offlineConceptNavigationCue(cleaned)) {
    const conceptSynthesisAnswer = makeOfflineConceptSynthesisResponse(cleaned);
    if (conceptSynthesisAnswer) {
      renderClinicalAnswer(conceptSynthesisAnswer);
      setClinicalStatus("ANI pulled the focused encyclopedia answer.");
      speak(conceptSynthesisAnswer);
      rememberConversation("assistant", conceptSynthesisAnswer);
      lastAssistantText = conceptSynthesisAnswer;
      return true;
    }
  }

  const redirect = handleOfflineLookupFlow(cleaned, {
    force: true,
    allowPrompt: false,
    preferDatabaseRedirect: true
  });
  const shouldOpen = redirect
    && typeof redirect === "object"
    && redirect.type === "pharm-database"
    && (
      options.preferDatabaseRedirect
      || shouldUseOfflineLookupCore()
      || isConciseOfflineLookupQuery(cleaned)
      || isStrongOfflineReferenceRequest(cleaned)
      || wantsOfflineSegmentAnswer(cleaned)
      || wantsDiagnosticResultInterpretation(cleaned)
      || hasLabLookupIntent(cleaned)
    );

  if (!shouldOpen) {
    return false;
  }

  const displayLine = redirect.preface || `Opening **${redirect.query}** in the clinical reference.`;
  renderClinicalAnswer(displayLine);
  setClinicalStatus("Opening the clinical reference...");

  window.requestAnimationFrame(() => {
    if (generation && !clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    if (clinicalModeActive) {
      exitClinicalMode();
    }
    openPharmDatabase(redirect.query || cleaned, {
      openDetail: true,
      detailType: redirect.detailType,
      targetCandidate: redirect.targetCandidate,
      fastDetail: true,
      autoFocus: false,
      highlightQuery: redirect.highlightQuery
    });
    rememberConversation("assistant", displayLine);
    lastAssistantText = displayLine;
  });

  return true;
}

function shouldAskClinicalRepeatBeforeProcessing(input = "") {
  const stripped = normalizeOfflineLookupText(input);
  if (!stripped) {
    return true;
  }
  const tokens = stripped.split(" ").filter(Boolean);
  if (tokens.length > 2) {
    return false;
  }
  if (hasOfflineReferenceCue(input) || wantsAiDepthTeaching(input) || wantsAiGeneratedStudyWork(input)) {
    return false;
  }
  return offlineLookupSuggestions(input).length === 0;
}

async function answerClinicalQuestion(question = "", options = {}) {
  const generation = Number(options.generation || 0);
  if (generation && !clinicalVoiceSessionIsCurrent(generation)) {
    return;
  }
  const cleaned = chooseClinicalSpeechTranscript([question]) || applyClinicalSpeechFixups(question) || cleanSpeechTranscript(question);
  if (!cleaned) {
    clinicalVoiceState = "idle";
    setClinicalDirecting(false);
    playClinicalUnderstandingCue("repeat");
    setClinicalStatus("I did not catch a clear clinical question. Tap ANI and try again.");
    return;
  }

  setClinicalTranscript(cleaned);
  if (shouldAskClinicalRepeatBeforeProcessing(cleaned)) {
    clinicalVoiceState = "idle";
    setClinicalDirecting(false);
    playClinicalUnderstandingCue("repeat");
    setClinicalStatus(`I heard "${cleaned}", but I do not have a confident clinical match. Tap ANI and say the main topic again.`);
    renderClinicalAnswer(`I heard "${cleaned}", but I do not have a confident clinical match yet. Tap ANI and say the main topic again.`);
    return;
  }

  if (!options.acknowledgementPlayed) {
    playClinicalUnderstandingCue("understood");
  }
  if (maybeOpenClinicalOfflineLookup(cleaned, options)) {
    return;
  }

  setClinicalStatus("ANI is pulling the highest-yield clinical points...");
  const answer = await requestClinicalQuickAnswer(cleaned);
  if (generation && !clinicalVoiceSessionIsCurrent(generation)) {
    return;
  }
  renderClinicalAnswer(answer);
  setClinicalStatus("Tap ANI again for another quick clinical question.");
  speak(answer);
}

function stopClinicalSilenceMonitor() {
  if (clinicalSilenceMonitor) {
    window.clearInterval(clinicalSilenceMonitor);
    clinicalSilenceMonitor = null;
  }
  if (clinicalAudioContext) {
    clinicalAudioContext.close?.().catch?.(() => {});
    clinicalAudioContext = null;
  }
}

function startClinicalSilenceMonitor(stream, generation = clinicalVoiceGeneration) {
  stopClinicalSilenceMonitor();
  clinicalSignalStats = { heardSpeech: false, peak: 0 };
  const AudioContextConstructor = window.AudioContext || window.webkitAudioContext;
  if (!AudioContextConstructor || !stream) {
    return;
  }

  try {
    clinicalAudioContext = new AudioContextConstructor();
    const source = clinicalAudioContext.createMediaStreamSource(stream);
    const analyser = clinicalAudioContext.createAnalyser();
    analyser.fftSize = 1024;
    source.connect(analyser);

    const data = new Uint8Array(analyser.fftSize);
    const startedAt = Date.now();
    let heardSpeech = false;
    let lastSpeechAt = startedAt;
    let lastStatusAt = 0;

    clinicalSilenceMonitor = window.setInterval(() => {
      if (!clinicalVoiceSessionIsCurrent(generation)
        || !clinicalRecordingActive
        || !mediaRecorder
        || mediaRecorder.state === "inactive") {
        stopClinicalSilenceMonitor();
        return;
      }

      analyser.getByteTimeDomainData(data);
      let sum = 0;
      for (const value of data) {
        const centered = (value - 128) / 128;
        sum += centered * centered;
      }
      const volume = Math.sqrt(sum / data.length);
      const now = Date.now();
      clinicalSignalStats.peak = Math.max(clinicalSignalStats.peak, volume);

      if (volume > 0.016) {
        heardSpeech = true;
        clinicalSignalStats.heardSpeech = true;
        lastSpeechAt = now;
        if (now - lastStatusAt > 1600) {
          setClinicalStatus("ANI can hear you. Pause for two seconds when you are done, or tap ANI to cancel.");
          lastStatusAt = now;
        }
      } else if (!heardSpeech && now - startedAt > 2800 && now - lastStatusAt > 2200) {
        setClinicalStatus("Listening... I have not heard clear speech yet. Speak closer to the microphone.");
        lastStatusAt = now;
      }

      const minimumListenMs = 2200;
      const silenceMs = heardSpeech ? CLINICAL_SPEECH_PAUSE_MS : 8500;
      const maxListenMs = 32000;
      if ((now - startedAt > minimumListenMs && now - lastSpeechAt > silenceMs) || now - startedAt > maxListenMs) {
        stopClinicalRecording();
      }
    }, 140);
  } catch (error) {
    stopClinicalSilenceMonitor();
  }
}

async function startClinicalRecording(options = {}) {
  const generation = Number(options.generation || clinicalVoiceGeneration);
  if (!clinicalVoiceSessionIsCurrent(generation)) {
    return;
  }
  if (!canRecordMicrophoneAudio()) {
    clinicalVoiceState = "idle";
    setClinicalListening(false);
    setClinicalStatus(microphoneUnavailableMessage());
    return;
  }

  try {
    stopMicrophoneStream();
    clinicalRecordedAudioChunks = [];
    clinicalRecordingCancelRequested = false;
    mediaStream = await requestMicrophoneStream({
      onStatus: setClinicalStatus
    });
    if (!clinicalVoiceSessionIsCurrent(generation)) {
      mediaStream?.getTracks?.().forEach((track) => track.stop());
      mediaStream = null;
      return;
    }

    const mimeType = preferredAudioMimeType();
    const recorderOptions = mimeType ? { mimeType } : {};
    mediaRecorder = new MediaRecorder(mediaStream, recorderOptions);
    mediaRecorder.addEventListener("dataavailable", (event) => {
      if (event.data?.size) {
        clinicalRecordedAudioChunks.push(event.data);
      }
    });
    mediaRecorder.addEventListener("stop", async () => {
      const blob = new Blob(clinicalRecordedAudioChunks, { type: mediaRecorder?.mimeType || "audio/webm" });
      const wasCancelled = clinicalRecordingCancelRequested;
      clinicalRecordingCancelRequested = false;
      clinicalRecordedAudioChunks = [];
      stopClinicalSilenceMonitor();
      stopMicrophoneStream({ force: true });
      setClinicalListening(false);
      if (wasCancelled || !clinicalVoiceSessionIsCurrent(generation)) {
        return;
      }

      if (!blob || blob.size < 900) {
        clinicalVoiceState = "idle";
        setClinicalDirecting(false);
        playClinicalUnderstandingCue("repeat");
        setClinicalStatus("No recording data came through. Check microphone permission and tap ANI again.");
        return;
      }

      if (!clinicalSignalStats.heardSpeech && clinicalSignalStats.peak < 0.012) {
        clinicalVoiceState = "idle";
        setClinicalDirecting(false);
        playClinicalUnderstandingCue("repeat");
        setClinicalStatus("I did not hear clear speech. Tap ANI and try again closer to the microphone.");
        return;
      }

      try {
        clinicalVoiceState = "transcribing";
        setClinicalDirecting(true, "Voice captured - turning it into text...");
        setClinicalStatus("Voice captured. ANI is turning it into text now. Tap ANI to cancel and record again.");
        const transcript = await transcribeAudioBlob(blob);
        if (!clinicalVoiceSessionIsCurrent(generation)) {
          return;
        }
        queueClinicalAutoRoute(transcript, { preferDatabaseRedirect: true }, generation);
      } catch (error) {
        if (!clinicalVoiceSessionIsCurrent(generation)) {
          return;
        }
        clinicalVoiceState = "idle";
        setClinicalDirecting(false);
        const errorText = error.payload?.error || error.message || "";
        if (error.status === 401 || /invalid|unauthorized|api key/i.test(errorText)) {
          setClinicalStatus("ANI reached the server, but transcription needs a valid OpenAI key.");
        } else if (error.status === 429 || /quota|billing|rate/i.test(errorText)) {
          setClinicalStatus("ANI reached OpenAI, but transcription is limited right now. Try again shortly.");
        } else if (!error.status) {
          setClinicalStatus(recordingServerUnavailableMessage());
        } else {
          playClinicalUnderstandingCue("repeat");
          setClinicalStatus(errorText || "ANI detected sound, but could not turn it into words. Try a slightly longer clinical question.");
        }
      }
    }, { once: true });
    mediaRecorder.start();
    startClinicalSilenceMonitor(mediaStream, generation);
    clinicalVoiceState = "listening";
    setClinicalListening(true);
    setClinicalStatus("Listening... speak naturally. Pause for two seconds when finished, or tap ANI to cancel.");
    if (clinicalAnswer) {
      clinicalAnswer.hidden = true;
    }
    clinicalModeScreen?.classList.remove("has-answer");
    setClinicalTranscript("");
  } catch (error) {
    if (!clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    stopClinicalSilenceMonitor();
    stopMicrophoneStream({ force: true });
    clinicalVoiceState = "idle";
    setClinicalListening(false);
    setClinicalDirecting(false);
    setClinicalStatus(error?.message || microphoneUnavailableMessage());
  }
}

function stopClinicalRecording(options = {}) {
  stopClinicalSilenceMonitor();
  if (options.cancelled) {
    clinicalRecordingCancelRequested = true;
  }
  if (mediaRecorder && mediaRecorder.state !== "inactive") {
    if (!options.cancelled) {
      clinicalVoiceState = "transcribing";
      setClinicalListening(false);
      setClinicalDirecting(true, "Voice captured - turning it into text...");
      setClinicalStatus("Voice captured. ANI is turning it into text now. Tap ANI to cancel and record again.");
    }
    mediaRecorder.stop();
    return;
  }
  stopMicrophoneStream({ force: true });
  setClinicalListening(false);
}

async function startAudioRecording() {
  try {
    microphoneMode = "recording";
    recordedAudioChunks = [];
    finalTranscript = "";
    messageInput.value = "";
    mediaStream = await requestMicrophoneStream({
      onStatus: (status) => {
        if (voiceStatus) {
          voiceStatus.textContent = status;
        }
      }
    });

    const mimeType = preferredAudioMimeType();
    const recorderOptions = mimeType ? { mimeType } : {};
    mediaRecorder = new MediaRecorder(mediaStream, recorderOptions);
    mediaRecorder.addEventListener("dataavailable", (event) => {
      if (event.data?.size) {
        recordedAudioChunks.push(event.data);
      }
    });
    mediaRecorder.addEventListener("stop", () => {
      const blob = new Blob(recordedAudioChunks, { type: mediaRecorder?.mimeType || "audio/webm" });
      const signalStats = { ...micSignalStats };
      recordedAudioChunks = [];
      stopMicrophoneStream();
      transcribeRecordedAudio(blob, signalStats);
    }, { once: true });
    startMicSignalMonitor(mediaStream, {
      onStatus: (status) => {
        if (voiceStatus && micActive) {
          voiceStatus.textContent = status;
        }
      }
    });
    mediaRecorder.start(250);
    setMicRecordingUi("Listening... speak naturally, then tap the microphone again when finished.");
  } catch (error) {
    stopMicrophoneStream();
    resetMicUi(error?.message || microphoneUnavailableMessage());
  }
}

function stopAudioRecording() {
  if (mediaRecorder && mediaRecorder.state !== "inactive") {
    mediaRecorder.stop();
    if (voiceStatus) {
      voiceStatus.textContent = "Processing microphone audio...";
    }
  } else {
    stopMicrophoneStream();
    resetMicUi();
  }
}

function cancelNativeSpeechRecognition() {
  const nativeRecognizer = getNativeSpeechRecognizer();
  try {
    const result = nativeRecognizer?.cancelRecognition?.();
    if (result?.catch) {
      result.catch(() => {});
    }
  } catch {
    // Native cancellation is best-effort. The recognizer promise will settle shortly.
  }
}

async function startNativeSpeechRecognition(target = "chat", options = {}) {
  const nativeRecognizer = getNativeSpeechRecognizer();
  if (!nativeRecognizer?.recognize) {
    return false;
  }
  const generation = target === "clinical"
    ? Number(options.generation || clinicalVoiceGeneration)
    : 0;
  if (target === "clinical" && !clinicalVoiceSessionIsCurrent(generation)) {
    return false;
  }

  microphoneMode = "native-speech";
  speechRecognitionTarget = target;
  finalTranscript = "";
  speechRecognitionAlternatives = [];

  if (target === "clinical") {
    clinicalVoiceState = "listening";
    setClinicalListening(true);
    setClinicalDirecting(false);
    setClinicalTranscript("");
    setClinicalStatus("Listening... speak naturally. Pause for two seconds when finished, or tap ANI to cancel.");
    if (clinicalAnswer) {
      clinicalAnswer.hidden = true;
    }
    clinicalModeScreen?.classList.remove("has-answer");
  } else {
    messageInput.value = "";
    setMicRecordingUi("Listening... speak naturally");
  }

  try {
    const result = parseNativeSpeechResult(await nativeRecognizer.recognize({
      language: "en-US",
      preferOffline: true,
      maxResults: 8
    }));
    const matches = Array.isArray(result.matches) ? result.matches : [];
    const recognizedText = target === "clinical"
      ? chooseClinicalSpeechTranscript([result.text, ...matches])
      : chooseClinicalSpeechTranscript([result.text, ...matches]) || cleanSpeechTranscript(result.text || matches[0] || "");

    if (target === "clinical") {
      if (!clinicalVoiceSessionIsCurrent(generation)) {
        return true;
      }
      setClinicalListening(false);
      if (recognizedText) {
        queueClinicalAutoRoute(recognizedText, { preferDatabaseRedirect: true }, generation);
      } else {
        clinicalVoiceState = "idle";
        setClinicalDirecting(false);
        playClinicalUnderstandingCue("repeat");
        setClinicalStatus("I did not hear clear speech. Tap ANI and try again.");
      }
      return true;
    }

    messageInput.value = recognizedText;
    resetMicUi(recognizedText
      ? "Transcript ready. Edit it if needed, then send."
      : "ANI heard the recording, but could not turn it into text. Try again or type.");
    messageInput.focus();
    return true;
  } catch (error) {
    if (target === "clinical" && !clinicalVoiceSessionIsCurrent(generation)) {
      return true;
    }
    const message = String(error?.message || error || "");
    const status = /blocked|permission|microphone/i.test(message)
      ? microphoneBlockedMessage()
      : message || "ANI heard the recording, but could not turn it into text. Try again or type.";
    if (target === "clinical") {
      clinicalVoiceState = "idle";
      setClinicalListening(false);
      setClinicalDirecting(false);
      playClinicalUnderstandingCue("repeat");
      if (clinicalModeActive) {
        setClinicalStatus(status);
      }
    } else {
      resetMicUi(status);
    }
    return true;
  } finally {
    if (microphoneMode === "native-speech"
      && (target !== "clinical" || generation === clinicalVoiceGeneration)) {
      microphoneMode = recognition ? "speech" : "recording";
    }
    if (speechRecognitionTarget === target
      && (target !== "clinical" || generation === clinicalVoiceGeneration)) {
      speechRecognitionTarget = "chat";
    }
    speechRecognitionAlternatives = [];
  }
}

function startSpeechRecognition(target = "chat", options = {}) {
  const generation = target === "clinical"
    ? Number(options.generation || clinicalVoiceGeneration)
    : 0;
  if (canUseNativeSpeechRecognition()) {
    startNativeSpeechRecognition(target, { generation });
    return;
  }

  if (!recognition) {
    if (target === "clinical") {
      clinicalVoiceState = "idle";
      setClinicalListening(false);
      setClinicalDirecting(false);
      setClinicalStatus("Browser speech recognition is unavailable. Try recording transcription or type your question.");
    } else {
      resetMicUi("Browser speech recognition is unavailable. Try recording transcription or type.");
    }
    return;
  }

  microphoneMode = "speech";
  speechRecognitionTarget = target;
  if (target === "clinical") {
    clinicalBrowserSpeechGeneration = generation;
  }
  try {
    recognition.start();
  } catch (error) {
    if (target === "clinical") {
      clinicalVoiceState = "idle";
      setClinicalListening(false);
      setClinicalDirecting(false);
      speechRecognitionTarget = "chat";
      setClinicalStatus("Microphone is already starting. Try again in a second.");
    } else {
      resetMicUi("Microphone is already starting. Try again in a second.");
    }
  }
}

function stopMicrophoneInput() {
  if (microphoneMode === "native-speech") {
    cancelNativeSpeechRecognition();
    resetMicUi("Stopping microphone input...");
    return;
  }
  if (microphoneMode === "recording") {
    stopAudioRecording();
    return;
  }
  if (recognition && microphoneMode === "speech") {
    recognition.stop();
    return;
  }
  resetMicUi();
}

if (recognition) {
  recognition.continuous = false;
  recognition.interimResults = true;
  recognition.lang = "en-US";

  recognition.addEventListener("start", () => {
    microphoneMode = "speech";
    finalTranscript = "";
    speechRecognitionAlternatives = [];
    speechRecognitionFallbackPending = canRecordMicrophoneAudio();
    if (speechRecognitionTarget === "clinical") {
      if (!clinicalVoiceSessionIsCurrent(clinicalBrowserSpeechGeneration)) {
        recognition.abort?.();
        return;
      }
      clinicalVoiceState = "listening";
      setClinicalListening(true);
      setClinicalDirecting(false);
      setClinicalTranscript("");
      setClinicalStatus("Listening... speak naturally. Pause for two seconds when finished, or tap ANI to cancel.");
    } else {
      messageInput.value = "";
      setMicRecordingUi("Listening... speak naturally");
    }
  });

  recognition.addEventListener("result", (event) => {
    if (speechRecognitionTarget === "clinical"
      && !clinicalVoiceSessionIsCurrent(clinicalBrowserSpeechGeneration)) {
      return;
    }
    let interimTranscript = "";
    for (let index = event.resultIndex; index < event.results.length; index += 1) {
      const transcript = event.results[index][0].transcript;
      const alternatives = Array.from(event.results[index] || [])
        .slice(0, 5)
        .map((result) => result?.transcript)
        .filter(Boolean);
      speechRecognitionAlternatives = Array.from(new Map([
        ...speechRecognitionAlternatives,
        ...alternatives
      ].map((value) => [normalizePharmText(value), value])).values())
        .filter(Boolean)
        .slice(0, 8);
      if (event.results[index].isFinal) {
        finalTranscript = `${finalTranscript} ${transcript}`.trim();
      } else {
        interimTranscript = `${interimTranscript} ${transcript}`.trim();
      }
    }

    // Interim events update the UI only. Ranking every partial transcript
    // against the encyclopedia made typing/listening feel frozen. Alternatives
    // are scored once, after recognition ends.
    const liveTranscript = speechRecognitionTarget === "clinical"
      ? (applyClinicalSpeechFixups(`${finalTranscript} ${interimTranscript}`)
        || cleanSpeechTranscript(`${finalTranscript} ${interimTranscript}`))
      : cleanSpeechTranscript(`${finalTranscript} ${interimTranscript}`);
    if (speechRecognitionTarget === "clinical") {
      setClinicalTranscript(liveTranscript);
      if (liveTranscript) {
        clinicalLastSpeechResultAt = Date.now();
        if (clinicalSpeechPauseTimer) {
          window.clearTimeout(clinicalSpeechPauseTimer);
        }
        setClinicalStatus("ANI can hear you. Pause for two seconds when you are done, or tap ANI to cancel.");
        const generation = clinicalBrowserSpeechGeneration;
        clinicalSpeechPauseTimer = window.setTimeout(() => {
          clinicalSpeechPauseTimer = null;
          if (!clinicalVoiceSessionIsCurrent(generation)
            || speechRecognitionTarget !== "clinical"
            || clinicalVoiceState !== "listening") {
            return;
          }
          setClinicalStatus("Voice captured. ANI is finishing the recording now.");
          recognition.stop();
        }, CLINICAL_SPEECH_PAUSE_MS);
      }
    } else {
      messageInput.value = liveTranscript;
    }
  });

  recognition.addEventListener("end", () => {
    if (clinicalBrowserSpeechCancelled) {
      clinicalBrowserSpeechCancelled = false;
      return;
    }
    const endingTarget = speechRecognitionTarget;
    const generation = clinicalBrowserSpeechGeneration;
    if (clinicalSpeechPauseTimer) {
      window.clearTimeout(clinicalSpeechPauseTimer);
      clinicalSpeechPauseTimer = null;
    }
    if (endingTarget === "clinical" && !clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }

    const recognizedText = endingTarget === "clinical"
      ? chooseClinicalSpeechTranscript([
        finalTranscript,
        clinicalTranscript?.dataset?.rawTranscript || "",
        ...speechRecognitionAlternatives
      ])
      : (chooseClinicalSpeechTranscript([messageInput.value || finalTranscript || "", ...speechRecognitionAlternatives])
        || cleanSpeechTranscript(messageInput.value || finalTranscript || ""));

    if (speechRecognitionFallbackPending && !recognizedText && canRecordMicrophoneAudio()) {
      const fallbackTarget = endingTarget;
      speechRecognitionFallbackPending = false;
      speechRecognitionTarget = "chat";
      speechRecognitionAlternatives = [];
      if (fallbackTarget === "clinical" && clinicalVoiceSessionIsCurrent(generation)) {
        setClinicalListening(false);
        scheduleClinicalRecordingFallback(
          generation,
          "I did not receive clear words, so ANI is switching to microphone recording. Tap ANI to cancel."
        );
      } else if (fallbackTarget === "chat") {
        resetMicUi("Speech recognition did not return words, so ANI is switching to recording transcription.");
        window.setTimeout(startAudioRecording, 250);
      }
      return;
    }

    if (endingTarget === "clinical") {
      setClinicalListening(false);
      speechRecognitionTarget = "chat";
      speechRecognitionAlternatives = [];
      if (recognizedText) {
        const elapsedSinceSpeech = clinicalLastSpeechResultAt
          ? Date.now() - clinicalLastSpeechResultAt
          : CLINICAL_SPEECH_PAUSE_MS;
        const remainingPause = Math.max(0, CLINICAL_SPEECH_PAUSE_MS - elapsedSinceSpeech);
        if (remainingPause > 0) {
          clinicalVoiceState = "listening";
          setClinicalListening(true);
          setClinicalStatus("ANI heard you. Waiting for the two-second pause; tap ANI to cancel.");
          clinicalSpeechPauseTimer = window.setTimeout(() => {
            clinicalSpeechPauseTimer = null;
            if (clinicalVoiceSessionIsCurrent(generation)) {
              queueClinicalAutoRoute(recognizedText, { preferDatabaseRedirect: true }, generation);
            }
          }, remainingPause);
        } else {
          queueClinicalAutoRoute(recognizedText, { preferDatabaseRedirect: true }, generation);
        }
      } else if (clinicalVoiceSessionIsCurrent(generation)) {
        scheduleClinicalRecordingFallback(
          generation,
          "I did not receive clear words, so ANI is switching to microphone recording. Tap ANI to cancel."
        );
      }
      return;
    }

    messageInput.value = chooseClinicalSpeechTranscript([messageInput.value, ...speechRecognitionAlternatives])
      || cleanSpeechTranscript(messageInput.value);
    if (messageInput.value) {
      resetMicUi("Transcript ready. Edit it if needed, then send.");
    } else if (canRecordMicrophoneAudio()) {
      resetMicUi("Speech recognition ended without text, so ANI is switching to recording transcription.");
      window.setTimeout(startAudioRecording, 250);
    } else {
      resetMicUi("No clear speech detected. Try again or type.");
    }
    speechRecognitionTarget = "chat";
    speechRecognitionAlternatives = [];
  });

  recognition.addEventListener("error", (event) => {
    if (clinicalBrowserSpeechCancelled) {
      return;
    }
    const isClinicalError = speechRecognitionTarget === "clinical";
    const generation = clinicalBrowserSpeechGeneration;
    if (isClinicalError && !clinicalVoiceSessionIsCurrent(generation)) {
      return;
    }
    const canFallback = event.error !== "not-allowed" && canRecordMicrophoneAudio();
    speechRecognitionFallbackPending = canFallback;
    const status = event.error === "not-allowed"
      ? microphoneBlockedMessage()
      : canFallback
      ? "Speech recognition did not catch words. ANI is switching to recording transcription."
      : "Browser speech recognition failed. Try the microphone again or type.";
    if (isClinicalError) {
      if (!canFallback) {
        clinicalVoiceState = "idle";
        setClinicalListening(false);
        setClinicalDirecting(false);
        clinicalVoiceGeneration += 1;
        clinicalBrowserSpeechCancelled = true;
        speechRecognitionTarget = "chat";
        speechRecognitionAlternatives = [];
      }
      setClinicalStatus(status);
    } else {
      resetMicUi(status);
    }
  });
} else {
  micButton.title = canRecordMicrophoneAudio()
    ? "Record microphone input"
    : "Microphone dictation needs browser recording support.";
  if (!canRecordMicrophoneAudio()) {
    micButton.disabled = true;
    voiceStatus.textContent = "Microphone dictation is unavailable in this browser. You can still type.";
  }
}

function isStandaloneApp() {
  return window.matchMedia?.("(display-mode: standalone)")?.matches || window.navigator.standalone === true;
}

function pwaInstallSupportedContext() {
  return location.protocol === "https:"
    || location.hostname === "localhost"
    || location.hostname === "127.0.0.1"
    || location.hostname === "127.0.0.2";
}

function updateInstallUi() {
  if (!installStatus || !installAppButton) {
    return;
  }

  if (!aniFeatureEnabled("installPrompt")) {
    installAppButton.hidden = true;
    installStatus.closest("[data-ani-feature]")?.setAttribute("hidden", "");
    return;
  }

  if (isStandaloneApp()) {
    installStatus.textContent = "ANI is already running as an installed app on this device.";
    installAppButton.hidden = true;
    return;
  }

  if (deferredInstallPrompt) {
    installStatus.textContent = "ANI is ready to install on this device.";
    installAppButton.hidden = false;
    return;
  }

  if (!pwaInstallSupportedContext()) {
    installStatus.textContent = "Phone install requires HTTPS or the native wrapper. Local LAN HTTP can preview ANI, but browsers usually will not install it.";
    installAppButton.hidden = true;
    return;
  }

  installStatus.textContent = "If your browser supports it, the install option will appear here. On iPhone, use Share, then Add to Home Screen.";
  installAppButton.hidden = true;
}

async function registerServiceWorker() {
  if (isNativeShell) {
    try {
      const registrations = await navigator.serviceWorker?.getRegistrations?.() || [];
      await Promise.all(registrations.map((registration) => registration.unregister()));
      if (window.caches?.keys) {
        const keys = await caches.keys();
        await Promise.all(keys.map((key) => caches.delete(key)));
      }
    } catch (error) {
      console.warn("ANI native cache cleanup skipped", error);
    }
    updateInstallUi();
    return;
  }

  if (!("serviceWorker" in navigator) || !pwaInstallSupportedContext()) {
    updateInstallUi();
    return;
  }

  try {
    const registration = await navigator.serviceWorker.register("/service-worker.js", { updateViaCache: "none" });
    await registration.update?.();
  } catch {
    // A cached worker can launch ANI correctly even when its background update
    // request cannot reach the server. Record that state without emitting a
    // misleading console warning during a valid offline launch.
    document.documentElement.dataset.aniServiceWorkerUpdate = "unavailable";
  } finally {
    updateInstallUi();
  }
}

window.addEventListener("beforeinstallprompt", (event) => {
  event.preventDefault();
  if (!aniFeatureEnabled("installPrompt")) return;
  deferredInstallPrompt = event;
  updateInstallUi();
});

window.addEventListener("appinstalled", () => {
  deferredInstallPrompt = null;
  updateInstallUi();
});

micButton?.addEventListener("click", () => {
  if (micActive) {
    stopMicrophoneInput();
    return;
  }

  if (canUseNativeSpeechRecognition()) {
    startSpeechRecognition("chat");
    return;
  }

  if (recognition) {
    startSpeechRecognition("chat");
    return;
  }

  if (canRecordMicrophoneAudio()) {
    startAudioRecording();
    return;
  }

  startSpeechRecognition("chat");
});

clinicalModeButton?.addEventListener("click", enterClinicalMode);
pharmDatabaseButton?.addEventListener("click", () => openPharmDatabase());
lectureModeButton?.addEventListener("click", () => {
  if (lectureModePrimed) {
    setLectureModeActive(false);
    messageInput?.focus();
    return;
  }

  const topic = messageInput?.value?.trim() || "";
  if (topic) {
    setLectureModeActive(true);
    sendUserMessage(topic);
    return;
  }

  setLectureModeActive(true);
  if (messageInput) {
    messageInput.focus();
  }
});
closePharmDatabaseButton?.addEventListener("click", requestClosePharmDatabase);
pharmMuteToggle?.addEventListener("click", () => {
  setPharmAutoReadMuted(!pharmAutoReadMuted);
});
pharmReadAllButton?.addEventListener("click", readCurrentPharmAll);
pharmCopyHighlightButton?.addEventListener("click", copyCurrentPharmHighlight);
pharmReadHighlightButton?.addEventListener("click", readCurrentPharmHighlight);
pharmDrugDetail?.addEventListener("click", activatePharmParagraphFromEvent);
pharmDrugDetail?.addEventListener("keydown", handlePharmParagraphKeydown);
pharmDrugDetail?.addEventListener("toggle", handlePharmParagraphDisclosureToggle, true);
pharmDrugDetail?.addEventListener("mouseup", updatePharmHighlightFromSelection);
pharmDrugDetail?.addEventListener("touchend", updatePharmHighlightFromSelection);
pharmDrugDetail?.addEventListener("scroll", () => {
  hideActionMenu();
  capturePharmBrowserDetailScroll();
}, { passive: true });
pharmResultsList?.addEventListener("scroll", hideActionMenu, { passive: true });
document.addEventListener("selectionchange", () => {
  if (pharmDatabaseScreen && !pharmDatabaseScreen.hidden && pharmDatabaseScreen.classList.contains("pharm-detail-open")) {
    updatePharmHighlightFromSelection();
  }
});

let medicalSearchAssistBox = null;
let medicalSearchAssistInput = null;
let medicalSearchAssistRecords = [];
let medicalSearchAssistActiveIndex = -1;
let medicalSearchAssistTimer = null;

function hideMedicalSearchAssist() {
  if (medicalSearchAssistTimer) {
    window.clearTimeout(medicalSearchAssistTimer);
    medicalSearchAssistTimer = null;
  }
  if (medicalSearchAssistBox) {
    medicalSearchAssistBox.hidden = true;
    medicalSearchAssistBox.textContent = "";
  }
  medicalSearchAssistInput?.setAttribute?.("aria-expanded", "false");
  medicalSearchAssistInput = null;
  medicalSearchAssistRecords = [];
  medicalSearchAssistActiveIndex = -1;
}

function positionMedicalSearchAssist(input) {
  if (!medicalSearchAssistBox || medicalSearchAssistBox.hidden || !input?.getBoundingClientRect) return;
  const rect = input.getBoundingClientRect();
  if (!rect.width || !rect.height) return;
  const viewportMargin = 10;
  const inputGap = 6;
  const width = Math.min(Math.max(rect.width, 260), Math.min(560, window.innerWidth - 20));
  const left = Math.min(
    Math.max(viewportMargin, rect.left),
    Math.max(viewportMargin, window.innerWidth - width - viewportMargin)
  );
  const roomBelow = Math.max(0, window.innerHeight - rect.bottom - inputGap - viewportMargin);
  const roomAbove = Math.max(0, rect.top - inputGap - viewportMargin);
  const desiredHeight = Math.min(
    320,
    Math.max(120, medicalSearchAssistBox.scrollHeight || 190),
    Math.max(80, window.innerHeight * 0.46)
  );
  const placeBelow = roomBelow >= Math.min(190, desiredHeight) || roomBelow >= roomAbove;
  const availableHeight = Math.max(48, Math.floor(placeBelow ? roomBelow : roomAbove));
  medicalSearchAssistBox.style.width = `${Math.round(width)}px`;
  medicalSearchAssistBox.style.left = `${Math.round(left)}px`;
  medicalSearchAssistBox.style.maxHeight = `${availableHeight}px`;
  if (placeBelow) {
    medicalSearchAssistBox.dataset.placement = "below";
    medicalSearchAssistBox.style.top = `${Math.round(rect.bottom + inputGap)}px`;
    medicalSearchAssistBox.style.bottom = "auto";
  } else {
    medicalSearchAssistBox.dataset.placement = "above";
    medicalSearchAssistBox.style.top = "auto";
    medicalSearchAssistBox.style.bottom = `${Math.round(window.innerHeight - rect.top + inputGap)}px`;
  }
}

function updateMedicalSearchAssistSelection() {
  if (!medicalSearchAssistBox) return;
  medicalSearchAssistBox.querySelectorAll(".medical-search-assist-option").forEach((option, index) => {
    const active = index === medicalSearchAssistActiveIndex;
    option.classList.toggle("is-active", active);
    option.setAttribute("aria-selected", String(active));
  });
}

function acceptMedicalSearchAssist(index, options = {}) {
  const record = medicalSearchAssistRecords[index];
  const input = medicalSearchAssistInput;
  if (!record || !input) return false;
  input.value = record.label;
  lastAniInteractiveInputAt = Date.now();
  hideMedicalSearchAssist();
  if (input === pharmSearchInput) {
    activePharmLetter = "All";
    clearPharmSearchRenderTimer();
    const requestGeneration = ++pharmSearchRequestGeneration;
    renderPharmResults({ expectedQuery: record.label, requestGeneration });
    if (options.openDetail === true) {
      setPharmDetailExpanded(false, { skipBrowserHistory: true });
      openPharmDetailCandidate({ type: record.type, item: record.item }, {
        highlightQuery: record.label,
        autoRead: true
      });
    }
  } else if (input === messageInput && options.submit === true) {
    const performanceTimingToken = beginAniUiTiming(
      "chat-recommendation-card-painted",
      "chat-suggestion"
    );
    sendUserMessage(record.label, {
      directEncyclopediaTarget: { type: record.type, item: record.item },
      displayText: record.label,
      performanceTimingToken
    });
  } else {
    input.focus?.();
  }
  return true;
}

function renderMedicalSearchAssist(input) {
  if (!input || document.activeElement !== input) {
    hideMedicalSearchAssist();
    return;
  }
  const query = safeText(input.value);
  const normalized = normalizePharmText(query);
  if (normalized.length < 2) {
    hideMedicalSearchAssist();
    return;
  }
  const result = medicalSearchAssistCandidates(query, 6);
  if (!result.candidates.length) {
    hideMedicalSearchAssist();
    return;
  }
  if (!medicalSearchAssistBox) {
    medicalSearchAssistBox = document.createElement("div");
    medicalSearchAssistBox.id = "aniMedicalSearchAssist";
    medicalSearchAssistBox.className = "medical-search-assist";
    medicalSearchAssistBox.setAttribute("role", "listbox");
    medicalSearchAssistBox.setAttribute("aria-label", "Medical encyclopedia suggestions");
    medicalSearchAssistBox.addEventListener("mousedown", (event) => event.preventDefault());
    document.body.append(medicalSearchAssistBox);
  }
  medicalSearchAssistInput = input;
  medicalSearchAssistRecords = result.candidates;
  medicalSearchAssistActiveIndex = -1;
  medicalSearchAssistBox.textContent = "";
  medicalSearchAssistRecords.forEach((record, index) => {
    const option = document.createElement("button");
    option.type = "button";
    option.className = "medical-search-assist-option";
    option.setAttribute("role", "option");
    option.setAttribute("aria-selected", "false");
    option.setAttribute("aria-label", `Use ${record.label}, ${record.kind}`);
    const title = document.createElement("strong");
    title.textContent = record.label;
    const detail = document.createElement("small");
    detail.textContent = record.matchKind === "phonetic-suggestion"
      ? `Sounds like this · ${record.kind}`
      : record.matchKind === "clinical-clue"
        ? `${record.confidenceTier || "Possible"} clinical match · ${record.kind}${record.unmatchedClues?.length ? ` · ${record.unmatchedClues.length} unmatched clue${record.unmatchedClues.length === 1 ? "" : "s"}` : ""}`
        : `${record.kind}${record.mayAutoOpen ? " · reviewed direct match" : ""}`;
    if (record.ambiguousIdentity === true) {
      detail.textContent = `Context-dependent abbreviation - choose this ${record.kind}`;
    }
    option.append(title, detail);
    option.addEventListener("mouseenter", () => {
      medicalSearchAssistActiveIndex = index;
      updateMedicalSearchAssistSelection();
    });
    option.addEventListener("click", () => {
      acceptMedicalSearchAssist(index, {
        openDetail: input === pharmSearchInput,
        submit: input === messageInput
      });
    });
    medicalSearchAssistBox.append(option);
  });
  medicalSearchAssistBox.hidden = false;
  input.setAttribute("aria-controls", medicalSearchAssistBox.id);
  input.setAttribute("aria-expanded", "true");
  input.setAttribute("aria-autocomplete", "list");
  positionMedicalSearchAssist(input);
}

function queueMedicalSearchAssist(input, delay = 55) {
  if (medicalSearchAssistTimer) window.clearTimeout(medicalSearchAssistTimer);
  medicalSearchAssistTimer = window.setTimeout(() => {
    medicalSearchAssistTimer = null;
    renderMedicalSearchAssist(input);
  }, delay);
}

function bindMedicalSearchAssist(input) {
  if (!input || input.dataset.medicalSearchAssistBound === "true") return;
  input.dataset.medicalSearchAssistBound = "true";
  input.addEventListener("focus", () => {
    scheduleMedicalPhoneticIdentityIndex();
    queueMedicalSearchAssist(input, 0);
  });
  input.addEventListener("input", (event) => {
    if (!event.isComposing) queueMedicalSearchAssist(input);
  });
  input.addEventListener("blur", () => window.setTimeout(() => {
    if (medicalSearchAssistInput === input) hideMedicalSearchAssist();
  }, 120));
  input.addEventListener("keydown", (event) => {
    if (!medicalSearchAssistBox || medicalSearchAssistBox.hidden || medicalSearchAssistInput !== input) return;
    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const direction = event.key === "ArrowDown" ? 1 : -1;
      const length = medicalSearchAssistRecords.length;
      medicalSearchAssistActiveIndex = (medicalSearchAssistActiveIndex + direction + length) % length;
      updateMedicalSearchAssistSelection();
      return;
    }
    if (event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation();
      hideMedicalSearchAssist();
      return;
    }
    if (event.key === "Tab" && medicalSearchAssistRecords.length) {
      const selectedIndex = medicalSearchAssistActiveIndex >= 0
        ? medicalSearchAssistActiveIndex
        : medicalSearchAssistRecords[0]?.mayAutoOpen === true
          ? 0
          : -1;
      if (selectedIndex >= 0) {
        event.preventDefault();
        acceptMedicalSearchAssist(selectedIndex);
      }
      return;
    }
    if (event.key === "Enter") {
      const automaticIndex = input === pharmSearchInput
        && medicalSearchAssistRecords[0]?.mayAutoOpen === true
        ? 0
        : -1;
      const selectedIndex = medicalSearchAssistActiveIndex >= 0
        ? medicalSearchAssistActiveIndex
        : automaticIndex;
      if (selectedIndex >= 0) {
        event.preventDefault();
        event.stopImmediatePropagation?.();
        acceptMedicalSearchAssist(selectedIndex, {
          openDetail: input === pharmSearchInput,
          submit: input === messageInput
        });
      }
    }
  });
}

