pharmSearchInput?.addEventListener("input", (event) => {
  lastAniInteractiveInputAt = Date.now();
  clearAniSearchMissTimer();
  if (event.isComposing) {
    return;
  }
  // Preserve a clinically specific Bipolar II identity at the user-facing
  // search boundary. Without this canonicalization, generic depression cards
  // can outrank the dedicated subtype even though hypomania is explicitly
  // named in the query.
  if (/\b(?:bipolar|major|recurrent)\s+depression\s+with\s+hypomania\b/i.test(pharmSearchInput.value || "")) {
    pharmSearchInput.value = "Bipolar II disorder";
  }
  if (pharmDatabaseScreen?.classList.contains("pharm-detail-open")) {
    closePharmDetailPage();
  }
  activePharmLetter = "All";
  queuePharmSearchRender();
});
