window.AniLane2Bridge = Object.freeze({
  async request(pathname, options = {}) {
    const response = await fetchApi(pathname, { credentials: "include", cache: "no-store", ...options });
    const data = await response.json().catch(() => ({}));
    return {
      ok: response.ok,
      status: response.status,
      data,
      requestId: response.headers?.get?.("x-request-id") || data.request_id || ""
    };
  },
  getCurrentUser() {
    return currentUser ? { ...currentUser } : null;
  },
  getActiveExamContext() {
    return activeExamContext ? JSON.parse(JSON.stringify(activeExamContext)) : null;
  },
  getQuestionContext(topic = "", layout = "standard") {
    return getAniQuestionGeneratorContext(String(topic || ""), { formatHint: layout });
  },
  async refreshAccount() {
    await restoreAuthSession();
    return currentUser ? { ...currentUser } : null;
  },
  renderGeneratedQuestion({ layout = "standard", item = {}, prompt = "" } = {}) {
    const normalizedLayout = String(layout || "standard").toLowerCase();
    if (normalizedLayout === "standard") {
      const normalized = normalizeGeneratedStandardQuestion(item, prompt);
      if (!normalized) throw new Error("ANI could not render the validated standard question.");
      addStandardQuestionMessage(formatQuestion(normalized, prompt));
    } else if (normalizedLayout === "bowtie") {
      const normalized = normalizeGeneratedCjeCase(item, prompt);
      if (!normalized) throw new Error("ANI could not render the validated bow-tie question.");
      addCjeCaseMessage(normalized);
    } else if (normalizedLayout === "unfolding") {
      if (!item || !Array.isArray(item.steps) || item.steps.length !== 6) {
        throw new Error("ANI could not render the validated unfolding case.");
      }
      addUnfoldingCaseMessage(item);
    } else {
      const normalized = normalizeGeneratedAdvancedItem({ ...item, type: normalizedLayout }, prompt);
      if (!normalized) throw new Error(`ANI could not render the validated ${normalizedLayout} question.`);
      addAdvancedItemMessage(normalized);
    }
    dispatchAniClientEvent("ani:question-rendered", { layout: normalizedLayout });
    return { rendered: true, layout: normalizedLayout };
  },
  applyAcceptedSyncRecord(record = {}) {
    const entityType = String(record.entity_type || "");
    const payload = record.payload && typeof record.payload === "object" ? record.payload : {};
    if (entityType === "favorite" && record.client_record_id) {
      const key = String(record.client_record_id).slice(0, 160);
      if (payload.favorite === false || record.deleted_at) pharmFavoriteKeys.delete(key);
      else pharmFavoriteKeys.add(key);
      savePharmFavoriteKeys();
      if (activePharmIndexMode === "favorites") {
        renderPharmAlphabet();
        renderPharmResults();
      }
      return true;
    }
    const syncableSettings = new Set([
      "ani-question-difficulty", "ani-voice-style", "ani-dynamic-voice", "ani-speech-rate",
      "ani-keep-mic-ready-v1", "ani-muted", "ani-pharm-nclex-only-v1", "ani-pharm-index-mode-v1"
    ]);
    if (entityType === "setting" && syncableSettings.has(payload.storage_key)) {
      localStorage.setItem(payload.storage_key, String(payload.value ?? "").slice(0, 500));
      return true;
    }
    return false;
  }
});

updateDepth();
updateFocus();
updatePharmVoiceControls();
applyVoiceControls();
setAuthMode("login");
renderAuthState();
if (ANI_ACCOUNT_MEMBERSHIP_ENABLED) restoreAuthSession();
renderChatHistory();
setChatHistoryOpen(false);
renderActiveChat();
startNursingFactTicker();
refreshAniModelStatus();
refreshMedicalUpdatesRuntime();
initializeAniFeedback();
registerServiceWorker();
updateInstallUi();
hideAppSplash();
